(window.GIM_TP=window.GIM_TP||{})["Z.Vayera.0"]={"from":0,"a":[[[", רַבִּי חִיָּיא פָּתַח (שיר השירים ב׳:י״ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים נִרְאוּ בָאָרֶץ, כַּד בְּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא. יָהַב בְּאַרְעָא כָּל חֵילָא דְּאִתְחֲזִי לָהּ. וְכֹלָּא הֲוָה בְאַרְעָא, וְלָא אֲפִיקַת אִיבִּין בְּעָלְמָא עַד דְּאִתְבְּרֵי אָדָם, כֵּיוָן דְּאִתְבְּרֵי אָדָם, כֹּלָּא אִתְחֲזֵי (ד\"א ל\"ג למיפק) בְּעָלְמָא, וְאַרְעָא גַּלִּיאַת אִיבָּהָא וְחֵילָהָא דְּאִתְפָּקְדוּ בָה.","כְּגַוְונָא דָא שָׁמַיִם לָא יָהֲבוּ חֵילִין לְאַרְעָא עַד דְּאָתָא אָדָם. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ה׳) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרְם יִצְמָח כִּי לא הִמְטִיר יְיָ אֱלהִים עַל הָאָרֶץ וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. אִטַּמָּרוּ כָּל אִנּוּן תּוֹלָדִין וְלָא אִתְגַּלּוּן, וּשְׁמַיָא אִתְעַכָּבוּ דְּלָא אַמְטִירוּ עַל אַרְעָא, בְּגִין דְּאָדָם אַיִן, דְּלָא אִשְׁתְּכַח וְלָא אִתְבְּרֵי, וְכֹלָּא אִתְעַכַּב בְּגִינֵיהּ, כֵּיוָן דְּאִתְחֲזֵי אָדָם, מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ וְכָל חַיָילִין דְּאִתְטַמָּרוּ אִתְגַּלִּיאוּ וְאִתְיְהִיבוּ בָהּ.","עֵת הַזָּמִיר הִגִּיעַ, דְּאִתְתַּקַּן תִּקּוּנָא דְּתוּשְׁבְּחָן לְזַמְּרָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא מַה דְּלָא אִשְׁתְּכַח עַד לָא אִתְבְּרֵי אָדָם. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. דְּהָא (ד\"א דא) (ד\"א ל\"ג כל) מִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא (ד\"א ל\"ג דעבד) דְּלָא אִשְׁתְּכַח בְּעָלְמָא עַד דְּאִתְבְּרֵי אָדָם. כֵּיוָן דְּאִשְׁתְּכַח אָדָם כּוֹלָּא אִשְׁתְּכַח."],[[0,"רבי חייא פתח הנצנים וגו':","ר\"ח פתח כתוב הנצנים נראו בארץ עת הזמיר וגו', הנצנים נראו בארץ, פירושו, כאשר ברא הקב\"ה את העולם נתן בהארץ כל הכח הראוי לה, והכל היה בהארץ, אבל לא הוציאה פירות בהעולם עד שנברא האדם. כיון שנברא האדם, הכל נראה בהעולם שהארץ גילתה פירותיה וכחותיה שנפקדו בה. ואז נאמר הנצנים נראו בארץ."],[1,"כגוונא דא, וכו':","כעין זה לא נתנו השמים כחות להארץ, עד שבא אדם. וז\"ש וכל שיח השדה טרם היה בארץ וגו', כי לא המטיר וגו', נסתרו בה כל אלו התולדות ולא נגלו, והשמים נעצרו ולא המטירו על הארץ, משום שאדם אין וגו', שלא נמצא ועוד לא נברא, והכל נעכב מלהגלות בסבתו. \u0003כיון דאתחזי וכו':\u0004 כיון שנראה אדם מיד הנצנים נראו בארץ, וכל הכחות שנסתרו נתגלו וניתנו בה."],[2,"עת הזמיר הגיע, וכו':","פירושו, שנתתקן תקון של שירות ותשבחות, לזמר לפני הקב\"ה, מה שלא היה מטרם שנברא האדם. וקול התור נשמע בארצנו, זהו הדיבור של הקב\"ה, שלא היה נמצא בעולם מטרם שנברא האדם. כיון שנמצא האדם נמצא הכל."]],[[0,"","רַבִּי חִיָּיא פָּתַח, (שיר ב) הַנִּצָּנִים נִרְאוּ בָאָרֶץ עֵת הַזָּמִיר הִגִּיעַ וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ. הַנִּצָּנִים נִרְאוּ בָאָרֶץ, כְּשֶׁבָּרָא הַקָּבָּ\"ה אֶת הָעוֹלָם, נָתַן בָּאָרֶץ כָּל הַכֹּחַ שֶׁרָאוּי לָהּ, וְהַכֹּל הָיָה בָּאָרֶץ, וְלֹא הוֹצִיאָה פֵרוֹת בָּעוֹלָם עַד שֶׁנִּבְרָא אָדָם. כֵּיוָן שֶׁנִּבְרָא אָדָם, הַכֹּל רָאוּי (ד\"א לצאת) בָּעוֹלָם, וְהָאָרֶץ גִּלְּתָה אֶת פֵּרוֹתֶיהָה וְכֹחָהּ שֶׁנִּפְקְדוּ בָהּ."],[1,"","כְּמוֹ זֶה הַשָּׁמַיִם לֹא נָתְנוּ כֹחוֹת לָאָרֶץ עַד שֶׁבָּא אָדָם. זֶהוּ שֶׁכָּתוּב (בראשית ב) וְכֹל שִׂיחַ הַשָּׂדֶה טֶרֶם יִהְיֶה בָאָרֶץ וְכָל עֵשֶׂב הַשָּׂדֶה טֶרֶם יִצְמָח כִּי לֹא הִמְטִיר ה' אֱלֹהִים עַל הָאָרֶץ וְאָדָם אַיִן לַעֲבֹד אֶת הָאֲדָמָה. נִסְתַּתְּרוּ בָהּ כָּל אוֹתָם תּוֹלָדוֹת וְלֹא הִתְגַּלּוּ, וְהַשָּׁמַיִם הִתְעַכְּבוּ, שֶׁלֹּא הִמְטִירוּ עַל הָאָרֶץ מִשּׁוּם שֶׁאָדָם אַיִן, שֶׁלֹּא נִמְצָא וְלֹא נִבְרָא, וְהַכֹּל הִתְעַכֵּב בִּגְלָלוֹ. כֵּיוָן שֶׁנִּרְאָה אָדָם, מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ, וְכָל הַכֹּחוֹת שֶׁנִּסְתְּרוּ, הִתְגַּלּוּ וְנִתְּנוּ בָהּ."],[2,"","עֵת הַזָּמִיר הִגִּיעַ, שֶׁהִתְתַּקֵּן תִּקּוּן הַתִּשְׁבָּחוֹת לְזַמֵּר לִפְנֵי הַקָּבָּ\"ה מַה שֶּׁלֹּא נִמְצָא עַד שֶׁלֹּא נִבְרָא אָדָם. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ, שֶׁהֲרֵי (זה) (כל) דָבָר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא (ד\"א שעשה) הַקָּבָּ\"ה שֶׁלֹּא נִמְצָא בָּעוֹלָם עַד שֶׁנִּבְרָא אָדָם. כֵּיוָן שֶׁנִּמְצָא אָדָם, הַכֹּל נִמְצָא."]]],[["בָּתַר דְּחָטָא, כּוֹלָּא אִסְתַּלַּק מֵעָלְמָא וְאִתְלַטְיָא אַרְעָא. הֲדָא הוּא דִכְתִיב, (בראשית ג׳:י״ז) אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ וְגו'. וּכְתִיב כִּי תַעֲבֹד אֶת הָאֲדָמָה לא תֹסֵף תֵּת כֹּחָהּ לָךְ וְגו'. וּכְתִיב וְקוֹץ וְדַרְדַּר תַּצְמִיחַ לָךְ.","אֲתָא נֹחַ וְתִקֵּן קַרְדּוּמִין וּפְצִירֵי בְּעָלְמָא. וּלְבָתַר וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלה. אָתוּ בְּנֵי עָלְמָא וְחָבוּ קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא. וְאִסְתַּלָּקוּ חֵילִין דְּאַרְעָא (דעלמא) כְּמִלְּקַדְּמִין, וְהֲווּ קָיְימֵי עַד דְּאָתָא אַבְרָהָם.","כֵּיוָן דְּאָתָא אַבְרָהָם (לעלמא) מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרְץ, אִתְתַּקָּנוּ וְאִתְגָּלוּ כָּל חֵילִין בְּאַרְעָא. עֵת הַזָּמִיר הִגִּיעַ. בְּשַׁעֲתָא דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְגְּזָר, כֵּיוָן דְּמָטָא הַהוּא זִמְנָא דִּבְרִית אִשְׁתְּכַח בֵּיהּ בְּאַבְרָהָם וְאִתְגְּזַר. כְּדֵין אִתְקְיַּים בֵּיהּ כָּל הַאי קְרָא, וְאִתְקְיַּים עָלְמָא, וּמִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה בְּאִתְגַּלְּיָיא בֵּיהּ הֲדָא הוּא דִכְתִיב וַיֵּרָא אֵלָיו יְיָ.","רַבִּי אֶלְעָזָר פָּתַח הַאי קְרָא (בשעתא) בָּתַר דְּאִתְגְּזַר אַבְרָהָם. דְּעַד לָא אִתְגְּזַר לָא הֲוָה מַלִּיל עִמֵּיהּ אֶלָּא מִגּוֹ דַּרְגָּא תַּתָּאָה, וְדַרְגִּין עִלָּאִין לָא הֲווּ קָיְימֵי עַל הַהִיא דַּרְגָּא. כֵּיוָן דְּאִתְגְּזַר מִיָּד הַנִּצָנִים נִרְאוּ בָאָרֶץ אִלֵּין דַּרְגִּין תַּתָּאִין דְּאֲפִיקַת וְאַתְקִינַת הַאי דַּרְגָּא תַּתָּאָה.","עֵת הַזָּמִיר הִגִּיעַ אִלֵּין עַנְפּוֹי דְּעָרְלָה. וְקוֹל הַתּוֹר נִשְׁמַע בְאַרְצֵנוּ. דָּא קוֹל דְּנָפִיק מִגּוֹ הַהוּא פְּנִימָאָה דְּכֹלָּא וְהַהוּא קוֹל נִשְׁמַע וְדָא קוֹל דְּגָזַר מִלָּה לְמַלָּלָא וְעָבִיד לָהּ שְׁלִימוּ."],[[0,"בתר דחטא וכו':","אחר שחטא, נסתלק הכל מהעולם ונתקללה הארץ, וז\"ש ארורה האדמה בעבורך וגו'. וכתוב כי תעבוד את האדמה וגו'. וכתוב, וקוץ ודרדר תצמיח לך."],[1,"אתא נח וכו':","בא נח להעולם, ותקן קרדומות ופצירות בהעולם, כלומר שתקן כלים לעבודת האדמה, וע\"כ כתוב עליו זה ינחמנו ממעשנו ומעצבון ידינו וגו'. כי יתן לנו כלים, ונפטור מעצבון ידינו, שהיה לנו עד עתה. ואח\"כ וישת מן היין וישכר ויתגל בתוך אהלה. ואח\"כ באו בני העולם וחטאו לפני הקב\"ה. ונסתלקו כחות הארץ כבתחילה. כלומר שכל התקונים של נח נתבטלו, והיה כן עד שבא אברהם."],[2,"כיון דאתא אברהם וכו':","כיון שבא אברהם מיד הנצנים נראו בארץ, שפירושו, נתתקנו ונתגלו כל כחות הארץ. עת הזמיר הגיע, היינו בשעה שאמר לו הקב\"ה שימול עצמו זמיר פירושו כריתה, דהיינו כריתה הערלה. כיון שהגיע זמן ההוא שהברית נמצא באברהם, דהיינו שנמול, אז נתקיים בו כל הכתוב הזה, הנצנים נראו וכו', ונתקיים העולם, והדיבור של הקב\"ה היה בהתגלות אליו, וז\"ש וירא אליו ה' אחר שנמול."],[3,"רבי אלעזר פתח וכו':","ר\"א פתח את הביאור של כל כתוב הזה, לאחר שנמול אברהם, כי מטרם שנמול, לא היה הקב\"ה מדבר עמו, אלא מתוך מדרגה תחתונה, הנקראת מחזה. דהיינו הנוקבא, בהיותה עוד בהארת השמאל. כמ\"ש אחר הדברים וגו' דבר ה' אל אברם במחזה וגו'. ומדרגות העליונות לא היו מתחברות במדרגה ההיא. דהיינו המדרגות של ז\"א לא נתחברו בהנוקבא. כיון שנמול, מיד הנצנים נראו בארץ, אלו הן מדרגות התחתונות שהמדרגה התחתונה הנקראת מחזה הוציאה ותקנה אותן. כדי שיתחברו בה המדרגות העליונות כולן."],[3,"","ביאור הדברים, כמו ב' הקוין ימין ושמאל שבישסו\"ת, אינם מזדווגים ונכללים זה בזה, אלא ע\"י קומת החסדים היוצאת על מ\"ן דז\"א, המכריע ביניהם וכוללם זה בזה. כן זו\"ן, לאחר שעלו לישסו\"ת לקבל מהם מוחין, נעשה שם ז\"א לבחינת קו ימין, והנוקבא לבחינת קו שמאל. והם נפרדים זה מזה, כדרך ב' הקוין ימין ושמאל, עד שעולה אליהם מ\"ן ע\"י נשמות הצדיקים, ויוצאת קומת חסדים על מ\"ן הללו דצדיקים, ומזווג את ז\"א ונוקבא. כמו שהארכנו בזה לעיל (בראשית א' דף קנ\"ב אות קע\"א ד\"ה ביאור עש\"ה) ובעת שזו\"ן נפרדים זה מזה, נקראת הנוקבא בשם \u0003מחזה,\u0004 כי תרגומו של ראיה הוא מחזה, ומלה של תרגום המובא במקרא, רומז על מוחין דאחורים, כנודע. ואלו המוחין דקו שמאל שבהנוקבא, מטרם הזווג עם ז\"א, הם מוחין דאחורים."],[3,"","וזה אמרו, \u0003דעד לא אתגזר,\u0004 דהיינו טרם שאברהם העלה מ\"ן לזו\"ן במצות המילה, \u0003לא הוה מליל עמיה אלא מגו דרגא תתאה\u0004 דהיינו הנוקבא, ודרגין עלאין שהם מדרגות ז\"א, \u0003לא הוו קיימי על ההיא דרגא,\u0004 כלומר שז\"א לא היה בזווג עם הנוקבא, אלא שהיו נפרדים זה מזה, להיות ז\"א בבחינת קו ימין, והנוקבא בקו שמאל, כנ\"ל. וקוי ימין ושמאל הם במחלוקת זה עם זה. \u0003כיון דאתגזר\u0004 דהיינו שהעלה מ\"ן ע\"י מצות מילה, \u0003מיד הנצנים נראו בארץ,\u0004 דהיינו בחינות המסך שעליהם נעשה זווג דהכאה, המוציא קומת החסדים בבחינת קו אמצעי, המכריע ומיחד ב' הקוין ימין ושמאל זה בזה. ובחינות המסך הללו מכונות \u0003הנצנים\u0004 שהם \u0003נראו בארץ\u0004 שהיא הנוקבא, בכח המ\"ן מצות המילה. וזהו שמפרש \u0003אלין דרגין תתאין,\u0004 דהיינו כחות המסך, \u0003דאפיקת ואתקינת האי דרגא תתאה,\u0004 שכחות הללו יצאו ונגלו בהנוקבא, והיא תיקנה את עצמה על ידיהם, בסוד מסך מתוקן לזווג. להוציא קומת החסדים המזווג אותה עם הזו\"ן (ועי' לעיל פ' לך דף צ\"ד אות רע\"ג)."],[4,"עת הזמיר הגיע וכו':","היינו עת כריתת ענפים הרעים הגיע, שהם אלו הענפים של \u0003ערלה\u0004 כי קליפה זו שלטה מטרם שנמול. והיתה בסו\"ה ונרגן מפריד אלוף. \u0003וקול התור נשמע בארצנו,\u0004 זהו קול, היוצא מתוך אותה הפנימית שבכולם קול פירושו ז\"א. הפנימית שבכולם היינו אמא, שז\"א נאצל ויוצא הימנה. ואותו הקול ז\"א נשמע בארצנו, שהיא הנוקבא. כלומר, שז\"א נזדווג עם הנוקבא, על ידי המ\"ן ממצות המילה כנ\"ל בסמוך. וזהו קול החותך המלה לדיבור, כלומר שיש בו חיתוך הדיבור, ועושה לה את השלימות. פירוש, ז\"א נקרא \u0003קול,\u0004 והנוקבא נקראת \u0003דיבור,\u0004 ואומר, שז\"א מתקן את הנוקבא ועושה אותה בכל השלימות."]],[[0,"","אַחַר שֶׁחָטָא, הַכֹּל הִסְתַּלֵּק מֵהָעוֹלָם וְהִתְקַלְּלָה הָאָרֶץ. זֶהוּ שֶׁכָּתוּב (בראשית ג) אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךְ וְגוֹ', וְכתוּב כִּי תַעֲבֹד אֶת הָאֲדָמָה לֹא תֹסֵף תֵּת כֹּחָהּ לָךְ וְגוֹ', וְכָתוּב וְקוֹץ וְדַרְדַּר תַּצְמִיחַ לָךְ."],[1,"","בָּא נֹחַ וְתִקֵּן קַרְדֻּמִּים וּפְצִירוֹת בָּעוֹלָם. אַחַר כָּךְ, וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה. בָּאוּ בְּנֵי הָעוֹלָם וְחָטְאוּ לִפְנֵי הַקָּבָּ\"ה, וְהִסְתַּלְּקוּ צִבְאוֹת הָאָרֶץ (של העולם) כְּמִקֹּדֶם, וְהָיוּ עוֹמְדִים עַד שֶׁבָּא אַבְרָהָם."],[2,"","כֵּיוָן שֶׁבָּא אַבְרָהָם (לעולם), מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ, הִתְתַּקְּנוּ וְהִתְגַּלּוּ כָּל הַצְּבָאוֹת בָּאָרֶץ. עֵת הַזָּמִיר הִגִּיעַ, בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּבָּ\"ה לָמוּל. כֵּיוָן שֶׁהִגִּיעַ אוֹתוֹ הַזְּמַן שֶׁבְּרִית נִמְצְאָה בּוֹ בְּאַבְרָהָם וְנִמּוֹל, אָז הִתְקַיֵּם בּוֹ כָּל הַפָּסוּק הַזֶּה, וְהִתְקַיֵּם הָעוֹלָם, וּדְבַר הַקָּבָּ\"ה הָיָה בְּהִתְגַּלּוּת בּוֹ. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה'."],[3,"","רַבִּי אֶלְעָזָר פָּתַח הַפָּסוּק הַזֶּה (בשעה) אַחַר שֶׁנִּמּוֹל אַבְרָהָם. שֶׁעַד שֶׁלֹּא נִמּוֹל, לֹא דִבֵּר עִמּוֹ אֶלָּא מִתּוֹךְ דַּרְגָּה תַחְתּוֹנָה, וְהַדְּרָגוֹת הָעֶלְיוֹנוֹת לֹא הָיוּ קַיָּמוֹת עַל אוֹתָהּ הַדַּרְגָּה. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד הַנִּצָּנִים נִרְאוּ בָאָרֶץ. אֵלּוּ הַדְּרָגוֹת הַתַּחְתּוֹנוֹת שֶׁהוֹצִיאָה וְהִתְקִינָה הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ."],[4,"","עֵת הַזָּמִיר הִגִּיעַ - אֵלּוּ עַנְפֵי הָעָרְלָה. וְקוֹל הַתּוֹר נִשְׁמַע בְּאַרְצֵנוּ - זֶהוּ קוֹל שֶׁיּוֹצֵא מִתּוֹךְ אוֹתוֹ פְּנִימִי שֶׁל הַכֹּל, וְאוֹתוֹ קוֹל נִשְׁמַע, וְזֶה קוֹל שֶׁגּוֹזֵר דָּבָר לְדַבֵּר וְעוֹשֶׂה לָהּ שְׁלֵמוּת."]]],[["תָּא חֲזֵי, דְּעַד לָא אִתְגְּזַר אַבְרָהָם לָא הֲוָה עֲלֵיהּ אֶלָּא הַאי דַרְגָּא (כח ב) כִּדְאֲמָרָן, כֵּיוָן (לבתר) דְּאִתְגְּזַר מַה כְּתִיב וַיֵּרָא אֵלָיו יְיָ. לְמַאן, דְּהָא לָא כְּתִיב וַיֵּרָא יְיָ אֶל אַבְרָם. דְּאִי לְאַבְרָם מַאי שְׁבָחָא הָכָא יַתִּיר מִבְּקַדְמִיתָא עַד לָא אִתְגְּזַר דִּכְתִיב וַיֵּרָא יְיָ אֶל אַבְרָם.","אֶלָא רָזָא סְתִימָא אִיהוּ, וַיֵּרָא אֵלָיו יְיָ. לְהַהוּא דַרְגָא דְּמַלִּיל עִמֵּיהּ, מַה דְּלָא הֲוָה מִקַּדְמַת דְּנָא עַד דְּלָא אִתְגְּזַר. דְּהַשְׁתָּא אִתְגְּלִי קוֹל וְאִתְחַבַּר בְּדִבּוּר כַּד מַלִּיל עִמֵּיהּ.","וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא וְלא גָּלֵי מַאן. אֶלָּא הָכָא גָּלֵי חָכְמְתָא דְּכֻלְהוּ דַּרְגִּין שָׁרוּ עַל הַאי דַּרְגָּא תַּתָּאָה בָּתַר דְּאִתְגְּזַר אַבְרָהָם. תָּא חֲזֵי, וַיֵּרָא אֵלָיו יְיָ. דָּא הוּא רָזָא דְּקוֹל דְּאִשְׁתְּמַע דְּאִתְחַבַּר בְּדִבּוּר וְאִתְגְּלִי בֵּיהּ.","וְהוּ\"א יוֹשֵׁב פֶּתַח הָאֹהֶל, דָּא עָלְמָא עִלָּאָה דְּקָאִים לְאַנְהָרָא עֲלֵיהּ. כְּחוֹם הַיּוֹם. דְּהָא אִתְנְהִיר יְמִינָא דַּרְגָּא דְאַבְרָהָם אִתְדָּבַּק בֵּיהּ. דָּבָר אַחֵר כְּחוֹם הַיּוֹם בְּשַׁעֲתָא דְּאִתְקְרִיב דַּרְגָּא לְדַרְגָּא בְּתִיאוּבְתָּא דְּדָא לָקֳבֵל דָּא,"],[[0,"ת\"ח דעד לא וכו':","בוא וראה, כל עוד שלא נמול אברהם, לא היה עליו אלא אותה מדרגה כמו שאמרנו, דהיינו מדרגת הנוקבא בעת שנקראת מחזה. מכיון שנמול מה כתוב, \u0003וירא אליו ה',\u0004 ולא אמר למי, כי לא כתוב, וירא ה' אל אברם. ומשיב, אם היה כתוב לאברם, איזה שבח יש כאן יותר מבתחילה, מטרם שנמול, שגם אז כתוב וירא ה' אל אברם (בראשית י\"ב)."],[1,"אלא רזא וכו':","אלא סוד סתום הוא. \u0003וירא אליו ה'\u0004 פירושו, שנראה לאותה המדרגה שדברה עמו. כלומר, ז\"א שהוא הוי\"ה, נראה אליו, היינו להנוקבא. מה שלא היה מקודם לכן מטרם שנמול, שאז היתה נפרדת מז\"א. ועתה נגלה הקול הוא ז\"א, ונתחבר בדבור היא הנוקבא, בעת שדבר עם אברהם. דהיינו שאברהם היה מקבל עתה מזווג זו\"ן והיה מרכבה לשניהם. וע\"כ כתוב כאן וירא אליו הוי\"ה הרומז על זווג זו\"ן יחד."],[2,"והוא יושב פתח האהל וכו':","אומר \u0003והוא\u0004 ואינו מגלה מי הוא היושב. ומשיב, אלא הכתוב מגלה כאן חכמה, לרמז שכל המדרגות שרו על אותה מדרגה התחתונה אחר שנמול אברהם. ושיעור הכתוב, \u0003והוא,\u0004 דהיינו הנוקבא, \u0003יושב פתח האהל,\u0004 נעשית לפתח לכל המדרגות. \u0003האהל,\u0004 הוא מלשון בהלו נרו (איוב כ\"ט) בוא וראה, \u0003וירא אליו ה',\u0004 זה הוא סוד, \u0003שהקול\u0004 היינו ז\"א, נשמע ונתחבר בדבור, היינו מלכות, ונגלה בו."],[3,"והוא יושב פתח האהל וכו': והוא.","זה עולם העליון, דהיינו אמא, העומד להאיר עליו, היינו על הנוקבא, הנקראת \u0003פתח האהל\u0004 שנעשית פתח להאורות. \u0003כחום היום,\u0004 היינו שהאיר הימין, שהוא חסד, מדרגה שאברהם נתחבר בה. פירוש אחר. \u0003כחום היום,\u0004 היינו בשעה שנתקרבה מדרגה למדרגה בתשוקה מזו אל זו. דהיינו מז\"א אל הנוקבא, אז נאמר עליהם כחום היום."]],[[0,"","בֹּא רְאֵה שֶׁעַד שֶׁלֹּא נִמּוֹל אַבְרָהָם לֹא הָיְתָה עָלָיו אֶלָּא הַדַּרְגָּה הַזּוֹ כְּפִי שֶׁאָמַרְנוּ. כֵּיוָן (אחר) שֶׁנִּמּוֹל מַה כָּתוּב? וַיֵּרָא אֵלָיו ה'. לְמִי? שֶׁהֲרֵי לֹא כָתוּב וַיֵּרָא ה' אֶל אַבְרָם? שֶׁאִם לְאַבְרָם אָז מָה הַשֶּׁבַח כָּאן יוֹתֵר מִבַּהַתְחָלָה עַד שֶׁלֹּא נִמּוֹל שֶׁכָּתוּב וַיֵּרָא ה' אֶל אַבְרָם?"],[1,"","אֶלָּא סוֹד נִסְתָּר הוּא. וַיֵּרָא אֵלָיו ה' - לְאוֹתָהּ דַּרְגָּה שֶׁדִּבְּרָה עִמּוֹ, מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָזֶה עַד שֶׁלֹּא נִמּוֹל. שֶׁכָּעֵת הִתְגַּלָּה הַקּוֹל וְהִתְחַבֵּר בַּדִּבּוּר כְּשֶׁדִּבֵּר עִמּוֹ."],[2,"","וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא - וְלֹא גִלָּה מִי. אֶלָּא כָּאן גִּלָּה אֶת הַחָכְמָה שֶׁכָּל הַדְּרָגוֹת שְׁרוּיוֹת עַל הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ אַחַר שֶׁנִּמּוֹל אַבְרָהָם. בֹּא רְאֵה, וַיֵּרָא אֵלָיו ה' - זֶהוּ הַסּוֹד שֶׁקּוֹל שֶׁנִּשְׁמַע שֶׁהִתְחַבֵּר בַּדִּבּוּר וּמִתְגַּלֶּה בּוֹ."],[3,"","וְהוּ\"א יֹשֵׁב פֶּתַח הָאֹהֶל - זֶהוּ הָעוֹלָם הָעֶלְיוֹן שֶׁעָמַד לְהָאִיר עָלָיו. כְּחֹם הַיּוֹם, שֶׁהֲרֵי הוּאַר הַיָּמִין, הַדַּרְגָּה שֶׁאַבְרָהָם נִדְבַּק בּוֹ. דָּבָר אַחֵר כְּחֹם הַיּוֹם - בְּשָׁעָה שֶׁמִּתְקָרֶבֶת דַּרְגָּה לְדַרְגָּה בִּתְשׁוּקָה שֶׁל זֶה כְּנֶגֶד זֶה."]]],[["וַיֵּרָא אֵלָיו. אָמַר רַבִּי אַבָּא עַד לָא אִתְגְּזַר אַבְרָהָם הֲוָה אָטִים. כֵּיוָן דְּאִתְגְּזַר אִתְגְּלִי כֹלָּא וְשָׁרָא עֲלֵיהּ שְׁכִינְתָּא בִּשְׁלִימוּ כְּדְקָא יְאוּת. תָּא חֲזֵי וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא. דָּא עָלְמָא עִלָּאָה דְּשָׁרֵי עַל הַאי עָלְמָא תַּתָּאָה. אֵימָתַי כְּחוֹם הַיּוֹם בְּזִמְנָא דְּתִיאוּבְתָּא דְּחַד צַדִּיק לְמִשְׁרֵי בֵּיהּ.","מִיָּד וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. מַאן אִנּוּן שְׁלשָׁה אֲנָשִׁים. אִלֵּין אַבְרָהָם יִצְחָק וְיַעֲקֹב דְּקָיְימֵי עֲלֵיהּ דְּהַאי דַרְגָּא, וּמִנַּיְיהוּ יָנִיק (יסודא דעלמא) וְאִתְּזָן."],[[0,"וירא אליו וכו':","אמר ר' אבא, עד שלא נמול אברהם, היה סתום כלומר, שלא היה יכול לקבל אורות העליונים. כיון שנמול נגלה הכל כלומר, שכל האורות נגלו אליו. כי נפתח מסתומתו, והשכינה שרתה עליו בשלימות כראוי. בוא וראה, כתוב, והוא יושב פתח האהל. \u0003והוא,\u0004 זהו עולם העליון בינה, השורה על עולם התחתון שהיא הנוקבא. ושואל אימתי שורה הבינה על הנוקבא. ומשיב, שזהו שמסיים, \u0003כחום היום,\u0004 בשעה שתשוקתו של צדיק אחד, שהוא יסוד דז\"א, הוא לשרות בו, בעולם התחתון, שהוא הנוקבא. כלומר. בשעה שיש זווג זו\"ן, אז המוחין של הבינה שורים בהנוקבא."],[1,"מיד וישא עיניו וגו':","מיד, אחר שנעשה זווג זו\"ן, נאמר, וישא עיניו וירא והנה שלשה אנשים נצבים עליו. ושואל, מי הם שלשה אנשים האלו. ואומר, שהם אברהם יצחק ויעקב, דהיינו חסד גבורה תפארת דז\"א, הנקראים אברהם יצחק ויעקב. שראה אותם עומדים עליה, על אותה המדרגה, שהיא הנוקבא, שמהם היא יונקת וניזונת."]],[[0,"","וַיֵּרָא אֵלָיו. אָמַר רַבִּי אַבָּא, עַד שֶׁלֹּא נִמּוֹל אַבְרָהָם, הָיָה אָטוּם. כֵּיוָן שֶׁנִּמּוֹל, הַכֹּל הִתְגַּלָּה, וְשָׁרְתָה עָלָיו שְׁכִינָה בִּשְׁלֵמוּת כָּרָאוּי. בֹּא רְאֵה, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְהוּא - זֶהוּ הָעוֹלָם הָעֶלְיוֹן שֶׁשּׁוֹרֶה עַל עוֹלָם הַתַּחְתּוֹן הַזֶּה. אֵימָתַי? כְּחֹם הַיּוֹם, בִּזְמַן שֶׁתְּשׁוּקָתוֹ שֶׁל צַדִּיק אֶחָד לִשְׁרוֹת בּוֹ."],[1,"","מִיָּד - וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. מִי הֵם שְׁלֹשָׁה אֲנָשִׁים? אֵלּוּ אַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁעוֹמְדִים עַל הַדַּרְגָּה הַזּוֹ, וּמֵהֶם הִיא יוֹנֶקֶת (יסוד העולם) וְנִזּוֹנֵית."]]],[["כְּדֵין וַיַּרְא וַיָּרָץ לִקְרָאתָם. דְּתִיאוּבְתָּא דְּהַאי דַרְגָּא תַּתָּאָה לְאִתְחַבְּרָא בְּהוּ וְחֶדְוָותָא דִּילָהּ לְאִתְמַשְּׁכָא אֲבַּתְרַיְיהוּ. וַיִשְׁתָּחוּ אַרְצָה, לְאִתְתַּקְּנָא כֻּרְסְיָיא לְגַבַּיְיהוּ.","תָּא חֲזֵי, עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְדָוִד מַלְכָּא חַד סַמְכָא מִכֻּרְסְיָיא עִלָּאָה כַּאֲבָהָן. וְאַף עַל גַּב דְּאִיהוּ כֻּרְסְיָיא לְגַבַּיְיהוּ. אֲבָל בְּזִמְנָא דְּאִתְחַבַּר בְּהוּ אִיהוּ חַד סַמְכָא לְאִתְתַּקְּנָא בְּכֻּרְסְיָיא עִלָּאָה. וּבְגִין כָּךְ נָטַל מַלְכוּתָא (עט ב) בְּחֶבְרוֹן דָּוִד מַלְכָּא שְׁבַע שְׁנִין לְאִתְחַבְּרָא בְּהוּ. וְהָא אִתְּמָר.","\u0003תּוֹסֶפְתָּא\u0004 ויֵּרָא אֵלָיו יְיָ בְּאֵלוֹנֵי מַמְרֵא. אַמַּאי בְּאֵלוֹנֵי מַמְרֵא, וְלָא בְּאֲתַּר אָחֳרָא. אֶלָּא בְּגִין דְּיָהִיב לֵיהּ עֵיטָא עַל גְּזִירוּ דִּקְיָימָא דִילֵיהּ. בְּשַׁעֲתָּא דְּאָמַר קוּדְשָׁא בְּרִיךָ הוּא לְאַבְרָהָם לְמִגְזַר אֲזַל אַבְרָהָם לִמָּלֵךָ עִם חַבְרוֹי, אָמַר לֵיהּ עָנֵר (אולי ר\"ל כבר עברו עליך צ' שנה ואולם גם יותר שהם צ\"ט כמ\"ש בתוה\"ק. ולא חשב הפרט) אַנְתְּ בֶּן תִּשְׁעִין שְׁנִין ואַתְּ מֵעִיק גַּרְמָךָ.","אָמַר לֵיהּ מַמְרֵא דְּכַרְתְּ יוֹמָא דְּרָמוּ לָךָ כַּשְׂדָאֵי בְּאַתּוּן דְּנוּרָא. והַהוּא כַּפְּנָא דְּעֲבַר עַל עָלְמָא דִּכְתִּיב, (בראשית י״ב:י׳) ויְהִי רָעָב בָּאָרֶץ וַיֵּרֶד אַבְרָם מִצְּרָיְמָה. ואִנּוּן מַלְכִין דִּרְדָּפּוּ בַּתְּרֵיהוֹן וּמָחִיתּ יַתְּהוֹן וקוּדְשָׁא בְּרִיךָ הוּא שֵׁזְבִינָךָ מִכֹּלָּא וְלָא יָכִיל בַּר נָשׁ לְמֶעְבַּד לָךָ בִּישׁ. קוּם עֲבִיד פִּקּוּדָא דְמָרָךָ. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךָ הוּא, מַמְרֵא אַנְתְּ יְהַבְתְּ לֵיהּ עֵיטָא לְמִגְזַר, חַיֶּיךָ לֵיתּ אֲנָא מִתְּגַּלֵּי עֲלֵיהּ אֶלָּא בְּפַּלְטְרִין דִּילָךָ, הֲדָא הוּא דִכְתִּיב בְּאֵלוֹנֵי מַמְרֵא (עד כאן התוספתא):","\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 רַבָּנָן פָּתְחֵי בְּהַאי קְרָא (שיר השירים א׳:ג׳) לְרֵיחַ (לט ב) שְׁמָנֶיךָ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךָ וגו'. תָּנוּ רַבָּנָן הַאי נִשְׁמָתָא דְּבַר אֵינָשׁ בְּשַׁעֲתָא דְּסָלְקָא מֵאַרְעָא לִרְקִיעָא וְקָיְימָא בְּהַהוּא זִיהֲרָא עִלָּאָה דְּאֲמָרָן, קוּדְשָׁא בְּרִיךְ הוּא מְבַקֵּר לָהּ.","תָּא שְׁמַע אָמַר רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי כָּל נִשְׁמָתָא דְּצַּדִּיקַיָּיא כֵּיוָן דְּקָיְימָא בְּאֲתַר שְׁכִינְתָּא יְקָרָא דְּחָזְיָא לְמֵיתַב, קוּדְשָׁא בְּרִיךְ הוּא קָרֵי לַאֲבָהָתָא, וְאָמַר לוֹן זִילוּ וּבַקְּרוּ לִפְלַנְיָא צַּדִּיקָא דְּאָתָא, וְאַקְדִּימוּ לֵיהּ שְׁלָמָא מִן שְׁמִי. וְאִנּוּן אָמְרִין, מָארֵי עָלְמָא, לָא אִתְחֲזֵי לְאַבָּא לְמֵיזַל לְמֶחֱמֵי לִבְרָא, בְּרָא אִתְחֲזֵי לְמֶיחֱמֵי וּלְמֶחֱזֵי וּלְמִתְבַּע לְאֲבוּי.","והוּא קָרֵי לְיַעֲקֹב וְאָמַר לֵיהּ אַנְתְּ דְּהֲוָה לָךְ צַּעֲרָא דִּבְנִין זִיל וְקַבִּיל (אולפניה) פְּנִי דִּפְלַנְיָא צַּדִּיקָא דְּאָתָא הָכָא, ואֲנָא אֵיזִיל עִמָּךְ. הֲדָא הוּא דִכְתִיב, (תהילים כ״ד:ו׳) מְבַקְּשֵׁי פָנְיךָ יַעֲקֹב סֶלָּה. מְבַקֵּשׁ לֹא נֶאֱמַר אֶלָּא מְבַקְּשֵׁי. אָמַר רַבִּי חִיָּיא מֵרֵישֵׁיהּ דִּקְרָא מַשְׁמַע דִּכְתִיב זֶה דּוֹר דּוֹרְשָׁיו וְגו'.","אָמַר רַבִּי יַעֲקֹב אָמַר רַבִּי חִיָּיא (נ\"א עקיבא) יַעֲקֹב אָבִינוּ הוּא כִּסֵּא הַכָּבוֹד, וְכֵן תָּאנָא דְּבֵי אֵלִיָּהוּ יַעֲקֹב אָבִינוּ הוּא כִּסֵּא בִּפְנֵי עַצְּמוֹ, דִּכְתִיב, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב, בְּרִית כָּרַת קוּדְשָׁא בְּרִיךְ הוּא לְיַעֲקֹב לְבַדּוֹ יוֹתֵר מִכָּל אֲבוֹתָיו דְּעֲבִיד לֵיהּ כִּסֵּא הַכָּבוֹד. בַּר מִן קַדְמָאָה:","רַבִּי אֱלִיעֶזֶר הֲוָה יָתִיב וְהֲוָה לָעֵי בְּאוֹרַיְיתָא. אֲתָא לְגַבֵּיהּ רַבִּי עֲקִיבָא אָמַר לֵיהּ בְּמַאי קָא עָסִיק מַר. אָמַר לֵיהּ בְּהַאי קְרָא דִּכְתִיב, (שמואל א ב׳:ח׳) וכִסֵּא כָבוֹד יַנְחִילֵם. מַהוּ כִּסֵּא כָבוֹד יַנְחִילֵם. זֶה יַעֲקֹב אָבִינוּ דְּעֲבִיד לֵיהּ כָּרְסֵי יְקָר בִּלְחוֹדוֹי לְקַבָּלָא אוּלְפַן נִשְׁמָתָא דְּצַּדִּיקַיָא.","וְקוּדְשָׁא בְּרִיךְ הוּא אָזִיל עִמֵּיהּ בְּכָל רֵישׁ יַרְחָא וְיַרְחָא. וכַד חָמֵי נִשְׁמָתָא יְקַר אַסְפַּקְלַרְיָאה שְׁכִינְתָּא דְמָארֵיהּ, מְבָרְכַת וְסָגְדַת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:א׳) בָּרְכִי נַפְשִׁי וְגו'.","אָמַר רַבִּי עֲקִיבָא קוּדְשָׁא בְּרִיךְ הוּא קָאִים עֲלוֹהִי. וְנִשְׁמָתָא פָּתַח וְאָמַר יְיָ אֱלהֵי גָּדַלְתָּ מְאֹד וְגו' כָּל הַפָּרָשָׁה עַד סִיּוּמָא דְּקָאָמַר יִתַּמּוּ חַטָאִים וְגו'. וְעוֹד אָמַר רַבִּי עֲקִיבָא וְלָא דָא בִּלְחוֹדוֹי אֶלָּא מְשַׁבַּחַת לֵיהּ עַל גּוּפָא דְּאִשְׁתָּאַר בְּעָלְמָא דֵין וְאָמַר (תהילים ק״ג:א׳) בָּרְכִי נַפְשִׁי אֶת יְיָ וְכָל קְרָבַי וְגו'.","וְקוּדְשָׁא בְּרִיךְ הוּא אָזִיל. מְנָא לָן הַאי. מֵהַאי קְרָא דִּכְתִיב וַיִּרָא אֵלָיו יְיָ בְּאֵלוֹנֵי מַמְרִא, זְה יַעֲקֹב. מַהוּ מַמְרִא. מִשּׁוּם דְּאַחְסִין מָאתָן עָלְמִין מֵעֵדֶן והוּא כִּסֵּא. אָמַר רַבִּי יִצְּחָק מַמְרֵא בְּגִימַטְרִיָּא מָאתָן וּתְמַנִין וְחַד הֲוָה, מָאתָן דְּעֵדֶן דִּכְתִיב, (שיר השירים ח׳:י״ב) וּמָאתַיִם לַנּוֹטְרִים אֶת פִּרְיוֹ, וּתְמַנִּין וְחַד דְּהוּא כִּסֵּא. וּבְגִין כָּךְ אִתְקְרֵי וַיֵּרָא אֵלָיו יְיָ בְּאֵלוֹנֵי מַמְרֵא. וְעַל שׁוּם דָּא נִקְרָא מַמְרֵא.","אָמַר רַבִּי יְהוּדָה מַהוּ בְּאֵלוֹנֵי. רְצּוֹנוֹ לוֹמַר תּוּקְפּוֹי הֲדָא הוּא דִכְתִיב, (בראשית מ״ט:כ״ד) אֲבִיר יַעֲקֹב. וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל. הֲדָא הוּא דִכְתִיב, (תהילים ט״ו:א׳) יְיָ מִי יָגוּר בְּאָהֳלֶךָ וְגו'. כְּחוֹם הַיּוֹם. דִּכְתִיב, (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְּדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.","אָמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי בְּהַהִיא שַׁעֲתָא אָזִיל קוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין דְּשָׁמְעִין אַבָהָתָא אַבְרָהָם וְיִצְּחָק דְּקוּדְשָׁא בְּרִיךְ הוּא אָזִיל לְגַבֵּיהּ. תָּבְעִין מִן יַעֲקֹב לְמֵיזַל עִמְּהוֹן וּלְאַקְדָּמָא לֵיהּ שְׁלָם","ואִנּוּן קָיְימִין עֲלוֹהִי. מִמַּאי דִּכְתִיב וַיִּשָּׂא עֵינָיו ויַּרְא וְהִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. שְׁלשָׁה אֲנָשִׁים (דקיימין) אִלֵּין אֲבָהָתָא אַבְרָהָם יִצְּחָק וְיַעֲקֹב דְּקָיְימִין עֲלוֹהִי וְחָמוּ עוֹבָדִין טָבִין (נ\"א דעבד) דְּעָבְדִין. וַיַּרְא ויָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אָרְצָּה. מִשּׁוּם דְּחָמֵי שְׁכִינַת יְקָרָא עִמְהוֹן הֲדָא הוּא דִכְתִיב, (שיר השירים א׳:ג׳) עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ (אלו הן האבות):","דָּבָר אַחֵר וַיִּרָא אֵלָיו יְיָ בְּאֵלוֹנֵי מַמְרֵא. רַבָּנָן פָּתְחֵי בְּהַאי קְרָא בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם. דְּתַנְיָא אָמַר רַבִּי יְהוּדָה בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם הוּא יוֹם הַדִּין הַגָּדוֹל שֶׁהַנְּשָׁמָה מִתְפָּרֶדֶת מִן הַגּוּף. וְלֹא נִפְטַר אָדָם מִן הָעוֹלָם עַד שֶׁרוֹאֶה אֶת הַשְּׁכִינָה הֲדָא הוּא דִכְתִיב (שמות ל״ג:כ׳) כִּי לֹא יִרְאַנִּי הָאָדָם וָחָי. וּבָאִין עִם הַשְּׁכִינָה שְׁלשָׁה מַלְאֲכֵי הַשָּׁרֵת לְקַבֵּל נִשְׁמָתוֹ שֶׁל צַּדִּיק. הֲדָא הוּא דִכְתִיב וַיֵּרָא אֵלָיו יְיָ וגו'. כְּחוֹם הַיּוֹם. זְה יוֹם הַדִּין הַבּוֹעֵר כַּתַּנּוּר לְהַפְרִיד הַנְּשָׁמָה מִן הַגּוּף.","וַיִּשָּׂא עֵינָיו וַיַּרְא והִנֵּה שְׁלשָׁה אֲנָשִׁים. הַמְבַקְּרִים מַעֲשָׂיו מַה שֶּׁעָשָׂה, וְהוּא מוֹדֶה עֲלֵיהֶם בְּפִיו. וְכֵיוָן שֶׁהַנְּשָׁמָה רוֹאָה כָּךְ, יוֹצֵּאת מִן הַגּוּף עַד פֶּתַח בֵּית הַבְּלִיעָה, וְעוֹמֶדֶת שָׁם עַד שֶׁמִּתְודָּה כָּל מַה שֶּׁעָשָׂה הַגּוּף עִמָּהּ בָּעוֹלָם הַזְּה. ואָז נִשְׁמַת הַצַּדִּיק הִיא שְׂמֵחָה בְּמַעֲשֶׂיהָ וּשְׂמֵחָה עַל פִּקְדוֹנָהּ. דְּתָאנָא אָמַר רַבִּי יִצְּחָק נִשְׁמָתוֹ שֶׁל צַּדִּיק מִתְאַוָּה אֵימָתַי תֵּצֵּא מִן הָעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל, כְּדֵי לְהִתְעַנֵּג בָּעוֹלָם הַבָּא.","תָּנוּ רַבָּנָן כְּשֶׁחָלָה רַבִּי אֱלִיעֶזֶר הַגָּדוֹל, הַהוּא יוֹמָא עֶרֶב שַׁבָּת הֲוָה, וְאוֹתִיב לִימִינֵיהּ הוֹרְקְנוּס בְּרֵיהּ, והֲוָה מְגַלֵּי לֵיהּ עֲמִיקְתָּא וּמַסְתַּרְתָּא, וְהוּא לָא הֲוָה מְקַבֵּל בְּדַעְתֵּיהּ מִלַּיָּיא, דְּחֲשִׁיב כִּמְטוֹרָף בְּדַעְתֵּיהּ הֲוָה. כֵּיוָן דְּחָמָא דְּדַעְתָּא דְּאֲבוֹי מִתְיַשְּׁבָא עֲלוֹי, קַבִּיל מִנֵּיהּ מְאָה וּתְמַנִּין וְתִשְׁעָה רָזִין עִלָּאִין.","כַּד מָטָא לְאַבְנֵי שַׁיִשׁ דְּמִתְעָרְבֵי בְּמַיָא עִלָּאָה, בָּכָה רַבִּי אֱלִיעֶזֶר וּפָסַק לְמֵימַר, אָמַר קוּם הָתָם בְּרִי. אָמַר לֵיהּ אַבָּא לָמָה. אָמַר לֵיהּ חָזִינָא דְּאוֹחִית חֲלָף מִן עָלְמָא. אָמַר לֵיהּ זִיל וְאֵימָא לְאִמָּךְ דְּתִסְתַּלַּק תְּפִלָּאִי בְּאֲתַר עִלָּאָה, וּבָתַר דְּאֶסְתַּלֵּק מִן עָלְמָא וְאַיְתֵי הָכָא לְמֶחֱמֵי לְהוֹן לָא תִבְכֵּי דְּאִנּוּן קְרִיבִין עִלָּאִין וְלָא תַתָּאִין וְדַעְתָּא דְבַר נָשׁ לָא יָדַע בְּהוּ.","עַד דְּהֲווּ יָתְבֵי, עָאלוּ חַכִּימֵי דָרָא לְמִבְקַּר לֵיהּ, אוֹלִיט לְהוּ עַל דְּלָא אָתוּ לְשַׁמָּשָׁא לֵיהּ דְּתָנִינָן גְּדוֹלָה שִׁמּוּשָׁהּ יוֹתֵר מִלִּמּוּדָהּ. עַד דְּאָתָא רַבִּי עֲקִיבָא, אָמַר לֵיהּ עֲקִיבָא עֲקִיבָא לָמָה לָא אָתֵית לְשַׁמָּשָׁא לִי (דהא אתא עתא לאצרפא). אָמַר לֵיהּ רַבִּי לָא הֲוָה לִי פְּנַאי. אַרְתַּח אָמַר אֶתְמְהָה עֲלָךְ אִי תָּמוּת מִיתַת עַצְּמְךָ. לַטְיֵיה דִּיהֵא קָשֶׁה מִכֻּלְהוֹן מִיתָתֵיהּ.","בָּכֵי רַבִּי עֲקִיבָא וְאָמַר לֵיהּ רַבִּי אוֹלִיף לִי אוֹרַיְיתָא. אַפְתַּח פּוּמֵיהּ רַבִּי אֱלִיעֶזֶר בְּמַעֲשֵׂה מֶרְכָּבָה. אֲתָא אֶשָׁא ואַסְחַר לְתַרְוִויהוֹן. אָמְרוּ חַכִּימַיָא שְׁמַע מִינָהּ דְּלֵית אֲנַן חַזְיָין וּכְדָאִין לְכָךְ, נָפְקוּ לְפִתְחָא דְבָרָא וְיָתִיבוּ תַּמָּן, הֲוָה מַה דְּהֲוָה וְאֲזַל אֶשָׁא.","וְאוֹלִיף בְּבַהֶרֶת עַזָּה תְּלַת מְאָה הֲלָכוֹת פְּסוּקוֹת, וְאוֹלִיף לֵיהּ רי\"ו טְעָמִים דִּפְסוּקֵי דְּשִׁיר הַשִּׁירִים. והֲווּ עֵינוֹי דְּרַבִּי עֲקִיבָא נַחֲתִין מַיָא. וְאִתְחַזַּר אֶשָׁא כְּקַדְמִיתָא. כַּד מָטָא לְהַאי פְּסוּקָא (שיר השירים ב׳:ה׳) סַמְכוּנִי בָּאֲשִׁישׁוֹת רַפְּדוּנִי בַּתַּפּוּחִים כִּי חוֹלַת אַהֲבָה אָנִי, לָא יָכִיל לְמִסְבַּל רַבִּי עֲקִיבָא וְאָרִים קָלֵיהּ בִּבְכִיָּיתָא וְגָעֵי וְלָא הֲוָה מְמַלֵּל מִדְחִילוּ דִּשְׁכִינְתָּא דְּהֲוַת תַּמָּן.","אוֹרֵי לֵיהּ כָּל עָמִיקְתָּא וְרָזִין עִלָּאִין דְּהֲוָה בֵּיהּ בְּשִׁיר הַשִּׁירִים. וְאוֹמֵי לֵיהּ אוֹמָאָה דְּלָא לִישְׁתַּמֵּשׁ בְּשׁוּם חַד פָּסוּק מִנֵּיהּ כִּי הֵיכִי דְּלָא לִיחָרֵיב עָלְמָא, קוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ. ולָא בָּעֵי קַמֵּיהּ דְּיִשְׁתַּמְּשׁוּן בֵּיהּ בְּרִיָיתֵי מִסְגִיאוּת קְדוּשָׁתָא דְּאִית בֵּיהּ. לְבָתַר נָפִיק רַבִּי עֲקִיבָא וְגָעֵי וְנָבְעִין עֵינוֹי מַיָא, וְהֲוָה אָמַר, וַוי רַבִּי, וַוי רַבִּי, דְּאִשְׁתָּאַר עָלְמָא יָתוֹם מִנָּךְ. עָאלוּ כָּל שְׁאָר חַכִּימַיָא גַּבֵּיהּ וְשָׁאֲלוּ לֵיהּ וְאָתִיב לְהוֹן.","הֲוָה דָּחִיק לֵיהּ (שעתא) לְרַבִּי אֱלִיעֶזְר, אַפִּיק תְּרֵי דְרוֹעוֹי ושַׁוִּינוּן עַל לִבֵּיהּ. פָּתַח וְאָמַר, אִי עָלְמָא עָלְמָא עִלָּאָה, חָזְרַת לְאָעֳלָא וּלְאִגְנָזָא מִן תַּתָּאָה כָּל נְהִירוּ וּבוּצִּינָא. וַוי לְכוֹן תְּרֵי דְּרָעֵי וַוי לְכוֹן תְּרֵי תּוֹרוֹת דְּיִשְׁתַּכְּחוּן יוֹמָא דֵין מִן עָלְמָא. דְּאָמַר רַבִּי יִצְּחָק כָּל יוֹמוֹי דְּרַבִּי אֱלִיעֶזֶר הֲוָה נְהִירָא שְׁמַעְתָּא מִפּוּמֵיהּ כְּיוֹמָא דְּאִתְיְהִיבַת בְּטוּרָא דְסִינַי.","אָמַר אוֹרַיְיתָא (סברית גמרא) גְּמָרִית וְחָכְמְתָא סְבָרִית וְשִׁמּוּשָׁא עֲבָדִית. דְּאִלּוּ יְהוֹן כָּל בְּנֵי אֵינָשָׁא דְּעָלְמָא סוֹפְרִים לָא יָכְלִין לְמִכְתַּב וְלָא חַסְרֵי תַּלְמִידַי מֵחָכְמָתִי אֶלָּא כְּכוֹחְלָא בְּעֵינָא ואֲנָא מֵרַבּוֹתַי אֶלָּא כְּמַאן דְּשָׁתֵי בְּיַמָּא. וְלָא הֲוָה, אֶלָּא לְמִיתַּן טִיבוּתָא לְרַבּוֹהִי יַתִּיר מִנֵּיהּ.","והֲווּ שָׁאֲלִין מִנֵּיהּ בְּהַהוּא סַנְדְּלָא דְּיִבּוּם עַד דְּנָפַק נִשְׁמָתֵיהּ וְאָמַר טָהוֹר. וְלָא הֲוָה תַּמָּן רַבִּי עֲקִיבָא. כַּד נָפַק שַׁבַּתָּא אַשְׁכְּחֵיהּ רַבִּי עֲקִיבָא דְּמִית, בָּזַע מָאנֵיהּ וגָרִיר כָּל בִּשְׂרֵיהּ וְדָמָא נָחִית וְנָגִיד עַל דִּיוּקְנֵיהּ. הֲוָה צָּוח וּבְכֵי, נָפַק לְבָרָא וְאָמַר, שְׁמַיָא שְׁמַיָא, אָמְרוּ וּלְסִיהֲרָא לְשִׁמְשָׁא דִּנְהִירוּתָא דְּהֲוַת נְהִיר יַתִּיר מִנְהוֹן הָא אִתְחַשַּׁךְ."],[[0,"כדין וירא","וכו': אז \u0003וירא וירץ לקראתם,\u0004 כי תשוקתה של מדרגה התחתונה, שהיא הנוקבא, הוא להתחבר בהם, בחג\"ת, וחדוה שלה היא להמשך אחריהם. ולפי\"ז קאי \u0003וירא וירץ,\u0004 על הנוקבא, שרצתה להתחבר בהם. \u0003וישתחו ארצה,\u0004 כדי להעשות ולהתתקן לכסא בעדם. כלומר שהנוקבא נעשית לכסא אל החג\"ת האלו דז\"א, שישרו עליה, כמו אדם היושב על כסא."],[1,"ת\"ח עבד קב\"ה וכו'.","בוא וראה, עשה הקב\"ה את דוד המלך, שה\"ס הנוקבא, לרגל אחד מכסא העליון, כמו האבות. פירוש. \u0003כסא העליון\u0004 ה\"ס בינה. \u0003האבות,\u0004 ה\"ס חג\"ת שהם ג' רגלי הכסא הזה, והז\"א תקן את הנוקבא, הנקראת דוד המלך, שתהיה לרגל רביעי לכסא הזה. ונמצאת הנוקבא במדרגה אחת עם האבות שהם חג\"ת, כי נתקנה לרגל הכסא כמוהם. (ועי' לעיל בראשית א' דף ק\"י אות קי\"ז ד\"ה ואלו)."],[1,"ואע\"ג דאיהי כורסיא וכו': שואל ואע\"פ","שהיא כסא אל האבות כנ\"ל. ואיך נאמר שנתקנה במדרגה אחת עם האבות להשלים ד' רגלי הכסא. ומשיב אבל הוא רק בזמן, שהיא נתחברה עמהם, להיות רגל אחד להתתקן בכסא העליון, ומשום זה קבל דוד המלך מלכות על ישראל בחברון שבע שנים כדי להתחבר בהם, בחג\"ת. והוא נתבאר. (בפרשת לך לך דפו\"י ע\"ט אות ס\"ה בסולם) שאומר שם, דדוד לית ליה לקבל מלכותא אלא עד דיתחבר באבהן, דאינון בחברון."],[1,"","פירוש. כי מתחילה נבנית הנוקבא בסוד ב' מאורות הגדולים, דהיינו בקומה שוה עם ז\"א מאחוריו, ואז שניהם משמשים בכתר אחד שהוא בינה. שז\"א מקבל צד ימין שלה והנוקבא צד שמאל שלה. ואז נחשבים זו\"ן לד' רגלין שלה, והיא נקראת כסא העליון. חג\"ת דז\"א הם ג' רגלי הכסא. והנוקבא היא רגל רביעי. באופן ששניהם שוים זה לזה. אמנם אלו המוחין נחשבים להנוקבא רק למוחין דאחורים, ובכדי להבנות במוחין דפנים, היא מתמעטת בסוד המאור הקטן, ואז יכולה לקבל מז\"א מוחין דפנים. ומבחינה זו היא נעשית כסא אל ז\"א מתחתיו. וכבר נתבאר כל זה באורך (לעיל בראשית א' דף ק\"ד מאות קי\"א עד אות קי\"ח) ואין להכפיל דברים. באופן שיש ב' זמנים להנוקבא. מתחילה בקומה שוה לז\"א, ואח\"כ מתמעטת ונעשית קטנה ממנו."],[1,"","וז\"ש \u0003ואע\"ג דאיהי כרסיא לגבייהו,\u0004 דהיינו בזמן של מוחין דפנים, היא קטנה ממנו ונבחנת לכסא אל החג\"ת דז\"א. \u0003אבל בזמנא דאתחבר בהו, איהי חד סמכא לאתתקנא בכרסיא עלאה.\u0004 דהיינו בזמן של מוחין דאחורים שנתחברה עם חג\"ת דז\"א בקומה שוה, הרי היא אז רגל אחת להתתקן בכסא העליון בשוה עם חג\"ת דז\"א. כי שניהם משמשים אז בשוה בכסא העליון שהוא בינה. גם נתבאר שם שלולא קבלה הנוקבא מקודם את המוחין דאחורים בסוד ב' המאורות הגדולים לא היתה יכולה לקבל אח\"כ מוחין דפנים. ע\"ש. וז\"ש \u0003ובגין כך נטל מלכותא בחברון דוד מלכא שבע שנין לאתחברא בהו.\u0004 כי מלכותא דחברון ה\"ס המוחין דאחורים ומלכותא דכל ישראל היא מוחין דפנים. ואם לא קבל דוד המלך את מלכותא דחברון מקודם, שהם המוחין דאחורים, לא היה ראוי לקבל כלל את מלכות כל ישראל, שהם המוחין דפנים. וז\"ש לעיל (בפרשת לך לך דפו\"י דף ע\"ט ע\"ב דף כ\"ו אות ס\"ה בסולם) \u0003דדוד לית ליה לקבל מלכותא, אלא עד דיתחבר באבהן,\u0004 שהם חג\"ת, \u0003דאינון בחברון.\u0004 דהיינו שצריכה להתחבר מקודם בקומה שוה עם החג\"ת מאחורים, ולולא זה לא היה יכול לקבל המלכות השלמה שהיא מוחין דפנים."],[2,"וירא אליו ה' באלוני ממרא וכו':","שואל, למה באלוני ממרא ולא במקום אחר. ומשיב, אלא משום שממרא נתן לו עצה על ברית מילה שלו. כי בשעה שאמר הקב\"ה לאברהם שימול את עצמו, הלך אברהם להועץ עם חבריו. אמר לו ענר. אתה כבר יותר מתשעים שנה, ואתה תצער את עצמך."],[3,"א\"ל ממרא דכרת וכו':","אמר לו ממרא, זכור את היום שהשליכו הכשדים אותך בכבשן האש. ואותו הרעב שעבר על העולם, שכתוב, ויהי רעב בארץ וירד אברם מצרימה. ואת אלו המלכים שרדפו אנשיך אחריהם והכית אותם. והקב\"ה הצילך מכולם ואיש לא יכול לעשות לך רעה. קום עשה מצות רבונך. אמר לו הקב\"ה לממרא. ממרא, אתה נתת לו עצה על המילה, חייך, איני מתגלה עליו אלא בהיכל שלך. וזהו שכתוב באלוני ממרא."],[4,"רבנן פתחי וכו':","רבנן פתחו בביאור הפרשה, עם הכתוב הזה, לריח שמניך טובים, שמן תורק וגו', תנו רבנן. נשמה הזו של האדם, בשעה שעולה מהארץ לרקיע, דהיינו בשעה שהאדם ישן בלילה, והנשמה עומדת באותה זיהרא עלאה שאמרנו (בראשית ב' אות רפ\"ט). הקב\"ה מבקר אותה."],[5,"תא שמע ארשב\"י וכו':","בוא ושמע אמר ר\"ש בן יוחאי, כל נשמה של צדיק, כיון שעומדת במקום שכינת כבודו ית', דהיינו שראויה לקבל הארת חכמה, שה\"ס עמידה, וראויה לישב אצלה, היינו לקבל את לבוש החסדים. שה\"ס ישיבה. הקב\"ה, הוא ז\"א, קורא אל האבות הם חג\"ת, ג' קוין שלו, ואמר להם, לכו ובקרו את פלוני הצדיק שבא, והקדימו אותו שלום משמי, כלומר שג' הקוין ישפיע לה הארת הזווג הנק' שלום. משמי. היא הנוקבא, והם אומרים, רבון העולם, אינו ראוי לאב ללכת לראות את בנו, הבן צריך לראות ולחזות ולדרוש לאביו."],[5,"","פירוש מתחילה האיר ז\"א להנשמה את הארת קו ימין הנקרא אברהם. וה\"ס הארת החולם. ואח\"כ האיר לה הארת קו שמאל, הנקרא יצחק, וה\"ס הארת השורק. ונעשה מחלוקת בין ב' הקוין (כנ\"ל, בראשית א' דף נ\"ז אות מ\"ד ד\"ה והנה אחר ע\"ש) ואז נסתמה הנשמה, ונסתלקו הארת ב' הקוין מהנשמה, וחזרו אל ז\"א, ואמרו לו \u0003מארי עלמא לא אתחזי לאבא. למיזל למחמי לברא,\u0004 כי נסתמה ואינה יכולה לקבל ממנו. אלא \u0003ברא אתחזי למחמי ולמחזי ולמתבע לאבוי,\u0004 כלומר, שאמרו שהנשמה צריכה להעלות מ\"ן מסוד מסך דחירק, ואז יתעורר קו אמצעי שה\"ס יעקב, ואז תוכל הנשמה לקבל הארתינו. \u0003למדמי\u0004 ה\"ס ג\"ר דחכמה. \u0003למחזי\u0004 ה\"ס ו\"ק דחכמה. \u0003למתבע\u0004 ה\"ס לבוש החסדים. שאינה נמשכת אלא בסוד דרישה ותביעה, דהיינו העלאת מ\"ן."],[6,"והוא קרי ליעקב וכו':","והקב\"ה קורא את יעקב, ואומר לו: אתה שהיה לך צער גידול בנים, לך וקבל פניו של פלוני הצדיק שבא כאן, ואני אלך עמך וזהו שכתוב, מבקשי פניך, יעקב סלה. מבקש לא נאמר. אלא \u0003מבקשי:\u0004 כי קאי על נשמות הצדיקים, שיעקב אבינו מקבל פניהם והם מבקשי פניו. אמר רבי חייא מתחילת הכתוב משמע זה שכתוב, זה דור דורשיו וגו'. שמשמע, שכונת הכתוב הוא על נשמות הצדיקים, שהם הדורשים של הדור."],[6,"","פירוש. \u0003יעקב\u0004 ה\"ס קו אמצעי \u0003בנים\u0004 ה\"ס לידת מוחין \u0003צערא דבנין,\u0004 ה\"ס המסך דחירק המקטין הקומה מג\"ר לו\"ק (כנ\"ל לך לך דף י\"ג אות כ\"ב ד\"ה ונתבאר) וגורם בזה צער, אבל אי אפשר להוליד בנים שהם מוחין, זולת המסך הזה, כמ\"ש שם."],[6,"","וז\"ש \u0003והוא קרי ליעקב,\u0004 דהיינו אחר שהנשמה העלתה מ\"ן כנ\"ל בסמוך, קרי ליעקב היינו שהזמין המסך דחירק, שעליו יוצא קו אמצעי שה\"ס יעקב. ואמר לו אנת דהוה לך צערא דבנין, כלומר שדרכך להמשיך מוחין על מסך הזה דחירק, תעשה גם עתה זווג הזה לצורך הנשמה. פנים ה\"ס חכמה, קבלת פנים ה\"ס התלבשות חכמה בחסדים. וז\"ש, \u0003זיל וקבל פני דפלניא צדיקא,\u0004 היינו, שיוציא קומת חסדים וילביש החכמה בחסדים שז\"ס קבלת פנים. \u0003ואנא איזיל עמך,\u0004 היינו כללות ז\"א."],[7,"א\"ר יעקב וכו':","אר\"י אר\"ח, יעקב אבינו הוא כסא הכבוד. וכן תאנא דבי אליהו, יעקב אבינו הוא כסא בפני עצמו, שכתוב, וזכרתי את בריתי יעקב. ברית כרת הקב\"ה עם יעקב לבדו, יותר מהכריתת ברית עם כל אבותיו. שעשה אותו כסא הכבוד להשראתו ית' לבד מהראשונים. והוא מטעם שהראשונים שהם אברהם ויצחק אינם יכולים להאיר זולתו כנ\"ל, לכן כולל בעצמו גם הארתם, ונעשה כסא בפני עצמו."],[8,"רבי אליעזר הוה יתיב וכו':","ר\"א היה יושב והיה לומד תורה. בא אצלו רבי עקיבא, אמר לו במה עוסק מר, אמר לו במקרא הזה, שכתוב, וכסא כבוד ינחילם. מהו כסא כבוד ינחילם. זה הוא יעקב אבינו שעשה אותו כסא הכבוד בפני עצמו, לקבל תורה בעד נשמות הצדיקים. ושיעור הכתוב הוא, \u0003וכסא כבוד,\u0004 דהיינו תורתו של יעקב, שנעשה לכסא הכבוד, \u0003ינחילם\u0004 לנשמות הצדיקים."],[9,"וקב\"ה אזיל עמיה וכו':","והקב\"ה הולך עם יעקב, בכל ראש חדש וראש חדש, (כנ\"ל באות כ\"א) וכאשר הנשמה רואה, את כבוד האספקלריא, היא השכינה של רבונה, הנשמה מברכת ומשתחוית לפני הקב\"ה, זהו שכתוב ברכי נפשי וגו'."],[10,"א\"ר עקיבא וכו':","אר\"ע, הקב\"ה עומד עליה, על הנשמה, והנשמה פותחת ואומרת, ה' אלקי גדלת מאד וגו' כל הפרשה עד הסיום, שנאמר יתמו חטאים וגו'. ועוד אמר ר\"ע. ולא זה בלבד, אלא שמשבח להקב\"ה גם על הגוף שנשאר בעולם הזה, ואומרת, ברכי נפשי את ה' וכל קרבי וגו'. וכל קרבי יורה על הגוף. כלומר שתחילה משבחת הנשמה להקב\"ה על השגתה עצמה ואז אומרת ברכי נפשי את ה' ה' אלקי גדלת מאד. (תהלים ק\"ד) ואח\"כ משבחת לו גם על הגוף. כלומר, שזיו הנשמה נמשך למטה ומאיר אל הגוף. ואז אומרת ברכי נפשי את ה' וכל קרבי וגו' (תהלים ק\"ג) שתשבחות האלו הם על אור הגוף."],[11,"וקב\"ה אזיל וכו':","והקב\"ה הולך עם יעקב, מנין לנו זה. ממקרא הזה, שכתוב וירא אליו ה' באלוני ממרא. זהו יעקב, שנקרא ממרא. הרי שהקב\"ה הולך עם יעקב. ושואל, מהו השם ממרא, ואומר משום שיעקב ירש מאתים עולמות מעדן, והוא כסא, כנ\"ל שנעשה לכסא הכבוד בפ\"ע. ומפרש רבי יצחק, \u0003ממרא\u0004 הוא בגימטריא רפ\"א, הנה מאתים של עדן, שזכה בהם יעקב שכתוב, ומאתים לנוטרים את פריו. ושמונים ואחד שהוא בגימטריא \u0003כסא.\u0004 הרי מאתים ושמונים ואחד שבגימטריא \u0003ממרא\u0004 מאתים עולמות מעדן ה\"ס החכמה הנק' עדן. \u0003וכסא\u0004 ה\"ס החסדים המלבישים את החכמה. וע\"כ נאמר וירא אליו ה' באלוני ממרא, כי משום זה נקרא יעקב ממרא. כלומר משום שכולל בחי' עדן ובחי' כסא, שהם סוד השם ממרא, ע\"כ וירא אליו ה'."],[12,"אמר ר' יהודה וכו':","אר\"י מהו \u0003באלוני,\u0004 אם ממרא זה יעקב למה נאמר באלוני ממרא, ואומר, באלוני, רצונו לומר, תקפו. והוא כמו שכתוב, אביר יעקב. כלומר באלוני ממרא הוא כמו שהיה כתוב כאן, אביר יעקב. כי אלוני פירושו אביר ותוקף, וממרא זה יעקב."],[12,"והוא יושב פתח האהל וכו':","זהו שכתוב ה' \u0003מי\u0004 יגור באהלך וגו'. כלומר פתח האהל ה\"ס הארת קו הימין, שה\"ס חסדים מכוסים, וה\"ס הארת נקודת החולם שנקרא \u0003מ\"י\u0004 דאלקים, (כנ\"ל בראשית א' דף ט\"ז אות ט' ד\"ה ותדע) המרומז בסו\"ה \u0003מי\u0004 יגור באהלך וגו'. דהיינו בהמלה \u0003מ\"י.\u0004"],[12,"כחום היום וכו':","שכתוב וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה. דהיינו הארת קו השמאל, שה\"ס הארת נקודת השורק שנקראת \u0003אל\"ה\u0004 דאלקים. שה\"ס הארת חכמה בלי חסדים, המכונה יציאת השמש מנרתיקה, כי אין אור החכמה מאירה אלא בנרתיק מחסדים. וכשמאירה בלי חסדים היא שורפת, בסו\"ה \u0003כחום היום.\u0004 ואז הרשעים נדונים בה. אבל הצדיקים מתרפאים בה. כי מגלים מ\"ן וממשיכים חסדים להלביש החכמה. וזהו שמרמז הזהר את פירושו של כחום היום, בהכתוב וזרחה לכם יראי שמי שמש צדקה ומרפא בכנפיה, ללמדינו, שאין אור השמש הזה מרפא אלא \u0003בכנפיה,\u0004 דהיינו בלבוש החסדים המכסים על תוקפה של השמש כמו כנפים. ומטרם ביאת הכנפים מקו האמצעי ה\"ס \u0003כחום היום,\u0004 ששורפת אז."],[13,"אמר רבן יוחנן בן זכאי וכו':","אריב\"ז, באותה שעה, היינו בעת שהנשמה היא בבחי' כחום היום, הולך הקב\"ה, שהוא ז\"א, כדי להשפיע להנשמה. כלומר, שהולך ממקום למקום בסוד \u0003תלת דוכתי,\u0004 (כנ\"ל בראשית א' דף כ' אות י\"ב ע\"ש) שאומר \u0003שמא דא כלילא בתלת דוכתו,\u0004 וכן הולך מפתח האהל, שה\"ס מקום החסדים הנעלמים בסוד \u0003מ\"י\u0004 וקו ימין. אל המקום שה\"ס \u0003כחום היום,\u0004 שה\"ס \u0003אל\"ה\u0004 וקו שמאל. ואח\"כ אל מקום בחינת יעקב שה\"ס קו אמצעי. כמ\"ש לפנינו."],[13,"ובגין דשמעין אבהתא וכו':","ומשום שהאבות אברהם ויצחק שמעו שהקב\"ה היינו כללות ז\"א, הולך אל הנשמה, כלומר שהאבות הרגישו שהנשמה היא במצב כחום היום, שצריכה למקום הלבשת החסדים. הם מבקשים מן יעקב שילך עמהם ולהקדים לה להנשמה שלום, כלומר שימשיך על מסך דחירק שלו קומת החסדים, המכרעת בין אברהם ויצחק, ואז מתלבשת החכמה בחסדים, שה\"ס \u0003שלום.\u0004 והטעם שנקראת \u0003שלום,\u0004 הוא, כי מטרם הכרעת, קומת החסדים, ב' הקוין נמצאים במחלוקת (כנ\"ל בראשית א' דף נ\"ז ד\"ה והנה אחר) אלא ע\"י קומת החסדים, שה\"ס קו האמצעי, נעשה שלום ביניהם."],[14,"ואינון קיימין עלוהי וכו':","והם, אברהם ויצחק עומדים על הנשמה, כלומר, אחר שיעקב השפיע החסדים בסוד קדימת השלום, מאירים אליה גם ב' הקוין שהם אברהם ויצחק, שכתוב וישא עיניו וירא היינו הנשמה והנה שלשה אנשים נצבים עליו, שלשה אנשים, הם האבות, אברהם יצחק ויעקב. הנצבים עליו, ורואים מעשים הטובים שעשתה הנשמה. כלומר, שרואים המ\"ן של הנשמה, ומשפיעים לה מיין דוכרין."],[14,"וירא וירץ לקראתם מפתח האהל וישתחו ארצה וכו':","משום שראתה שכינת כבודו ית' עמהם, וזהו שכתוב, על כן עלמות אהבוך."],[14,"","פירוש. כי רומז על הכתוב שפתח בו בתחילת המאמר. לריח שמניך טובים כשמן תורק שמך על כן עלמות אהבוך. שהוא מתבאר עם כל המבואר עד כאן. \u0003לריח,\u0004 ה\"ס המ\"ן שהנשמה מעלה, להמשיך הארת השלום של יעקב דהיינו קומת החסדים כנ\"ל, ואז מתלבשת החכמה בחסדים, וע\"כ, \u0003שמניך טובים\u0004 שהמוחין מקובלים בסוד שמן הטוב. \u0003שמן תורק\u0004 היינו \u0003כחום היום,\u0004 שאז מסתלקים ב' הקוין מהנשמה ואינם יכולים להאיר כנ\"ל, ונבחן אז \u0003שהשמן,\u0004 שה\"ס המוחין, \u0003מורק\u0004 מהנשמה. שה\"ס הארת נקודת השורק כנ\"ל. אמנם אח\"כ בביאת החסדים מיעקב, מושגת הארת החכמה מסוד נקודת השורק הזאת, כנ\"ל, הרי, אשר, \u0003כשמן תורק,\u0004 שבשעת הארת נקודת השורק, מושג \u0003שמך,\u0004 שה\"ס גילוי השכינה, שהיא \u0003שמו\u0004 של הקב\"ה. ועכ\"ז כל חשקה של הנשמה היא להמשיך החסדים דקו ימין, שה\"ס מ\"י, וזהו שמסיים הכתוב \u0003על כן עלמות אהבוך,\u0004 היינו החסדים הנעלמים מסוד מ\"י, שהם ג\"ר דבינה, משם דוקא אוהבות הנשמות להמשיך. וזהו שמבואר בהכ' \u0003וירא,\u0004 היינו גילוי שכינה, ע\"י הארת השורק אחר שמתלבשת בחסדים ואז \u0003וירץ לקראתם,\u0004 לקבל בעיקר, \u0003מפתח האהל\u0004 שה\"ס \u0003מ\"י\u0004 וזהו שכתוב \u0003על כן עלמות אהבוך.\u0004 דהיינו החסדים המכוסים מחכמה הנקראים עלמות, שהנשמות אוהבים אותם ביותר כנ\"ל."],[15,"דבר אחר, וירא אליו ה' באלוני ממרא וכו':","רבנן פתחו בכתוב הזה, שמדבר בשעת פטירתו של אדם וכו' (אין צריך פירוש)."],[17,"תנו רבגן כשחלה וכו':","כשחלה רבי אליעזר הגדול ונסה למות, אותו היום היה ערב שבת והושיב לימינו את הורקנוס בנו. והיה מגלה אליו עמוקות ונסתרות, והורקנוס לא היה מקבל ממנו בתחילה בדעה מלאה, כי חשב שדעתו אינה מיושבת עליו, לאחר שראה שדעתו של אביו מיושבת עליו, קבל ממנו מאה ושמונים ותשעים סודות עליונים."],[18,"כד מטי לאבני שיש טהור וכו':","כשהגיע להסוד של אבני שיש המתערבים במים עליונים בכה רבי אליעזר והפסיק מלדבר. אמר קום ולך שמה בני. אמר לו למה. אמר לו אני רואה שאמהר לעבור מהעולם, אמר לו לך ואמור לאמך, שיסתלקו התפילין שלי למקום עליון. כלומר, שרמז לה על הסתלקותו, ואחר שאסתלק מהעולם ואבא כאן לראות אותם היינו לבני המשפחה לא יבכו, כי הם עמי קרובים עליונים ולא תחתונים, ודעת אנוש לא משיג בזה."],[19,"עד דהוו יתבי וכו':","עוד שהם יושבים, נכנסו חכמי הדור לבקרו וקלל אותם על שלא באו אליו לשמשו, דתנן, גדולה שמושה יותר מלמודה. בינתים בא רבי עקיבא. אמר לו עקיבא עקיבא, למה לא באת לשמשיני. א\"ל, רבי, לא היה לי זמן פנוי. כעס ואמר, תמה אני עליך אם תמות מיתת עצמך. וקללו שמיתתו יהיה קשה מכולם. כלומר, שקלל גם את שאר חכמים שלא באו לשמשו, שלא ימותו מיתת עצמם, ואמר, שמיתת ר\"ע תהיה קשה מכולם."],[20,"בכי ר' עקיבא וכו':","בכה ר\"ע ואמר לו, רבי, למדני תורה. פתח פיהו רבי אליעזר במעשה מרכבה. בא אש וסבבה את שניהם. אמרו החכמים, משמע מזה, שאין אנו ראוים וכדאים לזה, דהיינו לשמוע עתה דברי תורתו. יצאו להפתח שבחוץ וישבו שם, היה מה שהיה והלך האש."],[21,"ואוליף בבהרת עזה וכו':","ולימד, בסוד, בהרת עזה כשלג, שלש מאה הלכות פסוקות, ולימדו רי\"ו טעמים שבהפסוקים שבשיר השירים. ועיניו של ר' עקיבא היו מורידות מים. וחזר האש והקיפם כבתחילה. כשהגיע להפסוק סמכוני באשישות רפדוני בתפוחים כי חולת אהבה אני, לא היה יכול עוד ר' עקיבא לסבול, ונשא קולו בבכי וגעה כמו שור, ולא היה יכול לדבר מפחד השכינה שהיתה שם."],[22,"אורי ליה וכו':","ולימד אותו כל עמוק, וסודות עליונים, שיש בשיר השירים והשביע אותו שבועה, שלא ישתמש בשום פסוק שבו, בשביל שלא יחריב הקב\"ה את העולם בסבתו, כי אין רצון לפניו, שישתמשו בו הבריות, מרוב קדושה שיש בו. אחר כך, יצא ר' עקיבא, וגעה, ועיניו נובעות מים. ואמר, ווי רבי ווי רבי, שהעולם ישאר יתום ממך, נכנסו אצלו כל שאר החכמים, ושאלו אותו והשיב להם בדברי תורה."],[23,"הוה דחיק ליה וכו':","נעשה צר לו לרבי אליעזר. הרים שתי זרועותיו ושם אותן על לבו, פתח ואמר, ווי עולם, עולם העליון חזר לסלק ולגנוז, כל אור וכל הארה מן עולם התחתון, כמו שהיה מטרם ביאתו להעולם. ווי לכם שתי זרועות, ווי לכם שתי תורות, שתהיו נשכחים ביום הזה מן העולם והזהר מסיים על זה, ואומר שאמר רבי יצחק, כל ימיו של רבי אליעזר, היתה, ההלכה מאירה מפיו כיום שניתנה על הר סיני."],[24,"אמר אורייתא גמרית וכו':","אמר רבי אליעזר, תורה למדתי וחכמה הבנתי ושימוש תלמידי חכמים. עשיתי, שאפילו כל בני העולם יהיו סופרים, לא יספיקו לכתבם. ולא חסרו תלמידי מחכמתי אלא כמכחול בעין, כשיעור הטפה שהעין מוציאה כנגד טפת המכחול שנחנסה בה, ואני לא חסרתי מחכמת רבותי אלא כשיעור מי ששותה בים. ומסיים ע\"ו הזהר, ולא אמר זה, אלא כדי להחזיק טובה לרבותיו יותר מעצמו. כלומר, מה שאמר שהוא החסיר מרבותיו כשותה בים, שהיא שיעור גדול ממכחול בשפופרת, שאמר על תלמידיו. היינו כדי להחזיק טובה לרבותיו יותר מעצמו."],[25,"והוו שאלין מניה בההוא סנדלא דיבום:","והיו שואלים ממנו בדינו של סנדל דיבום אם מקבל טומאה, עד שיצאה נשמתו ואמר טהור."],[25,"ולא הוה תמן ר\"ע וכו':","ולא היה שם רבי עקיבא, בשעת פטירתו. במוצאי שבת מצאו ר' עקיבא שמת, קרע את מלבושיו. וגרד את בשרו, ודם היה יורד ונמשך על זקנו, והיה צועק ובוכה יצא לחוץ ואמר: שמים שמים, אמרו אל השמש והלבנה, אשר האור שהיה מאיר יותר מהם, הנה נחשך."]],[[0,"","וְאָז - וַיַּרְא וַיָּרָץ לִקְרָאתָם. שֶׁתְּשׁוּקַת הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ לְהִתְחַבֵּר בָּהֶם וְחֶדְוָתָהּ לְהִמָּשֵׁךְ אַחֲרֵיהֶם. וַיִּשְׁתַּחוּ אָרְצָה, לְהַתְקִין לָהֶם כִּסֵּא."],[1,"","בֹּא רְאֵה, הַקָּבָּ\"ה עָשָׂה אֶת דָּוִד הַמֶּלֶךְ עַמּוּד אֶחָד מֵהַכִּסֵּא הָעֶלְיוֹן כְּמוֹ הָאָבוֹת. וְאַף עַל גַּב שֶׁהוּא כִּסֵּא אֲלֵיהֶם, אֲבָל בִּזְמַן שֶׁמִּתְחַבֵּר בָּהֶם הוּא עַמּוּד אֶחָד לְהִתְתַּקֵּן בַּכִּסֵּא הָעֶלְיוֹן, וּלְכָךְ נָטַל אֶת הַמַּלְכוּת בְּחֶבְרוֹן דָּוִד הַמֶּלֶךְ שֶׁבַע שָׁנִים לְהִתְחַבֵּר בָּהֶם, וַהֲרֵי נֶאֱמַר."],[2,"","וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. לָמָּה בְּאֵלֹנֵי מַמְרֵא וְלֹא בְמָקוֹם אַחֵר? אֶלָּא מִשּׁוּם שֶׁנָּתַן לוֹ עֵצָה עַל בְּרִית הַמִּילָה שֶׁלּוֹ. בְּשָׁעָה שֶׁאָמַר הַקָּבָּ\"ה לְאַבְרָהָם לְהִמּוֹל, הָלַךְ אַבְרָהָם לְהִמָּלֵךְ עִם חֲבֵרָיו. אָמַר לוֹ עָנֵר: אַתָּה בֶּן תִּשְׁעִים שָׁנָה, וְאַתָּה מֵעִיק לְעַצְמְךְ?"],[3,"","אָמַר לוֹ מַמְרֵא: הֲזָכַרְתָּ אֶת הַיּוֹם שֶׁזָּרְקוּ אוֹתְךְ הַכַּשְׂדִּים לְתוֹךְ כִּבְשַׁן הָאֵשׁ, וְאוֹתוֹ רָעָב שֶׁעָבַר עַל הָעוֹלָם, שֶׁכָּתוּב (בראשית יב) וַיְהִי רָעָב בָּאָרֶץ וַיֵּרֶד אַבְרָם מִצְרָיְמָה, וְאוֹתָם מְלָכִים שֶׁרָדְפוּ אַחֲרֵיהֶם וְהִכִּיתָ אוֹתָם, וְהַקָּבָּ\"ה הִצִּיל אוֹתְךְ מֵהַכֹּל וְלֹא יָכֹל אִישׁ לַעֲשׂוֹת לְךְ רַע? קוּם וַעֲשֵׂה אֶת מִצְוַת רִבּוֹנְךְ! אָמַר לוֹ הַקָּבָּ\"ה: מַמְרֵא, אַתָּה נָתַתָּ לוֹ עֵצָה לְהִמּוֹל, חַיֶּיךְ אֵינִי מִתְגַּלֶּה עָלָיו אֶלָּא בַּפַּלְטֵרִין שֶׁלְּךְ. וְזֶהוּ שֶׁכָּתוּב בְּאֵלֹנֵי מַמְרֵא. (עד כאן התוספתא)."],[4,"","רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה, (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים שֶׁמֶן תּוּרַק שְׁמֶךְ וְגוֹ'. שָׁנוּ רַבּוֹתֵינוּ, נְשָׁמָה זוֹ שֶׁל בֶּן הָאָדָם, בְּשָׁעָה שֶׁעוֹלָה מֵהָאָרֶץ לָרָקִיעַ וְעוֹמֶדֶת בְּאוֹתוֹ זהַר עֶלְיוֹן שֶׁאָמַרְנוּ, הַקָּבָּ\"ה מְבַקֵּר אוֹתָהּ."],[5,"","בֹּא תִשְׁמַע, אָמַר רַבִּי שִׁמְעוֹן בַּר יוֹחַאי, כָּל נִשְׁמַת הַצַּדִּיקִים, כֵּיוָן שֶׁעוֹמֶדֶת בִּמְקוֹם שְׁכִינַת הַכָּבוֹד, שֶׁרְאוּיָה לָשֶׁבֶת, הַקָּבָּ\"ה קוֹרֵא לָאָבוֹת וְאוֹמֵר לָהֶם: לְכוּ וּבַקְּרוּ אֶת פְּלוֹנִי הַצַּדִּיק שֶׁבָּא, וְהַקְדִּימוּ לוֹ שָׁלוֹם מִשְּׁמִי. וְהֵם אוֹמְרִים: רִבּוֹן הָעוֹלָם, לֹא רָאוּי לְאַבָּא לָלֶכֶת לִרְאוֹת אֶת הַבֵּן. הַבֵּן רָאוּי לִרְאוֹת וּלְהֵרָאוֹת וְלִִדְרוֹשׁ אֶת אָבִיו."],[6,"","וְהוּא קוֹרֵא לְיַעֲקֹב וְאוֹמֵר לוֹ: אַתָּה שֶׁהָיָה לְךְ צַעַר בָּנִים, לֵךְ וְקַבֵּל (למדו) פְּנֵי פְלוֹנִי הַצַּדִּיק שֶׁבָּא לְכָאן, וַאֲנִי אֵלֵךְ עִמְּךְ. זֶהוּ שֶׁכָּתוּב (תהלים כד) מְבַקְשֵׁי פָנֶיךְ יַעֲקֹב סֶלָה. לֹא נֶאֱמַר מְבַקֵּשׁ, אֶלָּא מְבַקְשֵׁי. אָמַר רַבִּי חִיָּיא, מֵרֹאשׁ הַפָּסוּק מַשְׁמָע, שֶׁכָּתוּב זֶה דּוֹר דֹּרְשָׁו וְגוֹ'."],[7,"","אָמַר רַבִּי יַעֲקֹב אָמַר רַבִּי חִיָּיא (נ\"א עקיבא), יַעֲקֹב אָבִינוּ הוּא כִּסֵּא הַכָּבוֹד. וְכֵן תָּנָא דְבֵי אֵלִיָּהוּ, יַעֲקֹב אָבִינוּ הוּא כִּסֵּא בִּפְנֵי עַצְמוֹ, שֶׁכַּתוּב (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. בְּרִית כָּרַת הַקָּבָּ\"ה לְיַעֲקֹב לְבַדּוֹ יוֹתֵר מִכָּל אֲבוֹתָיו, שֶׁעָשָׂה לוֹ כִּסֵּא הַכָּבוֹד, פְּרָט מִן הָרִאשׁוֹן."],[8,"","רַבִּי אֱלִיעֶזֶר הָיָה יוֹשֵׁב וְהָיָה עוֹסֵק בַּתּוֹרָה. בָּא אֵלָיו רַבִּי עֲקִיבָא וְאָמַר לוֹ, בַּמֶּה מַר עוֹסֵק? אָמַר לוֹ, בַּפָּסוּק הַזֶּה שֶׁכָּתוּב (שמואל א ב) וְכִסֵּא כָבוֹד יַנְחִלֵם. מַהוּ כִּסֵּא כָבוֹד יַנְחִלֵם? זֶה יַעֲקֹב אָבִינוּ שֶׁעָשָׂה לוֹ כִּסֵּא כָבוֹד לְבַדּוֹ לְקַבֵּל תּוֹרָה בְּעַד נִשְׁמַת הַצַּדִּיק,"],[9,"","וְהַקָּבָּ\"ה הוֹלֵךְ עִמּוֹ בְּכָל רֹאשׁ חֹדֶשׁ וְחֹדֶשׁ, וּכְשֶׁרוֹאָה הַנְּשָׁמָה אֶת כְּבוֹד הָאַסְפַּקְלַרְיָה שֶׁל שְׁכִינַת רִבּוֹנוֹ, מְבָרֶכֶת וּמִשְׁתַּחֲוָה לִפְנֵי הַקָּבָּ\"ה. וְזֶהוּ שֶׁכָּתוּב (תהלים קד) בָּרְכִי נַפְשִׁי אֶת ה'."],[10,"","אָמַר רַבִּי עֲקִיבָא, הַקָּבָּ\"ה עוֹמֵד עָלָיו, וְהַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת: ה' אֱלֹהַי גָּדַלְתָּ מְּאֹד וְגוֹ' כָּל הַפָּרָשָׁה, עַד הַסִּיּוּם שֶׁאוֹמֵר יִתַּמּוּ חַטָּאִים וְגוֹ'. וְעוֹד אָמַר רַבִּי עֲקִיבָא, וְלֹא זוֹ בִּלְבַד, אֶלָּא מְשַׁבַּחַת אוֹתוֹ עַל הַגּוּף שֶׁנִּשְׁאָר בָּעוֹלָם הַזֶּה, וְאוֹמֵר (שם קג) בָּרְכִי נַפְשִׁי אֶת ה' וְכָל קְרָבַי וְגוֹ'."],[11,"","וְהַקָּבָּ\"ה הוֹלֵךְ. מִנַּיִן לָנוּ זֶה? מֵהַפָּסוּק הַזֶּה שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. זֶה יַעֲקֹב. מַה זֶּה מַמְרֵא? מִשּׁוּם שֶׁיָּרַשׁ מָאתַיִם עוֹלָמוֹת מֵעֵדֶן, וְהוּא כִסֵּא. אָמַר רַבִּי יִצְחָק, מַמְרֵא בְּגִימַטְרִיָּא מָאתַיִם שְׁמוֹנִים וְאַחַת הָיָה. מָאתַיִם שֶׁל עֵדֶן, שֶׁכָּתוּב (שיר ח) וּמָאתַיִם לְנֹטְרִים אֶת פִּרְיוֹ, וּשְׁמוֹנִים וְאַחַת שֶׁהוּא כִּסֵּא. וְלָכֵן נִקְרָא וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא. וְעַל שֵׁם זֶה נִקְרָא מַמרֵא."],[12,"","אָמַר רַבִּי יְהוּדָה, מַה זֶּה בְּאֵלֹנֵי? רְצוֹנוֹ לוֹמַר חָזְקוֹ, זֶהוּ שֶׁכָּתוּב אֲבִיר יַעֲקֹב. וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל, זֶהוּ שֶׁכָּתוּב (תהלים טו) ה' מִי יָגוּר בְּאָהֳלֶךְ וְגוֹ'. כְּחֹם הַיּוֹם, שֶׁכָּתוּב (מלאכי ג) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ."],[13,"","אָמַר רַבִּי יוֹחָנָן בֶּן זַכַּאי, בְּאוֹתָהּ שָׁעָה הָלַךְ הַקָּבָּ\"ה, וּמִשּׁוּם שֶׁשּׁוֹמְעִים הָאָבוֹת, אַבְרָהָם יִצְחָק, שֶׁהַקָּבָּ\"ה הוֹלֵךְ אֵלָיו, תּוֹבְעִים מִיַּעֲקֹב לָלֶכֶת עִמָּם וּלְהַקְדִּים לוֹ שָׁלוֹם,"],[14,"","וְהֵם עוֹמְדִים עָלָיו, מִמַּה שֶּׁכָּתוּב וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו. שְׁלֹשָׁה אֲנָשִׁים (שעומדים) אֵלּוּ הָאָבוֹת, אַבְרָהָם יִצְחָק וְיַעֲקֹב, שֶׁעוֹמְדִים עָלָיו וְרָאוּ מַעֲשִׂים טוֹבִים (שעשה) שֶׁעוֹשִׂים. וַיַּרְא וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אַרְצָה, מִשּׁוּם שֶׁרָאָה שְׁכִינַת הַכָּבוֹד עִמָּם. זֶהוּ שֶׁכָּתוּב (שיר א) עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ (אלו הן האבות)."],[15,"","דָּבָר אַחֵר וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא, רַבּוֹתֵינוּ פָּתְחוּ בַּפָּסוּק הַזֶּה בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, בִּשְׁעַת פְּטִירָתוֹ שֶׁל אָדָם הוּא יוֹם הַדִּין הַגָּדוֹל, שֶׁהַנְּשָׁמָה מִתְפָּרֶדֶת מִן הַגּוּף. וְלֹא נִפְטָר אָדָם מִן הָעוֹלָם עַד שֶׁרוֹאֶה אֶת הַשְּׁכִינָה. זֶהוּ שֶׁכָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. וּבָאִים עִם הַשְּׁכִינָה שְׁלֹשָׁה מַלְאֲכֵי הַשָּׁרֵת לְקַבֵּל נִשְׁמָתוֹ שֶׁל צַדִּיק. זֶהוּ שֶׁכָּתוּב וַיֵּרָא אֵלָיו ה' וְגוֹ'. כְּחֹם הַיּוֹם - זֶה יוֹם הַדִּין הַבּוֹעֵר כַּתַּנּוּר לְהַפְרִיד אֶת הַנְּשָׁמָה מִן הַגּוּף."],[16,"","וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים, הַמְבַקְּרִים מַעֲשָׂיו מַה שֶּׁעָשָׂה, וְהוּא מוֹדֶה עֲלֵיהֶם בְּפִיו. וְכֵיוָן שֶׁהַנְּשָׁמָה רוֹאָה כָּךְ, יוֹצֵאת מִן הַגּוּף עַד פֶּתַח בֵּית הַבְּלִיעָה, וְעוֹמֶדֶת שָׁם עַד שֶׁמִּתְוַדָּה כָּל מַה שֶּׁעָשָׂה הַגּוּף עִמָּהּ בָּעוֹלָם הַזֶּה. וְאָז נִשְׁמַת הַצַּדִּיק הִיא שְׂמֵחָה בְּמַעֲשֶׂיהָ וּשְׂמֵחָה עַל פִּקְדוֹנָהּ. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יִצְחָק, נִשְׁמָתוֹ שֶׁל צַדִּיק מִתְאַוָּה אֵימָתַי תֵּצֵא מִן הָעוֹלָם הַזֶּה שֶׁהוּא הֶבֶל כְּדֵי לְהִתְעַנֵּג בָּעוֹלָם הַבָּא."],[17,"","שָׁנוּ רַבּוֹתֵינוּ, כְּשֶׁחָלָה רַבִּי אֱלִיעֶזֶר הַגָּדוֹל, אוֹתוֹ יוֹם עֶרֶב שַׁבָּת הָיָה, וְהוֹשִׁיב לִימִינוֹ אֶת הוֹרְקְנוּס בְּנוֹ, וְהָיָה מְגַלֶּה לוֹ עֲמֻקּוֹת וְנִסְתָּרוֹת, וְהוּא לֹא הָיָה מְקַבֵּל דָּבָר בְּדַעְתּוֹ שֶׁחָשַׁב שֶׁמְּטֹרָף בְּדַעְתּוֹ הָיָה. כֵּיוָן שֶׁרָאָה שֶׁדַּעַת אָבִיו מִתְיַשֶּׁבֶת עָלָיו, קִבֵּל מִמֶּנּוּ מֵאָה שְׁמוֹנִים וְתֵשַׁע סוֹדוֹת עֶלְיוֹנִים."],[18,"","כְּשֶׁהִגִּיעַ לְאַבְנֵי שַׁיִשׁ שֶׁמִּתְעָרְבִים בַּמַּיִם הָעֶלְיוֹנִים, בָּכָה רַבִּי אֱלִיעֶזֶר וּפָסַק לוֹמַר. אָמַר, עֲמֹד שָׁם בְּנִי. אָמַר לוֹ, אַבָּא, לָמָּה? אָמַר לוֹ, אֲנִי רוֹאֶה שֶׁאֲנִי מְמַהֵר לַחֲלֹף מִן הָעוֹלָם. אָמַר לוֹ, לֵךְ וֶאֱמֹר לְאִמְּךְ שֶׁתַּעֲלֶה אֶת הַתְּפִלִּין שֶׁלִּי לְמָקוֹם עֶלְיוֹן, וְאַחַר שֶׁאֶסְתַּלֵּק מִן הָעוֹלָם, וְאָבֹא לְכָאן כְּדֵי לִרְאוֹת אוֹתָם. לֹא תִבְכּוּ, שֶׁהֵם קְרוֹבִים עֶלְיוֹנִים וְלֹא תַחְתּוֹנִים, וְדַעַת בְּנֵי אָדָם לֹא מַשִּׂיגָה אוֹתָם."],[19,"","עֵד שֶׁהָיוּ יוֹשְׁבִים, נִכְנְסוּ חַכְמֵי הַדּוֹר לְבַקֵּר אוֹתָם, וְקִלֵּל אוֹתָם עַל שֶׁלֹּא בָאוּ לְשַׁמֵּשׁ אוֹתוֹ, שֶׁשָּׁנִינוּ, גְּדוֹלָה שִׁמּוּשָׁהּ יוֹתֵר מִלִּמּוּדָהּ. עַד שֶׁבָּא רַבִּי עֲקִיבָא, אָמַר לוֹ, עֲקִיבָא, עֲקִיבָא, לָמָּה לֹא בָאתָ לְשַׁמֵּשׁ אוֹתִי (שהרי באה העת להצרף)? אָמַר לוֹ, רַבִּי, לֹא הָיָה לִי פְּנַאי. רָתַח וְאָמַר, אֶתְמַהּ עָלֶיךְ אִם תָּמוּת מִיתַת עַצְמְךְ. קִלְּלוֹ שֶׁמִּיתָתוֹ תִּהְיֶה קָשָׁה מִכֻּלָּם."],[20,"","בָּכָה רַבִּי עֲקִיבָא וְאָמַר לוֹ, רַבִּי, תְּלַמֵּד אוֹתִי תּוֹרָה. פָּתַח פִּיו רַבִּי אֱלִיעֶזֶר בְּמַעֲשֵׂה מֶרְכָּבָה. בָּאָה אֵשׁ וְהִקִּיפָה אֶת שְׁנֵיהֶם. אָמְרוּ חֲכָמִים, נִשְׁמָע מִזֶּה שֶׁאֵין אָנוּ רְאוּיִים וּכְדָאִים לְכָךְ. יָצְאוּ לַפֶּתַח הַחִיצוֹן וְיָשְׁבוּ שָׁם. הָיָה מַה שֶּׁהָיָה, וְהָאֵשׁ הָלְכָה."],[21,"","וְלִמֵּד בְּבַהֶרֶת עַזָּה שְׁלֹשׁ מֵאוֹת הֲלָכוֹת פְּסוּקוֹת, וְלִמֵּד אוֹתוֹ מָאתַיִם וְשִׁשָּׁה עָשָּׂר טְעָמִים שֶׁל פְּסוּקֵי שִׁיר הַשִּׁירִים, וְהָיוּ עֵינֵי רַבִּי עֲקִיבָא זוֹלְגוֹת דְּמָעוֹת, וְחָזְרָה הָאֵשׁ כְּבַתְּחִלָּה. כְּשֶׁהִגִּיעַ לְפָסוּק (שיר ב) סַמְּכוּנִי בָּאֲשִׁישׁוֹת רַפְּדוּנִי בַּתַּפּוּחִים כִּי חוֹלַת אַהֲבָה אָנִי, לֹא יָכֹל רַבִּי עֲקִיבָא לִסְבֹּל, וְהֵרִים קוֹלוֹ בִּבְכִיָּה. וְהֵרִים קוֹלוֹ וְלֹא הָיָה מְדַבֵּר מִיִּרְאַת הַשְּׁכִינָה שֶׁהָיְתָה שָׁם."],[22,"","הוֹרָה לוֹ כָּל עֲמֻקּוֹת וְסוֹדוֹת עֶלְיוֹנִים שֶׁהָיוּ בְּשִׁיר הַשִּׁירִים, וְהִשְׁבִּיעוֹ שְׁבוּעָה שֶׁלֹּא יִשְׁתַּמֵּשׁ בְּשׁוּם פָּסוּק מִמֶּנּוּ, כְּדֵי שֶׁהַקָּבָּ\"ה לֹא יַחֲרִיב אֶת הָעוֹלָם בִּגְלָלוֹ, וְלֹא רוֹצֶה לְפָנָיו שֶׁהַבְּרִיּוֹת יִשְׁתַּמְּשׁוּ בוֹ מֵרֹב הַקְּדֻשָּׁה שֶׁיֵּשׁ בּוֹ. אַחַר יָצָא רַבִּי עֲקִיבָא וּבָכָה, וְנָבְעוּ עֵינָיו מַיִם, וְהָיָה אוֹמֵר, וַי רַבִּי! וַי רַבִּי! שֶׁהָעוֹלָם נִשְׁאָר יָתוֹם מִמְּךְ. נִכְנְסוּ אֵלָיו כָּל שְׁאָר הַחֲכָמִים, וְשָׁאֲלוּ אוֹתוֹ, וְהֵשִׁיב לָהֶם."],[23,"","הָיְתָה דְחוּקָה לוֹ (השעה) לְרַבִּי אֱלִיעֶזֶר. הוֹצִיא שְׁתֵּי זְרוֹעוֹתָיו וְשָׂם אוֹתָם עַל לִבּוֹ. פָּתַח וְאָמַר, אוֹי הָעוֹלָם, הָעוֹלָם הָעֶלְיוֹן חוֹזֵר לְהִתְכַּנֵּס וּלְהִגָּנֵז מִן הַתַּחְתּוֹן כָּל אוֹר וּמָאוֹר. אוֹי לָכֶם שְׁתֵּי זְרוֹעוֹת, אוֹי לָכֶם שְׁתֵּי תוֹרוֹת שֶׁיִּהְיוּ נִשְׁכָּחִים הַיּוֹם הַזֶּה מִן הָעוֹלָם. שֶׁאָמַר רַבִּי יִצְחָק, כָּל יְמֵי רַבִּי אֱלִיעֶזֶר הָיְתָה הַשְּׁמוּעָה מְאִירָה מִפִּיו כַּיּוֹם שֶׁנִּתְּנָה בְּהַר סִינַי."],[24,"","אָמַר, תּוֹרָה (למדתי וגמרא) הֵבַנְתִּי וְחָכְמָה לָמַדְתִּי וְשִׁמּוּשׁ עָשִׂיתִי, שֶׁאִלּוּ יִהְיוּ כָּל בְּנֵי אֱנוֹשׁ שֶׁל הָעוֹלָם סוֹפְרִים, לֹא יוּכְלוּ לִכְתֹּב, וְלֹא חָסְרוּ תַלְמִידַי מֵחָכְמָתִי אֶלָּא כְּמִכְחוֹל בְּעַיִן, וַאֲנִי מֵרַבּוֹתַי אֶלָּא כְּמִי שֶׁשּׁוֹתֶה בַּיָּם. וְלֹא הָיָה אֶלָּא לְהַחֲזִיק טוֹבָה לְרַבּוֹתָיו יוֹתֵר מִמֶּנּוּ."],[25,"","וְהָיוּ שׁוֹאֲלִים מִמֶּנּוּ בְּאוֹתוֹ סַנְדָּל שֶׁל יִבּוּם, עַד שֶׁיָּצְאָה נִשְׁמָתוֹ וְאָמַר טָהוֹר. וְלֹא הָיָה שָׁם רַבִּי עֲקִיבָא. כְּשֶׁיָּצְאָה הַשַּׁבָּת, מָצָא אוֹתוֹ רַבִּי עֲקִיבָא שֶׁמֵּת. קָרַע בִּגְדּוֹ וְשָׂרַט כָּל בְּשָׂרוֹ, וְדָם יָרַד וְנִמְשַׁךְ עַל זְקָנוֹ. הָיָה צוֹוֵחַ וּבוֹכֶה. יָצָא הַחוּצָה וְאָמַר: שָׁמַיִם שָׁמַיִם, אִמְרוּ לַשֶּׁמֶשׁ וְלַלְּבָנָה, שֶׁהָאוֹר שֶׁהָיָה מֵאִיר יוֹתֵר מֵהֶם הֲרֵי נֶחְשַׁךְ."]]],[["אָמַר רַבִּי יְהוּדָה בְּשָׁעָה שֶׁנִּשְׁמַת הַצַּדִּיק רוֹצָּה לָצֵּאת שְׂמֵחָה וְהַצַּדִּיק בָּטוּחַ בְּמִיתָתוֹ כְּדֵי לְקַבֵּל שְׂכָרוֹ, הֲדָא הוּא דִכְתִיב, וַיַּרְא וַיָּרָץ לִקְרָאתָם. בְּשִׂמְחָה, לְקַבֵּל פְּנֵיהֶם. מֵאֵי זֶה מָקוֹם, מִפֶּתַח הָאֹהֶל כְּדְקָא אֲמָרָן. וַיִּשְׁתַּחוּ אָרְצָּה לְגַבֵּי שְׁכִינָה.","רַבִּי יוֹחָנָן פָּתַח וְאָמַר, (שיר השירים ב׳:י״ז) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים סוֹב דְּמֵה לְךָ דּוֹדִי לִצְּבִי אוֹ לְעוֹפֶר הָאַיָּלִים. עַד שֶׁיָּפוּחַ הַיּוֹם וְגו'. זוֹ אַזְהָרָה לָאָדָם בְּעוֹדוֹ בָּעוֹלָם הַזְּה שֶׁהוּא כְּהֶרֶף עַיִן. תָּא חֲזֵי, מַה כְּתִיב, (קהלת ו׳:ו׳) וְאִלּוּ חָיָה אֶלֶף שָׁנִים פַּעֲמַיִם וגו'. בְּיוֹם הַמִּיתָה כָּל מַה שֶּׁהָיָה נְחְשַׁב כְּיוֹם אֶחָד אֶצְּלוֹ.","אָמַר רַבִּי שִׁמְעוֹן נִשְׁמָתוֹ שֶׁל אָדָם מַתְרָה בּוֹ וְאוֹמֶרֶת עַד שֶׁיָּפוּחַ הַיּוֹם (ונסו הצללים) וְיִדְמֶה בְּעֵינֶיךָ כְּהֶרֶף עַיִן בְּעוֹדְךָ בָּעוֹלָם הַזְּה. וְנָסוּ הַצְּלָלִים הֲדָא הוּא דִכְתִיב, (איוב ח׳:ט׳) כִּי צֵּל יָמֵינוּ עֲלֵי אָרֶץ. בְּבַקָּשָׁה מִמְּךָ סוֹב דְּמֵה לְךָ דּוֹדִי לִצְּבִי וְגו'.","דָּבָר אַחֵר עַד שֶׁיָּפוּחַ הַיּוֹם וְגו'. אָמַר רַבִּי שִׁמְעוֹן בֶּן פַּזִי, זוֹ אַזְהָרָה לָאָדָּם בְּעוֹדוֹ בָּעוֹלָם הַזֶּה שֶׁהוּא כְּהֶרֶף עַיִן. מַה הַצְּבִי קַל בְּרַגְלָיו אַף אַתָּה הֱיִה קַל כַּצְּבִי אוֹ כְּעוֹפֶר הָאַיָּלִים לַעֲשׂוֹת רְצּוֹן בּוֹרְאֲךָ כְּדֵי שֶׁתִּנְחַל הָעוֹלָם הַבָּא שֶׁהוּא הָרֵי בְּשָׂמִים הַנִּקְרָא הַר יְיָ, הַר הַתַּעֲנוּג הָהָר הַטוֹב (עד כאן המדרש הנעלם).","\u0003סתרי תורה\u0004 הורמנותא דמלכא אתחזי בתלת גוונין גוון חד חיזו דאתחזי לעינא מרחיק ועינא לא יכיל לקיימא בברירו דחזי בגין דאיהו מרחוק עד דנטיל עינא חיזו זעיר בקמיטו דיליה ועל דא כתיב (ירמיהו ל״א:ג׳) מרחוק יי' נראה לי,","גוון תניין חיזו האי (נ\"א דחד) עינא בסתימו דיליה דהאי גוון לא אתחזי לעינא בר בסתימו זעיר דנקיט ולא קיימא בברירו סתים עינא ופתח זעיר ונקיט ההוא חיזו וגוון דא (נ\"א גוון ודא) אצטריך לפתרונא לקיימא על מה דנקיט עינא ועל דא כתיב (שם א) מה אתה רואה,","גוון תליתאה הוא זהר אספקלריאה דלא אתחזי ביה כלל בר בגלוגולא דעינא כד איהו סתים בסתימו ומגלגלין ליה בגלגולא ואתחזאי בהאי גלגולא אספקלריאה דנהרא ולא יכיל לקיימא בההוא גוון בר דחזי זוהר מנהרא בסתימו דעינא","ועל דא כתיב (יחזקאל ל״ז:א׳) היתה עלי יד יי' (שם לג) (נ\"א ויד יי' היתה אלי) ויד יי' עלי חזקה וכלהו מתפרשן מנביאי קשוט בר משה מהימנא עלאה דזכה לאסתכלא לעילא במה דלא אתחזי כלל, עליה כתיב (במדבר י״ב:ז׳) לא כן עבדי משה וגו':","וירא אליו אתחזי ואתגלי ליה שכינתא גו אינון דרגין דאתחברו בסטרוי מיכא\"ל לסטר ימינא גבריא\"ל לסטר שמאלא, רפא\"ל לקמא, אוריא\"ל לאחורא, ועל דא אתגליא עליה שכינתא בהני אלוני בוסמין (נ\"א צולמין) דעלמא בגין לאחזאה קמייהו ברית (ד\"א ל\"ג קדמאה רשימו) קדישא דהוה בכל עלמא ברזא דמהימנותא,","והוא יושב פתח האהל, מאן דפתח האהל, דא אתר דאקרי ברית רזא דמהימנותא, כחום היום, דא רזא דאתדבק ביה אברהם תוקפא דסטרא דימינא דרגא דיליה,","פתח האהל רזא דתרעא דצדק פתחא דמהימנותא דכדין עאל ביה אברהם בההוא רשימא קדישא, כחום היום דא צדי\"ק דרגא דחבורא חדא דעאל ביה מאן דאתגזר ואתרשים ביה רשימא קדישא דהא אתעבר מערלה ועאל בקיומא דתרין דרגין אלין דאינון רזא דמהימנותא:","והנה שלשה אנשים וגו', אלין תלת מלאכין שליחן דמתלבשן באוירא ונחתי להאי עלמא (ואתחזון) (לד ע\"א) בחיזו דבר נש ותלת הוו כגוונא דלעילא בגין דקשת לא אתחזי אלא בגוונין תלתא חוור וסומק וירוק והכי הוא ודאי","ואלין אינון שלשה אנשים תלתא גוונין גוון חוור גוון סומק גוון ירוק, גוון חוור דא מיכאל בגין דאיהו סטרא דימינא, גוון סומק דא גבריאל סטרא דשמאלא, גוון ירוק דא רפאל והני אינון תלת גוונין דקשת דקשת לא אתחזי אלא עמהון ובג\"כ וירא אליו גלוי שכינה בתלת גוונין אלין","וכלהו אצטריכו חד לאסיא מן המילה ודא רפא\"ל מאריה דאסוון, וחד לבשרא לשרה על ברא ודא איהו מיכאל בגין דאיהו אתמנא לימינא וכל טבין וברכאן בידיה אתמסרן מסטרא דימינא","וחד להפכא לסדום ודא איהו גבריאל דאיהו לשמאלא, ואיהו ממנא על כל דינין דעלמא מסטרא (דדיא) דשמאלא למידן ולמעבד על ידא דמלאך המות דאיהו מארי דקטולא דבי מלכא","וכלהו עבדו שליחתהון וכל חד וחד כדקא חזי ליה, מלאך גבריא\"ל בשליחותא לנשמתא קדישא ומלאך המות בשליחותיה לנפשא דיצר הרע, ועם כל דא נשמתא קדישא לא נפיק עד דחזי שכינתא","כד חמא לון מתחברן כחדא כדין חמא שכינתא (כגוונא דא) בגוונא וסגיד דכתיב (בראשית ל״ג:ג׳) וישתחו ארצה כגוונא דיעקב שנאמר (שם מז) וישתחו ישראל על ראש המטה לשכינה","ולגבי שכינתא אמר בשמא אדנ\"י ולגבי צדיק אדו\"ן דהא כדין אקרי אדון כל הארץ כד אתנהרא מצדיק ואתנהרא בגוונהא דהא בגין (דא איהו כגוונא דא כדין) דא אשתלים לעילא","מהכא דחיזו דלתתא משיך משיכו מלעילא דהא גוונין אלין משכין משיכא מלעילא מאינון מקורין עלאין אדנ\"י משכא מלעילא באלין תלת גוונין דאתלבש בהו ובהו נטלא כל מה דנטלי מלעילא","ובגין דאינון חבורא דילה וסמכין דילה בכלא אתמר שמא אדנ\"י דהא שמא דא אתגלי ליה כליל ברזין עלאין אתגלי ליה באתגליא מה דלא הוות מקדמת דנא דלא הוה גזיר ועד דאתגזר לא בעא קודשא בריך הוא לאפקא מניה זרעא קדישא כיון דאתגזר מיד נפק מניה זרעא קדישא"],[[0,"אמר ר' יהודה וכו':","אר\"י בשעה שנשמת הצדיק רוצה לצאת מהגוף, היא שמחה מפני שהצדיק בטוח עם מיתתו, כי יקבל את שכרו. וזהו שכתוב וירא וירץ לקראתם, היינו כנגד ג' המלאכים שבאו עם השכינה לקבל נשמתו (כנ\"ל אות ל') בשמחה לקבל פניהם של המלאכים. מאי זה מקום מקבל פניהם, מפתח האהל כמו שאמרנו (לעיל אות כ\"ז). וישתחו ארצה. אל השכינה כלומר, הנשמה השתחוה אל השכינה שבאה אצלה. והשכינה נקראת ארץ, כנודע."],[4,"הורמנותא דמלכא אתחזי וכו':","הרשות ורצון של המלך, דהיינו השכינה, נראה בשלשה גוונין. שהם לבן אדום ירוק, והם ג' גוונין שבעין. גוון אחד, הוא מראה הנראה לעין מרחוק, והעין אינה יכולה לעמוד בבירור במה שרואה, משום שהוא מרחוק. עד שהעין מקבל ראיה מועטת על ידי קמיצה שלה. כמ\"ש להלן. וע\"כ כתוב, מרחוק ה' נראה לי. וה\"ס הארת קו האמצעי ע\"י מסך דחירק. שאין פתיחה להאורות זולתו (כנ\"ל ב\"א דף ט\"ז ד\"ה וזה)."],[5,"גוון תניין וכו':","גוון השני, הוא, ראיית העין בהסתימה שלה. כי גוון זה אינו נראה לעין זולת ע\"י מעט סתימה שמקבלת, ואינה ראיה ברורה. כי דרך ראיתו היא, שסותם העין, ואח\"כ פותחה מעט, ואז מקבלת מראה הזאת. ומראה זו צריכה פתרון, כדי לעמוד על מה שקבלה העין, כי הוא אינה ברורה כנ\"ל. וע\"כ כתוב, מה אתה רואה. וה\"ס הארת קו שמאל מסוד נקודת השורק, שהאורות אז בסתימה מטעם חסרון חסדים (כנ\"ל ב\"א דף ט\"ו ד\"ה בעת)."],[6,"גוון תליתאה וכו':","גוון השלישי. הוא זהר אספקלריאה, שאינו נראה בה כלל, לבד מבעת גלגול העין, כי כשהעין נסתמת עם סתימה, ומגלגלים אותה בגלגול, נראה בגלגול הזה האספקלריאה דנהרא. וה\"ס הארת קו ימין מסוד נקודת החולם. אבל אי אפשר לה להעין לעמוד בגוון שלישי הזה, זולת בראית הארת הזהר על ידי הסתימה שבעין, שהוא גוון הב', בהתכללות גוון הא'."],[7,"ועל דא כתיב וכו':","ועל כן כתוב, היתה עלי יד ה'. ויד ה' עלי חזקה. דהיינו משום שהראיה הוא בסתימת העין, שהוא גבורה ותוקף. וכולם מושגים לנביאי האמת, דהיינו ב' גוונים הראשונים. מלבד משה, נאמן העליון, שזכה להסתכל למעלה, במה שלא נראה הזהר בו כלל. דהיינו בגוון הג', שהוא אספקלריאה המאירה, כמבואר."],[7,"","ביאור הדברים. כי הוקשה לו להסתרי תורה, שכתוב בפרשת וארא, וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי הוי\"ה לא נודעתי להם. והרי כאן נאמר באברהם, וירא אליו הוי\"ה. הרי שנגלה בשם הוי\"ה גם לאבות. ובכדי לישב את זה, האריך לבאר היטב ההפרש בין מראה הנבואה של האבות, ובין מראה הנבואה של משה. ומוכיח, שאע\"פ שכתוב כאן וירא אליו הוי\"ה, עכ\"ז ה\"ס השכינה, הנקראת אספקלריאה שאינה מאירה. כמו שמסיים באות מ\"ט."],[7,"","וכבר ידעת שאין המוחין נמשכים זולת בסוד ג' קוין הנמשכים מג' נקודות, חולם שורק חירק. שנקודת החולם ה\"ס חסדים מכוסים וה\"ס מ\"י דאלקים. ונקודת השורק. ה\"ס אתוון אלה דאלהים, והוא אור סתום, להיותו אור חכמה בחסרון חסדים, שאין אור החכמה מאירה בלי חסדים, וע\"כ הוא סתום. עד שבא נקודת החירק שה\"ס קומת ו\"ק, ומכריע ביניהם שבכחו נכללים ב' הקוין זה בזה. כנ\"ל (דף י' ד\"ה ובגין) גם ה\"ס או\"א וישסו\"ת וז\"א. שחולם ה\"ס או\"א. ושורק ה\"ס ישסו\"ת. וחירק ה\"ס ז\"א (כנ\"ל ב\"א דף רצ\"ג ד\"ה ר' אבא)."],[7,"","וזה אמרו \u0003הורמנותא דמלכא\u0004 דהיינו השכינה שה\"ס רצון המלך, \u0003אתחזי בתלת גוונין,\u0004 היא מתגלית להנביאים בג' גוונים. שהם מכונים ג' גווני עינא. והוא מתחיל מתתא לעילא. דהיינו מקו אמצעי, שה\"ס נקודת החירק ואמר \u0003גוון חד. חיזו דאתחזי לעינא מרחיק,\u0004 שפירושו, \u0003ועינא לא יכיל לקיימא בברירו דחזי בגין דאיהו מרחוק.\u0004 גוון אחד. הוא מראה הנראה להעין מרחוק. שפירושו, שהעין אינה יכולה לעמוד בבירור במה שרואה משום שהיא מרחוק. פירוש. כי גוון זה דקו האמצעי ה\"ס קומת החסדים היוצאת על המסך דז\"א שה\"ס בחי\"א, שקומה זו ה\"ס קומת ו\"ק דהיינו חסדים בלי חכמה, (כנ\"ל בראשית א' דף מ\"ח ד\"ה ונמשכה) וראיה פירושה חכמה, וז\"ש \u0003ועינא לא יכיל לקיימא בברירו דחזי\u0004 שאינה יכולה לראות בבירור, \u0003בגין דאיהו מרחוק,\u0004 משום שגוון זה רחוק מחכמה. והחכמה ה\"ס הראיה כנ\"ל וז\"ש \u0003עד דנטיל עינא חיזו זעיר בקמיטו דיליה\u0004 כלומר, עד שגוון זה של העין, נכלל בקו השמאל, שה\"ס הארת נקודת השורק, ושם מקבלת העין ראיה מועטת, בכח הקמיצה שלה כלומר משום שקו השמאל מקומץ מחסדים ואינו יכול להאיר החכמה שלו בלי חסדים לפיכך בכח החסדים שהסתימה דקו שמאל מקבלת מקו אמצעי, כדי להפתח מסתימתו, בשיעור הזה הוא מאיר החכמה שלו אל קו האמצעי, ונכנס בו החכמה אע\"פ שתכונתו הוא בחינת ו\"ק ורחוק מחכמה. ונמצא שגוון זה דקו אמצעי \u0003נטיל חיזו זעיר בקמיטו דיליה\u0004 שנוטל ראיה מועטת בהקמיצה וסתימה שלו, ומה שאומר ראיה מועטת. להורות שהג\"ר דחכמה אינם מאירים בה, אלא רק ו\"ק דחכמה (כנ\"ל ב*א דף רס\"ג ד\"ה לבתר ע\"ש). והו\"ק כלפי הג\"ר נבחן כראיה מועטת. וז\"ש \u0003מרחוק ה' נראה לי.\u0004 שהכתוב הזה קאי על קו האמצעי שמבחינת עצמו הוא רחוק מחכמה, להיותו בחינת ו\"ק. אבל מבחינת התכללותו בקו השמאל מקבל \u0003חיזו זעיר,\u0004 ואז נאמר מרחוק ה' נראה לי כי הראיה מקובלת דוקא בקו האמצעי שהוא רחוק ולולא קו האמצעי לא היה נגלה הראיה כלל. (כנ\"ל ב\"א דף רס\"ד ד\"ה באצבען ע\"ש)."],[7,"","וזה אמרו. \u0003גוון תניין. חיזו דהאי עינא בסתימו דיליה,\u0004 גוון ב', הראיה, דהיינו אור החכמה, שבגוון זה, הוא בסתימה שלו, כי הוא קו השמאל והארת השורק, שמבחינת עצמו הוא סתום ואינו מאיר, מפאת חוסר חסדים, וע\"כ גוון החכמה שבו הוא סתום. \u0003דהאי גוון לא אתחזי לעינא, בר בכתימו זעיר דנקיט ולא קיימא בברירו\u0004 וגוון זה, דהיינו החכמה, אינה נראית בהעין, זולת במעט הסתימה שמקבל מגוון הא' שהוא קו אמצעי, ואינו מאיר ברור. כלומר, כיון שמחוסר חסדים הוא, ואינו יכול להאיר זולת בהתכללות קו האמצעי, שהוא בחינת ו\"ק כנ\"ל כדי לקבל ממנו חסדים, נמצא בהכרח, שאינו יכול להאיר זולת \u0003בסתימו זעיר דנקיט\u0004 מגוון הא'. ומשום זה \u0003ולא קיימא בברירו,\u0004 שאינו מאיר ברור, דהיינו בג\"ר דחכמה, אלא בו\"ק דחכמה, שאינה ברורה כל כך כמו הג\"ר דחכמה. ודרך הארתו של גוון זה שהוא הארת השורק וקו שמאל, הוא \u0003סתים עינא,\u0004 תחילה ממשיכין בה הארת החכמה, בלי חסדים, שהעין נסתם ממנה ואינה מאירה כלום, (כנ\"ל דף ט\"ז ד\"ה וכבר מ\"ש) ואחר כך, \u0003ופתח זעיר,\u0004 דהיינו שעל ידי התכללות בגוון הא', הוא פותח אותה להאיר מעט. כלומר להאיר בו\"ק דחכמה ולא בג\"ר, כנ\"ל. ואז, \u0003ונקיט ההוא חיזו,\u0004 ומקבלת שיעור הראיה הזו, דהיינו ו\"ק דחכמה."],[7,"","וז\"ש \u0003וגוון דא אצטריך לפתרונא,\u0004 וגוון ב' הזה הוא בחינת חלום. ונצרך לפתרון, כלומר, גוון זה הוא סתום מבחינת עצמו, מפאת חסרון חסדים כנ\"ל. וע\"כ נקרא הארתו אור אחורים. שה\"ס הארת החלומות הכתובים במקרא. והסוד הוא, שהוא מחכה על פתרון, שפירושו, להארת אור החסדים, שאז ע\"י התלבשות בחסדים נמשך אור החלום להתקיים בהקיץ. וז\"ש \u0003וגוון דא אצטריך לפתרונא, לקיימא על מה דנקיט עינא.\u0004 שע\"י הפתרון, שפירושו התלבשות באור החסדים מגוון הא', נמצא מתקיים הארת החכמה שקבל העין בסוד הארת השורק וקו שמאל. ואם אינו משיג אור החסדים מגוון הא', אין אור החלום הזה מתקיים כלל, ואינו נודע, ודומה כמו שלא היה כלל. ומטעם הזה מכונה הארת הגוון הב' הזה בשם חלום. להיותו בלתי מתקיים כלל בלי פתרון. \u0003ועל דא כתיב מה אתה רואה\u0004 שהוא מטעם היותו בלתי מושג מטרם הפתרון, כמבואר."],[7,"","וזה אמרו. \u0003גוון תליתאה, הוא זהר אספקלריא, דלא אתחזי ביה כלל, בר בגלגולא דעינא.\u0004 גוון הג' שה\"ס הארת נקודת החולם, שהוא חסדים מכוסים, דהיינו בחינת האור של חג\"ת דז\"א, הנקרא אספקלריאה המאירה, הרי אור זה אינו נמצא כלל בהעין זולת בשעת \u0003גלגולא דעינא,\u0004 דהיינו \u0003כד איהו סתים בסתימו,\u0004 בעת שהעין סתים ואינו מאיר דהיינו בשעה שרק הארת השורק מאיר בה בלבדו, שאז \u0003ומגלגלין ליה בגלגולא,\u0004 על תלת נקודין חולם שורק חירק, \u0003ואתחזאי בהאי גלגולא\u0004 ונראה בגלגול הזה גם הארת החולם, שהיא בחינת האור של \u0003אספקלריאה דנהרא,\u0004 דהיינו חסדים מכוסים מחכמה. אבל, \u0003ולא יכיל לקיימא בההוא גוון,\u0004 אבל העין, אינה יכולה להשאר באותו הגוון של נקודת החולם, כי לחסדים מגולים בחכמה היא צריכה, \u0003בר, דחזי זהר מנהרא בסתימו דעינא\u0004 אלא, שהעין רואה הזהר המאיר בתוך הסתימה של העין, דהיינו רק שמלבישה את הארת החכמה, אשר בגוון הב', שהוא הארת נקודת השורק, בתוך החסדים שהשיגה. ואז מאיר בה בעיקר אור החכמה. ולפיכך, היא נבחנת לאספקלריאה שאינה מאירה, כי הארת נקודת החולם אינה נשארת בה. \u0003ועל דא כתיב היתה עלי יד ה' וגו'\u0004 כי מתוך שמקבלת בעיקר מב' גוונין הראשונים שהם הארת חירק ושורק, שהם מצומצמים כנ\"ל, ע\"כ נקראת הנוקבא יד ה'. שהוא מלשון כח וגבורה. וכן ויד ה' עלי חזקה. וזהו שמסיים \u0003וכלהו מתפרשן מנביאי קשוט.\u0004 שב' גוונין הראשונים מאירים בעיקר במראה אל נביאי האמת. דהיינו רק בחינת אספקלריאה שאינה מאירה. \u0003בר משה מהימנא עלאה דזכה לאסתכלא לעילא במה דלא אתחזי כלל.\u0004 חוץ ממשה נאמן העליון שהוא זכה להסתכל למעלה בבחינת הארת החולם, במה שאינה נראית כלל. דהיינו בחינת אספקלריאה המאירה כנ\"ל."],[8,"וירא אליו וכו':","וירא אליו, פירושו, שהשכינה נראית ונגלית אליו, תוך אלו המדרגות המתחברים בבחינותיה, דהיינו מיכאל לצד ימין, גבריאל לצד שמאל רפאל לצד הפנים, אוריאל לאחור."],[8,"","ביאור הדברים. כי אחר שביאר לנו, ההפרש מנבואת משה לנבואת האבות, הוא מוכיח אשר הכתוב \u0003וירא אליו הוי\"ה,\u0004 פירושו גילוי השכינה בסוד ג' הגוונין דגלגולא דעינא. ומה שכתוב כאן השם הויה, היורה על אספקלריאה המאירה, היינו רק בדרך השפעה אל השכינה בעת הגלגול, כי אז מתראה אספקלריאה המאירה, שה\"ס הויה, בעת המשכת קו ימין, שה\"ס הארת החולם, (כנ\"ל בדיבור הסמוך) אמנם אחר הגלגול, היא נשארת בעיקר בסוד ב' הקוין שמאל ואמצע, כנ\"ל. כי ע\"כ היא נקראת אספקלריאה שאינה מאירה. וז\"ש \u0003וירא אליו, אתחזי ואתגלי ליה שכינתא,\u0004 דהיינו הנוקבא. ומ\"ש \u0003הוי\"ה,\u0004 הוא בבחינת השפעה להנוקבא בעת הגלגול, כמבואר."],[8,"","וכבר ידעת, שב' כסאות הם באצילות. כסא העליון ה\"ס בינה, שנעשית \u0003כסא\u0004 לחכמה. שפירושו, שאין החכמה מגולית אלא על ידיה, כסא התחתון ה\"ס הנוקבא, שפירושו, שאין המוחין דז\"א מתגלים אלא על ידי הנוקבא. כנ\"ל בדיבור הסמוך, כי ע\"כ היא נקרא \u0003עינא,\u0004 ע\"ש. וארבעה הרגלין שכסא העליון עומד עליהם, הם חג\"ת דז\"א, והנוקבא. אשר חג\"ת דז\"א ה\"ס ג' הקוין, הנמשכים בסוד ג' הנקודות חולם שורק חירק המאירים בהבינה, והנוקבא ה\"ס רגל רביעי המקבלת מהם, והיא עומדת אז מאחורי חג\"ת דז\"א. (כנ\"ל דף ה' ד\"ה ואע\"ג ע\"ש) ואח\"כ כשהנוקבא חוזרת לבחינת המוחין דפב\"פ, ונעשית כסא בפני עצמה אל ז\"א (כמ\"ש שם) נמצאים הד' רגלין שלה, בסוד ד' המלאכים מיכאל גבריאל רפאל אוריאל. אשר מיכאל גבריאל רפאל נמשכים מג' הקוין חג\"ת, שהם ג' רגלי הכסא העליון. וע\"כ הם כאן \u0003בפנים.\u0004 כמו החג\"ת העומדים שם בפנים. ואוריאל נמשך מרגל הד' של כסא העליון, שה\"ס הנוקבא העומדת שם באחורי חג\"ת כנ\"ל, וע\"כ גם המלאך אוריאל נמצא כאן באחורי הנוקבא. וז\"ש \u0003גו אינון דרגין דאתחברו בסטרוי,\u0004 דהיינו תוך ד' המדרגות שנתחברו להיות ד' רגלין בכסא העליון, שהם כאן בהנוקבא, ד' מלאכים. \u0003מיכאל\u0004 וכו', \u0003אוריאל לאחורא,\u0004 להיותו בחינת רגל הד' כמו רגל הד' של כסא העליון הנמצא גם שם באחורים, כמבואר. אמנם זה אמור בסוד שד' המלאכים נושאים את הכסא להזווג, דהיינו בעת גלגולא דעינא. כנ\"ל בדיבור הסמוך. אבל אח\"כ נשארת הנוקבא בסדר אחר, אשר אוריאל בא בפנים ורפאל באחור. אשר מבחינה זו נקראת הנוקבא אספקלריאה שאינה מאירה, כנ\"ל בדבור הסמוך. (ועי' במדבר אות ל\"א)"],[8,"ועל דא אתגליא וכו':","ומשום זה נתגלה עליו השכינה באלונים האלו, צללי העולם, כדי להראות לפניהם ברית הראשון, הרשימה הקדושה שהיה בכל העולם בסוד האמונה. פירוש, כי יש ב' נקודות בהמלכות, (כנ\"ל בהקדמת הזהר, דף נ\"ו ד\"ה גליפי) האחת היא נקודה האמצעית שבכל העולם, הן ממקומות הישוב והן ממקומות המדבר. וה\"ס הנקודה דצמצום א'. נקודה ב' ה\"ס נקודה אמצעית של מקומות הישוב בלבד, ולא מכל העולם, וה\"ס הנקודה דצמצום ב'. וכנגדם יש שני בריתות כנגד חיתוך ופריעה, ברית הא' הוא כנגד נקודה האמצעית מכל העולם, והוא סוד החיתוך של הערלה. וברית הב' הוא כנגד נקודת הישוב, והוא סוד הפריעה. וסוד \u0003אלוני ממרא,\u0004 ה\"ס דינין קשים הנמשכים מנקודה האמצעית שבכל העולם. וזה אמרו, \u0003ועל דא אתגליא עליה שכינתא בהני אלוני, צולמין דעלמא,\u0004 וע\"כ נגלה עליו השכינה באלוני ממרא, שהם צללים של כל העולם, כלומר שהם נגד נקודה האמצעית של כל העולם, \u0003בגין לאחזאה קמייהו ברית קדמאה\u0004 כדי להראות לפניהם ברית הראשון, דהיינו סוד חיתוך הערלה, שה\"ס \u0003רשימו קדישא דהוה בכל עלמא ברזא דמהימנותא,\u0004 שהוא כנגד רשימה הקדושה שהיה בכל העולם בסוד הנוקבא, הנקראת אמונה. דהיינו כנגד הנקודה הא', שהיתה בצמצום א', האמצעית מכל העולם, שממנה נמשך ברית הראשון שהוא סוד החיתוך של הערלה. כמו שיתבאר ענין זה להלן בדף כ' ד\"ה וזה ע\"ש."],[9,"והוא יושב פתח האהל וכו':","שואל, מאן פתח האהל. ואומר, זהו המקום שנקרא ברית, היא סוד האמונה. דהיינו הנוקבא. כחום היום, בזה הסוד נתדבק בו אברהם, שהוא תוקפו של צד הימין, המדרגה שלו. פירוש, כי יש ב' מיני דינין, דינין דנוקבא, הנמשכים מכח הצמצום שבה וה\"ס פתח האהל. ודינין דדכר, שהם נמשכים מכח הארת נקודת השורק. וה\"ס \u0003כחום היום.\u0004 דהיינו בזמן שהשמש, שה\"ס אור החכמה, מאיר בלי נרתק החסדים, שאז מושפע ממנו חום גדול. שהסו\"ה, אל תראוני שאני שחרחורת ששזפתני השמש. וז\"ש שהוא \u0003תוקפא דסטרא דימינא,\u0004 דהיינו גבורות הזכר, הנבחן לימין. ואלו ב' מיני דינים, ה\"ס צדיק וצדק. כמו שמבאר לפנינו."],[10,"פתח האהל וכו':","פתח האהל, ה\"ס שער הצדק, הפתח של האמונה, שהיא הנוקבא. שה\"ס הדינין דנוקבא כנ\"ל. ונקראת פתח כי אז נכנס אברהם באותו הרשימה הקדושה של ברית מילה. ולולא זה לא היה נכנס בברית מילה, משום זה נקרא פתח."],[10,"כחום היום, דא צדיק וכו':","כחום היום, הוא בחינת צדיק, מדרגת חיבור האחד, שנכנס בו מי שנמול ונרשם בו הרשימה הקדושה, כי הוסר ממנו הערלה, ונכנס בהארת ב' מדרגות הללו, צדיק וצדק, שהם סוד האמונה."],[10,"","פירוש. צדיק וצדק, הם יסוד ומלכות, אבל ב' שמות הללו יורו על זווג הגדול של זו\"ן לגלות המוחין דחיה. וכל זמן שיש אחיזה כל שהיא לקליפות ודינין, אין הזווג הזה יכול להתגלות, ולפי\"ז לא היה אפשר לגילוי המוחין הללו, מטרם גמר התקון, והעצה לזה ה\"ס ברית מילה. והוא, כי נתבאר, שכללות הדינין הם ב' בחינות, מבחינת הנוקבא ומבחינת הדכר. (כנ\"ל בדבור הסמוך). והם הפכים זה לזה, ואי אפשר ששניהם ישמשו במקום אחד, כי אין ב' הפכים באים במקום אחד. לכן באתערותא דלתתא על ידי מצות המילה מביאים ב' מיני הדינים במקום אחד בסוד היסוד העליון, ואז מכחישים זה את זה כטבע ההפכים, ומתבטלים שניהם. וכיון שנתבטלו, תכף מתגלה הזווג דצדיק וצדק, והמוחין הגדולים מתגלים. וז\"ס מעשה המילה, כי האיזמל החותך, היא נמשך מדינין דנוקבא. והערלה היא דינין דדכר, ונמצא האיזמל מעביר את הערלה, שהדינין דנוקבא מבטלים את הדינין דדכר. ולפעמים הצורך הוא להיפך, שהדינין דדכר יבטלו את הדינין דנוקבא. ע\"ד שאמרו ז\"ל על הפסוק ואת והב בסופה. (ברכות נ\"ד) ומובא ברש\"י על הפסוק ו אשד הנחלים (במדבר כ\"א), שהיו שם ב' הרים, באחד היו נקעים, שה\"ס דינין דנוקבא. ובהשני היו שדים בולטות כנגד הנקעים, שה\"ס דינין דדכר. והאמוריים נתחבאו בנקעים, להמטיר משם חצים על ישראל בעת שילכו בין ההרים. ועשה הקב\"ה נס, שנתקרבו ב' ההרים ונעשו אחד, ונכנסו הבלוטות של זה, דהיינו הדינין דדכורא, בהנקעים של זה, שהם הדינין דנוקבא. והאמוריים נמחצו ביניהם. הרי שעל ידי ביאת ב' ההפכים במקום אחד נתבטלו הדינין דנוקבא, כי האמוריים שבתוך הנקעים נהרגו. אבל כאן במילה עיקר הצורך הוא לבטל דינין דדכר. שה\"ס הערלה. אמנם באמת שניהם מתבטלים. כנ\"ל ואין להאריך."],[10,"","וזה אמרו, \u0003פתח האהל רזא דתרעא דצדק,\u0004 כי הדינין דנוקבא שנקראת \u0003אהל\u0004 הם מבטלים ומעבירים את הערלה, שה\"ס הדינין דדכר, נמצא שנעשו \u0003שער\u0004 לשלמות המלכות בסוד השם \u0003צדק\u0004 ונבחנת לשער, \u0003דכדין עאל ביה אברהם בההוא רשימא קדישא.\u0004 כי על ידי שהדינין דנוקבא העבירו את קליפת הערלה, נכנס אברהם לקבל אלו המוחין הקדושים המתגלים בזווג צדיק וצדק, ע\"כ נבחנים לשער. \u0003כחום היום. דא צדיק,\u0004 כלומר, אחר שהדינין דנוקבא העבירו את הערלה שהיתה דבוקה בהיסוד. בסוד \u0003כחום היום\u0004 כנ\"ל, נגלה בו השם \u0003צדיק,\u0004 בסוד \u0003הפריעה,\u0004 שהוא נוטריקון \u0003פרע י\"ה. דרגא דחבורא חדא,\u0004 היא המדרגה של חבור האחד, דהיינו של החיבור הגדול, דצדיק וצדק המגלה המוחין הגדולים, \u0003דעאל ביה מאן דאתגזר וכו'\u0004 דהיינו אחר שנעברו כל הדינים והקליפות בסוד \u0003החיתוך,\u0004 מתגלים המוחין די\"ה בסוד \u0003הפריעה. ועאל בקיומא דתרין דרגין אלין,\u0004 שהם צדיק וצדק כמבואר."],[11,"והנה שלשה אנשים וכו':","אלו הם ג' מלאכים, שליחים, שהם מתלבשים באויר, ויורדים לעולם הזה בצורה של אדם. והיו ג' כעין למעלה, דהיינו חג\"ת דז\"א, משום שהקשת, דהיינו הנוקבא, אינה נראית אלא בג' גוונים: לבן אדום וירוק, וכן הוא ודאי. דהיינו כמו הגוונים של חג\"ת דז\"א."],[12,"ואלין אינון וכו':","ואלו ג' אנשים הם ג' גוונים, גוון לבן, גוון אדום, גוון ירוק. גוון לבן, הוא מיכאל, משום שהוא צד ימין, שהוא נמשך מחסד דז\"א, הנבחן ללבן, גוון אדום זה גבריאל, שהוא צד שמאל, הנמשך מגבורה דז\"א, הנבחן לאדום. גוון ירוק זה רפאל. הנמשך מת\"ת דז\"א שהוא ירוק. ואלו הם ג' גוונים של הקשת, אשר הקשת, שהיא הנוקבא, אינה נראית זולתם. (כנ\"ל בראשית א' דף ע\"ה אות ע ') ומשום זה, וירא אליו, כי גילוי השכינה הוא בג' גוונים הללו. כלומר, שהכתוב והנה שלשה אנשים וגו', הוא ביאור על הכתוב וירא אליו ה', אשר וירא אליו פירושו, שנתגלה לו השכינה, והגילוי היה ע\"י גילוי ג' גוונים, שעליהם מסיים הכתוב והנה שלשה אנשים נצבים עליו, דהיינו מיכאל גבריאל רפאל. וכבר נתבאר ענין זה, שהם נמשכים מג' הקוין דז\"א, הנמשכים מג' נקודות חולם שורק חירק דבינה, כנ\"ל (דף י\"ח ד\"ה וכבר ע\"ש). ואין להכפיל דברים."],[13,"וכלהו אצטריכו וכו':","וצריכים לכל ג' המלאכים. כי אחד היה לרפאהו מן המילה. וזהו רפאל, שהוא בעל הרפואות. ואחד היה לבשר לשרה שתלד בן, וזהו מיכאל, משום שהוא הממונה על צד הימין, וכל טוב והברכות שמצד ימין נמסרו בידיו."],[14,"וחד להפכא וכו':","ואחד היה להפך את סדום, וזהו גבריאל, שהוא לשמאל, והוא ממונה על הדינים שבעולם. כי מצד שמאל הוא הדין, והפעולה הוא ע\"י מלאך המות, שהוא שר הטבחים של המלך. שהוא המוציא לפועל את הדינין שנדונו ע\"י גבריאל."],[15,"וכלהו עבדו וכו':","וכולם עושים את שליחותם. כל אחד ואחד כמו שראוי לו, המלאך גבריאל הולך בשליחות אל הנשמה הקדושה, ומלאך המות הולך בשליחות אל הנפש מיצר הרע. ועם כל זה, הנשמה אינה יוצאת מהגוף עד שרואה את השכינה."],[16,"כד חמא וכו':","כאשר אברהם ראה אותם, ג' המלאכים, מתחברים יחד, אז ראה את השכינה בגוונים שלה, והשתחוה. כי הם ג' גוונים של ז\"א, שהשכינה מתלבשת בהם. כנ\"ל. שכתוב \u0003וישתחו ארצה.\u0004 כמו ביעקב, שנאמר, וישתחו ישראל על ראש המטה, דהיינו לשכינה, הנקראת ראש המטה. אף כאן השתחוה לשכינה."],[17,"ולגבי שכינתא וכו':","ואל השכינה אמר בשם אדנ\"י שאמר אדנ\"י אל נא תעבור מעל עבדך: כמו אל הצדיק שהוא יסוד דז\"א הנקרא אדון. כי אז השכינה נקראת אדון כל הארץ, מאחר שהיא מאירה מהצדיק, הנקרא אדון, ומאירה בגוונים שלה, הנמשכים מג' קוין דז\"א כנ\"ל, כי עמהם היא נשלמת למעלה."],[18,"מהכא דחיזו וכו':","מכאן נשמע, שהמראה של מטה, דהיינו השכינה, מישכת משיכה מלמעלה, מהבינה. כי גוונין הללו, שה\"ס ג' המלאכים הנ\"ל, מושכים משיכת האורות מלמעלה, מאלו מקורים העליונים, שהם ג' הקוין שבבינה עצמה."],[19,"ובגין דאינון וכו':","ומשום שהם, מתחברים עמה, וסומכים אותה בכל, נאמר בה השם אדנ\"י, כי שם הזה נתגלה לאברהם לגמרי בסוד העליונים. באורות הבינה. ונתגלה לו בגלוי, מה שלא היה כן מטרם שנמול. ומקודם שנמול לא רצה הקב\"ה להוציא ממנו זרע קדוש, כיון שנמול, מיד יצא ממנו זרע קדוש, דהיינו יצחק."]],[[0,"","אָמַר רַבִּי יְהוּדָה, בְּשָׁעָה שֶׁנִּשְׁמַת הַצַּדִּיק רוֹצָה לָצֵאת - שְׂמֵחָה, וְהַצַּדִּיק בָּטוּחַ בְּמִיתָתוֹ כְּדֵי לְקַבֵּל שְׂכָרוֹ. זֶהוּ שֶׁכָּתוּב וַיַּרְא וַיָּרָץ לִקְרָאתָם, בְּשִׂמְחָה לְקַבֵּל פְּנֵיהֶם. מֵאֵיזֶה מָקוֹם? מִפֶּתַח הָאֹהֶל, כְּמוֹ שֶׁאָמַרְנוּ. וַיִּשְׁתַּחוּ אָרְצָה - אֶל הַשְּׁכִינָה."],[1,"","רַבִּי יוֹחָנָן פָּתַח וְאָמַר, (שיר ב) עַד שֶׁיָּפוּחַ הַיּוֹם וְנָסוּ הַצְּלָלִים סֹב דְּמֵה לְךְ דוֹדִי לִצְבִי אוֹ לְעֹפֶר הָאַיָּלִים. עַד שֶׁיָּפוּחַ הַיּוֹם וְגוֹ' - זוֹ אַזְהָרָה לָאָדָם בְּעוֹדוֹ בָּעוֹלָם הַזֶּה שֶׁהוּא כְּהֶרֶף עַיִן. בּא רְאֵה מַה כָּתוּב, (קהלת ו) וְאִלּוּ חָיָה אֶלֶף שָׁנִים פַּעֲמַיִם וְגוֹ'. בְּיוֹם הַמִּיתָה, כָּל מַה שֶּׁחָיָה, נֶחְשָׁב כְּיוֹם אֶחָד אֶצְלוֹ."],[2,"","אָמַר רַבִּי שִׁמְעוֹן, נִשְׁמָתוֹ שֶׁל אָדָם מַתְרָה בּוֹ וְאוֹמֶרֶת עַד שֶׁיָּפוּחַ הַיּוֹם (ונסו הצללים), וְיִדְמֶה בְעֵינֶיךְ כְּהֶרֶף עַיִן בְּעוֹדְךְ בָּעוֹלָם הַזֶּה. וְנָסוּ הַצְּלָלִים, זֶהוּ שֶׁכָּתוּב (איוב ח) כִּי צֵל יָמֵינוּ עֲלֵי אָרֶץ. בְּבַקָּשָׁה מִמְּךְ, סֹב דְּמֵה לְךְ דוֹדִי לִצְבִי וְגוֹ'."],[3,"","דָּבָר אַחֵר עַד שֶׁיָּפוּחַ הַיּוֹם וְגוֹ' - אָמַר רַבִּי שִׁמְעוֹן בֶּן פַּזִּי, זוֹ אַזְהָרָה לָאָדָם בְּעוֹדוֹ בָּעוֹלָם הַזֶּה שֶׁהוּא כְּהֶרֶף עַיִן: מָה הַצְּבִי קַל בְּרַגְלָיו - אַף אַתָּה הֱיֵה קַל כַּצְּבִי אוֹ כְּעֹפֶר הָאַיָּלִים לַעֲשׂוֹת רְצוֹן בּוֹרַאֲךְ כְּדֵי שֶׁתִּנְחַל הָעוֹלָם הַבָּא, שֶׁהוּא הָרֵי בְשָׂמִים, הַנִּקְרָא הַר ה', הַר הַתַּעֲנוּג, הָהָר הַטּוֹב. ע\"כ מדרש הנעלם."],[4,"","מֶמְשֶׁלֶת הַמֶּלֶךְ נִרְאֵית בִּשְׁלֹשָׁה גְוָנִים, גָּוֶן אֶחָד - מַרְאֶה שֶׁנִּרְאֶה לָעַיִן מֵרָחוֹק, וְאֵין הָעַיִן יְכוֹלָה לַעֲמֹד בַּבֵּרוּר שֶׁרוֹאָה, מִשּׁוּם שֶׁהוּא מֵרָחוֹק, עַד שֶׁנּוֹטֶלֶת הָעַיִן מַרְאֶה קָטָן בַּקִּמּוּץ שֶׁלָּהּ, וְעַל זֶה כָּתוּב (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי."],[5,"","גָּוֶן שֵׁנִי - מַרְאֶה שֶׁל הָעַיִן הַזֹּאת [נ\"א: של אחד] בַּסֵּתֶר שֶׁלָּהּ, שֶׁאֵין הַגָּוֶן הַזֶּה נִרְאֶה לָעַיִן, רַק בְּסֵתֶר קָטָן, שֶׁתּוֹפֵס וְלֹא עוֹמֵד בְּבֵרוּר, סוֹתֵם הָעַיִן וּפוֹתֵחַ מְעַט וְלוֹקֵחַ אוֹתוֹ הַמַּרְאֶה. וְהַגָּוֶן הַזֶּה [נ\"א: הגון וזה] צָרִיךְ לְפִתְרוֹן לַעֲמֹד עַל מַה שֶּׁלּוֹקַחַת הָעַיִן, וְעַל זֶה כָּתוּב (שם א) מָה אַתָּה רֹאֶה."],[6,"","הַגָּוֶן הַשְּׁלִישִׁי הוּא זֹהַר הָאַסְפַּקְלַרְיָה הַמְּאִירָה שֶׁלֹּא נִרְאֶה בוֹ כְּלָל, חוּץ מִגִּלְגּוּל הָעַיִן כַּאֲשֶׁר הוּא סָתוּם בִּסְתִימוּת וּמְגַלְגְּלִים לוֹ בְּגִלְגּוּל וְנִרְאֶה בַגִּלְגּוּל הַזֶּה אַסְפַּקְלַרְיָה הַמְּאִירָה. וְלֹא יָכוֹל לַעֲמֹד בְּאוֹתוֹ הַגָּוֶן, רַק שֶׁרוֹאֶה זהַר מֵאִיר בְּסֵתֶר הָעַיִן,"],[7,"","וְעַל זֶה כָּתוּב (יחזקאל לז) הָיְתָה עָלַי יַד ה', (שם לג) [ויד ה' היתה עלי] וְיַד ה' עָלַי חֲזָקָה. וְכֻלָּם מְפֹרָשִׁים מִנְּבִיאֵי הָאֱמֶת, פְּרָט לְמֹשֶׁה הַנֶּאֱמָן הָעֶלְיוֹן שֶׁזָּכָה לְהִסְתַּכֵּל לְמַעְלָה בְּמַה שֶּׁלֹּא נִרְאֶה כְּלָל. עָלָיו כָּתוּב (במדבר יב) לֹא כֵן עַבְדִּי מֹשֶׁה וְגוֹ'."],[8,"","וַיֵּרָא אֵלָיו, נִרְאֲתָה וְנִתְגַּלְּתָה לִי הַשְּׁכִינָה תּוֹךְ אוֹתָן דְּרָגוֹת שֶׁהִתְחַבְּרוּ בְּצִדּוֹ, מִיכָאֵ\"ל לְצַד יָמִין, גַּבְרִיאֵ\"ל לְצַד שְׂמֹאל, רְפָאֵ\"ל לְפָנִים, אוֹרִיאֵ\"ל לְאָחוֹר, וְעַל זֶה נִגְלְתָה עָלָיו הַשְּׁכִינָה בָּאֲלוֹנִים [נ\"א: צלמים] הַלָּלוּ שֶׁל הָעוֹלָם, כְּדֵי לְהַרְאוֹת לִפְנֵיהֶם בְּרִית [ד\"א רשם ראשון] הַקֹּדֶשׁ שֶׁהָיְתָה בְּכָל הָעוֹלָם בְּסוֹד הָאֱמוּנָה."],[9,"","וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. מַה זֶּה פֶּתַח הָאֹהֶל? זֶה הַמָּקוֹם שֶׁנִּקְרָא בְּרִית, סוֹד הָאֱמוּנָה. כְּחֹם הַיּוֹם, זֶה הַסּוֹד שֶׁנִּדְבַּק בּוֹ אַבְרָהָם, הַחֹזֶק שֶׁל צַד הַיָּמִין, הַדַּרְגָּה שֶׁלּוֹ."],[10,"","פֶּתַח הָאֹהֶל - סוֹד הַשַּׁעַר שֶׁל צֶדֶק פֶּתַח הָאֱמוּנָה, שֶׁאָז נִכְנַס בּוֹ אַבְרָהָם בְּאוֹתוֹ הָרֹשֶׁם הַקָּדוֹשׁ. כְּחֹם הַיּוֹם - זֶהוּ צַדִּיק, הַדַּרְגָּה שֶׁל חִבּוּר אֶחָד שֶׁנִּכְנָס בּוֹ מִי שֶׁנִּמּוֹל וְנִרְשַׁם בּוֹ הָרֹשֶׁם הַקָּדוֹשׁ, שֶׁהֲרֵי נִתְבַּטֵּל מִן הָעָרְלָה וְנִכְנַס בַּקִּיּוּם שֶׁל שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ שֶׁהֵן סוֹד הָאֱמוּנָה."],[11,"","וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים וְגוֹ' - אֵלּוּ שְׁלֹשָׁה אֲנָשִׁים שְׁלוּחִים שֶׁמִּתְלַבְּשִׁים בָּאֲוִיר, וְיוֹרְדִים לָעוֹלָם הַזֶּה [ונראים] בְּמַרְאֶה שֶׁל בֶּן אָדָם, וְהַשְּׁלֹשָׁה הֵם כְּמוֹ שֶׁלְּמַעְלָה, מִשּׁוּם שֶׁהַקֶּשֶׁת לֹא נִרְאֵית אֶלָּא בִּשְׁלֹשָׁה גְוָנִים - לָבָן, אָדם וְיָרֹק, וְכָךְ הוּא בְּוַדַּאי."],[12,"","וּשְׁלשֶת הָאֲנָשִׁים הַלָּלוּ שְׁלֹשָׁה גְוָנִים. גָּוֶן לָבָן, גָּוֶן אָדם, גָּוֶן יָרֹק (רחמים). הַגָּוֶן הַלָּבָן זֶה מִיכָאֵ\"ל, שֶׁהוּא צַד הַיָּמִין. הַגָּוֶן הָאָדם זֶה גַּבְרִיאֵ\"ל, הַצַּד שֶׁל הַשְּׂמֹאל. הַגָּוֶן הַיָּרֹק זֶה רְפָאֵ\"ל. וְאֵלּוּ הֵם שְׁלֹשֶׁת גּוֹנֵי הַקֶּשֶׁת, שֶׁאֵין הַקֶּשֶׁת נִרְאֵית אֶלָּא עִמָּהֶם. וּמִשּׁוּם כָּךְ וַיֵּרָא אֵלָיו, גִּלּוּי שְׁכִינָה בִּשְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ."],[13,"","וְאֶת כֻּלָּם הִצְטָרְכוּ. אֶחָד לְרַפֵּא אֶת הַמִּילָה, וְזֶהוּ רְפָאֵל, בַּעַל הָרְפוּאוֹת. וְאֶחָד לְבַשֵּׂר אֶת שָׂרָה עַל הַבֵּן, וְזֶהוּ מִיכָאֵל, מִשּׁוּם שֶׁהוּא הִתְמַנָּה לַיָּמִין, וְכָל הַטּוֹבוֹת וְהַבְּרָכוֹת שֶׁבְּיָדוֹ נִמְסְרוּ מִצַּד הַיָּמִין."],[14,"","וְאֶחָד לַהֲפֹךְ אֶת סְדוֹם, וְזֶהוּ גַבְרִיאֵל שֶׁהוּא לִשְׂמֹאל, וְהוּא מְמֻנֶּה עַל כָּל הַדִּינִים שֶׁל הָעוֹלָם מִצַּד (הדין) הַשְּׂמֹאל לָדוּן וְלַעֲשׂוֹת עַל יְדֵי מַלְאַךְ הַמָּוֶת, שֶׁהוּא בַּעַל הַהֶרֶג שֶׁל בֵּית הַמֶּלֶךְ."],[15,"","וְכֻלָּם עָשׂוּ שְׁלִיחוּתָם, וְכָל אֶחָד וְאֶחָד כָּרָאוּי לוֹ. וְהַמַּלְאָךְ גַּבְרִיאֵ\"ל בִּשְׁלִיחוּת לַנְּשָׁמָה הַקְּדוֹשָׁה, וּמַלְאַךְ הַמָּוֶת בִּשְׁלִיחוּתוֹ לַנֶּפֶשׁ שֶׁל הַיֵּצֶר הָרָע. וְעִם כָּל זֶה הַנְּשָׁמָה הַקְּדוֹשָׁה לֹא יוֹצֵאת עַד שֶׁרוֹאָה שְׁכִינָה."],[16,"","כְּשֶׁרָאָה אוֹתָם מְחֻבָּרִים כְּאֶחָד, אָז רָאָה שְׁכִינָה [כמו זה] בִּגְוָנֶיהָ וְהִשְׁתַּחֲוָה, שֶׁכָּתוּב (בראשית לג) וַיִּשְׁתַּחוּ אָרְצָה, כְּמוֹ אֵצֶל יַעֲקֹב שֶׁנֶּאֱמַר (שם מז) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, לַשְּׁכִינָה."],[17,"","וּלְגַבֵּי הַשְּׁכִינָה אָמַר בְּשֵׁם אדנ\"י, וּלְגַבֵּי הַצַּדִּיק אָדוֹ\"ן, שֶׁהֲרֵי אָז נִקְרָא אֲדוֹן כָּל הָאָרֶץ כְּשֶׁמּוּאֶרֶת מִצַּדִּיק וּמוּאֶרֶת בִּגְוָנֶיהָ, שֶׁהֲרֵי מִשּׁוּם [זהו כזה אז] זֶה נִשְׁלָם לְמַעְלָה."],[18,"","מִכָּאן שֶׁמַּרְאֶה שֶׁלְּמַטָּה מוֹשֵׁךְ הַמְשָׁכָה מִלְמַעְלָה, שֶׁהֲרֵי הַגְּוָנִים הַלָּלוּ מוֹשְׁכִים הַמְשָׁכָה מִלְמַעְלָה מֵאוֹתָם מְקוֹרוֹת עֶלְיוֹנִים. אדנ\"י מוֹשֵׁךְ מִלְמַעְלָה בִּשְׁלֹשֶׁת הַגְּוָנִים הַלָּלוּ שֶׁמִּתְלַבֵּשׁ בָּהֶם, וּבָהֶם נוֹטֶלֶת כָּל מַה שֶׁנּוֹטֶלֶת מִלְמַעְלָה."],[19,"","וּמִשּׁוּם שֶׁהֵם חִבּוּר שֶׁלָּהּ וְתוֹמְכִים שֶׁלָּהּ בַּכֹּל, נֶאֱמַר שֵׁם אדנ\"י, שֶׁהֲרֵי שֵׁם זֶה הִתְגַּלָּה לוֹ כָּלוּל בְּסוֹדוֹת עֶלְיוֹנִים, הִתְגַּלָּה לוֹ בְּגִלּוּי מַה שֶּׁלֹּא הָיָה מִקֹּדֶם לָכֵן כְּשֶׁלֹּא הָיָה מָהוּל. וְעַד שֶׁנִּמּוֹל, לֹא רצָה הַקָּבָּ\"ה לְהוֹצִיא מִמֶּנּוּ קָדוֹשׁ. כֵּיוָן שֶׁנִּמּוֹל, מִיָּד יָצָא מִמֶּנּוּ הַזֶּרַע הַקָּדוֹשׁ."]]],[["ובגין כך אתגלי עליה שכינתא באינון דרגין קדישין, (דניאל י״ב:ג׳) והמשכילים יזהירו כזהר הרקיע, זה\"ר זהרא דזהרין בדליקו זהרא, זה\"ר דאנהיר דאדליק ונציץ לכמה סטרין,","זה\"ר סליק ונחית, זה\"ר נציץ לכל עיבר, זה\"ר נגיד ונפיק, זה\"ר דלא פסיק לעלמין, זה\"ר דעביד תולדין,","זה\"ר טמיר וגניז נציצו דכל נציצין ושרגין כלא ביה נפיק וטמיר סתים וגליא חזי ולא חזי (זה\"ר) ספרא דא מבועא דבירא נפקי ביממא טמיר בליליא אשתעשע בפלגות ליליא בתולדין דאפיק,","זה\"ר דזהיר ואנהיר לכלא כללא דאורייתא ודא איהו דאתחזי וכל גוונין סתימין ביה ואתקרי בשמא דאדנ\"י תלת גוונין אתחזי לתתא מהאי תלת גוונין לעילא מאלין עלאין אתמשך כלא (ס\"א לגבי זהר) (אינון עלאין, זהר) דלא אתחזי ונציץ בתריסר נציצין וזהירין דנציצין מניה, תליסר אינון ברזא דשמא קדישא וגו' רזא דאין סוף ידוד אקרי"],[[0,"ובגין כך אתגלי וכו':","ומשום זה שנמול, נתגלה עליו השכינה באלו מדרגות הקדושים שבסוד הכתוב והמשכילים יזהירו כזהר הרקיע. שעם תקון הרקיע, שה\"ס הפרסא, נבקעו ונתחלקו כח\"ב תו\"מ דאצילות ונעשו מהם י\"ב פרצופין: הכתר, לד' פרצופין הנקראים, עתיק ונוקבא אריך אנפין ונוקבא. החכמה והבינה, לד' פרצופין הנקראים או\"א עלאין וישראל סבא ותבונה. הת\"ת ומלכות לד' פרצופין הנק' זו\"ן הגדולים וזו\"ן הקטנים. ולפיכך נקראים אלו י\"ב פרצופין בשם \u0003זהר הרקיע,\u0004 כי בכח הרקיע יצאו ונעשו. \u0003זהר\u0004 א' \u0003זהרא דזהרין בדליקו זהרא.\u0004 זהר המזהירים בהדלקה של הזהר. \u0003זהר\u0004 ב' \u0003דאנהיר דאדליק ונציץ לכמה סטרין\u0004. זהר המאיר המדליק, ונוצץ לכמה צדדים. פירוש. זהר א' הוא פרצוף עתיק וזהר ב' הוא הנוקבא שלו. ונתבאר לעיל (בראשית א' דף ה' ד\"ה וכשהאצילה) שעתיק עצמו הוא מבחינת המלכות הבלתי ממותקת, דהיינו למעלה מבחינת רקיע, שה\"ס לא בקע. אמנם מלכות זו הוא השורש למלכות הממותקת, והיא מדלקת את אורות הבינה אחר שנכבה. כנ\"ל (פרשת נח דף פ\"ד אות רמ\"א ע\"ש בסולם) וז\"ש בחשיבות פרצוף עתיק, \u0003זהרא דזהרין בדליקו זהרא,\u0004 שזהר שלו מזהיר בהדלקת הזהר. דהיינו שמדליק את הזהר דבינה שהיא שורש כל המוחין, ולולא הדלקה זו לא היו שום מוחין דגדלות באצילות. עש\"ה. ובחשיבות פרצוף נוקבא דעתיק, מוסיף, \u0003דאדליק ונציץ לכמה סטרין,\u0004 שהיא, מדלקת ומאירה הן בבחינת מלכות בלתי ממותקת והן בבחינת מלכות הממותקת. כי היא כבר נתקנה עם הרקיע בסוד \u0003בקע,\u0004 כנ\"ל (בראשית א' דף ה' ד\"ה וכשהאצילה) וע\"כ מאירה לכל הצדדים. אבל פרצוף עתיק דוכרא, אינו מאיר לכל הצדדים, רק לבחינת הדלקה לבד. להיותו למעלה מרקיע והוא \u0003לא בקע,\u0004 עש\"ה. ועל דרך זה הולך ומביא לפנינו מעלת כל י\"ב הפרצופין דאצילות ואשר כולם כלולים בז\"א, וז\"א משפיע להנוקבא כל אלו מדרגות הקדושים ונמצא אברהם, אע\"פ שלא קבל אלא מהנוקבא, מכל מקום זכה בכל י\"ב מדרגות העליונות כי כולן היו מחוברות בהנוקבא, בסוד השם אדנ\"י שבה. מה שאין כן מטרם שנמול לא זכה לקבל הדבור אלא מהנוקבא לבדה, דהיינו מטרם שנתחברו בה י\"ב מדרגות הללו."],[1,"זהר סליק ונחית:","זהר העולה ויורד, והוא פרצוף א\"א. כי הארת עתיק אינה יורדת לאצילות כמ\"ש לעיל (בראשית א' דף ו' ד\"ה בתר עש\"ה) \u0003זהר נציץ לכל עיבר.\u0004 זהר נוצץ לכל הבחינות. והיא הנוקבא דא\"א. כי א\"א משפיע רק חכמה לבד בלי חסדים. אבל הנוקבא דא\"א שה\"ס המלכות שלו משפעת לכל הבחינות דהיינו גם חסדים."],[1,"זהר נגיד ונפיק:","זהר נמשך ויוצא. דהיינו שיוצא מעדן שה\"ס א\"א. והיא בינה שיצאה לחוץ מראש א\"א, כנ\"ל (בהקדמת הזהר דף כ' ד\"ה וזהו שמבאר עש\"ה) ובינה זו נתלבשה בד' פרצופים, הג\"ר שלה נתלבשו באו\"א. וז\"ת שלה בישסו\"ת. וע\"כ מביא את זהר הזה דנגיד ונפיק, לפני ד' פרצופין הללו. \u0003זהר דלא פסיק לעלמין,\u0004 זהר שאינו נפסק לעולם. והוא ב' פרצופין הנקראים אבא ואמא עלאין, שהזווג שלהם הוא תמידי בלי הפסק, ובהיות ג\"ר דבינה מתלבשת בהם ע\"כ נמצאים בחסדים מכוסים מחכמה כטבע הבינה. \u0003זהר דעביד תולדין,\u0004 זהר העושה תולדות. והוא ב' פרצופין ישראל סבא ותבונה, שהארתם אינה תמידי כהארת או\"א, אמנם הם מאירים בהארת החכמה, ואין זווג להולדת נשמות בלי אור החכמה כנודע, וע\"כ מעלתם גדולה."],[2,"זהר טמיר וגניז נציצו דכל נציצין, ודרגין כלא ביה,","זהר נעלם וגנוז התנוצצות מכל התנוצצות, כלומר שהתנוצצות שלו גדול מכל התנוצצות שבעולמות. וכל המדרגות בו, כי הוא כולל כל י\"ב המדרגות דאצילות. והוא ב' הפרצופין זעיר ונוקביה הגדולים. ונקראים יחד בשם ז\"א. \u0003נפיק וטמיר סתים וגליא חזי ולא חזי,\u0004 יוצא ונעלם, סתום ומגולה, רואה ואינו רואה. פירוש. כשהוא יוצא ומאיר, הוא נעלם. כי הארתו של ז\"א נמשך מאו\"א עלאין, שהם בחסדים מכוסים מחכמה. וע\"כ, כשיוצא ומאיר הוא בהכרח נעלם כאו\"א. וכשהוא סתום ואינו מאיר אז הוא בגילוי. היינו בזמן שמקבל הארת השורק מאמא, שה\"ס חכמה, והוא אז בגלוי, אמנם אין החכמה מאירה בלי חסדים כנודע, וע\"כ הוא סתום ואינו מאיר. אמנם לעצמו אינו מקבל חכמה, להיותו בבחינת ג\"ר דבינה, אלא בשביל הנוקבא הוא מקבל חכמה. וז\"ש \u0003חזי ולא חזי,\u0004 חזי היינו אור החכמה הנקרא ראיה, ונבחן שהוא \u0003חזי\u0004 להשפיע לנוקבא אבל מבחינת עצמו \u0003לא חזי,\u0004 אלא תמיד הוא בחסדים מכוסים כנ\"ל."],[2,"ספרא דא מבועא דבירא,","ספר זה, כלומר הגבול שבפרצוף זה, ספר פירושו גבול, הוא המקור של הבור, שהיא הנוקבא דז\"א. גבול ה\"ס המסך המתוקן בכלי מלכות, שעליו נעשה הזווג דהכאה. ונודע שפני אדם, הוא רק בהמקום שמחזה ולמעלה דזו\"ן. וע\"כ יש שם מקום זווג. ולא מחזה ולמטה. כנ\"ל (בראשית א' א' דף פ\"ה ד\"ה ביאור.) ומחזה ולמעלה דזו\"ן נקרא זו\"ן הגדולים וכן ז\"א בלבד. דהיינו הפרצוף שלפנינו. ומחזה ולמטה דזו\"ן נקראים זו\"ן הקטנים וכן פרצוף נוקבא לבד. וז\"ש \u0003ספרא דא,\u0004 המסך שבפרצוף זה, שה\"ס פני אדם, הוא \u0003מבועא דבירא,\u0004 הוא המקור אל הבור, דהיינו של הנוקבא, כי היא מקבלת רק מהארת הזווג שבמסך הזה. \u0003נפיק ביממא טמיר בליליא אשתעשע בפלגות ליליא בתולדין דאפיק.\u0004 יוצא להאיר רק ביום, כי ז\"א מאיר ביום. ונעלם בלילה, שאינו מאיר אז. ומשתעשע בחצות לילה עם נשמות הצדיקים בגן עדן, שהם תולדותיו שהוציא. כמ\"ש לעיל דף ז' ד\"ה פירוש."],[3,"זהר, דזהיר ואנהיר לכלא כללא דאורייתא.","זהר המזהיר ומאיר לכל את כלל כל התורה. שה\"ס חכמה, \u0003ודא איהו דאתחזי וכל גוונין סתימין ביה,\u0004 וזה הוא שנראה, דהיינו שמקבל חכמה, וכל הגוונים חו\"ב תו\"מ נסתמים בו. כי הוא פרצוף נוקבא, הכוללת ב' פרצופין שמחזה ולמטה הנקראים זו\"ן הקטנים. ונודע שאין החכמה מקובלת באצילות אלא בהנוקבא, (כנ\"ל בראשית ב' דף ט\"ז ד\"ה אמר) על כן אומר בה וזה הוא שנראה וכו'. \u0003ואתקרי בשמא דאדנ\"י,\u0004 והיא נקראת בשם אדנ\"י. \u0003תלת גוונין אתחזי לתתא מהאי תלת גוונין לעילא.\u0004 ג' גוונים, שהם נה\"י נראים למטה ממנה. וג' גוונים הם למעלה, שהם חג\"ת. פי' כשהיא עולה למעלה מחזה לזווג עם ז\"א נעשית אז בסוד רביעי לאבות, ונבחן שחג\"ת דז\"א הם למעלה ונה\"י דז\"א הם למטה ממנה, ואומר שרק ג' שלמטה ממנה. נגלים ונראים בהארת חכמה ולא החג\"ת שלמעלה ממנה. \u0003מאלין עלאין אתמשך כלא, דלא אתחזי,\u0004 מאלו ג' העליונים שהם חג\"ת נמשך הכל כי אפילו הארת החכמה שבג' תתאין נה\"י נמשכת מחג\"ת, עם כל זה אינם נראים, כי לעצמם אינם מקבלים חכמה \u0003ונציץ בתריסר נציצין וזהירין דנציצין מניה,\u0004 והוא מתנוצץ בי\"ב התנוצציות ואורות שנוצצים ממנו. דהיינו שמקבלת מז\"א כל מדרגות י\"ב הפרצופין שז\"א כולל אותם כנ\"ל. \u0003תליסר אינון ברזא דשמא קדישא וגו רזא דאין סוף,\u0004 והם י\"ג בסוד האחד הכולל אותם בסוד שם הקדוש הויה, ותוך סוד א\"ס, כלומר שהם י\"ב מדרגות באצילות ועם הכולל אותם שה\"ס א\"ס הם י\"ג. כן בי\"ב מדרגות שבנוקבא, הם י\"ג עם שמא קדישא דז\"א הכולל אותם, בסוד א\"ס המלובש בו. \u0003הויה אקרי.\u0004 הכולל אותם נקרא בשם הויה. וי\"ב המדרגות שבנוקבא, נקרא בשם אדנ\"י כנ\"ל."]],[[0,"","וְלָכֵן הִתְגַּלְּתָה עָלָיו שְׁכִינָה בְּאוֹתָן דְּרָגוֹת קְדוֹשׁוֹת. (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. זֹהַ\"ר זוֹהֵר שֶׁזּוֹהֲרִים בִּדְלֵקוּת שֶׁל זֹהַר. זֹהַ\"ר שֶׁמֵּאִיר שֶׁמַּדְלִיק וְנוֹצֵץ לְכַמָּה צְדָדִים."],[1,"","זֹהַ\"ר עוֹלֶה וְיוֹרֵד. זהַ\"ר נוֹצֵץ לְכָל עֵבֶר. זֹהַ\"ר שׁוֹפֵעַ וְיוֹצֵא. זֹהַ\"ר שֶׁלֹּא פוֹסֵק לְעוֹלָמִים. זֹהַ\"ר שֶׁעוֹשֶׂה תוֹלָדוֹת."],[2,"","זֹהַ\"ר טָמִיר וְגָנוּז, הִתְנוֹצְצוּת שֶׁל כָּל הַנִּיצוֹצִים וְכָל הַדְּרָגוֹת בּוֹ. יוֹצֵא וְטָמִיר. נִסְתָּר וְגָלוּי. נִרְאֶה וְלֹא נִרְאֶה. [זה\"ר] סֵפֶר זֶה מַעְיַן הַבְּאֵר, יוֹצֵא בַּיּוֹם, נִסְתָּר בַּלַּיְלָה, מִשְׁתַּעֲשֵׁעַ בַּחֲצוֹת הַלַּיְלָה בַּתּוֹלָדוֹת שֶׁהוֹצִיא."],[3,"","זֹהַ\"ר שֶׁזּוֹהֵר וּמֵאֵיר לַכֹּל, הַכְּלָל שֶׁל הַתּוֹרָה, וְזֶהוּ שֶׁנִּרְאֶה, וְכָל הַגְּוָנִים נִסְתָּרִים בּוֹ וְנִקְרָא בַּשֵּׁם שֶׁל אדנ\"י. שְׁלֹשָׁה גְוָנִים נִרְאִים לְמַטָּה מֵאֵלּוּ שְׁלֹשֶׁת הַגְּוָנִים שֶׁלְּמַעְלָה. מֵאֵלּוּ הָעֶלְיוֹנִים הַכֹּל נִמְשָׁךְ [לגבי זהר] [אותם העליונים, זהר] שֶׁלֹּא נִרְאֶה, וְנוֹצֵץ בִּשְׁנֵים עָשָׂר נִצְנוּצִים וּזְהָרִים שֶׁנּוֹצְצִים מִמֶּנּוּ. שְׁלֹשָׁה עָשָׂר הֵם בְּסוֹד הַשֵּׁם הַקָּדוֹשׁ וְגוֹ', הַסּוֹד שֶׁל אֵין סוֹף נִקְרָא יהו\"ה."]]],[["כד אתחבר זהר תתאה אדני בזהר עלאה ידוד אתעביד שמא סתים דביה ידעי נביאי קשוט ומסתכלאן לגו זהרא עלאה ודא יאקדונקי חיזו טמירין (נ\"א חיוון טמירין) דכתיב (יחזקאל א׳:ד׳) כעין החשמל מתוך האש,","מתניתין עלאין רמאין טבין דימינא תשע נקודין דאורייתא נפקין ומתפלגין באתוון ואתוון בהו נטלין (מטלטלן) מטלנוי דקיקין ברזי (פלטין) פליגין אלין תשע שליטין על אתוון אתוון מנייהו אתפשטו אשתארו נקודין לאעלאה לון לא נטלין בר כד אינון נפקין","אלין אינון ברזא דאין סוף כלהו אתוון (מטללן) מטלנין ברזא דאין סוף כמה דאינון נטלי לון הכי נמי נטלי אלין סתימין אתוון גליין ואל גליין הני טמירין על מה דשריין אתוון"],[[0,"כד אתחבר וכו':","כאשר נתחבר זהר התחתון, דהיינו זהר הי\"ב, הנקרא \u0003אדנ\"י,\u0004 בזהר העליון שהוא ז\"א הנקרא \u0003הוי\"ה,\u0004 נעשה משניהם שם אחד, שבו משיגים נביאי האמת ומסתכלים לתוך זהר העליון, וזהו השם \u0003יאהדונה\"י.\u0004 דהיינו הויה אדני בשילוב. ומשיגים בו \u0003חיזו טמירין\u0004 שבשם הזה מושג הראיה של הנסתרות, בסוד שכתוב, כעין החשמל מתוך האש."],[1,"מתניתין עלאין רמאין וכו':","משנה. אליכם העליונים הרמים והטובים שמצד ימין נאמר סוד הזה, \u0003תשע נקודות שבתורה,\u0004 היינו הבינה, שה\"ס ג' נקודות חלם שורק חירק, (כנ\"ל דף כ' ד\"ה ואלין) שכל אחת כלולה משלשתם, והן ט' נקודות. \u0003נפקין, ומתפלגין באתוון, הן יוצאות,\u0004 מחוץ לראש דא\"א, היינו על ידי עלית המלכות לבינה (כנ\"ל לך לך דף ז' ד\"ה פירוש) \u0003ומתחלקים,\u0004 לכו\"ח ובינה ותו\"מ, ובינה ותו\"מ מתלבשים \u0003באותיות,\u0004 שהם זו\"ן. \u0003ואתוון בהו נטלין מטלנין דקיקין ברזי,\u0004 והאותיות נוסעות, על ידי בינה ותו\"מ דבינה המלובשת בהם, מסעות קטנות בסוד, כלומר. שהאותיות מקבלות מהם, בחי' מוחין דקטנות, דהיינו ו\"ק בלי ראש. (כנ\"ל ב\"א דף י\"ד ד\"ה ויש ע\"ש) ולעת גדלות \u0003פלטין אלין תשע שליטין אינון אתוון,\u0004 הבינה ותו\"מ דבינה הכוללת תשע הנקודות כנ\"ל \u0003פולטת ממנה אלו האותיות\u0004 שנתלבשה בה, \u0003אתוון מנייהו אתפשטו.\u0004 והאותיות נתפשטו מבינה ותו\"מ דבינה, המכונים ט' שליטים, \u0003אשתארו נקודין לאענאה לון,\u0004 ונשארו ט' נקודות בשלמותם. להניע האותיות. דהיינו להשפיע בהם מוחין הנותנים תנועה וחיות באותיות, שהם זו\"ן, כנ\"ל. פירוש. מתחילה נתחלקו ט' הנקודות, שה\"ס בינה, לב' חצאים אשר חצים התחתון, שהם בינה ותו\"מ, ירדה ונתלבשה באותיות, שהם זו\"ן. ואז השפיעו הנקודות אל האותיות מסעות קטנות, שפירושם מוחין דקטנות. ואח\"כ לעת גדלות, מחציתם התחתון דנקודות פלטה את האותיות, והאותיות נתפשטו מהם, כי הבינה חזרה לראש א\"א, ומחצית התחתון חזרה ונתחברה עם מחציתה העליון, ונשלמה שוב בע\"ס בכלים ואורות, ואז יכלו הנקודות להשפיע מוחין דגדלות לאותיות שהם זו\"ן, (כנ\"ל ב\"א דף י\"ד ד\"ה ויש ע\"ש)."],[1,"לא נטלין, בר כד אינין נפקין.","לא יסעו, רק כאשר אלו יוצאות, לבד מראש דא\"א. פירוש, כי לכאורה קשה, למה לו לבינה לצאת מהראש ולהתמעט לו\"ק, ואח\"כ לחזור לראש, כדי להשפיע מוחין דגדלות לאותיות, למה אינה משפעת להם מוחין דגדלות מטרם שיצאה מראש א\"א, לזה אומר. \u0003לא נטלין בר כד אינון נפקין,\u0004 האותיות לא יוכלו לנסוע, דהיינו לקבל מוחין לתנועה, רק כאשר אלו הנקודות יוצאות מראש א\"א, שאז יורדת מחצית התחתון ומתלבשת באותיות כנ\"ל."],[2,"אלין אינון ברזא דאין סוף","אלו האותיות הן בסוד אין סוף, כלומר שהן בחינת המלכות דמדת הדין, שעליה היה צמצום א' שלא תקבל לתוכה שום אור ישר. \u0003כלהו אתוון מטללי ברזא דאין סוף,\u0004 כל האותיות הן בצל סוד אין סוף. נשמר בזה, שלא תאמר. הרי האותיות הן ז\"א ונוקביה, והנוקבא שהיא מלכות, תוכל לומר שצמצום א' דאין סוף רובץ עליה. אבל ז\"א שעליו לא היה צמצום א', א\"כ אינו בצל אין סוף. לזה אומר \u0003כלהו אתוון\u0004 וכו' דהיינו אפילו ז\"א הוא בצל א\"ס. והטעם הוא כי שורש ז\"א הוא מטבור ולמטה דא\"ק ששם בחינת מלכות דצמצום א'. ולפי זה אין האותיות ראויות לקבל לתוכן שום מוחין, אלא. \u0003כמה דאינון נטלין לון,\u0004 כמו שהנקודות נוסעות, \u0003הכי נמי נטלי אלין סתימין אתוון.\u0004 כן נוסעות גם אלו האותיות הסתומות. פירוש מאחר שמסבת יציאת בינה מראש א\"א נפלו בינה ותו\"מ שלה ונתלבשו באותיות כנ\"ל. ע\"כ נעשו האותיות כמו גוף אחד עם בינה ותו\"מ הללו שבתוכם. ולעת גדלות, כמו שבינה ותו\"מ הללו חוזרות ועולות ונוסעות אל הבינה, והבינה חזרה לראש א\"א, כן נוסעות עמהן גם האותיות המלבישות עליהן, ועולות גם כן ומתחברות אל הבינה ומקבלות אורותיה, כמו הבינה ותו\"מ שלה. באופן, שמצד עצמם אין האותיות ראוים לנסיעה, דהיינו למוחין, אלא מתוך שמחצית כלים דבינה נפלו ונתלבשו בהן, נעשו עמהן גוף אחד ומקבלים מוחין על ידי נסיעתם של הכלים דבינה. וז\"ש \u0003כמה דאינון נטלין לון, הכי נמי נטלי אלין סתימין אתוון.\u0004 ואע\"פ שמצד עצמם אינן ראויות לנסיעה, להיותם בסוד מלכות המצומצמת. וכבר נתבאר זה לעיל (בראשית א' דף ז' ד\"ה כבר עש\"ה.) \u0003גליין ולא גליין הני טמירין על מה דשריין אתוון.\u0004 נגלות ואינן נגלות אלו הצפונות, שעליהן שורות האותיות. דהיינו מלכות המצומצמת. פירוש. אלו הכחות דמדת הדין ממלכות המצומצמת הם צפונות ונסתרות באותיות, ורק בחינת מלכות הממותקת בבינה נגלות בהן מתוך ירידת מחצית הבינה בתוכם כנ\"ל. ואל תחשוב שכחות מלכות המצומצמת גנוזים וצפונים, באופן שאינם מתגלים בהן לעולם. לזה אומר, \u0003גליין ולא גליין הני טמירין וכו'\u0004 כי בשעה שצריכים לקבל מוחין הן גנוזות וצפונות, אבל לפעמים הן מתגלות. והיינו בעת שצריכים להוציא את קו האמצעי. כנ\"ל לך לך דף י\"ג ד\"ה ונתבאר ע\"ש."]],[[0,"","כַּאֲשֶׁר מִתְחַבֵּר זֹהַר תַּחְתּוֹן אדנ\"י בְּזֹהַר עֶלְיוֹן יהו\"ה, נַעֲשֶׂה שֵׁם נִסְתָּר שֶׁבּוֹ יוֹדְעִים נְבִיאֵי הָאֱמֶת וּמִסְתַּכְּלִים לְתוֹךְ הַ הַר הָעֶלְיוֹן, וְזֶה יְאֲהֹדוָנָהֵי, מַרְאוֹת טְמִירִים [חיות טמירות], שֶׁכָּתוּב (יחזקאל א) כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ."],[1,"","מִשְׁנָה, עֶלְיוֹנִים גְּבוֹהִים טוֹבִים שֶׁל הַיָּמִין, תֵּשַׁע נְקֻדּוֹת שֶׁל הַתּוֹרָה יוֹצְאוֹת וְנֶחְלָקִים בָּאוֹתִיּוֹת, וְהָאוֹתִיּוֹת בָּהֶם נוֹסְעוֹת, [מטלטלים] מַסְעוֹתָיו דַּקִּיקִים בְּסוֹדוֹת. [היכל] חוֹלְקִים, אֵלּוּ תִּשְׁעַת הַשַּׁלִּיטִים עַל הָאוֹתִיּוֹת, הָאוֹתִיּוֹת הִתְפַּשְּׁטוּ מֵהֶם. נִשְׁאֲרוּ נְקוּדִים לְהַכְנִיסָם לָהֶם. לֹא נוֹסְעִים רַק כְּשֶׁאֵלֶּה יוֹצְאִים."],[2,"","הֵם בַּסּוֹד שֶׁל אֵין סוֹף. כָּל הָאוֹתִיּוֹת [נוסעות] מֻסָּעוֹת בַּסּוֹד שֶׁל אֵין סוֹף. כְּמוֹ שֶׁהֵם נוֹשְׂאִים אוֹתָם, כָּךְ הֵם נוֹסְעִים. אֵלּוּ הַנִּסְתָּרִים אוֹתִיּוֹת גְּלוּיוֹת וְלֹא גְלוּיוֹת. אֵלּוּ טְמִירִים עַל מַה שֶּׁשּׁוֹרוֹת הָאוֹתִיּוֹת."]]],[["תשע שמהן גליפן בעשר ואינון קדמאה אהיה יו\"ד ה\"א אדי\"ד אשר אדי\"ד ידו\"ד א\"ל אלדי\"ם ידו\"ד צבאו\"ת אדו\"ן שד\"י ומן דא שמא יו\"ד ה\"א וא\"ו ה\"א מתפשט כ\"ב אותיות ורזא דשמא מנצפך הרי כ\"ז אותיות ודא הוא רזא ידו\"ד אלהינ\"ו ידו\"ד אחד, יהוה אלהינו ידו\"ד הרי י\"ד אותיות, אח\"ד רזא י\"ג אתוון ומנהון יתפשטו רמ\"ח אברים שם בן מ\"ב ושם בן ע\"ב מנצפ\"ך חמשה גבורות ומניה יתפשט רזא דחמשין שערי בינה ומנהון יתפשטון ע\"ב הרי רמ\"ח אברהם עם יי' אלהיכם אמת,","אלין אינון עשר שמהן גליפן בסטריהון וכל הני שמהן אתגליפו רמ\"ח אברים ועאלין בחד ארון הברית ומאן איהו שמא דאתקרי אדני ודא (ד\"א רזא) אתגלי השתא לאברהם (י\"א ידו\"ד צבאות ונ\"א אל אדנ\"י)","מיכאל שמא דימינא דקא אחיד ומשמשא לשמא דא יתיר מאינון אחרנין בכל אתר דרזא דהאי שמא תמן מיכאל תמן אסתליק האי מיכאל אסתליק אלהים בהדי שדי,"],[[0,"תשע שמהן גליפן בעשר:","תשעה שמות נחקקות בעשרה. פירוש. כי מתוך שמלכות המצומצמת נגנזה הרי אין בהם רק תשע ספירות שה\"ס תשעה שמות, כי העשירית שהיא מלכות חסרה, אמנם אומר, שתשעה השמות נחקקו ונעשו מהם עשרה. והוא כי היסוד נחלק לב' ספירות וב' שמות. שהם \u0003אדון שדי,\u0004 כמו שמבאר לפנינו. \u0003ואנון\u0004 ואלו הם. \u0003קדמאה.\u0004 הראשון הוא \u0003אהיה,\u0004 דהיינו כתר. הב' \u0003יוד הא,\u0004 הוא חכמה. \u0003אהיה אשר אהיה,\u0004 הוא בינה. \u0003הוי\"ה\u0004 בניקוד אלקים, הוא ישסו\"ת. \u0003אל\u0004 הוא חסד. \u0003אלקים\u0004 הוא גבורה. \u0003הוי\"ה.\u0004 הוא ת\"ת. \u0003צבאות\u0004 הוא נצח והוד. \u0003אדון שדי\u0004 שניהם ביסוד. אדון, הוא עטרת יסוד. ושדי הוא יסוד עצמו."],[1,"אלין אינון וכו':","אלו הם עשרה שמות חקוקות לפי בחינתם. וכל אלו השמות נחקקו ובאו בארון הברית אחד, ומי הוא. הוא השם שנקרא \u0003אדנ\"י.\u0004 וזה הוא שנגלה עתה, לאחר המילה, אל אברהם. דהיינו השם אדנ\"י שה\"ס הנוקבא אחר שקבלה לתוכה כל עשרה השמות הנ\"ל שהם כל המדרגות שבאצילות. אבל מקודם שנמול, לא השיג סוד הראיה. רק מן הנוקבא לבדה בלי חיבורה עם המדרגות העליונות."],[2,"מיכאל שמא דימינא וכו':","מיכאל הוא שם הימין, דהיינו חסד, שהוא נאחז ומשמש לשם הזה \u0003אדנ\"י,\u0004 יותר ממלאכים האחרים. בכל מקום שסוד שם הזה \u0003אדנ\"י\u0004 נמצא גם מיכאל שמה. נסתלק מיכאל, נסתלק אלקים, שהיא הנוקבא, עם שד\"י, שהוא יסוד."]],[[0,"","תִּשְׁעָה שֵׁמוֹת חֲקוּקוֹת עִם עֲשָׂרָה, וְהָרִאשׁוֹן אֶהְיֶה. [יו\"ד ה\"א] אֶהְיֶ\"ה אֲשֶׁר אֶהְיֶ\"ה, יהו\"ה, אֵ\"ל, אֱלֹהִי\"ם, יהו\"ה, צְבָאוֹת, אָדוֹ\"ן, שַׁדַּ\"י. [ומהשם הזה יו\"ד ה\"א וא\"ו ה\"א מתפשט כ\"ב אותיות, וסוד השם מנצפ\"ך הרי כ\"ז אותיות, וזהו סוד יהו\"ה אלהינ\"ו יהו\"ה אחד, יהו\"ה אלהינו יהו\"ה הרי י\"ד אותיות, אחד סוד י\"ג אותיות, ומהם יתפשטו רמ\"ח אברים, שם בן מ\"ב ושם בן ע\"ב מנצפ\"ך חמשה גבורות, וממנו יתפשט הסוד של חמשים שערי בינה, ומהם יתפשטו ע\"ב, הרי רמ\"ח איברים עם יי' אלהיכם אמת]."],[1,"","אֵלֶּה הֵם עֲשָׂרָה שֵׁמוֹת חֲקוּקִים בְּצִדֵּיהֶם, וְכָל הַשֵּׁמוֹת הַלָּלוּ נֶחְקְקוּ מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵבָרִים וְנִכְנָסִים בַּאֲרוֹן הַבְּרִית הָאֶחָד, וּמִיהוּ? הַשֵּׁם שֶׁנִּקְרָא אדנ\"י. וְזֶה [ד\"א סוד] הִתְגַּלָּה עַכְשָׁו לְאַבְרָהָם. [נ\"א: יהו\"ה צבאו\"ת, ונ\"א א\"ל אדנ\"י]."],[2,"","מִיכָאֵל שֵׁם הַיָּמִין שֶׁאוֹחֵז וּמְשַׁמֵּשׁ אֶת הַשֵּׁם הַזֶּה יוֹתֵר מֵאוֹתָם הָאֲחֵרִים. בְּכָל מָקוֹם שֶׁסּוֹד הַשֵּׁם הַזֶּה שָׁם - מִיכָאֵל שָׁם. אִם הִסְתַּלֵּק מִיכָאֵל הַזֶּה - מִסְתַּלֵּק אֱלֹהִים עִם שַׁדַּי."]]],[["בקדמיתא שלשה אנשים ואגלימו בציורא דאוירא והוו אכלי אכלי ודאי דאשא דלהו אכל ושצי כלא ואעביד נחת רוח לאברהם אינון אשא ודאי וההוא אשא אתכסי בציורא דאוירא ולא אתחזי וההוא מיכלא אשא מלהטא ואכלא ליה ואברהם מקבל נחת רוח מהאי,","כיון דאסתלק שכינתא מה כתיב ויעל אלהים מעל אברהם מיד מסתלק בהדיה מיכאל דכתיב ויבאו שני המלאכים סדומה וגו' שלשה כתיב בקדמיתא והשתא תרין אלא מיכאל דאיהו ימינא אסתליק (קו ב) בהדי שכינתא,","מלאך דאתחזי למנוח נחת ואיגלים (ליה) באוירא ואתחזי ליה ודא איהו אוריאל מה דלא נחת באלין דאברהם נחת הכא בלחודוי לבשרא למנוח דאתי מדן","ובגין דלא חשיב כאברהם לא כתיב דאכל דהא כתיב (שופטים י״ג:כ׳) אם תעצרני לא אוכל בלחמך וכתיב ויהי בעלות הלהב מעל המזבח ויעל מלאך יי' בלהב המזבח וגו' והכא ויעל אלהים מעל אברהם בגין דביה אסתליק מיכאל ואשתארו רפאל וגבריאל","ועלייהו כתיב שני המלאכים סדומה בערב בשעתא דדינא תליא על עלמא לבתר אסתלק חד ואשתכח גבריאל בלחודיה בזכותיה דאברהם אשתזיב לוט ואיהו אוף הכי זכה בהו ועל דא אתו לגביה:","רַבִּי אַבָּא פָּתַח וְאָמַר, (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְהַר יְיָ וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ. תָּא חֲזֵי, כָּל בְּנֵי עָלְמָא לָא חָמָאן עַל מָה קָיְימֵי בְּעָלְמָא, וְיוֹמִין אָזְלִין וְסָלְקִין וְקָיְימֵי קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, כָּל אִנּוּן יוֹמִין דִּבְנֵי נָשָׁא קָיְימֵי בְּהוּ בְּהַאי עָלְמָא, דְּהָא כֻּלְהוּ אִתְבְּרִיאוּ וְכֻלְהוּ קָיְימֵי לְעֵילָא, וּמְנָלָן דְּאִתְבְּרִיאוּ, דִּכְתִיב, (תהילים קל״ט:ט״ז) יָמִים יוּצָרוּ.","וְכַד מָטָאן יוֹמִין לְאִסְתַּלָּקָא מֵהַאי עָלְמָא. כֻּלְהוּ קְרֵיבִין קַמֵּי מַלְכָּא עִלָּאָה, הֲדָא הוּא דִכְתִיב, (מלכים א ב׳:א׳) וַיִּקְרֵבוּ יְמֵי דָּוִד לָמוּת. (בראשית מ״ז:כ״ט) וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת.","בְּגִין דְּכַד בַּר נָשׁ אִיהוּ בְּהַאי עָלְמָא לָא אַשְׁגַּח וְלָא אִסְתַּכַּל עַל מַה קָאִים, אֶלָּא כָּל יוֹמָא וְיוֹמָא חָשִׁיב כְּאִלּוּ הוּא אָזִיל בְּרֵקַנְיָיא, דְּהָא כַּד נִשְׁמָתָא נָפְקַת מֵהַאי עָלְמָא לָא יָדְעַת לְאָן אָרְחָא סָלְקִין לָהּ. דְּהָא אוֹרְחָא לְסַלְקָא לְעֵילָא לְאֲתַר דִּנְהִירוּ דְּנִשְׁמָתִין עִלָּאִין נָהֲרִין, לָא אִתְיְהִיב לְכֻלְהוֹן נִשְׁמָתִין, דְּהָא כְּגַוְונָא דְּאִיהוּ אַמְשִׁיךְ עֲלֵיהּ בְּהַאי עָלְמָא, הָכִי אִתְמַשְׁכַת לְבָתַר דְּנָפִיק מִנֵּיהּ.","תָּא חֲזֵי, אִי בַּר נָשׁ אִתְמְשִׁיךְ בָּתַר קוּדְשָׁא בְּרִיךְ הוּא, וְתִיאוּבְתָּא דִּילֵיהּ אֲבַתְרִיהּ בְּהַאי עָלְמָא, לְבָתַר כַּד נָפִיק מִנֵּיהּ, אִיהוּ אִתְמְשִׁיךְ אֲבַתְרִיהּ וְיָהֲבִין לֵיהּ אוֹרַח לְאִסְתַּלָּקָא לְעֵילָא, בָּתַר הַהוּא מְשִׁיכוּ דְּאִתְמְשִׁיךְ בִּרְעוּתָא כָּל יוֹמָא בְּהַאי עָלְמָא.","אָמַר רַבִּי אַבָא יוֹמָא חַד אִעַרְעָנָא בְּחַד מָתָא מֵאִנּוּן דְּהֲווּ מִן בְּנֵי קֶדֶם, וְאָמְרוּ לִי מֵהַהִיא חָכְמְתָא דְּהֲווּ יָדְעִין מִיּוֹמֵי קַדְמָאֵי וְהֲווּ אַשְׁכְּחָן סִפְרִין דְּחָכְמְתָא דִּלְהוֹן, וּקְרִיבוּ לִי חַד סִפְרָא.","וְהֲוָה כְּתִיב בֵּיהּ, דְּהָא כְּגַוְונָא דִּרְעוּתָא דְּבַּר נָשׁ אִיכַוֵּון בֵּיהּ בְּהַאי עָלְמָא, הָכִי אַמְשִׁיךְ עֲלֵיהּ רוּחַ מִלְּעֵילָא כְּגַוְונָא דְּהַהוּא רְעוּתָא דְּאִתְדָּבַּק בֵּיהּ, אִי רְעוּתֵיהּ אִיכַוִּין בְּמִלָּה עִלָּאָה קַדִּישָׁא אִיהוּ אַמְשִׁיךְ עֲלֵיהּ לְהַהִיא מִלָה מִלְּעֵילָא לְתַתָּא לְגַבֵּיהּ.","וְאִי רְעוּתֵיהּ לְאִתְדַּבְּקָא בְּסִטְרָא אָחֳרָא וְאִיכַוֵּין בֵּיהּ, אִיהוּ אַמְשִׁיךְ לְהַהִיא מִלָּה מִלְּעֵילָא לְתַתָּא לְגַבֵּיהּ. וְהֲווּ אָמְרִי דְּעִקָּרָא דְּמִלְּתָא תַּלְיָיא בְּמִלִּין וּבְעוֹבָדָא וּבִרְעוּתָא לְאִתְדַּבְּקָא, וּבְדָא אִתְמְשַׁךְ מִלְּעֵילָא לְתַתָּא הַהוּא סִטְרָא דְּאִתְדָּבַּק בָּהּ.","וְאַשְׁכַּחְנָא בֵּיהּ כָּל אִנּוּן עוֹבָדִין וּפוּלְחָנִין דְּכֹכְבַיָא וּמַזָּלֵי וּמִלִּין דְּאִצְטְרִיכוּ לוֹן וְהֵיאַךְ רְעוּתָא לְאִתְכַּוְּונָא בְּהוּ בְּגִין לְאַמְשָׁכָא לוֹן לְגַבַּיְיהוּ.","כְּגַוְונָא דָא מַאן דְּבָעֵי לְאִתְדַּבְּקָא לְעֵילָא בְּרוּחַ קוּדְשָׁא דְּהָא בְּעוֹבָדָא וּבְמִלִּין וּבִרְעוּתָא דְלִבָּא לְכַוְּונָא בְּהַהִיא מִלָּה תַּלְיָיא מִלְּתָא לְאַמְשָׁכָא לֵיהּ לְגַבֵּיהּ מֵעֵילָא לְתַתָּא וּלְאִתְדַּבְּקָא בְּהַהִיא מִלָּה.","וְהֲווּ אָמְרֵי כַּמָּה דְּבַר נָשׁ אִתְמְשַׁךְ בְּהַאי עָלְמָא הָכִי נָמֵי מָשְׁכִין לֵיהּ כַּד נָפִיק מֵהַאי עָלְמָא. וּבְמָּה דְאִתְדָּבַּק בְּהַאי עָלְמָא וְאִתְמְשַׁךְ אֲבַתְרֵיהּ הָכִי אִתְדָּבַּק בְּהַהוּא עָלְמָא, אִי בְּקוּדְשָׁא, בְּקוּדְשָׁא. וְאִי בִּמְסָאֲבָא, בִּמְסָאֲבָא.","אִי בְּקוּדְשָׁא, מָשְׁכִין לֵיהּ לְגַבֵּי הַהוּא סְטַר וְאִתְדָּבַּק בֵּיהּ לְעֵילָא, וְאִתְעֲבִיד מְמַנָּא שַׁמָּשָׁא, לְשַׁמָּשָׁא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא בֵּין אִנּוּן שְׁאָר מַלְאָכִין. כְּמָה דְּהָכִי אִתְדָּבַּק לְעֵילָא וְקָאִים בֵּין אִנּוּן קַדִּישִׁין דִּכְתִיב (זכריה ג׳:ז׳) וְנָתַתִּי לְךָ מַהְלְכִים בֵּין הָעוֹמְדִים הָאֵלֶה.","הָכִי נָמֵי כְּגַוְונָא דָא. אִי בִּמְסָאֳבָא, מָשְׁכִין לֵיהּ לְגַבֵּי הַהוּא סְטַר וְאִתְעֲבִיד כְּחַד מִנַּיְיהוּ לְאִתְדַּבְּקַא בְּהוּ וְאִנּוּן אִקְרוּן נִזְקֵי בְּנֵי נְשָׁא. וּבְהַהִיא שַׁעֲתָא דְּנָפִיק מֵהַאי עָלְמָא נָטְלִין לֵיהּ וְשָׁאֲבִין לֵיהּ בַּגֵּיהִנָּם בְּהַהוּא אֲתַר דְּדַיְינֵי לוֹן לִבְנֵי מְסָאֳבָא דְּסָאִיבוּ גַּרְמַיְיהוּ וְרוּחַיְיהוּ, וּלְבָתַר אִתְדָּבַּק בְּהוּ. וְאִיהוּ נִזְקָא (כט א) כְּחַד מֵאִנּוּן נִזְקֵי דְעָלְמָא.","אֲמִינָא לוֹן בָּנַי קְרִיבָא דָא לְמִלִּין דְּאוֹרַיְיתָא. אֲבָל אִית לְכוּ אִתְרַחֲקָא (מגו) מֵאִנּוּן סִפְרִין (אלין) בְּגִין דְּלָא יִסְטֵי לִבַּיְיכוּ לְאִלֵּין פּוּלְחָנִין וּלְכָל אִנּוּן סִטְרִין דְּקָאֲמַר הָכָא דִּילְמָא חַס וְשָׁלוֹם (לא) תִּסְטוּן מִבָּתַר פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","דְּהָא כָּל סְפָרִים אִלֵּין אַטְעַיָּין לוֹן לִבְנֵי נָשָׁא, בְּגִין דִּבְנֵי קֶדֶם חַכִּימִין הֲווּ, וִירוּתָא דְּחָכְמְתָא דָא יָרְתוּ מֵאַבְרָהָם דְּיָהַב לִבְנֵי פִּלַּגְּשִׁים, דִּכְתִיב, (בראשית כ״ה:ו׳) וְלִבְנֵי הַפִּלַּגְּשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנוֹת וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ בְּעוֹדֶנוּ חַי קֵדְמָה אֶל אֶרֶץ קֶדֶם. וּלְבָתַר אִתְמַשְׁכוּ בְּהַהִיא חָכְמָה לְכַמָּה סִטְרִין.","אֲבָל זַרְעָא דְּיִצְחָק חוּלָקָא דְיַעֲקֹב לָאו הָכִי, דִּכְתִיב, (בראשית כ״ה:ה׳) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, דָּא חוּלָקָא קַדִּישָׁא דִּמְהֵימְנוּתָא דְּאִתְדָּבַּק בֵּיהּ אַבְרָהָם, וְנָפַק מֵהַהוּא עַדְבָא וּמֵהַהוּא סִטְרָא, יַעֲקֹב מַה כְּתִיב בֵּיהּ (בראשית כ״ח:י״ג) וְהִנֵה יְיָ נִצָּב עָלָיו. וּכְתִיב, (ישעיה מא) וְאַתָּה יַעֲקֹב עַבְדִּי וְגו'. בְּגִינֵי כָךְ בָּעֵי לֵיהּ לְבַּר נָשׁ לְאִתְמַשְׁכָא בָּתַר קוּדְשָׁא בְּרִיךְ הוּא וּלְאִתְדַּבְּקָא בֵּיהּ תָּדִיר דִּכְתִיב, (דברים י) וּבוֹ תִדְבָּק.","תָּא חֲזֵי, (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְּהַר יְיָ וְגו'. וּלְבָתַר אַהֲדַר וּפֵירַשׁ נְקִי כַפַּיִם. דְּלָא עֲבִיד בִּידוֹי טוּפְסָא וְלָא אִתְתַּקַּף בְּהוּ בְּמָּה דְּלָא אִצְטְרִיךְ. וְתוּ דְּלָא אִסְתָּאַב בְּהוּ וְלָא סָאִיב בְּהוּ לְגוּפָא כְּאִנּוּן דִּמְסָאֲבִין גַּרְמַיְיהוּ בְּיָדִין לְאִסְתָּאֲבָא, וְדָא הוּא נְקִי כַפַּיִם, וּבַר לֵבָב, כְּגַוְונָא דָא דְּלָא אַמְשִׁיךְ רְעוּתֵיהּ וְלִבֵּיהּ לְסִטְרָא אָחֳרָא, אֶלָּא לְאִתְמַשְּׁכָא בָּתַר פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","אֲשֶׁר לא נָשָׂא לַשָׁוְא נַפְשׁוֹ. נַפְשׁוֹ כְּתִיב נַפְשִׁי קְרִי, וְהָא אוּקְמוּהָ נַפְשִׁי דָּא נֶפֶשׁ דָּוִד סִטְרָא דִּמְהֵימְנוּתָא. נַפְשׁוֹ דָּא נֶפֶשׁ דְּבַר נָשׁ מַמָּשׁ. בְּגִין דְּכַד יִפּוּק מֵהַאי עָלְמָא. וְנַפְשֵׁיהּ יִסְתַּלַּק בְּעוֹבָדִין דְּכָשְׁרִין עַל מַה דְּיִתְקַיַּים בְּהוּ לְמֵיהַךְ בֵּין כָּל אִנּוּן קַדִּישִׁין כְּמָא דְאַתְּ אָמֵר, (תהילים קט״ז:ט׳) אֶתְהַלֵּךְ לִפְנֵי יְיָ בְּאַרְצוֹת הַחַיִּים. וּבְגִין דְּלָא נָשָׂא לַשָּׁוְא נַפְשִׁי יִשָּׂא בְרָכָה מֵאֵת יְיָ וְגו'.","תָּא חֲזֵי, בָּתַר דְּאִתְגְּזַר אַבְרָהָם הֲוָה יָתִיב וְכָאִיב, וְקוּדְשָׁא בְּרִיךְ הוּא שָׁדַר לְגַבֵּיהּ תְּלַת מַלְאָכִין בְּאִתְגַּלְּיָא לְאַקְדָמָא לֵיהּ שְׁלָם. וְאִי תֵימָא דְּהָא בְּאִתְגַּלְּיָא. וְכִי מַאן יָכִיל לְמֶחֱמֵי מַלְאָכִין וְהָא כְּתִיב, (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹת וְגו'.","אֶלָּא ודַּאי חָמָא לוֹן, דְּנַחֲתֵי לְאַרְעָא כְּגַוְונָא דִבְנֵי נָשָׁא, וְלָא יִקְשֶׁה לָךְ הַאי, דְּהָא וַדַּאי אִנּוּן רוּחִין קַדִּישִׁין, וּבְשַׁעֲתָא דְּנָחֲתֵי לְעָלְמָא מִתְלַבְּשִׁין (קמד א) בַּאֲוִירֵי וּבִיסוֹדֵי דְּגוּלְמִין, וְאִתְחֲזוּ לִבְנֵי נָשָׁא מַמָּשׁ כְּחֵיזוּ דִּיוּקְנָא דִּלְהוֹן.","וְתָּא חֲזֵי, אַבְרָהָם חָמָא לוֹן כְּחֵיזוּ בְּנֵי נָשָׁא. וְאַף עַל גַּב דְּהֲוָה כָּאִיב מִמִּילָה נָפַק וְרָהַט אֲבַּתְרַיְיהוּ בְּגִין דְּלָא לְמִגְרַע (מה) דְּהֲוָה עֲבִיד מִקַּדְמַת דְּנָא.","אָמַר רַבִּי שִׁמְעוֹן וַדַּאי כְּחֵיזוּ דְּמַלְאָכִין חָמָא לוֹן, מִמַּה דִּכְתִיב וַיֹּאמַר אֲדֹנָי בְּאל\"ף דל\"ת, שְׁכִינְתָּא הֲוָה אַתְיָא, וְאִלֵּין הֲווּ סְמִיכִין דִּילָהּ וְכֻּרְסְיָיא לְגַבָּהּ, בְּגִין דְּאִנּוּן גְּוָונִין (צא א) תְּלַת דִּתְחוֹתָא.","וְחָמָא הַשְׁתָּא בְּגִין דְּאִתְגְּזַר מַה דְּלָא הֲוָה חָמֵי מִקַּדְמַת דְּנָא עַד לָא אִתְגְּזַר, בְּקַדְמִיתָא לָא הֲוָה יָדַע אֶלָּא דְּאִנּוּן בְּנֵי נָשָׁא, וּלְבָתַר יָדַע דְּאִנּוּן מַלְאָכִין קַדִּישִׁין וְאָתוּ בִּשְׁלִיחוּתָא לְגַבֵּיהּ. בְּשַׁעֲתָא דְּאָמְרוּ לֵיהּ אַיֵּ\"ה שָׂרָה אִשְׁתְּךָ וּבִשְׂרוּ לֵיהּ בְּשׂוֹרַת יִצְחָק.","אֵלָיו אַתְוָון נְקוּדוֹת אַיּ\"וֹ, וְסִימָן אַיּ\"וֹ, רֶמֶז לְמַה דִּלְעֵילָא, רֶמֶז לְקוּדְשָׁא בְּרִיךְ הוּא. וַיֹּאמֶר הִנֵּה בָאֹהֶל. כְּתִיב הָכָא הִנֵּה בָאֹהֶל וּכְתִיב הָתָם (ישעיהו ל״ג:כ׳) אֹהֶל בַּל יִצְעָן וְגו'. תָּא חֲזֵי, כֵּיוָן דְּנָקוּד אי\"ו אַמַּאי כְּתִיב לְבָתַר אַיֵּה, אֶלָּא בְּגִין דְּחִבּוּרָא דִּדְכַר וְנוּקְבָא כְּחֲדָא רָזָא דִּמְהֵימְנוּתָא. כְּדֵין אָמַר וַיֹּאמֶר הִנֵּה בָאֹהֶל. תַּמָּן הוּא קִשּׁוּרָא דְּכֹלָּא וְתַמָּן אִשְׁתַּכַּח (ויאמר הנה באהל). אַיֵּה וְגו', וְכִי לָא הֲווּ יָדְעֵי מַלְאֲכֵי עִלָּאֵי דְּשָׂרָה הִנֵּה בָאֹהֶל, אַמַּאי כְּתִיב אַיֵּה. אֶלָּא לָא יָדְעֵי בְּהַאי עָלְמָא אֶלָּא מַה דְּאִתְמָסַר לְהוּ לְמִנְדַע.","תָּא חֲזֵי (שמות י״ב:י״ב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם אֲנִי יְיָ. וְכִי כַּמָּה שְׁלִיחִין וּמַלְאָכִין אִית לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, אֶלָּא בְּגִין דְּאִנּוּן לָא יָדְעֵי בֵּין טִפָּה דְּבוּכְרָא לְהַהוּא דְּלָא בּוּכְרָא בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי.","כְּגַוְונָא דָּא (יחזקאל ט׳:ד׳) וְהִתְוֵיתָ תָּו עַל מִצְחוֹת הָאֲנָשִׁים. וְאַמַּאי צְרִיכִין. אֶלָּא בְּגִין דְּאִנּוּן לָא יָדְעֵי, אֶלָא מַה דְּאִתְמָסַר לוֹן לְמִנְדַע (ידעי), כְּגוֹן כָּל אִנּוּן מִלִּין דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַיְיתָאָה עַל עָלְמָא. וּמַאי טַעְמָא בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אַעֲבַר כָּרוֹזָא בְּכֻלְהוּ רְקִיעִין בְּהַהִיא מִלָּה דְּזַמִּין לְאַיְתָאָה עַל עָלְמָא."],[[0,"בקדמיתא שלשה אנשים וכו':","בתחילה היו שלשה אנשים, ונתלבשו בציור של אויר, והיו אוכלים. אכלו ודאי, כי אש שלהם אכל והשחית הכל, ונעשה בזה נחת רוח לאברהם. ומפרש יותר בהרחבה, הם עצמם אש בודאי ואש הזה נתכסה בציור האויר ולא היה נראה, ואותו המאכל שאכלו, היה אש לוהט, ואכלו אותו, ואברהם היה מקבל נחת רוח מזה."],[1,"כיון דאסתלק וכו':","כיון שנסתלקה, השכינה, מה כתוב, ויעל אלקים מעל אברהם, מיד מסתלק עמה גם מיכאל, כנ\"ל. שכתוב ויבואו שני המלאכים סדומה וגו' מתחילה כתוב שלשה, ועתה שנים, מכאן שמלאך מיכאל נסתלק יחד עם עלית השכינה, ונשארו רק שני מלאכים."],[2,"מלאך דאתחזי וכו':","המלאך שנראה למנוח, ירד ונתלבש באויר ונראה אליו וזה הוא המלאך \u0003אוריאל,\u0004 מי שלא ירד באלו המלאכים שבאברהם, ירד כאן לבדו, לבשר למנוח הבא מדן, שיהיה לו בן."],[3,"ובגין דלא חשיב וכו':","ומשום שמנוח אינו חשוב כמו אברהם, לא כתוב שאכל, כי כתוב, אם תעצרני לא אוכל בלחמך. וכתוב ויהי בעלות הלהב וגו' ויעל מלאך ה' וגו'. וכאן כתוב ויעל אלקים מעל אברהם אבל במלאכים לא כתוב שנסתלקו מעל אברהם. והוא משום שעם אלקים נסתלק גם מיכאל כנ\"ל, ונשארו \u0003רפאל וגבריאל.\u0004"],[4,"ועליהם כתוב","שני המלאכים סדומה, בערב, בשעה שהדין תלוי על העולם. ולאחר כך, נסתלק אחד, ונשאר להפיכת סדום רק \u0003גבריאל\u0004 לבדו. בזכותו של אברהם ניצל לוט וע\"כ גם הוא זכה בהם, בשני המלאכים, וע\"כ באו אצלו. (ע\"כ סתרי תורה)."],[5,"ר' אבא פתח וכו':","ר\"א פתח ואמר, מי יעלה בהר ה' ומי יקום במקום קדשו בוא וראה כל בני העולם אינם רואים על מה הם נמצאים בעולם, כלומר, שאינם מסתכלים לדעת, לאיזה מטרה הם חיים בעולם. והימים הולכים מבלי לשוב. וכל אלו הימים, שבני אדם חיים בהם בעולם הזה, עולים ועומדים לפני הקב\"ה, כי כולם נבראו, ויש להם מציאות ממשית, ומאין לנו שנבראו. כי כתוב ימים יוצרו."],[6,"וכד מטאן יומין וכו':","וכשמגיעים הימים להסתלק מעולם הזה, כולם קרבים לפני מלך העליון. וזהו שכתוב, ויקרבו ימי דוד למות. ויקרבו ימי ישראל למות."],[7,"בגין דכד וכו':","כשהאדם הוא בעולם הזה, אינו משגיח ואינו מסתכל למה הוא חי, אלא כל יום ויום חשוב אצלו כאילו הוא הולך בריקנות, והנה כאשר הנשמה יוצאת מעולם הזה אינה יודעת לאיזה דרך מעלים אותה. כי הדרך לעלות למעלה, למקום שהארות נשמות העליונות מאירות, שהוא הג\"ע, לא ניתן לכל הנשמות. כי כמו שהוא ממשיך על עצמו בעולם הזה, כן נמשכת הנשמה ללכת לאחר שיצאה הימנו."],[8,"ת\"ח אי ב\"נ:","בוא וראה, אם האדם נמשך אחר הקב\"ה, והשתוקקותו אחריו בעולם הזה, לאחר כך, כשנפטר מעולם הזה, הוא נמשך גם כן אחר הקב\"ה, ונותנים לו דרך לעלות למעלה, להמקום שהנשמות מאירות, דהיינו אחר אותה המשיכה שרצונו נמשך אחריה בכל יום בעולם הזה."],[9,"א\"ר אבא, יומא וכו':","אר\"א יום אחד פגשתי עיר אחת, מאותן שהיו מבני קדם. ואמרו לי מאותה חכמה שהיו יודעים מימי קדם. ומצאו ספרי החכמה שלהם והגישו לי ספר אחד."],[10,"והוה כתיב וכו':","והיה כתוב בו, כי כעין מה שהרצון של אדם מכוון בו בעולם הזה, כן ממשיך עליו רוח מלמעלה, כעין אותו הרצין שנתדבק בו. אם רצונו כוון בדבר עליון קדוש, הוא ממשיך עליו אותו הדבר מלמעלה למטה אליו."],[11,"ואי רעותיה וכו':","ואם רצונו הוא להתדבק בסטרא אחרא, וכוון בו, הוא ממשיך אותו הדבר מלמעלה למטה אליו. והיו אומרים שכדי להמשיך דבר מלמעלה, עיקר הדבר תלוי: בדבור, ובמעשה, וברצון להתדבק, ובזה נמשך ממעלה למטה אותו הצד שנתדבק בו."],[12,"ואשכחנא ביה וכו':","ומצאתי בו בספר. כל אלו המעשים והעבודות של כוכבים ומזלות, והדברים שצריכים לעבודתם, ואיך צריך הרצון לכוון בהם, כדי להמשיך אותם אצלם."],[13,"כגוונא דא וכו':","כעין זה מי שרוצה להתדבק למעלה ברוח הקדש, הנה במעשה ובדבור ולכוון באותו הדבר בכוונת הלב, תלוי הדבר, שיוכל להמשיך אליו מלמעלה למטה ולהתדבק בהדבר."],[14,"והוו אמרי וכו':","והיו אומרים במה שאדם נמשך בעולם הזה, כן מושכים אותו כשיוצא מן עולם הזה, ובמה שנתדבק ונמשך אחריו בעולם הזה, כן הוא מתדבק בו בעולם האמת, אם בקדש בקדש, אם בטומאה בטומאה."],[15,"אי בקודשא וכו':","אם בקדש מושכים אותו לצד הקדושה, ונתדבק בו למעלה ונעשה ממונה משמש לשמש לפני הקב\"ה, בין כל המלאכים. כמו כן הוא מתדבק למעלה ועומד בין אלו הקדושים, שכתוב ונתתי לך מהלכים בין העומדים האלה."],[16,"הכי נמי כגוונא וכו':","כן כעין זה, אם בטומאה, נתדבק בעולם הזה, מושכים אותו, אל צד הטומאה, ונעשה כאחד מהם להתדבק בהם. והם נקראים מזיקי בני אדם. ובשעה שנפטר מעולם הזה לוקחים אותו ושוקעים אותו בגיהנם. באותו מקום שדנים לבני הטומאה שטמאו עצמם ורוחם ואח\"כ נתדבקו בהם. והוא נעשה מזיק, כאחד מאלו מזיקי העולם."],[17,"אמינא לון בני וכו':","אמרתי להם: בני, הדברים שבספר קרובים לדברי תורה. אבל יש לכם להתרחק מספרים אלו, כדי שלא יטו לבכם לאלו העבודות ולכל אלו הצדדים שאמר כאן. אולי ח\"ו תסורו מאחר עבודת הקב\"ה."],[18,"דהא כל וכו':","כי כל ספרים האלו מתעים בני אדם. משום שבני קדם חכמים היו וירושת החכמה הזו ירשו מאברהם שנתן לבני הפלגשים, שכתוב ולבני הפלגשים אשר לאברהם נתן אברהם מתנות וגו'. ולאחר כך נמשכו בחכמה זו לכמה צדדים."],[19,"אבל זרעא וכו':","אבל זרע יצחק חלקו של יעקב אינו כן, שכתוב ויתן אברהם את כל אשר לו ליצחק. זהו חלק הקדוש של האמונה, שנתדבק בו אברהם, ומגורל הזה ומצד הזה יצא יעקב. מה כתוב בו. והנה ה' נצב עליו. וכתוב ואתה יעקב עבדי וגו'. משום זה צריך האדם להמשך אחר הקב\"ה. ולהתדבק בו תמיד. שכתוב, ובו תדבק."],[20,"ת\"ח מי וכו':","בוא וראה כתוב, מי יעלה בהר ה' וגו' ואחר כך חוזר ומפרש \u0003נקי כפים.\u0004 היינו שלא עשה בידיו פסל, וידיו לא התקפו במה שאינו צריך. ועוד, יש לפרש הכתוב נקי כפים שלא נטמאו ידיו, ולא טמא עמהם את הגוף. כאותם המטמאים את עצמם בידיהם להטמא. וזה הוא נקי כפים. \u0003ובר לבב.\u0004 היינו, כמו זה, שלא המשיך רצונו ולבו לסטרא אחרא, אלא להמשך אחר עבודת הקב\"ה."],[21,"אשר לא נשא לשוא נפשו:","נפשו כתוב, נפשי קרי, ובארוה זה נפש דוד צד האמונה, שהיא הנוקבא דז\"א \u0003נפשו,\u0004 זה נפש בן אדם ממש. וזה הוא ההפרש בין הכתיב לבין הקרי. שהרי כשאדם נפטר מעולם הזה, ונפשו תסתלק במעשים כשרים, על מה שתזכה על ידיהם ללכת בין כל אלו הקדושים כמו שאתה אומר אתהלך לפני ה' בארצות החיים. לפיכך אומר ומשום ש \u0003לא נשא לשוא נפשי,\u0004 ישא ברכה מאת ה' וגו'."],[22,"ת\"ח בתר דאתגזר וכו':","בוא וראה אחר שאברהם נמול, היה יושב וכואב, והקב\"ה שלח אליו ג' מלאכים בגלוי, להקדים לו שלום. ואם תאמר, איך היו בגלוי. וכי מי יכול לראות מלאכים, כי כתוב, עושה מלאכיו רוחות."],[23,"אלא ודאי חמא וכו':","ומשיב. אלא ודאי שראה אותם, כי ירדו לארץ כצורת אנשים, ולא יקשה לך זה. כי ודאי הם רוחות קדושים, ובשעה שיורדים לעולם, הם מתלבשים באויר וביסודות של כיסוי ועטיפה, ונראים לבני אדם כעין צורתם ממש."],[24,"ות\"ח אברהם וכו':","ובוא וראה, אברהם ראה אותם כמראה בני אדם, ואף על פי שהיה כואב מן המילה, יצא ורץ לקראתם, כדי שלא לגרוע ממנהגו. שהיה עושה מקודם לכן, שהיה דרכו לקבל אורחים."],[25,"אמר ר\"ש ודאי וכו':","אר\"ש, ודאי, כמראה מלאכים ראה אותם. כמו שנשמע ממה שכתוב, ויאמר \u0003אדנ\"י\u0004 שהוא השם אלף דלת של השכינה. \u0003א' ד'\u0004 ה\"ס ראשי תיבות של השם \u0003אדנ\"י\u0004 כי השכינה היתה באה, ואלו המלאכים היו סמוכות שלה, וכסא אליה. משום שהם ג' גוונים: לבן, אדום, ירוק, שמתחת השכינה, (כנ\"ל דף י\"ד ד\"ה הורמנותא) כלומר מחזה ולמטה שלה, הנבחן בכל מדרגה לבחינת מתחת המדרגה. כי המלאכים הללו הם בחינת חיצוניות, שמחזה ולמטה של השכינה."],[26,"וחמא השתא וכו':","וראה עתה שהם מלאכים, משום שנמול, מה שלא ראה מקודם לכן מטרם שנמול. כי בתחילה לא היה יודע אלא שהם בני אדם, ואח\"כ ידע שהם מלאכים, ובאו אליו בשליחות מהקב\"ה, דהיינו בשעה שאמרו אליו, איה שרה אשתך, ובשרו לו בשורת יצחק."],[27,"אליו, אתוון נקודות אי\"ו וכו':","אותיות המנוקדות שבמלה \u0003אליו,\u0004 שבהכתוב ויאמר \u0003אליו\u0004 איה וגו' הוא \u0003איו.\u0004 והסימן אי\"ו רומז למה שלמעלה, כי רומז להקב\"ה. ששאלו אותו עליו \u0003איו. ויאמר הנה באהל.\u0004 דהיינו שדבוק בהשכינה, כי כתוב כאן הנה באהל, וכתוב שם, אהל בל יצען. מה שם פירושו השכינה, אף כאן פירושו השכינה. בוא וראה. כיון שכבר מנוקד \u0003איו,\u0004 בהמלה אליו, למה כתוב אח\"כ \u0003איה.\u0004 ומשיב, משום שחיבורם של דכר ונוקבא ביחד, הוא סוד האמונה. וע\"כ שאלו על הקב\"ה \u0003איו,\u0004 ושאלו על השכינה \u0003איה.\u0004 כלומר, שעוררו אותו ליחוד הקב\"ה ושכינתיה. \u0003כדין אמר\u0004 וכו' אז אומר הכתוב, ויאמר הנה באהל. כי שם קשר הכל דהיינו הנוקבא הנקראת אהל. ושם נמצא הקב\"ה."],[28,"איה","וגו', \u0003וכי לא הוו ידעי\u0004 וכו': ושואל, וכי לא ידעו מלאכים העליונים, ששרה היא באהל, למה כתוב ששאלו עליה איה. ומשיב, אלא המלאכים אינם יודעים בעולם הזה רק מה שנמסר להם לדעת. בוא וראה, ועברתי בארץ מצרים אני ה' ושואל, הלא כמה שליחים ומלאכים יש לו להקב\"ה, ולמה עבר בארץ מצרים בעצמו. ומשיב אלא משום שהמלאכים אינם יודעים להבחין בין טפה של בכור לאותה שאינה בכור, רק הקב\"ה לבדו יודע זה."],[29,"כגוונא דא וכו':","כעין זה, והתוית תו על מצחות האנשים, ולמה צריכים המלאכים לסימן זה, אלא משום שהמלאכים אינם יודעים רק מה שנמסר להם לדעת, דהיינו כל אלו הדברים שעתיד הקב\"ה להביא בעולם. ומהו הטעם שיודעים זה, הוא משום שהקב\"ה מעביר כרוזים בכל הרקיעים, ומודיע אותו הדבר שעתיד להביא בעולם, והמלאכים שומעים הכרוזים ויודעים."]],[[0,"","בַּהַתְחָלָה שְׁלֹשָׁה אֲנָשִׁים, וְהִתְגַּלְּמוּ בְּצִיּוּר שֶׁל אֲוִיר וְהָיוּ אוֹכְלִים, אוֹכְלִים וַדַּאי, שֶׁהָאֵשׁ שֶׁלָּהֶם אוֹכֶלֶת וּמְכַלָּה הַכֹּל וְעוֹשִׂים נַחַת רוּחַ לְאַבְרָהָם. הֵם אֵשׁ וַדַּאי, וְאוֹתָהּ הָאֵשׁ מִתְכַּסָּה בְּצִיּוּר שֶׁל אֲוִיר וְלֹא נִרְאֵית. וְאוֹתוֹ מַאֲכָל אֵשׁ לוֹהֶטֶת וְאוֹכֶלֶת אוֹתוֹ, וְאַבְרָהָם מְקַבֵּל נַחַת רוּחַ מזֶּה."],[1,"","כֵּיון שֶׁהִסְתַּלְּקָה הַשְּׁכִינָה מַה כָּתוּב? וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם. מִיָּד מִסְתַּלֵּק עִמּוֹ מִיכָאֵל, שֶׁכָּתוּב וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה וְגוֹ'. שְׁלֹשָׁה כָּתוּב בַּהַתְחָלָה, וְעַכְשָׁו שְׁנַיִם. אֶלָּא מִיכָאֵל שֶׁהוּא יָמִין הִסְתַּלֵּק עִם הַשְּׁכִינָה."],[2,"","הַמַּלְאָךָ שֶׁנִּרְאָה לְמָנוֹחַ יָרַד וְהִתְגַּלֵּם [לו] בָּאֲוִיר וְנִרְאָה לוֹ, וְזֶהוּ אוֹרִיאֵל. מַה שֶּׁלֹּא יָרַד עִם אֵלּוּ לְאַבְרָהָם - יָרַד כָּאן לְבַדּוֹ לְבַשֵּׂר לְמָנוֹחַ שֶׁבָּא מִדָּן."],[3,"","וּמִשּׁוּם שֶׁלֹּא חָשׁוּב כְּמוֹ אַבְרָהָם, לֹא כָתוּב שֶׁאָכַל, שֶׁהֲרֵי כָּתוּב (שופטים יג) אִם תַּעְצְרֵנִי לֹא אֹכַל בְּלַחְמֶךְ. וְכָתוּב, וַיְהִי בַעֲלוֹת הַלַּהַב מֵעַל הַמִּזְבֵּחַ, וַיַּעַל מַלְאַךְ ה' בְּלַהַב הַמִּזְבֵּחַ וְגוֹ'. וְכָאן וַיַּעַל אֱלֹהִים מֵעַל אַבְרָהָם. מִשּׁוּם שֶׁבּוֹ הִסְתַּלֵּק מִיכָאֵל, וְנִשְׁאֲרוּ רְפָאֵל וְגַבְרִיאֵל."],[4,"","וַעָלֵיהֶם כָּתוּב שְׁנֵי הַמַּלְאָכִים סְדמָה. בָּעֶרֶב - בְּשָׁעָה שֶׁהַדִּין תָּלוּי עַל הָעוֹלָם. אַחַר כָּךְ הִסְתַּלֵּק אֶחָד, וְנִמְצָא שֶׁגַּבְרִיאֵל לְבַדּוֹ. בִּזְכוּת אַבְרָהָם נִצַּל לוֹט, וְהוּא אַף כָּךְ זָכָה בָהֶם, וְעַל זֶה בָּאוּ אֵלָיו. (ע\"כ ס\"ת)."],[5,"","רַבִּי אַבָּא פָּתַח וְאָמַר, (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ. בּא רְאֵה, כָּל בְּנֵי הָעוֹלָם לֹא רוֹאִים עַל מָה עוֹמְדִים בָּעוֹלָם, וְהַיָּמִים הוֹלְכִים וְעוֹלִים וְעוֹמְדִים לִפְנֵי הַקָּבָּ\"ה כָּל אוֹתָם יָמִים שֶׁבְּנֵי אָדָם עוֹמְדִים בָּהֶם בָּעוֹלָם הַזֶּה, שֶׁהֲרֵי כֻּלָּם נִבְרְאוּ וְכֻלָּם עוֹמְדִים לְמַעְלָה. וּמִנַּיִן לָנוּ שֶׁנִּבְרְאוּ? שֶׁכָּתוּב (שם קלט) יָמִים יֻצָּרוּ."],[6,"","וּכְשֶׁמַּגִּיעִים הַיָּמִים לְהֵעָלוֹת מִן הָעוֹלָם הַזֶּה, כֻּלָּם קְרֵבִים לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן. זֶהוּ שֶׁכָּתוּב (מלכים א ב) וַיִּקְרְבוּ יְמֵי דָוִד לָמוּת. וַיִּקְרְבוּ יְמֵי יִשְׂרָאֵל לָמוּת."],[7,"","מִשּׁוּם שֶׁכַּאֲשֶׁר בֶּן אָדָם הוּא בָּעוֹלָם הַזֶּה, אֵינוֹ מַשְׁגִּיחַ וְלֹא מִתְבּוֹנֵן עַל מַה הוּא עוֹמֵד, אֶלָּא כָּל יוֹם וָיוֹם חוֹשֵׁב כְּאִלּוּ הוּא הוֹלֵךְ בְּרֵיקָנוּת, שֶׁהֲרֵי כְּשֶׁהַנְּשָׁמָה יוֹצֵאת מִן הָעוֹלָם הַזֶּה, לֹא יוֹדַעַת לְאֵיזוֹ דֶרֶךְ מַעֲלִים אוֹתָהּ. שֶׁהֲרֵי הַדֶּרֶךְ לַעֲלוֹת לְמַעְלָה לְמָקוֹם שֶׁאוֹר הַנְּשָׁמוֹת הָעֶלְיוֹנוֹת מְאִירוֹת, לֹא נִתָּן לְכָל הַנְּשָׁמוֹת, שֶׁהֲרֵי כְּמוֹ שֶׁהוּא מַמְשִׁיךְ עָלָיו בָּעוֹלָם הַזֶּה, כָּךְ נִמְשָׁךְ לְאַחַר שֶׁיּוֹצֵא מִמֶּנּוּ."],[8,"","בֹּא רְאֵה, אִם בֶּן אָדָם נִמְשָׁךְ אַחַר הַקָּבָּ\"ה וּתְשׁוּקָתוֹ אַחֲרָיו בָּעוֹלָם הַזֶּה, אַחֲרֵי זֶה כְּשֶׁיּוֹצֵא מִמֶּנּוּ, הוּא נִמְשָׁךְ אַחֲרָיו, וְנוֹתְנִים לוֹ דֶּרֶךְ לַעֲלוֹת לְמַעְלָה אַחַר אוֹתָהּ מְשִׁיכָה שֶׁנִּמְשָׁךְ בְּרָצוֹן כָּל יוֹם בָּעוֹלָם הַזֶּה."],[9,"","אָמַר רַבִּי אַבָּא, יוֹם אֶחָד נִפְגַּשְׁתִּי בְּעִיר אַחַת מֵאוֹתָם שֶׁהָיוּ מִן בְּנֵי קֶדֶם, וְאָמְרוּ לִי מֵאוֹתָהּ חָכְמָה שֶׁהָיוּ יוֹדְעִים מִיָּמִים רִאשׁוֹנִים, וְהָיוּ מוֹצְאִים סְפָרִים שֶׁל הַחָכְמָה שֶׁלָּהֶם, וְקֵרְבוּ לִי סֵפֶר אֶחָד,"],[10,"","וְהָיָה כָּתוּב בּוֹ, שֶׁכְּמוֹ שֶׁהָרָצוֹן שֶׁל הָאָדָם מִתְכַּוֵּן בּוֹ בָּעוֹלָם הַזֶּה, כָּךְ מַמְשִׁיךְ עָלָיו רוּחַ מִלְמַעְלָה כְּמוֹ אוֹתוֹ הָרָצוֹן שֶׁנִּדְבָּק בּוֹ. אִם רְצוֹנוֹ הִתְכַּוֵּן לְדָבָר עֶלְיוֹן קָדוֹשׁ, הוּא מַמְשִׁיךְ אוֹתוֹ הַדָּבָר מִלְמַעְלָה לְמַטָּה אֵלָיו."],[11,"","וְאִם רְצוֹנוֹ לְהִתְדַּבֵּק בַּצַּד הָאַחֵר וּמִתְכַּוֵּן בּוֹ, הוּא מַמְשִׁיךְ אֶת אוֹתוֹ הַדָּבָר מִלְמַעְלָה לְמַטָּה אֵלָיו. וְהָיוּ אוֹמְרִים שֶׁעִקַּר הַדָּבָר תָּלוּי בְּדִבּוּרִים וּבְמַעֲשֶׂה וּבְרָצוֹן לְהִתְדַּבֵּק, וּבָזֶה נִמְשָׁךְ מִלְמַעְלָה לְמַטָּה אוֹתוֹ הַצַּד שֶׁנִּדְבָּק בּוֹ."],[12,"","וּמָצָאנוּ בוֹ כָּל אוֹתָם מַעֲשִׂים וַעֲבוֹדוֹת הַכּוֹכָבִים וְהַמַּזָּלוֹת וּדְבָרִים שֶׁהִצְטָרְכוּ לָהֶם, וְאֵיךְ הָרָצוֹן לְהִתְכַּוֵּן בָּהֶם כְּדֵי לִמְשֹׁךְ אוֹתָם אֲלֵיהֶם."],[13,"","כְּמוֹ זֶה מִי שֶׁרוֹצֶה לְהִדָּבֵק לְמַעְלָה בְּרוּחַ הַקֹּדֶשׁ, שֶׁהֲרֵי בְּמַעֲשֶׂה וּבְדִבּוּרִים וּבִרְצוֹן הַלֵּב לְכַוֵּן בְּאוֹתוֹ הַדָּבָר תָּלוּי הַדָּבָר לִמְשֹׁךְ אוֹתוֹ אֵלָיו מִלְמַעְלָה לְמַטָּה וּלְהִדָּבֵק בְּאוֹתוֹ הַדָּבָר."],[14,"","וְהָיוּ אוֹמְרִים, כְּמוֹ שֶׁבֶּן אָדָם נִמְשַׁךְ בָּעוֹלָם הַזֶּה - כָּךְ גַּם מוֹשְׁכִים אוֹתוֹ כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה. וּבַמֶּה שֶׁנִּדְבַּק בָּעוֹלָם הַזֶּה וְנִמְשַׁךְ אַחֲרָיו - כָּךְ נִדְבָּק בְּאוֹתוֹ הָעוֹלָם. אִם בְּקֹדֶשׁ - בְּקֹדֶשׁ, וְאִם בְּטֻמְאָה - בְּטֻמְאָה."],[15,"","אִם בְּקֹדֶשׁ, מוֹשְׁכִים אוֹתוֹ לְאוֹתוֹ הַצַּד וְנִדְבָּק בּוֹ לְמַעְלָה וְנַעֲשֶׂה מְמֻנֶּה שַׁמָּשׁ לְשַׁמֵּשׁ לִפְנֵי הַקָּבָּ\"ה בֵּין אוֹתָם שְׁאָר מַלְאָכִים. כְּמוֹ שֶׁכָּךְ נִדְבָּק לְמַעְלָה וְעוֹמֵד בֵּין אוֹתָם קְדוֹשִׁים, שֶׁכָּתוּב (זכריה ג) וְנָתַתִּי לְךְ מַהְלְכִים בֵּין הָעֹמְדִים הָאֵלֶּה."],[16,"","כָּךָ גַּם כְּמוֹ זֶה. אִם בְּטֻמְאָה, מוֹשְׁכִים אוֹתוֹ לְאוֹתוֹ הַצַּד וְנַעֲשֶׂה כְּאֶחָד מֵהֶם לְהִדָּבֵק עִמָּם, וְהֵם נִקְרָאִים נִזְקֵי בְּנֵי אָדָם. וּבְאוֹתָהּ שָׁעָה שֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, לוֹקְחִים אוֹתוֹ וְשׁוֹאֲבִים אוֹתוֹ לַגֵּיהִנֹּם בְּאוֹתוֹ מָקוֹם שֶׁדָּנִים אֶת בְּנֵי הַטֻּמְאָה שֶׁטִּמְאוּ עַצְמָם וְרוּחָם, וְאַחַר כָּךְ נִדְבָּק בָּהֶם, וְהוּא מַזִּיק כְּאֶחָד מֵאוֹתָם מַזִּיקֵי הָעוֹלָם."],[17,"","אָמַרְתִּי לָהֶם, בָּנַי, דָּבָר זֶה קָרוֹב לְדִבְרֵי תוֹרָה, אֲבָל יֵשׁ לָכֶם לְהִתְרַחֵק (מתוך) מֵאוֹתָם הַסְּפָרִים (הללו) כְּדֵי שֶׁלֹּא יִסְטֶה לִבְּכֶם לָעֲבוֹדוֹת הַלָּלוּ וּלְכָל אוֹתָם הַצְּדָדִים שֶׁאָמַר כָּאן שֶׁמָּא חַס וְשָׁלוֹם (לא) תִּסְטוּ מֵאַחַר עֲבוֹדַת הַקָּבָּ\"ה,"],[18,"","שֶׁהֲרֵי כָּל הַסְּפָרִים הַלָּלוּ מַטְעִים אֶת בְּנֵי הָאָדָם, מִשּׁוּם שֶׁבְּנֵי קֶדֶם הָיוּ חֲכָמִים, וִירֻשַּׁת הַחָכְמָה הַזּוֹ יָרְשׁוּ מֵאַבְרָהָם שֶׁנָּתַן לִבְנֵי הַפִּילַגְשִׁים, שֶׁכָּתוּב (בראשית כה) וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ בְּעוֹדֶנּוּ חַי קֵדְמָה אֶל אֶרֶץ קֶדֶם. וְאַחַר כָּךְ נִמְשְׁכוּ בְּאוֹתָהּ חָכְמָה לְכַמָּה צְדָדִים."],[19,"","אֲבָל זֶרַע יִצְחָק, חֶלְקוֹ שֶׁל יַעֲקֹב, לֹא כָּךְ, שֶׁכָּתוּב (שם) וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק. זֶהוּ חֵלֶק הַקָּדוֹשׁ שֶׁל הָאֱמוּנָה שֶׁבָּהּ נִדְבַּק אַבְרָהָם וְיָצָא מֵאוֹתוֹ גוֹרָל וּמֵאוֹתוֹ הַצַּד. מַה כָּתוּב בְּיַעֲקֹב? (שם כח) וְהִנֵּה ה' נִצָּב עָלָיו, וְכָתוּב וְאַתָּה יַעֲקֹב עַבְדִּי וְגוֹ'. מִשּׁוּם כָּךְ צָרִיךְ הָאָדָם לְהִמָּשֵׁךְ אַחַר הַקָּבָּ\"ה וּלְהִדָּבֵק בּוֹ תָּמִיד, שֶׁכָּתוּב (דברים י) וּבוֹ תִדְבָּק."],[20,"","בֹּא רְאֵה, (תהלים כד) מִי יַעֲלֶה בְּהַר ה' וְגוֹ'. אַחַר כָּךְ חָזַר וּפֵרַשׁ, נְקִי כַפַּיִם. שֶׁלֹּא עוֹשֶׂה בְיָדָיו צֶלֶם, וְלֹא מַחֲזִיק עִמָּהֶם בְּמַה שֶּׁלֹּא צָרִיךְ. וְעוֹד, שֶׁלֹּא נִטְמָא בָהֶם וְלֹא מְטַמֵּא בָהֶם אֶת הַגּוּף כְּמוֹ אוֹתָם שֶׁמְּטַמְּאִים אֶת עַצְמָם בַּיָּדַיִם לְהִטָּמֵא, וְזֶה הוּא נְקִי כַפַּיִם וּבַר לֵבָב, כְּמוֹ זֶה שֶׁלֹּא מוֹשֵׁךְ אֶת רְצוֹנוֹ וְלִבּוֹ לַצַּד הָאַחֵר אֶלָּא לְהִמָּשֵׁךְ אַחַר עֲבוֹדַת הַקָּבָּ\"ה."],[21,"","אֲשֶׁר לֹא נָשָׂא לַשָּׁוְא נַפְשׁוֹ. כָּתוּב נַפְשׁוֹ וְנִקְרָא נַפְשִׁי, וַהֲרֵי פֵּרְשׁוּהָ, נַפְשִׁי - זוֹ נֶפֶשׁ דָּוִד, צַד הָאֱמוּנָה. נַפְשׁוֹ - זוֹ נֶפֶשׁ הָאָדָם מַמָּשׁ. מִשּׁוּם שֶׁכַּאֲשֶׁר יָצָא מִן הָעוֹלָם הַזֶּה וְנַפְשׁוֹ תִּתְעַלֶּה בְּמַעֲשִׂים שֶׁכְּשֵׁרִים, עַל מַה שֶּׁיִּתְקַיֵּם בָּהֶם לָלֶכֶת בֵּין כָּל אוֹתָם הַקְּדוֹשִׁים, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קטז) אֶתְהַלֵּךְ לִפְנֵי ה' בְּאַרְצוֹת הַחַיִּים. וּמִשּׁוּם שֶׁלֹּא נָשָׂא לַשָּׁוְא נַפְשִׁי, יִשָּׂא בְרָכָה מֵאֵת ה' וְגוֹ'."],[22,"","בֹּא רְאֵה, אַחַר שֶׁנִּמּוֹל אַבְרָהָם, הָיָה יוֹשֵׁב וְכוֹאֵב, וְהַקָּבָּ\"ה שָׁלַח אֵלָיו שְׁלֹשָׁה מַלְאָכִים בְּגִלּוּי לְהַקְדִּים לוֹ שָׁלוֹם. וְאִם תֹּאמַר, שֶׁהֲרֵי בְּנִגְלֶה וְכִי מִי יָכוֹל לִרְאוֹת מַלְאָכִים, וַהֲרֵי כָּתוּב (שם קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'?"],[23,"","אֶלָּא וַדַּאי שֶׁרָאָה אוֹתָם שֶׁיָּרְדוּ לָאָרֶץ כְּמוֹ בְּנֵי אָדָם. וְלֹא יִקְשֶׁה לְךְ זֶה, שֶׁהֲרֵי הֵם וַדַּאי רוּחוֹת קְדוֹשׁוֹת, וּבְשָׁעָה שֶׁיּוֹרְדִים לָעוֹלָם, מִתְלַבְּשִׁים בַּאֲוִירִים וּבִיסוֹדוֹת שֶׁל גְּלָמִים, וְנִרְאִים לִבְנֵי אָדָם מַמָּשׁ כְּמַרְאֵה דְמוּתָם."],[24,"","וּבֹא וּרְאֵה, אַבְרָהָם רָאָה אוֹתָם כְּמַרְאֵה בְּנֵי אָדָם, וְאַף עַל גַּב שֶׁהָיָה כּוֹאֵב מִן הַמִּילָה, יָצָא וְרָץ אַחֲרֵיהֶם כְּדֵי לֹא לִגְרֹעַ (מה) שֶׁהָיָה עוֹשֶׂה מִקֹּדֶם לָכֵן."],[25,"","אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי שֶׁרָאָה אוֹתָם כְּמַרְאֶה שֶׁל מַלְאָכִים, מִמַּה שֶּׁכָּתוּב וַיֹּאמַר אֲדנָי, בְּאָלֶ\"ף דָּלֶ\"ת הַשְּׁכִינָה הָיְתָה בָּאָה, וְאֵלּוּ הָיוּ עַמּוּדִים שֶׁלָּהּ וְכִסֵּא אֵלֶיהָ, מִשּׁוּם שֶׁהֵם שְׁלֹשֶׁת הַגְּוָנִים שֶׁתַּחְתֶּיהָ."],[26,"","וְרָאָה כָּעֵת מִשּׁוּם שֶׁנִּמּוֹל מַה שֶּׁלֹּא רָאָה מִקֹּדֶם לָזֶה עַד שֶׁלֹּא נִמּוֹל. בַּתְּחִלָּה לֹא הָיָה יוֹדֵעַ, אֶלָּא שֶׁהֵם בְּנֵי אָדָם. אַחַר כָּךְ יָדַע שֶׁאוֹתָם מַלְאָכִים קְדוֹשִׁים הֵם וּבָאוּ אֵלָיו בִּשְׁלִיחוּת, בְּשָׁעָה שֶׁאָמְרוּ לוֹ אַיֵּ\"ה שָׂרָה אִשְׁתְּךְ וּבִשְּׂרוּ לוֹ בְּשׂוֹרַת יִצְחָק."],[27,"","אֵלָיו - הָאוֹתִיּוֹת נְקוּדוֹת אַיּ\"וֹ, וְסִימַן אַיּ\"וֹ רֶמֶז לְמַה שֶּׁלְּמַעְלָה, רֶמֶז לַקָּבָּ\"ה. וַיֹּאמֶר הִנֵּה בָאֹהֶל. כָּתוּב כָּאן הִנֵּה בָאֹהֶל, וְכָתוּב שָׁם (ישעיה לג) אֹהֶל בַּל יִצְעָן וְגוֹ'. בֹּא רְאֵה, כֵּיוָן שֶׁנָּקוּד אַיּ\"וֹ, לָמָּה כָּתוּב אַחַר כָּךְ אַיֵּה? אֶלָּא מִשּׁוּם שֶׁחִבּוּר שֶׁל זָכָר וּנְקֵבָה כְּאֶחָד סוֹד הָאֱמוּנָה. אָז אָמַר וַיֹּאמֶר הִנֵּה בָאֹהֶל. שָׁם הוּא הַקֶּשֶׁר שֶׁל הַכֹּל וְשָׁם הוּא נִמְצָא (ויאמר הנה באהל). אַיֵּה וְגוֹ'. וְכִי לֹא יָדְעוּ הַמַּלְאָכִים הָעֶלְיוֹנִים שֶׁשָּׂרָה הִנֵּה בָאֹהֶל? לָמָּה כָּתוּב אַיֵּה? אֶלָּא שֶׁלֹּא יוֹדְעִים בָּעוֹלָם הַזֶּה אֶלָּא מַה שֶּׁנִּמְסָר לָהֶם לָדַעַת."],[28,"","בֹּא רְאֵה, (שמות יב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם אֲנִי ה'. וְכִי כַּמָּה שְׁלִיחִים וּמַלְאָכִים יֵשׁ לַקָּבָּ\"ה? אֶלָּא מִשּׁוּם שֶׁהֵם לֹא הָיוּ יוֹדְעִים בֵּין טִפָּה שֶׁל בְּכוֹר לְאוֹתָהּ שֶׁלֹּא שֶׁל בְּכוֹר פְּרָט לַקָּבָּ\"ה לְבַדּוֹ."],[29,"","כְּמוֹ זֶה (יחזקאל ט) וְהִתְוִיתָ תָּו עַל מִצְחוֹת הָאֲנָשִׁים. וְלָמָּה צְרִיכִים? אֶלָּא מִשּׁוּם שֶׁהֵם לֹא יוֹדְעִים אֶלָּא רַק מַה שֶּׁנִּמְסָר לָהֶם לָדַעַת (יודעים), כְּמוֹ כָּל הַדְּבָרִים הַלָּלוּ שֶׁעָתִיד הַקָּבָּ\"ה לְהָבִיא עַל הָעוֹלָם. וּמָה הַטַּעַם? מִשּׁוּם שֶׁהַקָּבָּ\"ה מַעֲבִיר כְּרוּז בְּכָל הָרְקִיעִים בְּאוֹתוֹ דָבָר שֶׁעָתִיד לְהָבִיא עַל הָעוֹלָם."]]],[["כְּגַוְונָא דָא בְּשַׁעֲתָא דִּמְחַבְּלָא אִשְׁתְּכַח בְּעָלְמָא בָּעֵי בַּר נָשׁ לְאִתְכַּסְיָא בְּבֵיתֵיהּ וְלָא יִתְחֲזֵי בְּשׁוּקָא בְּגִין דְּלָא יִתְחַבֵּל, כְּמָא דְאַתְּ אָמֵר, (שמות י״ב:כ״ב) וְאַתֶּם לא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מִנַּיְיהוּ (דיכיל לאסתתרא, אין, אבל מקמי קודשא בהך הוא לא (ס\"א יכיל)) בָּעֵי לְאִסְתַּתְּרָא. מַה כְּתִיב, (ירמיהו כ״ג:כ״ד) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם יְיָ.","אַיֵּה שָׂרָה אִשְׁתֶּךָ, דְּלָא בָעוּ לוֹמַר קַמָּהּ, כֵּיוָן דְּאָמַר הִנֵּה בָאֹהֶל מִיָּד וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ כְּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךָ וְגו'. תָּא חֲזֵי, אוֹרַח אַרְעָא, דְּעַד לָא אַזְמִין אַבְרָהָם קַמַּיְיהוּ לְמֵיכַל לָא אָמְרוּ לֵיהּ מִידֵּי, בְּגִין דְּלָא יִתְחֲזֵי דִּבְגִין הַהִיא בְּשׂוֹרָה קָא אַזְמִין לְהוּ לְמֵיכַל, בָּתַר דִּכְתִיב וַיּאכֵלוּ כְּדֵין אָמְרוּ לֵיהּ הַהִיא בְּשׂוֹרָה.","וַיֹּאכֵלוּ, סָלְקָא דַּעְתָּךְ וְכִי מַלְאֲכֵי עִלָּאֵי אָכְלֵי, אֶלָּא בְּגִין יְקָרָא דְּאַבְרָהָם אִתְחֲזֵי הָכִי. אָמַר רַבִּי אֶלְעָזָר וַיֹּאכֵלוּ וַדַּאי, בְּגִין דְּאִנּוּן (קד א) אֶשָׁא דְּאָכִיל אֶשָׁא וְלָא אִתְחֲזֵי, וְכָל מַה דְּיָהַב לוֹן אַבְרָהָם אָכְלֵי בְּגִין דְּמִסִּטְרָא דְּאַבְרָהָם אָכְלֵי לְעֵילָא (דאכלי מההוא סטרא דלעילא).","תָּא חֲזֵי, כָּל מַה דְּאָכִיל אַבְרָהָם בְּטָהֳרָה אִיהוּ קָא אָכִיל וּבְגִין כָּךְ אַקְרִיב קַמַּיְיהוּ וְאָכְלֵי, וְנָטִיר אַבְרָהָם בְּבֵיתֵיהּ דַּכְיָא וּמְסָאֲבוּתָא, דְּאֲפִילּוּ בַּר נָשׁ דְּאִיהוּ מְסָאַב (לא יכיל לקרבא לביתיה כדין ידע אברהם דהא מסאב איהו ועביד) (נ\"א לא הוה משמש בביתיה, עד דעביד) לֵיהּ טְבִילָה, אוֹ עֲבִיד לֵיהּ לְנַטְרָא שִׁבְעָה יוֹמִין כְּדְקָא חָזֵי לֵיהּ בְּבֵיתֵיהּ, וְהָכִי הוּא וַדַּאי.","תָּא חֲזֵי כְּתִיב, (דברים כ״ג:י״א) אִישׁ אֲשֶׁר לא יִהְיֶה טָהוֹר מִקְרֶה לַיְלָה וְגו'. מַאי תַּקַנְתֵּיהּ, וְהָיָה לִפְנוֹת עֶרֶב יִרְחַץ בַּמָּיִם. אִעֲרַע בֵּיהּ טֻמְאָה אָחֳרָא כְּגוֹן זִיבָה אוֹ (נ\"א סגירו או נדה) סְגִירַת נִדָּה דְּהֲווּ תְּרִי מְסָאֲבוּ, לָא סַגְיָא לֵיהּ בְּהַהִיא טְבִילָה (בגין) בֵּין דְּאִעֲרַע בֵּיהּ קֶרִי קֹדֶם דְּקַבִּיל טֻמְאָה אָחֳרָא (בגין) בֵּין דְּאִעֲרַא בֵּיהּ לְבָתָר."],[[0,"כגוונא דא בשעתא וכו':","כעין זה בשעה שמחבל נמצא בעולם, צריך בן אדם להסתיר עצמו בביתו ולא יתראה בשוק, כדי שלא יחבל. כמו שאתה אומר, ואתם לא תצאו איש מפתח ביתו עד בקר. כי מן המלאכים שאפשר להסתר מהם, צריכים להסתר. אבל מלפני הקב\"ה, אינו צריך להסתר. מה כתוב. אם יסתר איש במסתרים ואני לא אראנו נאם ה'."],[1,"איה שרה אשתך וכו':","הוקשה לו למה שאלו עליה, כיון שגם אחר ששמעו שהיא באהל, לא נכנסו שמה לבשר לה, אלא שבשרו לאברהם בהיותם בחוץ. ומשיב ע\"ז. \u0003דלא בעו. לומר קמה\u0004 וכו' שלא רצו לומר הבשורה בפניה, ולפיכך, כיון שאמר הנה באהל מיד ויאמר שוב אשוב וכו' כי נתכוונו ששרה לא תשמע. בוא וראה, דרך ארץ הוא, שמטרם שהזמינם אברהם לאכול לא אמרו לו כלום, שלא יתראה, שמשום הבשורה שבשרו לו, הזמינם לאכול. ועל כן, אחר שכתוב ויאכלו, אז אמרו לו הבשורה."],[2,"ויאכלו, סלקא דעתך וכו':","שואל. כתוב ויאכלו, וכי יעלה זה על הדעת, וכי מלאכים עליונים אוכלים. ומשיב, אלא משום כבודו של אברהם, נראה כך, שאכלו. כלומר שעשו את עצמם כאלו אכלו. ר' אלעזר אמר שאכלו ממש. משום שהם אש אוכלה אש. ולא שהיה נראה כאוכלים. וכל מה שנתן להם אברהם אכלו, משום שמצד אברהם אכלו למעלה. כלומר המשכת החסדים ה\"ס אכילה שלמעלה. ואברהם ה\"ס החסד, על כן כל מה שנתן להם ממדתו מדת החסד אכלו. כי כן דרך אכילתם למעלה בשמים."],[3,"ת\"ח כל מה דאכיל וכו':","בוא וראה, כל מה שאכל אברהם היה אוכל בטהרה. ומשום זה, הקריב לפני המלאכים ואכלו. ושמר אברהם בביתו טהרה וטומאה, ואדם טמא לא היה אפילו משמש בביתו עד שעשה לו טבילה, אם היה בטומאה קלה. או עשה לו שישמור שבעה ימים בביתו כראוי, אם היה בטומאה חמורה. ואח\"כ עשה לו טבילה."],[4,"ת\"ח כתיב וכו':","בוא וראה. כתוב, איש אשר לא יהיה טהור מקרה לילה. מה תיקונו. והיה לפנות ערב ירחץ במים. אם קרה לו טומאה אחרת חמורה, דהיינו זיבה או צרעת, או נדה. שיש לו ב' טומאות, אינו מספיק לו אותו טבילה שטבל לקריו. באותו יום לפנות ערב, אלא שצריך לשמור שבעה ימים ואח\"כ יטבול שנית, ואין הפרש בזה, בין שקרה לו הקרי טרם שקבל טומאה האחרת, ובין שקרה לו לאחר כך."]],[[0,"","כְּגוֹן זֶה בְּשָׁעָה שֶׁהַמַּשְׁחִית נִמְצָא בָעוֹלָם, צָרִיךְ בֶּן אָדָם לְהִסְתַּתֵּר בְּבֵיתוֹ וְלֹא יִהְיֶה נִרְאֶה בַּשּׁוּק כְּדֵי שֶׁלֹּא יֻשְׁחַת, כְּמוֹ שֶׁנֶּאֱמַר (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר. מֵאֵלּוּ שֶׁיָּכוֹל לְהִסְתַּתֵּר כֵּן, אֲבָל מִלִּפְנֵי הַקָּבָּ\"ה לֹא (ס\"א יכול) צָרִיךְ לְהִסְתַּתֵּר. מַה כָּתוּב? (ירמיה כג) אִם יִסָּתֵר אִישׁ בַּמִּסְתָּרִים וַאֲנִי לֹא אֶרְאֶנּוּ נְאֻם ה'."],[1,"","אַיֵּה שָׂרָה אִשְׁתְּךְ, שֶׁלֹּא רָצוּ לוֹמַר לְפָנֶיהָ. כֵּיוָן שֶׁאָמַר הִנֵּה בָאֹהֶל, מִיָּד - וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךְ וְגוֹ' בּא רְאֵה דֶּרֶךְ אֶרֶץ, שֶׁעַד שֶׁלֹּא הִזְמִין אַבְרָהָם לִפְנֵיהֶם לֶאֱכֹל, לֹא אָמְרוּ לוֹ דָּבָר, כְּדֵי שֶׁלֹּא יֵרָאֶה שֶׁמִּשּׁוּם אוֹתָהּ בְּשׂוֹרָה הִזְמִין אוֹתָם לֶאֱכֹל. אַחַר שֶׁכָּתוּב וַיֹּאכְלוּ, אָז אָמְרוּ לוֹ אוֹתָהּ בְּשׂוֹרָה."],[2,"","וַיֹּאכְלוּ,? , וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁמַּלְאָכִים עֶלְיוֹנִים אוֹכְלִים? אֶלָּא בִּשְׁבִיל כְּבוֹדוֹ שֶׁל אַבְרָהָם נִרְאֶה כָּךְ. אָמַר רַבִּי אֶלְעָזָר, וַיֹּאכְלוּ וַדַּאי, מִשּׁוּם שֶׁהֵם אֵשׁ אוֹכֶלֶת אֵשׁ וְלֹא נִרְאִים, וְכָל מַה שֶּׁנָּתַן לָהֶם אַבְרָהָם אָכְלוּ, מִשּׁוּם שֶׁמִּצַּד אַבְרָהָם אוֹכְלִים לְמַעְלָה (שאוכלים מאותו צד שלמעלה)."],[3,"","בֹּא רְאֵה, כָּל מַה שֶּׁאָכַל אַבְרָהָם, הוּא אָכַל בְּטָהֳרָה, וְלָכֵן הִקְרִיב לִפְנֵיהֶם וְאָכְלוּ, וְאַבְרָהָם שָׁמַר בְּבֵיתוֹ טֻמְאָה וְטָהֳרָה שֶׁאֲפִלּוּ בֶּן אָדָם שֶׁהוּא טָמֵא (לא יכל להתקרב לביתו, אז ידע אברהם שזה טמא הוא, ועשה) (לא היה משמש בביתו, עד שעשה) לוֹ טְבִילָה, אוֹ עָשָׂה לוֹ לִשְׁמֹר שִׁבְעָה יָמִים כָּרָאוּי לוֹ בְּבֵיתוֹ, וְכָךְ זֶה בְּוַדַּאי."],[4,"","בֹּא רְאֵה, כָּתוּב (דברים כג) אִישׁ אֲשֶׁר לֹא יִהְיֶה טָהוֹר מִקְּרֵה לָיְלָה וְגוֹ'. מַה תַּקָּנָתוֹ? וְהָיָה לִפְנוֹת עֶרֶב יִרְחַץ בַּמָּיִם. אֵרְעָה בּוֹ טֻמְאָה אַחֶרֶת, כְּמוֹ זִיבָה (טמאת צרעת או נדה) אוֹ טֻמְאַת נִדָּה שֶׁהָיוּ שְׁתֵּי טֻמְאוֹת, לֹא מַסְפִּיק לוֹ בְּאוֹתָהּ טְבִילָה (משום) בֵּין שֶׁאֵרַע לוֹ קֶרִי קֹדֶם שֶׁקִּבֵּל טֻמְאָה אַחֶרֶת (משום) בֵּין שֶׁאֵרַע לוֹ אַחַר כָּךְ."]]],[["וְאַבְרָהָם וְשָׂרָה הֲווּ מְתַקְּנֵי טְבִילָה לְכֻלְהוּ, אִיהוּ לְגַבְרֵי וְאִיהִי לְנַשֵּׁי. מַאי טַעְמָא אִעֲסַק אַבְרָהָם לְדַכָּאָה לִבְנִי נָשָׁא, בְּגִין דְּאִיהוּ טָהוֹר וְאִקְרֵי טָהוֹר. דִּכְתִיב, (איוב י״ד:ד׳) מִי יִתֵּן טָהוֹר מִטָּמֵא לא אֶחָד. טָהוֹר דָּא אַבְרָהָם דְּנָפַק מִתֶּרַח.","רַבִּי שִׁמְעוֹן אָמַר בְּגִין לְתַקָּנָא הַהוּא דַּרְגָּא דְּאַבְרָהָם, וּמַאן אִיהוּ מַיִ\"ם. בְגִין כָּךְ אַתְקִין לְדַכָּאָה בְּנִי עָלְמָא בְּמַיָא. וּבְשַׁעֲתָא דְּאַזְמִין לַמַּלְאָכִין, שֵׁירוּתָא דְּמִלּוֹי מַה כְּתִיב יוּקַח נָא מְעַט מַיִם. בְּגִין לְאִתְתַּקְּפָא בְּהַהוּא דַּרְגָּא דְמַיִין שָׁרָאן בָּהּ.","וּבְגִינֵי כָךְ הֲוָה מְדַכֵּי לְכָל בְּנֵי נָשָׁא מִכֹּלָּא. מְדַכֵּי לוֹן מִסִּטְרָא דְּעֲבוֹדָה זָרָה, וּמְדַכֵּי לוֹן מִסִּטְרָא דִּמְסָאֳבָא, וְכַמָּה דְּאִיהוּ מְדַכֵּי לְגוּבְרִין הָכִי נָמֵי שָׂרָה מְדַכַּאת לְנָשִׁין, וְאִשְׁתַּכָּחוּ כֻּלְהוּ דְּאַתְיָין לְגַבַּיְיהוּ דָּכְיָין מִכֹּלָּא.","תָּא חֲזֵי, אִילָנָא נָטַע אַבְרָהָם בְּכָל אֲתַר דְּדִיּוּרֵיהּ תַּמָּן, וְלָא הֲוָה סָלִיק בְּכָל אֲתַר כְּדְקָא יְאוּת, בַּר בְּשַׁעֲתָא דְּדִיוּרֵיהּ בְּאַרְעָא דִּכְנָעַן, וּבְהַהוּא אִילָנָא הֲוָה יָדַע מַאן דְּאִתְאַחִיד בֵּיה בְּקוּדְשָׁא בְּרִיךְ הוּא וּמַאן דְּאִתְאַחִיד בְּעֲבוֹדָה זָרָה.","מַאן דְּאִתְאַחִיד בְּקוּדְשָׁא בְּרִיךְ הוּא, אִילָנָא הֲוָה פָּרִישׂ עַנְפּוֹי וְחֲפֵי עַל רֵישֵׁיהּ וְעֲבִיד עֲלֵיהּ צִלָּא יָאֶה, וּמַאן דְּאִתְאַחִיד בְּסִטְרָא דְּעֲבוֹדָה זָרָה הַהוּא אִילָנָא הֲוָה אִסְתַּלַּק וְעַנְפּוֹי הֲווּ סְלִיקִין לְעֵילָא. כְּדֵין הֲוָה יָדַע אַבְרָהָם וְאַזְהִיר לֵיהּ, וְלָא אַעֲדֵי מִתַּמָּן עַד דְּאִתְאַחִיד בִּמְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא,","וְהָכִי מַאן דְּאִיהוּ דַּכְיָא (ד\"א ל\"ג הכי) מְקַבֵּל לֵיהּ אִילָנָא. מַאן דְּאִיהוּ מְסָאַב לָא מְקַבֵּל לֵיהּ. כְּדֵין יָדַע אַבְרָהָם וּמְדַכֵּי לוֹן בְּמַיָא.","וּמַעֲיָינָא דְמַיָא הֲוָה תְּחוֹת הַהוּא אִילָנָא, וּמַאן דְּצָרִיךְ טְבִילָה מִיָּד מַיִין סָלְקִין לְגַבֵּיהּ, וְאִילָנָא אִסְתַּלְּקִין עַנְפּוֹי, כְּדֵין יָדַע אַבְרָהָם דְּאִיהוּ מְסָאָבָא וּבָעֵי טְבִילָה מִיָּד, וְאִם לָאו מַיָא נְגִיבָן כְּדֵין יָדַע דְּבָעֵי לְאִסְתָּאֳבָא וּלְאִסְתַמְרָא שִׁבְעָה יוֹמִין.","תָּא חֲזֵי, דְּאֲפִילּוּ בְּשַׁעֲתָא דְּאַזְמִין לוֹן לְמַּלְאָכִין אָמַר לוֹן וְהִשָּׁעֲנוּ תַּחַת הָעֵץ בְּגִין לְמֶחמֵי וּלְמִבְדַּק בְּהוּ, וּבְהַהוּא אִילָנָא הֲוָה בָּדִיק לְכָל בְּנֵי עָלְמָא. וְרָזָא (לקבל) בְּגִין קוּדְשָׁא בְּרִיךְ הוּא קָא (עבד) אָמַר דְּאִיהוּ אִילָנָא דְחַיֵּי לְכֹלָּא, וּבְגִין כָּךְ וְהִשָּׁעֲנוּ תַּחַת הָעֵץ וְלֹא תַּחַת עֲבוֹדָה זָרָה.","וְתָּא חֲזֵי, כַּד חָב אָדָם, בְּעֵץ הַדַּעַת טוֹב וָרָע חָב, דִּכְתִיב וּמֵעֵץ הַדַּעַת וְגו' וְאִיהוּ בֵּיהּ חָב וְגָרַם מוֹתָא לְעָלְמָא. מַה כְּתִיב וְעַתָּה פֶּן יִשְׁלַח יָדוֹ וְלָקַח גַּם מֵעֵץ הַחַיִּים וְגו'. (וגרם מותא לכל בני עלמא) וְכַד אֲתָא אַבְרָהָם בְּאִילָנָא אָחֳרָא אַתְקִין עָלְמָא דְּהוּא אִילָנָא דְּחַיֵּי וְאוֹדַע מְהֵימְנוּתָא לְכָל בְּנֵי עָלְמָא:","\u0003מדרש הנעלם\u0004 אָמַר רַבִּי חִיָּיא אָמַר רַב אִי הֲוִינָא מִסְתַּכְּלִין בְּפָרָשָׁתָא דָּא נִסְתַּכֵּל בְּחָכְמָתָא, אִי עִנְיָינָא דְּנִשְׁמָתָא הִיא לָאו רֵישָׁא סוֹפָא וְלָאו סוֹפָא רֵישָׁא, וְאִי עִנְיָינָא לִפְטִירַת אִינִישׁ מֵעָלְמָא הִיא, נִסְתּוֹר כָּל פַּרְשָׁתָא אוֹ נוֹקִים פַּרְשָׁתָא בְּהַאי אוֹ בְּהַאי. מַהוּ יוּקַח נָא מְעַט מַיִם וְרַחֲצּוּ רַגְלֵיכֶם וְגו' וְאֶקְחָה פַת לֶחֶם וְגו' וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה וְגו' וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגו' וַיִּקַּח חֶמְאָה וְחָלָב וְגו'.","כַּד אֲתָא רַב דִּימִי אָמַר לא מָצְּאָה הַנְּשָׁמָה תּוֹעֶלֶת לַגּוּף אִלְּמָלֵא מַה שֶּׁרָמַז בְּכָאן רְמֶז הַקָּרְבָּנוֹת. בָּטְלוּ הַקָּרְבָּנוֹת לֹא בָּטְלָה הַתּוֹרָה, הַאי דְּלָא אִעֲסַק בַּקָּרְבָּנוֹת לִיעֲסַק בַּתּוֹרָה וְיִתְהַנֵּי לֵיהּ יַתִּיר,","דְּאָמַר רַבִּי יוֹחָנָן כְּשֶׁפֵּרַשׁ הַקָּדוֹשׁ בָּרוּךְ הוּא הַקָּרְבָּנוֹת אָמַר משֶׁה רִבּוֹנוֹ שֶׁל עוֹלָם תִּינַח בִּזְמַן שֶׁיִּהְיוּ יִשְׂרָאֵל עַל אַדְמָתָם, כֵּיוָן שֶׁיִּגְלוּ מֵעַל אַדְמָתָם מַה יַּעֲשׂוּ, אָמַר לוֹ משֶׁה, יַעַסְקוּ בַּתּוֹרָה ואֲנִי מוֹחֵל לָהֶם בִּשְׁבִילָהּ יוֹתֵר מִכָּל הַקָּרְבָּנוֹת שֶׁבָּעוֹלָם שֶׁנְּאֱמַר (ויקרא ז׳:ל״ז) זֹאת הַתּוֹרָה לָעוֹלָה לַמִּנְחָה וגו'. כְּלוֹמַר זֹאת הַתּוֹרָה בִּשְׁבִיל עוֹלָה בִּשְׁבִיל מִנְחָה בִּשְׁבִיל חַטָאת בִּשְׁבִיל אָשָׁם.","אָמַר רַבִּי כְּרוּסְפְּדָאי הַאי מַאן דְּמַדְכַּר בְּפוּמֵיהּ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת דְּקָרְבָּנַיָא עִנְיָינָא וְתִקְרוּבְתָּא וִיכַוִּון בְּהוּ, בְּרִית כְּרוּתָה הוּא דְּאִנּוּן מַלְאָכַיָא דְּמַדְכְּרִין חוֹבֵיהּ לְאַבְאָשָׁא לֵיהּ דְּלָא יָכְלִין לְמֶעְבַּד לֵיהּ אִלְּמָלֵא טִיבוּ.","וּמַאן יוֹכַח הַאי פַּרְשָׁתָא יוֹכַח, דְּכֵיוָן דְּאָמַר והִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו, מַהוּ עָלָיו, לְעַיֵּין בְּדִינֵיהּ, כֵּיוָן דְּחָמָא נִשְׁמָתָא דְּצַּדִּיקַיָא כָּךְ, מַה כְּתִיב וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה וגו'. מַהוּ הָאֹהֱלָה בֵּית הַמִּדְרָשׁ. וּמַהוּ אוֹמֵר מַהֲרִי שְׁלשׁ סְאִים, עִנְיַן הַקָּרְבָּנוֹת, וְנִשְׁמָתָא מִתְכַּוְּונְת בְּהוּ, הֲדָא הוּא דִכְתִיב וְאֶל הַבָּקָר רָץ אַבְרָהָם. וּכְדֵין נַיְיחָא לְהוּ ולָא יָכְלִין לְאַבְאָשָׁא לֵיהּ.","רַבִּי פִּנְחָס פָּתַח קְרָא דִּכְתִיב, (במדבר י״ז:י״א) וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם וּכְתִיב וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְגו' וּכְתִיב וַתֵּעָצַּר הַמַּגֵּפָה. כְּתִיב הָכָא מַהֵר וּכְתִיב הָתָם מַהֲרִי שְׁלשׁ סְאִים. מַה לְּהַלָּן קָרְבָּן לְאִשְׁתְּזָבָא אַף כָּאן קָרְבָּן לְאִשְׁתְּזָבָא.","אָמַר רַבִּי פִּנְחָס זִמְנָא חָדָא הֲוִינָא אָזְלֵי בְאָרְחָא וַעֲרָעִית בֵּיהּ בְּאֵלִיָּהוּ, אֲמִינָא לֵיהּ, לֵימָא לִי מַר מִלָּה דְּמַעֲלֵי לִבְרִיָּיתָא, אָמַר לֵיהּ, קְיים גָּזַר קוּדְשָׁא בְּרִיךְ הוּא וְעָאלוּ קַמֵּיהּ כָּל אִלֵּין מַלְאָכַיָא דִּמְמַנָּן לְאַדְכָּרָא חוֹבֵי דְּבַּר נָשׁ, דִּי בְּעִדְנָא דְּיִדְכְּרוּן בְּנִי אֱנָשָׁא קָרְבָּנַיָא דְּמַנֵּי משֶׁה ושַׁוִּי לִבֵּיהּ וּרְעוּתֵיהּ בְּהוּ, דְּכֻלְהוּ יִדְכְּרוּן לֵיהּ לְטַב.","וְעוֹד בְּעִדָּנָא דִּיעֲרַע מוֹתָנָא בִּבְנֵי אֱנָשָׁא, קְיָימָא אִתְגְּזַר וכָרוֹזָא אַעֲבַר עַל כָּל חֵילָא דִשְׁמַיָא דְּאִי יִיעֲלוּן בְּנוֹהִי בְּאַרְעָא בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְיֵימְרוּן בִּרְעוּת נַפְשָׁא וְלִבָּא עִנְיָינָא דִקְטֹרֶת בּוּסְמִין דְּהֲווּ לְהוּ לְיִשְׂרָאֵל, דְּיִתְבַּטַל מוֹתָנָא מִנַּיְיהוּ.","אָמַר רַבִּי יִצְּחָק בֹּא וּרְאֵה מַה כְּתִיב וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה ותֵן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. אָמַר לֵיהּ אַהֲרֹן לָמָּה. אָמַר כִּי יָצָּא הַקֶּצֶּף מִלִּפְנֵי יְיָ וגו'. מַה כְּתִיב וַיָּרָץ אֶל תּוֹךְ הַקָּהָל וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם. וּכְתִיב וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַּר הַמַּגֵּפָה. ולָא יָכִיל מַלְאָכָא דִּמְחַבְּלָא לְשַׁלְּטָאָה וְנִתְבַּטְלָא מוֹתָנָא.","רַבִּי אַחָא אֲזַל לִכְפַר טַרְשָׁא אֲתָא לְגַבֵּי אוּשְׁפִּיזֵיהּ, לְחִישׁוּ עֲלַיְהוּ כָּל בְּנֵי מָתָא, אָמְרוּ גַּבְרָא רַבָּא אֲתָא הָכָא נֵזִּיל לְגַבֵּיהּ, אָתוּ לְגַבֵּיהּ, אָמְרוּ לֵיהּ לָא חָס עַל אוֹבָדָנָא, אָמַר לְהוּ מַהוּ. אָמְרוּ לֵיהּ דְּאִית שִׁבְעָה יוֹמִין דְּשָׁארֵי מוֹתָנָא בְּמָאתָא וכָל יוֹמָא אִתְתַּקַּף ולָא אִתְבַּטַל.","אָמַר לְהוּ נֵזִּיל לְבֵי כְנִשְׁתָּא וְנִתְבַּע רַחֲמֵי מִן קֳדָם קוּדְשָׁא בְּרִיךְ הוּא. עַד דְּהֲווּ אָזְלֵי, אָתוּ וְאָמְרוּ פְּלוֹנִי וּפְלוֹנִי מִיתוּ, וּפְלוֹנִי וּפְלוֹנִי נָטוּ לָמוּת. אָמַר לְהוּ רַבִּי אַחָא לֵית עִתָּא לְקָיְימָא הָכִי דְּשַׁעֲתָא דְחִיקָא.","אֲבָל אַפְרִישׁוּ מִנְכוֹן אַרְבְּעִין בְּנֵי נָשָׁא מֵאִנּוּן דְּזַכָּאִין יַתִיר. עֲשָׂרָה עֲשָׂרָה לְאַרְבְּעָה חוּלָקִין ואֲנָא עִמְּכוֹן, עֲשָׂרָה לְזִוְויָיתָא דְּמָאתָא, וַעֲשָׂרָה לְזִוְויָיתָא דְּמָאתָא, וְכֵן לְאַרְבַּע זִוְויָיתָא דְּמָאתָא. וְאָמְרוּ בִּרְעוּת נַפְשְׁכוֹן עִנְיָינָא דִקְטֹרֶת בּוּסְמִין. דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לְמשֶׁה ועִנְיָינָא דְּקָרְבָּנָא עִמֵּיהּ.","עֲבְדוּ כֵּן תְּלַת זִמְנִין וְאַעֲבָרוּ בְּכָל מָאתָא לְאַרְבַּע זִוְויָיתָא והֲווּ אָמְרִין כֵּן, לְבָתַר אָמַר לְהוּ נֵּזִיל לְאִנּוּן דְּאוֹשִׁיטוּ לְמֵימַת אַפְרִישׁוּ מִנַּיְיכוּ לְבָתֵּיהוֹן, ואִמְרוּ כְדֵין, וְכַד תְּסַיְּימוּ אִמְרוּן אִלֵּין פְּסוּקַיָיא (במדבר ט״ז:כ״ח) וַיֹּאמֶר משֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה ותֵן עָלֶיהָ אֵשׁ וְגו' וַיִּקַּח אַהֲרֹן וְגו' וַיַּעֲמֹד בֵּין הַמֵּתִים וְגו'. וכֵן עֲבְדוּ ואִתְבַּטַל מִנַּיְיהוּ.","שָׁמְעוּ הַהוּא קָלָא דְּאָמַר סִתְרָא סִתְרָא קַמַּיְיתָא אוֹחִילוּ לְעֵילָא דְּהָא דִּינָא דִּשְׁמַיָא לָא אַשְׁרֵי הָכָא דְּהָא יָדְעֵי לְבַטְלָא לֵיהּ. חָלַשׁ לִבֵּיהּ דְּרַבִּי אַחָא, אִדְמוּךְ, שָׁמַע דְּאֲמְרֵי לֵיהּ, כַּד עָבַדְתְּ דָּא עֲבִיד דָּא, זִיל ואֵימָא לוֹן דְּיַחְזְרוּן בִּתְשׁוּבָה דְּחַיָּיבִין אִנּוּן קַמָּאי. קָם ואַחֲזַר לְהוּ בִּתְשׁוּבָה שְׁלֵימָתָא, וְקַבִּילוּ עֲלַייהוּ דְּלָא יִתְבַּטְלוּן (צד א (ב)) מֵאוֹרַיְיתָא לְעָלַם, וְאַחֲלִיפוּ שְׁמָא דְּקַרְתָּא וקָארוּן לָהּ מָאתָא מַחְסֵיָא.","אָמַר רַבִּי יְהוּדָה לֹא דַּי לָהֶם לַצַּדִּיקִים שֶׁמְבַטְלִין אֶת הַגְּזִרָה אֶלָּא לְאַחַר כֵּן שֶׁמְבָרְכִין לָהֶם, תֵּדַע לָךְ שֶׁכֵּן הוּא, דְּכֵיוָן שֶׁהַנְּשָׁמָה אוֹמֶרֶת לַגּוּף מַהֲרִי שְׁלשׁ סְאִים וְגו' וְכָל אוֹתוֹ הָעִנְיָן וּמְבַטֵל אֶת הַדִּין, מַה כְּתִיב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ כְּעֵת חַיָּה הֲרֵי בְּרָכָה.","כֵּיוָן שֶׁרוֹאִים אוֹתָהּ הַמַּלְאָכִים שֶׁזֶּה לָקַח עֵצָּה לְנַפְשׁוֹ, מַה עוֹשִׂים, הוֹלְכִים אֵצֶּל הָרְשָׁעִים לְעַיֵּן בְּדִינָם וְלַעֲשׂוֹת בָּהֶם מִשְׁפָּט הֲדָא הוּא דִכְתִיב וַיָּקוּמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִיפוּ עַל פְּנִי סְדוֹם לִמְקוֹם הָרְשָׁעִים לַעֲשׂוֹת בָּהֶם מִשְׁפָּט.","הֲדָא הוּא דְּאָמַר רַבִּי יְהוּדָה כָּךְ דַּרְכּוֹ שֶׁל צַּדִּיק כֵּיוָן שֶׁרוֹאֶה שֶׁמְעַיְינִין בְּדִינוֹ אֵינוֹ מִתְאַחֵר לָשׁוּב וּלְהִתְפַּלֵל וּלְהַקְרִיב (על) חֶלְבּוֹ וְדָמוֹ לִפְנֵי צּוּרוֹ עַד שֶׁמִּסְתַּלְּקִין בַּעֲלֵי הַדִּין מִמֶּנּוּ.","דְּכֵיון שֶׁאָמַר וַיִּשָּׂא עֵינָיו וַיַּרְא והִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו, מַה כְּתִיב בַּנְּשָׁמָה, וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה. בְּחִפָּזוֹן וּבִמְהִירוּת בְּלֹא שׁוּם הַעְכָּבָה, מִיָּד מְמַהֶרֶת הַנְּשָׁמָה אֵצֶּל הַגּוּף לְהַחֲזִירוֹ לְמוּטָב וּלְבַקֵּשׁ בַּמֶּה שֶׁיִּתְכַּפֵּר לוֹ עַד שֶׁמִּסְתַּלְּקִין מִמֶּנּוּ בַּעֲלֵי הַדִּין.","רַבִּי אֱלִיעֶזֶר אוֹמֵר מַהוּ דְּאָמַר ואַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים. אֶלָּא כֵּיוָן שֶׁהַנְּשָׁמָה עוֹמֶדֶת בְּמַעֲלָתָהּ וְהַגּוּף נִשְׁאָר בָּאָרֶץ מִכַּמָּה שָׁנִים, בָּאִים בַּיָּמִים, שָׁנִים וְיָמִים הַרְבֵּה. וְחָדַל לָצֵּאת וְלָבֹא וְלַעֲבֹר אֹרַח כִּשְׁאָר כָּל אָדָם, אִתְבַּשַּׂר לְהַחֲיוֹת הַגּוּף.","מַהוּ אוֹמֵר אַחֲרֵי בְלוֹתִי הָיְתָה לִי עֶדְנָה, אַחֲרֵי בְלוֹתִי בֶּעָפָר מֵהַיּוֹם כַּמָּה שָׁנִים הָיְתָה לִי עֶדְנָה וְחִדּוּשׁ, ואֲדוֹנִי זָקֵן שֶׁהַיּוֹם כַּמָּה שָׁנִים שֶׁיָּצָּאת מִמֶּנִּי וְלֹא הִפְקִידַנִי.","וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר הֲיִפָּלֵא מֵיְיָ דָּבָר לַמּוֹעֵד. מַהוּ לַמּוֹעֵד. אוֹתוֹ הַיָּדוּעַ אֶצְּלִי לְהַחֲיוֹת הַמֵּתִים. וּלְשָׂרָה בֵן מְלַמֵּד שֶׁיִּתְחַדֵּשׁ כְּבֶן שָׁלשׁ שָׁנִים.","אָמַר רַבִּי יְהוּדָה בְּרַבִּי סִימוֹן כֵּיוָן שֶׁהַנְּשָׁמָה נִיזוֹנֶת מִזִּיוָהּ שֶׁל מַעְלָה, קוּדְשָׁא בְּרִיךְ הוּא אוֹמֵר לְאוֹתוֹ הַמַּלְאָךְ הַנִּקְרָא דומ\"ה, לֵךְ וּבַשֵּׂר לְגוּף פְּלוֹנִי שֶׁאֲנִי עָתִיד לְהַחֲיוֹתוֹ לַמּוֹעֵד שֶׁאֲנִי אֲחַיֶּה אֶת הַצַּדִּיקִים לֶעָתִיד לָבֹא. והוּא מֵשִׁיב אַחֲרֵי בְלוֹתִי הָיְתָה לִי עֶדְנָה. אַחֲרֵי בְלוֹתִי בֶּעָפָר ושָׁכַנְתִּי בָּאֲדָמָה וְאָכַל בְּשָׂרִי רִמָּה וְגוּשׁ עָפָר תִּהְיְה לִי חִדּוּשׁ.","קוּדְשָׁא בְּרִיךְ הוּא אוֹמֵר לַנְּשָׁמָה, הֲדָא הוּא דִכְתִיב וַיֹּאמֶר יְיָ אֶל אַבְרָהָם וְגו' הֲיִפָּלֵא מֵיְיָ דָּבָר לַמּוֹעֵד הַיָּדוּעַ אֶצְּלִי לְהַחֲיוֹת אֶת הַמֵּתִים, אָשׁוּב אֵלֶיךָ, אוֹתוֹ הַגּוּף שֶׁהוּא קָדוֹשׁ כְּבָרִאשׁוֹנָה מְחוּדָשׁ לִהְיוֹתְכֶם מַלְאָכִים קְדוֹשִׁים ואוֹתוֹ הַיּוֹם עָתִיד לְפָנַי לִשְׂמֹחַ בָּהֶם הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ל״א) יְהִי כְבוֹד יְיָ לְעוֹלָם יִשְׂמַח יְיָ בְּמַעֲשָׂיו, (ע\"כ מדרש הנעלם)","וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה. אָמַר רַבִּי יִצְחָק שׁוֹב אָשׁוּב, שׁוֹב יָשׁוּב מִבָּעֵי לֵיהּ, דְּהָא מַפְתְחָא דָּא לְמִפְקַד עֲקָרוֹת בִּידָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ וְלָא בִּידָא דִּשְׁלִיחָא אָחֳרָא.","כְּמָה דְּתָנִינָן תְּלַת מַפְתְּחָן אִנּוּן דְּלָא אִתְמְסָרוּ בִּידָא דִּשְׁלִיחָא. דְּחַיָּה וּתְחִיַּת הַמֵּתִים וּגְשָׁמִים. וְהוֹאִיל דְּלָא אִתְמְסָרוּ בִּידָא דִשְׁלִיחָא אַמַּאי כְּתִיב שׁוֹב אָשׁוּב. אֶלָּא וַדַּאי קוּדְשָׁא בְּרִיךְ הוּא דְּהֲוָה קָאִים עֲלַיְיהוּ אָמַר (ליה) מִלָּה, בְגִין כָּךְ כְּתִיב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ.","וְתָּא חֲזֵי, בְּכָל אֲתַר דִּכְתִיב וַיֹּאמֶר סְתָם אוֹ וַיִּקְרָא סְתָם הוּא מַלְאָכָא דִּבְרִית וְלָא אָחֳרָא. וַיֹּאמֶר דִּכְתִיב, (שמות ט״ו:כ״ו) וַיֹּאמֶר אִם שָׁמֹעַ תִּשְׁמַע וְגו' וַיֹּאמֶר וְלָא קָאֲמַר מַאן הוּא. וַיִּקְרָא דִּכְתִיב, (ויקרא א׳:א׳) וַיִּקְרָא אֶל משֶׁה וְלָא קָאֲמַר מַאן הֲוָה. אָמַר דִּכְתִיב, (שמות כ״ד:ט״ז) וְאֶל משֶׁה אָמַר וְגו' וְלָא אָמַר מַאן הֲוָה. (אוף הכי דכתיב ויאמר שוב אשוב ויאמר סתם ולא קאמר מאן הוה) אֶלָּא בְּכָל הַנֵּי מַלְאָכָא דִּבְרִית הֲוָה וְכֹלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא אִתְּמָר. וּבְגִין כָּךְ כְּתִיב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ וְגו'. וְהִנֵּה בֵן וְגו':"],[[0,"ואברהם ושרה וכו':","ואברהם ושרה היו מתקנים טבילה לכל אדם, הוא לאנשים והיא לנשים. מהו הטעם, שאברהם עסק לטהר בני אדם. ואומר משום שהוא טהור ונקרא טהור, שכתוב מי יתן טהור מטמא לא אחד. שטהור זה אברהם, שיצא מתרח שהוא טמא."],[1,"ר' שמעון אמר וכו':","רש\"א, על כן עסק אברהם בטבילה, כדי לתקן את המדרגה של אברהם. ומי היא מדרגתו. ואומר, שהוא מים, דהיינו חסדים, הנקראים מים. ומשום זה התקין לטהר בני העולם במים. וכן בשעה שהזמין המלאכים, תחילת דבריו, מה כתוב, יוקח נא מעט מים. והיינו כדי להתחזק במדרגה ההיא שמים שורים בה. דהיינו מדרגת החסד."],[2,"ובגיני כך וכו':","ומשום זה, היה מטהר כל בני האדם מכל, שטיהר אותם מצד עבודה זרה, וטיהר אותם מצד הטומאה. וכמו שהוא היה מטהר את האנשים כן היא היתה מטהרת את הנשים. ונמצאו כל אלו שבאו אליו, שהם טהורים מכל. הן מע\"ז והן מטומאה."],[3,"ת\"ח אילנא וכו':","בוא וראה, בכל מקום שאברהם גר, נטע שם אילן. ולא היה עולה בכל מקום כראוי, רק בשעה שגר בארץ כנען. ובאילן ההוא היה יודע, מי שנתאחד בו בהקב\"ה, ומי שנתאחד בעבודה זרה."],[4,"מאן דאתאחיד וכו':","מי שנתאחד בהקב\"ה האילן היה פורש ענפיו ומחפה על ראשו, ועושה עליו צל נאה. ומי שנתאחד בעבודה זרה, האילן היה מתעלה ממנו, וענפיו היו עולים למעלה, אז ידע אברהם שהוא עובד ע\"ז, והזהיר אותו, ולא הרפה ממנו עד שנתאחד באמונת הקב\"ה."],[5,"והכי מאן וכו':","וכן, מי שהוא טהור, מקבל אותו האילן, ומי שהוא טמא, האילן אינו מקבלו, ואז ידע אברהם שהוא טמא, ומטהרו במים."],[6,"ומעיינא דמיא וכו':","ומעיין של מים היה תחת האילן. ומי שצריך טבילה. מיד היו המים עולים כנגדו וענפיו של האילן מתעלים. אז ידע אברהם שהוא טמא, וצריך טבילה מיד, כלומר שהוא טמא רק טומאה קלה, שאינו צריך לחכות ז' ימים. ואם אינו צריך טבילה מיד, היו המים מתיבשים, אז ידע אברהם שהוא צריך עוד להיות טמא ולחכות ז' ימים."],[6,"","פנימיות הדברים. האילן ה\"ס עץ החיים שהוא ז\"א, דהיינו קו אמצעי. והמעיין שמתחתיו ה\"ס המסך דחירק, הנעשה כמעיין נובע, שמוציא קומת החסדים, שעל ידו הכריע את קו השמאל ונכלל בימין. כנ\"ל (דף י\"ד ד\"ה הורמנותא) וכל האיסורים והס\"א כגון עבודה זרה וטומאה וכו' באים מקו שמאל, כלומר מתוך שרוצים להשליט השמאל על הימין, ולהמשיך שפע השמאל ממעלה למטה. שהוא המקור לכל האיסורים שבעולם, כנודע. ונמצא הטמא, שנאחז בשמאל, שנוהג בו אותו התקון, כמו שהיה בעת יציאת קו השמאל, שהיה במחלוקת ובסתימת האורות עד שנמשך קומת החסדים על המסך דחירק שבקו אמצעי, שאז התגברו החסדים על קו השמאל, ונכנע ונכלל בקו הימין. (כנ\"ל דף ט\"ז ד\"ה וכבר) כן ממש, בהנכשל על ידי הס\"א, ונתדבק בקו שמאל להמשיך ממנו ממעלה למטה, שאין לו תקנה אלא לקבל את קומת החסדים מקו אמצעי, ואז הוא נכלל בימין וטהר. וז\"ש (באות ק\"ה) \u0003מאי תקנתיה, והיה לפנות ערב ירחץ במים.\u0004 כי הוא צריך לחזור ולהמשיך קו שמאל ולהמשיך את הכרעת קו האמצעי על ידי ביאה במים, שה\"ס קומת החסדים. היוצאת על מסך דחירק, שמתחת האילן. ובסוד לפנות ערב, חוזר וממשיך הארת השמאל. כי אין הארת השמאל לאור היום, (כנ\"ל בפרשת לך דף י\"ג ד\"ה ורזא) ובסוד ירחץ במים חוזר וממשיך קומת חסדים שבסוד קו אמצעי המכריע את הארת השמאל וכולל אותו בימין. כנ\"ל."],[6,"","ונודע שיש ב' נקודות בהנוקבא, אחת ממותקת בבינה, הנקראת \u0003מפתחא,\u0004 ואחת דמדת הדין מצמצום א' שהיא בלתי ממותקת בבינה, הנקראת \u0003מנעולא.\u0004 אשר הזוכה ודבק בקו אמצעי, נגנזת בשבילו הנקודה דמדת הדין, ונקודה דמדת הרחמים גלויה בהנהגה העליונה בעדו. בסוד \u0003זכי הא טב.\u0004 ואם אינו זוכה, אלא שמתדבק בשליטת השמאל, אז מתגלה הנקודה דמדת הדין בהנוקבא. שה\"ס צמצום הא' שהיה על המלכות שאינה ראויה לקבל אור ישר. ואז כל האורות פורחים ממנה. (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' ע\"ש). בסוד \u0003לא זכי הא רע.\u0004"],[6,"","ולפיכך יש ב' מיני טומאות. אחת \u0003טומאה קלה\u0004 כגון בעל קרי, שפירושו, שנאחז בקו שמאל, אבל לא כל כך עד שתגלה הנקודה דמנעולא בסוד \u0003לא זכי הא רע.\u0004 ולפיכך אינו חסר רק הכרעת קו האמצעי ע\"י קומת החסדים, ובא במים וטהר. והשניה הוא \u0003טומאה חמורה,\u0004 שפירושו, שעל ידי התדבקותו בשמאל כבר נתגלה הנקודה דמנעולא, המסלקת כל האורות מהנוקבא, כנ\"ל בסוד \u0003לא זכי הא רע.\u0004 ואז צריך תחילה להמתיק המלכות בבינה, בב' הבחינות, בקטנות ובגדלות, שה\"ס ספירת שבעה ימים."],[6,"","ולפיכך בטומאה קלה, אומר, \u0003ומאן דצריך טבילה מיד, מיין סלקין לגביה ואילנא אסתלקין ענפוי,\u0004 כי להיותו עוד דבוק בקו שמאל, שהיא טומאתו, לכן מעלה האילן את ענפיו, דהיינו שאינו עושה צל עליו. כי קו אמצעי בעת שמכליל ב' הקוין ימין ושמאל זה בזה, הוא עושה צל, דהיינו שמכסה על הג\"ר דג\"ר, (כנ\"ל בפרשת לך דף ט\"ז ד\"ה עוד) ולפיכך כשדבק בקו שמאל, אין לו צל כלל, וז\"ס שהאילן מסלק ענפיו ממנו. אבל \u0003מיין סלקין לגביה,\u0004 שהמעיין שמתחת האילן שה\"ס קו אמצעי מעלה אליו קומת חסדים הנמשך עליו, כדי שיבא מיד בהמים, ויכללו הקוין זה בזה וטהר. מה שאין כן בטומאה חמורה שנגלה עליו המנעולא, שאז המים שבמעיין מתיבשים, כלומר שאין זווג על המסך שבקו אמצעי להוציא קומת חסדים. כי מטעם גילוי המנעולא נפסק הזווג, כי כל עוד שהמנעולא גלויה בזו\"ן אינם ראוים לקבל אור העליון, כנ\"ל, וע\"כ נתיבש המעיין. עד שסופר שבעת ימים, דהיינו שחוזר וממתיק המלכות בבינה, בסוד שלישי ושביעי לקטנות ולגדלות, ואז חוזר הזווג על המסך שבקו האמצעי והמעיין חוזר לאיתנו, ואז ובא במים וטהר, כי אינו חסר עוד אלא לקבל הכרעת קו האמצעי הבאה עם הטבילה, כנ\"ל. אכן זה אמור רק במסך דחירק שבקו אמצעי דזו\"ן, אבל במסך דחירק דקו אמצעי שבבינה, אין המסך מחויב להתמתק במפתחא, אלא הזווג לקומת חסדים יוצא על בחינת מנעולא. והטעם הוא, מפני שמסך דמנעולא אינו פועל כלום לפגום למעלה ממקור הויתו, דהיינו למעלה מזו\"ן. כי צמצום הא' לא היה רק על המלכות לבדה, וכן על ז\"א המשמש עמה, אבל לא כלום בבינה."],[7,"ת\"ח דאפילו וכו':","בוא וראה, כי אפילו בשעה שהזמין המלאכים, אמר להם, והשענו תחת העץ. והוא כדי לראות ולבדוק אותם. כנ\"ל. ובאילן ההוא היה בודק לכל בני העולם. והסוד הוא, שבשביל הקב\"ה אמר זה, שה\"ס עץ החיים לכל, ומשום זה אמר להם והשענו תחת העץ, שהוא הקב\"ה, ולא תחת עבודה זרה."],[8,"ות\"ח כד חב וכו':","ובוא וראה, כשחטא אדם הראשון, חטא בעץ הדעת טוב ורע. שכתוב, ומעץ הדעת וגו', והוא חטא בו וגרם מות לכל העולם, מה כתוב, ועתה פן ישלח ידו ולקח גם מעץ החיים ואכל וחי לעולם. וכשבא אברהם, תקן את העולם בעץ האחר, שהוא עץ החיים, והודיע האמונה לכל בני העולם."],[9,"א\"ר חייא אמר רב וכו':","אר\"ח אמר רב. אם אני מסתכלים בפרשה, צריכים להסתכל בחכמה. אם תפרשה בעניני נשמה, כמו שהתחיל לבאר (לעיל באות י\"ט) אין התחילה כהסוף, ואין הסוף כמו התחילה. כלומר כי קשה לבאר גם סוף הפרשה בעניני נשמה, דהיינו את הפסוקים יוקח נא מעט מים וגו'. ונמצא אין סופה כתחילתה, ואין תחילתה כסופה. ואם תפרשה בענין פטירת האדם מן העולם (כנ\"ל באות ל') נמשיך בכל הפרשה בדרך הזה. ובין שנעמיד הפרשה בפירוש זה או בזה, צריכים להמשיך מהו הפירוש של יוקח נא מעט מים ורחצו רגליכם וגו'. מהו ואקחה פת לחם וגו'. מהו וימהר אברהם האהלה אל שרה וגו'. מהו ואל הבקר רץ אברהם וגו'. מהו ויקח חמאה וחלב וגו'."],[10,"כד אתי ר' דימי וכו':","כאשר בא ר' דימי אמר, לא מצאה הנשמה תועלת לגוף, אלמלא מה שרמז בכאן רמז הקרבנות, בפסוקים הנ\"ל יוקח נא מעט מים וגו', והגם שבטלו הקרבנות, כי הבהמ\"ק נחרב, לא בטלה התורה, ויוכל לעסוק בתורה, ויועיל לו עוד יותר מקרבנות."],[12,"א\"ר כרוספדאי וכו':","אר\"כ, כל מי שמזכיר בפיו בבתי כנסיות ובבתי מדרשות ענין קרבנות והקרבה, ומכוון בהם, ברית כרותה הוא, שאלו המלאכים המזכירים עונותיו להרע לו, אינם יכולים לעשות לו רק טוב."],[13,"ומאן יוכח וכו':","ומי מוכיח זה, פרשה זו מוכיחה לנו זה. כי כיון שאמר, והנה שלשה אנשים נצבים עליו, מהו \u0003עליו,\u0004 היינו לעיין בדינו, כיון שנשמת הצדיק ראתה זה, מה כתוב, וימהר אברהם האהלה, מהו האהלה. הוא בית המדרש. ומהו אומר. מהרי שלש סאים, שהוא ענין הקרבנות, והנשמה מכוונת בהם, וז\"ש ואל הבקר רץ אברהם. ואז יש להם, נחת ואינם יכולים להרע לו."],[14,"ר' פנחס פתח וכו':","ר\"פ פתח המקרא. שכתוב והנה החל הנגף בעם. וכתוב, ויאמר משה אל אהרן קח את המחתה, וגו', וכתיב ותעצר המגפה, וילפינן גזירה שוה, כתוב כאן מהר, שכתוב והולך \u0003מהרה\u0004 אל העדה, כתוב שם \u0003מהרי\u0004 שלש סאים, מה שם הוא קרבן להנצל, אף כאן הוא קרבן להנצל. וזהו ראיה לפירושו של ר' כרוספדאי."],[15,"א\"ר פנחס וכו':","פעם אחת הייתי מהלך בדרך, ופגשתי את אליהו, אמרתי לו, יאמר אדוני לי דבר המועיל לבריות. אמר לי, ברית כרת הקב\"ה, כשנכנסים לפניו כל אלו המלאכים הממונים להזכיר עונותיו של אדם, בעת שיזכירו בני אדם את הקרבנות שצוה משה, ומשימים לבם ורצונם בהם, שכולם שכל המלאכים, יזכירו אותו לטוב."],[16,"ועוד, בעידנא וכו':","ועוד אמר לי אליהו, בשעה שיקרה מגפה בבני אדם, ברית נכרת, וכרוז מעביר, על כל צבאות השמים, שאם בניו יכנסו בבתי כנסיות ובבתי מדרשות שבארץ, ויאמרו ברצון הלב ונפש, את הענין של קטורת הסמים, שהיו להם לישראל, יתבטל המגפה מהם."],[17,"א\"ר יצחק בוא וכו':","אר\"י, בוא וראה מה כתוב, ויאמר משה אל אהרן קח את המחתה וגו' אמר לו אהרן למה זה. אמר משה כי יצא הקצף מלפני ה' וגו'. מה כתיב וירץ אל תוך הקהל וגו' ותעצר המגפה, ומלאך המחבל לא יכול לשלוט ונתבטל המגפה, הרי מפורש שהקטורת מבטל את המגפה."],[18,"ר' אחא אזל וכו':","ר' אחא הלך לכפר טרשא, ובא שם למלון, התלחשו עליו כל בני העיר, אמרו, אדם גדול בא לכאן נלך אליו. באו אליו. אמרו לו, וכי אינו חס על המגפה. אמר להם מהו. אמרו לו, שכבר יש שבעה ימים שמגפה שורה בעיר, וכל יום היא מתחזקת ואינה מתבטלה."],[19,"אמר להו וכו':","אמר להם נלך לבית הכנסת ונבקש רחמים מהקב\"ה. עוד שהיו הולכים, באו אנשים ואמרו להם פלוני ופלוני מתו, פלוני ופלוני נוטים למות. אמר להם ר' אחא, אין עתה העת לעמוד כך כי השעה דוחקת."],[20,"אבל אפרישו וכו':","אלא הפרישו מכם ארבעים אנשים, מאלו הכשרים ביותר, ויתחלקו עשרה עשרה לד' חלקים. ואני עמכם. עשרה לזוית זו של העיר ועשרה לזוית זו של העיר וכן לד' זויות של העיר. ותאמרו, ברצון נפשכם הענין של קטורת הסמים, אשר הקב\"ה נתן למשה. וענין הקרבנות תאמרו ג\"כ עמו."],[20,"","פירוש כי יש דבר, ומגפה, דבר פירושו כמ\"ש חז\"ל (תענית כ\"א.) אם ג' אנשים מתים בג' ימים זה אחר זה בעיר וכו' הוא דבר. אבל מגפה, הוא מיתה בהמון, כעין שכתוב בפ' קרח, ויהי המתים במגפה ארבעה עשר אלף. ויש ב' בחינות בכללות כל הדינים: דינים דנוקבא, הנק' פתח האהל. ודינים דדכר הנק' כחום היום. (כנ\"ל דף י\"ט ד\"ה והוא, עש\"ה). ו \u0003דבר\u0004 נמשך מן דינים דנוקבא, בסוד \u0003לא זכי הא רע,\u0004 שנתגלה מדת הדין שבה. וצריכים תפילה ותשובה לחזר ולהמתיקה במדת הרחמים, כמו שהיתה מטרם החטא. \u0003ומגפה\u0004 נמשכת מדינים דדכר מכח התגברות קו שמאל על הימין, שדינים אלו נמשכים מבינה, שה\"ס עלמא דדכורא, וה\"ס מדת הרחמים, וא\"כ אין צריכים כאן \u0003תפלה,\u0004 שענינה הוא להמתיק את הנוקבא במדת הרחמים שהוא בינה, כי אדרבא, הדינים, הללו ממדת הרחמים באים, שה\"ס בינה, ששם מקום מציאת ג' הקוין הללו. אלא שצריכים להעלות מ\"ן בסוד מסך דחירק, ולהמשיך קו אמצעי ולכלול הקוים ימין ושמאל זה בזה בבינה גופה, ומשם אל זו\"ן. וזהו נעשה בסוד הקרבת הקטרת, או על ידי אמירתה בכונה."],[20,"","וז\"ש, \u0003אמר להו ניזיל לכי כנישתא,\u0004 כי תחילה חשב ר' אחא שיש \u0003דבר\u0004 בעיר, וא\"כ צריכים תפלה להחזיר הנוקבא למדת הרחמים, וע\"כ אמר להם \u0003ניזיל לבי כנישתא\u0004 להתפלל. אבל כששמע שיש מיתה בהמון, שאמרו לו פלוני ופלוני מיתו פלוני ופלוני נטו למות, אז ראה שהוא מגפה, לכן, \u0003אמר להו ר' אחא לית עתא לקיימא הכי וכו',\u0004 כי למגפה אין תפלה מועלת כי אינה חסרה אז ממיתוק במדת הרחמים, אלא שצריכים קטורת דוקא, לגלות בה קו אמצעי ולכלול הקוין זה בזה. שכל זה נעשה על ידי קטרת, או על ידי אמירה בכונה את פרשת הקטרת. וסוד ד' פעמים עשרה אנשים שלקח עמו וסידרם לומר פרשת הקטרת, לד' זויות העיר, שעשו כן ג' פעמים, הוא להמשיך י\"ג מדות הקדושות מדיקנא דאריך אנפין, וע\"כ סיבב העיר ג\"פ, כי ג\"פ ד' שבמ' האנשים הוא י\"ב. וע\"כ אמר \u0003ואנא עמכון,\u0004 שהוא היה כנגד האחד הכולל את הי\"ב. והיו יחד י\"ג."],[21,"עבדו כן וכו':","עשו כן שלשה פעמים, ועברו בכל העיר אל ארבע זויות, ואמרו כן. לאחר כך אמר להם נלך לאלו שהגיעו למות, והפרישו מכם אנשים שיבואו לבתיהם, ויאמרו כזה שאמרנו, וכאשר תשלימו תאמרו אלו הפסוקים: ויאמר משה אל אהרן קח את המחתה וגו', ויקח אהרן וגו', ויעמוד בין המתים וגו'. וכן עשו. ונתבטלה המגפה מהם."],[22,"שמעו ההוא קלא וכו':","שמעו קול שאמר הסתרה הסתרה הראשונה המתיקו למעלה, שהרי דין השמים אינו שורה כאן, כי הם יודעים לבטל אותו."],[22,"","פירוש. כי ב' דברים היו צריכים לתקן על ידי אמירת הקטרת, א) להעלות מ\"ן לסוד מסך דחירק, שעליו יוצא קומת החסדים שהוא קו האמצעי. ב) להמשיך הזווג על המסך דחירק ולכלול הקוין ימין ושמאל זה בזה ולהמשיך הג\"ר. אמנם בסבת החטאים של אנשי המקום, לא הספיקו רק להעלות את המסך דחירק, שהוא מחליש את תוקפו של קו השמאל, (כנ\"ל פ' לך דף י\"ג ד\"ה ונתבאר ע\"ש) ונתבטלו על ידו הדינים דדכורא שהוא המגפה, אבל בשביל זה באו בהסתרה שניה, שנפלו לבחינת ו\"ק בלי ראש (כמ\"ש שם ד\"ה ונתבאר) כי עוד לא הספיקו לגלות הזווג על המסך ולהמשיך הג\"ר. וזהו שעירר אותם אותו הקול שאמר, \u0003סתרא סתרא קמייתא אוחילו לעילא,\u0004 רק הסתרה הראשונה, שה\"ס המגפה, המתיקו למעלה, \u0003דהא דינא דשמיא,\u0004 דהיינו דינים דדכורא הנקרא שמים, \u0003לא אשרי הכא,\u0004 אינם שורים יותר כאן, \u0003דהא ידעי לבטלא ליה,\u0004 כי על ידי הקטרת העלו את המסך דחירק המבטל את הדינים הללו דדכורא. אמנם בשביל זה, באו להסתרה השניה שהוא ו\"ק בלי ראש. וזהו שעורר אותם הקול."],[22,"","חלש לבו של ר' אחא, נתנמנם, שמע שאמרו לו כאשר עשית זאת עשה זאת. לך ואמור להם שיחזרו בתשובה, כי חוטאים המה לפני. קם והחזיר אותם בתשובה שלמה. וקבלו על עצמם שלא יתבטלו מתורה לעולם, והחליפו שם העיר, וקראו אותה מאתא מחסיא. על שם שהקב\"ה חס עליהם."],[22,"","פירוש. אחר שר' אחא שמע הקול, חלש לבו ונתנמנם, שיורה, שהרגיש גם הוא הסתלקות המוחין, והודיעו לו בזה, שמוטל עליו להחזיר אותם בתשובה שלימה. דהיינו שימשיכו הג\"ר ע\"י המשכת הזווג על המסך והתכללות הקוין זה בזה, שאז נמשך זווג פב\"פ אל זו\"ן. שזה נקרא תשובה, כמו שביארו. תשוב \u0003ה'\u0004 לגבי \u0003ו',\u0004 וז\"ש \u0003כד עבדת דא, עביד דא,\u0004 כיון שהבאת אותם לבחינת ו\"ק בלי ראש, הרי עליך להורותם שימשיכו גם הג\"ר. וז\"ש \u0003וקבילו עליידו דלא יתבטלון מאוריתא לעלם,\u0004 דהיינו שיתדבקו לעולם בקו אמצעי הנקרא \u0003אורייתא.\u0004 וז\"ש \u0003ואחליפו שמא דקרתא, וקארון לה מאתא מחסיא.\u0004 כי מקודם לכן היתה נקראת כפר טרשא, שהוא מלשון שדה טרשין, שפירושו שדה מלאה אבנים ואינה ראויה לזריעה. והוא משום שיושביה היו נמשכים אחר קו שמאל. אבל עתה אחר שנאחזו בקו האמצעי והמשיכו ג\"ר, נחלף המקום ונעשה \u0003למאתא מחסיא.\u0004 דהיינו למקום שהקב\"ה \u0003חס\u0004 עליו ומשפיע להם כל טוב."],[32,"ויאמר שוב אשוב אליך וגו':","א\"ר יצחק שוב אשוב, שוב ישוב היה צריך לומר, שהרי מפתח הזה לפקוד עקרות הוא בידי הקב\"ה ולא בידי שליח אחר."],[33,"כמה דתנינן וכו':","כמו שלמדנו, ג' מפתחות הם שלא נמסרו בידי שליח, של חיה ושל תחיית המתים ושל גשמים. וכיון שלא נמסרו בידי שליח, למה כתוב שוב אשוב, שמשמע שהמלאך ישוב לעת חיה ויפקוד אותה. ומשיב, אלא ודאי, הקב\"ה שהיה עומד עליהם אמר הדבר. ומשום זה כתוב, ויאמר שוב אשוב אליך."],[34,"ות\"ח בכל וכו':","ובוא וראה, בכל מקום שכתוב ויאמר סתם או ויקרא סתם, ולא כתוב מי האומר, ומי הקורא, הוא מלאך הברית דהיינו השכינה, ולא אחר. \u0003ויאמר,\u0004 שכתוב, ויאמר אם שמוע תשמע וגו', ויאמר, ואינו אומר מי הוא. \u0003ויקרא,\u0004 שכתוב, ויקרא אל משה, ואינו אומר מי היה. \u0003אמר,\u0004 שכתוב, ואל משה אמר וגו', ואינו אומר מי היה. אלא בכל אלו הוא"]],[[0,"","וְאַבְרָהָם וְשָׂרָה הָיוּ מְתַקְּנִים טְבִילָה לְכֻלָּם, הוּא לַגְּבָרִים וְהִיא לַנָּשִׁים. מָה הַטַּעַם עָסַק אַבְרָהָם לְטַהֵר בְּנֵי אָדָם? מִשּׁוּם שֶׁהוּא טָהוֹר וְנִקְרָא טָהוֹר, שֶׁכָּתוּב (איוב יד) מִי יִתֵּן טָהוֹר מִטָּמֵא לֹא אֶחָד. טָהוֹר - זֶה אַבְרָהָם שֶׁיָּצָא מִתֶּרַח."],[1,"","רַבִּי שִׁמְעוֹן אָמַר, כְּדֵי לְתַקֵּן אֶת אוֹתָהּ הַדַּרְגָּה שֶׁל אַבְרָהָם, וּמַהִי? מַיִ\"ם (חסד). לָכֵן הִתְקִין לְטַהֵר בְּנֵי הָעוֹלָם בְּמַיִם. וּבְשָׁעָה שֶׁהִזְמִין אֶת הַמַּלְאָכִים, בְּרֵאשִׁית דְּבָרָיו מַה כָּתוּב? יֻקַּח נָא מְעַט מַיִם, כְּדֵי לְהִתְחַזֵּק בְּאוֹתָהּ דַּרְגָּה שֶׁהַמַּיִם שְׁרוּיִים בָּהּ,"],[2,"","וּמִשּׁוּם כָּךְ הָיָה מְטַהֵר אֶת כָּל בְּנֵי הָאָדָם מֵהַכֹּל. מְטַהֵר אוֹתָם מִצַּד שֶׁל עֲבוֹדָה זָרָה, וּמְטַהֵר אוֹתָם מִצַּד הַטֻּמְאָה. וּכְמוֹ שֶׁהוּא מְטַהֵר אֶת הָאֲנָשִׁים, כָּךְ גַּם שָׂרָה מְטַהֶרֶת אֶת הַנָּשִׁים, וְנִמְצָא שֶׁכָּל מִי שֶׁבָּא אֲלֵיהֶם טְהוֹרִים מֵהַכֹּל."],[3,"","בֹּא רְאֵה שֶׁאַבְרָהָם נָטַע אִילָן בְּכָל מָקוֹם שֶׁדִּיּוּרוֹ שָׁם, וְלֹא הָיָה עוֹלֶה בְּכָל מָקוֹם כָּרָאוּי, פְּרָט לְשָׁעָה שֶׁדִּיּוּרוֹ הָיָה בְּאֶרֶץ כְּנַעַן, וּבְאוֹתוֹ אִילָן הָיָה יוֹדֵעַ מִי שֶׁנֶּאֱחָז בַּקָּבָּ\"ה וּמִי שֶׁנֶּאֱחָז בַּעֲבוֹדָה זָרָה."],[4,"","מִי שֶׁנֶּאֱחָז בַּקָּבָּ\"ה, הָיָה הָאִילָן פּוֹרֵשׂ עֲנָפָיו וּמְכַסֶּה עַל רֹאשׁוֹ וְעוֹשֶׂה עָלָיו צֵל נָאֶה. וּמִי שֶׁנֶּאֱחָז בַּצֵּל שֶׁל עֲבוֹדָה זָרָה, אוֹתוֹ הָאִילָן הָיָה מִתְעַלֶּה, וַעֲנָפָיו הָיוּ עוֹלִים לְמַעְלָה. אָז הָיָה יוֹדֵעַ אַבְרָהָם וּמַזְהִיר אוֹתוֹ, וְלֹא זָז מִשָּׁם עַד שֶׁנֶּאֱחַז בֶּאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא."],[5,"","וְכָךְ מִי שֶׁהוּא טָהוֹר (ד\"א כך) מְקַבֵּל אוֹתוֹ הָאִילָן, וּמִי שֶׁהוּא טָמֵא אֵינוֹ מְקַבֵּל אוֹתוֹ. אָז יָדַע אַבְרָהָם וְהָיָה מְטַהֵר אוֹתָם בְּמַיִם."],[6,"","וּמַעָיַין מַיִם הָיָה תַּחַת אוֹתוֹ אִילָן, וּמִי שֶׁצָּרִיךְ טְבִילָה מִיָּד הַמַּיִם עוֹלִים אֵלָיו, וְעוֹלִים עַנְפֵי הָאִילָן, אָז יָדַע אַבְרָהָם שֶׁהוּא טָמֵא וְצָרִיךְ מִיָּד טְבִילָה. וְאִם לֹא, יָבְשׁוּ הַמַּיִם, וְאָז יָדַע שֶׁרוֹצֶה לְהִטָּמֵא וּלְהִשָּׁמֵר שִׁבְעָה יָמִים."],[7,"","וּבֹא וּרְאֵה, שֶׁאֲפִלּוּ בְּשָׁעָה שֶׁהִזְמִין אֶת הַמַּלְאָכִים אָמַר לָהֶם וְהִשָּׁעֲנוּ תַּחַת הָעֵץ כְּדֵי לִרְאוֹת וְלִבְדּק אוֹתָם, וּבְאוֹתוֹ אִילָן הָיָה בּוֹדֵק אֶת כָּל בְּנֵי הָעוֹלָם. וְהַסּוֹד (כנגד) מִשּׁוּם הַקָּדוֹשׁ בָּרוּךְ הוּא (עשה) אָמַר שֶׁהוּא עֵץ הַחַיִּים לַכֹּל, וְלָכֵן וְהִשָּׁעֲנוּ תַּחַת הָעֵץ, וְלֹא תַחַת עֲבוֹדָה זָרָה."],[8,"","וּבֹא וּרְאֵה, כְּשֶׁחָטָא אָדָם, הוּא חָטָא בְּעֵץ הַדַּעַת טוֹב וָרָע, שֶׁכָּתוּב וּמֵעֵץ הַדַּעַת וְגוֹ', וְהוּא חָטָא בּוֹ וְגָרַם מָוֶת לָעוֹלָם. מַה כָּתוּב? וְעַתָּה פֶּן יִשְׁלַח יָדוֹ וְלָקַח גַּם מֵעֵץ הַחַיִּים וְגוֹ' (וגרם מות לכל בני העולם); וּכְשֶׁבָּא אַבְרָהָם, הִתְקִין אֶת הָעוֹלָם עִם אִילָן אַחֵר, שֶׁהוּא עֵץ הַחַיִּים, וְהוֹדִיעַ אֶת הָאֱמוּנָה לְכָל בְּנֵי הָעוֹלָם."],[9,"","אָמַר רַבִּי חִיָּיא אָמַר רַב, אִם הָיִינוּ מִסְתַּכְּלִים בַּפָּרָשָׁה הַזּוֹ - נִסְתַּכֵּל בְּחָכְמָה אִם עִנְיַן הַנְּשָׁמָה הִיא אֵין רֹאשָׁהּ סוֹפָהּ וְאֵין סוֹפָהּ רֹאשָׁהּ, וְאִם הָעִנְיָן לִפְטִירַת הָאָדָם מִן הָעוֹלָם הִיא, נִסְתֹּר אֶת כָּל הַפָּרָשָׁה אוֹ נַעֲמִיד אֶת הַפָּרָשָׁה בָּזֶה אוֹ בָזֶה. מַה זֶּה יֻקַּח נָא מְעַט מַיִם וְרַחֲצוּ רַגְלֵיכֶם וְגוֹ', וְאֶקְחָה פַת לֶחֶם וְגוֹ', וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה וְגוֹ', וְאֶל הַבָּקָר רָץ אַבְרָהָם וְגוֹ', וַיִּקַּח חֶמְאָה וְחָלָב וְגוֹ'."],[10,"","כְּשֶׁבָּא רַב דִּימֵי, אָמַר, לֹא מָצְאָה הַנְּשָׁמָה תּוֹעֶלֶת לַגּוּף אִלְמָלֵא מַה שֶּׁרָמַז בְּכָאן רֶמֶז הַקָּרְבָּנוֹת. בָּטְלוּ הַקָּרְבָּנוֹת - לֹא בָטְלָה הַתּוֹרָה. זֶה שֶׁלֹּא מִתְעַסֵּק בְּקָרְבָּנוֹת, שֶׁיַּעֲסֹק בַּתּוֹרָה וְיוֹעִיל לוֹ יוֹתֵר."],[11,"","שֶׁאָמַר רַבִּי יוֹחָנָן, כְּשֶׁפֵּרַשׁ הַקָּבָּ\"ה הַקָּרְבָּנוֹת, אָמַר מֹשֶׁה: רִבּוֹנוֹ שֶׁל עוֹלָם, תִּינַח בִּזְמַן שֶׁיִּהְיוּ יִשְׂרָאֵל עַל אַדְמָתָם, כֵּיוָן שֶׁיִּגְלוּ מֵעַל אַדְמָתָם מַה יַּעֲשׂוּ? אָמַר לוֹ: מֹשֶׁה, יַעַסְקוּ בַּתּוֹרָה, וַאֲנִי מוֹחֵל לָהֶם בִּשְׁבִילָהּ יוֹתֵר מִכָּל הַקָּרְבָּנוֹת שֶׁבָּעוֹלָם, שֶׁנֶּאֱמַר (ויקרא ז) זאת התורה לעלה למנחה וגו'. כְּלוֹמַר, זאת הַתּוֹרָה בִּשְׁבִיל עוֹלָה, בִּשְׁבִיל מִנְחָה, בִּשְׁבִיל חַטָּאת, בִּשְׁבִיל אָשָׁם."],[12,"","אָמַר רַבִּי כְּרוּסְפְּדַאי, זֶה מִי שֶׁמַּזְכִּיר בְּפִיו בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת עִנְיַן הַקָּרְבָּנוֹת וְתִקְרֻבְתָּם וִיכַוֵּן בָּהֶם, בְּרִית כְּרוּתָה הִיא שֶׁאוֹתָם הַמַּלְאָכִים הַמַּזְכִּירִים חֶטְאוֹ כְּדֵי לְהָרַע לוֹ, שֶׁלֹּא יְכוֹלִים לַעֲשׂוֹת לוֹ אֶלָּא רַק טוֹב."],[13,"","וּמִי יוֹכִיחַ? פָּרָשָׁה זוֹ תּוֹכִיחַ! שֶׁכֵּיוָן שֶׁאָמַר וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו, מַה זֶּה עָלָיו? לְעַיֵּן בְּדִינוֹ. כֵּיוָן שֶׁרוֹאָה נִשְׁמַת הַצַּדִּיק כָּךְ, מַה כָּתוּב? וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה וְגוֹ'. מַה זֶּה הָאֹהֱלָה? בֵּית הַמִּדְרָשׁ. וּמַהוּ אוֹמֵר? מַהֲרִי שְׁלֹשׁ סְאִים, עִנְיַן הַקָּרְבָּנוֹת, וְהַנְּשָׁמָה מִתְכַּוֶּנֶת בָּהֶם. זֶהוּ שֶׁכָּתוּב וְאֶל הַבָּקָר רָץ אַבְרָהָם. וְאָז נוֹחַ לָהֶם וְלֹא יְכוֹלִים לְהָרַע לוֹ."],[14,"","רַבִּי פִּנְחָס פָּתַח פָּסוּק שֶׁכָּתוּב (במדבר יז) וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם, וְכָתוּב וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְגוֹ', וְכָתוּב וַתֵּעָצַר הַמַּגֵּפָה. כָּתוּב כָּאן מַהֵר, וְכָתוּב שָׁם מַהֲרִי שְׁלֹשׁ סְאִים. מַה לְּהַלָּן קָרְבָּן לְהִנָּצֵל, אַף כָּאן קָרְבָּן לְהִנָּצֵל."],[15,"","אָמַר רַבִּי פִּנְחָס, פַּעַם אַחַת הָיִיתִי מְהַלֵּךְ בַּדֶּרֶךְ וּפָגַשְׁתִּי אֶת אֵלִיָּהוּ. אָמַרְתִּי לוֹ, יֹאמַר לִי מַר דָּבָר שֶׁמּוֹעִיל לַבְּרִיּוֹת. אָמַר לוֹ, בְּרִית גָּזַר הַקָּבָּ\"ה, וְנִכְנְסוּ לְפָנָיו כָּל הַמַּלְאָכִים שֶׁמְּמֻנִּים לְהַזְכִּיר חֲטָאֵי הָאָדָם, שֶׁבִּזְמַן שֶׁיַּזְכִּירוּ בְּנֵי אָדָם הַקָּרְבָּנוֹת שֶׁצִּוָּה מֹשֶׁה, וּמְכַוֵּן לִבּוֹ וּרְצוֹנוֹ בָהֶם - שֶׁכֻּלָּם יַזְכִּירוּ אוֹתוֹ לְטוֹב."],[16,"","וְעוֹד, בִּזְמַן שֶׁיֶּאֱרַע מָוֶת בִּבְנֵי אָדָם, הַבְּרִית נִגְזְרָה, וְהַכָּרוֹז עוֹבֵר עַל כָּל חֵילוֹת הַשָּׁמַיִם, דְּאִם יַעֲלוּ בָנָיו בָּאָרֶץ בְּבָתֵּי כְנֵסִיּוֹת וּבְבָתֵּי מִדְרָשׁוֹת וְיֹאמְרוּ בִּרְצוֹן נֶפֶשׁ וָלֵב עִנְיָנִים שֶׁל קְטֹרֶת בְּשָׂמִים שֶׁהָיוּ לָהֶם לְיִשְׂרָאֵל, שֶׁיִּתְבַּטֵּל הַמָּוֶת מֵהֶם."],[17,"","אָמַר רַבִּי יִצְחָק, בּא רְאֵה מַה כָּתוּב, וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֶן עָלֶיהָ אֵשׁ מֵעַל הַמִּזְבֵּחַ וְשִׂים קְטֹרֶת. אָמַר לוֹ אַהֲרֹן, לָמָּה? כִּי יָצָא הַקֶּצֶף מִלִּפְנֵי ה' וְגוֹ'. מַה כָּתוּב? וַיָּרָץ אֶל תּוֹךְ הַקָּהָל וְהִנֵּה הֵחֵל הַנֶּגֶף בָּעָם. וְכָתוּב וַיַּעֲמֹד בֵּין הַמֵּתִים וּבֵין הַחַיִּים וַתֵּעָצַר הַמַּגֵּפָה. וְלֹא יָכֹל מַלְאָךְ שֶׁל חַבָּלָה לִשְׁלֹט וְנִתְבַּטֵּל הַמָּוֶת."],[18,"","רַבִּי אַחָא הָלַךְ לִכְפַר טַרְשָׁא, בָּא אֵצֶל הַמְאָרֵחַ שֶׁלּוֹ. לָחֲשׁוּ עָלָיו כָּל בְּנֵי הָעִיר. אָמְרוּ, אָדָם גָּדוֹל בָּא לְכָאן, נֵלֵךְ אֵלָיו. בָּאוּ אֶצְלוֹ. אָמְרוּ לוֹ, לֹא חוֹשֵׁשׁ עַל אֲבֵדתֶינוּ? אָמַר לָהֶם, מַהוּ? אָמְרוּ לוֹ שֶׁיֵּשׁ שִׁבְעָה יָמִים שֶׁיֵּשׁ מָוֶת בָּעִיר, וְכָל יוֹם מִתְחַזֵּק וְלֹא מִתְבַּטֵּל."],[19,"","אָמַר לָהֶם, נֵלֵךְ לְבֵית הַכְּנֶסֶת וּנְבַקֵּשׁ רַחֲמִים מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. עַד שֶׁהָיוּ הוֹלְכִים, בָּאוּ וְאָמְרוּ, פְּלוֹנִי וּפְלוֹנִי מֵתוּ, וּפְלוֹנִי וּפְלוֹנִי נוֹטִים לָמוּת. אָמַר לָהֶם רַבִּי אַחָא, אֵין עֵת לַעֲמֹד כָּךְ, שֶׁהַשָּׁעָה דְחוּקָה."],[20,"","אֲבָל תַּפְרִישׁוּ מִכֶּם אַרְבָּעִים בְּנֵי אָדָם מֵאֵלּוּ הַיּוֹתֵר זַכָּאִים. עֲשָׂרָה עֲשָׂרָה לְאַרְבָּעָה חֲלָקִים, וַאֲנִי עִמָּכֶם, עֲשָׂרָה לִקְצֵה הָעִיר וַעֲשָׂרָה לִקְצֵה הָעִיר, וְכֵן לְאַרְבַּע קַצְווֹת הָעִיר, וְאִמְרוּ בְּנֶפֶשׁ חֲפֵצָה עִנְיָן שֶׁל קְטֹרֶת הַסַּמִּים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לְמֹשֶׁה, וְעִנְיָן שֶׁל הַקָּרְבָּנוֹת אִתּוֹ."],[21,"","עָשׂוּ כָּךְ שָׁלֹשׁ פְּעָמִים וְעָבְרוּ בְּכָל הָעִיר לְאַרְבַּע קְצָווֹת וְהָיוּ אוֹמְרִים כֵּן. לְבַסּוֹף אָמַר לָהֶם, נֵלֵךְ לְאֵלּוּ שֶׁנּוֹטִים לָמוּת, וְתַפְרִישׁוּ מִכֶּם לְבָתֵּיהֶם וְתֹאמְרוּ כָּךְ, וְכַאֲשֶׁר תְּסַיְּמוּ, תֹּאמְרוּ אֵלּוּ הַפְּסוּקִים, וַיֹּאמֶר מֹשֶׁה אֶל אַהֲרֹן קַח אֶת הַמַּחְתָּה וְתֵן עָלֶיהָ אֵשׁ וְגוֹ', וַיִּקַּח אַהֲרֹן וְגוֹ', וַיַּעֲמֹד בֵּין הַמֵּתִים וְגוֹ'. וְכֵן עָשׂוּ וְהִתְבַּטֵּל מֵהֶם (המות)."],[22,"","שָׁמְעוּ אוֹתוֹ קוֹל שֶׁאוֹמֵר: סוֹדֵי הַסּוֹדוֹת, הָרִאשׁוֹנִים הִנְחִילוּהָ לָנֶצַח, שֶׁהֲרֵי דִּין הַשָּׁמַיִם לֹא שׁוֹרֶה כָּאן, שֶׁהֲרֵי יוֹדְעִים לְבַטְּלוֹ. חָלַשׁ לִבּוֹ שֶׁל רַבִּי אָחָא וְיָשַׁן. שָׁמַע שֶׁאוֹמְרִים לוֹ: כְּמוֹ שֶׁעָשִׂיתָ אֶת זֶה - תַּעֲשֶׂה אֶת זֶה. לֵךְ אֱמֹר לָהֶם שֶׁיַּחְזְרוּ בִּתְשׁוּבָה, שֶׁרְשָׁעִים הֵם לְפָנַי. קָם וְהֶחֱזִירָם בִּתְשׁוּבָה שְׁלֵמָה, וְקִבְּלוּ עֲלֵיהֶם שֶׁלֹּא יִתְבַּטְּלוּ מֵהַתּוֹרָה לְעוֹלָם, וְהֶחְלִיפוּ אֶת שֵׁם הָעִיר, וְקָרְאוּ לָא מָתָא מַחְסֵיָא."],[23,"","אָמַר רַבִּי יְהוּדָה, לֹא דַי לָהֶם לַצַּדִּיקִים שֶׁמְּבַטְּלִים אֶת הַגְּזֵרָה, אֶלָּא לְאַחַר כֵּן שֶׁמְּבָרְכִים לָהֶם, תֵּדַע לְךְ שֶׁכֵּן הוּא. דְּכֵיוָן שֶׁהַנְּשָׁמָה אוֹמֶרֶת לַגּוּף מַהֲרִי שְׁלֹשׁ סְאִים וְגוֹ' וְכָל אוֹתוֹ הָעִנְיָן וּמְבַטֵּל אֶת הַדִּין - מַה כָּתוּב? וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. הֲרֵי בְּרָכָה."],[24,"","כֵּיוָן שֶׁרוֹאִים אוֹתָהּ הַמַּלְאָכִים שֶׁזֶּה לָקַח עֵצָה לְנַפְשׁוֹ - מָה עוֹשִׂים? הוֹלְכִים אֵצֶל הָרְשָׁעִים לְעַיֵּן בְּדִינָם וְלַעֲשׂוֹת בָּהֶם מִשְׁפָּט. זֶהוּ שֶׁכָּתוּב וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם, לִמְקוֹם הָרְשָׁעִים, לַעֲשׂוֹת בָּהֶם מִשְׁפָּט."],[25,"","זֶה הוּא שֶׁאָמַר רַבִּי יְהוּדָה, כָּךְ דַּרְכּוֹ שֶׁל צַדִּיק: כֵּיוָן שֶׁרוֹאֶה שֶׁמְּעַיְּנִים בְּדִינוֹ, אֵינוֹ מִתְאַחֵר לָשׁוּב וּלְהִתְפַּלֵּל וּלְהַקְרִיב (על) חֶלְבּוֹ וְדָמוֹ לִפְנֵי צוּרוֹ, עַד שֶׁמִּסְתַּלְּקִים בַּעֲלֵי הַדִּין מִמֶּנּוּ."],[26,"","שֶׁכֵּיוָן שֶׁאָמַר וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלֹשָׁה אֲנָשִׁים נִצָּבִים עָלָיו - מַה כָּתוּב בַּנְּשָׁמָה? וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה. בְּחִפָּזוֹן וּבִמְהִירוּת בְּלֹא שׁוּם הַעְכָּבָה. מִיָּד מְמַהֶרֶת הַנְּשָׁמָה אֵצֶל הַגּוּף לְהַחֲזִירוֹ לְמוּטָב וּלְבַקֵּשׁ בְּמַה שֶּׁיִּתְכַּפֵּר לוֹ, עַד שֶׁמִּסְתַּלְּקִים מִמֶּנּוּ בַּעֲלֵי הַדִּין."],[27,"","רַבִּי אֱלִיעֶזֶר אוֹמֵר, מַהוּ שֶׁאָמַר וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים? אֶלָּא, כֵּיוָן שֶׁהַנְּשָׁמָה עוֹמֶדֶת בְּמַעֲלָתָהּ, וְהַגּוּף נִשְׁאָר בָּאָרֶץ מִכַּמָּה שָׁנִים, בָּאִים בַּיָּמִים שָׁנִים וְיָמִים הַרְבֵּה וְחָדַל לָצֵאת וְלָבֹא וְלַעֲבֹר אֹרַח כִּשְׁאָר כָּל אָדָם. נִתְבַּשֵּׂר לְהַחֲיוֹת הַגּוּף."],[28,"","מַהוּ אוֹמֵר אַחֲרֵי בְלוֹתִי הָיְתָה לִּי עֶדְנָה? אַחֲרֵי בְלוֹתִי בֶּעָפָר מֵהַיּוֹם כַּמָּה שָׁנִים, הָיְתָה לִּי עֶדְנָה וְחִדּוּשׁ. וַאדנִי זָקֵן, שֶׁהַיּוֹם כַּמָּה שָׁנִים שֶׁיָּצָאת מִמֶּנּוּ וְלֹא הִפְקִידַנִי."],[29,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר, הֲיִפָּלֵא מֵה' דָּבָר לַמּוֹעֵד. מַהוּ לַמּוֹעֵד? אוֹתוֹ הַיָּדוּעַ אֶצְלִי לְהַחֲיוֹת מֵתִים. וּלְשָׂרָה בֵן, מְלַמֵּד שֶׁיִּתְחַדֵּשׁ כְּבֶן שָׁלֹשׁ שָׁנִים."],[30,"","אָמַר רַבִּי יְהוּדָה בְּרַבִּי סִימוֹן, כֵּיוָן שֶׁהַנְּשָׁמָה נִזּוֹנֵית מִזִּיוָהּ שֶׁל מַעְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לְאוֹתוֹ הַמַּלְאָךְ הַנִּקְרָא דוּמָ\"ה: לֵךְ וּבַשֵּׂר לְגוּף פְּלוֹנִי שֶׁאֲנִי עָתִיד לְהַחֲיוֹתוֹ למּוֹעֵד שֶׁאֲנִי אֲחַיֶּה אֶת הַצַּדִּיקִים לֶעָתִיד לָבֹא. וְהוּא מֵשִׁיב: אַחֲרֵי בְלוֹתִי הָיְתָה לִּי עֶדְנָה? אַחֲרֵי בְלוֹתִי בֶּעָפָר וְשָׁכַנְתִּי בָּאֲדָמָה, וְאָכַל בְּשָׂרִי רִמָּה וְגוּשׁ עָפָר, תִּהְיֶה לִי חִדּוּשׁ?"],[31,"","הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר לַנְּשָׁמָה: זֶהוּ שֶׁכָּתוּב וַיֹּאמֶר ה' אֶל אַבְרָהָם וְגוֹ' הֲיִפָּלֵא מֵה' דָּבָר!? לַמּוֹעֵד הַיָּדוּעַ אֶצְלִי לְהַחֲיוֹת אֶת הַמֵּתִים אָשׁוּב אֵלֶיךְ אוֹתוֹ הַגּוּף שֶׁהוּא קָדוֹשׁ מְחֻדָּשׁ כְּבָרִאשׁוֹנָה לִהְיוֹתְכֶם מַלְאָכִים קְדוֹשִׁים, וְאוֹתוֹ הַיּוֹם עָתִיד לְפָנַי לִשְׂמֹחַ בָּהֶם. זֶהוּ שֶׁכָּתוּב (תהלים קד) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו. (ע\"כ מדרש הנעלם)"],[32,"","וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. אָמַר רַבִּי יִצְחָק, שׁוֹב אָשׁוּב - שׁוֹב יָשׁוּב הָיָה צָרִיךְ לִכְתֹּב, שֶׁהֲרֵי הַמַּפְתֵּחַ הַזֶּה לִפְקֹד הָעֲקָרוֹת הוּא בְּיַד הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא בְּיַד שָׁלִיחַ אַחֵר,"],[33,"","כְּמוֹ שֶׁשָּׁנִינוּ, שָׁלֹשׁ מַפְתְּחוֹת הֵם שֶׁלֹּא נִמְסְרוּ בְּיַד שָׁלִיחַ: שֶׁל חַיָּה, וּתְחִיַּת הַמֵּתִים, וּגְשָׁמִים. וְהוֹאִיל וְלֹא נִמְסְרוּ בְּיַד שָׁלִיחַ, לָמָּה כָּתוּב שׁוֹב אָשׁוּב? אֶלָּא וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָיָה עוֹמֵד עֲלֵיהֶם אָמַר (לו) הַדָּבָר, לָכֵן כָּתוּב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ."],[34,"","וּבֹא וּרְאֵה, בְּכָל מָקוֹם שֶׁכָּתוּב וַיֹּאמֶר סְתָם אוֹ וַיִּקְרָא סְתָם, הוּא מַלְאַךְ הַבְּרִית וְלֹא אַחֵר. וַיֹּאמֶר - שֶׁכָּתוּב (שמות טו) וַיֹּאמֶר אִם שָׁמֹעַ תִּשְׁמַע וְגוֹ'. וַיֹּאמֶר, וְלֹא אָמַר מִיהוּ. וַיִּקְרָא - שֶׁכָּתוּב (ויקרא א) וַיִּקְרָא אֶל מֹשֶׁה, וְלֹא אָמַר מִי הָיָה. אָמַר - שֶׁכָּתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר וְגוֹ', וְלֹא אָמַר מִי הָיָה. (אף כך שכתוב שוב אשוב, ויאמר סתם, ולא אמר מי היה,) אֶלָּא בְּכָל אֵלֶּה מַלְאָךְ שֶׁל הַבְּרִית הָיָה, וְהַכֹּל נֶאֱמַר בַּקָּבָּ\"ה. וְלָכֵן כָּתוּב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ וְגוֹ', וְהִנֵּה בֵן וְגוֹ'."]]],[["וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךָ. מַאי טַעְמָא לָא כְּתִיב וְהִנֵּה בֵן לְךָ, אֶלָּא בְּגִין דְּלָא יַחֲשֹׁב דְּהָא מִן הָגָר אִיהוּ כִּדְבְקַדְמִיתָא. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (מלאכי א׳:ו׳) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדוֹנָיו. בֵּן יְכַבֵּד אָב דָּא יִצְחָק לְאַבְרָהָם.","אֵימָתַי כַּבִּיד לֵיהּ, בְּשַׁעֲתָא דְּעֲקַד לֵיהּ עַל גַּבֵּי מַדְבְּחָא וּבְעָא לְמִקְרַב לֵיהּ קָרְבָּנָא, וְיִצְחָק בַּר תְּלָתִין וּשְׁבַע שְׁנִין הֲוָה, וְאַבְרָהָם הֲוָה סָבָא, דְּאִילוּ הֲוָה בָּעִיט (ס\"א ביה) בְּרַגְלָא חַד לָא יָכִיל לְמֵיקַם קַמֵיהּ, (כל שכן למעבד ליה), וְאִיהוּ אוֹקִיר לֵיהּ לְאֲבוֹי וְעֲקַד לֵיהּ כְּחַד אִימְרָא בְּגִין לְמֶעְבַּד רְעוּתֵיהּ דְּאֲבוֹי.","(קמו ב) וְעֶבֶד אֲדוֹנָיו דָּא אֱלִיעֶזְרִ לְאַבְרָהָם. כַּד שַׁדַּר לֵיהּ לְחָרָן, וְעֲבַד כָּל רְעוּתֵיהּ דְּאַבְרָהָם, וְאוֹקִיר לֵיהּ כְּמָה דִכְתִיב, (בראשית כ״ד:א׳) וַיְיָ בֵּרַךְ אֶת אֲדוֹנִי וְגו'. וּכְתִיב (בראשית כ״ד:ל״ד) וַיֹּאמֶר עֶבֶד אַבְרָהָם אָנֹכִי, בְּגִין לְאוֹקִיר לֵיהּ לְאַבְרָהָם.","דְּהָא בַּר נָשׁ דְּהֲוָה מַיְיתֵי כֶּסֶף וְזָהָב וְאַבְנֵי יְקָר וּגְמַלִּין וְאִיהוּ כְּדְקָא יְאוּת שַׁפִּיר בְּחֵיזוּ לָא אָמַר דְּאִיהוּ רְחִימָא דְּאַבְרָהָם אוֹ קָרִיבָא דִּילֵיהּ. אֶלָּא אָמַר עֶבֶד אַבְרָהָם אָנֹכִי, בְּגִין לְסַלְּקָא בְּשִׁבְחָא דְּאַבְרָהָם וּלְאוֹקִיר לֵיהּ בְּעֵינַיְיהוּ.","וְעַל דָּא בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדוֹנָיו. וְאַתּוּן יִשְׂרָאֵל בָּנַי. קְלָנָא בְּעֵינַיְיכוּ לוֹמַר דְּאֲנָא אֲבוּכוֹן אוֹ דְּאַתּוּן עֲבָדִין לִי. וְאִם אָב אָנִי אַיֵּה כְבוֹדִי וְגו'. בְגִין כָּךְ וְהִנֵּה בֵן, דָּא הוּא בֵּן וַדַּאי, וְלָא יִשְׁמָעֵאל. דָּא הוּא בֵּן דְּאוֹקִיר לְאֲבוֹי כְּדְקָא חָזֵי.","וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךָ. בֵּן לְשָׂרָה, דִּבְגִינֵיהּ מִיתַת, דִּבְגִינֵיהּ כְּאִיבַת נַפְשָׁהּ עַד דְּנַפְקַת מִינָהּ. וְהִנִּה בֵן לְשָׂרָה. לְאִסְתַּלָּקָא בְּגִינֵיהּ בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עָלְמָא. דִּכְדֵין וַיְיָ פָּקַד אֶת שָׂרָה וְגו' דְּהָא מַדְכְּרֵי לְשָׂרָה בְּגִינִיהּ דְּיִצְחָק וְעַל דָּא אִיהוּ בֵּן לְשָׂרָה (אנהו מלאכי אמרו). וְהִנֵּה בֵן לְשָׂרָה. (דין) דְּהָא נוּקְבָא נָטְלָא (ליה) לִבְרָא מִן דְּכוּרָא:","וְשָׂרָה שׁוֹמַעַת פֶּתַח הָאֹהֶל וְהוּא אַחֲרָיו. מַאי וְהוּא אַחֲרָיו, וְהִיא אַחֲרָיו מִבָּעֵי לֵיהּ. אֶלָּא רָזָא אִיהוּ, וְשָׂרָה שׁוֹמַעַת מַה דְּהֲוָה אָמַר (פתח האהל דא קודשא בריך הוא. והוא אחריו מאן דהוה אמר) פֶּתַח הָאֹהֶל דָּא דַּרְגָּא תַּתָּאָה. פִּתְחָא דִּמְהֵימְנוּתָא. וְהוּא אַחֲרָיו (דא) דְּאוֹדֵי לֵיהּ דַּרְגָּא עִלָּאָה (נ\"א פתח האהל והוא אחריו דא קודשא בהך הוא. פתח האהל דא דרגא תתאה, והוא אחריו דא דרגא עלאה). מִן יוֹמָא דְּהֲוַת שָׂרָה בְּעָלְמָא לָא שָׁמְעַת מִלָּה דְּקוּדְשָׁא בְּרִיךְ הוּא בַּר הַהוּא שַׁעֲתָא.","דָּבָר אַחֵר דְּהֲוַת יָתְבָא שָׂרָה פֶּתַח הָאֹהֶל בְּגִין לְמִשְׁמַע מִלִּין. וְהִיא שָׁמְעַת הַאי מִלָּה דְּאִתְבַּשַּׂר בָּהּ אַבְרָהָם. (ד\"א) וְהוּא אַחֲרָיו. אַבְרָהָם דְּהֲוָה יָתִיב אַחוֹרוֹי דִּשְׁכִינְתָּא:","וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים. מַאי בָּאִים בַּיָּמִים. שִׁעוּרִין דְּיוֹמִין דְּאִתְחֲזֵי כְּדֵין לְהוּ, חַד מֵאָה וְחַד תִּשְׁעִים, עָאלוּ בְּיוֹמִין שִׁעוּרָא דְּיוֹמִין כְּדְקָא יָאוֹת. בָּאִים בַּיָּמִים. כְּמָא דְאַתְּ אָמֵר כִּי בָא הַיּוֹם דְּאִעֲרַב יוֹמָא לְמֵיעַל.","חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים. וְהַהִיא שַׁעֲתָא חָמַאת גַּרְמָהּ בְּעִדּוּנָא אָחֳרָא. וּבְגִין כָּךְ אָמְרָה וַאֲדוֹנִי זָקֵן דְּהָא אִיהוּ לָא כְדַאי לְאוֹלָדָא בְּגִין דְּאִיהוּ סָבָא.","רַבִּי יְהוּדָה פָּתַח (משלי ל״א:כ״ג) נוֹדַע בַּשְּׁעָרִים בַּעֲלָהּ בְּשִׁבְתּוֹ עִם זִקְנֵי אָרֶץ. תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלַּק בִּיקָרֵיהּ דְּאִיהוּ גָּנִיז וְסָתִים בְּעִילוּיָא סַגְיָא. לָאו אִיתַי בְּעָלְמָא וְלָא הֲוָה מִן יוֹמָא דְּאִתְבְּרֵי עָלְמָא דְּיָכִיל לְקָיְימָא עַל חָכְמָתָא דִילֵיהּ וְלָא יָכִיל לְקָיְימָא בֵּיהּ.","בְּגִין דְּאִיהוּ גָּנִיז וְסָתִים וְאִסְתַּלַּק לְעֵילָא לְעֵילָא, וְכֻלְהוּ עִלָּאֵי וְתַתָּאֵי לָא יָכְלִין לְאִתְדַּבְּקָא, עַד דְּכֻלְהוּ אָמְרִין (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד יְיָ מִמְקוֹמוֹ. תַּתָּאֵי אָמְרֵי דְּאִיהוּ לְעֵילָא דִּכְתִיב, (תהילים קי״ג:ד׳) עַל הַשָּׁמַיִם כְּבוֹדוֹ. עִלָאֵי אָמְרֵי דְּאִיהוּ לְתַתָּא דִּכְתִיב, (תהילים נ״ז:ו׳) עַל כָּל הָאָרֶץ כְּבוֹדֶךָ. עַד דְּכֻלְהוּ עִלָּאֵי וְתַתָּאֵי אָמְרֵי בָּרוּךְ כְּבוֹד יְיָ מִמְקוֹמוֹ. בְּגִין דְּלָא אִתְיְידַע וְלָא הֲוָה מַאן דְּיָכִיל לְקָיְימָא בֵּיהּ, וְאַתְּ אֲמַרְתְּ נוֹדָע בַּשְּׁעָרִים בַּעֲלָהּ."],[[0,"והנה בן לשרה אשתך:","ושואל, מה הטעם שלא כתוב והנה בן לך. ומשיב, אלא כדי שלא יחשוב, שמן הגר יהיה, כבתחילה. רבי שמעון פתח ואמר בן יכבד אב ועבד אדוניו. בן יכבד אב זה יצחק לאברהם."],[1,"אימתי כביד וכו':","מתי כבד אותו. היינו בשעה שעקד אותו על המזבח, ורצה להקריבו לקרבן, ויצחק היה אז בן ל\"ז שנים, ואברהם היה זקן, שאלו היה בועט בו ברגל אחד לא היה יכול לעמוד מפניו, והוא כבד את אביו, ואביו עקד אותו כמו כבשה אחת, ולא עמד כנגדו כדי לעשות רצון אביו."],[2,"ועבד אדוניו וכו':","ועבד אדוניו, זהו אליעזר לאברהם. כאשר שלח את אליעזר לחרן, ועשה שם כל רצונו של אברהם, וכבד אותו כמו שכתוב, וה' ברך את אדוני וגו', וכתוב ויאמר עבד אברהם אנכי, כדי לכבד את אברהם."],[3,"דהא בר נש וכו':","שהרי בן אדם, המביא כסף וזהב ואבנים יקרות, וגמלים, ובעצמו הוא כראוי, ויפה מראה, לא אמר שהוא אוהבו של אברהם או קרוב שלו, אלא אמר עבד אברהם אנכי. כדי להעלות שבחו של אברהם, ולכבד אותו בעיניהם."],[4,"ועל דא בן וכו':","ועל כן אוה\"כ, בן יכבד אב ועבד אדוניו, ואתם ישראל, בני, חרפה הוא בעיניכם, לומר שאני אביכם, או שאתם עבדי. ואם אב אני איה כבודי וגו'. משום זה אוה\"כ, \u0003והנה בן\u0004 זה הוא בן ודאי, ולא ישמעאל. זה הוא בן המכבד לאביו כראוי."],[5,"והנה בן לשרה אשתך, בן לשרה:","כי בשבילו מתה, מסבה ששמעה על עקדתו. ובשבילו היתה נפשה כואבת עד שהולידה אותו. \u0003והנה בן לשרה וכו':\u0004 והנה בן לשרה, היינו להתעלות בשבילו בעת שהקב\"ה יושב בדין על העולם כי אז, וה' פקד את שרה וגו', כי בראש השנה נולד יצחק הרי שזכר את שרה בשביל יצחק, ועל כן הוא בן לשרה. פירוש אחר \u0003והנה בן לשרה\u0004 כי הנקבה לוקחת הבן מן הזכר. ונמצא הבן אצל הנקבה, וע\"כ אומר והנה בן לשרה."],[6,"ושרה שומעת וכו':","ושואל מהו והוא אחריו, היה צריך לומר, והיא אחריו, דהיינו שהיתה מאחורי המלאך המבשר. ומשיב אלא סוד הוא. \u0003ושרה שומעת\u0004 היינו מה שאמר \u0003פתח האהל,\u0004 שזה הוא מדרגה תחתונה, פתח האמונה, דהיינו השכינה, \u0003והוא אחריו,\u0004 היינו שמדרגה העליונה, שהוא הקב\"ה, הודה לו מיום ששרה היתה בעולם, לא שמעה דבר מהקב\"ה, זולת בשעה ההיא."],[7,"ד\"א דהות וכו':","פירוש אחר. ששרה היתה יושבת פתח האהל כדי לשמוע מה שמדברים. והיא שמעה דבר בשורה זו שנתבשר בה אברהם. וע\"כ אומר ושרה שומעת פתח האהל. \u0003והוא אחריו.\u0004 היינו שאברהם היה יושב מאחוריה של השכינה."],[8,"ואברהם ושרה זקנים באים בימים:","ושואל מהו \u0003באים בימים.\u0004 ואומר שפירושו שבאו בשיעור הימים, שהיו ראוים להם אז, לאחד מאה שנים ולאחד תשעים שנה. ובאו בימים, בשיעור ימים כראוי להיות. \u0003באים בימים\u0004 הוא כמו שאתה אומר, כי בא היום, שפירושו שהעריב היום לבא, כי נשלם. אף כאן באים בימים היינו שנשלמו ימיהם."],[9,"חדל להיות לשרה ארח כנשים:","ובאותה שעה ראתה את עצמה, בעדנה אחרת, שחזר אליה אורח כנשים. ועל כן אמרה ואדוני זקן, כי הוא אינו ראוי להוליד, משום שהוא זקן, ולא אמרה על עצמה ואני זקנתי."],[10,"ר' יהודה פתח וכו':","ר\"י פתח. נודע בשערים בעלה וגו'. בוא ראה, הקב\"ה נתעלה ביקרו, כי הוא גנוז וסתום בהעלאה גדולה, לא יש בעולם, ולא היה מיום שנברא העולם, מי שיוכל לעמוד על החכמה שלו. ועל כן לא יוכל מי לעמוד על חכמתו."],[11,"משום שהוא גנוז וסתום,","ונעלה למעלה למעלה, וכל העליונים ותחתונים אינם יכולים להשיגו, עד שכולם אומרים, ברוך כבוד ה' ממקומו. התחתונים אומרים שהשכינה היא למעלה. שכתוב על השמים כבודו. והעליונים אומרים שהשכינה היא למטה. שכתוב על כל הארץ כבודך. עד שכל העליונים והתחתונים אומרים, ברוך כבוד ה' ממקומו, משום שלא נודע ולא היה מי שיכול לעמוד בו. ואתה תאמר, נודע בשערים בעלה."]],[[0,"","וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ. מָה הַטַּעַם לֹא כָתוּב וְהִנֵּה בֵן לְךְ? אֶלָּא כְּדֵי שֶׁלֹּא יַחְשֹׁב שֶׁהוּא מֵהָגָר כְּמוֹ בָּרִאשׁוֹנָה. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (מלאכי א) בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. בֵּן יְכַבֵּד אָב - זֶה יִצְחָק אֶת אַבְרָהָם."],[1,"","מָתַי כִּבֵּד אוֹתוֹ? בְּשָׁעָה שֶׁעָקַד אוֹתוֹ עַל גַּבֵּי הַמִּזְבֵּחַ וְרָצָה לְהַקְרִיבוֹ לְקָרְבָּן. וְיִצְחָק בֶּן שְׁלֹשִׁים וְשֶׁבַע שָׁנִים הָיָה, וְאַבְרָהָם הָיָה זָקֵן, שֶׁאִלּוּ הָיָה בּוֹעֵט (בו) בְּרֶגֶל אַחַת לֹא הָיָה יָכוֹל לַעֲמֹד לְפָנָיו, וְהוּא כִבֵּד אוֹתוֹ אֶת אָבִיו, וְעָקַד אוֹתוֹ כְּמוֹ תַיִשׁ כְּדֵי לַעֲשׂוֹת רְצוֹן אָבִיו."],[2,"","וְעָבֶד אֲדנָיו - זֶה אֱלִיעֶזֶר לְאַבְרָהָם, כְּשֶׁשָּׁלַח אוֹתוֹ לְחָרָן וְעָשָׂה כָּל רְצוֹנוֹ שֶׁל אַבְרָהָם וְכִבְּדוֹ, כְּמוֹ שֶׁכָּתוּב (בראשית כד) וַה' בֵּרַךְ אֶת אֲדנִי וְגוֹ', וְכָתוּב (שם) וַיֹּאמַר עֶבֶד אַבְרָהָם אָנֹכִי, כְּדֵי לְכַבֵּד אֶת אַבְרָהָם."],[3,"","שֶׁהֲרֵי בֶּן אָדָם שֶׁהָיָה מֵבִיא כֶסֶף וְזָהָב וַאֲבָנִים יְקָרוֹת וּגְמַלִּים, וְהוּא כָּרָאוּי, נָאֶה לְמַרְאֶה, לֹא אָמַר שֶׁהוּא אוֹהֵב אַבְרָהָם אוֹ קָרוֹב שֶׁלּוֹ, אֶלָּא אָמַר עֶבֶד אַבְרָהָם אָנֹכִי, כְּדֵי לְהַעֲלוֹת אֶת שֶׁבַח אַבְרָהָם וּלְכַבְּדוֹ בְּעֵינֵיהֶם."],[4,"","וְעַל כֵּן בֵּן יְכַבֵּד אָב וְעֶבֶד אֲדנָיו. וְאַתֶּם יִשְׂרָאֵל בָּנַי, קָלוֹן בְּעֵינֵיכֶם לוֹמַר שֶׁאֲנִי אֲבִיכֶם אוֹ שֶׁאַתֶּם עֲבָדִים שֶׁלִּי? וְאִם אָב אָנִי אַיֵּה כְבוֹדִי וְגוֹ'. מִשּׁוּם כָּךְ וְהִנֵּה בֵן. זֶהוּ בֵּן וַדַּאי, וְלֹא יִשְׁמָעֵאל. זֶהוּ בֵּן שֶׁכִּבֵּד אֶת אָבִיו כָּרָאוּי."],[5,"","וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ. בֵן לְשָׂרָה - שֶׁבִּגְלָלוֹ מֵתָה, שֶׁבִּגְלָלוֹ כָּאֲבָה נַפְשָׁה עַד שֶׁיָּצְאָה מִמֶּנָּה. וְהִנֵּה בֵן לְשָׂרָה - לְהִתְעַלּוֹת בִּגְלָלוֹ בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם. שֶׁאָז וַה' פָּקַד אֶת שָׂרָה וְגוֹ', שֶׁהֲרֵי מַזְכִּירִים אֶת שָׂרָה מִשּׁוּם יִצְחָק, וְעַל זֶה הוּא בֵּן לְשָׂרָה (זה אמרו המלאכים). וְהִנֵּה בֵן לְשָׂרָה. (זה) שֶׁהֲרֵי הַנְּקֵבָה לוֹקַחַת (את) הַבֵּן מֵהַזָּכָר."],[6,"","וְשָׂרָה שּמַעַת פֶּתַח הָאֹהֶל וְהוּא אַחֲרָיו. מַה זֶּה וְהוּא אַחֲרָיו? וְהִיא אַחֲרָיו צָרִיךְ לוֹ! אֶלָּא סוֹד הוּא, וְשָׂרָה שּמַעַת מַה שֶּׁהָיָה אוֹמֵר (פתח האהל, זה הקדוש ברוך הוא, והוא אחריו מי שהיה אומר) פֶּתַח הָאֹהֶל, זוֹ הַדַּרְגָּה הַתַּחְתּוֹנָה, פֶּתַח הָאֱמוּנָה. וְהוּא אַחֲרָיו - (זה) שֶׁהוֹדָה לוֹ הַדַּרְגָּה הָעֶלְיוֹנָה (נ\"א: פתח האהל והוא אחריו זה הקדוש ברוך הוא, פתח האהל זו הדרגה התחתונה, והוא אחריו זו הדרגה העליונה). מִיּוֹם שֶׁהָיְתָה שָׂרָה בָּעוֹלָם לֹא שָׁמְעָה דְּבַר הַקָּדוֹשׁ בָּרוּךְ הוּא פְּרָט לְאוֹתָהּ שָׁעָה."],[7,"","דָּבָר אַחֵר - שֶׁהָיְתָה יוֹשֶׁבֶת שָׂרָה פֶּתַח הָאֹהֶל כְּדֵי לִשְׁמֹעַ הַדְּבָרִים, וְהִיא שָׁמְעָה הַדָּבָר הַזֶּה שֶׁהִתְבַּשֵּׂר בּוֹ אַבְרָהָם. (דבר אחר) וְהוּא אַחֲרָיו - אַבְרָהָם שֶׁהָיָה יוֹשֵׁב מֵאֲחוֹרֵי הַשְּׁכִינָה."],[8,"","וְאַבְרָהָם וְשָׂרָה זְקֵנִים בָּאִים בַּיָּמִים. מַה זֶּה בָּאִים בַּיָּמִים? הַשִּׁעוּרִים שֶׁל הַיָּמִים שֶׁאָז נִרְאוּ לָהֶם, הָאֶחָד מֵאָה וְהָאֶחָד תִּשְׁעִים, נִכְנְסוּ בַיָּמִים הַשִּׁעוּר שֶׁל הַיָּמִים כָּרָאוּי. בָּאִים בַּיָּמִים, כְּמוֹ שֶׁנֶּאֱמַר כִּי בָא הַיּוֹם, שֶׁהֶעֱרִיב הַיּוֹם לְהִכָּנֵס."],[9,"","חָדַל לִהְיוֹת לְשָׂרָה אֹרַח כַּנָּשִׁים. וְאוֹתָהּ שָׁעָה רָאֲתָה עַצְמָהּ בְּעִדּוּן אַחֵר, וְלָכֵן אָמְרָה וַאדֹנִי זָקֵן, שֶׁהֲרֵי הוּא לֹא כְדַאי לְהוֹלִיד כִּי הוּא זָקֵן."],[10,"","רַבִּי יְהוּדָה פָּתַח, (משלי לא) נוֹדַע בַּשְּׁעָרִים בַּעְלָהּ בְּשִׁבְתּוֹ עִם זִקְנֵי אָרֶץ. בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בִּכְבוֹדוֹ שֶׁהוּא גָנוּז וְנִסְתָּר בְּעִלּוּי רַב. לֹא הָיָה בָּעוֹלָם וְלֹא הָיָה מֵהַיּוֹם שֶׁנִּבְרָא הָעוֹלָם שֶׁיָּכוֹל לַעֲמֹד עַל חָכְמָתוֹ וְלֹא יָכוֹל לַעֲמֹד בּוֹ."],[11,"","מִשּׁוּם כִּי הוּא גָנוּז וְנִסְתָּר וְהִתְעַלָּה לְמַעְלָה לְמַעְלָה, וְכָל הָעֶלְיוֹנִים וְהַתַּחְתּוֹנִים לֹא יְכוֹלִים לְהִתְדַּבֵּק עַד שֶׁכֻּלָּם אוֹמְרִים (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ. הַתַּחְתּוֹנִים אוֹמְרִים שֶׁהוּא לְמַעְלָה, שֶׁכָּתוּב (תהלים קיג) עַל הַשָּׁמַיִם כְּבוֹדוֹ. הָעֶלְיוֹנִים אוֹמְרִים שֶׁהוּא לְמַטָּה, שֶׁכָּתוּב (שם נז) עַל כָּל הָאָרֶץ כְּבוֹדֶךְ. עַד שֶׁכֻּלָּם, עֶלְיוֹנִים וְתַחְתּוֹנִים, אוֹמְרִים בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ, כִּי לֹא נוֹדַע וְלֹא הָיָה מִי שֶׁיָּכוֹל לַעֲמֹד עִמּוֹ, וְאַתָּה אוֹמֵר נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ?"]]],[["אֶלָּא וַדַּאי נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ אִתְיְדַע וְאִתְדָּבַּק לְפוּם מַה דִּמְשַׁעֵר בְּלִבֵּיהּ כָּל חַד כַּמָּה דְּיָכִיל לְאִדַּבְּקָא בְּרוּחָא דְּחָכְמְתָא. וּלְפוּם מַה דִּמְשַׁעֵר בְּלִבֵּיהּ הָכִי אִתְיְדַע בְּלִבֵּיהּ. וּבְגִינִי כָךְ נוֹדָע בַּשְּׁעָרִים בְּאִנּוּן שְׁעָרִים. אֲבָל דְּאִתְיְדַע כְּדְקָא יְאוּת לָא הֲוָה מַאן דְּיָכִיל לְאִדַּבְּקָא וּלְמִנְדַע לֵיהּ.","רַבִּי שִׁמְעוֹן אָמַר נוֹדָע בַּשְּׁעָרִים בַּעֲלָהּ. מַאן שְׁעָרִים. כְּמָא דְאַתְּ אָמֵר (תהילים כ״ד:ז׳) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם. וּבְגִין אֵלּוּ שְׁעָרִים דְּאִנּוּן דַּרְגִּין עִלָּאִין בְּגִינַיְיהוּ אִתְיְדַע קוּדְשָׁא בְּרִיךְ הוּא. וְאִי לָא לָא יָכְלִין לְאִתְדַּבָּקָא בֵּיהּ.","תָּא חֲזֵי, דְּהָא נִשְׁמָתָא דְּבַּר נָשׁ לָאו אִיהוּ (נ\"א לא אית) מַאן דְּיָכִיל לְמִנְדַע לָהּ, אֶלָּא בְּגִין אִלֵּין שַׁיְיפִין דְּגוּפָא וְאִנּוּן דַּרְגִּין דְּעָבְדִין אוּמָנוּתָא דְּנִשְׁמָתָא בְגִין כָּךְ אִתְיְדַע וְלָא אִתְיְדַע. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְיְדַע וְלָא אִתְיְדַע בְּגִין דְּאִיהוּ נִשְׁמָתָא לְנִשְׁמָתָא רוּחָא לְרוּחָא גָּנִיז וְטָמִיר מִכֹּלָּא, אֲבָל בְּאִנּוּן שְׁעָרִים דְּאִנּוּן פִּתְחִין לְנִשְׁמָתָא אִתְיְדַע קוּדְשָׁא בְּרִיךְ הוּא.","תָּא חֲזֵי, אִית פִּתְחָא לְפִתְחָא וְדַרְגָּא לְדַרְגָּא, וּמִנַּיְיהוּ יְדִיעַ יְקָרָא דְּקוּדְשָׁא בְּרִיךְ הוּא. פֶּתַח הָאֹהֶל, דָּא הוּא פִּתְחָא דְצֶדֶק. כְּמָא דְאַתְּ אָמֵר (תהלים קיח) פִּתְח\"וּ לִ\"י שַׁעֲרֵ\"י צֶדֶ\"ק וְגו' דָּא פִּתְחָא קַדְמָאָה לְאָעֳלָא בֵּיהּ, וּבְהַאי פִּתְחָא אִתְחַזּוּן כָּל שְׁאָר פִּתְחִין עִלָּאִין. מַאן דְּזָכֵי לְהַאי (פתחא) זָכֵי לְמִנְדַע בֵּיהּ וּבְכֻלְהוֹ שְׁאָר פִּתְחִין בְּגִין דְּכֻלְהוּ שָׁרָאן עֲלֵיהּ.","וְהַשְׁתָּא דְּפִתְחָא דָא לָא אִתְיְדַע. בְּגִין דְּיִשְׂרָאֵל בְּגָלוּתָא וְכֻלְהוּ פִּתְחִין אִסְתַּלָּקוּ מִנֵּיהּ וְלָא יָכְלִין לְמִנְדַע וּלְאִתְדַּבְּקָא. אֲבָל בְּזִמְנָא דְּיִפְקוּן יִשְׂרָאֵל מִן גָּלוּתָא זְמִינִין כֻּלְהוּ דַּרְגִּין עִלָּאִין לְמִשְׁרֵי עֲלֵיהּ כְּדְקָא יְאוּת.","וּכְדֵין יִנְדְעוּן בְּנִי עָלְמָא חָכְמְתָא עִלָּאָה יַקִּירָא מַה דְּלָא הֲווּ יָדְעִין מִקַּדְמַת דְּנָא. דִּכְתִיב, (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ יְיָ רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת יְיָ. כֻּלְהוּ זְמִינִין לְאַשְׁרָאָה עַל הַאי פִּתְחָא תַּתָּאָה דְּאִיהוּ פֶּתַח הָאֹהֶל. וְכֻלְהוּ זְמִינִין לְאַשְׁרָאָה עַל מַלְכָּא מְשִׁיחָא בְּגִין לְמֵידַן עָלְמָא דִּכְתִיב וְשָׁפַט בְּצֶדֶק דַּלִּים וְגו'.","בְּגִינֵי כָךְ כַּד אִתְבַּשַּׂר אַבְרָהָם, הַאי דַרְגָּא הֲוָה אָמַר כְּמָה דְּאִתְּמָר דִּכְתִיב וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה. וַיֹּאמֶר, לָא כְּתִיב מַאן הֲוָה. וְדָא הוּא פֶּתַח הָאֹהֶל. וְעַל דָּא וְשָׂרָה שׁוֹמַעַת הַאי דַרְגָּא דְּהֲוָה מַלִּיל עִמֵּיהּ מַאן דְּלָא הֲוָה שְׁמָעַת מִקַּדְמַת דְּנָא. דִּכְתִיב וְשָׂרָה שׁוֹמַעַת פֶּתַח הָאֹהֶל דְּהֲוָה מְבַשֵּׂר וְאָמַר שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתֶּךָ.","תָּא חֲזֵי, כַּמָּה הוּא חֲבִיבוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְגַבֵּיהּ דְּאַבְרָהָם, דְּהָא לָא נָפַק מִנֵּיהּ יִצְחָק עַד דְּאִתְגְּזַר, לְבָתַר דְּאִתְגְּזַר אִתְבַּשַּׂר בֵּיהּ בְּיִצְחָק, בְּגִין דְּאִיהוּ כְּדֵין זַרְעָא קַדִּישָׁא, וְעַד לָא אִתְגְּזַר לָאו אִיהוּ זַרְעָא קַדִּישָׁא. וּכְדֵין אִיהוּ כְּמָה דִּכְתִיב, (בראשית א׳:י״ב) אֲשֶׁר זַרְעוֹ בוֹ לְמִינֵהוּ.","וְתָּא חֲזֵי, עַד לָא אִתְגְּזַר אַבְרָהָם הַהוּא זַרְעָא דִילֵיהּ לָא הֲוָה קַדִּישָׁא, בְּגִין דְּנָפַק בְּגוֹ עָרְלָה וְאִתְדְּבַק בְּעָרְלָה לְתַתָּא. לְבָתַר דְּאִתְגְּזַר נָפַק הַהוּא זַרְעָא בְּגוֹ קַדִּישָׁא, וְאִתְדְּבַק בִּקְדוּשָׁה דִּלְעֵילָא וְאוֹלִיד לְעֵילָא, וְאִתְדְּבַק אַבְרָהָם בְּדַרְגֵּיהּ כְּדְקָא יְאוּת. תָּא חֲזֵי, כַּד אוֹלִיד אַבְרָהָם לְיִצְחָק נָפַק קַדִּישָׁא כְּדְקָא יְאוּת. וְהַאי (נ\"א ודאי) מַאי אַעֲדוּ וְאוֹלִידוּ חֲשׁוֹכָא.","רַבִּי אֶלְעָזָר שָׁאִיל יוֹמָא חַד לְרַבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ הַאי דְּקָרָא לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא יִצְחָק דִּכְתִיב וְקָרָאת אֶת שְׁמוֹ יִצְחָק. אַמַּאי, דְּהָא אִתְחֲזֵי דְּעַד לָא נָפַק לְעָלְמָא קָרָא לֵיהּ יִצְחָק.","אָמַר לֵיהּ הָא אִתְּמָר דְּאֶשָׁא נָטַל מַיָא. דְּהָא מַיָא מִסִּטְרָא דִגְבוּרָה קָא אַתְיָין. וְתוּ (נ\"א ותא שאיל להו ללואי) (שאיל ליה) לֵוָאֵי דְּאִנּוּן בְּדִיחִין לְהַהוּא סִטְרָא בְּמָאנֵי זֶמֶר וְתֻשְׁבְּחָן לָקֳבֵיל הַאי סִטְרָא, בְגִין כָּךְ יִצְחָק אִיהוּ חֶדְוָה בְּגִין דְּאָתֵי מֵהַהוּא סִטְרָא וְאִתְדָּבַּק בֵּיהּ.","תָּא חֲזֵי, יִצְחָק בְּדִיחוּתָא חֶדְוָה דְּאַחְלַף מַיָא בְּאֶשָׁא וְאֶשָׁא בְּמַיָא, וְעַל דָּא אִקְרֵי הָכִי. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ הָכִי עַד לָא יִפּוּק לְעָלְמָא שְׁמָא דָּא וְאוֹדַע לֵיהּ לְאַבְרָהָם."],[[0,"אלא ודאי וכו':","אלא ודאי נודע בשערים בעלה, זהו הקב\"ה, שהוא נודע ומושג לפי מה שכל אחד משער בלבו, כפי שיוכל להשיג ברוח החכמה, ולפי מה שמשער בלבו כן נודע בלבו. ומשום זה כתוב נודע \u0003בשערים,\u0004 דהיינו באלו \u0003השיעורים,\u0004 שכל אחד משער בלבו, אבל שיהיה נודע כראוי, אין מי שיוכל להשיג ולדעת אותו."],[1,"ר' שמעון וכו':","ר\"ש אומר. נודע בשערים בעלה, מהו שערים. כמש\"א, שאו שערים ראשיכם וגו', ומכח אלו השערים, שהם מדרגות עליונות, בכחם נודע הקב\"ה, ואם לא היו אלו השערים, לא היו יכולים להשיג בו."],[2,"ת\"ח דהא נשמתא וכו':","בוא וראה, שגם נשמתו של אדם, אין מי שיוכל לדעת אותה, אלא מכח אלו אברי הגוף ואלו המדרגות של אברי הגוף, המגלות פעולות הנשמה, משום זה הנשמה נודעת ואינה נודעת: נודעת על ידי אברי הגוף, ואינה נודעת ממהותה עצמה. כך הקב\"ה נודע ואינו נודע, משום שהוא נשמה לנשמה רוח לרוח, גנוז ונעלם מכל. אבל להזוכה באלו השערים דהיינו המדרגות העליונות, כנ\"ל, שהם פתחים לנשמה, נודע לו הקב\"ה. ונמצא שנודע ע\"י מדרגות העליונות שהם פעולותיו, ואינו נודע מצד מהותו עצמו."],[3,"ת\"ח אית פתחא וכו':","בוא וראה, יש פתח לפתח, ומדרגה למדרגה, ומהם נודע כבודו של הקב\"ה. והיינו \u0003פתח האהל,\u0004 זה הוא פתח של צדק. שהיא המלכות, כמו שאתה אומר. פתחו לי שערי צדק. זהו פתח הראשון לכנוס בו בהשגה, ובפתח הזה נראים כל שאר פתחים העליונים. מי שזכה לפתח הזה, זכה להשיג אותו, ואת כל שאר הפתחים עמו, משום שכולם שורים עליו."],[4,"והשתא דפתחא וכו':","ועתה שפתח הזה, התחתון הנקרא פתח האהל, ופתח דצדק, לא נודע, משום שישראל הם בגלות, כל הפתחים נסתלקו ממנו. ואינם יכולים לדעת ולהשיג. אבל בזמן שיצאו ישראל מן הגלות, עתידים כל המדרגות העליונות לשרות על פתח דצדק כראוי."],[5,"וכדין ינדעון וכו':","ואז ידעו העולם חכמה עליונה היקרה, מה שלא ידעו מקודם לכן. שכתוב ונחה עליו רוח ה' רוח חכמה ובינה וגו'. כולם עתידים לשרות על פתח זה התחתון, שהוא פתח האהל, דהיינו המלכות. וכולם עתידים לשרות על מלך המשיח, כדי לדון העולם, שכתוב ושפט בצדק דלים וגו'."],[6,"בגיני כך כד וכו':","משום זה, כאשר נתבשר אברהם, בלידת יצחק, מדרגה זו דהיינו פתח האהל, שהיא המלכות, היתה אומרת לו, כמו שבארו, שכתוב. ויאמר שוב אשוב אליך כעת חיה, \u0003ויאמר,\u0004 ולא כתוב מי היה האומר, וזה הוא פתח האהל. (כנ\"ל באות ק\"מ) אשר ויאמר סתם הוא השכינה, ושרה שומעת מדרגה הזו, דהיינו פתח האהל, שהיתה מדברת עם אברהם, מה שלא שמעה מקודם לכן, שכתוב ושרה שומעת את דברי פתח האהל, שהיה מבשר ואומר שוב אשוב אליך וגו'."],[7,"ת\"ח כמה הוא וכו':","בוא וראה, כמה הוא חביבותו של הקב\"ה לאברהם, כי לא יצא ממנו יצחק מקודם שנמול. ורק אחר שנמול נתבשר ביצחק, בשביל שהוא אז זרע קודש, ומקודם שנמול אין הוא זרע קודש. ואז הוא כמו שכתוב, אשר זרעו בו למינהו, דהיינו למין קדוש כמו אברהם."],[8,"ות\"ח עד לא וכו':","ובוא וראה עד שלא נמול אברהם, הזרע שלו לא היה קדוש, משום שיצא בתוך הערלה, ונתדבק בערלה למטה. אחר שנמול, יצא הזרע בתוך קדוש, ונתדבק בקדושה שלמעלה. והוליד למעלה (כנ\"ל לך דף קמ\"ח אות תנ\"ז) ונתדבק אברהם במדרגתו, שהוא חסד כראוי. בוא וראה, כשהוליד אברהם ליצחק הוא יצא קדוש כראוי והמים האלו שהוא אברהם וחסד, הרו וילדו אפלה. דהיינו יצחק שה\"ס קו שמאל, שמטרם התלבשותו בחסדים של אברהם, הוא חושך, (כנ\"ל ב\"א דף ק\"ל ד\"ה וזה ע\"ש) ועל ידי שיצא מאברהם נתלבש בחסדים שלו ונעשה אור."],[9,"ר' אלעזר שאיל וכו':","יום אחד שאל ר' אלעזר את ר\"ש אביו. זה שקרא לו הקב\"ה יצחק למה, ואין לומר משום שאמרה צחוק עשה לי אלקים וגו'. כי נראה, שעוד מטרם שיצא לעולם קרא אותו הקב\"ה יצחק, שעוד לא היה טעם הזה."],[10,"א\"ל הא אתמר וכו':","אמר לו הרי למדנו, שאש שהוא שמאל וגבורה, לקח מים, שהוא ימין וחסד, והרי מים באים מצד הגבורה. כלומר שהשמאל והימין נכללו זה בזה. ואז נעשה צד השמאל בחינת יין המשמח אלקים ואנשים. \u0003ודא שאיל לליואי דאינון בדיחין\u0004 וכו', וזה שאל את הלוים, הנמשכים מקו שמאל, שהם משמחים לאותו הצד, דהיינו לצד שמאל, בכלי זמר ותשבחות שהם כנגד הצד הזה, כלומר שכלי זמר ותשבחות נמשכים ג\"כ מצד שמאל, משום זה יצחק הוא חדוה וצחוק, ומשום שבא מצד הזה, דהיינו מצד שמאל, ונתדבק בו."],[11,"תא חזי יצחק וכו':","בוא ראה, יצחק הוא שמחה וחדוה כי החליף מים באש ואש במים, כלומד ששמאל וימין כלולים. כי הוא בחינת שמאל שהוא אש, הנכלל במים שהוא ימין וחסד, כנ\"ל, שאז כל חדוה ושמחה משמאל נמשך. ומשום זה הקב\"ה קרא לו שם הזה, יצחק, עוד מטרם שיצא לעולם, והודיע לאברהם."]],[[0,"","אֶלָּא וַדַּאי נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא נוֹדָע וְנִדְבָּק לְפִי מַה שֶּׁמְּשַׁעֵר בְּלִבּוֹ כָּל אֶחָד כַּמָּה שֶׁיָּכוֹל לְהִדָּבֵק בָּרוּחַ שֶׁל הַחָכְמָה. וּלְפִי מַה שֶּׁמְּשַׁעֵר בְּלִבּוֹ, כָּךְ נוֹדָע בְּלִבּוֹ, וְלָכֵן נוֹדָע בַּשְּׁעָרִים - בְּאוֹתָם הַשְּׁעָרִים. אֲבָל שֶׁנּוֹדָע כָּרָאוּי אֵין מִי שֶׁיָּכוֹל לְהִדָּבֵק וְלָדַעַת אוֹתוֹ."],[1,"","רַבִּי שִׁמְעוֹן אָמַר, נוֹדָע בַּשְּׁעָרִים בַּעְלָהּ, אֵיזֶה שְׁעָרִים? כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) שְׂאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשְׂאוּ פִּתְחֵי עוֹלָם. וּמִשּׁוּם הַשְּׁעָרִים הַלָּלוּ, שֶׁהֵם דְּרָגוֹת עֶלְיוֹנוֹת, בִּגְלָלָם נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאִם לֹא - לֹא יְכוֹלִים לְהִתְדַּבֵּק בּוֹ."],[2,"","בֹּא רְאֵה, הֲרֵי נִשְׁמַת הָאָדָם אֵין הוּא (אין) מִי שֶׁיָּכוֹל לָדַעַת אוֹתָהּ, אֶלָּא עַל יְדֵי אֶבְרֵי הַגּוּף, וְהֵם הַדְּרָגוֹת שֶׁעוֹשׂוֹת אֻמָּנוּת הַנְּשָׁמָה. מִשּׁוּם כָּךְ נוֹדָע וְלֹא נוֹדָע. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹדָע וְלֹא נוֹדָע, מִשּׁוּם שֶׁהוּא נְשָׁמָה לִנְשָׁמָה, רוּחַ לְרוּחַ, גָּנוּז וְטָמִיר מִן הַכֹּל. אֲבָל בְּאוֹתָם הַשְּׁעָרִים, שֶׁהֵם פְּתָחִים לַנְּשָׁמָה, נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא."],[3,"","בֹּא רְאֵה, יֵשׁ פֶּתַח לְפֶתַח וְדַרְגָּה לְדַרְגָּה, וּמֵהֶם יָדוּעַ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. פֶּתַח הָאֹהֶל - זֶהוּ פֶּתַח שֶׁל צֶדֶק, כְּמוֹ שֶׁנֶּאֱמַר (שם קיח) פִּתְח\"וּ לִ\"י שַׁעֲרֵ\"י צֶדֶ\"ק וְגוֹ'. זֶהוּ פֶּתַח רִאשׁוֹן לְהִכָּנֵס בּוֹ, וּבַפֶּתַח הַזֶּה נִרְאִים כָּל שְׁאָר הַפְּתָחִים הָעֶלְיוֹנִים. מִי שֶׁזּוֹכֶה לָזֶה (לפתח), זוֹכֶה לָדַעַת אוֹתוֹ וּבְכָל שְׁאָר הַפְּתָחִים, מִשּׁוּם שֶׁכֻּלָּם שׁוֹרִים עָלָיו."],[4,"","וְעַכְשָׁו שֶׁפֶּתַח זֶה לֹא נוֹדָע, מִשּׁוּם שֶׁיִּשְׂרָאֵל בַּגָּלוּת וְכָל הַפְּתָחִים הִסְתַּלְּקוּ מִמֶּנּוּ וְלֹא יְכוֹלִים לָדַעַת וְלִדְבּק. אֲבָל בִּזְמַן שֶׁיִּשְׂרָאֵל יֵצְאוּ מִן הַגָּלוּת, עֲתִידוֹת כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת לִשְׁרוֹת עָלָיו כָּרָאוּי."],[5,"","וְאָז יָדְעוּ בְּנֵי הָעוֹלָם חָכְמָה עֶלְיוֹנָה נִכְבָּדָה מַה שֶּׁלֹּא הָיוּ יוֹדְעִים מִקֹּדֶם לָזֶה, שֶׁכָּתוּב (ישעיה יא) וְנָחָה עָלָיו רוּחַ ה' רוּחַ חָכְמָה וּבִינָה רוּחַ עֵצָה וּגְבוּרָה רוּחַ דַּעַת וְיִרְאַת ה'. כֻּלָּם עֲתִידִים לִשְׁרוֹת עַל הַפֶּתַח הַתַּחְתּוֹן הַזֶּה, שֶׁהוּא פֶּתַח הָאֹהֶל, וְכֻלָּם עֲתִידִים לִשְׁרוֹת עַל מֶלֶךְ הַמָּשִׁיחַ כְּדֵי לָדוּן הָעוֹלָם, שֶׁכָּתוּב וְשָׁפַט בְּצֶדֶק דַּלִּים וְגוֹ'."],[6,"","מִשּׁוּם כָּךְ, כְּשֶׁהִתְבַּשֵּׂר אַבְרָהָם, הַדַּרְגָּה הַזּוֹ הָיְתָה אוֹמֶרֶת כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה. וַיֹּאמֶר - לֹא כָּתוּב מִי הָיָה, וְזֶהוּ פֶּתַח הָאֹהֶל. וְעַל זֶה וְשָׂרָה שּמַעַת דַּרְגָּה זוֹ שֶׁהָיְתָה מְדַבֶּרֶת עִמּוֹ מַה שֶּׁלֹּא הָיְתָה שׁוֹמַעַת מִקֹּדֶם לָזֶה, שֶׁכָּתוּב וְשָׂרָה שּמַעַת פֶּתַח הָאֹהֶל, שֶׁהָיְתָה מְבַשֶּׂרֶת וְאוֹמֶרֶת שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְהִנֵּה בֵן לְשָׂרָה אִשְׁתְּךְ."],[7,"","בֹּא רְאֵה כַּמָּה חֲבִיבוּת הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, שֶׁהֲרֵי לֹא יָצָא מִמֶּנּוּ יִצְחָק עַד שֶׁנִּמּוֹל. אַחַר שֶׁנִּמּוֹל הִתְבַּשֵּׂר עַל יִצְחָק, מִשּׁוּם שֶׁאָז הוּא זֶרַע קָדוֹשׁ, וְטֶרֶם שֶׁנִּמּוֹל אֵינוֹ זֶרַע קָדוֹשׁ, וְאָז הוּא כְּמוֹ שֶׁכָּתוּב (בראשית א) אֲשֶׁר זַרְעוֹ בוֹ לְמִינֵהוּ."],[8,"","וּבֹא וּרְאֵה, טֶרֶם שֶׁנִּמּוֹל אַבְרָהָם זַרְעוֹ לֹא הָיָה קָדוֹשׁ, מִשּׁוּם שֶׁיָּצָא מִתּוֹךְ עָרְלָה וְהִדְבַּק בָּעָרְלָה לְמַטָּה. אַחַר שֶׁנִּמּוֹל, יָצָא אוֹתוֹ הַזֶּרַע בְּתוֹךְ הַקְּדֻשָּׁה, וְנִדְבַּק בַּקְּדֻשָּׁה שֶׁלְּמַעְלָה וְהוֹלִיד לְמַעְלָה, וְנִדְבַּק אַבְרָהָם בְּדַרְגָּתוֹ כָּרָאוּי. בֹּא רְאֵה, כְּשֶׁהוֹלִיד אַבְרָהָם אֶת יִצְחָק, יָצָא קָדוֹשׁ כָּרָאוּי. וְאֵלּוּ (ודאי) הַמַּיִם שֶּׁהָרוּ וְהוֹלִידוּ חֹשֶׁךְ."],[9,"","רַבִּי אֶלְעָזָר שָׁאַל יוֹם אֶחָד אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, זֶה שֶׁקָּרָא לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יִצְחָק, שֶׁכָּתוּב וְקָרָאתָ אֶת שְׁמוֹ יִצְחָק, לָמָּה? שֶׁהֲרֵי נִרְאֶה שֶׁעַד שֶׁלֹּא יָצָא לָעוֹלָם קָרָא לוֹ יִצְחָק?"],[10,"","אָמַר לוֹ, הֲרֵי נֶאֱמַר שֶׁאֵשׁ לוֹקַחַת מַיִם, שֶׁהֲרֵי הַמַּיִם בָּאִים מִצַּד שֶׁל הַגְּבוּרָה, וְעוֹד (נ\"א: ובא תשאל מהלוים) (שאל אותו) הַלְוִיִּם שֶׁהֵם מְשַׂמְּחִים לְאוֹתוֹ הַצַּד בִּכְלֵי זֶמֶר וְתִשְׁבָּחוֹת כְּנֶגֶד הַצַּד הַזֶּה, מִשּׁוּם כָּךְ יִצְחָק הוּא חֶדְוָה, מִשּׁוּם שֶׁהוּא בָּא מֵאוֹתוֹ צַד וְנִדְבָּק בּוֹ."],[11,"","בֹּא רְאֵה, יִצְחָק צְחוֹק, חֶדְוָה שֶׁמַּחֲלִיפָה מַיִם בְּאֵשׁ וְאֵשׁ בְּמַיִם, וְעַל זֶה נִקְרָא כָּךְ. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ כָּךְ בְּטֶרֶם יָצָא לָעוֹלָם בְּשֵׁם זֶה וְהוֹדִיעַ לְאַבְרָהָם."]]],[["וְתָּא חֲזֵי, בְּכֻלְהוּ אָחֳרָנִין שָׁבַק לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְמִקְרֵי לוֹן שְׁמָהָן, וְאֲפִילּוּ נָשֵׁי הֲווּ קָרָאן לִבְנַיְיהוּ שְׁמָהָן, אֲבָל הָכָא לָא שָׁבַק קוּדְשָׁא בְּרִיךְ הוּא לְאִמֵּיהּ לְמִקְרֵי לֵיהּ שְׁמָא אֶלָּא לְאַבְרָהָם, דִּכְתִיב וְקָרָאתָ אֶת שְׁמוֹ יִצְחָק אַנְתְּ וְלָא אָחֳרָא, בְּגִין לְאַחְלָפָא מַיָּא בְּאֶשָׁא וְאֶשָׁא בְּמַיָא לְאַכְלָלָא לֵיהּ בְּסִטְרֵיהּ.","כֵּיוָן דְּאִתְבַּשַּׂר אַבְרָהָם בְּיִצְחָק, מַה כְּתִיב וַיָּקוּמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִיפוּ עַל פְּנִי סְדוֹם. רַבִּי אֶלְעָזָר אָמַר תָּא חֲזֵי, כַּמָּה אַנְהַג קוּדְשָׁא בְּרִיךְ הוּא טִיבוּ עִם כָּל בְּרִיָין וְכָל שֶׁכֵּן לְאִנּוּן דְּאָזְלֵי בְּאָרְחוֹי, דְּאָפִילּוּ בְּזִמְנָא דְּבָעֵי לְמֵידַן עָלְמָא, אִיהוּ גָּרִים לְמַאן דְרָחִים לֵיהּ לְמִזְכֵּי בְּמִלָּה עַד לָא יֵיתֵי הַהוּא דִּינָא לְעָלְמָא.","דְּתָנִינָן בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא רָחִים לֵיהּ לְבַּר נָשׁ, מְשַׁדֵּר לֵיהּ דּוֹרוֹנָא, וּמַאן אִיהוּ, מִסְּכֵּנָא, בְּגִין דְּיִזְכֵּי בֵּיהּ. וְכֵיוָן דְּזָכֵי בֵּיהּ, אִיהוּ אַמְשִׁיךְ עֲלֵיהּ חַד חוּטָא דְּחֶסֶד דְּאִתְמְשַׁךְ מִסְּטַר יָמִינָא וּפָרִישׂ אֲרֵישֵׁיהּ וְרָשִׁים לֵיהּ, בְּגִין דְּכַד יֵיתֵי דִינָא לְעָלְמָא הַהוּא מְחַבְּלָא יִזְדְּהַר בֵּיהּ, וְזָקֵיף עֵינוֹי וְחָמָא לְהַהוּא רְשִׁימוּ וּכְדֵין אִסְתַּלַּק מִנֵּיהּ וְאִזְדְּהַר בֵּיהּ. בְּגִינֵי כָךְ אַקְדִּים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בְּמָּה דְּיִזְכֵּי.","וְתָּא חֲזֵי, כַּד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאַיְתָאָה דִּינָא עַל סְדוֹם, אַזְכֵּי קֹדֶם לְאַבְרָהָם וְשַׁדַּר לֵיהּ דּוֹרוֹנָא לְמִזְכֵּי עִמְּהוֹן בְּגִין לְשֵׁזָבָא לְלוֹט בַּר אֲחוּהָ מִתַּמָּן, הֲדָא הוּא דִכְתִיב וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה. וְלָא כְּתִיב וַיִּזְכֹּר אֱלֹהִים אֶת לוֹט, דְּהָא בִּזְכוּתֵיהּ דְּאַבְרָהָם אִשְׁתְּזִיב. וּמַאי וַיִּזְכֹּר, דְּדָכִיר לֵיהּ מַאי דְּאַזְכֵּי קֹדֶם עִם אִנּוּן תְּלַת מַלְאָכִין.","כְּגַוְונָא דָא בַּר נָשׁ דְּיִזְכֵּי בִּצְדָקָה עִם בְּנֵי נְשָׁא, בְּשַׁעֲתָא דְדִינָא שָׁרְיָא בְּעָלְמָא קוּדְשָׁא בְּרִיךְ הוּא אַדְכַּר לֵיהּ לְהַהִיא צְדָקָה דְּעֲבַד. בְּגִין דְּבְּכָל שַׁעֲתָא דְּזָכֵי בַּר נָשׁ הָכִי אַכְתִּיב עֲלֵיהּ לְעֵילָא, וְאֲפִילּוּ בְּשַׁעֲתָא דְדִינָא שָׁרְיָא עֲלוֹי קוּדְשָׁא בְּרִיךְ הוּא אִדְכַּר לֵיהּ לְהַהוּא טִיבוּ דְּעֲבַד וְזָכָה עִם בְּנֵי נָשָׁא. כְּמָא דְאַתְּ אָמֵר, (משלי י״א:ד׳) וּצְדָקָה תַּצִּיל מִמָּוֶת. בְּגִינֵי כָךְ אַקְדִּים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם בְּגִין דְּיִזְכֵּי וִישֵׁזִיב לְלוֹט.","וַיַּשְׁקִיפוּ עַל פְּנֵי סְדוֹם. תָּא חֲזֵי, וַיָּקוּמוּ מִשָּׁם הָאֲנָשִׁים. מֵהַהִיא סְעוּדָה דְּאַתְקִין לוֹ אַבְרָהָם וְזָכָה בְּהוּ. אַף עַל גַּב דְּמַלְאָכִין הֲווּ, זָכָה בְּהוּ, וְכָל הַהוּא מֵיכְלָא לָא אִשְׁתָּאַר מִנֵּיהּ כְּלוּם, בְּגִינֵי דְּאַבְרָהָם, וּלְמִזְכֵּי בֵּיהּ, דְּהָא כְּתִיב וַיֹּאכֵלוּ בְּאֶשָׁא דִלְהוֹן (קכ א) אִתְאֲכִיל.","וְאִי תֵימָא הָא תְּלַת מַלְאָכִין הֲווּ. הַאי אֶשָׁ\"א. וְהַאי מַיָ\"א. וְהַאי רוּחָ\"א. אֶלָא כָּל חַד וְחַד כָּלִיל בְּחַבְרֵיהּ וּבְגִינֵי כָךְ וַיֹּאכֵלוּ. כְּגַוְונָא דָא (שמות כ״ד:י״א) וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. אֲכִילָה וַדָּאִית אֲכְלוּ דְּאִתְזָנוּ מִן שְׁכִינְתָּא, אוּף הָכָא וַיֹּאכֵלוּ גָּרְמוּ (נ\"א נרמז רמז) לְאִתְזְנָא (מניה) מֵהַהוּא סִטְרָא דְאַבְרָהָם אִתְדְּבַק בֵּיהּ, וּבְגִין כָּךְ לָא אַשְׁאָרוּ מִמַּה דְּיָהִיב לוֹן אַבְרָהָם כְּלוּם.","כְּגַוְּונָא דָּא בָּעֵי לֵיהּ לְבַּר נָשׁ לְמִשְׁתֵּי מֵהַהוּא כַּסָּא דִּבְרָכָה, בְּגִין דְּיִזְכֵּי לְהַהִיא בְּרָכָה דִּלְעֵילָא. אוּף אִנּוּן אֲכְלוּ מִמַּה דְּאַתְקִין לוֹן אַבְרָהָם בְּגִין דְּיִזְכּוּן לְאִתְזְנָא מִסִּטְרָא דְאַבְרָהָם. דְּהָא מֵהַהוּא סִטְרָא נָפִיק מְזוֹנָא לְכֻלְהוּ מַלְאֲכֵי עִלָּאֵי.","וַיַּשְׁקִיפוּ, אִתְעָרוּתָא דְּרַחֲמֵי לְשֵׁיזָבָא לְלוֹט. כְּתִיב הָכָא וַיַּשְׁקִיפוּ וּכְתִיב הָתָם (דברים כ״ו:ט״ו) הַשְׁקִיפָה מִמְּעוֹן קָדְשֶׁךָ. מַה לְּהַלָּן לְרַחֲמֵי אוּף הָכָא לְרַחֲמֵי.","וְאַבְרָהָם הוֹלֵךְ עִמָּם לְשַׁלְּחָם. לְמֶעְבַּד לוֹן לְוָיָה. אָמַר רַבִּי יֵיסָא אִי תֵימָא דְּאַבְרָהָם יָדַע דְּמַלְאָכִין אִנּוּן אַמַּאי אַעֲבִיד לוֹן לְוָיָה. אֶלָּא אָמַר רַבִּי אֶלְעָזָר אַף עַל גַּב דְּהֲוָה יָדַע (רגיל הוה למעכד לכלהו בני נשא דזמינין עמיה למעכד לון לויה) (נ\"א מה דהוה רגיל למעבד עם בני נשא עבד בהו ואלוי לון) בְּגִין דְּכָךְ אִצְטְרִיךְ לֵיהּ לְבַּר נָשׁ לְמֶעְבַּד לְוָיָה לְאוּשְׁפִּיזִין דְּהָא כֹּלָּא בְּהַאי תַּלְיָא,","וּבְעוֹד דְּאִיהוּ הֲוָה אָזִיל עִמְּהוֹן אִתְגְּלִי קוּדְשָׁא בְּרִיךְ הוּא עֲלֵיהּ דְּאַבְרָהָם דִּכְתִיב וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עוֹשֶׂה. וַיְיָ הוּא וּבֵית דִּינֵיהּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה אָזִיל עִמְּהוֹן."],[[0,"ות\"ח בכלהו אחרנין וכו':","ובוא ראה, בכל האחרים, חוץ מיצחק, הרשה להם הקב\"ה לקרוא שמות, ואפילו נשים היו קוראים שמות לבניהן, אבל כאן לא נתן הקב\"ה לאמו לקרוא לו שם, אלא לאברהם, שכתוב, וקראת את שמו יצחק, אתה ולא אחר. כדי להחליף מים באש ואש במים, דהיינו התכללות שמאל בימין וימין בשמאל כנ\"ל, כדי לכלול את יצחק בצד ימין שלו. פירוש כי השפיע לו ממדתו מדת החסד הנק' מים וימין, וקבל ממנו מהארת השמאל שה\"ס אש. ונכללו זה בזה ועל ידי התכללות הזה נתן לו השם יצחק. באופן שמה שאמר לו הקב\"ה וקראת את שמו יצחק, היינו שיעשה עמו את התכללות הנ\"ל, שבזה נעשה למקור השמחה והצחוק כנ\"ל."],[1,"כיון דאתבשר וכו':","כיון שנתבשר אברהם ביצחק, מה כתוב, ויקומו משם האנשים וישקיפו וגו': ר\"א אמר בוא וראה. כמה מנהיג הקב\"ה את כל הבריות במדת טובו, וכל שכן לאותם ההולכים בדרכיו, שאפילו בזמן שמבקש לדון העולם, הוא מסבב למי שאוהבו, שיזכה באיזה דבר, מטרם שיבא אותו הדין לעולם."],[2,"דתנינן בשעתא וכו':","שלמדנו, בשעה שהקב\"ה אוהב את האדם, שולח לו מתנה. ומה היא המתנה. עני, כדי שיזכה על ידו. וכיון שזכה על ידו, הקב\"ה ממשיך עליו חוט אחד של חסד, הנמשך מצד ימין, ופורש על ראשו, ורושם אותו. כדי כאשר יבא הדין לעולם יזהר בו אותו המחבל מלהזיקו, שנושא עיניו ורואה לאותו הרשימה, אז מסתלק ממנו ונזהר בו. משום זה הקדים לו הקב\"ה דבר במה שיזכה לזה."],[3,"ות\"ח כד בעא וכו':","ובוא וראה, כשרצה הקב\"ה להביא דין על סדום, זיכה מקודם את אברהם, ושלח לו מתנה דהיינו ג' המלאכים, שיזכה על ידיהם. כדי להציל את לוט בן אחיו משם. זהו שכתוב ויזכור אלקים את אברהם וישלח את לוט מתוך ההפכה, ולא כתוב, ויזכור את לוט, כי בזכותו של אברהם נצל. ומהו ויזכור. היינו, שזכר לו מה שזכה מקודם על ידי אותם ג' מלאכים."],[4,"כגוונא דא וכו':","כעין זה, מי שזוכה בצדקה עם בני אדם בשעה שהדין שורה בעולם, הקב\"ה זוכר לו אותו צדקה שעשה, משום שבכל שעה שאדם זוכה, נכתב לו כן למעלה, וע\"כ אפילו בשעה שהדין שורה בעולם הקב\"ה זוכר לו את הטוב שעשה וזכה עם בני אדם, כמו שאתה אומר וצדקה תציל ממות, משום זה, הקדים הקב\"ה וסבב לאברהם במה שיזכה על ידו, שיציל בזכותו את לוט."],[5,"וישקיפו על פני סדום:","בוא וראה, ויקומו משם האנשים, היינו מאותה סעודה שהתקין להם אברהם, וזכה על ידם. אף על פי שמלאכים היו, שאינם צריכים לסעודה, מכל מקום זכה על ידיהם. ומכל אותו המאכל לא נשאר כלום, כדי שאברהם יזכה על ידו, שהרי כתוב \u0003ויאכלו,\u0004 כי באש שלהם נאכל ונשרף."],[6,"ואי תימא וכו':","ואם תאמר, הרי ג' מלאכים היו זה אש וזה מים וזה רוח, כי גבריאל אש, ומיכאל מים, ורפאל רוח, וא\"כ רק גבריאל לבדו היה יכול לשרוף המאכל באשו, מה שאין כן מיכאל ורפאל שאינם אש כלל. ומשיב אלא כל אחד ואחד כלול בחברו, ונמצא שכל אחד היה בו אש מים רוח, ומשום זה כתב על כולם \u0003ויאכלו.\u0004 כי היה אש בכל אחד מהם, שהמאכל נשרף בו."],[6,"כגוונא דא ויחזו וכו':","כעין זה, ויחזו את האלקים ויאכלו וישתו. שאכילה ודאית אכלו, והיינו שנזונו מזיו השכינה, שזה נבחן להם לאכילה. אף \u0003ויאכלו\u0004 שבכאן, גרמו באכילתם, ליזון מאותו צד שאברהם נתדבק בו דהיינו ימין שהוא חסדים, ומשום זה לא השאירו כלום ממה שנתן להם אברהם. כדי להרבות בהמשכת החסדים כמה שאפשר."],[7,"כגוונא דא בעי וכו':","כעין זה, שצריך האדם לשתות מכוס של ברכה, כדי שעל ידי שתיתו יזכה אל הברכה של מעלה. אף המלאכים, אכלו ממה שהתקין להם אברהם, כדי שיזכו על ידי אכילתם, ליזון מצד אברהם, דהיינו אור החסדים, כי מאותו צד נמשכים המזונות לכל מלאכים העליונים."],[8,"וישקיפו:","פירושו, התעוררות של רחמים, להציל את לוט. ולומד גזירה שוה, כתוב כאן וישקיפו, וכתוב שם, השקיפה ממעון קדשך, מה שם השקפה לרחמים. אף כאן השקפה לרחמים."],[9,"ואברהם הולך עמם לשלחם:","היינו לעשות להם לויה. אמר ר' ייסא, אם תאמר שאברהם ידע שהם מלאכים למה עשה להם לויה. אלא אמר ר' אלעזר, אף על פי שהיה יודע שהם מלאכים, מה שהיה רגיל לעשות עם בני אדם, עשה גם בהם, וליוה אותם. כי כך צריך האדם לעשות לויה לאורחים. שהרי הכל תלוי בזה. כלומר, כל המצוה של הכנסת אורחים תלוי בלויה, שהוא גמר הדבר, ואין המצוה נקראת אלא על מי שגמרה."],[10,"ובעוד דאיהו וכו':","ובעוד שהוא היה הולך עמהם ללותם, נגלה עליו הקב\"ה. שכתוב וה' אמר המכסה אני מאברהם אשר אני עושה. \u0003והויה\u0004 היינו, הוא, ובית דינו, שהיא הנוקבא, משום שהקב\"ה היה הולך עמהם."]],[[0,"","וּבֹא וּרְאֵה, בְּכָל הָאֲחֵרִים הִשְׁאִיר לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לִקְרֹא לָהֶם שֵׁמוֹת, וַאֲפִלּוּ נָשִׁים הָיוּ קוֹרְאוֹת לִבְנֵיהֶן שֵׁמוֹת, אֲבָל כָּאן לֹא הִשְׁאִיר הַקָּדוֹשׁ בָּרוּךְ הוּא לְאִמּוֹ לִקְרֹא לוֹ שֵׁם, אֶלָּא לְאַבְרָהָם, שֶׁכָּתוּב וְקָרָאתָ אֶת שְׁמוֹ יִצְחָק. אַתָּה וְלֹא אַחֵר. כְּדֵי לְהַחֲלִיף מַיִם בְּאֵשׁ וְאֵשׁ בְּמַיִם לְהַכְלִילוֹ בְּצִדּוֹ."],[1,"","כֵּיוָן שֶׁהִתְבַּשֵּׂר אַבְרָהָם בְּיִצְחָק, מַה כָּתוּב? וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם. רַבִּי אֶלְעָזָר אָמַר, בֹּא רְאֵה כַּמָּה נוֹהֵג הַקָּדוֹשׁ בָּרוּךְ הוּא טוֹבָה עִם כָּל הַבְּרִיּוֹת, וְכָל שֶׁכֵּן לְאוֹתָם שֶׁהוֹלְכִים בִּדְרָכָיו, שֶׁאֲפִלּוּ בִּזְמַן שֶׁרוֹצֶה לָדוּן אֶת הָעוֹלָם, הוּא גוֹרֵם לְמִי שֶׁאוֹהֵב אוֹתוֹ לִזְכּוֹת בַּדָּבָר עַד שֶׁלֹּא יָבא אוֹתוֹ הַדִּין לָעוֹלָם."],[2,"","שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אֶת הָאָדָם, שׁוֹלֵחַ לוֹ דּוֹרוֹן, וּמִיהוּ? הֶעָנִי, כְּדֵי לִזְכּוֹת בּוֹ. וְכֵיוָן שֶׁזּוֹכֶה בּוֹ, הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶד שֶׁנִּמְשָׁךְ מִצַּד הַיָּמִין וּפוֹרֵס עַל רֹאשׁוֹ וְרוֹשֵׁם אוֹתוֹ, כְּדֵי שֶׁכְּשֶׁיָּבֹא הַדִּין לָעוֹלָם, אוֹתוֹ הַמַּשְׁחִית יִזָּהֵר בּוֹ, וּמֵרִים עֵינָיו וְרוֹאֶה אוֹתוֹ הָרֹשֶׁם, וְאָז מִסְתַּלֵּק מִמֶּנּוּ וְנִזְהָר עָלָיו. מִשּׁוּם כָּךְ מַקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַה שֶּׁיִּזְכֶּה."],[3,"","וּבֹא וּרְאֵה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָבִיא דִין עַל סְדם, זִכָּה קֹדֶם אֶת אַבְרָהָם וְשָׁלַח לוֹ דּוֹרוֹן לִזְכּוֹת עִמָּהֶם כְּדֵי לְהַצִּיל אֶת לוֹט בֶּן אָחִיו מִשָּׁם. זֶהוּ שֶׁכָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה, וְלֹא כָתוּב וַיִּזְכֹּר אֱלֹהִים אֶת לוֹט, שֶׁהֲרֵי בִּזְכוּת אַבְרָהָם נִצַּל. וּמַה זֶּה וַיִּזְכֹּר? שֶׁזָּכַר אוֹתוֹ מַה שֶּׁזָּכָה קֹדֶם עִם אוֹתָם שְׁלֹשֶׁת הַמַּלְאָכִים."],[4,"","כְּמוֹ זֶה, בֶּן אָדָם שֶׁזּוֹכֶה בִּצְדָקָה עִם בְּנֵי אָדָם, בְּשָׁעָה שֶׁדִּין שָׁרוּי בָּעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר לוֹ אֶת אוֹתָהּ הַצְּדָקָה שֶׁעָשָׂה. מִשּׁוּם שֶׁבְּכָל שָׁעָה שֶׁזּוֹכֶה בֶּן אָדָם, כָּךְ נִכְתָב עָלָיו לְמַעְלָה. וַאֲפִלּוּ בְּשָׁעָה שֶׁדִּין שׁוֹרֶה עָלָיו, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אֶת אוֹתוֹ הַטּוֹב שֶׁעָשָׂה וְזָכָה עִם בְּנֵי אָדָם, כְּמוֹ שֶׁנֶּאֱמַר (משלי יא) וּצְדָקָה תַּצִּיל מִמָּוֶת. מִשּׁוּם כָּךְ הִקְדִּים הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, כְּדֵי שֶׁיִּזְכֶּה וְיַצִּיל אֶת לוֹט."],[5,"","וַיַּשְׁקִפוּ עַל פְּנֵי סְדם. בֹּא רְאֵה, וַיָּקֻמוּ הָאֲנָשִׁים מִשָּׁם, מֵאוֹתָהּ סְעוּדָה שֶׁתִּקֵּן לָהֶם אַבְרָהָם וְזָכָה בָהֶם. אַף עַל גַּב שֶׁהָיוּ מַלְאָכִים, זָכָה בָהֶם. וְכָל אוֹתוֹ מַאֲכָל לֹא נִשְׁאַר מִמֶּנּוּ כְּלוּם, מִשּׁוּם אַבְרָהָם, וּלְזַכּוֹתוֹ, שֶׁהֲרֵי כָּתוּב וַיֹּאכֵלוּ, בָּאֵשׁ שֶׁלָּהֶם נֶאֱכַל."],[6,"","וְאִם תֹּאמַר, הֲרֵי שְׁלֹשָׁה מַלְאָכִים הָיוּ? זֶה אֵ\"שׁ וְזֶה מַיִ\"ם וְזֶה רוּ\"חַ. אֶלָּא כָּל אֶחָד וְאֶחָד כָּלוּל בַּחֲבֵרוֹ, וּמִשּׁוּם כָּךְ וַיֹּאכֵלוּ. כְּמוֹ זֶה (שמות כד) וַיֶּחֱזוּ אֶת הָאֱלֹהִים וַיֹּאכְלוּ וַיִּשְׁתּוּ. אֲכִילָה וַדָּאִית הֵם אָכְלוּ, שֶׁנִּזּוֹנוּ מֵהַשְּׁכִינָה. אַף כָּאן וַיֹּאכֵלוּ - גָּרְמוּ (נ\"א: נרמז רמז) לְהִזּוֹן (ממנו) מֵאוֹתוֹ הַצַּד שֶׁאַבְרָהָם נִדְבַּק בּוֹ, וּמִשּׁוּם כָּךְ לֹא הִשְׁאִירוּ כְלוּם מִמַּה שֶּׁנָּתַן לָהֶם אַבְרָהָם."],[7,"","כְּמוֹ כֵן צָרִיךְ הָאָדָם לִשְׁתוֹת מֵאוֹתָהּ כּוֹס שֶׁל בְּרָכָה כְּדֵי שֶׁיִּזְכֶּה לְאוֹתָהּ בְּרָכָה שֶׁלְּמַעְלָה, אַף הֵם אָכְלוּ מִמַּה שֶּׁתִּקֵּן לָהֶם אַבְרָהָם כְּדֵי שֶׁיִּזְכּוּ לְהִזּוֹן מֵהַצַּד שֶׁל אַבְרָהָם, שֶׁהֲרֵי מֵאוֹתוֹ צַד יוֹצֵא מָזוֹן לְכָל הַמַּלְאָכִים הָעֶלְיוֹנִים."],[8,"","וַיַּשְׁקִפוּ, הִתְעוֹרְרוּת שֶׁל רַחֲמִים לְהַצִּיל אֶת לוֹט. כָּתוּב כָּאן וַיַּשְׁקִפוּ, וְכָתוּב שָׁם (דברים כו) הַשְׁקִיפָה מִמְּעוֹן קָדְשֶׁךְ. מַה לְּהַלָּן לְרַחֲמִים - אַף כָּאן לְרַחֲמִים."],[9,"","וְאַבְרָהָם הֹלֵךְ עִמָּם לְשַׁלְּחָם, לַעֲשׂוֹת לָהֶם לְוָיָה. אָמַר רַבִּי יֵיסָא, אִם תֹּאמַר שֶׁאַבְרָהָם יָדַע שֶׁהֵם מַלְאָכִים, לָמָּה עָשָׂה לָהֶם לְוָיָה? אֶלָּא, אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁיָּדַע (רגיל היה לעשות לכל בני האדם שמזמנים עמו לעשות להם לויה). (מה שהיה רגיל לעשות עם בני אדם עשה בהם ולוה אותם), מִשּׁוּם שֶׁכָּךְ צָרִיךְ לָאָדָם לַעֲשׂוֹת לְוָיָה לָאוֹרְחִים, שֶׁהֲרֵי הַכֹּל תָּלוּי בָּזֶה."],[10,"","וּבְעוֹד שֶׁהוּא הָיָה הוֹלֵךְ עִמָּם, הִתְגַּלָּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶל אַבְרָהָם, שֶׁכָּתוּב וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה. וַה' - הוּא וּבֵית דִּינוֹ, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה הוֹלֵךְ עִמָּם."]]],[["תָּא חֲזֵי כַּד בַּר נָשׁ עֲבִיד לְוָיָה (לבר נש) לְחַבְרֵיהּ אִיהוּ אַמְשִׁיךְ (עליה) לִשְׁכִינְתָּא לְאִתְחַבְּרָא בַּהֲדֵיהּ וּלְמֵהַךְ עִמֵּיהּ בְּאָרְחָא לְשֵׁזָבָא לֵיהּ. וּבְגִין כָּךְ בָּעֵי לֵיהּ לְבַּר נָשׁ לְלַווּיֵי לְאוּשְׁפִּיזָא בְּגִין דְּחַבַּר לֵיהּ לִשְׁכִינְתָּא וְאַמְשִׁיךְ עֲלֵיהּ לְאִתְחַבְּרָא בַּהֲדֵיהּ.","בְגִין כָּךְ וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עוֹשֶׂה. רַבִּי חִיָּיא פָּתַח (עמוס ג׳:ז׳) כִּי לא יַעֲשֶׂה יְיָ אֱלהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים. זַכָּאִין אִנּוּן זַכָּאֵי עָלְמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, בְּכָל מַה דְּאִיהוּ עָבִיד בָּרְקִיעָא וְזַמִּין לְמֶעְבַּד בְּעָלְמָא, עַל יְדֵי דְּזַכָּאִין עֲבִיד לֵיהּ, וְלָא כַּסֵּי מִנַּיְיהוּ לְעָלְמִין כְּלוּם.","בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְשַׁתָּפָא בַּהֲדֵיהּ (לצדיקיא דלא תהא פתחון פה לרשיעייא בכל מה דאיהו עביד. תא חזי, כלא גלי קודשא בריך הוא) לְצַדִּיקַיָא בְּגִין דְּאִנּוּן אַתְיָין וּמַזְהִירִין לִבְנֵי נָשָׁא לְאֲתָבַא מֵחוֹבַיְיהוּ וְלָא יִתְעַנְשׁוּן מִגּוֹ דִּינָא עִלָּאָה וְלָא יְהֵא לוֹן פִּתְחָא דְפוּמָא לְגַבֵּיהּ. בְּגִינֵי כָךְ קוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לוֹן רָזָא דְּאִיהוּ עָבִיד בְּהוּ דִינָא. תּוּ בְּגִין דְּלָא יֵימְרוּן דְּהָא בְּלָא דִינָא עֲבִיד בְּהוּ דִּינָא.","אָמַר רַבִּי אֶלְעָזָר וַוי לוֹן לְחַיָּיבַיָא דְּלָא יָדְעִין וְלָא מַשְׁגִּיחִין וְלָא יָדְעִין לְאִסְתַּמְּרָא מֵחוֹבַיְיהוּ. וּמַה קוּדְשָׁא בְּרִיךְ הוּא דִּי כָּל עוֹבָדוֹהִי קְשׁוֹט וְאוֹרְחָתֵיהּ דִּין. לָא עָבִיד כָּל מַה דְּעֲבִיד בְּעָלְמָא עַד דְּגָלֵי לְהוּ לְצַדִּיקַיָיא בְּגִין דְלָא יְהֵא לוֹן פִּתְחָא דְפוּמָא לִבְנֵי נָשָׁא. (כאן שייך מה שבסוף הספר סימן ח\"י, עי' לקמן דף ק\"ו ע\"א ותמצאנו שם) גַּבֵּי בְּנֵי נָשָׁא לא כָל שֶׁכֵּן דְּאִית לוֹן לְמֶעְבַּד מִלַּיְיהוּ דְּלָא יְמַלְּלוּן בְּנֵי נָשָׁא סִטְיָא עֲלֵיהוֹן. וְכֵן כְּתִיב, (במדבר ל״ב:כ״ב) וִהְיִיתֶם נְקִיִּים מֵיְיָ וּמִיִּשְׂרָאֵל.","וְאִית לוֹן לְמֶעְבַּד דְּלָא יְהֵא לוֹן פִּתְחוֹן פֶּה לִבְנֵי נָשָׁא, וְיִתְרוּן בְּהוֹן אִי אִנּוּן חָטָאן וְלָא מַשְׁגְּחֵי לְאִסְתַּמָּרָא, דְּלָא יְהֵא לֵיהּ לְמִדַּת דִּינָא דְּקוּדְשָׁא בְּרִיךְ הוּא פִּתְחָא דְפוּמָא לְגַבַּיְיהוּ. וּבְמָּה, בִּתְשׁוּבָה וְעוֹבָדִין דְּכַשְׁרָן."],[[0,"ת\"ח כד ב\"נ וכו':","בוא וראה. כאשר האדם עושה לויה לחבירו, הוא ממשיך השכינה להתחבר עמו, וללכת עמו בדרך להציל אותו, ומשום זה צריך האדם ללוות את ארחו, משום שמחבר אותו אל השכינה, וממשיך עליו השכינה להתחבר עמו."],[1,"בג\"כ וה' אמר וכו':","ומשום זה שעשה לויה זכה, וה' אמר המכסה אני מאברהם אשר אני עושה. ר' חייא פתח. כי לא יעשה ה' אלקים דבר, כי אם וגו'. אשריהם צדיקי העולם שהקב\"ה רצה בהם, וכל מה שהוא עשה בשמים ועתיד לעשות בעולם, עושה על ידי הצדיקים, ואינו מעלים מהם כלום."],[2,"בגין דקב\"ה וכו':","משום שהקב\"ה רוצה לשתף עמו הצדיקים, כדי שיבואו ויזהירו את בני האדם שישובו מעונותיהם, ולא יענשו מדין העליון. ולא יהיה להם פתחון פה אליו לומר שלא הוזהרו ולא ידעו. משום זה הקב\"ה מודיע להם הסוד, שיעשה בהם דין. ועוד, שלא יאמרו, שמעניש אותם בלי משפט."],[3,"אמר ר' אלעזר וכו':","אר\"א, ווי להם לרשעים, שאינם יודעים ואינם מסתכלים לדעת, ואינם יודעים להשמר מעונותיהם. ומה הקב\"ה, שכל מעשיו אמת, ודרכיו משפט, אינו עושה כל מה שעושה בעולם, עד שמגלה אל הצדיקים, כדי שלא יהיה לבני אדם פתחון פה עליו, כנ\"ל, בני אדם עצמם, לא כל שכן, שיש להם לעשות דבריהם, באופן שלא ידברו בני אדם שטנה עליהם. וכן כתוב, והייתם נקיים מה' ומישראל."],[4,"ואית לון וכו':","ויש להם, לצדיקים, לעשות שלא יהיה פתחון פה לבני אדם על הקב\"ה, ויזהירו אותם, אם חוטאים ואינם משגיחים על עצמם להשמר, שיהיה למדת הדין של הקב\"ה פתחון פה לקטרג עליהם. ובמה ינצלו ממדת הדין. על ידי שיעשו תשובה ומעשים טובים."]],[[0,"","בֹּא רְאֵה, כְּשֶׁבֶּן אָדָם עוֹשֶׂה לְוָיָה (לאדם) לַחֲבֵרוֹ, הוּא מוֹשֵׁךְ אֶת הַשְּׁכִינָה לְהִתְחַבֵּר עִמּוֹ וְלָלֶכֶת עִמּוֹ בַּדֶּרֶךְ לְהַצִּילוֹ, וְלָכֵן צָרִיךְ אָדָם לְלַוּוֹת אֶת הָאוֹרֵחַ כְּדֵי לְחַבֵּר עִמּוֹ שְׁכִינָה וּמוֹשֵׁךְ עָלָיו לְהִתְחַבֵּר עִמּוֹ."],[1,"","מִשּׁוּם כָּךְ, וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה. רַבִּי חִיָּיא פָּתַח, (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים. אַשְׁרֵיהֶם צַדִּיקֵי הָעוֹלָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם, וְכָל מַה שֶּׁהוּא עוֹשֶׂה בָּרָקִיעַ וְעָתִיד לַעֲשׂוֹת בָּעוֹלָם - עַל יְדֵי הַצַּדִּיקִים עוֹשֶׂה אוֹתוֹ, וְלֹא מְכַסֶּה מֵהֶם כְּלוּם לְעוֹלָמִים,"],[2,"","כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְשַׁתֵּף עִמּוֹ אֶת (הצדיקים שלא יהיה פתחון פה לרשעים בכל מה שהוא עושה, בא ראה, הכל מגלה הקדוש ברוך הוא) לַצַּדִּיקִים, מִשּׁוּם שֶׁהֵם בָּאִים וּמַזְהִירִים אֶת בְּנֵי הָאָדָם לָשׁוּב מֵחֲטָאֵיהֶם וְלֹא יֵעָנְשׁוּ מִתּוֹךְ הַדִּין הָעֶלְיוֹן וְלֹא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה אֵלָיו. מִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ לָהֶם הַסּוֹד שֶׁהוּא עוֹשֶׂה בָהֶם הַדִּין. וְעוֹד, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁהֲרֵי בְּלִי דִין עָשָׂה בָהֶם דִּין."],[3,"","אָמַר רַבִּי אֶלְעָזָר, אוֹי לָרְשָׁעִים שֶׁלֹּא יוֹדְעִים וְלֹא מַשְׁגִּיחִים וְלֹא יוֹדְעִים לְהִשָּׁמֵר מֵחֲטָאֵיהֶם. וּמָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁכָּל מַעֲשָׂיו אֱמֶת וּדְרָכָיו דִּין אֵינוֹ עוֹשֶׂה כָּל מַה שֶּׁעוֹשֶׂה בָּעוֹלָם עַד שֶׁמְּגַלֶּה לַצַּדִּיקִים כְּדֵי שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה לִבְנֵי אָדָם, אֵצֶל בְּנֵי אָדָם לֹא כָּל שֶׁכֵּן שֶׁיֵּשׁ לָהֶם לַעֲשׂוֹת דִּבְרֵיהֶם שֶׁלֹּא יְדַבְּרוּ בְּנֵי אָדָם לָשׁוֹן הָרָע בָּהֶם. וְכֵן כָּתוּב (במדבר לב) וִהְיִיתֶם נְקִיִּים מֵה' וּמִיִּשְׂרָאֵל."],[4,"","וְיֵשׁ לָהֶם לַעֲשׂוֹת שֶׁלֹּא יִהְיֶה לָהֶם פִּתְחוֹן פֶּה לִבְנֵי אָדָם, וְיַתְרוּ בָהֶם אִם הֵם חוֹטְאִים וְלֹא מַשְׁגִּיחִים לְהִשָּׁמֵר, שֶׁלֹּא תִהְיֶה לְמִדַּת הַדִּין שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא פִּתְחוֹן פֶּה אֲלֵיהֶם, וּבַמֶּה? בִּתְשׁוּבָה וּמַעֲשִׂים כְּשֵׁרִים."]]],[["תָּא חֲזֵי, וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר רַבִּי יְהוּדָה, קוּדְשָׁא בְּרִיךְ הוּא יָהַב כָּל אַרְעָא לְאַבְרָהָם לְמֶהֱוֵי לֵיהּ אַחְסָנַת יְרוּתָא לְעָלְמִין, דִּכְתִיב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה לְךָ אֶתְּנֶנָּה וְגו'. וּכְתִיב שָׂא נָא עֵינֶיךָ וּרְאֵה. וּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא אִצְטְרִיךְ לְאַעֲקָרָא אַתְרִין אִלֵּין. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, כְּבָר יַהֲבִית יַת אַרְעָא לְאַבְרָהָם, וְהוּא אַבָּא לְכֹלָּא, דִּכְתִיב כִּי אַב הֲמוֹן גּוֹיִם נְתַתִּיךָ. וְלָא יָאוֹת לִי לְמִמְחֵי בְּנִין וְלָא אוֹדַע לַאֲבוּהוֹן דְּקָרִית לֵיהּ אַבְרָהָם אוֹהֲבִי. וּבְגִין כָּךְ אִצְטְרִיךְ לְאוֹדַע לֵיהּ, בְגִין כָּךְ (אמר) וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עוֹשֶׂה.","אָמַר רַבִּי אַבָּא תָּא חֲזֵי (קיא א) עִנְוְתָנוּתָא דְּאַבְרָהָם, דְּאַף עַל גַּב דְּאָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רַבָּה. וְעִם כָּל דָּא דְּאוֹרִיךְ עִמֵּיהּ וְאוֹדַע לֵיהּ דְּבָעֵי לְמֶעְבַּד דִּינָא בִּסְדוֹם, לָא בָּעָא קַמֵיהּ לְשֵׁזָבָא לֵיהּ לְלוֹט וְלָא יַעֲבִיד בֵּיהּ דִּינָא. מַאי טַעְמָא בְּגִין דְּלָא לְמִתְבַּע אַגְרָא מִן עוֹבָדוֹי.","וְעַל דָּא שָׁלַח קוּדְשָׁא בְּרִיךְ הוּא לְלוֹט וְשֵׁזִיב לֵיהּ בְּגִינֵיהּ דְּאַבְרָהָם. דִּכְתִיב וַיִּזְכֹּר אֱלהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגו'.","מַאי אֲשֶׁר יָשַׁב בָּהֵן לוֹט הָא אִתְּמָר. אֲבָל בְּגִין דְּכֻלְהוּ חַיָּיבִין וְלָא אִשְׁתְּכַח (בינייהו), מִכֻּלְהוּ דְּאִית לֵיהּ מִידִי דִּזְכוּ, בַּר לוֹט. מִכָּאן אוֹלִיפְנָא בְּכָל אֲתַר דְּדָיְירִין בֵּיהּ חַיָּיבִין חָרִיב אִיהוּ.","אֲשֶׁר יָשַׁב בָּהֵן לוֹט. (קח א) וְכִי בְּכֻלְהוּ הֲוָה יָתִיב לוֹט, אֶלָא בְּגִינֵיהּ הֲווּ יַתְבֵי דְּלָא אִתְחָרְבוּ. וְאִי תֵימָא בִּזְכוּתֵיהּ, לָא. אֶלָּא בִּזְכוּתֵיהּ דְּאַבְרָהָם.","אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, דְּשִׁמּוּשָׁא דְּעֲבִיד בַּר נָשׁ לְזַכָּאָה, הַהוּא שִׁמּוּשָׁא אָגִין עֲלֵיהּ בְּעָלְמָא. וְלָא עוֹד אֶלָּא דְּאַף עַל גַּב דְּאִיהוּ חַיָּיבָא, אוֹלִיף מֵאָרְחוֹי וְעֲבִיד לוֹן.","תָּא חֲזֵי דְּהָא בְּגִין דְּאִתְחַבַּר לוֹט בַּהֲדֵיהּ דְּאַבְרָהָם אַף עַל גַּב דְּלָא אוֹלִיף כָּל עוֹבָדוֹי, אוֹלִיף לְמֶעְבַּד טִיבוּ עִם בִּרְיָין כְּמָה דְּהֲוָה עָבִיד אַבְרָהָם, וְדָא הוּא דְּאוֹתִיב לְכָל אִנּוּן קַרְתֵּי כָּל הַהוּא זִמְנָא דְּיָתְבוּ בָּתַר דְּעָאל לוֹט בֵּינַיְיהוּ.","אָמַר רַבִּי שִׁמְעוֹן תָּא חֲזֵי, דִּשְׁכִינְתָּא לָא אַעֲדֵי מִנֵּיהּ דְּאַבְרָהָם בְּהַהִיא שַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ (בההוא זמנא דקודשא בריך הוא עמיה), אָמַר לֵיהּ רַבִּי אֶלְעָזָר וְהָא שְׁכִינְתָּא הֲוָה מַלִּיל עִמֵּיהּ דְּהָא (בדרגא) דָא אִתְגְּלִי עֲלֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב, (שמות ו׳:ג׳) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. אָמַר לֵיהּ הָכִי הוּא וַדַּאי.","וְתָּא חֲזֵי מַה כְּתִיב וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמֹרָה כִּי רָבָּה. בְּקַדְמִיתָא וַיְיָ אָמַר. וּלְבַסּוֹף וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמוֹרָה וְגו'. דָּא אִיהוּ דַּרְגָא עִלָּאָה דְּאִתְגְּלֵי לֵיהּ עַל דַּרְגָּא תַּתָּאָה,","\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 וַיְיָ אָמָר הַמְכַסֶּה אֲנִי מֵאַבְרָהָם וְגו' מַה כְּתִיב לְמַעְלָה וַיָּקוּמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִיפוּ עַל פְּנִי סְדוֹם לַעֲשׂוֹת דִּין בָּרְשָׁעִים. מַה כְּתִיב אַחֲרָיו הַמְכַסֶּה אֲנִי מֵאַבְרָהָם.","אָמַר רַב חַסְדָא אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִּין בָּרְשָׁעִים עַד שֶׁנִּמְלַךְ בְּנִשְׁמָתָן שֶׁל צַּדִּיקִים הֲדָא הוּא דִכְתִיב, (איוב ד׳:ט׳) מִנִּשְׁמַת אֱלוֹהַּ יֹאבֵדוּ. וּכְתִיב הַמְכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם יֵשׁ לִי לַעֲשׂוֹת דִּין בָּרְשָׁעִים עַד שֶׁאֱמָלֵךְ בְּנִשְׁמוֹת הַצַּדִּיקִים, וְאוֹמֵר לָהֶם, הָרְשָׁעִים חָטְאוּ לְפָנַי, אֶעֱשֶׂה בָּהֶם דִּין, דִּכְתִיב וַיֹּאמֶר יְיָ זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה וחַטָאתָם וְגו'.","אָמַר רַבִּי אַבְהוּ הַנְּשָׁמָה עוֹמֶדֶת בִּמְקוֹמָהּ וְהִיא יְרֵאָה לְהִתְקָרֵב אֵלָיו וְלוֹמַר לְפָנָיו כְּלוּם, עַד שֶׁיֹּאמַר לְמטטרו\"ן שֶׁיַּגִּישֶׁנָּה לְפָנָיו וְתֹאמַר מַה שֶׁרָצְּתָה, הֲדָא הוּא דִכְתִיב ויִּגַּשׁ אַבְרָהָם, וַיֹּאמֶר הַאַף תִּסְפֶּה צַּדִּיק עִם רָשָׁע חָלִילָה לְךָ וגו'.","אוּלַי יֵשׁ חֲמִשִּׁים צַּדִּיקִים וְגו'. הַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם שֶׁמָּא נִתְעַסְּקוּ בְּנ' פָּרָשִׁיּוֹת שֶׁל תּוֹרָה, וְאַף עַל פִּי שֶׁלא נִתְעַסְּקוּ לִשְׁמָהּ, שָׂכָר יִשׁ לָהֶם לָעוֹלָם הַבָּא וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כְּתִיב בַּתְרֵיהּ וַיֹּאמֶר יְיָ אִם אֶמְצָּא בִּסְדוֹם חֲמִשִּׁים צַּדִּיקִים וְגו'.","והָא (תנינן) יַתִּיר אִנּוּן פָּרָשִׁיּוֹת נ\"ג הֲווּ. אֶלָּא אָמַר רַבִּי אַבָּהוּ חֲמִשָּׁה סְפָרִים הֵם בַּתּוֹרָה וּבְכָל אֶחָד וְאֶחָד נִכְלָלִים עֲשֶׂרֶת הַדִּבְּרוֹת עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם חֲשׁוֹב עֲשָׂרָה בְּכָל חַד מִנְּהוֹן הוּא חֲמִשִּׁים.","עוֹד פּוֹתַחַת הַנְּשָׁמָה וְאוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם אַף עַל פִּי שֶׁלא נִתְעַסְּקוּ בַּתּוֹרָה שֶׁמָּא קִבְּלוּ עוֹנְשָׁם עַל מַה שֶּׁחָטְאוּ בְּבֵּית דִּין וְנִתְכַּפֵּר לָהֶם שֶׁנֶּאֱמַר (דברים כ״ה:ג׳) אַרְבָּעִים יַכֶּנּוּ לֹא יוֹסִיף. וּמִמַּה שֶּׁנִּתְבַּיְישׁוּ לִפְנֵיהֶם דַּיָּים לְהִתְכַּפֵּר (לפניהם) לָהֶם שֶׁלֹּא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כְּתִיב אַחֲרָיו לֹא אֶעֱשֶׂה בַּעֲבוּר הָאַרְבָּעִים.","עוֹד פּוֹתַחַת ואוֹמֶרֶת אוּלַי יִשׁ שָׁם שְׁלשִׁים, אוּלַי יִשׁ בֵּינֵיהֶם צַּדִּיקִים שֶׁהִשִּׂיגוּ שְׁלשִׁים מַעֲלוֹת הָרְמוּזִים בַּפָּסוּק (יחזקאל א׳:א׳) וַיְהִי בִּשְׁלשִׁים שָׁנָה וְהֵם כְּלוּלִים בְּל\"ב נְתִיבוֹת שֶׁהֵם כ\"ב אוֹתִיּוֹת וי' סְפִירוֹת לִפְעָמִים הֵם כְּלוּלִים לִשְׁמוֹנָה.","עוֹד פּוֹתַחַת ואוֹמֶרֶת אוּלַי יִמָּצְּאוּן שָׁם עֶשְׂרִים, שֶׁמָּא יְגָדְּלוּ בָּנִים לְתַלְמוּד תּוֹרָה ויִשׁ לָהֶם שָׂכָר לַעֲשֶׂרֶת הַדִּבְּרוֹת שְׁתֵּי פְּעָמִים בְּכָל יוֹם, דְּאָמַר רַבִּי יִצְּחָק כָּל הַמְגַדֵּל בְּנוֹ לְתַלְמוּד תּוֹרָה וּמוֹלִיכוֹ לְבֵית רַבּוֹ בַּבֹּקֶר וּבָעֶרֶב מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ קִיֵּים (עליו) הַתּוֹרָה ב' פְּעָמִים בְּכָל יוֹם. מַה כְּתִיב וַיֹּאמֶר לא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים.","עוֹד פּוֹתַחַת וְאוֹמֶרֶת אוּלַי יִמָּצְּאוּן שָׁם עֲשָׂרָה. אוֹמֶרֶת רִבּוֹנוֹ שֶׁל עוֹלָם שֶׁמָא הָיוּ מֵאוֹתָם הָעֲשָׂרָה הָרִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת שֶׁנּוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרֵיהֶם, מַה כְּתִיב (ביה) וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה.","כָּל זֶה יִשׁ לְנִשְׁמַת הַצַּדִּיק לוֹמַר עַל הָרְשָׁעִים, כֵּיוָן שֶׁלֹּא נִמְצָּא בְּיָדָם כְּלוּם, מַה כְּתִיב וַיֵּלֶךְ יְיָ כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. מַהוּ לִמְקוֹמוֹ. לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה.","אָמַר רַבִּי מִצְּוָה לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים כְּדֵי שֶׁיַּחְזְרוּ לְמוּטָב וְלא יִכָּנְסוּ לַגֵּיהִנֹּם. דִּכְתִיב, (תהילים ל״ה:י״ג) וַאֲנִי בַּחֲלוֹתָם לְבוּשִׁי שָׂק וְגו'. ואָמַר רַבִּי אָסוּר לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים שֶׁיִּסְתַּלְּקוּ מִן הָעוֹלָם, שֶׁאִלְמָלֵא סִלְּקוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְתֶרַח מִן הָעוֹלָם כְּשֶׁהָיָה עוֹבֵד עֲבוֹדָה זָרָה, לֹא בָּא אַבְרָהָם אָבִינוּ לָעוֹלָם, וְשִׁבְטֵי יִשְׂרָאֵל לא הָיוּ, וְהַמֶּלֶךְ דָּוִד וּמֶלֶךְ הַמָּשִׁיחַ, וְהַתּוֹרָה לֹא נִתְּנָה, וְכָל אוֹתָם הַצַּדִּיקִים וְהַחֲסִידִים והַנְּבִיאִים לא הָיוּ בָּעוֹלָם. אָמַר רַבִּי יְהוּדָה כֵּיוָן שֶׁרוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלא נִמְצָּא בָּרְשָׁעִים כְּלוּם מִכָּל אוֹתָם הָעִנְיָינִים, מַה כְּתִיב ויָּבֹאוּ שְׁנִי הַמַּלְאָכִים סְדוֹמָה וגו', (עד כאן מדרש הנעלם)"],[[0,"א\"ר יהודה וכו':","אר\"י, הקב\"ה נתן כל הארץ לאברהם שיהיה לו נחלה וירושה לעולם. שכתוב כל הארץ אשר אתה רואה וגו'. וכתוב שא נא עיניך וראה וגו'. ואחר כך כשהקב\"ה היה רוצה לעקור ולהחריב מקומות הללו, סדום ועמורה וכו' אמר הקב\"ה, כבר נתתי את הארץ לאברהם, והוא אב אל כולם, שכתוב, כי אב המון גוים נתתיך, ולא יאה לי להכות הבנים ולא להודיע לאביהם, שקראתיו אברהם אוהבי. ועל כן אני צריך להודיעו, ומשום זה, וה' אמר המכסה אני מאברהם אשר אני עושה."],[1,"אמר רבי אבא וכו':","אר\"א בוא ראה את הענוה של אברהם שאף על פי שאמר לו הקב\"ה, זעקת סדום ועמורה כי רבה וגו', ועם כל זה שהתמהמה עמו והודיע לו שרוצה לעשות דין בסדום, לא התפלל לפניו שיציל את לוט, ולא יעשה עמו דין, מהו הטעם. הוא, כדי שלא לבקש שכר על מעשיו."],[2,"ועל דא, שלח וכו':","ועל זה, אע\"פ שלא בקש, שלח הקב\"ה ללוט והציל אותו בשביל אברהם, שכתוב, ויזכור אלקים את אברהם וגו' בהפוך את הערים אשר ישב בהן לוט."],[3,"מאי אשר וכו':","מהו, אשר ישב בהן לוט למה נקראו על שמו. הוא נתבאר, אבל הוא משום שכולם היו רשעים ולא נמצא מי מכולם שיהיה לו דבר זכות חוץ מלוט. מכאן למדנו, שבכל מקום שיושבים שם רשעים הוא חרוב. כי מהכתוב שאומר, אשר ישב בהן לוט, משמע, שבשביל כל שאר שישבו שם לא נחשב לישוב, אלא כמו חרב ושממה מאין יושב, שהוא מטעם היותם רשעים."],[4,"אשר ישב בהן לוט:","ושואל וכי בכולם היה יושב לוט. ומשיב, אלא משום שבשבילו היו יושבים בערים, ולא נחרבו, על כן נקראו על שמו. ואם תאמר שהיה בזכותו של לוט, לא כן אלא בזכותו של אברהם."],[5,"א\"ר שמעון וכו':","אר\"ש. בוא ראה, השרות שאדם עושה אל הצדיק, שרות ההוא מגין עליו בעולם. ולא עוד אלא אף על פי שהוא רשע. הוא לומד מדרכיו ועושה אותם."],[6,"ת\"ח דהא וכו':","בוא ראה, כי בשביל שלוט נתחבר עם אברהם, אע\"פ שלא למד ממנו את כל מעשיו, למד ממנו לעשות טובה עם הבריות, כמו שעשה אברהם. וזה הוא, שאחר שלוט נכנס ביניהם היה מישב לכל אלו הערים כל אותו זמן שהיו מיושבים. וע\"כ כתוב, אשר ישב בהן לוט."],[7,"אר\"ש ת\"ח וכו':","אמר ר\"ש, בוא וראה, שהשכינה לא סרה מעם אברהם. באותו הזמן שהקב\"ה היה עמו. אמר לו ר' אלעזר, והרי השכינה עצמה היתה מדברת עמו, ולא הקב\"ה לבדו. כי במדרגה הזו נגלה עליו הקב\"ה, שכתוב, וארא אל אברהם וגו' באל שדי, שהוא השכינה. וא\"כ מה צריך להשמיענו, שהשכינה לא סרה מאברהם בעת שהקב\"ה היה עמו. אמר לו ר\"ש, כן הוא ודאי, והצדק עמך."],[8,"ת\"ח מה וכו':","בוא וראה מה כתוב, ויאמר ה' זעקת וגו'. תחילה כתוב \u0003וה' אמר,\u0004 שפירושו הוא ובית דינו, דהיינו השכינה. ולבסוף כתוב, ויאמר הוי\"ה, ואין הפירוש הויה לבדו, אלא הוא מדרגה העליונה הוי\"ה, שנגלה לו על מדרגה התחתונה, שהיא השכינה."],[13,"והא יתיר אינון וכו':","שואל, והרי יש יותר מחמשים פרשיות בתורה, כי הם נ\"ג פרשיות. ומשיב כדר' אבהו, שכל אחד מה' ספרים שבתורה כלול מיוד דברות שה\"ס עשרה מאמרות שבהם נברא העולם. והם חמשים."],[15,"עוד פותחת ואומרת וכו':","סוד ל\"ב נתיבות החכמה, הוא, כשזו\"ן, שהם כ\"ב אותיות עולים למ\"ן לבינה, שהיא יוד ספירות, נעשים בבינה ל\"ב בחינות שה\"ס ל\"ב נתיבות החכמה, כ\"ב מזו\"ן ועשרה מבינה עצמה. והענין הוא, כי בינה מצד עצמה היא חפיצה רק בחסדים, ולא בחכמה, בסו\"ה כי חפץ חסד הוא. אלא כשזו\"ן עולים אליה למ\"ן היא עולה לראש אריך אנפין ונעשית שם לחכמה. ונקראת משום זה אז, ל\"ב נתיבות החכמה. וז\"ש, \u0003שהשיגו שלשים מעלות\u0004 וכו' \u0003והם כלולים בל\"ב נתיבות שהם כ\"ב אותיות,\u0004 דהיינו זו\"ן, \u0003ויוד ספירות,\u0004 דהיינו בינה. שביחד הרי ל\"ב בחינות. \u0003לפעמים הם כלולים בשמונה.\u0004 היינו הבינה, שאין בה עשרה ספירות אלא רק שמונה ספירות. והיינו מבחינתה עצמה ולמטה, שחסרים לה כתר וחכמה, שה\"ס ג\"ר שלה, ואז אינה נבחנת לל\"ב נתיבות החכמה, אלא רק לשלשים מעלות בלבד. מטעם שהיא חסרה מחכמה. והם רמוזים בדברי אברהם, אולי יש שם שלשים וגו'."]],[[0,"","בֹּא רְאֵה, וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר רַבִּי יְהוּדָה, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אֶת כָּל הָאָרֶץ לְאַבְרָהָם לִהְיוֹת לוֹ נַחֲלַת יְרֻשָּׁה לְעוֹלָמִים, שֶׁכָּתוּב כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה לְךְ אֶתְּנֶנָּה וְגוֹ', וְכָתוּב שָׂא נָא עֵינֶיךְ וּרְאֵה. וּלְאַחַר מִכֵּן הִצְטָרֵךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲקֹר אֶת הַמְּקוֹמוֹת הַלָּלוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּבָר נָתַתִּי אֶת הָאָרֶץ לְאַבְרָהָם, וְהוּא אָב לַכֹּל, שֶׁכָּתוּב כִּי אַב הֲמוֹן גּוֹיִם נְתַתִּיךְ, וְלֹא נָאֶה לִי לִמְחוֹת בָּנִים בְּלִי לְהוֹדִיעַ לַאֲבִיהֶם שֶׁקָּרָאתִי לוֹ אַבְרָהָם אֹהֲבִי, וּמִשּׁוּם כָּךְ צָרִיךְ לְהוֹדִיעוֹ, מִשּׁוּם כָּךְ (אמר) וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה."],[1,"","אָמַר רַבִּי אַבָּא, בֹּא רְאֵה עַנְוְתָנוּתוֹ שֶׁל אַבְרָהָם, שֶׁאַף עַל גַּב שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, וְעִם כָּל זֶה שֶׁהֶאֱרִיךְ עִמּוֹ וְהוֹדִיעַ לוֹ שֶׁרוֹצֶה לַעֲשׂוֹת דִּין בִּסְדם, לֹא בִקֵּשׁ מִמֶּנּוּ לְהַצִּיל אֶת לוֹט וְלֹא יַעֲשֶׂה בּוֹ דִּין. מָה הַטַּעַם בִּשְׁבִיל? שֶׁלֹּא לִתְבּעַ שָׂכָר מִמַּעֲשָׂיו."],[2,"","וְעַל זֶה שָׁלַח הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת לוֹט וְהִצִּילוֹ מִשּׁוּם אַבְרָהָם, שֶׁכָּתוּב וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגוֹ'."],[3,"","מַה זֶּה אֲשֶׁר יָשַׁב בָּהֵן לוֹט? הֲרֵי נֶאֱמַר, אֲבָל מִשּׁוּם שֶׁכֻּלָּם רְשָׁעִים וְלֹא נִמְצָא (ביניהם) מִכֻּלָּם שֶׁיֵּשׁ לוֹ דְּבַר זְכוּת פְּרָט לְלוֹט. מִכָּאן לָמַדְנוּ, שֶׁבְּכָל מָקוֹם שֶׁדָּרִים בּוֹ רְשָׁעִים הוּא חָרֵב."],[4,"","אֲשֶׁר יָשַׁב בָּהֵן לוֹט, וְכִי בְּכֻלָּם יָשַׁב לוֹט? אֶלָּא בִּגְלָלוֹ הָיוּ מְיֻשָּׁבִים וְלֹא חָרְבוּ. וְאִם תֹּאמַר בִּזְכוּתוֹ - לֹא! אֶלָּא בִּזְכוּת אַבְרָהָם."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, בֹּא רְאֵה שֶׁשִּׁמּוּשׁ שֶׁאָדָם עוֹשֶׂה לְצַדִּיק, אוֹתוֹ שִׁמּוּשׁ מֵגֵן עָלָיו בָּעוֹלָם, וְלֹא עוֹד, אֶלָּא שֶׁאַף עַל גַּב שֶׁהוּא רָשָׁע, לוֹמֵד מִדְּרָכָיו וְעוֹשֶׂה אוֹתָם."],[6,"","בֹּא רְאֵה, שֶׁהֲרֵי מִשּׁוּם שֶׁהִתְחַבֵּר לוֹט עִם אַבְרָהָם - אַף עַל גַּב שֶׁלֹּא לָמַד כָּל מַעֲשָׂיו, לָמַד לַעֲשׂוֹת חֶסֶד עִם הַבְּרִיּוֹת כְּמוֹ שֶׁהָיָה עוֹשֶׂה אַבְרָהָם, וְזֶהוּ שֶׁהָיָה מְיַשֵּׁב אֶת כָּל אוֹתָן הֶעָרִים כָּל אוֹתוֹ זְמַן שֶׁהָיוּ מְיֻשָּׁבִים אַחַר שֶׁנִּכְנַס לוֹט בֵּינֵיהֶם."],[7,"","אָמַר רַבִּי שִׁמְעוֹן, בּא רְאֵה שֶׁשְּׁכִינָה לֹא זָזָה מֵאַבְרָהָם בְּאוֹתָהּ שָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ (באותו זמן שהקדוש ברוך הוא עמו). אָמַר לוֹ רַבִּי אֶלְעָזָר, וַהֲרֵי שְׁכִינָה הָיְתָה מְדַבֶּרֶת עִמּוֹ, שֶׁהֲרֵי (בדרגה) זוֹ הִתְגַּלָּה אֵלָיו הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שמות ו) וָאֵרָא אֶל אַבְרָהָם אֶל יִצְחָק וְאֶל יַעֲקֹב בְּאֵל שַׁדָּי. אָמַר לוֹ, כָּךְ זֶה וַדַּאי."],[8,"","וּבֹא וּרְאֵה מַה כָּתוּב, וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה. בַּהַתְחָלָה וַה' אָמָר, וּלְבַסּוֹף וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה וְגוֹ'. זוֹהִי הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁהִתְגַּלְּתָה לוֹ עַל הַדַּרְגָּה הַתַּחְתּוֹנָה."],[9,"","וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם וְגוֹ'. מַה כָּתוּב לְמַעְלָה? וַיָּקֻמוּ מִשָּׁם הָאֲנָשִׁים וַיַּשְׁקִפוּ עַל פְּנֵי סְדם, לַעֲשׂוֹת דִּין בָּרְשָׁעִים. מַה כָּתוּב אַחֲרָיו? הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם."],[10,"","אָמַר רַב חַסְדָּא, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּרְשָׁעִים עַד שֶׁנִּמְלָךְ בְּנִשְׁמָתָם שֶׁל צַדִּיקִים. זֶהוּ שֶׁכָּתוּב (איוב ד) מִנִּשְׁמַת אֱלוֹהַּ יאבֵדוּ. וְכָתוּב הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: כְּלוּם יֵשׁ לִי לַעֲשׂוֹת דִּין בָּרְשָׁעִים עַד שֶׁאֶמָּלֵךְ בְּנִשְׁמוֹת הַצַּדִּיקִים. וְאוֹמֵר לָהֶם: הָרְשָׁעִים חָטְאוּ לְפָנַי, אֶעֱשֶׂה בָהֶם דִּין, שֶׁכָּתוּב וַיֹּאמֶר ה' זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה וְחַטָּאתָם וְגוֹ'."],[11,"","אָמַר רַבִּי אַבָּהוּ, הַנְּשָׁמָה עוֹמֶדֶת בִּמְקוֹמָהּ, וְהִיא יְרֵאָה לְהִתְקָרֵב אֵלָיו וְלוֹמַר לְפָנָיו כְּלוּם, עַד שֶׁיֹּאמַר לְמטטרו\"ן שֶׁיַּגִּישֶׁנָּה לְפָניו וְתֹאמַר מַה שֶּׁרָצְתָה. זֶהוּ שֶׁכָּתוּב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע וְגוֹ', חָלִילָה לְּךְ וְגוֹ'."],[12,"","אוּלַי יֵשׁ חֲמִשִּׁים צַדִּיקִם וְגוֹ'. הַנְּשָׁמָה פּוֹתַחַת וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא נִתְעַסְּקוּ בַּחֲמִשִּׁים פָּרָשִׁיּוֹת שֶׁל תּוֹרָה, וְאַף עַל פִּי שֶׁלֹּא נִתְעַסְּקוּ לִשְׁמָהּ, שָׂכָר יֵשׁ לָהֶם לָעוֹלָם הַבָּא וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כָּתוּב אַחֲרָיו? וַיֹּאמֶר ה' אִם אֶמְצָא בִסְדֹם חֲמִשִּׁים צַדִּיקִים וְגוֹ'."],[13,"","וַהֲרֵי (שנינו), אוֹתָן פָּרָשִׁיּוֹת יְתֵרוֹת חֲמִשִּׁים וְשָׁלֹשׁ הָיוּ. אֶלָּא, אָמַר רַבִּי אַבָּהוּ, חֲמִשָּׁה סְפָרִים הֵם בַּתּוֹרָה, וּבְכָל אֶחָד וְאֶחָד נִכְלָלִים עֲשֶׂרֶת הַדִּבְּרוֹת עֲשָׂרָה מַאֲמָרוֹת שֶׁבָּהֶם נִבְרָא הָעוֹלָם. חֲשֹׁב עֲשָׂרָה בְּכָל אֶחָד מֵהֶם - הוּא חֲמִשִּׁים."],[14,"","עוֹד פּוֹתַחַת הַנְּשָׁמָה וְאוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, אַף עַל פִּי שֶׁלֹּא נִתְעַסְּקוּ בַּתּוֹרָה, שֶׁמָּא קִבְּלוּ עָנְשָׁם עַל מַה שֶּׁחָטְאוּ בְּבֵית דִּין וְנִתְכַּפֵּר לָהֶם, שֶׁנֶּאֱמַר (דברים כה) אַרְבָּעִים יַכֶּנּוּ לֹא יֹסִיף. וּמִמַּה שֶּׁנִּתְבַּיְּשׁוּ לִפְנֵיהֶם, דַּיָּם לְהִתְכַּפֵּר (לפניהם) לָהֶם שֶׁלֹּא יִכָּנְסוּ לַגֵּיהִנֹּם. מַה כָּתוּב אַחֲרָיו? לֹא אֶעֱשֶׂה בַּעֲבוּר הָאַרְבָּעִים."],[15,"","עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יֵשׁ שָׁם שְׁלֹשִׁים? אוּלַי יֵשׁ בֵּינֵיהֶם צַדִּיקִים שֶׁהִשִּׂיגוּ שְׁלֹשִׁים מַעֲלוֹת הָרְמוּזִים בְּפָסוּק (יחזקאל א) וַיְהִי בִּשְׁלֹשִׁים שָׁנָה, וְהֵם כְּלוּלִים בְּל\"ב נְתִיבוֹת, שֶׁהֵם כ\"ב אוֹתִיּוֹת וְי' סְפִירוֹת, לִפְעָמִים הֵם כְּלוּלִים לִשְׁמֹנָה."],[16,"","עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יִמָּצְאוּן שָׁם עֶשְׂרִים, שֶׁמָּא יְגַדְּלוּ בָנִים לְתַלְמוּד תּוֹרָה וְיֵשׁ לָהֶם שָׂכָר לַעֲשֶׂרֶת הַדִּבְּרוֹת שְׁתֵּי פְעָמִים בְּכָל יוֹם, שֶׁאָמַר רַבִּי יִצְחָק, כָּל הַמְגַדֵּל בְּנוֹ לְתַלְמוּד תּוֹרָה וּמוֹלִיכוֹ לְבֵית רַבּוֹ בַּבֹּקֶר וּבָעֶרֶב, מַעֲלֶה עָלָיו הַכָּתוּב כְּאִלּוּ קִיֵּם (עליו) הַתּוֹרָה שְׁתֵּי פְעָמִים בְּכָל יוֹם. מַה כָּתוּב? וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים."],[17,"","עוֹד פּוֹתַחַת וְאוֹמֶרֶת: אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה. אוֹמֶרֶת: רִבּוֹנוֹ שֶׁל עוֹלָם, שֶׁמָּא הָיוּ מֵאוֹתָם הָעֲשָׂרָה הָרִאשׁוֹנִים שֶׁל בֵּית הַכְּנֶסֶת שֶׁנּוֹטֵל שָׂכָר כְּנֶגֶד כֻּלָּם שֶׁבָּאִים אַחֲרֵיהֶם. מַה כָּתוּב (בו)? וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה."],[18,"","כָּל זֶה יֵשׁ לְנִשְׁמַת הַצַּדִּיק לוֹמַר עַל הָרְשָׁעִים. כֵּיוָן שֶׁלֹּא נִמְצָא בְיָדָם כְּלוּם, מַה כָּתוּב? וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקֹמוֹ. מַהוּ לִמְקֹמוֹ? לִמְקוֹם מַעֲלָתוֹ הַיְדוּעָה."],[19,"","אָמַר רַבִּי, מִצְוָה לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים כְּדֵי שֶׁיַּחְזְרוּ לְמוּטָב וְלֹא יִכָּנְסוּ לַגֵּיהִנֹּם, שֶׁכָּתוּב (תהלים לה) וַאֲנִי בַּחֲלוֹתָם לְבוּשִׁי שָׂק וְגוֹ'. וְאָמַר רַבִּי, אָסוּר לוֹ לָאָדָם לְהִתְפַּלֵּל עַל הָרְשָׁעִים שֶׁיִּסְתַּלְּקוּ מִן הָעוֹלָם, שֶׁאִלְמָלֵא סִלְּקוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְתֶרַח מִן הָעוֹלָם כְּשֶׁהָיָה עוֹבֵד עֲבוֹדָה זָרָה, לֹא בָא אַבְרָהָם אָבִינוּ לָעוֹלָם, וְשִׁבְטֵי יִשְׂרָאֵל לֹא הָיוּ, וְהַמֶּלֶךְ דָּוִד וּמֶלֶךְ הַמָּשִׁיחַ, וְהַתּוֹרָה לֹא נִתְּנָה, וְכָל אוֹתָם הַצַּדִּיקִים וְהַחֲסִידִים וְהַנְּבִיאִים לֹא הָיוּ בָּעוֹלָם. אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁרוֹאֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא נִמְצָא בָּרְשָׁעִים כְּלוּם מִכָּל אוֹתָם הָעִנְיָנִים, מַה כָּתוּב? וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה וְגוֹ'. עַד כָּאן מִדְרָשׁ הַנֶּעְלָם"]]],[["אֵרְדָה נָא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה. לְמַאן קָאֲמַר. אִי תֵימָא לְאִנּוּן מַלְאָכִין. מַאן חָמָא מַלִּיל עִם דָּא וּפַקִּיד לְדָא. אֶלָּא לְאַבְרָהָם קָאֲמַר דְּבִרְשׁוּתֵיהּ קָיְימִין אִנּוּן אַתְרֵי. דָּבָר אַחֵר לְאִנּוּן מַלְאָכִין.","מַה דְּאִתְּמָר לְאַבְרָהָם מַה טַעֲמָא עָשׂוּ. עָשָׂה מִבָּעֵי לֵיהּ. מַאי עָשׂוּ. (אלא) דָּא אַבְרָהָם וּשְׁכִינְתָּא דְּלָא אַעֲדֵי מִנֵּיהּ. (דבר אחר) עָשׂוּ מַה דְּאִתְּמָר לַמַּלְאָכִין, בְּגִין דְּהֲווּ זְמִינִין תַּמָּן וְהֲווּ מִשְׁתַּכְּחִין לְמֶעְבַּד דִּינָא, וְעַל דָּא עָשׂוּ.","דָּבָר אַחֵר עָשׂוּ (למעבד) כְּתַרְגּוּמוֹ עֲבְדוּ. וְכִי לָא הֲוָה יָדַע קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ אָמַר אֵרְדָה נָא וְאֶרְאֶה, וְהָא כֹּלָּא אִתְגְּלִי קַמֵּיהּ. אֶלָּא אֵרְדָה נָא מִדַּרְגָּא דְּרַחֲמֵי לְדַרְגָּא דְדִינָא, וְהַיְינוּ (האי) יְרִידָה. וְאֶרְאֶה, רְאִיָּיה דָּא הִיא לְאַשְׁגָּחָא עֲלֵיהוֹן בְּמַאן דִּינָא יָדִין לוֹן.","אַשְׁכְּחָן רְאִיָּיה לְטַב וְאַשְׁכְּחָן רְאִיָּיה לְבִישׁ. רְאִיָּיה לְטַב, דִּכְתִיב, (שמות ב׳:כ״ה) וַיַּרְא אֱלֹהִים אֶת בְּנִי יִשְׂרָאֵל וַיֵּדַע. רְאִיָּיה לְבִישׁ, דִּכְתִיב אֵרְדָה נָא וְאֶרְאֶה (נ\"א אשכחן ירידה לטב ואשכחן ירידה לביש. לטב דכתיב, (שמות י״ט:כ׳) וירד יי על הר סיני. (במדבר י״א:י״ז) וירדתי ודברתי עמך שם. ירידה לביש ארדה נא בגין) לְאַשְׁגָּחָא עֲלַיְיהוּ בְּדִינָא, וְעַל דָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא הַמְכַסֶּה אֲנִי מֵאַבְרָהָם:","וְאַבְרָהָם הָיוֹ יִהְיֶה לְגוֹי גָּדוֹל וְעָצוּם. מַאי טַעְמָא בְּרָכָה דָא הָכָא. אֶלָא בְּגִין לְאוֹדָעָא דְּאָפִילּוּ בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָתִיב בְּדִינָא עַל עָלְמָא לָא אִשְׁתַּנִּי. דְּהָא יָתִיב בְּדִינָא עַל דָּא (ד\"א ל\"ג ויתיב) וּבְרַחֲמֵי עַל דָּא וְכֹלָּא בְּרִגְעָא חָדָא וּבְשַׁעֲתָא חָדָא.","אָמַר רַבִּי יְהוּדָה וְהָא כְּתִיב, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ עֵת רָצוֹן. זִמְנִין דְּאִיהוּ עֵת רָצוֹן וְזִמְנִין דְּלָאו אִיהוּ עֵת רָצוֹן. זִמְנִין דְּשָׁמַע וְזִמְנִין דְּלָא שָׁמַע. זִמְנִין דְּאִשְׁתְּכַח וְזִמְנִין דְּלָא אִשְׁתְּכַח דִּכְתִיב, (ישעיהו נ״ה:ו׳) דִּרְשׁוּ יְיָ בְּהִמָּצְאוֹ קְרָאוּהוּ בִּהְיוֹתוֹ קָרוֹב.","אָמַר רַבִּי אֶלְעָזָר כָּאן לְיָחִיד כָּאן לְצִבּוּר. כָּאן לְאֲתַר חָד וְכָאן לְכוּלֵי עָלְמָא. בְּגִינִי כָךְ בָּרִיךְ לֵיהּ לְאַבְרָהָם דְּאִיהוּ שָׁקִיל כְּכָל עָלְמָא דִּכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם (וכתיב) וְתָנִינָן בְּאַבְרָהָם.","יִהְיֶה בְּגִימַטְרִיָּא שְׁלשִׁים. הָכִי תָּנִינָן תְּלָתִין צַדִּיקִים אַזְמִין קוּדְשָׁא בְּרִיךְ הוּא בְּכָל דָּרָא וְדָרָא לְעָלְמָא. כְּמָה דְּאַזְמִין לְאַבְרָהָם.","פָּתַח וְאָמַר, (שמואל ב כ״ג:כ״ג) מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד וְאֶל הַשְּׁלשָׁה לֹא בָא וְגו'. מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד, אִלֵּין אִנּוּן תְּלָתִין צַדִּיקִים דְּאַזְמִין קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמָא וְלָא יְבַטֵּל לוֹן מִנֵּיהּ. וּבְנָיָהוּ בֶּן יְהוֹיָדָע כְּתִיב בֵּיהּ מִן הַשְּׁלשִׁים הֲכִי נִכְבָּד אִיהוּ חַד מִנַּיְיהוּ. וְאֶל הַשְּׁלשָׁה לא בָא. דְּלָא שָׁקִיל לִתְלָתָא אָחֳרָנִין דְּעָלְמָא קָאִים עֲלַיְיהוּ.","וְאֶל הַשְּׁלשָׁה לֹא בָא. לְמֶהוֵי בְּמִנְיָינָא כְּחַד מִנַּיְיהוּ. בְּאִנּוּן תְּלָתִין זַכָּאִין זָכָה לְמֵיעַל בְּחוּשְׁבְּנָא, אֲבָל וְאֶל הַשְּׁלשָׁה לֹא בָא, דְּלָא זָכָה לְאִתְחַבְּרָא בְּהוּ וּלְמֶהֱוֵי עִמְּהוֹן בְּחוּלָקָא חָדָא. יִהְיֶ\"ה, כְּמָה דְּתָנִינָן תְּלָתִין הֲוָה. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא בָּרְכֵיהּ בְּאִנּוּן תְּלָתִין צַדִּיקִים.","תָּא חֲזֵי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה, דְּהָא סְלִיקַת קֳדָמַי מַה דְּאִנּוּן עָבְדִין לְכָל עָלְמָא, דְּכָל עָלְמָא מָנְעֵי רַגְלַיְיהוּ דְּלָא לְמֵיעַל בִּסְדוֹם וַעֲמוֹרָה דִּכְתִיב, (איוב כ״ח:ד׳) פָּרַץ נַחַל מֵעִם גָּר הַנִּשְׁכָּחִים מִנִּי רָגֶל דַּלּוּ מֵאֱנוֹשׁ נָעוּ. פָּרַץ נַחַל מֵעִם גָּר, פִּרְצָה הֲוָה פָּרִיץ נַחַל לְאִנּוּן בְּנֵי עָלְמָא דְּעָאלוּ לְתַמָּן. דְּכֻלְהוּ דְּחָמָאן לְמַאן דְּהֲווּ יַהֲבֵי לְמֵיכַל וּלְמִשְׁתֵּי לְבַר נָשׁ אָחֳרָא, שַׁדְיָין לֵיהּ (בנוקבי דנקרי) בְּעוּמְקָא דְּנַהֲרָא, וְאִיהוּ דְּנָטִיל לֵיהּ הָכִי נָמֵי.","וְעַל דָּא כֻּלְהוּ בְּנֵי עָלְמָא הֲווּ נִשְׁכָּחִים מִנִּי רָגֶל. דְּמָנְעֵי רַגְלַיְיהוּ דְּלָא לְמֵיעַל תַּמָּן. וּמַאן דְּעָאל, דַּלּוּ מֵאֱנוֹשׁ נָעוּ, דְּהֲווּ דָּלֵי גוּפָא בְּכַפְנָא לָא הֲווּ יַהֲבֵי לֵיהּ לְמֵיכַל וּלְמִשְׁתֵּי וְאִשְׁתַּנֵּי דִּיוּקְנֵיהּ מִשְּׁאָר בְּנֵי עָלְמָא, דִּכְתִיב דַּלּוּ מֵאֱנוֹשׁ, נָעוּ. כְּתִיב הָכָא נָעוּ. וּכְתִיב הָתָם (משלי ה׳:ו׳) נָעוּ מַעְגְּלוֹתֶיהָ. הָכִי נָמֵי הֲווּ סָטָאן מַעֲגָלִין וְאָרְחִין דְּלָא לְמֵיעַל תַּמָּן. וְאֲפִילּוּ עוֹפֵי שְׁמַיָא הֲווּ מָנְעֵי לְמֵיעַל תַּמָּן דִּכְתִיב, (איוב כ״ח:ז׳) נְתִיב לֹא יְדָעוֹ עַיִט וְגו'. וּבְגִינֵי כָךְ כֻּלֵּי עָלְמָא הֲווּ צָוְוחִין עַל סְדוֹם וְעַל עֲמוֹרָה וְעַל כֻּלְהוּ קַרְתֵּי. דְּכֻלְהוּ כְּגַוְונָא חָדָא הֲווּ."],[[0,"ארדה נא וכו':","שואל למי אמר הקב\"ה, עשו כלה. כי הזהר דורש הכתוב, כאלו היה כתוב, \u0003עשו\u0004 עם חטף פתח תחת ה \u0003ע\u0004 שהיא ציווי. אם תאמר, שאמר לאלו המלאכים, עשו כלה. מי ראה כזאת, שמדבר עם זה עם אברהם, ומצוה לזה להמלאכים, ואומר, אלא שאמר לאברהם עשו כלה, כי אלו המקומות ברשותו היו עומדים. פירוש אחר, שאמר לאלו המלאכים, עשו כלה."],[1,"מה דאתמר לאברהם וכו':","ושואל, מה שאמרנו שאמר לאברהם עשו כלה, מה הטעם, שכתוב \u0003עשו\u0004 לשון רבים, היה צריך לכתוב \u0003עשה\u0004 לשון יחיד. למה אמר עשו. ואומר, שזה אמר לאברהם ולהשכינה שלא סרה ממנו וע\"כ אמר עשו."],[1,"מה דאתמר למלאכים","וכו': ושואל מה שאמרנו, שלמלאכים אמר עשו כלה, צריכים לישב הקושיא הנ\"ל, מי ראה כזאת לדבר עם זה ולצות לאחר. ומשיב. שהוא משום שהמלאכים היו עומדים שם, והיו נמצאים שם כדי לעשות דין, ועל כן אמר להם \u0003עשו.\u0004"],[2,"ד\"א עשו וכו':","פירוש אחר, \u0003עשו\u0004 פירושו כתרגומו עבדו, דהיינו שה \u0003ע'\u0004 היא עם קמץ, וסיבב על אנשי סדום."],[2,"","ושואל, וכי לא היה יודע הקב\"ה, עד שהיה צריך לומר ארדה נא ואראה, והרי הכל גלוי לפניו. ואומר אלא \u0003ארדה נא\u0004 פירושו, ממדרגת הרחמים אל מדרגת הדין, והיינו הוא ירידה. \u0003ואראה,\u0004 ראיה זו, היא להשגיח עליהם באיזה דין ידין אותם."],[3,"אשכחן ראיה וכו':","מצאנו, ראיה שהוא לטוב, ומצאנו ראיה שהוא לרע. ראיה לטוב, שכתוב, וירא אלקים את בני ישראל וידע אלקים. ראיה לרע, שכתוב ארדה נא ואראה. להשגיח עליהם בדין ועל זה אמר הקב\"ה המכסה אני מאברהם."],[4,"ואברהם היו יהיה לגוי גדול ועצום:","שואל מהו הטעם של ברכה זו כאן. ואומר, אלא כדי להשמיענו, שגם בשעה שהקב\"ה יושב בדין על העולם, אינו משתנה, כי יושב בדין על זה, וברחמים על זה והכל ברגע אחד ובשעה אחת. כי לסדום היה בדין, ולאברהם היה באותה שעה ברחמים, וברכו, ואברהם היו וגו'."],[5,"א\"ר יהודה וכו':","אר\"י, והרי כתוב, ואני תפלתי לך ה' עת רצון, ומשמע, שפעמים הוא עת רצון ופעמים שאין אז עת רצון. פעמים שומע התפילה ופעמים אינו שומע התפילה. וכן פעמים שנמצא ופעמים שאינו נמצא, שכתוב, דרשו ה' בהמצאו, וגו'. ומשמע שפעמים אינו נמצא. דהיינו בעת דין, ואיך אתה אומר שאפילו ברגע שיושב בדין על זה יושב ברחמים על זה."],[6,"אר\"א כאן וכו':","א\"ר אלעזר, כאן ליחיד וכאן לצבור. ליחיד יש שינוי זמנים ולצבור הוא תמיד ברחמים ואפילו כשיושב בדין. כאן למקום אחד יש שינוי זמנים, וכאן לכל העולם, הוא תמיד ברחמים ואינו משתנה. ועל כן ברך לאברהם בשעה שהיה בדין על סדום, כי הוא שקול כנגד העולם כולו, שכתוב אלה תולדות השמים וארץ בהבראם, ולמדנו אשר בהבראם היא אותיות באברהם, שבשבילו נברא העולם. הרי שהוא שקול ככל העולם."],[7,"יהיה, בגימטריא וכו': יהיה,","הוא בגימטריא שלשים. כך למדנו, שלשים צדיקים הזמין הקב\"ה לעולם להיות בכל דור ודור, כמו שהזמין את אברהם. כלומר כי כתוב אלה תולדות וגו' בהבראם, שנתבאר, שהוא אותיות באברהם, שבשבילו נברא העולם. ואומר שכך בכל דור ודור יש ל' צדיקים שבשבילם נברא העולם כמו שנברא בשביל אברהם."],[8,"פתח ואמר מן השלשים הכי נכבד וגו':","מן השלשים הכי נכבד, אלו הם שלשים הצדיקים שהזמין הקב\"ה לעולם שלא יהיו חסרים מן העולם בכל דור: ובניהו בן יהוידע כתוב בו מן השלשים הכי נכבד, שהוא אחד מהם. היינו, שיש שלשה אחרים שהעולם עומד עליהם והוא אינו שקול כמוהם."],[9,"ואל השלשה לא בא וגו':","ואל השלשה לא בא, היינו להיות במנינם כאחד מהם. באלו שלשים הצדיקים זכה לכנס בחשבונם, אבל ואל השלשה, לא בא, שלא זכה להתחבר בהם ולהיות עמהם בחלק אחד. \u0003יהיה,\u0004 הוא כמו שלמדנו, ששלשים הוא, ובשביל זה הקב\"ה ברכו שיהיה שקול כאלו שלשים הצדיקים."],[10,"ת\"ח א\"ל קב\"ה וכו':","בוא וראה אמר הקב\"ה לאברהם זעקת סדום ועמורה כי רבה, כי עלה לפני מה שהם עושים לכל העולם. כי כל העולם מונעים את רגליהם מלכנס בסדום ועמורה, שכתוב פרץ נחל מעם גר הנשכחים וגו'. פרץ נחל מעם גר פירושו, פרצה היה פורץ הנחל שהוא סדום, לאלו בני העולם שנכנסו שם. שכולם, אם ראו למי, שהיה נותן לאכול ולשתות לאדם אחר, השליכו אותו בעומק הנהר, וכן השליכו את האדם שקיבל ממנו האכילה ושתיה."],[11,"ועל דא כלהו וכו':","ועל כן כל בני העולם היו \u0003נשכחים מני רגל,\u0004 כי מנעו את רגליהם מלכנוס שמה. ומי שנכנס שמה, \u0003דלו מאנוש נעו,\u0004 שהיו דולים את כחות הגוף ברעב שלא נתנו לו לאכול ולשתות ונשתנה צורתו משאר בני העולם, שכתוב דלו מאנוש נעו. כתוב כאן נעו וכתוב שם נעו מעגלותיה מה שם פירושו של נעו שנטו מעגלותיה ולא נמצאו, אף כאן דלו מארץ נעו פירושו שהיו נוטים מעגלות ואורחות שלא לכנוס שמה, ואפילו עוף השמים מנעו את עצמם מלכנוס שמה, שכתוב, נתיב לא ידעו עיט. ומשום זה כל העולם היו צועקים על סדום ועמורה, ועל כל הערים, כי כולם היו שוים."]],[[0,"","אֵרֲדָה נָּא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה. לְמִי אָמַר? אִם תֹּאמַר לְאוֹתָם הַמַּלְאָכִים - מִי רָאָה מְדַבֵּר עִם זֶה וּמְצַוֶּה אֶת זֶה? אֶלָּא לְאַבְרָהָם אָמַר, שֶׁבִּרְשׁוּתוֹ עוֹמְדִים הַמְּקוֹמוֹת הַלָּלוּ. דָּבָר אַחֵר - לְאוֹתָם מַלְאָכִים."],[1,"","מַה שֶּׁנֶּאֱמַר לְאַבְרָהָם, מָה הַטַּעַם עָשׂוּ? הָיָה צָרִיךְ לִכְתֹּב עָשָׂה. מַה זֶּה עָשׂוּ? (אלא) זֶה אַבְרָהָם וּשְׁכִינָה שֶׁלֹּא זָזָה מִמֶּנּוּ. (דבר אחר) עָשׂוּ - מַה שֶּׁנֶּאֱמַר לַמַּלְאָכִים, מִשּׁוּם שֶׁהָיוּ מְזֻמָּנִים לְשָׁם, וְהָיוּ נִמְצָאִים לַעֲשׂוֹת דִּין, וְעַל זֶה עָשׂוּ."],[2,"","דָּבָר אַחֵר עָשׂוּ - (לעשות) כְּתַרְגּוּמוֹ עֲבָדוּ. וְכִי לֹא הָיָה יוֹדֵעַ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא אָמַר אֵרֲדָה נָּא וְאֶרְאֶה, וַהֲרֵי הַכֹּל גָּלוּי לְפָנָיו? אֶלָּא אֵרֲדָה נָּא מִדַּרְגַּת הָרַחֲמִים לְדַרְגַּת הַדִּין, וְהַיְנוּ (זו) יְרִידָה. וְאֶרְאֶה - רְאִיָּה זוֹ לְהַשְׁגִּיחַ עֲלֵיהֶם בְּאֵיזֶה דִין יָדוּן אוֹתָם."],[3,"","מָצָאנוּ רְאִיָּה לְטוֹב וּמָצָאנוּ רְאִיָּה לְרַע. רְאִיָּה לְטוֹב - שֶׁכָּתוּב (שמות ב) וַיַּרְא אֱלֹהִים אֶת בְּנֵי יִשְׂרָאֵל וַיֵּדַע. רְאִיָּה לְרַע - שֶׁכָּתוּב אֵרֲדָה נָּא וְאֶרְאֶה (נ\"א: מצאנו ירידה לטוב ומצאנו ירידה לרע, לטוב שכתוב (שם יט) וירד ה' על הר סיני, (במדבר יא) וירדתי ודברתי עמך שם, ירידה לרע ארדה נא, בשביל) לְהַשְׁגִּיחַ עֲלֵיהֶם בַּדִּין, וְעַל זֶה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם."],[4,"","וְאַבְרָהָם הָיוֹ יִהְיֶה לְגוֹי גָּדוֹל וְעָצוּם. מָה הַטַּעַם הַבְּרָכָה הַזּוֹ כָּאן? אֶלָּא כְּדֵי לְהוֹדִיעַ שֶׁאֲפִלּוּ בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב בְּדִין עַל הָעוֹלָם, לֹא מִשְׁתַּנֶּה. שֶׁהֲרֵי יוֹשֵׁב בְּדִין עַל זֶה (ד\"א ויושב) וּבְרַחֲמִים עַל זֶה, וְהַכֹּל בְּרֶגַע אֶחָד וּבְשָׁעָה אַחַת."],[5,"","אָמַר רַבִּי יְהוּדָה, וַהֲרֵי כָּתוּב (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן. לִפְעָמִים שֶׁהוּא עֵת רָצוֹן, וְלִפְעָמִים שֶׁאֵינוֹ עֵת רָצוֹן. לִפְעָמִים שֶׁשּׁוֹמֵעַ, וְלִפְעָמִים שֶׁלֹּא שׁוֹמֵעַ. לִפְעָמִים שֶׁנִּמְצָא, וְלִפְעָמִים שֶׁלֹּא נִמְצָא, שֶׁכָּתוּב (ישעיה נה) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב."],[6,"","אָמַר רַבִּי אֶלְעָזָר, כָּאן לְיָחִיד, כָּאן לְצִבּוּר. כָּאן לְמָקוֹם אֶחָד, וְכָאן לְכָל הָעוֹלָם. מִשּׁוּם כָּךְ בֵּרַךְ אֶת אַבְרָהָם, שֶׁהוּא שָׁקוּל כְּכָל הָעוֹלָם, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, (וכתוב) וְשָׁנִינוּ בְּאַבְרָהָם."],[7,"","יִהְיֶה בְּגִימַטְרִיָּא שְׁלֹשִׁים. כָּךְ שָׁנִינוּ, שְׁלֹשִׁים צַדִּיקִים מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא בְּכָל דּוֹר וָדוֹר לְעוֹלָם, כְּמוֹ שֶׁהִזְמִין אֶת אַבְרָהָם."],[8,"","פָּתַח וְאָמַר, (שמואל ב כג) מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד וְאֶל הַשְּׁלֹשָׁה לֹא בָא וְגוֹ'. מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד - אֵלּוּ הֵם שְׁלֹשִׁים צַדִּיקִים שֶׁמַּזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם וְלֹא יְבַטֵּל אוֹתָם מִמֶּנּוּ. וּבְנָיָהוּ בֶּן יְהוֹיָדָע כָּתוּב בּוֹ מִן הַשְּׁלֹשִׁים (הכי) נִכְבָּד, הוּא אֶחָד מֵהֶם. וְאֶל הַשְּׁלֹשָׁה לֹא בָא - שֶׁלֹּא שָׁקוּל לִשְׁלֹשֶׁת הָאֲחֵרִים שֶׁהָעוֹלָם עוֹמֵד עֲלֵיהֶם."],[9,"","וְאֶל הַשְּׁלֹשָׁה לֹא בָא - לִהְיוֹת בְּמִנְיָן כְּאֶחָד מֵהֶם. עִם אוֹתָם שְׁלֹשִׁים צַדִּיקִים זָכָה לְהִכָּנֵס בְּחֶשְׁבּוֹן, אֲבָל וְאֶל הַשְּׁלֹשָׁה לֹא בָא, שֶׁלֹּא זָכָה לְהִתְחַבֵּר עִמָּם וְלִהְיוֹת עִמָּהֶם בְּחֵלֶק אֶחָד. יִהְיֶ\"ה, כְּמוֹ שֶׁשָּׁנִינוּ שְׁלֹשִׁים הוּא, וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ אוֹתוֹ עִם אוֹתָם שְׁלֹשִׁים צַדִּיקִים."],[10,"","בֹּא רְאֵה, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְאַבְרָהָם, זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, שֶׁהֲרֵי עָלְתָה לְפָנַי מַה שֶּׁהֵם עוֹשִׂים לְכָל הָעוֹלָם, שֶׁכָּל הָעוֹלָם מוֹנְעִים רַגְלֵיהֶם שֶׁלֹּא לְהִכָּנֵס לִסְדם וַעֲמֹרָה, שֶׁכָּתוּב (איוב כח) פָּרַץ נַחַל מֵעִם גָּר הַנִּשְׁכָּחִים מִנִּי רָגֶל דַּלּוּ מֵאֱנוֹשׁ נָעוּ. פָּרַץ נַחַל מֵעִם גָּר - פִּרְצָה הָיָה פּוֹרֵץ הַנַּחַל לְאוֹתָם בְּנֵי הָעוֹלָם שֶׁנִּכְנְסוּ לְשָׁם. שֶׁכָּל מִי שֶׁרָאָה אֶת מִי שֶׁהָיָה נוֹתֵן לֶאֱכֹל וְלִשְׁתּוֹת לְאָדָם אַחֵר, זוֹרְקִים אוֹתוֹ לְעֹמֶק הַנָּהָר (בנקבי הנקרות), וּמִי שֶׁלּוֹקֵחַ אוֹתוֹ גַּם כֵּן."],[11,"","וְעַל זֶה כָּל בְּנֵי הָעוֹלָם הָיוּ נִשְׁכָּחִים מִנִּי רָגֶל, שֶׁמּוֹנְעִים רַגְלֵיהֶם שֶׁלֹּא לְהִכָּנֵס לְשָׁם. וּמִי שֶׁנִּכְנַס - דַּלּוּ מֵאֱנוֹשׁ נָעוּ, שֶׁהָיוּ מְדַלְדְּלִים אֶת הַגּוּף בָּרָעָב וְלֹא הָיוּ נוֹתְנִים לוֹ לֶאֱכֹל וְלִשְׁתּוֹת, וּמִשְׁתַּנֶּה דְיוֹקְנוֹ מִשְּׁאָר בְּנֵי הָעוֹלָם, שֶׁכָּתוּב דַּלּוּ מֵאֱנוֹשׁ, נָעוּ. כָּתוּב כָּאן נָעוּ, וְכָתוּב שָׁם (משלי ה) נָעוּ מַעְגְּלֹתֶיהָ. כָּךְ גַּם הָיוּ סוֹטִים מַעְגָּלִים וּדְרָכִים כְּדֵי לֹא לְהִכָּנֵס לְשָׁם, וַאֲפִלּוּ עוֹפוֹת הַשָּׁמַיִם הָיוּ מְנוּעִים מִלְּהִכָּנֵס לְשָׁם, שֶׁכָּתוּב (איוב כח) נָתִיב לֹא יְדָעוֹ עַיִט וְגוֹ'. וְלָכֵן כָּל הָעוֹלָם הָיוּ צוֹוְחִים עַל סְדם וְעַל עֲמֹרָה וְעַל כָּל הַקְּרָיוֹת, שֶׁכֻּלָּם כְּמוֹ גָוֶן אֶחָד הָיוּ."]]],[["זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה. אָמַר לֵיהּ אַבְרָהָם. אַמַּאי. אָמַר לֵיהּ וְחַטָּאתָם כִּי כָבְדָה מְאֹד. בְּגִינֵי כָךְ אֵרְדָה נָא וְאֶרְאֶה, הַכְּצַעֲקָתָהּ. הַכְּצַעֲקָתָם מִבָּעֵי לֵיהּ, דְּהָא כְּתִיב זַעֲקַת סְדוֹם וַעֲמוֹרָה וּתְרֵי קַרְתֵּי הֲווּ, אַמַּאי הַכְּצַעֲקָתָהּ. אֶלָּא הָא אוּקְמוּהָ.","תָּא חֲזֵי, בְּסִטְרָא דְּתוּתֵי קָלָא דְּבַרְדָּא סָלְקִין קוּטְרֵי כֻּלְהוּ בְּכַתְּפָא מִתְכַּנְשֵׁי בְּחַד טִיף וְעָאלִין בְּגוֹ נוּקְבֵי דִּתְהוֹמָא רַבָּא, אִתְעֲבִידוּ חָמֵשׁ בְּחַד. חַד אִיהוּ כַּד (צלילן קלין) אִיכָּא צְלִילִין קָלִין דְּכֻלְהוּ אִתְעֲבִידוּ חַד. קָלָא דְּסָלִיק מִתַּתָּא עָאל בֵּינַיְיהוּ וְאִתְמַשְׁכוּ כְּחַד.","וְהַהוּא קָלָא סָלְקָא וְנַחֲתָא תָּבְעָא דִינָא לְאִתְמַשְׁכָא לְתַתָּא. כַּד הַאי קָלָא סָלְקָא לְמִתְבַּע דִּינָא כְּדֵין אִתְגְּלִי לְאַשְׁגָחָא קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא.","אָמַר רַבִּי שִׁמְעוֹן, הַכְּצַעֲקָתָהּ. מַאן הַכְּצַעֲקָתָהּ, דָּא גְּזֵרַת דִּינָא דְּתָבְעָא דִינָא כָּל יוֹמָא. דְּהָכִי תָּנִינָן כַּמָּה שְׁנִין קָיְימָא גְּזֵרַת דִּינָא וְתָבְעָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא עַל דְּזַבִּינוּ אֲחוּי דְיוֹסֵף לְיוֹסֵף. בְּגִין דִּגְזֵרַת דִּינָא צָוְוחַת עַל דִּינָא, וְעַל דָּא הַכְּצַעֲקָתָהּ, הַבָּאָה אֵלַי.","מַאי (קז א) הַבָּאָה אֵלַי. דָּא הוּא רָזָא כְּמָא דְאַתְּ אָמֵר, (אסתר ב׳:י״ד) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. וְדָא הוּא הַבָּאָה אֵלַי תָּדִיר. כְּגַוְונָא דָא קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְהָא אִתְּמָר. עָשׂוּ כָּלָה הָא אִתְּמָר:","וַיִּגַשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע. אָמַר רַבִּי יְהוּדָה מַאן חָמָא אַבָּא דְּרַחְמָנוּתָא כְּאַבְרָהָם. תָּא חֲזֵי, בְּנֹחַ כְּתִיב וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגו' עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר. וְאִשְׁתִּיק וְלָא אָמַר לֵיהּ מִידִי. וְלָא בָעָא רַחֲמֵי. אֲבָל אַבְרָהָם בְּשַׁעֲתָא דְּאָמַר לֵיה קוּדְשָׁא בְּרִיךְ הוּא, זַעֲקַת סְדוֹם וַעֲמוֹרָה כִּי רָבָּה וְגו'. אֵרַדָה נָא וְאֶרְאֶה וְגו'. מִיָּד כְּתִיב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע.","אָמַר רַבִּי אֶלְעָזָר, אוּף אַבְרָהָם לָא עָבַד שְׁלִימוּ כְּדְקָא יְאוּת. נֹחַ לָא עֲבִיד מִידִי, לָא הַאי וְלָא הַאי. אַבְרָהָם תָּבַע דִּינָא כְּדְקָא יְאוּת דְּלָא יְמוּת זַכָּאָה עִם חַיָּיבָא. וְשָׁארֵי מֵחֲמִשִּׁים עַד עֲשָׂרָה, עָבַד וְלָא אַשְׁלִים, דְּלָא בָּעָא רַחֲמֵי בֵּין כָּךְ וּבֵין כָּךְ, דְּאָמַר אַבְרָהָם לָא בָּעִינָא לְמִתְבַּע אֲגַר עוֹבָדוֹי.","אֲבָל מַאן עָבַד שְׁלִימוּ כְּדְקָא יְאוּת, דָּא משֶׁה. דְּכֵיוָן דְּאָמַר קוּדְשָׁא בְּרִיךְ הוּא (שמות ל״ב:ח׳) סָרוּ מַהֵר מִן הַדֶּרֶךְ וְגו'. עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ. מִיָּד מַה כְּתִיב וַיְחַל משֶׁה אֶת פְּנֵי יְיָ אֱלהָיו וְגו'. עַד דְּאָמַר וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךָ אֲשֶׁר כָּתָבְתָּ. וְאַף עַל גַּב דְּכֻלְהוּ חָטוּ, לָא זָז מִתַּמָּן עַד דְּאָמַר לֵיהּ סָלַחְתִּי כִּדְבָרֶךָ.","אֲבָל אַבְרָהָם לָא אַשְׁגַּח אֶלָּא אִי אִשְׁתְּכַח בְּהוּ זַּכַּאי וְאִם לָאו לָא. וְעַל דָּא לָא הֲוָה בְּעָלְמָא בַּר נָשׁ דְּיָגִין עַל דָּרֵיהּ כְּמשֶׁה דְּאִיהוּ רַעֲיָא מְהֵימְנָא.","וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר, אַתְקִין גַּרְמֵיהּ לְמִתְבַּע דָּא. אוּלַי יִמָּצְאוּ שָׁם חֲמִשִּׁים. שָׁרָא מֵחֲמִשִּׁים דְּאִיהוּ שֵׁירוּתָא לְמִנְדַע, עַד עֲשָׂרָה דְּאִיהוּ עֲשִׂירָאָה סוֹפָא דְּכָל דַּרְגִּין.","אָמַר רַבִּי יִצְחָק עַד עֲשָׂרָה, אִלֵּין עֲשָׂרָה יוֹמִין דְּבֵין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים. בְּגִין כָּךְ שָׁרָא מֵחֲמִשִּׁים עַד עֲשָׂרָה. וְכֵיוָן דְּמָטָא לַעֲשָׂרָה, אָמַר מִכָּאן וּלְתַתָּא לָאו הוּא אֲתַר דְּקָיְימָא בִּתְשׁוּבָה, בְּגִינֵי כָךְ לָא נָחַת לְתַתָּא מֵעֲשָׂרָה:","וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב וְגו'. אָמַר רַבִּי יוֹסֵי תָּא חֲזֵי מַה כְּתִיב לְעֵילָא וַיֵּלֶךְ יְיָ כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם. דְּהָא כֵּיוָן דְּאִתְפְּרַשׁ שְׁכִינְתָּא מֵאַבְרָהָם, וְאַבְרָהָם תָּב לְאַתְרֵיהּ, כְּדֵין וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדוֹמָה בָּעֶרֶב, דְּהָא חַד אִסְתַּלַּק בִּשְׁכִינְתָּא, וְאִשְׁתָּאֲרוּ אִנּוּן תְּרֵין."],[[0,"זעקת סדום ועמורה כי רבה:","אמר לו אברהם להקב\"ה, למה. אמר לו וחטאתם כי כבדה מאד, משום זה ארדה נא ואראה הכצעקתה, וגו'. ושואל, הכצעקתם היה צריך לומר. שהרי כתוב זעקת סדום ועמורה, ושני ערים היו, ולמה אומר הכצעקתה, לשון יחיד. ואומר, אלא כבר בארוה."],[1,"ת\"ח בסטרא וכו':","בוא וראה, בצד, שמתחת קול הברד, עולים כל הסבכים בכתף. מתאספים בטפה אחת, ובאים בהנקבים של תהום הגדול, ונעשו חמשה באחד. אחד הוא כשיש קולות צלולים, שכולם נעשו אחד, כי הקול של מטה נכנס ביניהם ונמשך עמהם כאחד."],[2,"וההוא קלא וכו':","וקול ההוא עולה ויורד ותובע דין להמשך למטה. כאשר קול הזה עולה לתבוע דין, נתגלה אז הקב\"ה, להשגיח בדין."],[2,"","פירוש. הדינים שבעולם מתחלקים לב' בחינות א) מבחינת המלכות עצמה, והקול העולה מדינים הללו, נקרא \u0003קול של מטה,\u0004 דהיינו של המלכות. ב) מבחינת המלכות הממותקת בבינה, והקול העולה מדינים הללו, נקרא, \u0003קול של מעלה,\u0004 דהיינו של הבינה. וכן נקרא קול הברד, ורומז על הכתוב קולות וברד שנאמר במכות מצרים. וענין ב' קולות הללו, נתבארו לעיל (דף קס\"ז ד\"ה תו מן המדבר ע\"ש.) \u0003קוטרי\u0004 פירושו סבכים כי דבר מסובך, שקשה להתירו ולפתחו, נקרא קובהקדמת הזהר דטרא. כמ\"ש קטיר קא חזינא הכא. (יבמות סא.) וכן תרי קוטרי עבדי ביה (שם ק\"ז:). \u0003כתף,\u0004 פירושו מוחין דאחורים של הגוף, כי הכתף הוא אחורי הפנים. \u0003חד טיף\u0004 פירושו, טפה של נקודת השורק. כי ג' נקודות חולם שורק חירק, שכל המוחין נמשכים מהן, מכונים ג' טיפות (לעיל בראשית א' דף רס\"ד אות שכ\"א) \u0003תהומא רבא,\u0004 פירושו כחות הדין הנמשכים מהבינה, (כנ\"ל בראשית א' דף רס\"ג ד\"ה לבתר תהומא רבא')."],[2,"","וז\"ש \u0003בסטרא דתותי קלא דברדא\u0004 בצד שמתחת הקול של ברד, שהוא הקול של מעלה מבינה, \u0003סלקין קוטרי כלהו בכתפא.\u0004 עולים כל הסבכים, דהיינו שהם נפתחים ומושגים. בכתף, שהוא בחינת מוחין דג\"ר דאחורי הגוף. כי קול הברד כולו טוב בלי רע. וע\"כ כל סבכי הדינים מקבלים בו את תקונם. ומפרש יותר. \u0003מתכנשי בחד טיף,\u0004 כל האורות מתאספים בטפה אחת מג' הטפות חולם שורק חירק, והיינו בטפה דשורק, שכל הדינים נמשכים ממנה כל עוד שלא נתחברה בטפה דחולם, ולפיכך, \u0003ועאלין בגו נוקבי דתהומא רבא,\u0004 שמכח הדינים דשורק הם נכנסים בהנקבים של תהום הגדול, כלומר שבאים בדינים דבינה, שה\"ס קול של מעלה כנ\"ל. ואז \u0003אתעבידו חמש בחד,\u0004 שכל החמשה ספירות כח\"ב תו\"מ, נכללו בקול אחד הנזכר, דהיינו אפילו המלכות שהיא קול של מטה נכללה ג\"כ בקול הזה של מעלה, הנק' קול הברד. וקול המלכות עצמה לא ישמע, כי לולי נגלה קולה, היו המוחין מסתלקין, (כמ\"ש בבראשית א' דף קס\"ז ד\"ה תו מן המדבר, ודף ז' ד\"ה וכבר ע\"ש) וע\"כ אומר הכתוב \u0003הכצעקתה,\u0004 לשון יחיד, כי אין כאן אלא קול אחד."],[2,"","וז\"ש \u0003חד איהו, כד איכא צלילין קלין,\u0004 מתי כל החמשה אחד, הוא כאשר יש קולות צלולים, כלומר, שקול העב של מטה אינו נשמע בהם, \u0003דכלהו אתעבידו חד.\u0004 שכולם נעשו קול אחד. וקול של מטה אינו מעורב בהם. כי \u0003קלא דסליק מתתא\u0004 דהיינו קול של מלכות עצמה, \u0003עאל בינייהו ואתמשכו כחד,\u0004 בא ביניהם, בין הקולות של מעלה, ונמשך עמהם יחד, כלומר שנבלע בהם ואינו נשמע. \u0003וההוא קלא,\u0004 וקול ההוא של מעלה, הנשמע. \u0003סלקא,\u0004 בסוד נקודת החולם, \u0003ונחתא,\u0004 בסוד נקודת השורק, \u0003תבעא דינא,\u0004 בסוד הדינים הנמשכים מהשורק מטרם שנכללה בחולם. \u0003לאתמשכא לתתא,\u0004 כדי שתוכל להמשך ולהאיר למטה. \u0003כד האי קלא סלקא למתבע דינא, כדין אתגלי קב\"ה לאשגחא בדינא,\u0004 באותה שעה שהקול עולה לתבוע דין, דהיינו בשעת שליטת נקודת השורק, אז נתגלה הקב\"ה להשגיח בדין. פירוש כי התגלות הקב\"ה ה\"ס אור החכמה, ואחר התכללות הקוין זה בזה היא נמשכת משליטת נקודת השורק, שאין אור החכמה בשום קו אלא בר, (כנ\"ל ב\"א דף ט\"ו ד\"ה ההיא) אמנם בעת ההיא הוא משגיח בדין, אבל לאחר התכללות הקוין זה בזה הוא מאיר ברחמים."],[2,"","ומשמיענו בזה, ביאור הכתוב. אשר, \u0003ארדה נא,\u0004 היינו מנקודת החולם, שהיא חסד אל נקודת השורק שהיא דין, שזה נבחן לירידה כנ\"ל. \u0003ואראה,\u0004 כי שם בנקודת השורק יש ראיה, שה\"ס אור החכמה כנ\"ל, \u0003הכצעקתה, הבאה אלי,\u0004 הוא צעקת הקול האחד לתבוע דין, שבזמן שליטת השורק כי גילוי החכמה היא במיוחד בעת הצעקה הזו, כנ\"ל, \u0003כד האי קלא סלקא למתבע דינא כדין אתגלי קב\"ה לאשגחא בדינא.\u0004 כי אין גילוי חכמה בנקודה אחרת זולת נקודת השורק, כנ\"ל."],[3,"אמר ר' שמעון וכו':","אר\"ש, כתוב הכצעקתה, ממי הוא \u0003הכצעקתה\u0004 הזה, ומשיב, זהו גזרת דין שתובעת דין בכל יום. שעליה אומר הכתוב הכצעקתה, כי כך למדנו, הרבה שנים עמדה גזרת הדין, ותבעה מאת הקב\"ה, על מה שאחיו של יוסף מכרוהו ליוסף, כי גזרת הדין צועקת שיתגלה הדין. ועל כן אומר הכתוב הכצעקתה הבאה אלי, דהיינו צעקתה של גזרת הדין."],[3,"","פירוש. גזרת הדין, ה\"ס הארת נקודת השורק שבהנוקבא, מטרם התכללותה בחסדים, שאינה מתגלה אלא עם גילוי דינים כנ\"ל, וסוד יוסף ה\"ס הארת ג\"ר (כמ\"ש לעיל בהקדמת הזהר דף י\"א ד\"ה ואיטמרו ע\"ש) וע\"י שאחיו של יוסף מכרוהו למצרים נסתלקו הג\"ר מהם. וזהו שמרמז ר\"ש, \u0003כמה שנין קיימא גזרת דינא ותבעא\u0004 וכו'. דהיינו שתבעה על שנתבטלה הארתה מחמת מכירת יוסף, \u0003בגין דגזרת דינא צווחת על דינא,\u0004 כי רצתה לצעוק ולגלות הדין, דהיינו שרצתה להחזיר הג\"ר המתבטלים על ידי מכירת יוסף ומתוך שאין הארתה אלא עם גילוי הדין, כנ\"ל על כן מרומזת הארתה בסוד \u0003צווחת על דינא, ועל דא הכצעקתה הבאה אלי,\u0004 דהיינו גילוי החכמה על ידי צעקתה של גזרת הדין."],[4,"מה הבאה אלי וכו':","ושואל מה משמיענו הכתוב בהמלות \u0003הבאה אלי,\u0004 ואומר, זה הוא סוד, כמו שאתה אומר בערב היא באה ובבקר היא שבה. כלומר, אחר שביאר המלה \u0003הבצעקתה.\u0004 שה\"ס גילוי הארת החכמה על ידי צעקה של גזרת דינא, כבדיבור הסמוך, מבאר המלות \u0003הבאה אלי,\u0004 שהוא לשון הוה, שפירושו, שבאה בעת הזווג. כמ\"ש בערב היא באה, הרומז על זמן הזווג ההוא המקבל מהארת השורק, שנקרא ערב, להיותו בשליטת הדינים של השורק, שז\"ס ותקם בעוד לילה, (כנ\"ל בראשית א' דף קי\"ז אות קכ\"ה) \u0003ודא הוא הבאה אלי תדיר,\u0004 וע\"כ כתוב \u0003הבאה אלי,\u0004 לשון הוה, כי הוא נוהג תדיר, כי בתחילת כל זווג נוהג שליטת השורק בסוד הארת קו השמאל, (כנ\"ל בראשית ב' דף קל\"ו ד\"ה פנימית ע\"ש) \u0003כגוונא דא קץ כל בשר בא לפני, והא אתמר,\u0004 כעין זה אומר הכתוב, קץ כל בשר בא לפני, שאומר ג\"כ לשון הוה, בא לפני, (ועי' להלן דף ע\"ב אות ר\"נ)."],[5,"ויגש אברהם ויאמר האף וגו:","אמר ר\"י מי ראה אב רחמן כמו אברהם. בוא וראה בנח כתוב ויאמר אלקים לנח קץ כל בשר בא לפני וגו' ושתק ולא אמר כלום ולא בקש רחמים. אבל אברהם בשעה שאמר לו הקב\"ה זעקת סדום ועמורה וגו', מיד כתוב, ויגש אברהם ויאמר האף תספה צדיק עם רשע."],[6,"אמר ר' אלעזר וכו':","אר\"א, אף אברהם לא עשה בשלימות כראוי. נח לא עשה כלום לא זה ולא זה. כלומר לא בקש על צדיקים כאברהם, ולא בקש אף על הרשעים כמשה. כמו שמבאר לפנינו. אברהם תבע משפט כראוי, שלא ימות צדיק עם רשע, והתחיל מן חמשים צדיקים עד עשרה. עשה ולא השלים, כי לא בקש רחמים בין כך ובין כך, בין אם יש צדיקים ובין אם אין צדיקים. כי אמר אברהם, איני רוצה לתבוע שכר על מעשי. כלומר, שלא האמין בעצמו שיש לו שכר, עד לבקש בזכותו לפטור את הרשעים מן הדין."],[7,"אבל מאן עביד שלימו וכו':","אבל מי עשה בשלמות כראוי, זה משה. כיון שאמר לו הקב\"ה סרו מהר מן הדרך וגו', מיד מה כתוב, ויחל משה את פני ה' אלקיו וגו' עד שאמר ועתה אם תשא חטאתם ואם אין מחני נא מספרך אשר כתבת. ואף על פי שכולם חטאו לא מש משם עד שאמר לו סלחתי כדברך. ויש כאן השמטת המעתיק, והכי גרסינן \u0003לא זז מתמן עד דמחל קב\"ה לישראל הה\"ד וינחם ה' על הרעה אשר דבר לעשות לעמו וכתיב ויאמר ה' סלחתי כדברך.\u0004 כי כן גרסינן בזהר פרשת ויקרא דף י\"ד ע\"ב (דפו\"י) ע\"ש. והוא מוכרח, כי לא יתכן שלא יביא הכתוב של מחילה הנאמר בעגל, ויביא רק \u0003הכתוב,\u0004 סלחתי כדברך, הנאמר במרגלים."],[8,"אבל אברהם וכו':","אבל אברהם לא התחשב אלא אם נמצא בהם צדיקים. ואם אין בהם צדיקים, לא התפלל. ועל כן לא היה עוד איש בעולם שיגין על דורו כמו משה, שהוא רועה הנאמן."],[9,"ויגש אברהם ויאמר:","פירושו, שהתקין את עצמו לבקש את זה, \u0003אולי ימצאון שם חמשים,\u0004 התחיל מחמשים, שהוא התחלה לדעת, עד עשרה שהוא סוף כל המדרגות. פירוש. כי ה' קומות יש בכל מדרגה זה למטה מזה, היוצאות על ה' בחינות המסך כנ\"ל בפתיחה לחכמת הקבלה אות כ\"א עש\"ה ונמצא בקומת כתר חמשים ספירות שהם ה' ספירות כח\"ב תו\"מ שבכל אחת עשרה ספירות. ובקומת חכמה רץ ארבעים ספירות, כי חסרה ע\"ס דכתר. ובקומת בינה שלשים ספירות, כי חסרים ג\"כ ע\"ס דחכמה. ובקומת ת\"ת עשרים ספירות, כי חסרים גם ע\"ס דבינה. ובקומת מלכות רק עשר ספירות. וז\"ש. \u0003שרא מחמשים דאיהו שירותא למנדע,\u0004 דהיינו קומת כתר שיש בה חמשים ספירות, \u0003עד עשרה, דאיהו עשיראה,\u0004 עד קומת מלכות שאין בה רק עשר ספירות והמלכות היא ספירה עשירית לע\"ס. \u0003סופא דכל דרגין,\u0004 והיא סוף כל המדרגות."],[10,"אמר ר' יצחק וכו':","אר\"י עד עשרה שהתפלל עליהם אברהם, אלו הם עשרת הימים שבין ראש השנה ויום הכפורים, שבהם מתתקנות עשר ספירות המלכות לעלות אל הבינה. משום זה התחיל להתפלל מחמשים עד עשרה. שהם ע\"ס המלכות בתקון עשרת ימי תשובה, וכיון שהגיע לעשרה, אמר מכאן ולמטה, ששם המלכות שאינה נמתקת בבינה, אינו מקום העומד בתשובה, אינו נמתק בבינה, הנקראת תשובה, משום זה לא ירד לבקש על למטה מעשרה."],[11,"ויבאו שני המלאכים סדומה וגו':","אמר ר' יוסי בוא וראה מה כתוב למעלה, וילך ה' כאשר כלה לדבר אל אברהם, כי מאחר שהשכינה נפרשה מאברהם, ואברהם שב למקומו, אז ויבאו שני המלאכים סדומה בערב, כי מלאך אחד נסתלק עם השכינה ונשארו שנים אלו. כנ\"ל דף כ\"ח אות ע\"ד)."]],[[0,"","זַעָקַת סְדם וַעֲמֹרָה כִּי רָבָּה. אָמַר לוֹ אַבְרָהָם, לָמָּה? אָמַר לוֹ, וְחַטָּאתָם כִּי כָבְדָה מְאֹד. מִשּׁוּם כָּךְ אֵרֲדָה נָּא וְאֶרְאֶה הַכְּצַעֲקָתָהּ. הָיָה צָרִיךְ לִכְתֹּב הַכְּצַעֲקָתָם, שֶׁהֲרֵי כָתוּב זַעֲקַת סְדם וַעֲמֹרָה, וּשְׁתֵּי עָרִים הָיוּ, אָז לָמָּה הַכְּצַעֲקָתָהּ? אֶלָּא הֲרֵי פֵּרְשׁוּהָ."],[1,"","בֹּא רְאֵה, בַּצַּד שֶׁמִּתַּחַת אֶבֶן הַבָּרָד עוֹלִים עֲשָׁנִים בְּכָתֵף, מִתְכַּנְּסִים בְּטִפָּה אַחַת וְנִכְנָסִים לְתוֹךְ נִקְבֵי תְהוֹם רַבָּה וְנַעֲשִׂים חֲמִשָּׁה בְּאֶחָד. אֶחָד הוּא כַּאֲשֶׁר (הקולות צלולים) יֵשׁ קוֹלוֹת צְלוּלִים שֶׁכֻּלָּם נַעֲשִׂים אֶחָד. הַקּוֹל שֶׁעוֹלֶה מִלְּמַטָּה נִכְנָס בֵּינֵיהֶם וְנִמְשָׁכִים כְּאֶחָד."],[2,"","וְאוֹתוֹ הַקּוֹל עוֹלֶה וְיוֹרֵד וְתוֹבֵעַ דִּין לְהִמָּשֵׁךְ לְמַטָּה. כְּשֶׁקּוֹל זֶה עוֹלֶה לִתְבֹּעַ דִּין, אָז מִתְגַּלֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׁגִּיחַ בְּדִין."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, הַכְּצַעֲקָתָהּ, מִי הַכְּצַעֲקָתָהּ? זוֹ גְזֵרַת הַדִּין שֶׁתּוֹבַעַת דִּין כָּל יוֹם. שֶׁכָּךְ שָׁנִינוּ, כַּמָּה שָׁנִים עוֹמֶדֶת גְּזֵרַת דִּין וְתוֹבַעַת מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל שֶׁאֲחֵי יוֹסֵף מָכְרוּ אֶת יוֹסֵף, מִשּׁוּם שֶׁגְּזֵרַת הַדִּין צוֹוַחַת עַל הַדִּין, וְעַל זֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי."],[4,"","מַה זֶּה הַבָּאָה אֵלַי? זֶהוּ סוֹד כְּמוֹ שֶׁנֶּאֱמַר (אסתר ב) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. וְזֶהוּ הַבָּאָה אֵלַי, תָּמִיד. כְּמוֹ זֶה קֵץ כָּל בָּשָׂר בָּא לְפָנַי, וַהֲרֵי נִתְבָּאֵר. עָשׂוּ כָּלָה, הֲרֵי נִתְבָּאֵר."],[5,"","וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע. אָמַר רַבִּי יְהוּדָה, מִי רָאָה אַב הָרַחֲמִים כְּמוֹ אַבְרָהָם. בּא רְאֵה, בְּנֹחַ כָּתוּב וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי וְגוֹ', עֲשֵׂה לְךְ תֵּבַת עֲצֵי גֹפֶר. וְשָׁתַק וְלֹא אָמַר לוֹ דָּבָר וְלֹא בִקֵּשׁ רַחֲמִים. אֲבָל אַבְרָהָם, בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא זַעֲקַת סְדם וַעֲמֹרָה כִּי רָבָּה, אֵרֲדָה נָּא וְאֶרְאֶה - מִיָּד כָּתוּב וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע."],[6,"","אָמַר רַבִּי אֶלְעָזָר, אַף אַבְרָהָם לֹא עָשָׂה בִּשְׁלֵמוּת כָּרָאוּי. נֹחַ לֹא עָשָׂה דָבָר, לֹא זֶה וְלֹא זֶה. אַבְרָהָם בִּקֵּשׁ דִּין כָּרָאוּי שֶׁלֹּא יָמוּת צַדִּיק עִם רָשָׁע, וְהִתְחִיל מֵחֲמִשִּׁים עַד עֲשָׂרָה. עָשָׂה וְלֹא הִשְׁלִים, שֶׁלֹּא בִקֵּשׁ רַחֲמִים בֵּין כָּךְ וּבֵין כָּךְ, שֶׁאָמַר אַבְרָהָם שֶׁלֹּא רוֹצֶה לִתְבֹּעַ שְׂכַר מַעֲשָׂיו."],[7,"","אֲבָל מִי עָשָׂה בִּשְׁלֵמוּת כָּרָאוּי? זֶה מֹשֶׁה. שֶׁכֵּיוָן שֶׁאָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות לב) סָרוּ מַהֵר מִן הַדֶּרֶךְ וְגוֹ', עָשׂוּ לָהֶם עֵגֶל מַסֵּכָה וַיִּשְׁתַּחֲווּ לוֹ - מִיָּד כָּתוּב וַיְחַל מֹשֶׁה אֶת פְּנֵי ה' אֱלֹהָיו וְגוֹ', עַד שֶׁאָמַר וְעַתָּה אִם תִּשָּׂא חַטָּאתָם וְאִם אַיִן מְחֵנִי נָא מִסִּפְרְךְ אֲשֶׁר כָּתָבְתָּ. וְאַף עַל גַּב שֶׁכֻּלָּם חָטְאוּ, לֹא זָז מִשָּׁם עַד שֶׁאָמַר לוֹ סָלַחְתִּי כִּדְבָרֶךְ."],[8,"","אֲבָל אַבְרָהָם לֹא הִשְׁגִּיחַ אֶלָּא אִם נִמְצָא בָהֶם צַדִּיק, וְאִם לֹא - לֹא. עַל זֶה לֹא הָיָה בָּעוֹלָם בֶּן אָדָם שֶׁיָּגֵן עַל דּוֹרוֹ כְּמוֹ מֹשֶׁה שֶׁהוּא רוֹעֶה נֶאֱמָן."],[9,"","וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר, הִתְקִין עַצְמוֹ לְבַקֵּשׁ אֶת זֶה. אוּלַי יִמָּצְאוּ שָׁם חֲמִשִּׁים. הִתְחִיל מֵחֲמִשִּׁים שֶׁהוּא רֵאשִׁית לְדַעַת, עַד עֲשָׂרָה, שֶׁהוּא עֲשִׂירִי, סוֹף כָּל הַדְּרָגוֹת."],[10,"","אָמַר רַבִּי יִצְחָק, עַד עֲשָׂרָה, אֵלּוּ עֲשָׂרָה יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים, מִשּׁוּם כָּךְ הִתְחִיל מֵחֲמִשִּׁים עַד עֲשָׂרָה. וְכֵיוָן שֶׁהִגִּיעַ לַעֲשָׂרָה, אָמַר, מִכָּאן וּלְמַטָּה אֵינוֹ מָקוֹם שֶׁעוֹמֵד בִּתְשׁוּבָה. מִשּׁוּם כָּךְ לֹא יָרַד מִתַּחַת לַעֲשָׂרָה."],[11,"","וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב וְגוֹ'. אָמַר רַבִּי יוֹסֵי, בֹּא רְאֵה מַה כָּתוּב לְמַעְלָה, וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם. שֶׁהֲרֵי כֵּיוָן שֶׁנִּפְרְדָה שְׁכִינָה מֵאַבְרָהָם וְאַבְרָהָם שָׁב לִמְקוֹמוֹ, אָז וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדמָה בָּעֶרֶב, שֶׁהֲרֵי אֶחָד הִסְתַּלֵּק עִם הַשְּׁכִינָה, וְנִשְׁאֲרוּ אוֹתָם שְׁנַיִם."]]],[["כֵּיוָן דְּחָמָא לוֹט לוֹן, רָהַט בַּתְרַיְיהוּ. מַאי טַעְמָא, וְכִי כָּל אִנּוּן דְּהֲווּ אַתְיָין אִיהוּ אָעִיל לוֹן לְבֵיתֵיהּ וְיָהִיב לוֹן לְמֵיכַל וּלְמִשְׁתֵּי וּבְנִי מָתָא הֵיךְ לָא קָטְלִין לֵיהּ, דְּהָא לִבְרַתֵּיהּ עֲבְדוּ דִינָא.","וּמַאי הוּא. דִּבְרַתֵּיהּ דְּלוֹט יַהֲבַת פִּתָּא דְּנַהֲמָא לְחַד עַנְיָא, יָדְעוּ בָּהּ, שָׁפוּהָ דוּבְשָׁא וְאוֹתְבוּהָ בְּרִישׁ אִיגְרָא עַד דְּאֲכְלוּהָ צִרְעֵי.","אֶלָּא בְּגִין דְּהֲוָה בְּלֵילְיָא חָשִׁיב דְּלָא יִסְתַּכְּלוּן לֵיהּ בְּנֵי מָתָא, וְעִם כָּל דָּא כֵּיוָן דַּאֲעָלוּ לְבֵיתָא אִתְכְּנָשׁוּ כֻּלְהוּ וְאַסְחָרוּ לְבֵיתָא.","אָמַר רַבִּי יִצְחָק אַמַּאי רָהַט לוֹט אֲבַּתְרַיְיהוּ, (אלא בגין) דִּכְתִיב וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם. רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא. חַד אָמַר דִּיוּקְנָא דְּאַבְרָהָם חָמָא עִמְהוֹן. וְחַד אָמַר שְׁכִינְתָּא אַתְיָא עֲלַיְיהוּ. כְּתִיב הָכָא וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וּכְתִיב הָתָם וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל. מַה לְהַלָּן חָמָא שְׁכִינְתָּא, אוּף הָכָא חָמָא שְׁכִינְתָּא.","וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַי בָּאָלֶ\"ף דָלֶ\"ת נוּ\"ן יוּ\"ד. סוּרוּ נָא, גְּשׁוּ נָא מִבָּעֵי לֵיהּ, מַאי סוּרוּ נָא. אֶלָּא לְאַהֲדָרָא לוֹן סַחֲרָנֵיהּ דְּבֵיתָא בְּגִין דְּלָא יֶחמוּן לוֹן בְּנֵי מָתָא, וְלָא יֵעֲלוּן בְּאוֹרַח מֵישָׁר לְבֵיתָא, וּבְגִין כָּךְ סוּרוּ נָא.","רַבִּי חִזְקִיָּה פָּתַח (איוב כ״ח:כ״ד) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִסְתַּכָּלָא בְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וּלְאִשְׁתַּדָּלָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילֵי, דְּכָל מָאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּבַּח בֵּיהּ לְעֵילָא, וְאִשְׁתַּבַּח בֵּיהּ לְתַתָּא, בְּגִין דְּאוֹרַיְיתָא אִילָנָא דְחַיֵּי אִיהִי לְכָל אִנּוּן דְּעָסְקִין בָּהּ לְמֵיהַב לוֹן חַיִּין בְּעָלְמָא דֵין וּלְמֵיהַב לוֹן חַיִּין בְּעָלְמָא דְּאָתֵי."],[[0,"כיון דחמא לוט וכו':","כיון שראה אותם לוט רץ אחריהם. מה הטעם, וכי כל אלו שהיו באים לעירו, היה מכניסם לביתו, ונותן להם לאכול ולשתות. ובני עירו לא הרגו אותו, והלוא לבתו עשו דין."],[1,"ומאי הוא וכו':","מה היה, בתו של לוט, שנתנה פת לחם לעני אחד, ונודע להם זה, משחוה דבש, והושיבוה בראש הגג, עד שהדבורים אכלוה."],[2,"אלא בגין וכו':","ומשיב, אלא משום שהיה בלילה, חשב שבני עירו לא יראו אותו. ועם כל זה, כיון שנכנסו לבית נאספו כולם וסבבו את הבית."],[3,"אמר ר' יצחק וכו':","למה רץ לוט אחרי המלאכים, שכתוב, וירא וירץ לקראתם. רבי חזקיה ורבי ייסא, אחד אמר שראה עמהם צורתו של אברהם. לכן רץ לקראתם ואחד אמר, שראה השכינה שורה עליהם. לכן רץ לקראתם. ויליף גזירה שוה, כתוב כאן, וירא לוט וירץ לקראתם, וכתוב שם וירץ לקראתם מפתח האהל. מה שם ראה את השכינה. אף כאן ראה את השכינה."],[4,"ועל דא","וירא לוט וירץ לקראתם ויאמר הנה נא אדני באלף דלת נון יוד, דהיינו שם השכינה. ובספרים שלנו לא כתוב וירץ לקראתם, אלא ויקם לקראתם, ונראה דעת הזהר, אשר ויקם לקראתם, המובן הוא שקם ורץ לקראתם, דאם לא כן היה צריך לומר ויקם מפניהם. \u0003סורו נא\u0004 וכו': שואל כתוב סורו נא, גשו נא היה צריך לכתוב, מהו סורו נא. ומשיב, אלא רצה להסב אותם מסביב הבית ולא יכנסו לבית בדרך הרגיל, כדי שבני העיר לא יראו אותם, ומשום זה אמר סורו נא."],[5,"ר' חזקיה פתח וכו':","ר\"ח פתח, כתוב, כי הוא לקצות הארץ יביט. תחת כל השמים יראה. כמה יש להם לבני אדם להסתכל במעשיו של הקב\"ה, ולעסוק בתורה יום ולילה. כי כל מי שעוסק בתורה, הקב\"ה משתבח בו למעלה, ומשתבח בו למטה, כי התורה היא עץ חיים לכל אלו העוסקים בה. לתת להם חיים בעולם הזה ולתת להם חיים בעולם הבא."]],[[0,"","כֵּיוָן שֶׁרָאָה אוֹתָם לוֹט, רָץ אַחֲרֵיהֶם. מָה הַטַּעַם? וְכִי כָּל אוֹתָם שֶׁהָיוּ בָּאִים הוּא הִכְנִיס לְבֵיתוֹ וְנָתַן לָהֶם לֶאֱכֹל וְלִשְׁתּוֹת? וּבְנֵי הָעִיר אֵיךְ לֹא הָרְגוּ אוֹתוֹ, שֶׁהֲרֵי לְבִתּוֹ עָשׂוּ דִין,"],[1,"","וּמַה הוּא? שֶׁבַּת לוֹט נָתְנָה פַּת לֶחֶם לְעָנִי אֶחָד, יָדְעוּ בָזֶה, וּמָרְחוּ אוֹתָהּ בִּדְבַשׁ וְהוֹשִׁיבוּהָ בְּרֹאשׁ הַגַּג עַד שֶׁהַצְּרָעוֹת אָכְלוּ אוֹתָהּ."],[2,"","אֶלָּא מִשּׁוּם שֶׁזֶּה הָיָה בַּלַּיְלָה, חָשַׁב שֶׁלֹּא יִסְתַּכְּלוּ בְּנֵי הָעִיר עָלָיו. וְעִם כָּל זֶה, כֵּיוָן שֶׁנִּכְנְסוּ לַבַּיִת, הִתְכַּנְּסוּ כֻלָּם וְהִקִּיפוּ אֶת הַבַּיִת."],[3,"","אָמַר רַבִּי יִצְחָק, לָמָּה רָץ לוֹט אַחֲרֵיהֶם, (אלא משום) שֶׁכָּתוּב וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם? רַבִּי חִזְקִיָּה וְרַבֵּי יֵיסָא. אֶחָד אָמַר, דְּמוּת אַבְרָהָם רָאָה עִמָּם. וְאֶחָד אָמַר, שְׁכִינָה בָּאָה עִמָּהֶם. כָּתוּב כָּאן וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וְכָתוּב שָׁם וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל. מַה לְּהַלָּן רָאָה שְׁכִינָה, אַף כָּאן רָאָה שְׁכִינָה."],[4,"","וַיַּרְא לוֹט וַיָּרָץ לִקְרָאתָם, וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַ\"י, בְּאָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוֹ\"ד. סוּרוּ נָא, הָיָה צָרִיךְ לִכְתֹּב גְּשׁוּ נָא, מַה זֶּה סוּרוּ נָא? אֶלָּא לְהַחֲזִירָם סְבִיב הַבַּיִת כְּדֵי שֶׁלֹּא יִרְאוּ אוֹתָם בְּנֵי הָעִיר וְלֹא יִכָּנְסוּ בְּדֶרֶךְ יָשָׁר הַבַּיְתָה, וּמִשּׁוּם כָּךְ סוּרוּ נָא."],[5,"","רַבִּי חִזְקִיָּה פָּתַח, (איוב כח) כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. כַּמָּה יֵשׁ לָהֶם לִבְנֵי אָדָם לְהִסְתַּכֵּל בְּמַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּבֵּחַ בּוֹ לְמַעְלָה וּמִשְׁתַּבֵּחַ בּוֹ לְמַטָּה, מִשּׁוּם שֶׁהַתּוֹרָה הִיא עֵץ חַיִּים לְכָל אוֹתָם הָעוֹסְקִים בָּהּ לָתֵת לָהֶם חַיִּים בָּעוֹלָם הַזֶּה וְלָתֵת לָהֶם חַיִּים בָּעוֹלָם הַבָּא."]]],[["תָּא חֲזֵי, כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. לְמֵיהַב לוֹן מְזוֹנָא וּלְסַפָּקָא לוֹן מִכָּל מַה דְּאִצְטְרִיכוּ, בְּגִין דְּאִיהוּ אַשְׁגַּח בָּהּ תָּדִיר, דִּכְתִיב, (דברים י״א:י״ב) תָּמִיד עֵינֵי יְיָ אֱלוֹהֶיךָ בָּהּ מֵרִשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה.","בְּגִין דְּאֶרֶץ דָּא מַה כְּתִיב בָּהּ (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ, וּלְבָתַר אִיהִי יְהַבְתְּ מְזוֹנָא וְטַרְפָא לְכָל אִנּוּן חֵיוָן בְּרָא דִּכְתִיב (משלי ל״א:ט״ו) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ.","וְעַל דָּא כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. לְכֻלְהוּ בְּנֵי עָלְמָא לְמֵיהַב לוֹן מְזוֹנָא וְסִפּוּקָא לְכָל מַה דְּאִצְטְרִיךְ כָּל חַד וְחַד דִּכְתִיב (תהילים קמ״ה:ט״ז) פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן.","דָּבָר אַחֵר כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט. לְאִסְתַּכָּלָא עוֹבָדוֹי דְּבַר נָשׁ וּלְאַשְׁגָּחָא בְּכָל מַה דְּעַבְדֵי בְּנֵי נָשָׁא בְּעָלְמָא. תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה. מִסְתַּכֵּל וְחָמֵי לְכָל חַד וְחַד.","תָּא חֲזֵי, כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא עוֹבָדִין דִּסְדוֹם וַעֲמוֹרָה, שַׁדַּר לוֹן לְאִנּוּן מַלְאָכִין לְחַבָּלָא לִסְדוֹם. מַה כְּתִיב וַיַּרְא לוֹט חָמָא לִשְׁכִינְתָּא. וְכִי מַאן יָכִיל לְמֶחמֵי שְׁכִינְתָּא, אֶלָא חָמָא זָהֲרָא חַד דְּנָהִיר דְּקָא סָלְקָא עַל רֵישַׁיְיהוּ. וּכְדֵין וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַי בְּאָלֶ\"ף דָלֶ\"ת כְּמָה דְּאִתְּמָר, וּבְגִין שְׁכִינְתָּא הַהוּא נְהִירוּ דְּנָהִיר קָאֲמַר, סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ וְרַחֲצוּ רַגְלֵיכֶם.","לָא עֲבַד הָכִי אַבְרָהָם, אֶלָּא בְּקַדְמִיתָא אָמַר וְרַחֲצוּ רַגְלֵיכֶם וּלְבָתַר וְאֶקְחָה פַּת לֶחֶם וְגו'. אֲבָל לוֹט אָמַר סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ. וּלְבָתַר וְרַחֲצוּ רַגְלֵיכֶם וְהִשְׁכַּמְתֶּם וַהֲלַכְתֶּם לְדַרְכְּכֶם. בְּגִין דְּלָא יִשְׁתְּמוֹדְעוּן בְּהוּ בְּנֵי נָשָׁא.","וַיֹּאמְרוּ לֹא כִּי בָרְחוֹב נָלִין. בְּגִין דְּכָךְ הֲווּ עָבְדֵי אוֹרְחִין דְּעָאלִין תַּמָּן לָא הֲוָה בַּר נָשׁ דְּיִכְנוֹשׁ לוֹן לְבֵיתָא, וְעַל דָּא אָמְרוּ לא כִּי בָרְחוֹב נָלִין. מַה כְּתִיב וַיִּפְצַר בָּם מְאֹד וְגו'.","תָּא חֲזֵי כַּד קוּדְשָׁא בְּרִיךְ הוּא עֲבִיד דִּינָא בְּעָלְמָא, שְׁלִיחָא חָדָא עֲבִיד לֵיהּ, וְהַשְׁתָּא חָמֵינָן תְּרֵי שְׁלוּחֵי, אַמַּאי וְכִי לָא סַגֵּי בְּחַד. אֶלָא חַד הֲוָה, וּמַה דְּאָמַר תְּרֵי (הכי הוא ודאי בגין דחד) חַד הֲוָה לְאַפָּקָא לֵיהּ לְלוֹט וּלְשֵׁזָבָא לֵיהּ, וְחַד לְמֶהְפַּךְ לְקַרְתָּא וּלְחַבָּלָא אַרְעָא, וּבְגִין כָּךְ אִשְׁתָּאַר חַד:","\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 רַבִּי פָּתַח בְּהַאי קְרָא (שופטים ג׳:א׳) וְאֵלֶּה הַגּוֹיִם אֲשֶׁר הִנִּיחַ יְיָ לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אָמַר רַבִּי חָזֵי הֲוִית בְּהַהוּא עָלְמָא (ולית עלמא) קָאִים (ד\"א ולית מעלה) אֶלָּא בְּאִנּוּן דְּשַׁלִּיטִין עַל רְעוּתָא דְּלִבְּהוֹן שֶׁנֶּאֱמַר (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגו'. אָמַר רַב יְהוּדָה לָמָּה זָכָה יוֹסֵף לְאוֹתָהּ הַמַּעֲלָה וְהַמַּלְכוּת, בִּשְׁבִיל שֶׁכָּבַשׁ יִצְּרוֹ. דְּתָנִינָן כָּל הַכּוֹבֵשׁ אֶת יִצְּרוֹ מַלְכוּתָא דִּשְׁמַיָא אָחִיל עֲלֵיהּ.","דְּאָמַר רַב אַחָא לֹא בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא לַיֵּצֶּר הָרָע אֶלָּא לְנַסּוֹת בּוֹ בְּנֵי אָדָם. וּמִי בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְנַסּוּתָא בִּבְנֵי נָשָׁא. אִין. דְּאָמַר רַב אַחָא מְנָא לָן מִדִּכְתִיב, (דברים י״ג:ד׳) כִּי יָקוּם בְּקִרְבְּךָ נָבִיא וגו' וּבָא הָאוֹת וְהַמּוֹפֵת וגו' כִּי מְנַסֶה יְיָ אֱלהֵיכֶם וגו'. וְלָמָה בָּעֵי נַסוּתָא דְּהָא כָּל עוֹבָדוֹי דְּבַר נָשׁ אִתְגְּלִי קַמֵּיהּ, אֶלָּא שֶׁלא לָתֵת פִּתְחוֹן פֶּה לִבְנֵי אָדָם. רְאֵה מַה כְּתִיב וְלוֹט יוֹשֵׁב בְּשַׁעַר סְדוֹם, דְּהֲוָה יָתִיב לְנַסּוּתָא לִבְרִיָּיתָא.","אָמַר רַבִּי יִצְּחָק מַאי דִּכְתִיב (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגו'. אֲפִלּוּ בִּשְׁעַת דִּינוֹ שֶׁל רָשָׁע הוּא מֵעִיז פָּנָיו ואֲזַי הוּא בְּרִשְׁעָתוֹ קַיָּים, רְאֵה מַה כְּתִיב טֶרֶם יִשְׁכָּבוּ וגו'. אָמַר רַבִּי יִצְּחָק כְּשֵׁם שֶׁבָּרָא קוּדְשָׁא בְּרִיךְ הוּא גַּן עֵדֶן בָּאָרֶץ כָּךְ בָּרָא גֵּיהִנֹּם בָּאָרֶץ. וּכְשֵׁם שֶׁבָּרָא גַּן עֵדֶן לְמַעְלָה כָּךְ בָּרָא גֵּיהִנֹּם לְמַעְלָה.","גַּן עֵדֶן בָּאָרֶץ דִּכְתִיב, (בראשית ב׳:ח׳) וַיִּטַע יְיָ אֱלֹהִים גַּן בְּעֵדֶן וגו'. גֵּיהִנֹּם בָּאָרֶץ דִּכְתִיב, (איוב י׳:כ״ב) אֶרֶץ עֵיפָתָה כְּמוֹ אוֹפֶל וגו'. גַּן עֵדֶן לְמַעְלָה דִּכְתִיב, (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדוֹנִי צְּרוּרָה בִּצְּרוֹר הַחַיִּים אֶת ה' אֱלֹהֶיךָ וּכְתִיב, (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ.","גֵּיהִנֹּם לְמַעְלָה דִּכְתִיב וְאֵת נֶפֶשׁ אֹיְבֶיךָ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. גַּן עֵדֶן לְמַטָה כִּדְקָאֲמָרָן. גַּן עֵדֶן לְמַעְלָה לְנִשְׁמָתָן שֶׁל צַּדִּיקִים גְּמוּרִים לִהְיוֹת נִזּוֹנִין מֵאוֹר הַגָּדוֹל שֶׁל מַעְלָה.","גֵּיהִנִֹּם לְמַטָה לְאוֹתָם הָרְשָׁעִים (דישראל) שֶׁלֹּא קִבְּלוּ בְּרִית מִילָה וְלֹא הֶאֱמִינוּ בְּהַקָּדוֹשׁ בָּרוּךְ הוּא וְדָתוֹ ולֹא שָׁמְרוּ שַׁבָּת, וְאֵלּוּ הֵם עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שֶׁנִּדּוֹנִים בָּאֵשׁ, שֶׁנְּאֱמַר (יחזקאל ט״ו:ז׳) מֵהָאֵשׁ יָצָּאוּ וְהָאֵשׁ תֹּאכְלֵם וגו'. וּכְתִיב (ישעיהו ס״ו:כ״ד) וְיָצְּאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים וְגו'.","גֵּיהִנֹּם לְמַעְלָה לְאוֹתָם פּוֹשְׁעֵי יִשְׂרָאֵל שֶׁעָבְרוּ עַל מִצְּווֹת הַתּוֹרָה וְלֹא חָזְרוּ בִּתְשׁוּבָה שֶׁדּוֹחִים אוֹתָם לַחוּץ עַד שֶׁיְקַבְּלוּ עָנְשָׁם. וְהוֹלְכִים וְסוֹבְבִים כָּל הָעוֹלָם שֶׁנֶּאֱמַר (תהילים י״ב:ט׳) סָבִיב רְשָׁעִים יִתְהַלָּכוּן.","וְשָׁם נִדּוֹנִים שְׁנֵים עָשָׂר חֹדֶשׁ, לְאַחַר כֵּן מָדוֹרָם עִם אוֹתָם שֶׁקִּבְּלוּ עָנְשָׁם בְּמוֹתָם כָּל אֶחָד ואֶחָד כְּפִי הַמָּקוֹם הָרָאוּי לוֹ. וְהָרְשָׁעִים שֶׁל הַעוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת נִדּוֹנִים תָּמִיד בָּאֵשׁ וּבַמַּיִם וְשׁוּב אֵינָם עוֹלִים שֶׁנְּאֱמַר וְאִשָּׁם לא תִכְבֶּה.","מִשְׁפַּט הָרְשָׁעִים בַּגֵּיהִנָּם כְּמָה דִּכְתִיב וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ וְגו' ושׁוּב אֵינָם עוֹלִים ולֹא יָקוּמוּ לְיוֹם הַדִּין שֶׁנֶּאֱמַר (דברים כ״ט:כ״ב) אֲשֶׁר הָפַךְ יְיָ בְּאַפּוֹ וּבַחֲמָתוֹ, בְּאַפּוֹ בָּעוֹלָם הַזְּה. וּבַחֲמָתוֹ בָּעוֹלָם הַבָּא.","אָמַר רַבִּי יִצְּחָק לְהַאי גַּוְונָא אִית גַּן עֵדֶן לְמַעְלָה וְאִית גַּן עֵדֶן לְמַטָה. אִית גֵּיהִנֹּם לְמַטָה ואִית גֵּיהִנֹּם לְמַעְלָה. אָמַר רַבִּי יַעֲקֹב הָרְשָׁעִים שֶׁקִּלְקְלוּ בְּרִית מִילָה שֶׁבָּהֶם וְחִלְּלוּ שַׁבָּת בְּפַרְהֶסְיָא וְחִלְּלוּ אֶת הַמּוֹעֲדוֹת וְשֶׁכָּפְרוּ בַּתּוֹרָה וְשֶׁכָּפְרוּ בִּתְחִיַּת הַמֵּתִים וְכַדּוֹמֶה לָהֶם יוֹרְדִים לַגֵּיהִנֹּם שֶׁלְּמַטָה וְנִדּוֹנִים שָׁם וְשׁוּב אֵינָם עוֹלִים.","אֲבָל יָקוּמוּ לְיוֹם הַדִּין וְיָקוּמוּ לִתְחִיַּת הַמֵּתִים, וַעֲלֵיהֶם נֶאֱמַר (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמָת עָפָר יָקִיצּוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגו'. וַעֲלֵיהֶם נְאֱמַר (ישעיהו ס״ו:כ״ד) וְהָיוּ דֵּרָאוֹן לְכָל בָּשָׂר. מַה דֵּרָאוֹן, דַּיי רָאוֹן, שֶׁהַכֹּל יֹאמְרוּ דַּיי בִּרְאִיָּיתָם. וְעַל הַצַּדִּיקִים שֶׁבְּיִשְׂרָאֵל נֶאֱמַר (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַּדִּיקִים וגו', (ע\"כ מדרש הנעלם)","וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה וְגו'. רַבִּי חִיָּיא פָּתַח (ישעיהו י״ג:ט׳) הִנֵּה יוֹם יְיָ בָּא אַכְזָרִי וְגו'. הִנִּה יוֹם יְיָ בָּא, דָּא בֵּי דִינָא לְתַתָּא. בָּא כְּמָה דְּאִתְּמָר. (קו א) הַבָּאָה אֵלַי (עשו). בְּגִין דְּלָא עֲבִיד דִּינָא עַד דְעָאל וְנָטִיל רְשׁוּ, כְּגַוְונָא דָּא קֵץ כָּל בָּשָׂר בָּא לְפָנַי.","דָּבָר אַחֵר הִנֵּה יוֹם יְיָ בָּא. דָּא הוּא מְחַבְּלָא לְתַתָּא כַּד נָטִיל נִשְׁמָתָא, בְּגִינֵי כָּךְ אַכְזָרִי וְעֶבְרָה. לָשׂוּם הָאָרֶץ לְשַׁמָּה, דָּא סְדוֹם וַעֲמוֹרָה. וְחַטָּאֶיהָ יַשְׁמִיד מִמֶּנָּהּ. אִלֵּין יַתְבֵי אַרְעָא."],[[0,"ת\"ח כי וכו':","בוא וראה, כתוב, כי הוא לקצות הארץ יביט, היינו, כדי לתת להם מזונות ולכלכל אותם בכל מה שהם צריכים. ארץ היא המלכות, קצות הארץ היינו כל הנמשכים ממנה משום שהוא משגיח בה תמיד שכתוב, עיני ה' אלקיך בה מרשית השנה ועד אחרית שנה."],[1,"בגין דארץ וכו':","משום שארץ זו, דהיינו המלכות, מה כתוב בה, ממרחק תביא לחמה. ואחר כך היא נותנת טרף ומזון לכל חיות השדה, שהם המלאכים דבי\"ע שכתוב ותקם בעוד לילה ותתן טרף לביתה וחק לנערותיה."],[2,"וע\"ד כי הוא וכו':","ועל כן כתוב, כי הוא לקצות הארץ יביט, תחת כל השמים יראה, דהיינו לכל בני העולם, לתת להם מזונות וכלכלה לפי צרכו של כל אחד ואחד. שכתוב פותח את ידך ומשביע לכל חי רצון."],[3,"ד\"א כי הוא לקצות וכו':","פירוש אחר להכתוב כי הוא לקצות הארץ יביט, היינו להסתכל במעשה בני אדם, ולהשגיח בכל מה שבני אדם עושים בעולם. תחת כל השמים יראה, היינו שמסתכל ורואה את כל אחד ואחד."],[4,"ת\"ח כיון דחמא וכו':","בוא וראה כיון שראה הקב\"ה מעשה סדום ועמורה, שלח אותם המלאכים להשחית את סדום, מה כתוב, וירא לוט, היינו שראה את השכינה. ושואל, וכי מי יכול לראות את השכינה. ומשיב, אלא ראה אור אחד מאיר ועולה על ראשיהם, ואז אמר, הנה נא אדני, באלף דלת, שהוא שם השכינה כמו שנתבאר (לעיל אות רכ\"ט) ובשביל השכינה דהיינו אותה הארה שהיה מאיר על ראשיהם כנ\"ל, אמר סורו נא אל בית עבדכם."],[5,"ולינו ורחצו רגליכם:","אברהם לא עשה כך, אלא בתחילה אמר ורחצו רגליכם ואחר כך, ואקחה פת לחם. אבל לוט אמר סורו נא וגו' ולינו, ולבתר ורחצו רגליכם וגו'. והוא כדי שלא יכירו בהם בני אדם, כלומר, שאם ירגישו בהם, יאמרו שעתה באו אליו, שהרי עוד לא רחצו רגליהם מן הדרך."],[6,"ויאמרו לא כי ברחוב נלין:","אמרו כן, משום שכך היו עושים האורחים שנכנסו שמה, שלנו ברחוב, כי לא היה אדם שיאספם הביתה, וע\"כ אמרו, לא כי ברחוב נלין. מה כתוב, ויפצר בם מאד וגו'."],[7,"ת\"ח כד וכו':","בוא וראה, כאשר הקב\"ה עושה דין בעולם, שליח אחד עושה אותו, ועתה, בהפיכת סדום, אנו רואים ב' שליחים כמ\"ש ויבאו שני המלאכים סדומה. וכי לא די מלאך אחד. ומשיב, אלא אחד היה, ומה שאומר הכתוב שני מלאכים, אחד היה להוציא את לוט ולהציל אותו. ואחד היה להפך העיר ולהשחית הארץ. ומשום זה היה רק אחד בהפיכת סדום."],[8,"רבי פתח וכו':","רבי פתח במקרא הזה. ואלה הגוים אשר הניח ה' לנסות בם את ישראל. אמר רבי, מסתכל הייתי באותו העולם. היינו בעולם הנצחי, ואין העולם עומד, אלא על אלו הצדיקים המושלים על רצון לבם. שנאמר עדות ביהוסף שמו וגו', ואמר רב יהודה, למה זכה יוסף לאותה המעלה והמלכות בשביל שכבש יצרו, כי למדנו, כל הכובש את יצרו מלכות שמים ממתנת עליו."],[17,"אמר ר' יצחק להאי גוונא וכו':","ומסיים ר' יצחק. לאופן הזה, שבארתי, יש ג\"ע למעלה וכו'."],[19,"וה' המטיר על סדום ועל עמורה וגו':","ר' חייא פתח. הנה יום ה' בא אכזרי וגו': הנה יום ה' זה בית דין של מטה, דהיינו הדינים הנמשכים מהמלכות, בעת שהיא בהארת השמאל שה\"ס נקודת השורק, מטרם שנכלל על ידי קו אמצעי. שלמעלה באות רט\"ז מכנה אותה גזרת דינא. \u0003בא,\u0004 פירושו כמו שנתבאר בפירוש הכתוב \u0003הבאה אלי,\u0004 (לעיל באות רי\"ז) שהיא בא תמיד לכל התחלת הזווג. \u0003הבאה אלי,\u0004 משום שאיני עושה דין עד שנכנס ומקבל רשות, כעין זה נתבאר בהכתוב קץ כל בשר בא לפני (לעיל נח דף כ\"ט אות ע\"ח) שבא לקבל רשות."],[19,"","פירוש. כי נתבאר לעיל (בראשית ב' דף קל\"ו ד\"ה פנימיות) שב' פעולות נוהגות בכל זווג. ופעולה הראשונה ה\"ס \u0003נטילת רשות,\u0004 שפירושו שאין הנוקבא מתפייסת לזווג עם ז\"א, מטרם שממשיך לה הארת השמאל שה\"ס הארת נקודת השורק. וע\"כ נבחן המשכת הארת השמאל, לבחינת נטילת רשות לזווג. עש\"ה. וזה אמרו כאן, \u0003בגין דלא עביד דינא עד דעאל ונטיל רשו.\u0004 כי בעת שז\"א מקבל רשות מן הנוקבא, דהיינו בעת שממשיך לה הארת השמאל, באותו רגע כל בעלי הדין מקבלים רשות מז\"א לפעול הדינים, כי אין הארת שמאל בלי גילוי הדינים, כי ע\"כ נקראת \u0003גזרת דינא,\u0004 לעיל (באות רס\"ז ע\"ש) וז\"ס \u0003בא לפני ליטול רשות.\u0004 כי בא בתחילת כל זווג כנ\"ל."],[20,"דבר אחר וכו':","פירוש אחר. \u0003הנה יום ה' בא,\u0004 זהו המחבל של מטה, דהיינו מלאך המות, כשהוא נוטל את הנשמה, משום זה קורא אותו הכתוב, \u0003אכזרי, ועברה וגו' לשום הארץ לשמה,\u0004 זהו סדום ועמורה. שנהפכו והיו לשמה. \u0003וחטאיה ישמיד ממנה,\u0004 אלו יושבי הארץ ההיא."]],[[0,"","בֹּא רְאֵה, כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט, לָתֵת לָהֶם מָזוֹן וּלְסַפֵּק אוֹתָם מִכָּל מַה שֶּׁהִצְטָרְכוּ, מִשּׁוּם שֶׁהוּא מַשְׁגִּיחַ בָּהּ תָּמִיד, שֶׁכָּתוּב (דברים יא) תָּמִיד עֵינֵי ה' אֱלֹהֶיךְ בָּהּ מֵרֵשִׁית הַשָּׁנָה וְעַד אַחֲרִית שָׁנָה."],[1,"","מִשּׁוּם שֶׁאֶרֶץ זוֹ מַה כָּתוּב בָּהּ? (משלי לא) מִמֶּרְחָק תָּבִיא לַחְמָהּ. אַחַר כָּךְ הִיא נוֹתֶנֶת מָזוֹן וְטֶרֶף לְכָל חַיּוֹת הַשָּׂדֶה, שֶׁכָּתוּב (שם) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ."],[2,"","וְעַל זֶה כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה, אֶת כָּל בְּנֵי הָעוֹלָם לָתֵת לָהֶם מָזוֹן וְסִפּוּק לְכָל מַה שֶּׁצָּרִיךְ כָּל אֶחָד וְאֶחָד, שֶׁכָּתוּב (תהלים קמה) פּוֹתֵחַ אֶת יָדֶךְ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן."],[3,"","דָּבָר אַחֵר כִּי הוּא לִקְצוֹת הָאָרֶץ יַבִּיט, לְהִסְתַּכֵּל בְּמַעֲשֵׂי בֶּן הָאָדָם וּלְהַשְׁגִּיחַ בְּכָל מַה שֶּׁעוֹשִׂים בּוֹ בְּנֵי אָדָם בָּעוֹלָם. תַּחַת כָּל הַשָּׁמַיִם יִרְאֶה, מִסְתַּכֵּל וְרוֹאֶה כָּל אֶחָד וְאֶחָד."],[4,"","בֹּא רְאֵה, כֵּיוָן שֶׁרָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲשֵׂי סְדם וַעֲמֹרָה, שָׁלַח לָהֶם אוֹתָם הַמַּלְאָכִים לְהַשְׁחִית אֶת סְדם. מַה כָּתוּב? וַיַּרְא לוֹט. רָאָה אֶת הַשְּׁכִינָה. וְכִי מִי יָכוֹל לִרְאוֹת שְׁכִינָה? אֶלָּא רָאָה זהַר אֶחָד שֶׁמֵּאִיר וְעוֹלֶה עַל רָאשֵׁיהֶם. וְאָז, וַיֹּאמֶר הִנֶּה נָּא אֲדנַי, בְּאָלֶ\"ף דָּלֶ\"ת כְּמוֹ שֶׁנִּתְבָּאֵר. וּבִגְלַל הַשְּׁכִינָה אוֹתוֹ הָאוֹר שֶׁהֵאִיר הוּא אָמַר סוּרוּ נָא אֶת בֵּית עַבְדְּכֶם וְלִינוּ וְרַחֲצוּ רַגְלֵיכֶם."],[5,"","לֹא עָשָׂה כָּךְ אַבְרָהָם, אֶלָּא בַּתְּחִלָּה אָמַר וְרַחֲצוּ רַגְלֵיכֶם, וְאַחַר כָּךְ וְאֶקְחָה פַּת לֶחֶם וְגוֹ'. אֲבָל לוֹט אָמַר סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ, וְאַחַר כָּךְ וְרַחֲצוּ רַגְלֵיכֶם וְהִשְׁכַּמְתֶּם וַהֲלַכְתֶּם לְדַרְכְּכֶם, כְּדֵי שֶׁלֹּא יֵדְעוּ בָהֶם בְּנֵי הָאָדָם."],[6,"","וַיֹּאמְרוּ לֹא כִּי בָרְחוֹב נָלִין. מִשּׁוּם שֶׁכָּךְ הָיוּ עוֹשִׂים: אוֹרְחִים שֶׁנִּכְנָסִים לְשָׁם, לֹא הָיָה בֶּן אָדָם שֶׁיַּכְנִיסֵם לַבַּיִת. וְעַל זֶה אָמְרוּ, לֹא כִּי בָרְחוֹב נָלִין. מַה כָּתוּב וַיִּפְצַר? בָּם מְאֹד וְגוֹ'."],[7,"","בּא רְאֵה, כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּעוֹלָם, שָׁלִיחַ אֶחָד עוֹשֶׂה אוֹתוֹ, וְכָעֵת רָאִינוּ שְׁנֵי שְׁלִיחִים, לָמָּה? וְכִי לֹא מַסְפִּיק בְּאֶחָד? אֶלָּא אֶחָד הָיָה, וּמַה שֶּׁאָמַר שְׁנַיִם (כך זה ודאי, משום שאחד) - אֶחָד הָיָה לְהוֹצִיא אֶת לוֹט וּלְהַצִּילוֹ, וְאֶחָד לַהֲפֹךְ אֶת הָעִיר וּלְהַשְׁחִית אֶת הָאָרֶץ, וּלְכָךְ נִשְׁאַר אֶחָד."],[8,"","רַבִּי פָּתַח בְּפָסוּק זֶה, (שופטים ג) וְאֵלֶּה הַגּוֹיִם אֲשֶׁר הִנִּיחַ ה' לְנַסּוֹת בָּם אֶת יִשְׂרָאֵל. אָמַר רַבִּי, רָאִיתִי בְּאוֹתוֹ עוֹלָם, (ואין העולם) עוֹמֵד (ואין מעלה) אֶלָּא בְּאוֹתָם שֶׁשּׁוֹלְטִים עַל רְצוֹן לִבָּם, שֶׁנֶּאֱמַר (תהלים פא) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגוֹ'. אָמַר רַב יְהוּדָה, לָמָּה זָכָה יוֹסֵף לְאוֹתָהּ הַמַּעֲלָה וְהַמַּלְכוּת? בִּשְׁבִיל שֶׁכָּבַשׁ יִצְרוֹ. שֶׁשָּׁנִינוּ, כָּל הַכּוֹבֵשׁ אֶת יִצְרוֹ, מֵחִיל עָלָיו אֶת מַלְכוּת הַשָּׁמַיִם."],[9,"","שֶׁאָמַר רַב אָחָא, לֹא בָרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַיֵּצֶר הָרָע אֶלָּא לְנַסּוֹת בּוֹ בְּנֵי אָדָם. וְהַאִם רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַסּוֹת בְּנֵי אָדָם? כֵּן. שֶׁאָמַר רַב אָחָא, מִנַּיִן לָנוּ? מִשֶּׁכָּתוּב (דברים יג) כִּי יָקוּם בְּקִרְבְּךְ נָבִיא וְגוֹ' וּבָא הָאוֹת וְהַמּוֹפֵת וְגוֹ', כִּי מְנַסֶּה ה' אֱלֹהֵיכֶם וְגוֹ'. וְלָמָּה צָרִיךְ נִסָּיוֹן, שֶׁהֲרֵי כָּל מַעֲשֵׂי בְּנֵי אָדָם גְּלוּיִים לְפָנָיו? אֶלָּא שֶׁלֹּא לִתֵּן פִּתְחוֹן פֶּה לִבְנֵי אָדָם. רְאֵה מַה כָּתוּב וְלוֹט? יֹשֵׁב בְּשַׁעַר סְדם, שֶׁהָיָה יוֹשֵׁב לְנַסּוֹת אֶת הַבְּרִיּוֹת."],[10,"","אָמַר רַבִּי יִצְחָק, מַהוּ שֶׁכָּתוּב (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ וְגוֹ'? אֲפִלּוּ בִּשְׁעַת דִּינוֹ שֶׁל רָשָׁע הוּא מֵעֵז פָּנָיו, וַאֲזַי הוּא בְּרִשְׁעָתוֹ קַיָּם. רְאֵה מַה כָּתוּב, טֶרֶם יִשְׁכָּבוּ וְגוֹ'. אָמַר רַבִּי יִצְחָק, כְּשֵׁם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא גַּן עֵדֶן בָּאָרֶץ - כָּךְ בָּרָא גֵיהִנֹּם בָּאָרֶץ. וּכְשֵׁם שֶׁבָּרָא גַּן עֵדֶן לְמַעְלָה - כָּךְ בָּרָא גֵיהִנֹּם לְמַעְלָה."],[11,"","גַּן עֵדֶן בָּאָרֶץ, שֶׁכָּתוּב (בראשית ב) וַיִּטַּע ה' אֱלֹהִים גַּן בְּעֵדֶן וְגוֹ'. גֵּיהִנֹּם בָּאָרֶץ, שֶׁכָּתוּב (איוב י) אֶרֶץ עֵיפָתָה כְּמוֹ אֹפֶל וְגוֹ'. גַּן עֵדֶן לְמַעְלָה, שֶׁכָּתוּב (שמואל א כה) וְהָיְתָה נֶפֶשׁ אֲדנִי צְרוּרָה בִּצְרוֹר הַחַיִּים אֵת ה' אֱלֹהֶיךְ, וְכָתוּב (קהלת יב) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ."],[12,"","גֵּיהִנֹּם לְמַעְלָה, שֶׁכָּתוּב וְאֵת נֶפֶשׁ אֹיְבֶיךְ יְקַלְּעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. גַּן עֵדֶן לְמַטָּה, כְּמוֹ שֶׁאָמַרְנוּ. גַּן עֵדֶן לְמַעְלָה לְנִשְׁמָתָן שֶׁל צַדִּיקִים גְּמוּרִים לִהְיוֹת נִזּוֹנִים מֵאוֹר הַגָּדוֹל שֶׁל מַעְלָה."],[13,"","גֵּיהִנֹּם לְמַטָּה לְאוֹתָם הָרְשָׁעִים (של ישראל) שֶׁלֹּא קִבְּלוּ בְּרִית מִילָה וְלֹא הֶאֱמִינוּ בַּקָּבָּ\"ה וְדָתוֹ וְלֹא שָׁמְרוּ שַׁבָּת, וְאֵלּוּ הֵם עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שֶׁנִּדּוֹנִים בָּאֵשׁ, שֶׁנֶּאֱמַר (יחזקאל טו) מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם וְגוֹ', וְכָתוּב (ישעיה סו) וְיָצְאוּ וְרָאוּ בְּפִגְרֵי הָאֲנָשִׁים וְגוֹ'."],[14,"","גֵּיהִנֹּם לְמַעְלָה לְאוֹתָם פּוֹשְׁעֵי יִשְׂרָאֵל שֶׁעָבְרוּ עַל מִצְווֹת הַתּוֹרָה וְלֹא חָזְרוּ בִּתְשׁוּבָה, שֶׁדּוֹחִים אוֹתָם לַחוּץ עַד שֶׁיְּקַבְּלוּ עָנְשָׁם, וְהוֹלְכִים וְסוֹבְבִים כָּל הָעוֹלָם, שֶׁנֶּאֱמַר (תהלים יב) סָבִיב רְשָׁעִים יִתְהַלָּכוּן."],[15,"","וְשָׁם נִדּוֹנִים שְׁנֵים עָשָׂר חֹדֶשׁ. לְאַחַר כֵּן מָדוֹרָם עִם אוֹתָם שֶׁקִּבְּלוּ עָנְשָׁם בְּמוֹתָם, כָּל אֶחָד וְאֶחָד כְּפִי הַמָּקוֹם הָרָאוּי לוֹ. וְהָרְשָׁעִים שֶׁל הָעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת נִדּוֹנִים תָּמִיד בָּאֵשׁ וּבַמַּיִם וְשׁוּב אֵינָם עוֹלִים, שֶׁנֶּאֱמַר וְאִשָּׁם לֹא תִכְבֶּה."],[16,"","מִשְׁפַּט הָרְשָׁעִים בַּגֵּיהִנֹּם כְּמוֹ שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ וְגוֹ', וְשׁוּב אֵינָם עוֹלִים, וְלֹא יָקוּמוּ לְיוֹם הַדִּין, שֶׁנֶּאֱמַר (דברים כט) אֲשֶׁר הָפַךְ ה' בְּאַפּוֹ וּבַחֲמָתוֹ. בְּאַפּוֹ - בָּעוֹלָם הַזֶּה. וּבַחֲמָתוֹ - בָּעוֹלָם הַבָּא."],[17,"","אָמַר רַבִּי יִצְחָק, כְּמוֹ זֶה יֵשׁ גַּן עֵדֶן לְמַעְלָה וְיֵשׁ גַּן עֵדֶן לְמַטָּה. יֵשׁ גֵּיהִנֹּם לְמַטָּה וְיֵשׁ גֵּיהִנֹּם לְמַעְלָה. אָמַר רַבִּי יַעֲקֹב, הָרְשָׁעִים שֶׁקִּלְקְלוּ בְּרִית מִילָה שֶׁבָּהֶם וְחִלְלוּ שַׁבָּת בְּפַרְהֶסְיָה וְחִלְלוּ אֶת הַמּוֹעֲדוֹת וְשֶׁכָּפְרוּ בַּתּוֹרָה וְשֶׁכָּפְרוּ בִּתְחִיַּת הַמֵּתִים וְכַדּוֹמֶה לָהֶם, יוֹרְדִים לַגֵּיהִנֹּם שֶׁלְּמַטָּה וְנִדּוֹנִים שָׁם, וְשׁוּב אֵינָם עוֹלִים."],[18,"","אֲבָל יָקוּמוּ לְיוֹם הַדִּין וְיָקוּמוּ לִתְחִיַּת הַמֵּתִים, וַעֲלֵיהֶם נֶאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגוֹ', וַעֲלֵיהֶם נֶאֱמַר (ישעיה סו) וְהָיוּ דֵרָאוֹן לְכָל בָּשָׂר. מַהוּ דֵרָאוֹן? דַּי רָאוֹן, שֶׁהַכֹּל יֹאמְרוּ דַּי בִּרְאִיָּתָם. וְעַל הַצַּדִּיקִים שֶׁבְּיִשְׂרָאֵל נֶאֱמַר (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. (ע\"כ מדרש הנעלם)."],[19,"","וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (ישעיה יג) הִנֵּה יוֹם ה' בָּא אַכְזָרִי וְגוֹ'. הִנֵּה יוֹם ה' בָּא - זֶה בֵּית דִּין שֶׁלְּמַטָּה. בָּא - כְּמוֹ שֶׁנֶּאֱמַר הַבָּאָה אֵלַי עָשׂוּ. מִשּׁוּם שֶׁלֹּא עוֹשֶׂה דִין עַד שֶׁנִּכְנָס וְנוֹטֵל רְשׁוּת. כְּמוֹ זֶה קֵץ כָּל בָּשָׂר בָּא לְפָנַי."],[20,"","דָּבָר אַחֵר הִנֵּה יוֹם ה' בָּא - זֶהוּ הַמַּשְׁחִית שֶׁלְּמַטָּה כְּשֶׁנּוֹטֵל אֶת הַנְּשָׁמָה, מִשּׁוּם כָּךְ אַכְזָרִי וְעֶבְרָה. לָשׂוּם הָאָרֶץ לְשַׁמָּה - זוֹ סְדם וַעֲמֹרָה. וְחַטָּאֶיהָ יַשְׁמִיד מִמֶּנָּה - אֵלּוּ יוֹשְׁבֵי הָאָרֶץ."]]],[["מַה כְּתִיב בַּתְרֵיהּ כִּי כּוֹכְבֵי הַשָּׁמַיִם וּכְסִילֵיהֶם וְגו'. דְּהָא מִן שְׁמַיָא אַמְטָר עֲלֵיהוֹן אֶשָׁא, וְאַעֲבַר לוֹן מִן עָלְמָא. לְבָתַר מַה כְּתִיב אוֹקִיר אֱנוֹשׁ מִפָּז וְגו'. דָּא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא סָלִיק לֵיהּ עַל כָּל בְּנֵי עָלְמָא.","רַבִּי יְהוּדָה אוֹקִים לוֹן לְהַנֵּי קְרָאֵי בְּיוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא, דִּבְהַהוּא יוֹמָא אִתְחַשְׁכוּ עִלָּאֵי וְתַתָּאֵי, וְאִתְחַשְׁכָן שְׁמַיָא וְכוֹכְבַיָא. רַבִּי אֶלְעָזָר מוֹקִים לְהַנֵּי קְרָאֵי בְּיוֹמָא דְּיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לִכְנְסֶת יִשְׂרָאֵל מֵעַפְרָא, וְהַהוּא יוֹמָא יִתְיְדַע לְעֵילָא וְתַתָּא, דִּכְתִיב, (זכריה י״ד:ז׳) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ. וְהַהוּא יוֹמָא יוֹמָא דְּנוֹקְמָא אִיהוּ, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנָקְמָא מִשְּׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת.","וְכַד קוּדְשָׁא בְּרִיךְ הוּא יַעֲבִיד נוּקְמִין בִּשְׁאָר עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, כְּדֵין אוֹקִיר אֱנוֹשׁ מִּפָּז דָּא מַלְכָּא מְשִׁיחָא דְּיִסְתָּלַּק וְיִתְיָיקַר עַל כָּל בְּנִי עָלְמָא, וְכָל בְּנֵי עָלְמָא יִפְלְחוּן וְיִסְגְּדוּן קַמֵּיהּ דִּכְתִיב, (תהילים ע״ב:ט׳) לְפָנָיו יִכְרְעוּ צִיִּים וְגו' מַלְכֵי תַרְשִׁישׁ וְגו'.","תָּא חֲזֵי, אַף עַל גַּב דִּנְבוּאָה דָא אִתְּמָר עַל בָּבֶל, בְּכוֹלָּא אִתְּמָר. דְּהָא חָמֵינָן בְּהַאי פַּרְשָׁתָא דִּכְתִיב (ר\"ל סמוך לפ' שלמעלה שכ' בה אוקיר אנוש וגו' ואולי לדעת הזוה\"ק חד פר' היא) כִּי יְרַחֵם יְיָ אֶת יַעֲקֹב. וּכְתִיב וּלְקָחוּם עַמִּים וְהֱבִיאוּם אֶל מְקוֹמָם.","וַיְיָ הִמְטִיר עַל סְדוֹם. דָּא דַּרְגָא דְּבֵי דִינָא לְתַתָּא דְּנָטִיל רְשׁוּ מֵעֵילָא. רַבִּי יִצְחָק אָמַר דְּעֲבִיד דִּינָא בְּרַחֲמֵי. דִּכְתִיב מֵאֵת יְיָ מִן הַשָּׁמָיִם. בְּגִין לְאִשְׁתַּכָּחָא דִּינָא בְּרַחֲמֵי. וְאִי תֵימָא מַאי רַחֲמֵי הָכָא דִּכְתִיב וַיְהִי בְּשַׁחֵת אֱלֹהִים אֶת עָרֵי הַכִּכָּר וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וְגו'. וּלְבָתַר נָפְקוּ מִנֵּיהּ תְּרֵין אוּמִין שְׁלֵמִין, וְזָכָה דְּנָפִיק מִנֵּיהּ דָּוִד וּשְׁלֹמֹה מַלְכָּא.","חֲמֵי מַה כְּתִיב וַיְהִי כְּהוֹצִיאָם אוֹתָם הַחוּצָה וַיֹּאמֶר וְגו'. תָּא חֲזֵי (סג א) בְּשַׁעֲתָא דְּדִינָא שָׁרֵי בְּעָלְמָא, הָא אִתְּמָר דְּלָא לִיבָּעֵי לְבַּר נָשׁ לְאִשְׁתַּכָּחָא בְּשׁוּקָא, בְּגִין דְּכֵיוָן דְּשָׁרְיָא דִינָא לָא אַשְׁגַּח בֵּין זַכָּאָה וְחַיָּיבָא, וְלָא בָעֵי (לאסתכלא) לְאִשְׁתַּכָּחָא תַּמָּן. וְהָא אִתְּמָר דִּבְגִין כָּךְ אִסְתִּים נֹחַ בַּתֵּיבָה וְלָא יִשְׁגַּח בְּעָלְמָא בְּשַׁעֲתָא דְּדִינָא יִתְעֲבִיד. וּכְתִיב (שמות י״ב:כ״ב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר עַד דְּיִתְעֲבִיד דִּינָא. וּבְגִין כָּךְ וַיֹּאמֶר הִמָּלֵט עַל נַפְשְׁךָ אַל תַּבִּיט אַחֲרֶיךָ וְגו'.","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק דִּינָא דְּעֲבִיד קוּדְשָׁא בְּרִיךְ הוּא בַּמַּבּוּל וְדִינָא דִּסְדוֹם, תַּרְוַויְיהוּ דִּינִין דְּגֵיהִנֹּם הֲווּ בְּגִין דְּחַיָּיבֵי גֵּיהִנֹּם אִתְדָּנוּ בְּמַיָא וּבְאֶשָׁא.","אָמַר רַבִּי יִצְחָק סְדוֹם בְּדִינָא דְּגֵיהִנֹּם אִתְדָּן, דִּכְתִיב וַיְיָ הִמְטִיר עַל סְדוֹם וְעַל עֲמוֹרָה גָּפְרִית וָאֵשׁ מֵאֵת יְיָ מִן הַשָּׁמָיִם. דָּא מִסִּטְרָא דְּמַיָיא וְדָא (עיין סוף הספר סימן ב) מִסִּטְרָא דְאֶשָׁא. דָּא וְדָא הוּא דִּינָא דְּגֵיהִנֹּם, וְחַיָּיבִין דְּגֵיהִנֹּם בִּתְרֵין דִּינִין אִלֵּין אִתְדָנוּ.","אָמַר לֵיהּ דִּינָא דְּחַיָּיבֵי דְּגֵיהִנֹּם תְּרֵיסַר יַרְחֵי, וְקוּדְשָׁא בְּרִיךְ הוּא סָלִיק לוֹן מִגֵּיהִנֹּם, וְתַמָּן מִתְלַבְּנִין וְיָתְבִין לְתַרְעָא דְּגֵיהִנֹּם, וְחָמָאן אִנּוּן חַיָּיבִין דְּעָאלִין וְדָנִין לוֹן תַּמָּן, וְאִנּוּן תָּבְעֵי רַחֲמֵי עֲלַיְיהוּ. וּלְבָתַר קוּדְשָׁא בְּרִיךְ הוּא חַיִּיס עֲלַיְיהוּ וְאָעִיל לוֹן לְדוּכְתָּא דְּאִצְטְרִיךְ לוֹן. מֵהַהוּא יוֹמָא וּלְהָלְאָה גּוּפָא אִשְׁתְּכַךְ בְּעַפְרָא וְנִשְׁמָתָא יַרְתָא אַתְרָהּ כִּדְחָזֵי לָהּ. (נח סט א)."],[[0,"מה כתיב בתריה וכו':","מה כתוב אחריו, \u0003כי ככבי השמים וכסיליהם\u0004 וגו', כי מן השמים המטיר עליהם אש והעבירם מן העולם. ואחר כך כתוב, \u0003אוקיר אנוש מפז\u0004 וגו', זהו אברהם, שהקב\"ה העלה אותו למעלה מכל בני העולם."],[1,"ר' יהודה אוקים וכו':","ר\"י העמיד את המקראות האלו, על יום שנחרב בית המקדש. שביום ההוא נחשכו העליונים והתחתונים ונחשנו הככבים ומזלות."],[1,"ר' אלעזר מוקים וכו':","ר\"א מעמיד את מקראות הללו, ביום שהקב\"ה יקים את כנסת ישראל מן העפר. דהיינו לעת הגאולה. ויום ההוא יהיה ידוע למעלה ולמטה. שכתוב, והיה יום אחד הוא יודע לה', ויום ההיא הוא יום של נקמות שעתיד הקב\"ה לנקם משאר עובדי עבודה זרה."],[2,"וכד קב\"ה וכו':","וכאשר הקב\"ה יעשה נקמות בשאר העמים עובדי כו\"מ, אז נאמר אוקיר אנוש מפז, זהו מלך המשיח, שיתעלה ויתכבד על כל בני העולם, וכל בני העולם יעבדו וישתחוו לפניו. שכתוב, לפניו יכרעו ציים וגו' מלכי תרשיש וגו'."],[3,"ת\"ח אע\"ג וכו':","בוא וראה, אף על פי שנבואה זו, דהיינו הפסוקים הנה יום ה' בא אכזרי וגו' אוקיר אנוש מפז וגו', נאמרה על בבל, שנאמר שם משא בבל, עם כל זה, על הכל נאמרה, כי אנו רואים שכתוב בפרשה זו, כי ירחם ה' את יעקב, וכתוב ולקחום עמים והביאום אל מקומם. הרי שאין נבואה הזו מיוחדת דוקא לבבל. ונראה שלבעלי הזהר היתה חלוקה אחרת בסדר הפרשיות כי בהספרים שלנו, מובא כתוב זה בהפרשה שלאחריה."],[4,"וה' המטיר על סדום:","זהו מדרגה של בית דין של מטה, שמקבל רשות מלמעלה. פירוש והויה, יורה, הוא, ובית דינו, (כנ\"ל ב\"א דף י\"ט אות י\"ב) \u0003הוא,\u0004 היינו ז\"א. \u0003ובית דינו\u0004 היינו הנוקבא, ושהיא בית דין של מטה. ומדרגה של בית דין שלמטה, היינו גזרת דינא, (הנ\"ל, באות רט\"ז) ואומר שעל כן כתוב וה', שגם ז\"א נזכר בפעולה זו, כי גזרת דינא לא פעלה הדין דסדום עד שקבלה רשות מלמעלה, דהיינו מז\"א, המרומז בהשם, והויה."],[4,"ר' יצחק אמר וכו':","רי\"א, שפעל הדין ברחמים שכתוב, מאת הויה מן השמים, והויה הוא שם הרחמים, כדי שימצא הדין ברחמים. דהיינו כמ\"ש לעיל (דף ס\"א אות ר\"ה) ואם תאמר מהו הרחמים כאן. ומשיב, שכתוב ויהי בשחת אלקים וגו' ויזכור אלקים את אברהם וגו'. ואח\"כ יצאו ממנו, מלוט, שתי אומות שלמות. וזכה שיצאו ממנו דוד ושלמה המלך."],[5,"חמי מה כתיב וכו':","ראה מה כתוב. ויהי כהוציאם אותם החוצה ויאמר המלט על נפשך וגו'. בוא וראה בשעה שהדין שורה בעולם, הנה למדנו, שאדם אינו צריך להמצא בשוק, כי מאחר שהדין שורה אינו משגיח להבדיל בין צדיק לרשע. וע\"כ אדם אינו צריך להמצא שמה. לכן נתבאר (לעיל פ' נח דף ע\"א אות ר') שמשום זה נסתתר נח בתיבה, כדי שלא יביט בעולם בשעה שהדין נעשה. וכן כתוב, ואתם לא תצאו איש מפתח ביתו עד בקר, דהיינו עד שהדין כבר נעשה, ומשום זה, כתוב, ויאמר המלט על נפשך אל תביט אחריך."],[6,"ר' יצחק ור' יהודה וכו':","ר\"י ור\"י היו הולכים בדרך. א\"ר יהודה לר' יצחק, הדין שעשה הקב\"ה בהמבול, והדין ושבסדום שניהם היו דינים של גיהנם, כי הרשעים שבגיהנם נידונים במים ובאש."],[7,"אמר ר' יצחק וכו':","אר\"י סדום נידונה בדינו של גיהנם, נשמע. שכתוב, וה' המטיר על סדום ועל עמורה גפרית ואש מאת ה' מן השמים, זה נידון מבחינת מים, וזה נידון מבחינת אש, וזה וזה הוא דינו של גיהנם, והרשעים שבגיהנם, בב' בחינות דינים אלו נדונים. כי יש גיהנם של שלג, שהוא מים. ויש גיהנם של אש."],[8,"א\"ל דינא וכו':","אמר לו, הדין של הרשעים בגיהנם הוא י\"ב חדשים. ושם הם מתלבנים, דהיינו שמטהרים שמה, ואחר כך הקב\"ה מעלה אותם מגיהנם ויושבים על פתחו של גיהנם, ורואים את הרשעים הנכנסים שם ודגים אותם, והם מבקשים רחמים עליהם ואחר כך, הקב\"ה מרחם עליהם, ומעלה אותם גם מפתחו של גיהנם, ומביאם אל המקום הנצרך להם. מיום ההוא ואילך, הגוף נשתכך בעפר. והנשמה יורשת מקומה כראוי לה."]],[[0,"","מַה כָּתוּב אַחֲרָיו? כִּי כוֹכְבֵי הַשָּׁמַיִם וּכְסִילֵיהֶם וְגוֹ'. שֶׁהֲרֵי מֵהַשָּׁמַיִם הִמְטִיר עֲלֵיהֶם אֵשׁ וְהֶעֱבִירָם מֵהָעוֹלָם. אַחַר כָּךְ מַה כָּתוּב? אוֹקִיר אֱנוֹשׁ מִפָּז וְגוֹ'. זֶה אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֶעֱלָה אוֹתוֹ עַל כָּל בְּנֵי הָעוֹלָם."],[1,"","רַבִּי יְהוּדָה הֵקִים אֶת הַפְּסוּקִים הַלָּלוּ בַּיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, שֶׁבְּאוֹתוֹ הַיּוֹם חָשְׁכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְחָשְׁכוּ שָׁמַיִם וְכוֹכָבִים. רַבִּי אֶלְעָזָר מְבָאֵר אֶת הַפְּסוּקִים הַלָּלוּ בַּיּוֹם שֶׁיָּקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת כְּנֶסֶת יִשְׂרָאֵל מֵהֶעָפָר, וְאוֹתוֹ יוֹם נוֹדָע לְמַעְלָה וּלְמַטָּה, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה'. וְאוֹתוֹ הַיּוֹם הוּא יוֹם נְקָמָה, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לִנְקֹם מִשְּׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת."],[2,"","וּכְשֶׁהַקָּדוֹשׁ בָּרוּךָ הוּא יַעֲשֶׂה נְקָמוֹת בִּשְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, אָז אוֹקִיר אֱנוֹשׁ מִפָּז - זֶה מֶלֶךְ הַמָּשִׁיחַ שֶׁיִּתְעַלֶּה וְיִתְכַּבֵּד עַל כָּל בְּנֵי הָעוֹלָם, וְכָל בְּנֵי הָעוֹלָם יַעַבְדוּ וְיִשְׁתַּחֲווּ לְפָנָיו, שֶׁכָּתוּב (תהלים עב) לְפָנָיו יִכְרְעוּ צִיִּים וְגוֹ' מַלְכֵי תַרְשִׁישׁ וְגוֹ'."],[3,"","בּא רְאֵה, אַף עַל גַּב שֶׁנְּבוּאָה זוֹ נֶאֶמְרָה עַל בָּבֶל - בַּכֹּל זֶה נֶאֱמַר. שֶׁהֲרֵי רָאִינוּ בְּפָרָשָׁה זוֹ שֶׁכָּתוּב כִּי יְרַחֵם ה' אֶת יַעֲקֹב, וְכָתוּב וּלְקָחוּם עַמִּים וֶהֱבִיאוּם אֶל מְקוֹמָם."],[4,"","וַה' הִמְטִיר עַל סְדם - זוֹ הַדַּרְגָּה שֶׁל בֵּית דִּין שֶׁלְּמַטָּה שֶׁנּוֹטֵל רְשׁוּת מִלְמַעְלָה. רַבִּי יִצְחָק אָמַר, שֶׁעוֹשֶׂה הַדִּין בְּרַחֲמִים, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם, כְּדֵי לְהִמָּצֵא דִין עִם רַחֲמִים. וְאִם תֹּאמַר מָה הָרַחֲמִים כָּאן? שֶׁכָּתוּב וַיְהִי בְּשַׁחֵת אֱלֹהִים אֶת עָרֵי הַכִּכָּר וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וְגוֹ'. וְאַחַר כָּךְ יָצְאוּ מִמֶּנּוּ שְׁתֵּי אֻמּוֹת שְׁלֵמוֹת וְזָכָה שֶׁיֵּצֵא מִמֶּנּוּ דָּוִד וּשְׁלֹמֹה הַמֶּלֶךְ."],[5,"","רְאֵה מַה כָּתוּב? וַיְהִי כְהוֹצִיאָם אֹתָם הַחוּצָה וַיֹּאמֶר בֹּא רְאֵה, בְּשָׁעָה שֶׁהַדִּין שׁוֹרֶה בָעוֹלָם, הֲרֵי לָמַדְנוּ שֶׁלֹּא צָרִיךְ לִבְנֵי אָדָם לְהִמָּצֵא בַשּׁוּק, בִּגְלַל שֶׁמִּכֵּיוָן שֶׁשּׁוֹרֶה דִין, לֹא מַבְחִין בֵּין זַכַּאי לְחַיָּב, וְלֹא צָרִיךְ לְהִמָּצֵא שָׁם. וַהֲרֵי לָמַדְנוּ שֶׁבְּסִבַּת זֶה נִסְגַּר נֹחַ בַּתֵּבָה וְלֹא נִמְצָא בָעוֹלָם בְּשָׁעָה שֶׁהַדִּין נַעֲשָׂה, וְכָתוּב (שמות יב) וְאַתֶּם לֹא תֵצְאוּ אִישׁ מִפֶּתַח בֵּיתוֹ עַד בֹּקֶר, עַד שֶׁיֵּעָשֶׂה הַדִּין. וּמִפְּנֵי כָּךְ, וַיֹּאמֶר הִמָּלֵט עַל נַפְשֶׁךְ אַל תַּבִּיט אַחֲרֶיךְ וְגוֹ'."],[6,"","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יִצְחָק, הַדִּין שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בַּמַּבּוּל וְהַדִּין שֶׁל סְדם, שְׁנֵיהֶם דִּינֵי הַגֵּיהִנֹּם הָיוּ, כִּי רִשְׁעֵי הַגֵּיהִנֹּם נִדּוֹנִים בָּאֵשׁ וּבַמַּיִם."],[7,"","אָמַר רַבִּי יִצְחָק, סְדם נִדּוֹנָה בְּדִין הַגֵּיהִנֹּם, שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ מֵאֵת ה' מִן הַשָּׁמָיִם. זֶה מִצַּד שֶׁל מַיִם וְזֶה מִצַּד שֶׁל אֵשׁ. זֶה וְזֶה הוּא דִּין הַגֵּיהִנֹּם, וְרִשְׁעֵי הַגֵּיהִנֹּם נִדּוֹנִים בִּשְׁנֵי הַדִּינִים הַלָּלוּ."],[8,"","אָמַר לוֹ, הַדִּין שֶׁל רִשְׁעֵי הַגֵּיהִנֹּם שְׁנֵים עָשָׂר חֳדָשִׁים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלֶה אוֹתָם מֵהַגֵּיהִנֹּם, וְשָׁם מִתְלַבְּנִים וְיוֹשְׁבִים לְשַׁעַר הַגֵּיהִנֹּם, וְרוֹאִים אוֹתָם רְשָׁעִים שֶׁנִּכְנְסוּ וְדָנִים אוֹתָם שָׁם, וְהֵם מְבַקְשִׁים עֲלֵיהֶם רַחֲמִים, וְאַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עֲלֵיהֶם וּמַכְנִיס אוֹתָם בַּמָּקוֹם שֶׁצָּרִיךְ לָהֶם. מֵאוֹתוֹ יוֹם וָהָלְאָה הַגּוּף שׁוֹכֵךְ בֶּעָפָר וְהַנְּשָׁמָה יוֹרֶשֶׁת מְקוֹמָהּ כָּרָאוּי לָהּ."]]],[["תָּא חֲזֵי דְּהָא אִתְּמָר דְּאֲפִילּוּ אִנּוּן בְּנֵי טוֹפָנָא לָא אִתְדָּנוּ אֶלָּא בְּאֶשָׁא וּמַיָּא. מַיָּיא קְרִירָן נַחֲתֵי מִלְּעֵילָא, וּמַיָּיא רְתִיחָן סָלְקֵי מִתַּתָּא כְּאֶשָׁא. וְאִתְדָּנוּ בִּתְרֵי דִינִין, בְּגִין דְּדִינָא דִּלְעֵילָא הָכִי הֲוָה, בְגִין כָּךְ בִּסְדוֹם גָּפְרִית וָאֵשׁ.","אָמַר לֵיהּ אִי יְקוּמוּן לְיוֹם דִּינָא. אָמַר לֵיהּ הָא אִתְּמָר. אֲבָל אִלֵּין דִּסְדוֹם וַעֲמוֹרָה לָא יְקוּמוּן, וּקְרָא אוֹכַח דִּכְתִיב, (דברים כ״ט:כ״ב) גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ לא תִזָּרַע וְלא תַצְמִיחַ וְגו'. אֲשֶׁר הָפַךְ יְיָ בְּאַפּוֹ וּבַחֲמָתוֹ. אֲשֶׁר הָפַךְ יְיָ, בְּעָלְמָא דֵּין. בְּאַפּוֹ, בְּעָלְמָא דְאָתֵי. וּבַחֲמָתוֹ, בְּזִמְנָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָּיא. אָמַר לֵיהּ תָּא חֲזֵי, כַּמָּה דְּאַרְעָא דִּלְהוֹן אִתְאֲבִיד לְעָלַם וּלְעָלְמֵי עָלְמַיָא, הָכִי נָמֵי אִתְאֲבִידוּ אִנּוּן לְעָלַם וּלְעָלְמֵי עָלְמַיָא.","וְתָּא חֲזֵי, דִּינָא דְּקוּדְשָׁא בְּרִיךְ הוּא דִּינָא לָקֳבֵל דִּינָא. אִנּוּן לָא הֲוָה תַּיְיבִין נַפְשָׁא דְּמִסְכֵּנָא בְּמֵיכְלָא וּבְמִשְׁתַּיָּא, אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא לָא אָתִיב לוֹן נַפְשַׁיְיהוּ לְעָלְמָא דְּאָתֵי.","וְתָּא חֲזֵי, אִנּוּן אִתְמְנָעוּ מִצְּדָקָה דְּאִקְרֵי חַיִּים, אוּף קוּדְשָׁא בְּרִיךְ הוּא מָנַע מִנַּיְיהוּ חַיִּים בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי. וְכַמָּה דְּאִנּוּן מָנְעוּ אָרְחִין וּשְׁבִילִין מִבְּנֵי עָלְמָא, הָכִי נָמֵי קוּדְשָׁא בְּרִיךְ הוּא מָנַע מִנַּיְיהוּ אוֹרְחִין וּשְׁבִילִין דְּרַחֲמֵי לְרַחֲמָא עֲלַיְיהוּ בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי.","רַבִּי אַבָּא אָמַר כֻּלְהוּ בְּנֵי עָלְמָא יְקוּמוּן, וִיקוּמוּן לְדִינָא וְעֲלַיְיהוּ כְּתִיב, (דניאל י״ב:ב׳) וְאֵלֶּה לַחֲרָפוֹת וּלְדֵרָאוֹן עוֹלָם. וְקוּדְשָׁא בְּרִיךְ הוּא מָארִי דְּרַחֲמִין אִיהוּ, כֵּיוָן דְּדָן לְהוּ בְּהַאי עָלְמָא וְקַבִּילוּ דִּינָא, לָא אִתְדָּנוּ בְּכֻלְהוּ דִּינִין.","אָמַר רַבִּי חִיָּיא כְּתִיב וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגו'. (קה א) מַהוּ בַּהֲפֹךְ אֶת הֶעָרִים אֲשֶׁר יָשַׁב בָּהֵן לוֹט. אֶלָא בְּכֻלְהוּ עֲבַד דִּיּוּרֵיהּ לוֹט, דִּכְתִיב וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדוֹם. (וכתיב אשר ישב בהן לוט. אלא ודאי בכלהו עבד דיוריה) וְלָא קַבִּילוּ לֵיהּ, בַּר דְּמֶלֶךְ סְדוֹם קַבִּיל לֵיהּ בִּסְדוֹם בְּגִינֵיהּ דְּאַבְרָהָם:"],[[0,"ת\"ח דהא וכו':","בוא וראה, כי למדנו, שאפילו בני המבול לא נדונו אלא באש ומים, מים קרים ירדו מלמעלה, ומים רותחים מלמטה, מן התהום, (כנ\"ל פ' נח דף כ\"א אות ס' ע\"ש) ונדונו בב' דינים. משום שהדין של מעלה כן הוא, בב' דינים, מים ואש, משום זה היה בסדום גפרית ואש. שגפרית הוא ממים, כנודע."],[1,"א\"ל אי יקומון וכו':","שאל אותו, אם יקומו אנשי סדום לעתיד ליום הדין. אמר לו הרי למדנו, אבל אלו של סדום ועמורה לא יקומו לדין, לעתיד בעת תחית המתים. והכתוב מוכיח, שכתוב גפרית ומלח שריפה כל ארצה וגו' אשר הפך ה' באפו ובחמתו, שפירושו, \u0003אשר הפך ה',\u0004 בעולם הזה. \u0003באפו,\u0004 בעולם הבא. \u0003ובחמתו,\u0004 בזמן שעתיד הקב\"ה להחיות המתים."],[2,"א\"ל ת\"ח,","כמו שארצם נאבד לעולם ולעולמי עולמים, כן נאבדו גם הם לעולם ולעולמי עולמים. ובוא וראה, הדין של הקב\"ה הוא דין כנגד דין, כלומר, מדה כנגד מדה, הם לא היו מחזירים נפש העני במאכל ומשקה כן גם הקב\"ה אינו מחזיר להם נפשם לעולם הבא. ומה שהזהר אומר לעולם הבא, הוא בדיוק, משום שלומד מארצם, וארצם נאבד רק במשך זמן שתא אלפי שני, שאז היא נקרא לעולם ולעולמי עולמים, אבל בגמר התקון תחזור סדום לקדמותה כמ\"ש (ביחזקאל ט\"ז) ואחותך סדום ובנותיה תשבנה לקדמותן. וע\"כ גם בנפשם אינו אומר בזמן התחיה, כנ\"ל בדבור הסמוך, לענין העמדה בדין, אלא אומר רק לעוה\"ב. שהוא נוהג רק במשך שתא אלפי שני."],[3,"ת\"ח אינון וכו':","ובוא וראה, הם נמנעו מליתן צדקה שנקראת חיים, אף הקב\"ה מנע מהם חיים בעולם הזה ובעולם הבא, וכמו שהם מנעו מבני העולם אורחות ושבילים שלהם, כן מנע הקב\"ה מהם אורחות ושבילים של הרחמים, מלרחם עליהם בעולם הזה ובעולם הבא."],[4,"ר' אבא אמר וכו':","רא\"א, כל בני העולם יקומו לתחית המתים ויקומו לדין, ועליהם, על אנשי סדום, כתוב, ואלה לחרפות ולדראון עולם. והקב\"ה בעל הרחמים הוא, כיון שדן אותם בעולם הזה, וקבלו הדין, אינם נידונים לעתיד בכל הדינים, אלא במקצתם."],[5,"א\"ר חייא כתיב וכו':","אר\"ח, כתוב, וישלח את לוט מתוך ההפכה וגו' ושואל, מהו בהפוך את הערים אשר ישב בהן לוט, והלא לא ישב אלא באחת מהן. ומשיב, אלא בכולם התישב לוט, שכתוב ולוט ישב בערי הככר, ויאהל עד סדום, אלא שלא קבלו אותו, חוץ ממלך סדום שקבלו בסדום, בשביל אברהם, שהחזיר לו הנפש והרכוש, שאבד במלחמת ד' המלכים."]],[[0,"","בֹּא רְאֵה, שֶׁהֲרֵי נֶאֱמַר שֶׁאֲפִלּוּ אוֹתָם בְּנֵי הַמַּבּוּל לֹא נִדּוֹנוּ אֶלָּא בְּאֵשׁ וּמַיִם. מַיִם קְרִירִים יָרְדוּ מִלְמַעְלָה, וּמַיִם רוֹתְחִים עָלוּ מִלְּמַטָּה כְּאֵשׁ. וְנִדּוֹנוּ בִּשְׁנֵי דִינִים, מִשּׁוּם שֶׁדִּין שֶׁל מַעְלָה כָּךְ הוּא, וְלָכֵן בִּסְדם גָּפְרִית וָאֵשׁ."],[1,"","אָמַר לוֹ, הַאִם יָקוּמוּ לְיוֹם הַדִּין? אָמַר לוֹ, הֲרֵי נִתְבָּאֵר, אֲבָל אֵלּוּ שֶׁל סְדם וַעֲמֹרָה לֹא יָקוּמוּ, וְהַכָּתוּב מוֹכִיחַ, שֶׁכָּתוּב (דברים כט) גָּפְרִית וָמֶלַח שְׂרֵפָה כָל אַרְצָהּ לֹא תִזָּרַע וְלֹא תַצְמִחַ וְגוֹ', אֲשֶׁר הָפַךְ ה' בְּאַפּוֹ וּבַחֲמָתוֹ. אֲשֶׁר הָפַךְ ה' - בָּעוֹלָם הַזֶּה. בְּאַפּוֹ - בָּעוֹלָם הַבָּא. וּבַחֲמָתוֹ - בִּזְמַן שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים. אָמַר לוֹ, בּא רְאֵה, כְּמוֹ שֶׁאַרְצָם אָבְדָה לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, גַּם כָּךְ הֵם אָבְדוּ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[2,"","וּבֹא רְאֵה שֶׁדִּין הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין כְּנֶגֶד דִּין. הֵם לֹא הֵשִׁיבוּ אֶת נֶפֶשׁ הֶעָנִי בְּמַאֲכָל וּמַשְׁקֶה - גַּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא לֹא הֵשִׁיב נַפְשָׁם לָעוֹלָם הַבָּא."],[3,"","וּבֹא רְאֵה, הֵם נִמְנְעוּ מִצְּדָקָה שֶׁנִּקְרֵאת חַיִּים - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא מָנַע מֵהֶם חַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וּכְמוֹ שֶׁהֵם מָנְעוּ דְּרָכִים וּשְׁבִילִים מִבְּנֵי הָעוֹלָם - כָּךְ גַּם הַקָּדוֹשׁ בָּרוּךְ הוּא מָנַע מֵהֶם דְּרָכִים וּשְׁבִילִים שֶׁל רַחֲמִים לְרַחֵם עֲלֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[4,"","רַבִּי אַבָּא אָמַר, כָּל בְּנֵי הָעוֹלָם יַעַמְדוּ וְיָקוּמוּ לַדִּין, וַעֲלֵיהֶם כָּתוּב (דניאל יב) וְאֵלֶּה לַחֲרָפוֹת לְדִרְאוֹן עוֹלָם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בַּעַל הָרַחֲמִים, כֵּיוָן שֶׁדָּן אוֹתָם בָּעוֹלָם הַזֶּה וְקִבְּלוּ דִין, לֹא נִדּוֹנוּ בְּכָל הַדִּינִים."],[5,"","אָמַר רַבִּי חִיָּיא, כָּתוּב וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה וְגוֹ'. מַהוּ בַּהֲפֹךְ אֶת הֶעָרִים אֲשֶׁר יָשַׁב בָּהֵן לוֹט? אֶלָּא בַּכֹּל עָשָׂה דִיּוּרוֹ לוֹט, שֶׁכָּתוּב וְלוֹט יָשַׁב בְּעָרֵי הַכִּכָּר וַיֶּאֱהַל עַד סְדם. (וכתוב אשר ישב בהן לוט, אלא ודאי שבכלם עשה את דיורו) וְלֹא קִבְּלוּ אוֹתוֹ, חוּץ מִמֶּלֶךְ סְדם שֶׁקִּבֵּל אוֹתוֹ בִּסְדם מִשּׁוּם אַבְרָהָם."]]],[["\u0003סִתְרֵי תּוֹרָה\u0004 תּוֹסֶפְּתָּא קְטוּרֵי רָמָּאי, הוּרְמְנֵי (עיין סוף הספר סי' ב) דִּבְדוּרֵי. (נ\"א דבורירי ונ\"א דבורייני) חַכִּימִין בְּסֻכְלְתָּנוּ, יִסְתַּכְּלוּן לְמִנְדַע, בְּשַׁעֲתָּא דְּרֵישָׁא חִוָּורָא אַתְּקִין כֻּרְסְיָיא עַל גַּבֵּי סָמְכִין דְּאַבְנִין דְּמַרְגְּלִיטָן טָבָן.","בֵּין אִנּוּן אַבְנִין אִיתּ חַד מַרְגָּלִיטָא שַׁפִּירָא בְּחֵיזוּ יָאָה בְּרֵיוָא קוּמְטְרָא דְּקַנְטָרָא (נ\"א דקיטרא) דִּמְלַהֲטָא בְּע' גְּוָונִין, אִנּוּן ע' גְּוָונִין מְלַהֲטָן לְכָל סְטַר.","אִלֵּין ע' מִתְּפָּרְשָׁאן מִגּוֹ ג' גְּוָונִין. אִלֵּין זִיקִין בְּזִיקִין דִּנְצִּיצִּין לְד' סִטְרֵי עָלְמָא, הָכָא אִיתָּא זִיקָא תַּקִּיפָּא דִּסְטַר שְׂמָאלָא דְּאִתְּאַחִיד בִּשְׁמַיָא. אִנּוּן גְּוָונִין שִׁבְעִין (דניאל ז׳:י׳) דִּינָא יָתִּיב וְסִפְּרִין פְּתִּיחוּ.","מֵהָכָא נָפְּקֵי גִירִין וּסְיָיפִּין וְרוֹמְחִין וְאֶשָׁא דְּקוּסְטְרָא. וְאִתְּאַחִיד אֶשָׁא תַּקִּיפָּא דְּנָפְּקָא מִשָׁמַיִם בֵּיהּ, וְכַד אִתְּאַחַד אשא עִלָּאָה בְּאִלֵּין דִּלְתַּתָּא, לֵיתּ מַאן דְּיָכִיל לְאִתְּבַּר רוּגְזָא וְדִינָא.","עַיְינִין לָהֲטִין כְּטִיסִין דְּנוּרָא, נָחִיתּ בְּהוּ לְעָלְמָא. וַוי מַאן דְּאִעָרַע בֵּיהּ, חֲגִיר חַרְצִּין (ס\"א חרבין), אִיהוּ חַרְבָּא שִׁנְּנָא בִּידֵיהּ, לָא חָיִיס עַל טַב וְעַל בִּישׁ. דְּהָא (ס\"א פסקא) פִּתְּקָא דְּאִנּוּן שִׁבְעִין בִּרְשׁוּ דְּאִתְּאַחִיד הַהוּא סִטְרָא דִשְׁמַיָא נָחִיתּ בִּידָא שְׂמָאלָא בְּכַמָּה דִּינִין,","אִתְּהַפֵּךָ בְּכַמָּה גְּוָונִין, הֲפּוּךָ בְּכָל יוֹמָא, אִיהוּ אִקְרֵי כְּרֻם זְלֻּתּ דִּמְתַּקְּנָא לְגַבֵּי בְּנֵי אָדָם. כָּל גְּוָונִין דִּכְלֵי זַעֲמוֹ דְּקוּדְשָׁא בְּרִיךָ הוּא בֵּיהּ אִתְּחַזְּיָין. וְאִנּוּן יָתְּבִין בְּרוּמֵי דְּעָלְמָא, וּבְנֵי נָשָׁא בְּסִכְלוּתָּא דִלְהוֹן לָא מַשְׁגְּחֵי בְּהוֹן.","גָּפְּרִיתּ וָאֵשׁ הִתּוּכָא דְּמַיָא וְאֶשָׁא דְּמִתְּהַתְּכֵי מִן שְׁמַיָא אִתְּאַחֲדוּ דָּא בְּדָא וּנְחַתּ עַל סְדוֹם. וַוי לְחַיָּיבַיָא דּלא מַשְׁגִּיחִין עַל יְקָרָא דְמָארֵיהוֹן:","א. עֲשָׂרָה שְׁמָהָן גְּלִיפָּן בְּהוּרְמְנוּתָּא דְמַלְכָּא. (פירוש השם במלואו עשר אותיות יו\"ד ה\"א וי\"ו ה\"א). ב. עשר אִנּוּן וְסָלְקִין לְחוּשְׁבַּן סַגֵּי. (פי' יוד עולה כ', יוד הא עולה כ\"ו, יוד (נ\"ל הה וו) הא ויו עולה מ\"ב, י' יד' יד' ידוד' עולה ע\"ב). ג. שִׁבְעִין (הם ע\"ב ונקראים ד' מחנות שכינה והם למטה ממלכות). גַּוְונָן מְלַהֲטֵי לְכָל סְטַר. נַפְּקֵי מִגּוֹ שְׁמָהָן דְּאִגְלִיף רָזָא דְּע' שְׁמָהָן דְּמַלְאָכַיָיא. דְּאִנּוּן בְּרָזָא דִשְׁמַיָא.","וְאִנּוּן מיכאל גּבריאל רפּאל נוריאל. קמ\"ץ \"קדומיאל \"מלכיאל \"צּדקיאל. פּתּ\"ח \"פּדאל \"תּומיאל \"חשדיאל. צּר\"י \"צּדקיאל \"רזיאל \"יופּיאל. סגו\"ל \"סטוטריה \"גזריאל \"ותּריאל נ\"א ורדיא\"ל \"למואל. חר\"ק \"רהטיאל \"חזקיאל \"קדשיאל. שׁב\"א \"שמעאל \"ברכיאל (נ\"א שכניאל ונ\"א ברקיא\"ל) \"אהיאל. חל\"ם חניא\"ל \"להדיאל \"מחניאל. (נ\"א ח\"ניאל ל\"עדיאל מ\"לכיאל). \"עניאל ענאל אהניאל רחמיאל עזריאל (נ\"א ש\"בנאל ר\"ומיאל ק\"דומיאל. שר\"ק. חכמיאל רמיאל קרשיאל. חר\"ק)","סנניה ודרגזיה רסיסיאל דומיאל","חוניאל \"זכריאל \"ואריאל \"ה\"ינאל ד\"נדאל ג\"דיאל ב\"דאל א\"נפּיאל ועדי\"אל, אדנ\"י עַל כֻּלְהוּ. ד (פירוש כשע\"ב מלאכים מתחברין במלכות אז נקרא מלכות הוא ובית דינו בלשון וה').","כַּד מִתְּחַבְּרָן כֻּלְהוּ כְּחֲדָא בְּרָזָא חָדָא בְּחֵילָא עִלָּאָה, כְּדֵין אִקְרֵי וידוד כֹּלָּא בִּכְלָלָא חָדָא. מֵאֵתּ יְיָ מִן הַשָׁמַיִם, שְׁמָא קַדִּישָׁא דְּאִתְּגְּלַף בְּע' שְׁמָהָן אָחֳרָנִין רָזָא דְּשָׁמָיִם. ואִלֵּין אִנּוּן שִׁבְעִין דְּשָׁלְטִין עַל אִלֵּין ע' דִּינִין רָזָא דְּיהו\"ה, ואִלֵּין שִׁבְעִין שְׁמָהָן בִּקְדוּשָׁה יהו\"ה שָׁמָיִם. ה (פירוש שם של ע\"ב גשרים היוצא מפסוק ויסע ויבא ויט אלו הם נקראים שמים, ואותם ע\"ב מלאכים של מטה במלכו\"ת מקבלים מע\"ב של מעלה, ונוטלין מהן).","אִלֵּין נָטְלִין מֵאִלֵּין וְידוד. ו (פירוש מלכות מתפארת). נָטִיל מֵאֵתּ ידוד דָּא מִן דָּא. ז (פירוש סוד של אותן ע\"ב שמות הוא שם ידוד, והוא הרוכב עליהן כנשמה לגוף). ואִלֵּין תַּלְיָין מֵאִלֵּין, תַּתָּאִין בְּעִלָּאִין, וְכלָּא קִשׁוּרָא חָדָא. וּבְהַאי קוּדְשָׁא בְּרִיךָ הוּא אִשְׁתְּמוֹדָע בִּיקָרֵיהּ. ח (פירוש ע\"ב מלאכים של מטה מתחבים בע\"ב שמות של מעלה הנקראים שמים). שָׁמַיִם דְּאִנּוּן ע' רָזָא ידוד, דָּא אִיהוּ בְּרָזָא דְּשִׁבְעִין וּתְּרֵין שְׁמָהָן ואִלֵּין אִנּוּן דְּנָפְּקֵי מִן וַיִּסַּע וַיָּבֹא וַיֵּט.","וה\"ו יל\"י סי\"ט על\"ם מה\"ש לל\"ה אכ\"א כה\"תּ הז\"י אל\"ד לא\"ו הה\"ע. חֵלֶק רִאשׁוֹן בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד יז\"ל מב\"ה הר\"י הק\"ם לא\"ו כל\"י לו\"ו פּה\"ל נל\"ךָ יי\"י מל\"ה חה\"ו. חֵלֶק שֵׁנִי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד נתּ\"ה הא\"א יר\"תּ שא\"ה רי\"י או\"ם לכ\"ב וש\"ר יה\"ו לה\"ח כו\"ק מנ\"ד. חֵלֶק שְׁלִישִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד אנ\"י חע\"ם רה\"ע יי\"ז הה\"ה מי\"ךָ וו\"ל יל\"ה סא\"ל ער\"י עש\"ל מי\"ה. חלק רְבִיעִי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד וה\"ו דנ\"י הח\"ש עמ\"ם ננ\"א ני\"תּ מב\"ה פּו\"י נמ\"מ יי\"ל הר\"ח מצּ\"ר. חֵלֶק חֲמִישִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם וָעֶד ומ\"ב יה\"ה ענ\"ו מח\"י דמ\"ב מנ\"ק אי\"ע חב\"ו רא\"ה יב\"מ הי\"י מו\"ם, חֵלֶק שִׁשִׁי בָּרוּךָ שֵׁם כְּבוֹד מַלְכוּתּוֹ לְעוֹלָם ועֶד.","וְאִלֵּין אִנּוּן שִׁבְעִין שְׁמָהָן דְּשָׁלְטִין עַל שִׁבְעִין דַּרְגִּין תַּתָּאִין רָזָא וידוד. אִלֵּין שִׁבְעִין שְׁמָהָן ידוד רָזָא דְאִקְּרֵי שָׁמָיִם. שִׁבְעָא רְקִיעִין אִנּוּן דְּסָלְקִין לְשִׁבְעִין שְׁמָהָן שְׁמָא קַדִּישָׁא, וְדָא אִיהוּ וַידוד הִמְטִיר. מֵאֵתּ ידוד מִן הַשָׁמָיִם."],[[0,"ת ו ס פ ת א. קטורי רמאי:","קשרים הרמים, היינו הצדיקים שנר\"ן שלהם מקושרים ברוממות הקב\"ה, (כנ\"ל פ' נח דף כ\"ג אות ס\"ד) שרים המנפצים, את כחות הסטרא אחרא. חכמי התבונה, יתבוננו לדעת. \u0003קטורי\u0004 פירושו קשרים. \u0003רמאי\u0004 גבוהים ורמים. \u0003הורמני,\u0004 פירושו שרים, מוציאי לפועל פקודות המלך. כמו שאמרו (עירובין נ\"ט) כיון דשכיחי גבי הרמנא. \u0003דבדורי,\u0004 פירושו המנפצים, כי, ואיש כלי מפצו בידו, מתרגם, וגבר מן \u0003בדוריה\u0004 בידיה, (יחזקאל ט' ב') וכן ונפצתי בך גוים מתרגם, \u0003ואבדר\u0004 בך עממין. (ירמיה נ\"א כ') ודרך הסתרי תורה הוא לפתוח המאמר בפניה אל חכמי הסוד שישכילו בהדברים."],[0,"בשעתא דרישא חוורא,","בשעה שראש הלבן, היינו א\"א ששער רישיה כעמר נקי, \u0003אתקין כרסייא על גבי סמכין דאבנין דמרגליטן טבן,\u0004 תקן הכסא, הוא בינה, על עמודים של אבנים טובות ומרגליות, דהיינו חסד גבורה ת\"ת דז\"א והנוקבא, שהם ד' רגלי הכסא, (כנ\"ל דף ו' ד\"ה וז\"ש ע\"ש) שהיא בינה."],[1,"בין אינון אבנין, אית חד מרגליטא.","בין אלו אבנים, יש מרגלית אחת, היינו הנוקבא דז\"א, \u0003שפירא בחיזו יאה בריוא,\u0004 טובת מראה ויפת תואר. \u0003קומטרא דקיטרא דמלהטא בע' גוונין\u0004 מקום קיבוץ העשן והאש, הלוהט בשבעים פנים. היינו גזרת דינא, (המובא לעיל דף ס\"ד אות רט\"ז) שפירושו הארת השמאל שבנוקבא, מטרם התכללותה בימין. שאז היא מקום הדינים בסוד אש לוהט וקיטור הכבשן. \u0003קומטרא,\u0004 פירושו מקום קבוץ של בגדים ותכשיטים וכדומה. כי על מלתחה, שהוא מקום קבוץ בגדים, מתרגם קמטריא (מלכים ב' יוד כ\"ב). קיטרא פירושו עשן, מלשון קיטור הכבשן. וענין ע' פנים מבאר לפנינו. \u0003אינון ע' גוונין מלהטן לכל סטר\u0004 אלו ע' פנים לוהטות לכל צד. היינו לד' רוחות העולם שהם חו\"ב תו\"מ."],[2,"אלין ע' מתפרשאן מגו ג' גוונין,","אלו ע' פנים מתבארים מן ג' גוונים, שהם לבן, אדום, ירוק. וגוון המלכות שהוא שחור, אין שם. \u0003אלין זיקין בזיקין דנציצין לד' סטרי עלמא,\u0004 אלו זיקים נכללים בזיקים שמנוצצים לד' רוחות העולם שהם חו\"ב תו\"מ, כלומר, אע\"פ שאלו ע' פנים אין בהם אלא ג' פנים אריה שור נשר שה\"ס חג\"ת, וחסרים פני אדם, שה\"ס הנוקבא, עם כל זה. כשנכללים זה מזה נכלל הנוקבא ג\"כ עם החג\"ת, ויש ג' פנים בכל אחד, ואפילו בהנוקבא. באופן שיש ג' פנים בפני אריה, וג' פנים בפני שור, וג' פנים בפני נשר. וג' פנים בפני אדם. שהם י\"ב פנים. שג' פנים יש בכל אחד מחו\"ג תו\"מ, ופני אדם חסר בכל אחד מחו\"ג תו\"מ. וז\"ש \u0003אלין ע' מתפרשאן מגו ג' גוונין,\u0004 וחסר גוון הנוקבא, אבל \u0003אלין זיקין\u0004 נכללים \u0003בזיקין דנציצין לד' סטרי עלמא.\u0004 והם על כן י\"ב, דהיינו ד' סטרי עלמא חו\"ב תו\"מ שיש בכל אחד ג' גוונין. \u0003הכא איתא זיקא תקיפא דסטר שמאלא,\u0004 כאן יש ניצוץ חזק מצד שמאל, \u0003דאתאחיד בשמיא,\u0004 הנאחז בשמים שהוא ז\"א. פירוש. שמכח הארת ניצוץ הזה נמצא כל בחינה ובחינה מי\"ב הבחינות, מקבלת מז\"א ששה קצוות, שהם חג\"ת נה\"י."],[2,"","ונתבאר ג' בחינות בע' פנים הללו: א) שעיקרם הם רק ג' גוונים חו\"ב ות\"ת, וחסר שם הנוקבא. ב) שמבחינת התכללותם זה בזה, יש גם בהנוקבא אלו ג' בחינות, ומכאן נעשו אלו ג' גוונים לי\"ב בחינות. ג) התאחדותם בז\"א, וכל בחינה מי\"ב בחינות מקבלת ו\"ס חג\"ת נה\"י. ומכאן נעשו למספר ע' בחינות, כי שש פעמים י\"ב הם ע\"ב. ועקרם רק ע', בסוד ע' סנהדרין וב' עדים. ומאלו ע' פנים נמשכים ע' מלאכים כמ\"ש לפנינו. שהם בית דינה של המלכות. \u0003אינון גוונין שבעין, דינא יתיב וספרין פתיחו:\u0004 אלו שבעים בחינות, הדין שבהם נשקט והספרים פתוחים כלומר, אע\"פ שהספרים, שבהם כתוב הדין, פתוחים ונראים לכל, עם כל זה, הדין נשקט, ואינו פועל כלום. וה\"ס מלכות דמדת הדין הגנוזה בהם, בסוד, \u0003זכי הא טוב:\u0004 (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב)."],[3,"מהכא נפקי, גירין וסייפין ורומחין ואשא דקוסטרא,","מכאן יוצאים, חיצים, וחרבות, ורמחים, ואש של המגדל. פירוש. כי נתבאר לעיל שג' הגוונים, הנמשכים מג' נקודות חולם שורק חירק, נכללו בכל הד' ואפילו בהנוקבא. וע\"כ כשהיא בדינין דהארת שמאל, נמשכים מכח החולם שבה בחינת \u0003חצים,\u0004 שהורגים מרחוק, וכן מעליית המלכות לבינה, נחצה הבינה, ונפלה ממנה, חציה התחתונה ואור הג\"ר נתרחק ממנה. ובכונה עשתה כן הבינה, בסוד הנשר שהוא רחמני על בניו ואומר מוטב שיכנס החץ בי, ואל יכנס בבני. (כנ\"ל בכמה מקומות) מכח נקודת השורק שבה נמשכים \u0003חרבות,\u0004 שהורג מקרוב, וכן כל הדינין שבשורק נמשכים מכח קרבת אור הג\"ר דחכמה כנודע. ומכח נקודת החירק שבה, נמשכים \u0003רמחים.\u0004 שכוללים שניהם, שהורג מקרוב כמו חרב, וכן זורקים אותו ומכה מרחוק כמו חץ. כמ\"ש (שמואל י\"ח יא) ויטל שאול את החנית וגו'. כי הוא כולל את שניהם. וכללות ג' דינים הללו, עושה בהנוקבא בחינת אש לוהטת שהיא נקרא \u0003אשא דקוסטרא.\u0004 האש שבהמגדל, שהיא הנוקבא. \u0003ואתאחיד אשא תקיפא, דנפקא משמים, ביה:\u0004 ונאחז בה, בהנוקבא, אש חזקה היוצאת משמים שה\"ס ז\"א. \u0003וכד אתאחד אשא עלאה באלין דלתתא,\u0004 וכשנאחז אש העליונה, דהיינו הדינים שבז\"א. באלו שלמטה, דהיינו בע' דינין הנ\"ל של הנוקבא, \u0003לית מאן דיכיל למתבר רוגזא ודינא,\u0004 אין עוד מי שיוכל לשבור את הכעס ואת הדין של הדינים שבנוקבא."],[4,"עיינין להטין כטיסין דנורא,","העינים לוהטות כלשונות אש. \u0003נחית בהו לעלמא,\u0004 ז\"א יורד עמהם לעולם, היינו בעינים לוהטות, ורומז בזה לסו\"ה ארדה נא ואראה וגו'. \u0003ווי מאן דאערע ביה חגיר חרבין,\u0004 ווי למי שיפגוש בו כשהוא חגור בחרבות, דהיינו הדינים הנמשכים מבחינת נקודת השורק, הנקראים חרבות כנ\"ל. \u0003איהו חרבא שננא בידיה, לא חיים על טב ועל ביש,\u0004 הוא, יש לו בידו חרב חדה, ואינו מרחם על טוב ועל רע. \u0003דהא פסקא דאינון שבעין, ברשו דאתאחיד ההוא סטרא דשמיא נחית בידא שמאלא.\u0004 כי הפסק דין של אותם שבעים גוונים הנ\"ל, יורד ביד שמאל, ברשות היחוד שנתאחד בו צד השמים, שאז \u0003לית מאן דיכיל לאתבר רוגזא,\u0004 כנ\"ל."],[5,"בכמה דינין אתהפך, בכמה גוונין הפוך בכל יומא:","בכמה דינין הוא מתהפך, בכל יום מתהפך לכמה גוונים. דהיינו שמקבלים כל פעם צורה אחרת, כנ\"ל (בראשית א' דף ע\"ז אות קי\"ט) שאומר שם ומתהפכי תדיר לזמנין נוקבי ולזמנין גוברי, לזמנין רוחין, לזמנין עירין קדישין, ע\"ש בהסולם. \u0003כל גוונין דכלי זעמו דקב\"ה ביה אתחזיין.\u0004 כל מיני הדינים הנמצאים בכלי זעמו של הקב\"ה נראים בו. ואנון \u0003יתבין ברומי דעלמא.\u0004 ואלו הדינים יושבים ברומו של עולם, \u0003ובני נשא בסכלותא דלהון, לא משגחי בהון.\u0004 ובני אדם מחמת סכלותם, אינם מסתכלים בהם."],[6,"גפרית ואש, התוכא דמיא ואשא, דמתהתכי מן שמיא אתאחדו דא בדא ונחת על סדום.","גפרית ואש, פירושו, הפסולת של מים והפסולת של אש, שהותכו מן שמים, ונתאחדו זה בזה, וירדו על סדום. כי שמים, ה\"ס אש ומים, ימין ושמאל,שנתחברו בז\"א ושמים אותיות אש ומים, כנודע, ועל ידי עונות התחתונים נפרדו ונעשו מחלוקת בין אש ומים, שה\"ס ב' הקוין ימין ושמאל, ונבחן שהם הותכו, ופסולת הימין ה\"ס גפרית, ופסולת השמאל ה\"ס אש. ואלו ב' מיני הדינים שנתחברו, הפכו את סדום."],[7,"עשרה שמהן גליפן בהורמנותא דמלכא,","עשרה שמות תקונים, ברשות המלך. דהיינו עשר ספירות. \u0003עשר אינון, וסלקין לחושבן סני,\u0004 הם עשר ספירות, כמ\"ש בספר יצירה עשר ולא ט' ולא י\"א, ועם כל זה עולים לחשבון גדול, דהיינו לחשבון ע\"ב שמות כמו שמבאר לפנינו. \u0003שבעין גוונן מלהטי לכל סטר, נפקי מגו שמהן,\u0004 שבעים גוונין הנ\"ל הלוהטים לכל צד יוצאים מתוך השמות, דהיינו מן ע\"ב שמות. \u0003דאגליף רזא דע' שמהן דמלאכיא דאינון ברזא דשמיא,\u0004 ששבעים גוונין נחקקו ונעשו לסוד ע' שמות של המלאכים, שהם בסוד השמים, כלומר, שחם יוצאים מע\"ב שמות של השמים, שהוא ז\"א. ויש בהם ג' בחינות כנגד ג' קוין דז\"א. וע\"כ הנמשכים מקו ימין מסודרים בראשי תיבות של א\"ב ביושר. והנמשכים מקו שמאל מסודרים בר\"ת של תשר\"ק צפע\"ס, שהם א\"ב למפרע המורים על דין. והנמשכים מקו אמצעי מסודרים בר\"ת של תשע הנקודות קמץ, פתח, צירי, סגול, שבא, חלם, חירק, שרק, ושורק שמכנים אותו, מלאפום."],[11,"כד מתחברן כלהו וכו':","כאשר מתחברים כולם כאחד, בסוד אחד, בכחו של העליון, דהיינו ז\"א, אז נקרא \u0003והויה,\u0004 שפירושו הכל בכלל אחד, דהיינו ז\"א ונוקבא וע' המלאכים שמתחתיה. \u0003מאת הויה מן השמים,\u0004 היינו שם הקדוש שנחקק בע' שמות אחרים שבסוד השמים, שהוא ז\"א שהוא שם ע\"ב שבמוחין דז\"א, כמ\"ש לפנינו. ועקרו הוא \u0003ע'.\u0004 ואלו, הם ע' דז\"א השולטים על ע' דינין דנוקבא הנ\"ל באות רע\"ד דמלהטי לכל סטר. שהם סוד של \u0003והויה\u0004 ואלו ע' שמות שבקדושה, דהיינו שבמוחין דז\"א, ה\"ס \u0003הויה\u0004 בלי \u0003ו',\u0004 ונקרא \u0003שמים.\u0004"],[12,"אלין נטלין מאלין וכו':.","אלו, ע' דינים שבנוקבא מקבלים מאלו, דהיינו מן \u0003ע'\u0004 שמות דז\"א. \u0003והויה\u0004 שהוא כולל ע' דינין מקבל מן \u0003הויה\u0004 שה\"ס ע' שמות דז\"א. זה מן זה. ואלו תלוים באלו דהיינו התחתונים שהם ע' דינים, תלוים בעליונים שהם ע' שמות דז\"א. והכל קשר אחד. כלומר, שמתקשרים זה בזה ומאירים בבת אחת. ובזה מתגלה הקב\"ה בכבודו. מה שאמרנו ששמים הוא \u0003ע'\u0004 וסוד \u0003הויה\u0004 בלי \u0003ו',\u0004 זה הוא בסוד \u0003ע\"ב שמות\u0004 היוצאים מג' הפסוקים: \u0003ויסע, ויבא, ויט.\u0004 הנאמרים בפרשת קריעת ים סוף."],[14,"ואלין אינון שבעין שמהן וכו':","ואלו הם ע' השמות, השולטים על ע' מדרגות התחתונות שהם סוד \u0003והויה\u0004 עם \u0003ו',\u0004 ואלו הם ע' השמות שה\"ס הויה בלי \u0003ו'.\u0004 בסוד שנקרא שמים, דהיינו ז\"א. ז' רקיעים הם, דהיינו ז\"ס דז\"א הנקרא שמים, שכל אחד כלול מעשר, שעולים לע' שמות של השם הקדוש, הויה, וזה הוא סוד הכתוב, \u0003והויה המטיר.\u0004 שה\"ס ע' דינין דנוקבא, \u0003מאת ה' מן השמים\u0004 שה\"ס ע' השמות של השם הקדוש הויה."]],[[0,"","קְשָׁרִים רָמִים, שָׂרִים הַמְפַזְּרִים (נ\"א: המבררים, ונ\"א המנפצים), חֲכָמִים בַּשֵּׂכֶל, יִסְתַּכְּלוּ לָדַעַת, בְּשָׁעָה שֶׁהָרֹאשׁ הַלָּבָן תִּקֵּן כִּסֵּא עַל גַּבֵּי הָעַמּוּדִים עַל אֲבָנִים שֶׁל מַרְגָּלִיּוֹת טוֹבוֹת."],[1,"","בֵּין אוֹתָם הָאֲבָנִים יֵשׁ מַרְגָּלִית אַחַת בְּמַרְאֶה יָפֶה וּבְתֹאַר כִּסּוּי הַכְּלִי (של העשן) שֶׁלּוֹהֵט בְּשִׁבְעִים גְּוָנִים. אוֹתָם שִׁבְעִים גְּוָנִים לוֹהֲטִים לְכָל צַד."],[2,"","אֵלֶּה הַשִּׁבְעִים נִפְרָדִים מִתּוֹךְ שְׁלֹשָׁה גְוָנִים. אֵלֶּה רוּחוֹת בְּרוּחוֹת שֶׁנּוֹצְצוֹת לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. כָּאן יֵשׁ רוּחַ חֲזָקָה שֶׁל צַד שְׂמֹאל שֶׁנֶּאֱחָז בַּשָּׁמַיִם. אוֹתָם שִׁבְעִים גְּוָנִים הַדִּין יוֹשֵׁב וְהַסְּפָרִים נִפְתָּחִים."],[3,"","מִכָּאן יוֹצְאִים חִצִּים וַחֲרָבוֹת וּרְמָחִים וְאֵשׁ שֶׁל הַמִּגְדָּל. וְנֶאֱחֶזֶת אֵשׁ חֲזָקָה שֶׁיּוֹצֵאת מֵהַשָּׁמַיִם בּוֹ. וּכְשֶׁנֶּאֱחֶזֶת הָאֵשׁ הָעֶלְיוֹנָה בְּאֵלּוּ שֶׁלְּמַטָּה, אֵין מִי שֶׁיָּכוֹל לִשְׁבֹּר אֶת הָרֹגֶז וְהַדִּין."],[4,"","עֵינַיִם לוֹהֲטוֹת כְּמוֹ שַׁלְהָבוֹת שֶׁל אֵשׁ יוֹרֵד בָּהֶם לָעוֹלָם. אוֹי לְמִי שֶׁפּוֹגֵשׁ אוֹתוֹ, חֲגוּר מָתְנַיִם (חרבות) הוּא, וְחֶרֶב שְׁנוּנָה בְּיָדוֹ. לֹא מְרַחֵם עַל טוֹב וְלֹא עַל רַע. שֶׁהֲרֵי (הפסק) הַפֶּתֶק, שֶׁהֵם שִׁבְעִים בִּרְשׁוּת שֶׁנֶּאֱחָז אוֹתוֹ צַד שֶׁל הַשָּׁמַיִם, יוֹרֵד בְּיַד שְׂמֹאל בְּכַמָּה דִינִים."],[5,"","מִתְהַפֵּךְ בְּכַמָּה גְוָנִים, הוֹפֵךְ בְּכָל יוֹם. הוּא נִקְרָא כְּרֻם זֻלֻּת שֶׁמְּתֻקָּן לִבְנֵי אָדָם. כָּל הַגְּוָנִים שֶׁל כְּלֵי הַזַּעַם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִרְאִים בּוֹ. וְהֵם יוֹשְׁבִים בְּרוּם הָעוֹלָם, וּבְנֵי אָדָם בְּסִכְלוּתָם לֹא מַשְׁגִּיחִים בָּהֶם."],[6,"","גָּפְרִית וָאֵשׁ - הִתּוּךְ שֶׁל מַיִם וְאֵשׁ שֶׁנִּתָּכִים מֵהַשָּׁמַיִם נֶאֶחְזוּ זֶה בָּזֶה וְיָרְדוּ עַל סְדם. אוֹי לָרְשָׁעִים שֶׁאֵינָם מַשְׁגִּיחִים עַל כְּבוֹד רִבּוֹנָם."],[7,"","א, עֲשָׂרָה שֵׁמוֹת חֲקוּקִים בִּרְצוֹן הַמֶּלֶךְ. ב: עֲשָׂרָה הֵם וְעוֹלִים לְחֶשְׁבּוֹן גָּדוֹל. ג: שִׁבְעִים גְּוָנִים לוֹהֲטִים לְכָל צַד. יוֹצְאִים מִתּוֹךְ שֵׁמוֹת שֶׁחֲקוּקִים סוֹד שֶׁל שִׁבְעִים שְׁמוֹת מַלְאָכִים שֶׁהֵם בְּסוֹד הַשָּׁמַיִם."],[8,"","וְהֵם, ' מִיכָאֵל, גַּבְרִיאֵל, רְפָאֵל, נוֹרִיאֵל. קָמַ\"ץ - \"קדומיאל \"מלכיאל \"צדקיאל. פַּתָּ\"ח - \"פדאל \"תומיאל \"חשדיאל. צֵרֵ\"י - \"צדקיאל \"רזיאל \"יופיאל. סֶגּוֹ\"ל - \"סטוטריה \"גזריאל \"ותריאל (נ\"א: ו\"רדיאל) \"למואל. חִרֵ\"ק - \"חזקיאל \"רהטיאל \"קדשיאל. שְׁבָ\"א - \"שמעאל \"ברכיאל (נ\"א: ש\"כניאל ונ\"א ב\"רקיאל) \"אהיאל."],[9,"","חֹלָ\"ם - \"חניאל \"להדיאל \"מחניאל (נ\"א: ח\"ניאל ל\"עדיאל מ\"לכיאל). \"עניאל ענאל אהניאל רחמיאל עזריאל (נ\"א ש\"בנאל ר\"ומיאל ק\"דומיאל שר\"ק, ח\"כמיאל ר\"מיאל ק\"רשיאל חר\"ק)"],[10,"","סנניה ודרגזיה רסיסיאל דומיאל \"חוניאל \"זכריאל \"ואריאל \"ה\"ינאל ד\"נדאל ג\"דיאל ב\"דאל א\"נפיאל ועדי\"אל אדנ\"י עַל כֻּלָּם. ד (פירוש, כשע\"ב מלאכים מתחברים במלכות, אז נקרא מלכות הוא ובית דינו בלשון וה',)"],[11,"","כְּשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד בְּסוֹד אֶחָד בְּכֹחַ עֶלְיוֹן אָז נִקְרָא ויהוה, הַכֹּל בִּכְלַל אֶחָד. מֵאֵת ה' מִן הַשָּׁמָיִם - שֵׁם קָדוֹשׁ שֶׁנֶּחְקָק בְּשִׁבְעִים שֵׁמוֹת אֲחֵרִים, סוֹד שֶׁל שָׁמַיִם. וְאֵלֶּה הֵם שִׁבְעִים שֶׁשּׁוֹלְטִים עַל אֵלּוּ שִׁבְעִים דִּינִים, סוֹד שֶׁל יהו\"ה, וְשִׁבְעִים הַשֵּׁמוֹת הַלָּלוּ בִּקְדֻשָּׁה, יהו\"ה שָׁמַיִם. ה (פירוש, שם של ע\"ב גשרים היוצא מפסוק ויסע ויבא ויט, אלו הם נקראים שמים, ואותם ע\"ב מלאכים של מטה במלכו\"ת מקבלים מע\"ב של מעלה ונוטלין מהם,)"],[12,"","אֵלּוּ נוֹטְלִים (נוסעים) מֵאֵלֶּה, וְיהו\"ה ו (פירוש, מלכות מתפארת) נוֹטֵל מֵאֵת יהוה זֶה מִזֶה. ז (פירוש, סוד של אותן ע\"ב שמות הוא שם יהוה, והוא הרוכב עליהן כנשמה לגוף,) וְאֵלּוּ תְּלוּיִים בְּאֵלּוּ, תַּחְתּוֹנִים בָּעֶלְיוֹנִים, וְהַכֹּל קֶשֶׁר אֶחָד. וּבָזֶה נוֹדָע הַקָּדוֹשׁ בָּרוּךְ הוּא בִּכְבוֹדוֹ. ח (פירוש, ע\"ב מלאכים של מטה מתחברים בע\"ב שמות של מעלה הנקראים שמים,) שָׁמַיִם שֶׁהֵם שִׁבְעִים סוֹד יהוה, זֶהוּ בְּסוֹד שִׁבְעִים וּשְׁנַיִם שֵׁמוֹת, וְאֵלּוּ הֵם שֶׁיּוֹצְאִים מִן וַיִּסַּע וַיָּבא וַיֵּט."],[13,"","וה\"ו יל\"י סי\"ט על\"ם מה\"ש לל\"ה אכ\"א כה\"ת הז\"י אל\"ד לא\"ו הה\"ע. חֵלֶק רִאשׁוֹן בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. יז\"ל מב\"ה הר\"י הק\"ם לא\"ו כל\"י לו\"ו פה\"ל נל\"ךָּ יי\"י מל\"ה חה\"ו. חֵלֶק שֵׁנִי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. נת\"ה הא\"א יר\"ת שא\"ה רי\"י או\"ם לכ\"ב וש\"ר יח\"ו לה\"ח כו\"ק מנ\"ד. חֵלֶק שְׁלִישִׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. אנ\"י חע\"ם רה\"ע יי\"ז הה\"ה מי\"ךָּ וו\"ל יל\"ה סא\"ל ער\"י עש\"ל מי\"ה. חֵלֶק רְבִיעִי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וה\"ו דנ\"י הח\"ש עמ\"ם ננ\"א ני\"ת מב\"ה פו\"י נמ\"מ יי\"ל הר\"ח מצ\"ר. חֵלֶק חֲמִישִׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. ומ\"ב יה\"ה ענ\"ו מח\"י דמ\"ב מנ\"ק אי\"ע חב\"ו רא\"ה יב\"מ הי\"י מו\"ם. חֵלֶק שִׁשִּׁי בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד."],[14,"","וְאֵלּוּ הֵם שִׁבְעִים שֵׁמוֹת שֶׁשּׁוֹלְטִים עַל שִׁבְעִים דְּרָגוֹת תַּחְתּוֹנוֹת סוֹד ויהו\"ה. אֵלּוּ שִׁבְעִים שֵׁמוֹת יהו\"ה, סוֹד שֶׁנִּקְרָא שָׁמַיִם. שִׁבְעָה רְקִיעִים הֵם שֶׁעוֹלִים לְשִׁבְעִים שֵׁמוֹת שֵׁם קָדוֹשׁ. וְזֶהוּ וַיהוה הִמְטִיר. מֵאֵת יהוה מִן הַשָּׁמָיִם."]]],[["סִתְּרָא דְּסִתְּרִין לַחֲכִימִין אִתְּמָסַר. שְׁמָא דָּא דְּאִקְּרֵי שָׁמָיִם מִנֵּיהּ אִתְּבְּרֵי סִתְּרָא דְּאִקְּרֵי אָדָם. חָשְׁבָן שַׁיְיפֵּי גוּפָּא דְּאִנּוּן חוּשְׁבַּן מָאתָּן וְאַרְבְּעִין וּתְּמַנְיָא שַׁיְיפִּין.","חָשְׁבָן אַתְּווֹהִי מָאתָּן וְשִׁיתּ סָרֵי, שְׁמָא דָא דְּאִיהוּ רָזָא וְסִתְּרָא כְּלָלָא דְּכָל אוֹרַיְיתָּא בְּכ\"ב אַתְּוָון וְעֶשֶׂר אֲמִירָן, בְּגִין דְּהָא שְׁמָא דָא מָאתָּן וְשִׁיתּ סָרֵי אַתְּוָון וּתְּלָתִּין וּתְּרֵין שְׁבִילִין דְּאִתְּכְּלִילָן בֵּיהּ, הָא מָאתָּן וְאַרְבָּעִין וּתְּמַנְיָא שַׁיְיפִּין דְּגוּפָּא","רָזָא דְאִקְרֵי אָדָם דְּשַׁלִּיט על כֻּרְסְיָיא. רָזָא דְּשִׁבְעִין דִּלְתַּתָּא, וְסִתְּרָא דָא דִּכְתִּיב (יחזקאל א׳:כ״ו) וְעַל דְּמוּתּ הַכִּסֵּא דְּמוּתּ כְּמַרְאֵה אָדָם עָלָיו מִלְּמַעְלָה, וְדָא הוּא סִתְּרָא דִּכְתִּיב וַיְיָ הִמְטִיר עַל סְדוֹם וְגו' מֵאֵתּ יְיָ מִן הַשָׁמָיִם. וְכלָּא חַד וּמִלָּה חָדָא, וְסִתְּרָא חָדָא לַחֲכִימֵי לִבָּא אִתְּמָסַר, זַכָּאָה (ד\"א ל\"ג איהו) חוּלַקְהוֹן בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵּי.","סְדוֹם גְּזַר דִּינָא דִּלְהוֹן על דְּמָנְעוּ צְּדָקָה מִנַּיְיהוּ, כְּמָא דְאַתְּ אָמֵר, (יחזקאל ט״ז:מ״ט) וְיַד עָנִי וְאֶבְיוֹן לא הֶחֱזִיקָה. וּבְגִין כָּךָ דִּינָא לָא הֲוָה אֶלָּא מִן שָׁמַיִם. צְּדָקָה וְשָׁמַיִם כּלָּא חַד וּכְתִּיב, (תהילים ק״ח:ה׳) כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךָ, וּבְגִין דְּתַּלְיָא צְּדָקָה בִּשְׁמֵיהּ (נ\"א בשמים) דִּינָא הוּא מִשָׁמַיִם דִּכְתִּיב מאתּ יְיָ מִן הַשָׁמָיִם.","דִּינָא דְּיִשְׂרָאֵל מֵהַאי אֲתַּר דִּכְתִּיב, (איכה ד׳:ו׳) וַיִּגְדַּל עֲוֹן בַּתּ עַמִּי מֵחַטַאתּ סְדוֹם. וְאִקְרֵי יְרוּשָׁלֵם אֲחוֹתּ לִסְדוֹם כְּמָא דְאַתְּ אָמֵר, (יחזקאל ט״ז:מ״ט) הִנֵּה זְה הָיָה עֲוֹן סְדוֹם אֲחוֹתֵּךָ, וְדִינְהוֹן הֲוָה מִן שְׁמַיָא דִּינָא חָדָא כִּסְדוֹם עַל דְּמָנְעוּ צְּדָקָה מִנַּיְיהוּ. בַּר דְּדָא אִתְּהַפַּךָ וְדָא אִתְּחָרַב, דָּא אִיתּ לָהּ תְּקוּמָה, וְדָא לֵיתּ לָהּ תְּקוּמָה, (ע\"כ סתרי תורה).","וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, מֵאַחֲרֶיהָ מִבָּעֵי לֵיהּ, אֶלָּא מִבָּתַר שְׁכִינְתָּא. רַבִּי יוֹסֵי אָמַר מִבַּתְרִיהּ דְּלוֹט, דִּמְחַבְּלָא אָזִיל אֲבַתְרֵיהּ, וְכִי אֲבַתְרִיהּ אָזִיל, וְהָא הוּא שַׁדַּר לֵיהּ, אֶלָּא בְּכָל אֲתַר דְּהֲוָה אָזִיל לוֹט אִתְעַכַּב מְחַבְּלָא לְחַבָּלָא, וְכָל אֲתַר דְּאָזִיל כְּבָר וְשָׁבִיק לַאֲחוֹרֵיהּ הֲוָה מְהַפֵּךְ לֵיהּ מְחַבְּלָא.","וּבְגִין כָּךְ אָמַר לֵיהּ אַל תַּבֵּט אַחֲרֶיךָ דְּהָא אֲנָא אֲחַבֵּל בַּתְרָךְ, וְעַל דָּא כְּתִיב וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו וְחֲמַת מְחַבְּלָא. כְּדֵין וַתְּהִי נְצִיב מֶלַח. דְּהָא בְּכָל זִמְנָא דִּמְחַבְּלָא לָא חָמֵי אַנְפּוֹי דְּבַר נָשׁ (נ\"א אחמי אנפי לכר נש) לָא מְחַבִּיל לֵיהּ. כֵּיוָן דְּאִתְּתֵיהּ אֲהַדְּרַת אַנְפָּהָא לְאִסְתַּכָּלָא אֲבַתְרִיהּ מִיָּד וַתְּהִי נִצָּב מֶלַח.","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הֲווּ קָיְימֵי יוֹמָא חַד וְעָסְקֵי בְּהַאי קְרָא, אָמַר רַבִּי אֶלְעָזָר כְּתִיב, (דברים ח׳:ט׳) אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם, לא תֶחְסַר כֹּל בָּהּ. הַאי בָּהּ בָּהּ תְּרִי זִמְנֵי אַמַּאי. אֶלָּא הָא אִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא פָּלִיג כָּל עַמִּין וְאַרְעָאן לִמְמַנָּן שְׁלִיחָן, וְאַרְעָא דְיִשְׂרָאֵל לָא שַׁלִּיט בָּהּ מַלְאָכָא וְלָא מְמַנָּא אָחֳרָא אֶלָּא אִיהוּ בִּלְחוֹדוֹי, בְּגִין כָּךְ אָעִיל לְעַמָּא דְּלָא שַׁלִּיט בְּהוּ אָחֳרָא לְאַרְעָא דְּלָא שָׁלִיט בָּהּ אָחֳרָא.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב מְזוֹנָא תַּמָּן בְּקַדְמִיתָא וּלְבָתַר לְכָל עָלְמָא. כָּל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בְּמִסְכֵּנוּת, וְאַרְעָא דְּיִשְׂרָאֵל לָאו הָכִי, אֶלָּא אֶרֶץ יִשְׂרָאֵל אִתְּזָן בְּקַדְמִיתָא וּלְבָתַר כָּל עָלְמָא.","וּבְגִין כָּךְ אֶרֶץ אֲשֶׁר לא בְמִסְכֵּנוּת תֹּאכַל בָּהּ לֶחֶם. אֶלָּא בְּעֲתִירוּ בְּסִפּוּקָא דְּכֹלָּא תֹּאכַל בָּהּ וְלָא בְּאֲתַר אָחֳרָא. בָּהּ בִּקְדִּישׁוּ דְּאַרְעָא, בָּהּ שַׁרְיָא מְהֵימְנוּתָא עִלָּאָה. בָּהּ שַׁרְיָא בִּרְכְּתָא דִּלְעֵילָא, וְלָא בְּאֲתַר אָחֳרָא.","תָּא חֲזֵי כְּתִיב כְּגַן יְיָ כְּאֶרֶץ מִצְרַיִם. עַד הָכָא לָא אִתְיְדַע גַּן יְיָ אִי הוּא אֶרֶץ מִצְרַיִם, וְאִי אִיהוּ אֶרֶץ סְדוֹם, (דף קט ע\"א) וְאִי אִיהוּ גַּן יְיָ דְּאִקְרֵי גַּן עֵדֶן. אֶלָּא כְּגַן יְיָ דְּאִית בֵּיהּ סִפּוּקָא וְעִדּוּנָא דְּכֹלָּא, הָכִי נָמֵי הֲוָה סְדוֹם וְהָכִי נָמֵי מִצְרַיִם. מַה גַּן יְיָ לָא אִצְטְרִיךְ בַּר נָשׁ לְאַשְׁקָאָה לֵיהּ, אוּף מִצְרַיִם לָא אִצְטְרִיךְ אָחֳרָא לְאַשְׁקָאָה לֵיהּ, בְּגִין דְּנִילוּס אִיהוּ אַסִּיק וְאַשְׁקֵי לְכָל אַרְעָא דְמִצְרַיִם.","תָּא חֲזֵי, מַה כְּתִיב, (זכריה י״ד:י״ז) וְהָיָה אֲשֶׁר לא יַעֲלֶה מֵאֵת מִשְׁפְּחוֹת הָאָרֶץ אֶל יְרוּשָׁלֵם וְגו'. דָּא הוּא עוֹנָשָׁא דִלְהוֹן דְּאִתְמְנַע מִנְּהוֹן מִטְרָא, מַה כְּתִיב וְאִם מִשְׁפַּחַת מִצְרַיִם לא תַעֲלֶה וְלא בָאָה וְגו'. חָמֵי דְּלָא כְּתִיב וְלא עֲלֵיהֶם יִהְיֶה הַגֶּשֶׁם, בְּגִין דְּלָא נָחִית מִטְרָא לְמִצְרַיִם וְלָא אִצְטַרְכָן לֵיהּ, אֶלָּא עוֹנָשָׁא דִּלְהוֹן מַה הוּא דִּכְתִיב, (זכריה י״ד:י״ב) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגּוֹף יְיָ אֶת כָּל הַגּוֹיִם וְגו'. בְּגִין דְּמִצְרַיִם לָא צְרִיכִין לְמִטְרָא. אוּף סְדוֹם מַה כְּתִיב בֵּיהּ כִּי כֻלָּהּ מַשְׁקֶה, כָּל עִדּוּנִין דְּעָלְמָא הֲווּ בָהּ, וְעַל דָּא לָא בָעָאן דִּבְנֵי נָשָׁא אָחֳרָנִין יִתְעַדְּנוּן בָּהּ.","רַבִּי חִיָּיא אָמַר אִנּוּן הֲווּ חַיָּיבִין מִגַּרְמַיְיהוּ וּמִמָּמוֹנְהוֹן, דְּכָל בַּר נָשׁ דְּאִיהוּ צָר עֵינָא לְגַבֵּי מִסְכֵּנָא, יָאוֹת הוּא דְּלָא יִתְקַיַּים בְּעָלְמָא. וְלא עוֹד אֶלָּא דְּלֵית לֵיהּ חַיִּים לְעָלְמָא דְּאָתֵי. וְכָל מַאן דְּאִיהוּ וַותְּרָן לְגַבֵּי מִסְכֵּנָא יָאוֹת הוּא דְּיִתְקַיַּים בְּעָלְמָא, וְיִתְקַיַּים עָלְמָא בְּגִינֵיהּ, וְאִית לֵיהּ חַיִּים וְאוֹרְכָּא דְחַיֵּי לְעָלְמָא דְּאָתֵי:","וַיַּעַל לוֹט מִצֹּעַר וַיֵּשֶׁב בָּהָר הוּא וּשְׁתֵּי בְנוֹתָיו עִמּוֹ וְגו'. מַאי טַעְמָא. בְּגִין דְּחָמָא דְּהֲוָה קָרִיב לִסְדוֹם וְאִסְתַּלַּק מִתַּמָּן.","רַבִּי יִצְחָק פָּתַח (איוב ל״ז:י״ב) וְהוּא מְסִיבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלתָיו לְפָעֳלָם וְגו'. קוּדְשָׁא בְּרִיךְ הוּא מְסַבֵּב סִבּוּבִין דְּעָלְמָא וְאַיְיתֵי קוּמְרִין טְהִירִין לְמֶעְבַּד עוֹבָדוֹי, וּלְבָתַר מְהַפֵּךְ לוֹן וְעָבִיד לוֹן כְּגַוְונָא אָחֳרָא."],[[0,"סתרא דסתרין לחכימין אתמסר וכו':","סתר שבסתרים נמסר לחכמים, אשר שם זה שנקרא שמים, ממנו נברא סוד הנסתר שנקרא אדם. שחשבון אברי גופו הם חשבון רמ\"ח אברים. פירוש. משמים, שה\"ס ז\"א בהמוחין דע\"ב שמות, נמשך האדם, וע\"כ נברא באדם, רמ\"ח אברים, שהם כנגד רי\"ו האותיות שבע\"ב שמות, ול\"ב נתיבות החכמה, כמ\"ש לפנינו."],[1,"חשבן אתווהי מאתן ושית סרי וכו':","חשבון אותיותיו של ע\"ב שמות הוא רי\"ו. כי בכל שם יש ג' אותיות, וג' פעמים ע\"ב הוא רי\"ו. שם זה, ע\"ב הוא הסוד, והנסתר, כלל כל התורה, ונכלל בכ\"ב אותיות ועשרה מאמרות שבגימט' ל\"ב שה\"ס ל\"ב שבילין של החכמה. ונמצא כי שם הזה, הוא רי\"ו אותיות ועם ל\"ב שבילין שנכללו בו, עולים יחד רמ\"ח, והם רמ\"ח אברים של הגוף. פירוש. זו\"ן נקראים כ\"ב אותיות, ועשרה מאמרות היינו עשר ספירות דבינה. ואלו המוחין דע\"ב אינם מתגלים זולת ע\"י עלית זו\"ן למ\"ן אל הבינה, שנתחברו כ\"ב אותיות דזו\"ן עם ע\"ס דבינה, לפיכך מכונה עלית מ\"ן הזו בשם ל\"ב שבילין דחכמה או ל\"ב נתיבות החכמה. ללמדך שכל החכמה המתגלה באצילות, מתגלים רק בשבילים הללו. וכיון שז\"א הוא הגורם לאלו המוחין, ע\"כ נחקקו בו בסוד רמ\"ח בחינות, שיורה על ל\"ב שבילין, ורי\"ו אותיות המתגלים ע\"י ל\"ב שבילים, כנ\"ל. וה\"ס רמ\"ח אברים שבגוף. ומטעם זה מכונה ז\"א עצמו ג\"כ בשם \u0003אדם\u0004 כמ\"ש לפנינו, שיורה על התפשטות מוחין הללו בו."],[2,"רזא דאקרי אדם וכו':","וזה סוד שז\"א נקרא אדם, השולט על הכסא שהוא סוד שבעים שלמטה, דהיינו ע' דינין וע' מלאכים הנמשכים מהם כנ\"ל שהם מכונים כסא. וזה סוד שכתוב ועל דמות הכסא דמות כמראה אדם עליו מלמעלה. דהיינו ז\"א המכונה אדם, הוא ממעל הכסא, שה\"ס הנוקבא וע' דינין שבה. וזה הוא סוד שכתוב והוי\"ה המטיר על סדום וגו' שהוא הנוקבא וע' דינין שלה, שה\"ס כסא, מאת הויה מן השמים, שה\"ס ז\"א שהוא ממעל הכסא. והכל אחד וענין אחד וסוד אחד, שנמסר לחכמי לב. אשרי חלקם בעולם הזה ובעולם הבא."],[3,"סדום גזר דינא וכו':","סדום, הגזר דין שלהם היה, על שמנעו את עצמם מלעשות צדקה. כמו שאתה אומר, ויד עני ואביון לא החזיקה. ומשום זה, הדין שלהם לא היה אלא מן השמים. כי צדקה ושמים הוא אחד, וכתוב כי גדול מעל שמים חסדך, הרי שצדקה וחסד נמשכים מעל השמים. ומשום שצדקה תלויה בשמים נמשך גם דינם מן השמים, שכתוב מאת ה' מן השמים, פירוש כי יש דינין דנוקבא ויש דינין דדכורא, (כנ\"ל דף י\"ט ד\"ה והוא) ואומר שדינין דסדום הם דינין דדכורא, דהיינו מן השמים שהוא ז\"א. והוא מטעם שגזר דינם יצא על מניעת הצדקה, שפגם הזה נוגע בז\"א, שמנעו אותו להשפיע צדקה וחסד להנוקבא, וע\"כ גם דינם דין דדכורא."],[4,"דינא דישראל וכו':","הדין של ישראל הוא גם כן מאותו מקום, דהיינו מן השמים, שכתוב, ויגדל עון בת עמי מחטאת סדום, וירושלים נקרא אחות אל סדום, כמו שאתה אומר, הנה זה היה עון סדום אחותך, ועל כן היה דינם מן השמים, דין אחד עם סדום, על שמנעו את עצמם מלעשות צדקה, רק ההפרש הוא שזה נתהפך דהיינו סדום, וזה נחרב דהיינו ירושלים. זה יש לה תקומה, דהיינו ירושלים וזה אין לה תקומה, דהיינו סדום."],[4,"","פנימיות הדברים, כי ערי סדום היו ממשיכים בחינת ג\"ר דהארת שמאל, וזה היה בחינתם עצמם. ובחינת ירושלים הוא רק ו\"ק דהארת שמאל. ומטרם חטאת סדום, היו המוחין של הארת השמאל מסודרים למעלה כראוי להיות, דהיינו ג\"ר למעלה, ואחריהן ו\"ק, ואחריהן גזרת דינא המובא לעיל, (באות רט\"ז) וכשחטא ויצא גזר דינם, אז הפך המדרגות ממטה למעלה, בהמוחין דהארת השמאל, שהעלה גזרת דינא למעלה, שרק היא נעשתה ראויה לזווג, כנ\"ל בסו\"ה בערב היא באה ע\"ש. ואחריה נמשכו הו\"ק דמוחין, ואחריהן למטה מכולם נפלו הכלים דג\"ר דמוחין. וכיון שהפך ה' המדרגות למעלה כן נתהפכו ערי סדום למטה, להיותם מבחינת הג\"ר שנפלו למטה מכולם. ואמר לעיל באות רס\"ג \u0003כמה דארעא דלהון אתאביד לעלם ולעלמי עלמיא הכי נמי אתאבידו אינון\u0004 וכו', והיינו כי תקון זה שנעשה בהארת השמאל נשאר כן בהחלט עד גמר התקון. שנאמר אז ואחותך סדום ובנותיה תשבנה לקדמותם. כי אז יחזרו המדרגות למעלה לקדמותם, דהיינו ג\"ר למעלה ואחריהם ז\"ת, ולבסוף גזרת דינא."],[4,"","וזהו אמרו \u0003כאן בר דדא אתהפך, ודא אתחרב,\u0004 כי אע\"פ שדין ירושלים וסדום אחד הוא, מ\"מ יש הפרש רב, כי סדום להיותם מבחינת ג\"ר, הרי נתהפכו ונתבטלו עד גמר התקון, משא\"כ ירושלים להיותה מבחינת ו\"ק לא נהפכה, כי ו\"ק דמוחין דשמאל נשארו מהארת השמאל על מקומם, באמצע, ולא יארע בהם שינוי לעולם, אלא לסבת עונם נחרבו, כי נפרד הזווג העליון לשעתו, עד שיעשו תשובה. וז\"ש \u0003דא אית לה תקומה,\u0004 ירושלים יש לה תקומה, אם יעשו ישראל תשובה, ואפילו לפני גמר התקון. \u0003ודא לית לה תקומה,\u0004 וסדום אין לה תקומה. כי המהפכה לא תתבטל מטרם גמר התקון. כנ\"ל. (ע\"כ סתרי תורה)"],[5,"ותבט אשתו מאחריו:","ושואל, כתוב \u0003מאחריו\u0004 הלא מאחריה צריך לכתוב. ומשיב, ר' יוסי אמר, \u0003מאחריו\u0004 היינו מאחריו של לוט. שהמחבל היה הולך מאחוריו, ושואל וכי הלך אחריו המחבל, הלא המחבל שלח אותו ממנו. ומשיב, אלא בכל מקום שלוט היה הולך, נעכב המחבל מלחבל, והמקום שכבר הלך משם, ועזבו לאחריו, היה המחבל מהפך אותו, ומשום זה אמר לו המחבל: \u0003אל תבט אחריך,\u0004 כי אני אחבל אחריך. ועל כן כתוב, ותבט אשתו מאחריו, וראתה המחבל, אז נעשתה נציב מלח. כי כל זמן שהמחבל אינו רואה פניו של האדם אינו מחבל אותו, וכיון שאשת לוט החזירה פניה להסתכל אחריו, מיד, \u0003ותהי נציב מלח.\u0004"],[7,"ר' אלעזר ור' יוסי וכו':","ר\"א ור\"י, יום אחד, היו עומדים ועוסקים בכתוב הזה. אמר ר' אלעזר, כתוב, ארץ אשר לא במסכנות תאכל \u0003בה\u0004 לחם, לא תחסר כל \u0003בה,\u0004 אלו \u0003בה בה,\u0004 שתי פעמים, למה לי. \u0003אלא הא אתמר\u0004 וכו' ומשיב, אלא כבר אמרו, שהקב\"ה חלק את כל העמים והארצות לממונים שליחים, וארץ ישראל, אין מלאך שולט בה ולא ממונה אחר, אלא הקב\"ה לבדו. ומשום זה, הביא את העם, שאין אחר שולט עליו חוץ מהקב\"ה, אל הארץ, שאין אחר שולט עליה חוץ מהקב\"ה,"],[8,"ת\"ח קודשא בריך הוא וכו':","בוא ראה, הקב\"ה נותן תחילה מזונות לארץ ישראל, ואחר כך לכל העולם. ונמצאים כל שאר העמים עכו\"ם, מקבלים במסכנות, וארץ ישראל אינו כך, אלא ארץ ישראל ניזון מתחילה, ואחר כך כל העולם ניזונים משירים."],[9,"ובג\"כ, ארץ וכו':","ומשום זה, כתוב, ארץ אשר לא במסכנות תאכל בה לחם, אלא בעשירות בכל המלוא \u0003תאכל בה,\u0004 ולא במקום אחר. \u0003בה,\u0004 יורה בקדושת הארץ, \u0003בה\u0004 שורה אמונה העליונה, \u0003בה\u0004 שורה ברכה העליונה, ולא במקום אחר. וע\"כ כתוב בהמקרא ב' פעמים בה, לרמז על כל הנזכר."],[10,"ת\"ח כתיב וכו':","בוא וראה, כתוב, כגן ה' כארץ מצרים, באכה צוער ושואל, עד כאן עוד לא נודע מהכתוב, אם ארץ מצרים הוא כגן ה', ואם ארץ סדום הוא כגן ה'. ואם גן ה', הוא הגן הנקרא גן עדן. ומשיב, אלא הפירוש הוא, כגן ה', שהוא גן עדן, שיש בו מלוא ועדון לכל, כן היה סדום וכן היה מצרים. מה גן ה', אין אדם צריך להשקותו כן מצרים, אין אחר צריך להשקותה, משום שנהר נילוס עולה ומשקה את כל ארץ מצרים."],[11,"ת\"ח מה כתיב וכו':","בוא וראתה מה כתוב. והיה אשר לא יעלה מאת משפחות הארץ אל ירושלם וגו', זה הוא העונש שלהם שנמנע מהם הגשם. ואם משפחת מצרים לא תעלה ולא באה וגו', ראה, שלא כתוב כאן, ולא עליהם יהיה הגשם, כי לא ירד גשם במצרים ואינם צריכים לו. אלא עונש שלהם מה הוא, היא כמ\"ש וזאת תהיה המגפה אשר יגוף ה' את הגוים וגו'. שהוא משום שהמצרים אינם צריכים גשם."],[11,"אוף סדום וכו':","אף סדום היה כגן ה', מה כתוב בהם, כי כלה משקה. דהיינו כל מעדני עולם היו בה. ועל כן לא רצו, שאנשים אחרים יתעדנו בה. ולא קבלו אורחים."],[12,"רבי חייא וכו':","רח\"א, הם, אנשי סדום היו רשעים מעצמם ומרכושם, ולא מסבת ארצם הטובה, כי לא רצו ליתן צדקה, כי כל אדם, שהוא צר עין כלפי עני, ראוי לו, שלא יתקיים בעולם. ולא עוד, אלא שאין לו חיים לעולם הבא. וכל מי שהוא טוב לב לעני, ראוי לו שיתקיים בעולם,והעולם יתקיים בזכותו, ויש לו חיים, ואריכות ימים לעולם הבא."],[13,"ויעל לוט מצוער וישב בהר הוא ושתי בנותיו עמו וגו':","ושואל מה הטעם שעלה מצוער. ואומר, שהוא משום שראה שצוער קרוב לסדום וע\"כ עלה משם."],[14,"ר' יצחק פתח וכו':","ר\"י פתח, והוא מסיבות מתהפך בתחבולותיו לפעלם וגו', דהיינו שהקב\"ה מסבב סבות בעולם, ומביא אורות משחיתים שיעשו מעשיו, ואחר כך מהפך אותם, ועושה אותם באופן אחר טהירין, פירושו אורות. \u0003קומרין\u0004 הוא כמו \u0003גומרין\u0004 כי ק' מתחלפת בג', ופירושו משחיתים, כי \u0003ואכל\u0004 פרי בהמתך (דברים כ\"ח נ\"א) מתרגם יונתן, \u0003ויגמרון\u0004 ולדי דבעירכון. ואומר בפירוש הכתוב, והוא מסבות מתהפך וגו' שמדרך הקב\"ה, להביא תחלה אורות משחיתים, העושים מעשים של חורבן, ואח\"כ מהפך אותם ומתקן אותם."]],[[0,"","סֵתֶר הַסְּתָרִים לַחֲכָמִים נִמְסָר. שֵׁם זֶה שֶׁנִּקְרָא שָׁמַיִם, מִמֶּנּוּ נִבְרָא סֵתֶר שֶׁנִּקְרָא אָדָם. חֶשְׁבּוֹן אֵיבְרֵי הַגּוּף שֶׁהֵם חֶשְׁבּוֹן מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים."],[1,"","חֶשְׁבּוֹן אוֹתִיּוֹתָיו מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה. שֵׁם זֶה שֶׁהוּא סוֹד וְסֵתֶר כְּלָל שֶׁל כָּל הַתּוֹרָה בְּכ\"ב אוֹתִיּוֹת וְעֶשֶׂר אֲמִירוֹת, מִשּׁוּם שֶׁהֲרֵי שֵׁם זֶה מָאתַיִם וְשֵׁשׁ עֶשְׂרֵה אוֹתִיּוֹת וּשְׁלֹשִׁים וּשְׁנַיִם שְׁבִילִים שֶׁכְּלוּלִים בָּהּ. הֲרֵי מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבְרֵי הַגּוּף."],[2,"","סוֹד שֶׁנִּקְרָא אָדָם הַשּׁוֹלֵט עַל הַכִּסֵּא, סוֹד שֶׁל שִׁבְעִים שֶׁלְּמַטָּה, וְסֵתֶר זֶה שֶׁכָּתוּב (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה, וְזֶה הוּא סֵתֶר שֶׁכָּתוּב וַה' הִמְטִיר עַל סְדם וְגוֹ' מֵאֵת ה' מִן הַשָּׁמָיִם. וְהַכֹּל אֶחָד וְדָבָר אֶחָד, וְסֵתֶר אֶחָד לְחַכְמֵי הַלֵּב נִמְסָר. אַשְׁרֵי (הוא) חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[3,"","סְדֹם נֶחְתַּם גְּזַר דִּין שֶׁלָּהֶם עַל שֶׁמָּנְעוּ צְדָקָה מֵהֶם, כְּמוֹ שֶׁנֶּאֱמַר (שם יו) וְיַד עָנִי וְאֶבְיוֹן לֹא הֶחֱזִיקָה, וְלָכֵן הַדִּין לֹא הָיָה אֶלָּא מִן הַשָּׁמַיִם. צְדָקָה וְשָׁמַיִם הַכֹּל אֶחָד, וְכָתוּב (תהלים קח) כִּי גָדוֹל מֵעַל שָׁמַיִם חַסְדֶּךְ, מִשּׁוּם שֶׁצְּדָקָה תְלוּיָה בִּשְׁמוֹ (בשמים), דִּין הוּא מִשָּׁמַיִם, שֶׁכָּתוּב מֵאֵת ה' מִן הַשָּׁמָיִם."],[4,"","הַדִּין שֶׁל יִשְׂרָאֵל מִמָּקוֹם זֶה, שֶׁכָּתוּב (איכה ד) וַיִּגְדַּל עֲון בַּת עַמִּי מֵחַטַּאת סְדם. וִירוּשָׁלַיִם נִקְרֵאת אָחוֹת לִסְדם, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל יט) הנה זה היה עון סדם אחותך, ודינם היה מן השמים דין אחד כִּסְדם עַל שֶׁמָּנְעוּ צְדָקָה מֵהֶם, פְּרָט לָזֶה שֶׁזֶּה הִתְהַפֵּךְ וְזֶה נֶחֱרַב. לָזוֹ יֵשׁ תְּקוּמָה, וְלָזוֹ אֵין תְּקוּמָה. ע\"כ סתרי תורה."],[5,"","וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, הָיָה צָרִיךְ לִכְתֹּב מֵאַחֲרֶיהָ? אֶלָּא מֵאַחַר הַשְּׁכִינָה. רַבִּי יוֹסֵי אָמַר, מֵאֲחוֹרָיו שֶׁל לוֹט, שֶׁהַמַּשְׁחִית הָיָה הוֹלֵךְ אַחֲרָיו. וְכִי אַחֲרָיו הָלַךְ, הֲרֵי הוּא שָׁלַח אוֹתוֹ? אֶלָּא כָּל מָקוֹם שֶׁהָלַךְ לוֹט, הִתְעַכֵּב הַמַּשְׁחִית לְהַשְׁחִית, וְכָל מָקוֹם שֶׁהָלַךְ כְּבָר וְהִשְׁאִיר לַאֲחוֹרָיו, הָיָה הוֹפֵךְ אוֹתוֹ הַמַּשְׁחִית."],[6,"","וְלָכֵן אָמַר לוֹ אַל תַּבֵּט אַחֲרֶיךְ, שֶׁהֲרֵי אֲנִי מְחַבֵּל אַחֲרֶיךְ. וְעַל זֶה כָּתוּב וַתַּבֵּט אִשְׁתּוֹ מֵאַחֲרָיו, וְרָאֲתָה אֶת הַמַּשְׁחִית, אָז וַתְּהִי נְצִיב מֶלַח. שֶׁהֲרֵי כָּל זְמַן שֶׁהַמַּשְׁחִית אֵינוֹ רוֹאֶה אֶת פְּנֵי הָאִישׁ (מראה פניו לאיש), הוּא אֵינוֹ מַשְׁחִית אוֹתוֹ. כֵּיוָן שֶׁאִשְׁתּוֹ הֶחֱזִירָה פָנֶיהָ לְהִסְתַּכֵּל אַחֲרָיו, מִיָּד וַתְּהִי נְצִיב מֶלַח."],[7,"","רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ עוֹמְדִים יוֹם אֶחָד וְעוֹסְקִים בַּפָּסוּק הַזֶּה. אָמַר רַבִּי אֶלְעָזָר, כָּתוּב (דברים ח) אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם לֹא תֶחְסַר כֹּל בָּהּ. לְשֵׁם מָה פַּעֲמַיִם בָּהּ בָּהּ? אֶלָּא הֲרֵי נֶאֱמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חִלֵּק אֶת כָּל הָעַמִּים וְהָאֲרָצוֹת לִשְׁלוּחִים מְמֻנִּים, וּבְאֶרֶץ יִשְׂרָאֵל לֹא שׁוֹלֵט מַלְאָךְ וְלֹא מְמֻנֶּה אַחֵר, אֶלָּא הוּא לְבַדּוֹ, לָכֵן הִכְנִיס אֶת הָעָם שֶׁלֹּא שׁוֹלֵט בָּהֶם אַחֵר לְאֶרֶץ שֶׁלֹּא שׁוֹלֵט בָּהּ אַחֵר."],[8,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן מָזוֹן שָׁם בַּתְּחִלָּה, וְאַחַר כָּךְ לְכָל הָעוֹלָם. כָּל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת בְּעֹנִי, וְאֶרֶץ יִשְׂרָאֵל לֹא כָּךְ, אֶלָּא אֶרֶץ יִשְׂרָאֵל נִזּוֹנֵית בַּתְּחִלָּה וְאַחַר כָּךְ כָּל הָעוֹלָם."],[9,"","וְלָכֵן אֶרֶץ אֲשֶׁר לֹא בְמִסְכֵּנֻת תֹּאכַל בָּהּ לֶחֶם, אֶלָּא בְּעֹשֶׁר, בַּסִּפּוּק שֶׁל הַכֹּל תֹּאכַל בָּהּ וְלֹא בְּמָקוֹם אַחֵר. בָּהּ בִּקְדֻשַּׁת הָאָרֶץ, בָּהּ שׁוֹרָה הָאֱמוּנָה הָעֶלְיוֹנָה, בָּהּ שׁוֹרָה הַבְּרָכָה שֶׁלְּמַעְלָה, וְלֹא בְּמָקוֹם אַחֵר."],[10,"","בֹּא רְאֵה, כָּתוּב כְּגַן ה' כְּאֶרֶץ מִצְרַיִם. עַד כָּאן לֹא נוֹדַע גַּן ה' אִם הוּא אֶרֶץ מִצְרַיִם וְאִם הוּא אֶרֶץ סְדם וְאִם הוּא גַּן ה' שֶׁנִּקְרָא גַן עֵדֶן. אֶלָּא כְּגַן ה' שֶׁיֵּשׁ בּוֹ סִפּוּק וְעִדּוּן שֶׁל הַכֹּל, כָּךְ גַּם הָיְתָה סְדם וְכָךְ גַּם מִצְרַיִם. מַה גַּן ה' לֹא צָרִיךְ אָדָם לְהַשְׁקוֹתוֹ, אַף מִצְרַיִם לֹא צָרִיךְ אַחֵר לְהַשְׁקוֹתָהּ, מִשּׁוּם שֶׁהַנִּילוּס עוֹלֶה וּמַשְׁקֶה אֶת כָּל אֶרֶץ מִצְרַיִם."],[11,"","בֹּא רְאֵה מַה כָּתוּב, (זכריה יד) וְהָיָה אֲשֶׁר לֹא יַעֲלֶה מֵאֵת מִשְׁפְּחוֹת הָאָרֶץ אֶל יְרוּשָׁלם וְגוֹ'. זֶהוּ עֹנֶשׁ שֶׁלָּהֶם שֶׁנִּמְנָע מֵהֶם מָטָר. מַה כָּתוּב וְאִם מִשְׁפַּחַת מִצְרַיִם לֹא תַעֲלֶה וְלֹא בָאָה וְגוֹ'? רְאֵה שֶׁלֹּא כָתוּב וְלֹא עֲלֵיהֶם יִהְיֶה הַגָּשֶׁם, כִּי לֹא יוֹרֵד מָטָר בְּמִצְרַיִם וְלֹא צְרִיכִים אוֹתוֹ. אֶלָּא עָנְשָׁם מַהוּ שֶׁכָּתוּב? (שם) וְזֹאת תִּהְיֶה הַמַּגֵּפָה אֲשֶׁר יִגֹּף ה' אֶת כָּל הַגּוֹיִם וְגוֹ'. מִשּׁוּם שֶׁמִּצְרַיִם לֹא צְרִיכִים מָטָר. אַף סְדם מַה כָּתוּב בָּהּ? כִּי כֻלָּהּ מַשְׁקֶה. כָּל עִדּוּנֵי הָעוֹלָם הָיוּ בָּהּ, וְעַל זֶה לֹא רָצוּ שֶׁבְּנֵי אָדָם אֲחֵרִים יִתְעַדְּנוּ בָּהּ."],[12,"","רַבִּי חִיָּיא אָמַר, הֵם הָיוּ רְשָׁעִים מֵעַצְמָם וּמָמוֹנָם, שֶׁכָּל בֶּן אָדָם שֶׁהוּא צַר עַיִן לְעָנִי, רָאוּי הוּא שֶׁלֹּא יַעֲמֹד בָּעוֹלָם, וְלֹא עוֹד, אֶלָּא שֶׁאֵין לוֹ חַיִּים לָעוֹלָם הַבָּא. וְכָל מִי שֶׁהוּא וַתְּרָן לְעָנִי, רָאוּי הוּא שֶׁיִּתְקַיֵּם בָּעוֹלָם וְיִתְקַיֵּם הָעוֹלָם בִּשְׁבִילוֹ, וְיֵשׁ לוֹ חַיִּים וְאֹרֶךְ שֶׁל חַיִּים לָעוֹלָם הַבָּא."],[13,"","וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר הוּא וּשְׁתֵּי בְנֹתָיו עִמּוֹ וְגוֹ'. מָה הַטַּעַם? מִשּׁוּם שֶׁרָאָה שֶׁהָיָה קָרוֹב לִסְדם וְעָלָה מִשָּׁם."],[14,"","רַבִּי יִצְחָק פָּתַח, (איוב לז) וְהוּא מְסִבּוֹת מִתְהַפֵּךְ בְּתַחְבּוּלֹתָו לְפָעֳלָם וְגוֹ'. הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים בָּעוֹלָם וּמֵבִיא גַּחֲלֵי אֵשׁ צַחִים לַעֲשׂוֹת מַעֲשָׂיו, וְאַחַר כָּךְ הוֹפֵךְ אוֹתָם וְעוֹשֶׂה אוֹתָם בְּגָוֶן אַחֵר."]]],[["וּבְמָּה, בְּתַחְבּוּלוֹתָיו, עָבִיד תַּחְבּוּלִין וּמְסַבֵּב סִבּוּבִין לַאֲפָכָא לוֹן וְלָאו כְּאִנּוּן קַדְמָאֵי. לְפָעֳלָם, בְּגִין פָּעֳלָם דִּבְנֵי נָשָׁא, כְּמָה דְאִנּוּן עָבְדִין עוֹבָדִין הָכִי מְהַפֵּךְ לוֹן. כֹּל אֲשֶׁר יְצַוֵּם עַל פְּנֵי תֵבֵל אָרְצָה. בְּגִין דְּעוֹבָדִין דִּבְנֵי נָשָׁא מְהַפֵּךְ לְאִנּוּן מְסִבּוֹת בְּכָל מַה דְּאִיהוּ פַּקִּיד לוֹן עַל פְּנִי תֵבֵל וְגו'.","רַבִּי אֶלְעָזָר אָמַר וְהוּא מְסִבּוֹת מִתְהַפֵּךְ. הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִין וְאַיְיתֵי עוֹבָדִין בְּעָלְמָא לְאִתְקָיְימָא, וּלְבָתַר דְּחֲשִׁיבוּ בְּנֵי נָשָׁא דְּיִתְקָיְימוּן אִנּוּן עוֹבָדִין, קוּדְשָׁא בְּרִיךְ הוּא מְהַפֵּךְ לוֹן לְאִנּוּן עוֹבָדִין מִכְּמָה דְּהֲווּ בְּקַדְמִיתָא.","בְּתַחְבּוּלוֹתָיו. בְּתַחְבּוּלָתוֹ כְּתִיב כְּהַאי אוֹמָנָא דְּעָבִיד מָאנִין דְּחַרְסָא. בְּעוֹד דְּהַהִיא טִיקְלָא אִסְתַּחֲרַת קַמֵיהּ. חָשִׁיב לְמֶעְבַּד כְּגַוְונָא דָּא עָבִיד. חָשִׁיב לְמֶעְבַּד כְּגַוְונָא אָחֳרָא עָבִיד. מְהַפֵּךְ מָאנָא דָּא לְמָאנָא דָא, בְּגִין דְּהַהוּא טִיקְלָא אִסְתַּחֲרַת קַמֵּיהּ. כָּךְ קוּדְשָׁא בְּרִיךְ הוּא מְהַפֵּךְ עוֹבָדוֹי דְּאִיהוּ עָבִיד.","בְּתַחְבּוּלֹתָו חָסֵר יו\"ד, וּמַאן אִיהוּ, דָּא בֵּי דִינָא לְתַתָּא דְּאִיהוּ טִקְלָא דְּאִסְתַּחֲרַת קַמֵּיהּ, וְעַל דָּא מְהַפֵּךְ מָאנִין מִמָּאנָא דָא לְמָאנָא אָחֳרָא.","וְכָל דָּא כְּפִי פָּעֳלָם דִּבְנֵי נָשָׁא, אִי מְטִיבִין בְּנֵי נָשָׁא עוֹבָדֵיהוֹן, הַהוּא טִקְלָא דְּסַחֲרָא אַסְחָרַת לוֹן לְיָמִינָא, וּכְדֵין אִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאוֹטָבָא לוֹן כְּדְקָא יְאוּת. וְטִיקְלָא אַסְחָרַת תָּדִיר וְלָא שָׁכִיךְ בְּהַהוּא סִטְרָא דְּיָמִינָא וְעָלְמָא מִתְגַּלְגְּלָא בֵּיהּ."],[[0,"ובמה, בתחבולותיו וכו':","ושואל ובמה, מהפך אותם. ואומר שזהו שכתוב \u0003בתחבולותיו,\u0004 הקב\"ה עושה תחבולות ומסבב סבות להפך אותם, עד שאינם כמו הקודמים. \u0003לפעלם,\u0004 היינו לפי פעלם של בני אדם, לפי המעשים שהם עושים, כך מהפך אותם המעשים של קומרין טהירין, \u0003כל אשר יצום על פני תבל ארצה,\u0004 היינו שמעשי בני אדם, גורמים להפך אותם המעשים בכל מה שהקב\"ה מצוה אותם על פני תבל. דהיינו שמקבלים כל מיני צורות שבעולם, לפי ערך מעשיהם של בני אדם. ובדברים הללו, פתח ר' יצחק, להבין ענין עמון ומואב, שיצאו על ידי מעשה מקולקל כזה, ולבסוף יצאו מהם כל מלכי יהודה, ומלך המשיח, כמו שמבאר להלן."],[1,"רבי אלעזר וכו':","ר\"א אמר, והוא מסבות מתהפך. הוא, שהקב\"ה מסבב סבות, ומביא מעשים להתקיים בעולם. ואחר שבני אדם חושבים שהמעשים יתקיימו, הקב\"ה מהפך אותם המעשים ממה שהיו בתחילה. והוא חולק על ר\"י שפירש הכ' שמתחילה יצאו המעשים בקלקול על ידי קומרין טהירין, ואח\"כ הפכם הקב\"ה ותקן אותם. ור\"א מפרש שמתחילה יצאו טובים וראוים לקיום, אלא שנתקלקלו בסבת מעשי בני אדם, ואח\"כ מהפכם הקב\"ה אם עושים תשובה."],[2,"בתחבולותיו:","בתחבולתו כתוב, בלי י', שיורה לשון יחיד. והוא, כאומן הזה, העושה כלים של חרס. כל עוד שאותם האבנים מסתובבים לפניו, אם חושב לעשות באופן זה עושה, ואם חושב לעשות באופן אחר עושה, כשהוא רוצה מהפך כלי זו לכלי אחרת. וכל זה הוא, משום שאותם האבנים מסתובבים לפניו."],[3,"כך קב\"ה וכו':","כן הקב\"ה מהפך מעשיו שהוא עושה, \u0003בתחבולתו\u0004 חסר י', שהוא לשון יחיד, ומי הוא התחבולה, הוא בית דין של מטה, שהיא הנוקבא דז\"א, והיא האבנים המסתובבים לפניו. לפי שהמוחין באים להנוקבא, ומושפעים ממנה, בסוד ג' נקודות, שהם נבחנים לתלת דוכתי (כנ\"ל ב\"א דף כ' ד\"ה עד הכא ע\"ש) ע\"כ מדומית אז הנוקבא שמסתובבת בג' דוכתי. \u0003ועל דא מהפך וכו':\u0004 ועל זה, הוא מהפך הכלים, מכלי זו אל כלי אחרת."],[4,"וכל זה הוא כפי פעלם של בני אדם,","אם בני אדם מטיבים מעשיהם, אותם האבנים המסתובבים, מסבבים אותם לימין, שהוא חסד, ואז המעשים שנעשו בעולם, הם להטיב לבני העולם כראוי, כי נמשכים חסדים וכל טוב אל העולם. \u0003וטיקלא אסחרת וכו':\u0004 והאבנים מסתובבים תמיד לצד ימין. ואינם נדמים, והעולם מתגלגל בו, ומקבל מעשים מקו ימין, שהם חסדים."]],[[0,"","וּבַמֶּה,? בְּתַחְבּוּלֹתָו. עוֹשֶׂה תַחְבּוּלוֹת וּמְסַבֵּב סִבּוּבִים כְּדֵי לַהֲפֹךְ אוֹתָם, וְלֹא כְּמוֹ אוֹתָם הָרִאשׁוֹנִים. לְפָעֳלָם - מִשּׁוּם פָּעֳלָם שֶׁל בְּנֵי אֱנוֹשׁ. כְּמוֹ שֶׁהֵם עוֹשִׂים מַעֲשִׂים, כָּךְ הוּא מְהַפֵּךְ אוֹתָם. כֹּל אֲשֶׁר יְצַוֵּם עַל פְּנֵי תֵבֵל אָרְצָה - מִשּׁוּם מַעֲשֵׂי בְּנֵי אָדָם הוּא מְהַפֵּךְ אוֹתָם מְסִבּוֹת בְּכָל מַה שֶּׁהוּא מְצַוֶּה אוֹתָם עַל פְּנֵי תֵבֵל וְגוֹ'."],[1,"","רַבִּי אֶלְעָזָר אָמַר, וְהוּא מְסִבּוֹת מִתְהַפֵּךְ - הַקָּדוֹשׁ בָּרוּךְ הוּא מְסַבֵּב סִבּוּבִים וּמֵבִיא מַעֲשִׂים בָּעוֹלָם לְהִתְקַיֵּם, וְאַחַר שֶׁחוֹשְׁבִים בְּנֵי אָדָם שֶׁיִּתְקַיְּמוּ אוֹתָם מַעֲשִׂים, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹפֵךְ אוֹתָם אֶת אוֹתָם מַעֲשִׂים מִכְּמוֹ שֶׁהָיוּ בַּהַתְחָלָה."],[2,"","בְּתַחְבּוּלֹתָו, בְּתַחְבּוּלָתוֹ כָּתוּב, כְּמוֹ הָאֻמָּן הַזֶּה שֶׁעוֹשֶׂה כְּלִי חֶרֶס, בְּעוֹד שֶׁאוֹתוֹ הַגַּלְגַּל מִסְתּוֹבֵב לְפָנָיו, חוֹשֵׁב לַעֲשׂוֹת כְּגוֹן זֶה - עוֹשֶׂה, חוֹשֵׁב לַעֲשׂוֹת כְּגוֹן אַחֵר - עוֹשֶׂה. מְהַפֵּךְ כְּלי זֶה לִכְלִי אַחֵר מִשּׁוּם שֶׁאוֹתוֹ הַגַּלְגַּל סוֹבֵב לְפָנָיו. כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְהַפֵּךְ אֶת מַעֲשָׂיו שֶׁהוּא עוֹשֶׂה."],[3,"","בְּתַחְבּוּלֹתָו חָסֵר יוֹ\"ד, וּמַהוּ? זֶה בֵּית דִּין לְמַטָּה שֶׁהוּא גַלְגַּל הַסּוֹבֵב לְפָנָיו, וְעַל זֶה הוּא מְהַפֵּךְ כֵּלִים מִכְּלִי זֶה לִכְלִי אַחֵר,"],[4,"","וְכָל זֶה כְּפִי פָעֳלָם שֶׁל בְּנֵי אָדָם. אִם בְּנֵי אָדָם מְטִיבִים מַעֲשֵׂיהֶם - אוֹתוֹ הַגַּלְגַּל הַסּוֹבֵב מְסוֹבֵב אוֹתָם יָמִינָה, וְאָז נַעֲשִׂים מַעֲשִׂים בָּעוֹלָם לְהֵיטִיב לָהֶם כָּרָאוּי, וְהַגַּלְגַּל סוֹבֵב תָּמִיד וְלֹא שׁוֹקֵט בְּאוֹתוֹ צַד הַיָּמִין, וְהָעוֹלָם מִתְגַּלְגֵּל בּוֹ."]]],[["אָתוּ בְּנֵי נָשָׁא לְאַבְאָשָׁא, תַּחְבּוּלָתוֹ דְּאַסְחַר תָּדִיר וְהֲוָה קָיְימָא בְּאַסְחָרוּתָא דְּיָמִינָא, קוּדְשָׁא בְּרִיךְ הוּא אַסְחַר לֵיהּ בְּסִטְרָא דִּשְׂמָאלָא וּמְהַפֵּךְ מְסִבּוֹת וּמָאנִין דְּהֲווּ בְּקַדְמִיתָא לְהַהוּא סְטַר שְׂמָאלָא.","וּכְדֵין טִקְלָא אַסְחָרָא וְאִתְעֲבִידוּ עוֹבָדִין בְּעָלְמָא לְאַבְאָשָׁא לוֹן לִבְנֵי נָשָׁא. וְטִקְלָא אַסְחַר לְהַהוּא סִטְרָא עַד דִּבְנֵי נָשָׁא תָּיְיבִין לְאוֹטָבָא עוֹבָדֵיהוֹן. וְטִקְלָא קָיְימָא בְּעוֹבָדִין דִּבְנֵי נָשָׁא. וְעַל דָּא בְּתַחְבּוּלָתוֹ לְפָעֳלָם, וְלָא קָיְימָא תָּדִיר.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא גָּרַם סִבּוּבִין וְעוֹבָדִין בְּעָלְמָא בְּגִין לְמֶעְבַּד כֹּלָּא כְּדְקָא יְאוּת. וְכֹלָּא נָפְקָא מֵעִקָּרָא וְשָׁרְשָׁא דִּלְעֵילָא. אַקְרִיב אַבְרָהָם לְגַבֵּיהּ, נָפַק מִנֵּיהּ יִשְׁמָעֵאל דְּלָא הֲוָה אַבְרָהָם גָּזִיר כַּד נָפַק מִנֵּיהּ, בְּגִין דְּאִיהוּ לְתַתָּא וְלָא אִשְׁתְּלִים בְּאָת קְיָימָא קַדִּישָׁא.","לְבָתַר קוּדְשָׁא בְּרִיךְ הוּא סִבֵּב סִבּוּבִין בְּתַחְבּוּלוֹתָיו וְאִתְגְּזַר אַבְרָהָם וְעָאל בַּבְּרִית וְאִשְׁתְּלִים בִּשְׁמֵיהּ וְאִקְרֵי אַבְרָהָם, וְה' (צו א) עִלָּאָה אַעֲטָרַת לֵיהּ בְּרָזָא דְּמַיִם (לא א) מֵרוּחַ.","כֵּיוָן דְּרָזָא (דברי הימים א) אִשְׁתְּלִים וְאִתְגְּזַר, נָפַק מִנֵּיהּ יִצְחָק וְהֲוָה זַרְעָא קַדִּישָׁא וְאִתְקַשַּׁר לְעֵילָא בְּרָזָא דְּאֵשׁ מִמַּיִם, וְעַל דָּא כְּתִיב, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלּה זֶרַע אֱמֶת. וְלָא אִתְקְשַׁר בְּהַהוּא סִטְרָא אָחֳרָא.","תָּא חֲזֵי, לוֹט נָפְקוּ מִנֵּיהּ וּמִבְּנָתֵיהּ תְּרִין אוּמִין מִתְפָּרְשָׁן, וְאִתְקְשָׁרוּ בְּהַהוּא סִטְרָא דְּאִתְחֲזֵי לוֹן, וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא מְסַבֵּב סִבּוּבִין וּמְגַלְגֵּל גִּלְגּוּלִין בְּעָלְמָא דְּיִתְעֲבִיד כֹּלָּא כְּדְקָא יְאוּת וְיִתְקַשַּׁר כֹּלָּא בְּאַתְרֵיהּ."],[[0,"אתו בני נשא וכו':","ואם בני אדם באים לחטוא, אז, \u0003תחבולתו,\u0004 שהיא הנוקבא המסתובבת תמיד, והיתה עומדת לצד ימין עתה הקב\"ה מסבב אותה לצד שמאל, והסבות והכלים שהיו מתחילה בצד ימין, מהפך אותם לצד שמאל."],[1,"וכדין טקלא וכו':","ואז, האבנים מסתובבים ונעשו מעשים בעולם, להרע לבני אדם, והאבנים מסתובבים לצד ההוא לשמאל, עד שבני אדם חוזרים להטיב מעשיהם. והאבנים תלוים לפי מעשה בני אדם. ועל כן כתוב, \u0003בתחבולתו לפעלם,\u0004 כי התחבולה שה\"ס האבנים, תלויה בפעולת בני אדם. ותמיד אינה עומדת, אלא שמסתובבת או לימין או לשמאל, כנ\"ל."],[2,"תא חזי קב\"ה וכו':","בוא וראה, הקב\"ה גרם סבות ומעשים בעולם, כדי לעשות הכל כראוי. והכל יוצא ונמשך למטה בעולם מן העיקר והשורש שלמעלה. הקב\"ה הקריב את אברהם אליו, יצא ממנו ישמעאל, שעוד לא היה נמול בעת שיצא ממנו, ועל כן הוא יצא למטה, ולא נשלם באות ברית קדש."],[3,"לבתר קב\"ה וכו':","אחר כך, סבב הקב\"ה סבות בתחבולותיו, ואברהם נמול, ובא בברית, ונשלם בשמו, ונקרא אברהם עם \u0003ה', וה'\u0004 עליונה דהויה שניתנה בשמו, שהיא בינה, עטרה לו, בסוד \u0003מים מרוח.\u0004"],[4,"כיון דרזא וכו':","כיון שהסוד נשלם, ונמול, יצא ממנו יצחק. והיה זרע קדש ונקשר למעלה בסוד \u0003אש ממים,\u0004 ועל כן כתוב, ואנכי נטעתיך שורק כלה זרע אמת, שלא נקשר בצד האחר, דהיינו בצד שמאל לבד, אלא נכלל בימין."],[4,"","פירוש. כי מתחילה מטרם שנמול, היה תחת שליטת קומרין טהירין הנ\"ל, ובעת ההוא הוליד את ישמעאל, והולידו למטה בחיצוניות, כי ה\"ס התוכא דכספא, דהיינו פסולת הימין. ואח\"כ נאמר עליו, והוא מסבות מתהפך בתחבולותיו, שהקב\"ה סבב עליו סבות עד שנמול וכו', וזכה לקו ימין של הבינה שנקרא \u0003מים,\u0004 אמנם לא קבל המים ישר מבינה אלא מז\"א שנקרא \u0003רוח,\u0004 (כנ\"ל פרשת לך דף קמ\"ז ד\"ה פנימיות ע\"ש) וז\"ש \u0003וה' עלאה,\u0004 דהיינו בינה, אעטרת ליה ברזא \u0003דמים מרוח,\u0004 דהיינו שהבינה עטרה לו קו ימין שלה שהוא חסד הנקרא \u0003מים,\u0004 והוא קבל אותו מז\"א הנקרא \u0003רוח.\u0004 בבחינת העברה, כמ\"ש שם. ואז יצא ממנו יצחק, שנקשר \u0003למעלה,\u0004 בבינה, דהיינו שקבל קו שמאל מבינה, (כמ\"ש שם) אבל לא קבלו ישר מבינה, אלא בסוד \u0003אש ממים\u0004 שקבלו מאברהם שנקרא מים. וע\"כ נכלל בו, בסוד אברהם הוליד את יצחק."],[5,"תא חזי לוט וכו':","בוא וראה, לוט, יצאו ממנו ובנותיו, ב' אומות נפרדות ונתקשרו בצד ההוא הראוי להם. דהיינו בס\"א. ועל כן הקב\"ה מסבב סבות ומגלגל גלגולים בעולם, כדי שהכל יהיה נעשה כראוי להיות ויהיה נקשר הכל במקומו בקדושה. דהיינו שיהיה ראוי לצאת משם מלכי יהודה ומלך המשיח. שע\"ז נאמר והוא מסבות מתהפך בתחבולותיו וגו'."]],[[0,"","בָּאוּ בְּנֵי אָדָם לְהָרַע - תַּחְבּוּלָתוֹ שֶׁסּוֹבֶבֶת תָּמִיד וְהָיְתָה עוֹמֶדֶת בַּסִּבּוּב שֶׁל הַיָּמִין, הַקָּדוֹשׁ בָּרוּךְ הוּא מְסוֹבֵב אוֹתָהּ לְצַד שְׂמֹאל וּמְהַפֵּךְ מְסִבּוֹת וְכֵלִים שֶׁהָיוּ צַד שְׂמֹאל."],[1,"","וְאָז הַגַּלְגַּל סוֹבֵב וְנַעֲשִׂים מַעֲשִׂים בָּעוֹלָם לְהָרַע לִבְנֵי אָדָם. וְהַגַּלְגַּל סוֹבֵב לְאוֹתוֹ צַד עַד שֶׁבְּנֵי אָדָם שָׁבִים לְהֵיטִיב מַעֲשֵׂיהֶם, וְהַגַּלְגַּל עוֹמֵד בְּמַעֲשֵׂי בְּנֵי הָאָדָם. וְעַל כָּךְ בְּתַחְבּוּלֹתָו לְפָעֳלָם, וְלֹא עוֹמֵד תָּמִיד."],[2,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹרֵם סִבּוּבִים וּמַעֲשִׂים בָּעוֹלָם כְּדֵי לַעֲשׂוֹת הַכֹּל כָּרָאוּי, וְהַכֹּל יוֹצֵא מֵהָעִקָּר וְהַשֹּׁרֶשׁ שֶׁלְּמַעְלָה. קֵרַב אֶת אַבְרָהָם אֵלָיו - יָצָא מִמֶּנּוּ יִשְׁמָעֵאל, כְּשֶׁלֹּא הָיָה אַבְרָהָם מָהוּל כְּשֶׁיָּצָא מִמֶּנּוּ, מִשּׁוּם שֶׁהוּא לְמַטָּה וְלֹא נִשְׁלַם בְּאוֹת בְּרִית קֹדֶשׁ."],[3,"","אַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא סִבֵּב סִבּוּבִים בְּתַחְבּוּלוֹתָיו וְנִמּוֹל אַבְרָהָם, וְנִכְנַס בִּבְרִית וְנִשְׁלַם בִּשְׁמוֹ וְנִקְרָא אַבְרָהָם, וְה' עֶלְיוֹנָה עִטְּרָה אוֹתוֹ בְּסוֹד שֶׁל מַיִם מֵרוּחַ."],[4,"","כֵּיוָן שֶׁהַסּוֹד (של ה\"א) נִשְׁלַם וְהוּא נִמּוֹל, יָצָא מִמֶּנּוּ יִצְחָק וְהָיָה זֶרַע קֹדֶשׁ, וְנִקְשַׁר לְמַעְלָה בְּסוֹד שֶׁל אֵשׁ מִמַּיִם, וְעַל זֶה כָּתוּב (ירמיה ב) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת, וְלֹא נִקְשַׁר בְּאוֹתוֹ הַצַּד הָאַחֵר."],[5,"","בֹּא רְאֵה, מִלּוֹט יָצְאוּ מִמֶּנּוּ וּמִבְּנוֹתָיו שְׁתֵּי אֻמּוֹת נִפְרָדוֹת וְנִקְשְׁרוּ בְּאוֹתוֹ צַד שֶׁרָאוּי לָהֶם, וְעַל זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא מְסוֹבֵב סִבּוּבִים וּמְגַלְגֵּל גִּלְגּוּלִים בָּעוֹלָם שֶׁהַכֹּל יֵעָשֶׂה כָּרָאוּי וְיִתְקַשֵּׁר הַכֹּל בִּמְקוֹמוֹ."]]],[["תָּא חֲזֵי, יָאוֹת הֲוָה לְלוֹט דְּקוּדְשָׁא בְּרִיךְ הוּא יָפִיק מִנֵּיהּ (ומבנתיה) וּמֵאִתְּתֵיהּ תְּרִין אוּמִין אִלֵּין, אֶלָּא בְּגִין לְאִתְקַשָּׁרָא בְּאַתְרַיְיהוּ דְּאִתְחֲזֵי לְהוּ. וְאִתְעֲבִידוּ מִגּוֹ יֵינָא, וְהַהוּא יֵינָא אִזְדַּמַּן לְהוֹן בַּמְּעַרְתָּא הַהִיא לֵילְיָא, וְדָא הוּא רָזָא דְּאִתְעֲבִידוּ כְּמָה דְּאַתְּ אָמֵר וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וְהָא אִתְּמָר וְאוּקְמוּהָ.","תָּא חֲזֵי, מוֹאָב וְעַמּוֹן אִנּוּן קָרָאן לוֹן שְׁמָהָן, מוֹאָב מֵאָב. רַבִּי יוֹסֵי אָמַר בְּכִירָה בַּחֲצִיפוּ אָמְרָה מוֹאָב, מֵאַבָּא הוּא. וְהַצְּעִירָה גַּם הִיא יָלְדָה בֵּן וַתִּקְרָא שְׁמוֹ בֶּן עַמִּי. בִּצְנִיעוּ אָמְרָה בֶּן עַמִּי. בַּר עַמִּי, וְלָא אָמְרָה מִמָּאן הֲוָה.","תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב וְלָא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ בְּוא\"ו וְנָקוּד עַל וא\"ו, בְּגִין דְּסִיּוּעָא דְּעֵילָא הֲוָה אִשְׁתְּכַח בְּהַהוּא עוֹבָדָא דְּזַמִּין מַלְכָּא מְשִׁיחָא לְנָפְקָא מִנֵּיהּ, וּבְגִין כָּךְ אִשְׁתְּלִים הָכָא בְּוא\"ו. וּבְאָחֳרָא כְּתִיב וּבְקֻמָּהּ חָסֵר וי\"ו, בְּגִין דְּלָא נָפַק מִינָּהּ חוּלְקָא לְקוּדְשָׁא בְּרִיךְ הוּא כְּהַאי אָחֳרָא, וְעַל דָּא כְּתִיב בְּהַאי אָחֳרָא קְשִׁישָׁא וּבְקוּמָהּ בְּוא\"ו מָלֵא וְנָקוּד עֲלָהּ.","רַבִּי שִׁמְעוֹן אָמַר, לָא יְדַע דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאוֹקְמָא מִינָהּ דָּוִד מַלְכָּא וּשְׁלֹמֹה וְכָל שְׁאָר מַלְכִין וּמַלְכָּא מְשִׁיחָא. תּוּ וּבְקוּמָהּ, דִּכְתִיב בְּרוּת (רות ג׳:י״ד) וַתָּקָם בְּטֶרְם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגו'. וּבְהַהוּא יוֹמָא הֲוָה לָהּ קִימָה וַדַּאי אִתְחַבַּר עִמָּהּ בֹּעַז לְהָקִים שֵׁם הַמֵּת עַל נַחֲלָתוֹ, וְאִתָּקַם מִנָּהּ כָּל הַנֵּי מַלְכִין וְכָל עִלּוּיָא דְיִשְׂרָאֵל. וְלא יָדַע בְּשִׁכְבָהּ דִּכְתִיב וַתִּשְׁכַּב מַרְגְּלוֹתָיו עַד הַבֹּקֶר. וּבְקוּמָהּ דִּכְתִיב וַתָּקָם בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגו'. בְּגִין כָּךְ וּבְקוּמָהּ נְקוּד וא\"ו."],[[0,"ת\"ח יאות וכו':","בוא וראה, ראוי היה לוט, שהקב\"ה יוציא ממנו ומאשתו שתי אומות הללו. אלא כדי לקשר אותם במקום הראוי להם, לכן הוציא אותם מבנותיו. ולידתם נעשה מתוך יין, דהיינו כמ\"ש ותשקין את אביהן יין ויין הזה נועד להם באותה לילה, במערה, וזהו סוד עשיתם, כלומר שלולא היין, לא באו האומות הללו לעולם, כמו שאתה אומר וישת מן היין וישכר. וכבר נתבאר זה ונתיישב."],[0,"","ביאור המאמר. תחילה צריכים להבין ב' הביאורים: של ר' יצחק ושל ר' אלעזר, בפירוש הכתוב והוא מסכות מתהפך בתחבולותיו וגו'. והענין הוא, כי יש ב' מיני מהפכות בתקוני העולמות. א) הוא מהפכת סדום ועמורה, שכבר נתבאר ענינו לעיל (דף פ\"ג ד\"ה פנימיות עש\"ה) ומבחינת מהפכה זו ביאר ר' יצחק את הכתוב והוא מסבות מתהפך וגו' וע\"כ אמר \u0003ואייתי קומרין טהורין. ולבתר מהפך לון,\u0004 כי אלו ג\"ר דהארת השמאל, היו אורות משחיתים. בסו\"ה ארדה נא ואראה הכצעקתה וגו'. (כנ\"ל דף ס\"ה ד\"ה פירוש, ואחר כך הפך אותם ותקן הגזרא דדינא למעלה והג\"ר נפלו למטה, כנ\"ל ע\"ש. מהפכה ב) הוא מהפכת הטיקלא, המהפך מאנין ממאנא דא למאנא אחרא. (כנ\"ל באות רצ\"ט) ו הוא המהפכה דמואב ועמון, שמצד לידתם היו קליפות טמאות יותר מכל העמים עד שנאסרו לבא בקהל ה'. ובסוד והוא מסיבות מתהפך בתחבולותיו וגו', יצאו מהם כל המלכים ומלך המשיח. והענין הוא. כי ב' האומות הללו, נמשכו על ידי יין המשכר, שפירושו על ידי נחש הקדמוני, כמ\"ש להלן (בסתרי תורה ע\"ש) דהיינו שהיה בדומה לחטא דעצה\"ד, וע\"כ המשיך ג\"ר דהארת שמאל באתגליא, כלומר אורות מגולים בחכמה. ובבחי' ג\"ר כדי שהאורות ימשכו ממעלה למטה, כמו בעצה\"ד, והמשכה זו עשתה הבכירה, שממנה נולד מואב, שע\"ז שלו פעור, הוא באתגליא. והרמז הוא, שהשם מואב הוא בגלוי לכל, שנולד מאביו. ונודע. שעל ידי המשכת ג\"ר דשמאל מתגלית המלכות דמדת הדין. (כמ\"ש לעיל פרשת נח ק\"ח ד\"ה פירוש) וע\"כ הצעירה המשיכה רק בחינת ו\"ק, שהיה כבר מגולה בה המלכות דמדת הדין. ועכ\"ז היו קשורים ב' הקליפות ג\"ר וו\"ק זו בזו, והיו מקבלים זו מזו. ולפי שהמשכת הצעירה היתה מעורבה עם מלכות דמדת הדין הדוחית כל המוחין, (כנ\"ל נח ק\"ח ד\"ה פירוש) ע\"כ היתה, כל מעשיה באתכסיא, בסו\"ה ועין נואף שמרה נשף לאמור לא תשורני עין. ולפיכך נאסרו עמון ומואב לבא בקהל ה'. כי טומאתם היה גדולה, כי מואב נאסר, משום שהיה מבחינת ג\"ר דהארת השמאל, שאז מלבד שנמשכות בדינים קשים, הנה גם מגלות המלכות דמדת הדין כנ\"ל, ועמון נאסר משום שמלכות דמדת הדין היתה בו. אמנם כנגד זה נתקנה הנוקבא דקדושה, בעת שהתחתונים מטיבים מעשיהם, שהאורות המגולים בחכמה, מאירים בה מלמטה מחזה, ובבחינת ממטה למעלה, ובזה מתבטלת קליפת מואב, וכן בדרך זה מתכללים הקוים דחכמה וחסדים זה בזה, והארת החכמה מתקיימת בכל השלמות. והאורות המכוסים מאירים בה מלמעלה מחזה, במקום ג\"ר. וכן בחינת המלכות דמדת הדין נתקנה ונגנזה שם מחזה ולמעלה, ואינה פועלת שום דין, ובזה מתבטלת קליפת עמון. והמלכות הממותקת במדת הרחמים המכונה מפתחא, נתקנה מחזה ולמטה של הנוקבא. וז\"ס \u0003זכי הא טוב,\u0004 (כנ\"ל בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב') \u0003ואם לא זכי הא רע\u0004 כי אז מתקלקל תקון הנ\"ל שבנוקבא, והאורות מאירים בדינים דשמאל, וחוזרות קליפת מואב ועמון לשליטתם, ומביאים דינים קשים בעולם."],[0,"","וזה שאמר רבי אלעזר. (באות רצ\"ח) \u0003הקב\"ה מסבב סבובין, ואייתי עובדין בעלמא לאתקיימא,\u0004 דהיינו שסבב סבות ועשה מעשים בעולם, שהיא הנוקבא המכונה עולם, שתקן אותה באורות מכוסים מחזה ולמעלה, ואורות מגולים מחזה ולמטה, ועשה זה בבנין הנוקבא כדי \u0003לאתקיימא,\u0004 שהארת החכמה תתקיים בה, דהיינו שבדרך זה נכללים הקוין זה בזה והחכמה מתלבשת בחסדים כנ\"ל, ואז מתקיימת. \u0003ולבתר דחשיבו בני נשא דיתקיימון אינון עובדין,\u0004 ואחר שבני אדם מובטחים שהמוחין יתקיימו, ואינם שומרים עוד דרכיהם, וחוטאים להמשיך אורות המגולים, בהמקום שלמעלה מחזה, אז, \u0003קב\"ה מהפך לון לאינון עובדין,\u0004 וכו', כי אז חוזרים קליפת מואב ועמון למקומם כנ\"ל, ואורות השמאל מביאים דינים קשים בעולם."],[0,"","וז\"ש (באות ש\"א) \u0003אי מטיבין וכו': ההוא טקלא דסחרא אסחרת לון לימינא.\u0004 דהיינו שהקב\"ה מתקן אז את \u0003הטקלא דסחרא\u0004 שהיא הנוקבא, שאורות המגולים, יאירו למטה מחזה וכו' כנ\"ל, ואז החכמה מתלבשת בחסדים והימין שולט כנ\"ל. \u0003אתו בני נשא לאבאשא\u0004 וכו' \u0003קב\"ה אסחר ליה בסטרא דשמאלא\u0004 כי אז חוזרים קליפת מואב ועמון למקומם, והשמאל שולט כנ\"ל, וז\"ש \u0003ומהפך מסבות ומאנין דהוו בקדמיתא, לההוא סטר שמאלא,\u0004 שמהפך המסבות והכלים שהיו מתוקנים מתחילה לימין, דהיינו האורות המכוסים למעלה והאורות המגולים למטה, ועתה נתהפכו, שאורות המגולים למעלה ואורות המכוסים למטה. שדרך זה הוא שליטת השמאל בדינים הקשים, כנ\"ל. וז\"ש (באות ש\"ז) \u0003לוט נפקו מניה ומבנתיה תרין אומין מתפרשן ואתקשרו בההוא סטרא דאתחוי לון,\u0004 שנקשרו במקום הראוי להם, דהיינו האורות מגולים למעלה מחזה, שהיא קליפת מואב, ואורות מכוסים למטה מחזה שהיא קליפת עמון, כנ\"ל. \u0003ועל דא קב\"ה מסבב סבובין ומגלגל גלגולין בעלמא דיתעביד כלא כדקא יאות\u0004 וכו'. דהיינו להפך הסדר בהנוקבא הנקראת עולם, שאורות המכוסים יאירו בה למעלה והמגולים למטה כנ\"ל. תשלום ענין זה מתבאר להלן בסמוך, בביאור הסתרי' תורה, על הכתוב ויעל לוט מצוער."],[1,"ת\"ח מואב וכו':","בוא וראה מואב ועמון, הן עצמן קראו להם שמות, מואב קראה לו על שהוא מאב. ר' יוסי אמר הבכירה אמרה בעזות מואב, מואבי הוא, והצעירה גם היא ילדה בן ותקרא שמו בן עמי, בצניעות אמרה בן עמי, בן עמי, ולא אמרה ממי היה."],[2,"ת\"ח בקדמיתא וכו':","בוא וראה, בתחילה כתוב, ולא ידע בשכבה ובקומה עם ו', וגם נקודה על ה \u0003ו',\u0004 יורה, שעזרה מלמעלה היה נמצא באותו מעשה, אשר מלך המשיח עתיד לצאת ממנו. ומשום זה נתמלא המלה \u0003ובקומה\u0004 עם \u0003ו'.\u0004 ואצל האחרת כתוב, ובקמה חסר \u0003ו',\u0004 משום שלא יצא ממנה חלק להקב\"ה כמו מהבכירה. ועל כן כתוב, רק בהשניה הבכירה, \u0003ובקומה מלא\u0004 עם \u0003ו'\u0004 ונקודה עליה. ואע\"פ שגם מהצעירה יצאו מלכים. כי נעמה העמונית היתה אשת שלמה ואם רחבעם. אמנם דוד המלך הוא העיקר, והוא מלך המשיח. (כנ\"ל לך דף נ\"ה אות קל\"ה) שאומר אי מן חייא דוד שמיה אי מן מתייא דוד שמיה."],[3,"ר' שמעון אמר וכו':","רש\"א, שמ\"ש לא ידע בשכבה ובקומה, הוא, שלא ידע, שעתיד הקב\"ה להקים ממנו דוד המלך ושלמה המלך וכל שאר המלכים ומלך המשיח. עוד יש לפרש, \u0003ובקומה\u0004 על מ\"ש ברות ותקם בטרם יכיר איש את רעהו ובאותו היום היה לה קימה ודאי, כי נתחבר עמה בועז להקים שם המת על נחלתו, והוקם ממנה כל אלו המלכים, וכל איש נעלה שבישראל. פירוש אחר. ולא ידע \u0003בשכבה,\u0004 היינו שכתוב, ותשכב מרגלותיו עד הבקר. \u0003ובקומה\u0004 שכתוב ותקם בטרם יכיר איש את רעהו וגו'. משום זה כתוב \u0003ובקומה\u0004 ב \u0003ו'\u0004 עם נקודה, וההפרש שבפירוש זה על הראשון, הוא. מה שביאר ג\"כ את הכתוב, ולא ידע בשכבה שלא ביאר זה בפירוש הראשון."]],[[0,"","בֹּא רְאֵה, נָאֶה הָיָה לְלוֹט שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹצִיא מִמֶּנּוּ (ומבנותיו) וּמֵאִשְׁתּוֹ שְׁתֵּי הָאֻמּוֹת הַלָּלוּ, אֶלָּא בִּשְׁבִיל לְהִתְקַשֵּׁר בִּמְקוֹמָם הָרָאוּי לָהֶם, וְנַעֲשׂוּ מִתּוֹךְ יַיִן, וְאוֹתוֹ הַיַּיִן הִזְדַּמֵּן לָהֶם בַּמְּעָרָה בְּאוֹתוֹ לַיְלָה, וְזֶהוּ הַסּוֹד שֶׁנַּעֲשׂוּ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר, וַהֲרֵי נִתְבָּאֵר וּבֵאֲרוּהָ."],[1,"","בֹּא רְאֵה, מוֹאָב וְעַמּוֹן הֵן קָרְאוּ לָהֶם שֵׁמוֹת. מוֹאָב - מֵאָב. רַבִּי יוֹסֵי אָמַר, הַבְּכִירָה אָמְרָה בְּחֻצְפָּה, אָמְרָה מוֹאָב, מֵאַבָּא הוּא. וְהַצְּעִירָה גַּם הִיא יָלְדָה בֵּן וַתִּקְרָא שְׁמוֹ בֶּן עַמִּי. בִּצְנִיעוּת אָמְרָה בֶּן עַמִּי. בֶּן עַמִּי, וְלֹא אָמְרָה מִמִּי הוּא."],[2,"","בֹּא רְאֵה, בַּהַתְחָלָה כָּתוּב וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ, בְּוָא\"ו, וְנָקוּד עַל וָא\"ו, מִשּׁוּם שֶׁסִּיּוּעַ מִלְמַעְלָה הָיָה נִמְצָא בְּאוֹתוֹ מַעֲשֶׂה שֶׁעָתִיד מֶלֶךְ הַמָּשִׁיחַ לָצֵאת מִמֶּנּוּ, וְלָכֵן נִשְׁלַם כָּאן בְּוָא\"ו. וּבָאַחֶרֶת כָּתוּב וּבְקֻמָהּ, חָס וָי\"ו, מִשּׁוּם שֶׁלֹּא יָצָא מִמֶּנָּה חֵלֶק לַקָּבָּ\"ה כְּמוֹ הָאַחֶרֶת הַזּוֹ, וְעַל זֶה כָּתוּב בָּאַחֶרֶת הַזּוֹ הַגְּדוֹלָה וּבְקוּמָהּ בְּוָא\"ו מָלֵא וְנִקּוּד עָלָיו."],[3,"","רַבִּי שִׁמְעוֹן אָמַר, לֹא יָדַע שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲמִיד מִמֶּנָּה דָּוִד הַמֶּלֶךְ וּשְׁלֹמֹה וְכָל שְׁאָר הַמְּלָכִים וּמֶלֶךְ הַמָּשִׁיחַ. עוֹד וּבְקוּמָהּ, כְּמוֹ שֶׁכָּתוּב בְּרוּת (רות ג) וַתָּקָם בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגוֹ'. וּבְאוֹתוֹ הַיּוֹם הָיְתָה לָהּ קִימָה וַדַּאי, הִתְחַבֵּר עִמָּהּ בֹּעַז לְהָקִים שֵׁם הַמֵּת עַל נַחֲלָתוֹ, וְהוּקְמוּ מִמֶּנָּה כָּל הַמְּלָכִים הַלָּלוּ וְכָל הָעִלּוּי שֶׁל יִשְׂרָאֵל. וְלֹא יָדַע בְּשִׁכְבָהּ, שֶׁכָּתוּב וַתִּשְׁכַּב מַרְגְּלוֹתָו עַד הַבֹּקֶר. וּבְקוּמָהּ, שֶׁכָּתוּב בְּטֶרֶם יַכִּיר אִישׁ אֶת רֵעֵהוּ וְגוֹ'. מִשּׁוּם כָּךְ וּבְקוּמָהּ נָקוּד וָא\"ו."]]],[["תָּא חֲזֵי, (קה ע\"א) עִנְוְתָנוּתָא דְאַבְרָהָם דְּהָא אֲפִילּוּ בְּקַדְמִיתָא כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד דִּינָא בִּסְדוֹם לָא בָעָא מִנֵּיהּ רַחֲמֵי עַל לוֹט (דהא), לְבָתַר דִּכְתִיב וַיַּרְא וְהִנֵּה עָלָה קִיטֹר הָאָרֶץ כְּקִיטֹר הַכִּבְשָׁן לָא תָבַע עֲלֵיהּ דְּלוֹט וְלָא אָמַר עֲלֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּלוּם, אוּף הָכִי קוּדְשָׁא בְּרִיךְ הוּא לָא אָמַר לֵיהּ מִידִי, בְּגִין דְּלָא יַחֲשֹׂב אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא גָּרַע מִזְכוּתֵיהּ כְּלוּם.","וְאִי תֵימָא דְּאַבְרָהָם לָא הֲוָה חָשִׁיב לֵיהּ לְלוֹט בְּלִבֵּיהּ כְּלוּם, הָא מָסַר נַפְשֵׁיהּ לְמֵיהַךְ לְאַגָּחָא קְרָבָא בַּחֲמִשָּׁה מְלָכִין תַּקִּיפִין, כְּמָא דְאַתְּ אָמֵר, (בראשית י״ד:י״ד) וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו וְגו'. וּכְתִיב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה. וּכְתִיב וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ וְגַם אֶת לוֹט אָחִיו וּרְכֻשׁוֹ הֵשִׁיב וְגו'. אֲבָל בִּרְחִימוּתָא דִּרְחִים לְקוּדְשָׁא בְּרִיךְ הוּא וְחָמָא עוֹבָדוֹי דְלוֹט דְּלָא כַשְׁרָן כְּדְקָא יְאוּת, לָא בָעָא אַבְרָהָם דִּבְגִינֵיהּ יִשְׁבּוֹק קוּדְשָׁא בְּרִיךְ הוּא כְּלוּם מִדִּילֵיהּ, וּבְגִינֵי כָךְ לָא תָבַע עֲלֵיהּ רַחֲמֵי לָא בְּקַדְמִיתָא וְלָא בְסוֹפָא:","\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 וַיַּעַל לוֹט מִצּוֹעַר וְגו'. אָמַר רַבִּי אַבָּהוּ, בֹּא וּרְאֵה מַה כְּתִיב בַּיֵּצֶּר הָרָע, תֵּדַע לְךָ שֶׁאֵינוֹ מִתְבַּטֵל לְעוֹלָם מִבְּנֵי אָדָם עַד אוֹתוֹ זְמַן דִּכְתִיב, (יחזקאל ל״ו:כ״ו) וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וגו'. שֶׁאַף עַל פִּי שֶׁרוֹאֶה בְּנֵי אָדָם נִדּוֹנִין בַּגֵּיהִנָּם, הוּא בָּא וְחוֹזֵר לוֹ אֵצֶּל בְּנֵי אָדָם, הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר. מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם מִשָּׁם עוֹלֶה לְפַתּוֹת בְּנֵי אָדָם.","אָמַר רַבִּי יְהוּדָה שָׁלשׁ הַנְהָגוֹת יִשׁ בָּאָדָם, הַנְהָגַת הַשֵּׂכֶל וְהַחָכְמָה וזוֹ הִיא כֹּחַ הַנְּשָׁמָה הַקְּדוֹשָׁה. וְהַנְהָגַת הַתַּאֲוָה שֶׁהִיא מִתְאַוָּה בְּכָל תַּאֲוֹת רָעוֹת, וזֶהוּ כֹּחַ הַתַּאֲוָה. וְהַהַנְהָגָה הַמַנְהֶגֶת לִבְנֵי אָדָם וּמְחַזֶּקֶת הַגּוּף וְהִיא נִקְרֵאת נֶפֶשׁ הַגּוּף, אָמַר רַב דִּימִי זֶהוּ כֹּחַ הַמַּחֲזִיק.","אָמַר רַבִּי יְהוּדָה בֹּא וּרְאֵה לְעוֹלָם אֵין יֵצֶּר הָרָע שׁוֹלֵט אֶלָּא בְּאֵלּוּ ב' כֹּחוֹת אִלֵּין דְּאֲמָרָן, נֶפֶשׁ הַמִּתְאַוָּה הִיא הָרוֹדֶפֶת אַחַר יִצֶּר הָרָע לְעוֹלָם, מַשְׁמַע דִּכְתִיב וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. נֶפֶשׁ הַמִּתְאַוָּה הִיא מְעוֹרֶרֶת אֶת הָאַחֶרֶת וּמְפַתָּה אוֹתָהּ עִם הַגּוּף לְהִדָּבֵק בַּיֵּצֶּר הָרָע, והִיא אוֹמֶרֶת לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן וְנִשְׁכְּבָה עִמּוֹ. מַה יִּשׁ לָנוּ בָּעוֹלָם הַבָּא, נֵלֵךְ וְנִרְדֹּף אַחַר יִצֶּר הָרָע וְאַחַר תְּשׁוּקַת חֶמְדַת הָעוֹלָם הַזֶּה. וּמַה עוֹשׂוֹת, שְׁתֵּיהֶן מַסְכִּימוֹת לְהִדָּבֵק בּוֹ, מַה כְּתִיב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן מִתְפַּטְמוֹת לְהִתְעוֹרֵר לְיִּצֶּר הָרָע בַּאֲכִילָה וּבִשְׁתִיָּה.","וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. כְּשֶׁאָדָם שׁוֹכֵב עַל מִטָתוֹ בַּלַּיְלָה, נֶפֶשׁ הַמִתְאַוָּה הִיא הַמְעוֹרֶרֶת לַיִּצֶּר הָרָע, וּמְהַרְהֶרֶת בּוֹ, והוּא דָּבֵק בְּכָל הִרְהוּר רָע עַד שֶׁמִּתְעַבֶּרֶת מְעַט (ס\"א ממנו) (ד\"א ל\"ג על) (נ\"א עד) שֶׁמֵּבִיא בְּלֵב הָאָדָם אוֹתָהּ הַמַּחֲשָׁבָה הָרָעָה וּדְבֵקָה בּוֹ, וַעֲדַיִן יִשׁ בְּלִבּוֹ וְלֹא נִגְמַר לַעֲשׂוֹתָהּ עַד שֶׁזֹּאת הַתַּאֲוָה מְעוֹרֶרֶת לְכֹחַ הַגּוּף כְּמִתְּחִלָּה לְהִדָּבֵק בַּיֵּצֶּר הָרָע ואָז הוּא תַּשְׁלוּם הָרָעָה, הֲדָא הוּא דִכְתִיב וַתַּהֲרֶיןָ שְׁתֵּי בְּנוֹת לוֹט מֵאֲבִיהֶן.","אָמַר רַבִּי יִצְּחָק מֵעוֹלָם אֵין יִצֶּר הָרָע מִתְפַּתֶּה אֶלָּא בַּאֲכִילָה וּשְׁתִיָּה, וּמִתּוֹךְ שִׂמְחַת הַיַּיִן אָז שׁוֹלֵט בָּאָדָם. בַּצַּדִּיק מַה כְּתִיב בֵּיהּ (משלי י״ג:כ״ה) צַּדִּיק אֹכֵל לְשׂבַע נַפְשׁוֹ. ואֵינוֹ מִשְׁתַּכֵּר לְעוֹלָם, דְאָמַר רַבִּי יְהוּדָה הַאי צּוּרְבָא מֵרַבָּנָן דְמַרְוִי, קָרֵינָא עֲלֵיהּ (משלי י״א:כ״ב) נֶזְם זָהָב בְּאַף חֲזִיר. וְלֹא עוֹד אֶלָּא שֶׁמְחַלֵּל שֵׁם שָׁמַיִם. מִנְהַג הָרְשָׁעִים מַהוּ (ישעיהו כ״ב:י״ג) הִנֵּה שָׂשׂוֹן וְשִׂמְחָה. הַיַּיִן אָז שׁוֹלֵט בָּאָדָם, הָרוֹג בָּקָר וְשָׁחוֹט צֹּאן וְגו'. עֲלֵיהֶם אָמַר הַכָּתוּב (משלי ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדֹּפוּ וְגו'. כְּדֵי לְעוֹרֵר לַיִּצֶּר הָרָע, שֶׁאֵין יִצֶּר הָרָע מִתְעוֹרֵר אֶלָּא מִתּוֹךְ הַיַּיִן, הֲדָא הוּא דִּכְתִיב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן.","אָמַר רַבִּי אַבָּהוּ מַה כְּתִיב וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ. כְּלוֹמַר יֵצֶּר הָרָע אֵינוֹ מַשְׁגִּיחַ בָּהּ בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה וּבְקוּמָהּ לָעוֹלָם הַבָּא, אֶלָּא מִתְעוֹרֵר עִם כֹּחַ הַגּוּף לַעֲבֹד תַּאֲוָתוֹ בָּעוֹלָם הַזֶּה. דְּאָמַר רַבִּי אַבָּהוּ בְּשָׁעָה שֶׁנִּכְנָסִין הָרְשָׁעִים בַּגֵּיהִנָּם מַכְנִיסִים לַיֵּצֶּר הָרָע לִרְאוֹת בָּהֶן, הֲדָא הוּא דִכְתִיב וְלוֹט בָּא צֹּעֲרָה לְצַּעֲרָהּ שֶׁל גֵּיהִנֹּם, וְנָפַק לֵיהּ מִתַּמָּן לִבְרִיָּיתָא לְנַסּוּתָא כִּדְקָאֲמָרָן. הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם.","וַיִּשֶׁב בָּהָר, אָמַר רַבִּי יִצְּחָק מַשְׁמַע דִּכְתִיב בָּהָר מְלַמֵּד שֶׁהוּא שָׁם מוֹשָׁבוֹ בְּמָקוֹם הָר. גּוּף שֶׁהוּא חָרֵב כָּהָר דְּלֵית בֵּיהּ טִיבוּתָא. וּשְׁתֵּי בְּנוֹתָיו עִמּוֹ. אֵלּוּ הַב' כֹּחוֹת דְּאֲמָרָן. כִּי יָרֵא לָשֶׁבֶת בְּצּוֹעַר, יִרְאָה וַחֲרָדָה נוֹפֶלֶת עָלָיו בְּשָׁעָה שֶׁרוֹאֶה צַּעַר גֵּיהִנֹּם שֶׁמְצַּעֲרִין לָרְשָׁעִים וְחוֹשֵׁב שֶׁשָּׁם יִדּוֹן, כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ נִדּוֹן שָׁם יוֹצֵּא וְהוֹלֵךְ לְפַתּוֹת בְּנֵי אָדָם אַחֲרָיו.","רַב הוּנָא כַּד הֲוָה דָּרִישׁ לְאִזְדַּהֲרָא לִבְנֵי אָדָם, הֲוָה אָמַר לְהוּ בָּנַי אִסְתַּמָּרוּ מִשְׁלִיחָא שֶׁל גֵּיהִנֹּם, וּמַאן הוּא זֶהוּ יֵצֶּר הָרָע שֶׁהוּא שָׁלִיחַ שֶׁל גֵּיהִנֹּם.","רַבִּי אַבָּא אָמַר מַאי דִכְתִיב, (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. אֵלּוּ שְׁתֵּי בְּנוֹת לוֹט דְּאֲמָרָן, שֶׁהִיא נֶפֶשׁ הַמִּתְאַוּה, וְנֶפֶשׁ הַמִּשְׁתַּתֶּפֶת בַּגּוּף הָרוֹדֶפֶת אַחַר יִצֶּר הָרָע לְעוֹלָם. אָמַר רַבִּי יְהוֹשֻׁעַ כְּתִיב הָכָא בְּלוֹט כִּי יָרֵא לָשֶׁבֶת בְּצּוֹעַר, וּכְתִיב הָתָם לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. יָרֵ\"א בְּגִימַטְרִיָּא הוּא עֲלוּקָ\"ה. אָמַר רַבִּי יִצְּחָק אִי יָרֵא הוּא לְמַאי אָתֵי לְמִטְעֵי בְּרִיָּיתָא, אֶלָּא כָּךְ דֶּרֶךְ כָּל עוֹשֵׂה עַוְלָה, כְּשֶׁרוֹאֶה הָרָע מִתְיָרֵא לְפִי שָׁעָה, מִיָּד חוֹזֵר לְרִשְׁעָתוֹ ואֵינוֹ חוֹשֵׁשׁ לִכְלוּם, כָּךְ יֵצֶּר הָרָע בְּשָׁעָה שֶׁרוֹאֶה דִּין בָּרְשָׁעִים יָרֵא, כֵּיוָן שֶׁיּוֹצֵּא לַחוּץ (לעשות) אֵינוֹ חוֹשֵׁשׁ כְּלוּם.","רַבִּי אַבָּא אָמַר מַּהוּ דְּאֲמָּרוּ וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. מַאי אָבִינוּ זָקֵן. זֶהוּ יֵצֶּר הָרָע שֶׁנִּקְרָא זָקֵן שֶׁנֶּאֱמַר (קהלת ד׳:י״ג) מֶלֶךְ זָקֵן וּכְסִיל. שֶׁהוּא זָקֵן שֶׁנּוֹלַד עִם הָאָדָם, דְּתָנִינָן אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יוֹסֵי אוֹתָהּ נֶפֶשׁ הַמִּתְאַוָּה אוֹמֶרֶת לָאַחֶרֶת אָבִינוּ זָקֵן נִרְדֹּף אַחֲרָיו וְנִדְבַּק בּוֹ כִּשְׁאָר כָּל הָרְשָׁעִים שֶׁבָּעוֹלָם. ואִישׁ אֵין בָּאָרֶץ לָבֹא עָלֵינוּ, אֵין אִישׁ צַּדִּיק בָּאָרְץ, וְאֵין אִישׁ שַׁלִּיט עַל יִצְּרוֹ, הַרְבֵּה רְשָׁעִים בָּאָרֶץ, לֵית אֲנַן בִּלְחוֹדָנָא חַיָּיבִין, נַעֲשֶׂה כְּדֶרֶךְ כָּל הָאָרֶץ שֶׁהֵם חַיָּיבִים, שֶׁעַד הַיּוֹם דֶּרֶךְ כָּל הָאָרֶץ הוּא. לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן, נִשְׂמַח בָּעוֹלָם הַזְּה, נֹאכַל ונִשְׁתֶּה וְנִרְוְה חַמְרָא וְנִדְבַּק בְּאָבִינוּ בַּיִצֶּר הָרָע ונִשְׁכְּבָה עִמּוֹ. וְרוּחַ הַקֹּדֶשׁ צּווַֹחַת וְאוֹמֶרֶת (ישעיהו כ״ח:ז׳) גַּם אֵלֶּה בַּיַּיִן שָׁגוּ וּבַשֵּׁכָר תָּעוּ.","אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, מַה כְּתִיב ותַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. דֶּרֶךְ הָרְשָׁעִים לִטְעוֹת אַחֲרֵי הַיַּיִן לְפַנֵּק לַיֵצֶּר הָרָע וּלְעוֹרְרוֹ, ועַד שֶׁהוּא שָׂמֵחַ בְּשִׁכְרוּתוֹ שׁוֹכֵב עַל מִטָתוֹ, מִיָּד וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. הִיא מְזְמֶּנֶת עִמּוֹ וּמִתְאַוָּה וּמְהַרְהֶרֶת בְּכָל הִרְהוּרִים רָעִים, ויֵצֶּר הָרָע מִתְחַבֵּר עִמָּהּ וְנִדְבַּק בָּהּ ואֵינוֹ מַשְׁגִּיחַ בָּהּ (ס\"א מההוא זמנא) מַה הוּא מִמֶּנָּהּ. בְּשִׁכְבָהּ וּבְקוּמָהּ. בְּשִׁכְבָהּ בָּעוֹלָם הַזְּה וּבְקוּמָהּ לֶעָתִיד לָבֹא. בְּשִׁכְבָהּ בָּעוֹלָם הַבָּא כְּשֶׁתִּתֵּן דִּין וחֶשְׁבּוֹן. וּבְקוּמָהּ לְיוֹם הַדִּין דִּכְתִיב, (דניאל י״ב:ב׳) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצּוּ וְגו'. בְּשׁוּם עִנְיָן מֵאֵלּוּ אֵין מַשְׁגִּיחַ בָּהּ יִצֶּר הָרָע, אֶלָּא דָּבֵק בָּהּ והִיא נִדְבֶּקֶת בּוֹ, וּלְאַחַר כֵּן מְעוֹרֶרֶת לְאָחֳרָא לְאַחַר שֶׁהַהִרְהוּר גָּדוֹל נִדְבַּק בַּיִּצֶּר הָרָע, בָּאָה הָאַחֶרֶת וְנִדְבֶּקֶת בּוֹ"],[[0,"תא חזי ענותנותא וכו':","בוא וראה הענוה של אברהם, כי אפילו מתחלה כשרצה הקב\"ה לעשות דין בסדום, שבקש אז רחמים עליהם, עם כל זה, לא בקש ממנו רחמים על לוט. ואחר כך, שכתוב וירא והנה עלה קיטור הארץ כקיטור הכבשן, לא דרש על לוט. ולא אמר להקב\"ה עליו כלום, אף הקב\"ה לא אמר לו כלום, כדי שלא יחשוב אברהם, שהקב\"ה יגרע משהו מזכותו מחמת זה."],[1,"ואי תימא וכו':","ואם תאמר. שאברהם לא החשיב את לוט בלבו כלום. הרי אנו רואים שמסר נפשו לעשות מלחמה עם ארבעה מלכים חזקים כמו שאתה אומר, וישמע אברהם כי נשבה אחיו וגו'. אבל מתוך האהבה שאהב אברהם את הקב\"ה, וראה את המעשים של לוט שאינם ישרים כראוי,לכן לא רצה אברהם, שבשבילו יעזוב משהו הקב\"ה משלו, משום זה לא בקש עליו רחמים לא בתחילה ולא בסוף."],[6,"האי צורבא דרבנן דמרוי:","תלמיד חכם שמשתכר."]],[[0,"","בֹּא רְאֵה אֶת עַנְוְתָנוּתוֹ שֶׁל אַבְרָהָם, שֶׁהֲרֵי אֲפִלּוּ בַּתְּחִלָּה, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת דִּין בִּסְדם, לֹא בִקֵּשׁ מִמֶּנּוּ רַחֲמִים עַל לוֹט. (שהרי) אַחַר שֶׁכָּתוּב וַיַּרְא וְהִנֵּה עָלָה קִיטֹר הָאָרֶץ כְּקִיטֹר הַכִּבְשָׁן, לֹא בִקֵּשׁ עַל לוֹט וְלֹא אָמַר עָלָיו לַקָּבָּ\"ה כְּלוּם. אַף כָּךְ לֹא אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר, כְּדֵי שֶׁלֹּא יַחְשֹׁב אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַע מִזְּכוּתוֹ כְּלוּם."],[1,"","וְאִם תֹּאמַר שֶׁאַבְרָהָם לֹא הֶחְשִׁיב בְּלִבּוֹ אֶת לוֹט לִכְלוּם - הֲרֵי מָסַר נַפְשׁוֹ לָלֶכֶת לְהִלָּחֵם בַּקְּרָב עִם חֲמִשָּׁה מְלָכִים חֲזָקִים, כְּמוֹ שֶׁנֶּאֱמַר וַיִּשְׁמַע אַבְרָם כִּי נִשְׁבָּה אָחִיו, וְכָתוּב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, וְכָתוּב וַיָּשֶׁב אֵת כָּל הָרְכֻשׁ וְגַם אֶת לוֹט אָחִיו וּרְכֻשׁוֹ הֵשִׁיב וְגוֹ'. אֲבָל בָּאַהֲבָה שֶׁאָהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וְרָאָה שֶׁמַּעֲשָׂיו שֶׁל לוֹט אֵינָם כְּשֵׁרִים כָּרָאוּי, לֹא רָצָה אַבְרָהָם שֶׁבִּגְלָלוֹ יַעֲזֹב הַקָּדוֹשׁ בָּרוּךְ הוּא כְּלוּם מִשֶּׁלּוֹ, וְלָכֵן לֹא בִקֵּשׁ עָלָיו רַחֲמִים לֹא בַּתְּחִלָּה וְלֹא בַּסּוֹף."],[2,"","וַיַּעַל לוֹט מִצּוֹעַר וְגוֹ'. אָמַר רַבִּי אַבָּהוּ, בּא רְאֵה מַה כָּתוּב בַּיֵּצֶר הָרָע, תֵּדַע לְךְ שֶׁאֵינוֹ מִתְבַּטֵּל לְעוֹלָם מִבְּנֵי אָדָם עַד אוֹתוֹ זְמַן, שֶׁכָּתוּב (יחזקאל לו) וַהֲסִרֹתִי אֶת לֵב הָאֶבֶן וְגוֹ'. שֶׁאַף עַל פִּי שֶׁרוֹאֶה בְּנֵי אָדָם נִדּוֹנִין בַּגֵּיהִנֹּם, הוּא בָּא וְחוֹזֵר לוֹ אֵצֶל בְּנֵי אָדָם. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר, מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם, מִשָּׁם עוֹלֶה לְפַתּוֹת בְּנֵי אָדָם."],[3,"","אָמַר רַבִּי יְהוּדָה, שָׁלֹשׁ הַנְהָגוֹת יֵשׁ בָּאָדָם: הַנְהָגַת הַשֵּׂכֶל וְהַחָכְמָה, וְזוֹ הִיא כֹּחַ הַנְּשָׁמָה הַקְּדוֹשָׁה. וְהַנְהָגַת הַתַּאֲוָה, שֶׁהִיא מִתְאַוָּה בְּכָל תַּאֲווֹת רָעוֹת, וְזֶהוּ כֹּחַ הַתַּאֲוָה. וְהַהַנְהָגָה הַמַּנְהֶגֶת לִבְנֵי אָדָם וּמְחַזֶּקֶת הַגּוּף, וְהִיא נִקְרֵאת נֶפֶשׁ הַגּוּף. אָמַר רַבִּי דִּימִי, זֶהוּ כֹּחַ הַמַּחֲזִיק."],[4,"","אָמַר רַבִּי יְהוּדָה, בּא רְאֵה, לְעוֹלָם אֵין יֵצֶר הָרָע שׁוֹלֵט אֶלָּא בְּאֵלּוּ שְׁנֵי כֹּחוֹת אֵלּוּ שֶׁאָמַרְנוּ, נֶפֶשׁ הַמִּתְאַוָּה הִיא הָרוֹדֶפֶת אַחַר יֵצֶר הָרָע לְעוֹלָם, מַשְׁמָע שֶׁכָּתוּב וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן. נֶפֶשׁ הַמִּתְאַוָּה הִיא מְעוֹרֶרֶת אֶת הָאַחֶרֶת וּמְפַתָּה אוֹתָהּ עִם הַגּוּף לְהִדָּבֵק בַּיֵּצֶר הָרָע, וְהִיא אוֹמֶרֶת לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן וְנִשְׁכְּבָה עִמּוֹ. מַה יֵּשׁ לָנוּ בָּעוֹלָם הַבָּא, נֵלֵךְ וְנִרְדֹּף אַחַר יֵצֶר הָרָע וְאַחַר תְּשׁוּקַת חֶמְדַּת הָעוֹלָם הַזֶּה. וּמָה עוֹשׂוֹת? שְׁתֵּיהֶן מַסְכִּימוֹת לְהִדָּבֵק בּוֹ. מַה כָּתוּב? וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. מִתְפַּטְּמוֹת לְהִתְעוֹרֵר לַיֵּצֶר הָרָע בַּאֲכִילָה וּבִשְׁתִיָּה."],[5,"","וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. כְּשֶׁאָדָם שׁוֹכֵב עַל מִטָּתוֹ בַּלַּיְלָה, נֶפֶשׁ הַמִּתְאַוָּה הִיא הַמְּעוֹרֶרֶת לַיֵּצֶר הָרָע וּמְהַרְהֶרֶת בּוֹ, וְהוּא דָּבֵק בְּכָל הִרְהוּר רָע עַד שֶׁמִּתְעַבֶּרֶת מְעַט (ממנו) (ד\"א על) (נ\"א עד) שֶׁמֵּבִיא בְּלֵב הָאָדָם אוֹתָהּ הַמַּחֲשָׁבָה הָרָעָה וּדְבֵקָה בּוֹ, וַעֲדַיִן יֵשׁ בְּלִבּוֹ וְלֹא נִגְמָר לַעֲשׂוֹתָהּ עַד שֶׁ את הַתַּאֲוָה מְעוֹרֶרֶת לְכֹחַ הַגּוּף כְּמִתְּחִלָּה לְהִדָּבֵק בַּיֵּצֶר הָרָע, וְאָז הוּא תַּשְׁלוּם הָרָעָה. זֶהוּ שֶׁכָּתוּב וַתַּהֲרֶיןָ שְׁתֵּי בְּנוֹת לוֹט מֵאֲבִיהֶן."],[6,"","אָמַר רַבִּי יִצְחָק, מֵעוֹלָם אֵין יֵצֶר הָרָע מִתְפַּתֶּה אֶלָּא בַּאֲכִילָה וּשְׁתִיָּה, וּמִתּוֹךְ שִׂמְחַת הַיַּיִן אָז שׁוֹלֵט בָּאָדָם. בַּצַּדִּיק מַה כָּתוּב בּוֹ? (משלי יג) צַדִּיק אֹכֵל לְשֹׁבַע נַפְשׁוֹ, וְאֵינוֹ מִשְׁתַּכֵּר לְעוֹלָם. שֶׁאָמַר רַבִּי יְהוּדָה, אוֹתוֹ תַּלְמִיד חָכָם שֶׁשּׁוֹתֶה, קוֹרְאִים עָלָיו (שם יא) נֶזֶם זָהָב בְּאַף חֲזִיר. וְלֹא עוֹד, אֶלָּא שֶׁמְּחַלֵּל שֵׁם שָׁמַיִם. מִנְהַג הָרְשָׁעִים מַהוּ? (ישעיה כב) הִנֵּה שָׂשׂוֹן וְשִׂמְחָה. הַיַּיִן אָז שׁוֹלֵט בָּאָדָם, הָרוֹג בָּקָר וְשָׁחוֹט צֹאן וְגוֹ'. עֲלֵיהֶם אָמַר הַכָּתוּב (שם ה) הוֹי מַשְׁכִּימֵי בַבֹּקֶר שֵׁכָר יִרְדּפוּ וְגוֹ'. כְּדֵי לְעוֹרֵר לַיֵּצֶר הָרָע, שֶׁאֵין יֵצֶר הָרָע מִתְעוֹרֵר אֶלָּא מִתּוֹךְ הַיַּיִן. זֶהוּ שֶׁכָּתוּב וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן."],[7,"","אָמַר רַבִּי אַבָּהוּ, מַה כָּתוּב? וְלֹא יָדַע בְּשִׁכְבָהּ וּבְקוּמָהּ. כְּלוֹמַר, יֵצֶר הָרָע אֵינוֹ מַשְׁגִּיחַ בָּהּ בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה וּבְקוּמָהּ לָעוֹלָם הַבָּא, אֶלָּא מִתְעוֹרֵר עִם כֹּחַ הַגּוּף לַעֲבֹד תַּאֲוָתוֹ בָּעוֹלָם הַזֶּה. שֶׁאָמַר רַבִּי אַבָּהוּ, בְּשָׁעָה שֶׁנִּכְנסִים הָרְשָׁעִים בַּגֵּיהִנֹּם, מַכְנִיסִים לַיֵּצֶר הָרָע לִרְאוֹת בָּהֶן, זֶהוּ שֶׁכָּתוּב וְלוֹט בָּא צֹעֲרָה, לְצַעֲרָהּ שֶׁל גֵּיהִנֹּם. וְיָצָא לוֹ מִשָּׁם לְנַסּוֹת אֶת הַבְּרִיּוֹת, כְּמוֹ שֶׁאָמַרְנוּ. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר - מִצַּעֲרָהּ שֶׁל גֵּיהִנֹּם."],[8,"","וַיִּשֱׁב בָּהָר - אָמַר רַבִּי יִצְחָק, מַשְׁמָע שֶׁכָּתוּב בָּהָר, מְלַמֵּד שֶׁהוּא שָׂם מוֹשָׁבוֹ בִּמְקוֹם הַר. גּוּף שֶׁהוּא חָרֵב כְּמוֹ הַר שֶׁאֵין בּוֹ טוֹבָה. וּשְׁתֵּי בְנֹתָיו עִמּוֹ - אֵלּוּ שְׁתֵּי הַכֹּחוֹת שֶׁאָמַרְנוּ. כִּי יָרֵא לָשֶׁבֶת בְּצוֹעַר - יִרְאָה וַחֲרָדָה נוֹפֶלֶת עָלָיו בְּשָׁעָה שֶׁרוֹאֶה צַעַר גֵּיהִנֹּם שֶׁמְּצַעֲרִין לָרְשָׁעִים וְחוֹשֵׁב שֶׁשָּׁם יִדּוֹן. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ נִדּוֹן שָׁם, יוֹצֵא וְהוֹלֵךְ לְפַתּוֹת בְּנֵי אָדָם אַחֲרָיו."],[9,"","רַב הוּנָא כְּשֶׁהָיָה דוֹרֵשׁ לְהַזְהִיר אֶת בְּנֵי הָאָדָם, הָיָה אוֹמֵר לָהֶם: בָּנַי, הִשָּׁמְרוּ מִשָּׁלִיחַ שֶׁל גֵּיהִנֹּם, וּמִיהוּ? זֶה יֵצֶר הָרָע, שֶׁהוּא שָׁלִיחַ שֶׁל גֵּיהִנֹּם."],[10,"","רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁכָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב? אֵלּוּ שְׁתֵּי בְּנוֹת לוֹט שֶׁאָמַרְנוּ, שֶׁהִיא נֶפֶשׁ הַמִּתְאַוָּה, וְנֶפֶשׁ הַמִּשְׁתַּתֶּפֶת בַּגּוּף הָרוֹדֶפֶת אַחַר יֵצֶר הָרָע לְעוֹלָם. אָמַר רַבִּי יְהוֹשֻׁעַ, כָּתוּב כָּאן בְּלוֹט כִּי יָרֵא לָשֶׁבֶת בְּצוֹעַר, וְכָתוּב שָׁם לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. יָרֵ\"א בְּגִימַטְרִיָּא הוּא עֲלוּקָ\"ה. אָמַר רַבִּי יִצְחָק, אִם יָרֵא הוּא, אָז לָמָּה הוּא בָּא לְהַטְעוֹת אֶת הַבְּרִיּוֹת? אֶלָּא כָּךְ דֶּרֶךְ כָּל עוֹשֵׂה עַוְלָה - כְּשֶׁרוֹאֶה הָרָע, מִתְיָרֵא לְפִי שָׁעָה, וּמִיָּד חוֹזֵר לְרִשְׁעָתוֹ וְאֵינוֹ חוֹשֵׁשׁ לִכְלוּם. כָּךְ יֵצֶר הָרָע, בְּשָׁעָה שֶׁרוֹאֶה דִין בָּרְשָׁעִים, יָרֵא. כֵּיוָן שֶׁיּוֹצֵא לַחוּץ (לעשות), אֵינוֹ חוֹשֵׁשׁ כְּלוּם."],[11,"","רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁאָמְרוּ וַתֹּאמֶר הַבְּכִירָה אֶל הַצְּעִירָה אָבִינוּ זָקֵן? מַה זֶּה אָבִינוּ זָקֵן? זֶהוּ יֵצֶר הָרָע שֶׁנִּקְרָא זָקֵן, שֶׁנֶּאֱמַר (קהלת ד) מֶלֶךְ זָקֵן וּכְסִיל. שֶׁהוּא זָקֵן, שֶׁנּוֹלַד עִם הָאָדָם. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי יוֹסֵי, אוֹתָהּ נֶפֶשׁ הַמִּתְאַוָּה אוֹמֶרֶת לָאַחֶרֶת: אָבִינוּ זָקֵן, נִרְדֹּף אַחֲרָיו וְנִדְבַּק בּוֹ כִּשְׁאָר כָּל הָרְשָׁעִים שֶׁבָּעוֹלָם. וְאִישׁ אֵין בָּאָרֶץ לָבֹא עָלֵינוּ - אֵין אִישׁ צַדִּיק בָּאָרֶץ וְאֵין אִישׁ שַׁלִּיט עַל יִצְרוֹ. הַרְבֵּה רְשָׁעִים בָּאָרֶץ, אֵין אֲנַחְנוּ בִּלְבַדֵּנוּ רְשָׁעִים, נַעֲשֶׂה כְּדֶרֶךְ כָּל הָאָרֶץ שֶׁהֵם רְשָׁעִים, שֶׁעַד הַיּוֹם דֶּרֶךְ כָּל הָאָרֶץ הוּא. לְכָה נַשְׁקֶה אֶת אָבִינוּ יַיִן - נִשְׂמַח בָּעוֹלָם הַזֶּה, נֹאכַל וְנִשְׁתֶּה וְנִרְוֶה יַיִן וְנִדְבַּק בְּאָבִינוּ, בַּיֵּצֶר הָרָע, וְנִשְׁכְּבָה עִמּוֹ. וְרוּחַ הַקֹּדֶשׁ צוֹוַחַת וְאוֹמֶרֶת: (ישעיה כח) גַּם אֵלֶּה בַּיַּיִן שָׁגוּ וּבַשֵּׁכָר תָּעוּ."],[12,"","אָמַר רַבִּי יְהוּדָה, בּא רְאֵה מַה כָּתוּב? וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. דֶּרֶךְ הָרְשָׁעִים לִטְעוֹת אַחֲרֵי הַיַּיִן, לְפַנֵּק לַיֵּצֶר הָרָע וּלְעוֹרְרוֹ. וְעַד שֶׁהוּא שָׂמֵחַ בְּשִׁכְרוּתוֹ שׁוֹכֵב עַל מִטָּתוֹ, מִיָּד - וַתָּקָם הַבְּכִירָה וַתִּשְׁכַּב אֶת אָבִיהָ. הִיא מְזֻמֶּנֶת עִמּוֹ וּמִתְאַוָּה וּמְהַרְהֶרֶת בְּכָל הִרְהוּרִים רָעִים, וְיֵצֶר הָרָע מִתְחַבֵּר עִמָּהּ וְנִדְבָּק בָּהּ וְאֵינוֹ מַשְׁגִּיחַ בָּהּ (באותו זמן) מַה הוּא מִמֶּנָּה. בְּשִׁכְבָהּ וּבְקוּמָהּ - בְּשִׁכְבָהּ בָּעוֹלָם הַזֶּה, וּבְקוּמָהּ לֶעָתִיד לָבֹא. בְּשִׁכְבָהּ - בָּעוֹלָם הַבָּא כְּשֶׁתִּתֵּן דִּין וְחֶשְׁבּוֹן, וּבְקוּמָהּ - לְיוֹם הַדִּין, שֶׁכָּתוּב (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ וְגוֹ'. בְּשׁוּם עִנְיָן מֵאֵלּוּ אֵין מַשְׁגִּיחַ בּוֹ יֵצֶר הָרָע, אֶלָּא דָּבֵק בָּהּ וְהִיא נִדְבֶּקֶת בּוֹ, וּלְאַחַר כֵּן מְעוֹרֶרֶת לָאַחֶרֶת. לְאַחַר שֶׁהַהִרְהוּר גָּדוֹל נִדְבַּק בַּיֵּצֶר הָרָע, בָּאָה הָאַחֶרֶת וְנִדְבֶּקֶת בּוֹ,"]]],[["וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יָיִן. כְּמוֹ כֵן לְעוֹרֵר לַיִּצֶּר הָרָע וְנִדְבֶּקֶת בּוֹ ואֲזַי תַּשְׁלוּם הָרָעוֹת לַעֲשׂוֹת וּמִתְעַבְּרוֹת שְׁתֵּיהֶן מִיִּצֶּר הָרָע, הֲדָא הוּא דִכְתִיב וַתַּהֲרֶין שְׁתֵּי בְנוֹת לוֹט מֵאֲבֵיהֶן. עַד שֶׁיָּצָּא לַפֹּעַל מַעֲשֵׂיהֶן זוֹ יוֹלֶדֶת רִשְׁעָתָהּ וזוֹ יוֹלֶדֶת רִשְׁעָתָהּ, וְכֵן דַּרְכָּם שֶׁל רְשָׁעִים בְּעִנְיַן זְה עִם יִצֶּר הָרָע, עַד שֶׁהוֹרֵג לָאָדָם וּמוֹלִיכוֹ לַגֵּיהִנֹּם וּמַכְנִיסוֹ שָׁם, וְאַחַר כָּךְ עוֹלֶה מִשָּׁם לְפַתּוֹת לִבְנֵי אָדָם כְּמוֹ כֵן. וּמִי שֶׁמַּכִּיר בּוֹ נִצֹּל מִמֶּנּוּ וְאֵינוֹ מִתְחַבֵּר עִמּוֹ.","אָמַר רַבִּי יִצְּחָק מָשָׁל לְמָה הַדָּבָר דּוֹמֶה, לְכַתְּ לִסְטִים שֶׁהָיוּ אוֹרְבִים בַּדְּרָכִים לִגְזֹל וְלַהֲרֹג לִבְנֵי אָדָם, וּמַפְרִישִׁים מֵהֶם אֶחָד שֶׁיּוֹדֵעַ לְהָסִית לִבְנֵי אָדָם וּלְשׁוֹנוֹ רַךְ, מֶה עָבִיד מַקְדִּים וְהוֹלֵךְ לְקַבְּלָם וְנַעֲשָׂה כְּעֶבֶד לִפְנֵיהֶם עַד שֶׁמַּאֲמִינִים הַטִפְּשִׁים בּוֹ וּבוֹטְחִים בְּאַהֲבָתוֹ וּבְשִׂיחָתוֹ וּשְׂמֵחִים עִמּוֹ, וּמוֹלִיכָם בְּחֵלֶק דְּבָרָיו בְּאוֹתוֹ הַדֶּרֶךְ שֶׁהַלִּסְטִים שָׁם, כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג בָּם, לְאַחַר שֶׁנּוֹתְנָם בְּיַד הַלִּסְטִים לְהָרְגָּם וְלָקַחַת מָמוֹנָם, וְאִנּוּן צָּוְוחִין וְאָמְרִין וַוי דַּאֲצִּיתְנָא לְדֵין וְלִרְכִּיכָא דְּלִישְׁנֵיהּ. לְאַחַר שֶׁהָרְגוּ אֵלֶּה, עוֹלֶה מִשָּׁם וְיוֹצֵּא לְפַתּוֹת לִבְנֵי אָדָם כְּמִתְּחִלָּה. הַפִּקְחִים מָה הֵם עוֹשִׂים כְּשֶׁרוֹאִים לָזֶה יוֹצֵּא לִקְרָאתָם וּמְפַתֶּה לָהֶם, מַכִּירִין בּוֹ שֶׁהוּא צּוֹדֶה אֶת נַפְשָׁם וְהוֹרְגִּים אוֹתוֹ וְהוֹלְכִים בְּדֶרֶךְ אַחֶרֶת. כָּךְ הוּא יִצֶּר הָרָע יוֹצֵּא מִכַּתְ הַלִּסְטִים עוֹלֶה מִגֵּיהִנֹּם לְקָבְלָא דִּבְנֵי נָשָׁא וּלְפַתּוֹת לָהֶם בְּחֵלֶק מֶתֶק דְּבָרָיו, הֲדָא הוּא דִכְתִיב וַיַּעַל לוֹט מִצּוֹעַר וַיִּשֶׁב בָּהָר וגו'. כְּמוֹ לִסְטִים לֶאֱרֹב לִבְנֵי אָדָם, מַה עוֹשֶׂה עוֹבֵר לִפְנֵיהֶם, וְהַטִפְּשִׁים מַאֲמֲינִים בּוֹ וּבְאַהֲבָתוֹ שֶׁהוּא הוֹלֵךְ לְפַתּוֹתָם וְעוֹבֵד לָהֶם כְּעֶבֶד, שֶׁנּוֹתֵן לָהֶם נָשִׁים יָפוֹת אֲסוּרוֹת, נוֹתֵן לָהֶם בְּנֵי אָדָם לְהָרַע, מְפָרֵק מֵהֶם עֹל תּוֹרָה וְעֹל מַלְכוּת שָׁמַיִם. הַטִפְּשִׁים רוֹאִים כָּךְ, בּוֹטְחִים בְּאַהֲבָתוֹ, עַד שֶׁהוֹלֵךְ עִמָּהֶם וּמוֹלִיכָם בְּאוֹתוֹ דֶּרֶךְ שֶׁהַלִּסְטִים שָׁם, בְּדֶרֶךְ גֵּיהִנֹּם אֲשֶׁר אֵין דֶּרֶךְ לִנְטוֹת יָמִין וּשְׂמֹאל, כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג לָהֶם, וְנַעֲשָׂה לָהֶם מַלְאַךְ הַמָּוְת וּמַכְנִיסָן לַגֵּיהִנֹּם, וּמוֹרִידִין לְהוֹן מַלְאֲכֵי חַבָּלָה, וְאִנּוּן צָּוְוחִין וְאָמְרִין וַוי דַּאֲצִּיתְנָא לְדֵין, וְלָא מְהַנְיָא לוֹן. לְאַחַר כֵּן עוֹלֶה מִשָּׁם וְיוֹצֵּא לְפַתּוֹת לִבְנֵי אָדָם. הַפִּקְחִין כְּשֶׁרוֹאִין אוֹתוֹ מַכִּירִים אוֹתוֹ וּמִתְגַּבְּרִים עָלָיו עַד שֶׁשּׁוֹלְטִין עָלָיו, וסָאטִין מִזֶּה הַדֶּרֶךְ וְלוֹקְחִין דֶּרֶךְ אַחֶרֶת לְהִנָּצֵּל מִמֶּנּוּ."],[[1,"ואינון צווחין ואומרין ווי דאציתנא לדין ולרכיכא דלישניה:","והם צועקים ואומרים ווי ששמענו לזה היינו ליצר הרע, ולרכות לשונו."],[1,"ווי דאציתנא לדין:","ווי ששמענו לזה, ליצר הרע. כלומר שמתחרטים, \u0003ולא מהניא לון,\u0004 ואינו מועיל להם, כי חרטה ותשובה מועיל רק בחיים ולא לאחר מיתה."]],[[0,"","וַתַּשְׁקֶיןָ אֶת אֲבִיהֶן יַיִן. כְּמוֹ כֵן לְעוֹרֵר לַיֵּצֶר הָרָע וְנִדְבֶּקֶת בּוֹ, וַאֲזַי תַּשְׁלוּם הָרָעוֹת לַעֲשׂוֹת, וּמִתְעַבְּרוֹת שְׁתֵּיהֶן מִיֵּצֶר הָרָע. זֶהוּ שֶׁכָּתוּב וַתַּהֲרֶיןָ שְׁתֵּי בְנוֹת לוֹט מֵאֲבִיהֶן. עַד שֶׁיָּצָא לַפֹּעַל מַעֲשֵׂיהֶן - זוֹ יוֹלֶדֶת רִשְׁעָתָהּ, וְזוֹ יוֹלֶדֶת רִשְׁעָתָהּ. וְכֵן דַּרְכָּם שֶׁל רְשָׁעִים בְּעִנְיָן זֶה עִם יֵצֶר הָרָע, עַד שֶׁהוֹרֵג לָאָדָם וּמוֹלִיכוֹ לַגֵּיהִנֹּם וּמַכְנִיסוֹ שָׁם, וְאַחַר כָּךְ עוֹלֶה מִשָּׁם לְפַתּוֹת לִבְנֵי אָדָם כְּמוֹ כֵן. וּמִי שֶׁמַּכִּיר בּוֹ, נִצּוֹל מִמֶּנּוּ וְאֵינוֹ מִתְחַבֵּר עִמּוֹ."],[1,"","אָמַר רַבִּי יִצְחָק, מָשָׁל לְמָה הַדָּבָר דּוֹמֶה? לְכַת לִסְטִים שֶׁהָיוּ אוֹרְבִים בַּדְּרָכִים לִגְזל וְלַהֲרֹג לִבְנֵי אָדָם, וּמַפְרִישִׁים מֵהֶם אֶחָד שֶׁיּוֹדֵעַ לְהָסִית לִבְנֵי אָדָם וּלְשׁוֹנוֹ רַךְ. מָה עוֹשֶׂה? מַקְדִּים וְהוֹלֵךְ לְקַבְּלָם וְנַעֲשֶׂה כְּעֶבֶד לִפְנֵיהֶם, עַד שֶׁמַּאֲמִינִים הַטִּפְּשִׁים בּוֹ וּבוֹטְחִים בְּאַהֲבָתוֹ וּבְשִׂיחָתוֹ וּשְׂמֵחִים עִמּוֹ, וּמוֹלִיכָם בְּחֵלֶק דְּבָרָיו בְּאוֹתוֹ הַדֶּרֶךְ שֶׁהַלִּסְטִים שָׁם. כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג בָּם לְאַחַר שֶׁנּוֹתְנָם בְּיַד הַלִּסְטִים לְהָרְגָם וְלָקַחַת מָמוֹנָם. וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי שֶׁהִקְשַׁבְנוּ לוֹ וּלְרֹךְ לְשׁוֹנוֹ. לְאַחַר שֶׁהָרְגוּ אֵלֶּה, עוֹלֶה מִשָּׁם וְיוֹצֵא לְפַתּוֹת בְּנֵי אָדָם כְּמִתְּחִלָּה. הַפִּקְחִים מַה הֵם עוֹשִׂים כְּשֶׁרוֹאִים לָזֶה יוֹצֵא לִקְרָאתָם וּמְפַתֶּה לָהֶם? מַכִּירִין בּוֹ שֶׁהוּא צוֹדֶה אֶת נַפְשָׁם, וְהוֹרְגִים אוֹתוֹ, והוֹלְכִים בְּדֶרֶךְ אַחֶרֶת. כָּךָ הוּא יֵצֶר הָרָע, יוֹצֵא מִכַּת הַלִּסְטִים, עוֹלֶה מִגֵּיהִנֹּם כְּנֶגֶד בְּנֵי אָדָם וּלְפַתּוֹת לָהֶם בְּחֵלֶק מֶתֶק דְּבָרָיו. זֶהוּ שֶׁכָּתוּב וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר וְגוֹ'. כְּמוֹ לִסְטִים לֶאֱרֹב לִבְנֵי אָדָם. מָה עוֹשֶׂה? עוֹבֵר לִפְנֵיהֶם, וְהַטִּפְּשִׁים מַאֲמִינִים בּוֹ וּבְאַהֲבָתוֹ שֶׁהוּא הוֹלֵךְ לְפַתּוֹתָם וְעוֹבֵד לָהֶם כְּעֶבֶד, שֶׁנּוֹתֵן לָהֶם נָשִׁים יָפוֹת אֲסוּרוֹת, נוֹתֵן לָהֶם בְּנֵי אָדָם לְהָרַע, מְפָרֵק מֵהֶם עֹל תוֹרָה וְעֹל מַלְכוּת שָׁמַיִם. הַטִּפְּשִׁים רוֹאִים כָּךְ, בּוֹטְחִים בְּאַהֲבָתוֹ, עַד שֶׁהוֹלֵךְ עִמָּהֶם וּמוֹלִיכָם בְּאוֹתוֹ דֶרֶךְ שֶׁהַלִּסְטִים שָׁם, בְּדֶרֶךְ גֵּיהִנֹּם אֲשֶׁר אֵין דֶּרֶךְ לִנְטוֹת יָמִין וּשְׂמֹאל. כֵּיוָן שֶׁמַּגִּיעַ עִמָּהֶם לְשָׁם, הוּא הָרִאשׁוֹן שֶׁהוֹרֵג לָהֶם, וְנַעֲשֶׂה לָהֶם מַלְאַךְ הַמָּוֶת וּמַכְנִיסָן לַגֵּיהִנֹּם, וּמוֹרִידִים לָהֶם מַלְאֲכֵי חַבָּלָה, וְהֵם צוֹוְחִים וְאוֹמְרִים: אוֹי שֶׁהִקְשַׁבְנוּ לָזֶה. וְלֹא מוֹעִיל לָהֶם. לְאַחַר כֵּן עוֹלֶה מִשָּׁם וְיוֹצֵא לְפַתּוֹת לִבְנֵי אָדָם. הַפִּקְחִים כְּשֶׁרוֹאִים אוֹתוֹ, מַכִּירִים אוֹתוֹ, וּמִתְגַּבְּרִים עָלָיו עַד שֶׁשּׁוֹלְטִים עָלָיו, וְסוֹטִים מִזֶּה הַדֶּרֶךְ וְלוֹקְחִים דֶּרֶךְ אַחֶרֶת לְהִנָּצֵל מִמֶּנּוּ."]]],[["רַב יוֹסֵף כַּד הֲוָה נָחִית לְבָבֶל חָמָא אִנּוּן רַוָּוקַיָא דְּהֲווּ עַיְילֵי וְנָפְקֵי בֵּינִי נַשֵּׁי שַׁפִּירִין ולָא חָטָאן, אָמַר לוֹן לָא מִסְתָּפוּ אִלֵּין מִיִצֶּר הָרָע, אָמְרוּ לֵיהּ לָא מִקּוֹנְדִיטוֹן בִּישָׁא קָאֲתֵינָא, מִקְדוּשָׁתָא דְּקַדִּישָׁא אִתְגַּזַּרְנָא, דְּאָמַר רַב יְהוּדָה אָמַר רַב צָּרִיךְ אָדָם לְקַדֵּשׁ עַצְּמוֹ בִּשְׁעַת תַּשְׁמִישׁ, וְנָפְקֵי מִנִּיהּ בְּנִי קַדִּישֵׁי בְּנִי מַעֲלֵי דְּלָא מִסְתָּפוּ מִיֵצֶּר הָרָע שֶׁנְּאֱמַר (ויקרא כ׳:ז׳) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים.","רַבִּי אַבָּא אָמַר מַאי דִכְתִיב, (יחזקאל כ׳:כ׳) וְאֶת שַׁבְּתוֹתַי קַדֵּשׁוּ, אֶלָּא אֵין עוֹנָתָן שֶׁל תַּלְמִּידֵּי חֲכָמִים אֶלָּא מִשַּׁבָּת לְשַׁבָּת, וּמַזְהַר לְהוּ דְּהוֹאִיל דְּתַשְׁמִישׁ הַמִּטָה דְּמִצְּוָה הוּא, קַדֵּשׁוּ. כְּלוֹמַר קַדְשׁוּ עַצְּמְכֶם בְּשַׁבְּתוֹתַי בְּהַהוּא תַּשְׁמִישׁ דְּמִצְּוה. אָמַר רַב יְהוּדָה אָמַר רַב הַאי מַאן דְּעָיִיל לְקַרְתָּא וְחָמֵי נַשֵּׁי שַׁפִּירָן, יַרְכִּין עֵינוֹי וְיֵימָא הָכִי, בָּךְ (נ\"א סך) סָפָאן אִיגְזַר אִיגְזַרְנָא (קרדינא) קַרְדִיטָא תְּקִיל פּוּק פּוּק דְּאֲבוֹי קַדִּישָׁא דְּשַׁבַּתָּא הוּא. מַאי טַעְמָא דְּחֲמִימוּת דְּאָרְחָא שָׁלַט בֵּיהּ וְיָכִיל יִצֶּר הָרָע לְשָׁלְטָא עֲלוֹי, (עד כאן מדרש הנעלם)","ויעל לוט מצוער וגו' מגו הורמנותא דמלכא אתפרשא מסטרא דימינא חד התוכא דקטורא דגולפא מתדבקא בגו התוכא דדהבא מסטרא דשמאלא בגו מסאבו (דיצריה) (נ\"א ודיוריה) ואתעביד דקטורא חדא דאילנא","כד בעא יצחק לאתערא בעלמא בתוקפיה דדינא קשיא אתתקף ופריש דרגין מקיומייהו ואתתקף אברהם ופריש ההוא דקטורא חדא דאילנא מגו ההוא מסאבו,","ההוא נחש קדמאה עאל באנביה דההוא אילנא ואיהו חמרא דשתא ואוליד תרין דרגין קטירין דא בדא ואינון דרגין דסחרן בסטר מסאבו חד אקרי מלכו\"ם וחד אקרי פעו\"ר","דא עיטא דאתכסיא ודא עיטא דאתגליא, פעור דאתגליא איהו וכל עובדוי באתגליא, מלכו\"ם דאתכסיא איהו וכל עובדוי באתכסיא מאלין תרין אתפרשן זינין סגיאין לזנייהו וסחרן ימא רבא ולכל אלין סטרי מסאבו, וכל חד וחד שף (נ\"א נזף) לדוכתיה,","כגוונא דא איהו לתתא, לוט אתפרש מאברהם ושוי דיוריה באנשי סדום כד אתער דינא בהו אדכר לאברהם ושלח ליה מתמן ואתפריש מנייהו,","יין אשקיאו ליה בנתיה ואולידו בהו תרין אומין חד אקרי עמון וחד אקרי מואב, חד באתגליא וחד באתכסיא, עמון דרגא (קעג א) דיליה מלכו\"ם עיטא דאתכסיא, מואב דרגא דיליה פעו\"ר כלא באתגליא","כגוונא דא בנתיה דא אמרת בן עמי ברא אית לי מעמי ולא אמרת ממאן הוא בגין כך איהו הוה באתכסיא, דא אמרת מואב מאב הוא דנא, מאבא אולידת ליה, דרגא דיליה פעו\"ר מלה באתגליא,","ובתרין אלין אחיד דוד מלכא לבתר מן מואב אתת רות ונפק מנה דוד מלכא, מן עמון אתעטר דוד מלכא בהאי עטרא דאיהי סהדותא לזרעא דדוד דכתיב (מלכים ב י״א:י״ב) ויתן עליו את הנזר ואת העדות והאי הות מן מלכום דרגא דבני עמון דכתיב (שמואל ב י״ב:ל׳) ויקח את עטרת מלכם,","מלכם דרגא דבני עמון הוא דכתיב ותהי על ראש דוד, ומתמן הוה סהדותא לבנוי לעלמין ובה אשתמודע מאן דאיהו מן בנוי דדוד דאתחזי למלכא ודאי דאמרין מן דוד הוא (הגוף) דאפילו אתיליד בההוא יומא יכיל הוה למסבל ההיא עטרא על רישיה (דהא איהו) דהות משקל ככר זהב ואבן יקרה הות וב\"נ אחרא לא יכיל למסבלא ודא הוא דכתיב ביואש ויתן עליו את הנזר ואת העדות,","ובתרין דרגין אתאחיד דוד מלכא ואינון תוקפא דמלכותיה לאתתקפא על שאר עמין דאי לא אתכליל בסטרא דלהון לא יכיל לאתתקפא עלייהו כל (גוונין) דרגין דשאר עמין כלילן ביה בדוד לאתגברא ולאתתקפא עלייהו:","ויעל לוט מצוער וישב בהר, כתיב (משלי ל׳:ט״ו) לעלוקה שתי בנות הב הב, אלין שתי בנות דיצר הרע דאינון מתערין ליה (ד\"א ל\"ג בגין) לשלטא בגופא חדא איהי נפש דאתרביאת תדיר בגופא וחדא איהי נפש דכסיפת בתיאובתין בישין (ד\"א ל\"ג דהאי עלמא) ובכל כסופין בישין דהאי עלמא דא איהי בכיר\"ה ודא (ד\"א ואחרא) איהי צעיר\"ה","ויצה\"ר לא אתחבר תדיר אלא בתרין אלין בגין לפתאה לבני נשא ובגין דיהמנון ליה (א) (ס\"א לאובלא) לאובדא להו לאתר גירין דמותא ויפלחון ליה כמא דאת אמר (שם ז) עד יפלח חץ כבדו,","ללסטים דמקפחי בטוריא (וכמינו) וטמירו גרמייהו באתר דחיל דטוריא וידעין דהא בני נשא אתטמרן גרמייהו למיהך באינון דוכתי מה עבדי ברירו מנייהו ההוא דחדידא בלישניה מכלא ההוא דידע למפתי בני נשא ויפוק מבינייהו ויתיב באורח מישר דכל בני עלמא עברין תמן כיון דמטא לגבייהו שרי לאתחברא תמן:","וַיִּסַּע מִשָּׁם אַבְרָהָם אַרְצָה הַנֶּגֶב. כָּל מַטְלָנוֹי הֲווּ לְסִטְרָא דְּדָרוֹמָא יַתִּיר מִסִּטְרָא אָחֳרָא, בְּגִין דְּהָא בְּחָכְמָתָא עֲבַד לְאִתְדַּבְּקָא בְּדָרוֹמָא:","וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחוֹתִי הִיא. תָּנִינָן (כיון) לָא לִיבָּעֵי לֵיהּ לְבַר נָשׁ לְסָמְכָא עַל נִיסָא, וְאִי קוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ נִיסָא לְבַּר נָשׁ, לָא אִית לֵיהּ לְסָמְכָא (תדיר) עַל נִיסָא זִמְנָא אָחֳרָא. בְּגִין דְּלָאו בְּכָל שַׁעֲתָא וְשַׁעֲתָא אִתְרְחִישׁ נִיסָא.","וְאִי יֵיעוּל בַּר נָשׁ גַּרְמֵיהּ בְּאֲתַר דְּנִזְקָא אִשְׁתְּכַח לְעֵינָא, הָא פָּקַע כָּל זְכוּתֵיהּ דְּעֲבַד בְּקַדְמִיתָא וְאוּקְמוּהָ. כְּמָא דְאַתְּ אָמֵר, (בראשית ל״ב:י״א) קָטוֹנְתִּי מִכָּל הַחֲסָדִים וּמִכָּל הָאֱמֶת וְגו'. וְאַבְרָהָם כֵּיוָן דְּסָלִיק מִמִּצְרַיִם וְאִשְׁתְּזִיב זִמְנָא חָדָא, הַשְׁתָּא אַמַּאי אָעִיל גַרְמֵיהּ בְּצַעֲרָא כְּקַדְמִיתָא וְאָמַר אֲחוֹתִי הִיא.","אֶלָּא אַבְרָהָם לָא סָמִיךְ עַל גַּרְמֵיהּ כְּלוּם, וְחָמָא שְׁכִינְתָּא תָּדִיר בְּדִיּוּרָהּ דְּשָׂרָה וְלָא אַעֲדֵי מִתַּמָּן, וּבְגִין דְּהֲוַת תַּמָּן, אַסְמִיךְ אַבְרָהָם וְאָמַר אֲחוֹתִי הִיא כְּמָה דִכְתִיב (משלי ז׳:ד׳) אֱמֹר לַחָכְמָה אֲחוֹתִי אָתּ. וּבְגִין כָּךְ אָמַר אֲחוֹתִי הִיא (ס\"א את):","וַיָּבֹא אֱלהִים אֶל אֲבִימֶלֶךְ וְגו'. וְכִי קוּדְשָׁא בְּרִיךְ הוּא אֲתָא לְגַבַּיְיהוּ דְּרַשִּׁיעַיָּא כְּמָה דִכְתִיב, (במדבר כ״ב:ט׳) וַיָּבֹא אֱלהִים אֶל בִּלְעָם. (בראשית ל״א:כ״ד) וַיָּבֹא אֱלהִים אֶל לָבָן. אֶלָּא הַהוּא מְמַנָּא שְׁלִיחָא דְּאִתְפַּקְּדָא עֲלַיְיהוּ הֲוָה, בְּגִין דְּכֻלְהוּ כַּד עָבְדֵי שְׁלִיחוּתָא נַטְלֵי שְׁמָא דָא, וּמִסִּטְרָא דְדִינָא קָא אַתְיָין. וְעַל דָּא וַיָּבֹא אֱלהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִנְךָ מֵת עַל הָאִשָּׁה אֲשֶׁר לָקַחְתָּ וְגו'.","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי י״ב:י״ט) שְׂפַת אֱמֶת וְגו'. שְּׂפַת אֱמֶת תִּכּוֹן לָעַד. דָּא אַבְרָהָם, דְּכָל מִלּוֹי בְּקַדְמִיתָא וּבְסוֹפָא הֲווּ בֶּאֱמֶת. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר. דָּא אֲבִימֶלֶךְ.","בְּאַבְרָהָם נֶאֱמַר וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחוֹתִי הִיא. דָּא בְּקַדְמִיתָא, דְּאָמַר בְּגִין שְׁכִינְתָּא דְּהֲוַת עִמָּהּ דְּשָׂרָה אֲחוֹתִי הִיא, וְאַבְרָהָם בְּחָכְמְתָא עֲבַד.","מַאי טַעְמָא בְּגִין דְּאַבְרָהָם מִסִּטְרָא דְּיָמִינָא אִיהוּ, אָמַר אֲחוֹתִי הִיא, וְרָזָא כְּמָא דְאַתְּ אָמֵר, (שיר השירים ה׳:ב׳) אֲחוֹתִי רַעֲיָתִי יוֹנָתִי תַמָּתִי. וְעַל דָּא אַבְרָהָם קָרָא לָהּ תָּדִיר אֲחוֹתִי, בְּגִין דְּאִתְדָּבַּק בַּהֲדָהּ, וְלָא יִתְעַדּוּן (ויקרא קב דא מן דא לעלמין).","לְסוֹף מַה כְּתִיב וְגַם אָמְנָה אֲחוֹתִי בַת אָבִי הִיא אַךְ לא בַת אִמִּי. וְכִי הָכִי הֲוָה. אֶלָּא כֹּלָּא בְּגִין שְׁכִינְתָּא קָאֲמַר, אֲחוֹתִי הִיא בְּקַדְמִיתָא, דִּכְתִיב אֱמֹר לַחָכְמָה אֲחוֹתִי אָתְּ. וּלְבָתַר וְגַם אָמְנָה. מַאי וְגַם. לְאִתּוֹסְפָא עַל מַה דְּקָאֲמַר בְּקַדְמִיתָא. אֲחוֹתִי בַת אָבִי הִיא. בְּרַתֵּיהּ דְּחָכְמָה עִלָּאָה, וּבְגִין כָּךְ אִתְקְרֵי אֲחוֹתִי וְאִתְקְרֵי חָכְמָה. אַךְ לֹא בַת אִמִּי. מֵאֲתַר דְּשֵׁירוּתָא דְּכֹלָּא סְתִימָא עִלָּאָה. וְעַל דָּא וַתְּהִי לִי לְאִשָּׁה בְּאַחְוָה בַּחֲבִיבוּתָא דִּכְתִיב, (שיר השירים ב׳:ו׳) וִימִינוֹ תְחַבְּקֵנִי וְכֹלָּא רָזָא דְּחָכְמְתָא אִיהוּ.","תָּא חֲזֵי, בְּקַדְמִיתָא כַּד נַחְתוּ לְמִצְרַיִם הָכִי קָאֲמַר בְּגִין לְאִתְדַּבְּקָא בְּגוֹ מְהֵימְנוּתָא, וְקָרָא לָהּ אֲחוֹתִי, בְּגִין דְּלָא יִטְעוּן גּוֹ אִנּוּן דַּרְגִּין דִּלְבַר. אוּף הָכָא אֲחוֹתִי, בְּגִין דְּלָא אִתְעֲדֵי מִגּוֹ מְהֵימְנוּתָא כְּדְקָא יְאוּת.","דְּהָא אֲבִימֶלֶךְ וְכָל אִנּוּן יָתְבֵי אַרְעָא הֲווּ אָזְלֵי בָּתַר פּוּלְחָנָא נוּכְרָאָה, וְאִיהוּ אִתְדָּבַּק גּוֹ מְהֵימְנוּתָא, וּבְגִין כָּךְ עָאל לְתַמָּן וְאָמַר אֲחוֹתִי, מָה אָחוֹת לָא אִתְפְּרַשׁ מֵאָחָא לְעָלְמִין אוּף הָכָא. דְּהָא אִתְּתָא יְכִילַת לְאִתְפְּרָשָׁא אֲבָל אָחוֹת לָא אִתְפְּרַשׁ, דְּהָא תְּרֵין אַחִין לָא יָכְלִין לְאִתְפָּרְשָׁא לְעָלְמִין וּלְעָלְמֵי עָלְמִין.","וּבְגִין כָּךְ אָמַר אַבְרָהָם אֲחוֹתִי הִיא, דְּהָא כֻּלְהוֹן הֲווּ לְהוּטִין גּוֹ טָהֳרֵי כֹּכְבַיָא וּמַזָּלֵי וּפַלְחֵי לוֹן, וְאַבְרָהָם הֲוָה מִתְדְּבַּק גּוֹ מְהֵימְנוּתָא וְאָמַר אֲחוֹתִי דְּלָא נִתְפְּרַשׁ לְעָלְמִין. וְסִימָנִיךְ (ויקרא כ״א:ג׳) וְלַאֲחוֹתוֹ הַבְּתוּלָה דְּאִתְּמָר לְכֹהֵן, אַתְרָא דְּאַבְרָהָם שַׁרְיָא בֵּיהּ.","כְּתִיב, (דברים י׳:כ׳-כ״א) אֶת יְיָ אֱלהֶיךָ תִּירָא אוֹתוֹ תַעֲבֹד וּבוֹ תִדְבָּק וּבִשְׁמוֹ תִשָּׁבֵעַ. הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, לַיְיָ אֱלהֶיךָ תִּירָא לָא כְּתִיב, אֶלָּא אֶת יְיָ, מַאי אֶת, דָּא דַרְגָּא קַדְמָאָה אֲתַר דַּחֲלָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ כְּתִיב תִּירָא, דְּתַמָּן בָּעֵי בַּר נָשׁ לְדַחֲלָא קַמֵּי מָארֵיהּ (קודשא בריך הוא) בְּגִין דְּאִיהוּ (בי) דִּינָא."],[[0,"רב יוסף כד הוה וכו':","רב יוסף, כשירד לבבל ראה בחורים, פנוים מאשה, שהיו נכנסים ויוצאים בין נשים יפות ואינם חוטאים. אמר להם: אינכם מפחדים מפני יצר הרע. אמרו לו אין אנו באים מתערובת רע מקדש הקדשים נחצבנו. כלומר, שאמרו לו, שהוריהם לא היה להם מחשבות זרות. בעת שנחצבו מדם, אלא מחשבות קדושות ומקודשות, ועל כן אינם מפחדים מפני היצר הרע."],[1,"אמר ר' יהודה אמר רב וכו':","אר\"י א\"ר, כל מי שנכנס לעיר ורואה נשים יפות, ישפיל עיניו, ויאמר כך. \u0003סך ראה, ספאן, אגזר אגזרנא,\u0004 שנחצב נחצבתי מן הורים ספונים, דהיינו חשובים. \u0003קרדינא תקיל, פוק פוק,\u0004 מכשול הקשה, דהיינו הקליפה המביאה הרהורי נשים, צא צא ממני, \u0003דאבוי, קדישא דשבתא הוא.\u0004 כי פירי קדוש של שבת הוא, כלומר שנולד מזווג של שבת, שאין לקליפות אחיזה בהנולד מזווג של שבת. ושואל, מהו הטעם, שהנכנס לעיר מחייב לומר לחש הזה. ואומר שהוא משום שחמימות יגיעת הדרך שולט בו, וע\"כ יכול היצר הרע לשלוט עליו. (ע\"כ מדרש הנעלם)"],[2,"ויעל לוט מצוער וגו':","מתוך רצון המלך, נפרד מצד ימין פסולת אחת של צורת חקיקה, ומתדבקת בתוך פסולת הזהב שמצד שמאל, ובתוך הטומאה היתה דירתו, ונעשה לצורה אחת של האילן. קטורא פירושו צורה."],[2,"","פירוש. קו ימין ה\"ס חסדים מכוסים, שאין בו הארת חכמה, ובמקומו בבינה הוא בחינת ג\"ר, משום שאינה מקבלת חכמה, להיותה בסוד כי חפץ חסד הוא. אמנם כשהחסדים מתפשטים למטה לתחתונים הצריכים להארת חכמה, מתגלה בהם פסולת, כלומר הצורך שלהם להארת חכמה עושה בהם חסרון, ובכל מקום שיש חסרון, מתדבקות הקליפות, וע\"כ נבחן החסרון לפסולת, וזהו פסולת ימין. ונבחן ג\"כ \u0003לקטורא דגולפא,\u0004 כי מבחינת הקדושה אין זה חסרון, אלא \u0003צורת חקיקה\u0004 לבית קבול, דהיינו אם לא היה החסרון והחלל לא היה שם לעולם בית קבול לאורות, אבל הקליפות חושבים זה לפסולת."],[2,"","וכדי להשתלם הלכה הפסולת ונתדבקה \u0003בנו התוכא דדהבא מסטרא דשמאלא.\u0004 כי שם מאירה החכמה בלי חסדים, והסרון החסדים נחשב פסולת דקו שמאל, אמנם הפסולת דימין קבלה שם השתלמות. כי אינה חסירה יותר מחכמה. וע\"כ \u0003ואתעביד קטירא חדא דאילנא\u0004 שנעשה לצורה שלמה של אילן המדרגות. \u0003דהיינו הנוקבא,\u0004 אמנם, \u0003בגו מסאבו דיוריה,\u0004 שדירתו היתה בטומאה. כי הארת השמאל בלי ימין מאיר למקום הט מאה. וכן \u0003התוכא דדהבא\u0004 הוא טומאה."],[3,"כד בעא יצחק וכו':","כשרצה יצחק, שהוא קו שמאל דקדושה. להתעורר בעולם בתוקפו של דין הקשה. נתגבר והפריד מדרגות השמאל מקיומם. דהיינו שהפך שורשים דה' ערי סדום למעלה. שהג\"ר דמדרגות דשמאל הפיל למטה, ואת הגזרא דדינא העלה למעלה (כנ\"ל דף פ\"ג ד\"ה פנימיות). ואז נחרבו מדרגות השמאל של הקליפות והשמאל דקדושה נתחבר ונכלל עם הימין. וע\"כ \u0003ואתתקף אברהם ופריש ההוא קטורא חדא דאילנא מגו ההוא מסאבו\u0004 ונתחזק קו הימין המכונה אברהם, כי נכלל משמאל וקבל ממנו ג\"ר, אשר עם זה נתקנה ג\"כ הפסולת שלו, שאינו צריך יותר להתדבק \u0003בהתוכא דדהבא.\u0004 ונמצא שתפריד אותה הצורה מתוך הטומאה."],[4,"ההוא נחש קדמאה עאל באנביה דההוא אילנא:","אותו נחש הקדמוני נכנס בפירותיו של אילן ההוא הנ\"ל, והוא יין ששתה, והוליד שתי מדרגות קשורות זו בזו ואלו המדרגות סובבות בצד הטומאה אחת נקראת \u0003מלכם\u0004 ואחת נקראת \u0003פעור.\u0004"],[4,"","פירוש. אותה פסולת הימין שעל ידי התדבקותה בהתוכא דדהבא. קבלה צורה אחת של האילן שהוא הנוקבא דז\"א, ואחר מהפכת סדום חזרה לקדושה, היא הנחשבת עתה לפירי של האילן, והיא שתתה יין המשכר, שהוא נחש הקדמוני, שנכנס בה המסית להמשיך הג\"ר דחכמה. כמו במעשה דעץ הדעת, ואז הפירי הוליד, על ידי מעשה זו. ב' קליפות, שהן, \u0003מלכם ופעור.\u0004 שהן ב' עבודה זרות."],[5,"דא עיטא דאתכסיא ודא עיטא דאתגליא:","זו עצה נסתרת, וזו עצה נגלית, ומפרש. \u0003פעור,\u0004 הוא בנגלה, וכל מעשיו דהיינו עבודתו הוא בנגלה. \u0003מלכם,\u0004 הוא בנסתר ומכוסה, וכל מעשיו, דהיינו עבודתו המה בסתר. מאלו השנים נפרדו מיני טומאות הרבה למינן, ומסבבים את ים הגדול, שהוא הנוקבא, ואת כל בחינות הטומאה. וכל אחד ואחד נוטה אל מקומו."],[5,"","פירוש כי נמשכו, בהסתת הנחש ב' קליפות, שהם ג\"ר וו\"ק דהארת השמאל. שבטומאה, \u0003פעור\u0004 הוא ג\"ר \u0003ומלכם\u0004 הוא ו\"ק. והיו מסודרות בהיפוך מהנוקבא דקדושה, כדרך הטומאה שהוא הפוכה לקדושה. כי בנוקבא דקדושה, הג\"ר שבה דהיינו מחזה שלה ולמעלה היא במכוסה, כלומר שמכוסה מהארת חכמה. ומחזה ולמטה שבה, היא במגולה, דהיינו שהארת חכמה מתגלית שם. וכן יש בה ב' נקודין מפתחא ומנעולא, שמנעולא גנוזה בג\"ר שבה, והמפתחא שולטת בה בגלוי בו\"ק שמחזה ולמטה שבה, כנ\"ל (בהקדמת הזהר דף קכ\"ג אות קכ\"ב ד\"ה ב' ע\"ש) ואלו ב' הקליפות הם בהיפך כי הקליפה \u0003דפעור\u0004 שהיא בחינת ג\"ר שמחזה ולמעלה היא המגולה, והקליפה \u0003דמלכם,\u0004 שהיא בחינת ו\"ק שמחזה ולמטה, היא המכוסה. וכן בקליפת פעור שהוא מחזה ולמעלה מושלת המפתחא, ובקליפת מלכם שהיא מחזה ולמטה מושלת המלכות דמדת הדין הבלתי ממותקת."],[6,"כגוונא דא איהו לתתא וכו':","כעין זה שנתבאר, במה שנעשה בעולמות, נעשה גם כן בנשמות למטה. לוט, שהוא פסולת הימין, נפרד מאברהם, ושם משכנו באנשי סדום, שהם פסולת הזהב מצד השמאל, וקבל מהם שלמותו, כנ\"ל בעולמות. כאשר נתעורר הדין עליהם ונהפכו, זכר הקב\"ה את אברהם, ושלח משם את לוט, ואז נפרד מהטומאה של סדום, ושב לקדושה."],[7,"יין אשקיאו וכו':","השקוהו בנותיו יין, שהוא סוד נחש הקדמוני שנכנס בו, כנ\"ל בעולמות, והולידו שתי אומות, אחת נקראת עמון ואחת נקראת מואב, אחת בנגלה שהיא מואב, ואחת במכוסה שהיא עמון. עמון, המדרגה שלו הוא העבודה זרה, \u0003מלכם,\u0004 שהוא עצה של העלם, מואב, מדרגתו הוא \u0003פעור,\u0004 שהוא כולו בנגלה."],[8,"כגוונא דא וכו':","כעין זה היו בנותיו, זו אמרה \u0003בן עמי,\u0004 בן יש לי מעמי, לא אמרה ממי הוא, משום זה, שהוא היה בבחינת העלם. וזו אמרה \u0003מואב.\u0004 מאב הוא זה, מאבי הולדתיו. כי המדרגה שלו הוא \u0003פעור\u0004 שהוא בחינת התגלות."],[9,"ובתרין אלין אחיד וכו':","ובשנים אלו, עמון ומואב, נאחז דוד המלך. כי אחר כך, באה רות מן מואב, ויצא ממנה דוד המלך, ומן עמון נתעטר דוד המלך באותה העטרה, שהיא עדות לזרעו של דוד, שכתוב, ויתן עליו את הנזר ואת העדות. ונזר זה חיה מן מלכם, שהוא מדרגת בני עמון, שכתוב, ויקח את עטרת מלכם."],[10,"מלכם דרנא דבני עמון וכו':","מלכם הוא מדרגת בני עמון, שכתוב, ותהי על ראש דוד. ומשם היה עדות לבניו לעולם, ובה, ניכר מי שהוא מן בניו של דוד הראוי למלוכה, דהיינו אם היה יכול לישא הכתר על ראשו, ודאי אמרו שהוא מזרע דוד, שאפילו באותו יום שנולד, היה יכול לסבול את כתר על ראשו, אעפ\"י שמשקל ככר זהב ואבן יקרה היתה. ואדם אחר חוץ מזרעו לא היה יכול לסבלו. וזהו שכתוב ביואש, ויתן עליו את הנזר ואת העדות."],[11,"ובתרין דרגין אתאחיד:","ובשתי מדרגות הללו נאחז דוד המלך, והם תקפה של מלכותו, להתגבר על כל שאר האומות, שאם לא היה נכלל בצד שלהם לא היה יכול להתגבר עליהם. וכל המדרגות של שאר אומות העולם היו כלולות בדוד, כדי להתגבר ולהתחזק עליהם."],[12,"ויעל לוט מצוער וישב בהר וכו':","כתוב לעלוקה שתי בנות הב הב. אלו הן שתי בנות של יצר הרע, שהן מעוררות את היצר הרע לשלוט בגוף. אחת היא, נפש שמגודלת תמיד בגוף. ואחת היא נפש המתאוה לתאות רעות. ולכל תאות הרעות שבעולם הזה, זו היא בכירה. והאחרת, הראשונה, היא צעירה."],[13,"ויצר הרע לא אתחבר וכו':","ויצה\"ר, תמיד, אינו מתחבר אלא בשתי נפשות, הללו, כדי לפתות לבני אדם. וכדי שיאמינו בו ויוכל להובילם למקום שזורקים בהם חיצי מות ויבקיעו אותם, כמו שאתה אומר, עד יפלח חץ כבדו."],[14,"ללסטים דמקפחי וכו':","וזה דומה, לשודדים החומסים בהרים, ומסתירים עצמם במקום איום שבהרים. ויודעים שבני אדם מונעים את עצמם ללכת במקומות אלו. מה עשו, בחרו מהם. אותו, אשר יש לו לשון חדה יותר מכולם. אותו, היודע לפתות אנשים. שיצא מהם, וישב בדרך הישר, במקום, שכל בני העולם עוברים שמה, כיון שהגיע אצלם. לבני העולם, הוא מתחיל להתחבר שם עמהם, עד שמושך אותם לרשתו. ומביאם למקום האיום שהשודדים שמה, והורגים אותם. כן דרך היצר הרע שמפתה את בני העולם עד שמאמינים בו. ואז מביאם למקום חצי מות כנ\"ל. (ע\"כ סתרי תורה)"],[15,"ויסע משם אברהם ארצה הנגב:","כל מסעותיו היו לצד דרום, שהוא חסד, יותר מלצד אחר. כי בחכמה עשה זה כדי להתדבק בדרום, שהוא חסד."],[16,"ויאמר אברהם אל שרה אשתו אחותי היא וכו':","למדנו. אין לו לאדם לסמוך על נס, ואס הקב\"ה עושה פעם נס לאדם, אין לו לסמוך על הנס בפעם אחר. משום, שלא בכל שעה ושעה יקרה נס."],[17,"ואי ייעול וכו':","ואם אדם מכניס עצמו במקום שהנזק גלוי לעין, הנה מתבטלת בזה כל זכיותיו. שעשה מקודם לכן, וכבר בארוהו, כמו שאתה אומר קטונתי מכל החסדים ומכל האמת. ולפי זה שואל, ואברהם, אחר שעלה ממצרים ונצל פעם אחת, למה הכניס עצמי עתה בצער כבתחילה, ושוב אמר אחותי היא."],[18,"אלא אברהם וכו':","ומשיב, אלא אברהם לא סמך על עצמו כלום. כי ראה את השכינה תמיד במשכנה של שרה, שלא סרה משם, ומשום שהשכינה היתה שם, סמך אברהם עליה ואמר, אחותי היא. כמו שכתוב, אמור לחכמה אחותי את, שפירושה, להשכינה שנקראת חכמה. ועל כן, אמר. אחותי היא."],[19,"ויבא אלקים אל אבימלך וגו':","שואל, וכי יבא הקב\"ה אל רשעים, כמו שכתוב, ויבא אלקים אל בלעם, ויבא אלקים אל לבן, הלא רשעים היו. ומשיב, אלא הוא הממונה, השליח שנתמנה עליהם, היה, כי לכל אומה יש לה שר בשמים, משום שכל המלאכים בעת שעושים שליחות מה', מקבלים שם זה, אלקים, כי מצד הדין הם באים, והשם אלקים יורה דינים, ועל כן כתוב ויבא אלקים אל אבימלך בחלום הלילה וגו'. דהיינו רק מלאך הממונה על עמו, ולא הקב\"ה."],[20,"ר\"ש פתח ואמר וכו':","ר' שמעון פתח ואמר, שפת אמת וגו'. שפת אמת תכון לעד זהו אברהם. שכל דבריו בתחילה ובסוף היו אמת. ועד ארגיעה לשון שקר, זהו אבימלך."],[21,"באברהם נאמר וכו':","באברהם נאמר ויאמר אברהם אל שרה אשתו אחותי היא, וזהו כמו בתחילה, במצרים, שאמר על השכינה שהיתה עם שרה, אחותי היא, אף כאן אמר אחותי היא על השכינה. ואברהם בחכמה עשה הכל."],[22,"מאי טעמא וכו':","שואל מהו הטעם, שהשכינה נקראת אחות. ואומר, לפי שאברהם הוא מצד הימין. אמר אחותי היא. והסוד, כמו שאתה אומר אחותי רעיתי יונתי תמתי, וע\"כ קראה אברהם תמיד אחותי משום שנתדבק בה, ולא ימושו זה מזה לעולם. פירוש. לפי שאברהם הוא בחינת חסד, אשר בגדלות עולה החסד, ונעשה חכמה, שה\"ס או\"א עלאין שזווגם תמידי בלי הפסק, וכשהשכינה עולית שם היא נמצאת גם עם אברהם בזווג דלא פסיק. וז\"ש \u0003דלא יתעדון דא מן דא לעלמין.\u0004 ואז נקראת השכינה בשם אחותי, ולא בשם אשתי. כי אחות, היא מצד ימין, ואשה מצד שמאל היא, בסוד אש ה', (כנ\"ל פרשת נח דף פ\"א אות רל\"ב ע\"ש)"],[23,"לסוף מה כתיב וכו':","בסוף מה כתוב, וגם אמנה אחותי בת אבי היא אך לא בת אמי. ושואל, וכי היה כן באמת, הלא בת הרן היתה. ואומר, אלא הכל על השכינה אמר: אחותי היא שבתחילה, הוא כמ\"ש אמור לחכמה אחותי את. ואח\"כ כתוב \u0003וגם אמנה,\u0004 מהו \u0003וגם.\u0004 אלא הוא להוסיף ביאור, על מה שאמר בתחילה. \u0003אחותי בת אבי\u0004 פירושו, שהשכינה היא בת לחכמה העליונה, שהוא או\"א עלאין, הנקראים אבא. ומשום זה נקראת השכינה אחותו ונקראת חכמה כנ\"ל בדבור הסמוך. \u0003אך לא בת אמי,\u0004 פירושו, שאמי, היא נמשכת ממקום התחלת הכל, סתום מכל, שהוא אריך אנפין. שממנו נמשך סוד הבינה החוזרת להיות חכמה שהיא מתלבשת בישסו\"ת (כנ\"ל ב\"א דף י\"א ד\"ה זהר עש\"ה) שהם נקראים \u0003אמא,\u0004 והשכינה אינה בת, אלא שהיא כאמא עצמה, כי מלבישה עליה, \u0003ועל דא ותהי לי לאשה באחוה בחביבותא,\u0004 ועל כן, להיותה בחינת שמאל, מצד אמא, ותהי לי לאשה, באחוה ובחביבות, שכתוב \u0003וימינו תחבקני,\u0004 כי חושקת לחסדים שבימין כדי שהחכמה שבה תתלבש בחסדים. \u0003וכלא רזא דחכמתא איהו\u0004 והכל הוא סוד החכמה. וזהו שהוסיף ביאור, שמה שאמר עליה אחותי, הוא מצד או\"א, שמצדם היא בת, והיא אחות, ואינה ראויה לאשה, להיותה מימין. אבל מצד ישסו\"ת שהם אמא, אינה בת, ואינה אחות, אלא אשה, בסוד \u0003אש ה',\u0004 וראויה לזווג."],[24,"תא חזי בקדמיתא וכו':","בוא וראה, בתחילה כשירדו למצרים אמר כך, אחותי היא כדי להתדבק עם האמונה, וקרא לה \u0003אחותי,\u0004 כדי שלא יטעו באלו המדרגות שמחוץ לקדושה, אף כאן באבימלך, אמר-אחותי היא כדי שלא יסורו מן אמונה כראוי."],[25,"דהא אבימלך וכו':","כי אבימלך וכל יושבי הארץ, היו הולכים אחר עבודה זרה, והוא, אברהם, נתדבק באמונה, ומשום זה נכנס שמה ואמר, על השכינה, \u0003אחותי היא.\u0004 מה אחות אינה נפרדת מן האח לעולם, אף כאן סך, שאברהם היה דבוק עם השכינה באופן שלא יפרד ממנה לעולם. כי אשה יכולה להפרד מבעלה, אבל אחות אינה נפרדת מהאח, כי שני אחים, לא יוכלו להפרד זה מזה לעולם ולעלמי עולמים. פירוש. כי אח ואחות נמשכים מאו\"א עלאין, שהזווג שלהם אינו נפסק לעולם. ועל כן גם אח ואחות אינם נפרדים לעולם. אבל איש ואשה נמשכים מישסו\"ת, שזווגם נפסק ואינו תמידי, לכן איש ואשה יכולים להפרד גם הם."],[26,"ובגין כך וכו':","ומשום זה אמר אברהם אחותי היא, כי כולם היו להוטים אחרי האורות של כוכבים ומזלות, ועבדו להם, ואברהם היה מתדבק עם האמונה, ואמר על השכינה, \u0003אחותי,\u0004 שלא נפרד לעולם. וסימנך, ולאחותו הבתולה הנאמר לכהן, שהכהן, הוא מקום שאברהם, דהיינו ימין וחסד, שורה בו, וע\"כ נקראת השכינה אליו, \u0003ולאחותו הבתולה,\u0004 כי מצד ימין נקראת השכינה \u0003אחות,\u0004 וכן \u0003בת.\u0004 כנ\"ל."],[27,"כתיב את ה' אלקיך תירא וגו':","מקרא זק כבר בארוהו, אבל בוא וראה, לה' אלקיך תירא לא כתוב, אלא את ה', מהו \u0003את\u0004. זה היא מדרגה הראשונה, מעשר ספירות, ממטה למעלה, שהיא הנוקבא, מקום היראה של הקב\"ה. ועל כן כתוב \u0003תירא,\u0004 כי שם, בהנוקבא, צריך האדם לירא מפני רבונו, משום שהיא דין."]],[[0,"","רַב יוֹסֵף כְּשֶׁהָיָה יוֹרֵד לְבָבֶל, רָאָה אֶת אוֹתָם רַוָּקִים שֶׁהָיוּ נִכְנָסִים וְיוֹצְאִים בֵּין נָשִׁים יָפוֹת וְלֹא חוֹטְאִים. אָמַר לָהֶם: הַאִם אֵלֶּה לֹא פוֹחֲדִים מִיֵּצֶר הָרָע? אָמְרוּ לוֹ: לֹא מִקּוֹנְדִיטוֹן רַע בָּאנוּ. אָנוּ נִגְזַרְנוּ מִקְּדֻשַּׁת הַקֹּדֶשׁ. שֶׁאָמַר רַב יְהוּדָה אָמַר רַב, צָרִיךְ אָדָם לְקַדֵּשׁ עַצְמוֹ בִּשְׁעַת תַּשְׁמִישׁ, וְיֵצְאוּ מִמֶּנּוּ בָּנִים קְדוֹשִׁים בָּנִים מְעֻלִּים שֶׁלֹּא פוֹחֲדִים מִיֵּצֶר הָרָע, שֶׁנֶּאֱמַר (ויקרא כ) והתקדשתם והייתם קדשים."],[1,"","רַבִּי אַבָּא אָמַר, מַה זֶּה שֶׁכָּתוּב (יחזקאל כ) וְאֶת שַׁבְּתוֹתַי קַדֵּשׁוּ? אֶלָּא אֵין עוֹנָתָם שֶׁל תַּלְמִידֵי חֲכָמִים אֶלָּא מִשַּׁבָּת לְשַׁבָּת. וּמַזְהִיר אוֹתָם, שֶׁהוֹאִיל וְתַשְׁמִישׁ הַמִּטָּה הִיא מִצְוָה - קַדֵּשׁוּ, כְּלוֹמַר קַדְּשׁוּ עַצְמְכֶם בְּשַׁבְּתוֹתַי בְּאוֹתוֹ תַשְׁמִישׁ שֶׁל מִצְוָה. אָמַר רַב יְהוּדָה אָמַר רַב, מִי שֶׁנִּכְנָס לָעִיר וְרוֹאִים נשִׁים יָפוֹת, יַרְכִּין עֵינָיו וְיֹאמַר כָּךְ: בְּךְ (ראה) מֵחֲשׁוּבִים חָצוֹב נֶחְצַבְתִּי (חזק) דְּפוּס הַתְּקָלָה, צֵא צֵא, שֶׁאָבִי הַקָּדוֹשׁ שֶׁל שַׁבָּת הוּא. מָה הַטַּעַם? מִשּׁוּם שֶׁחֲמִימוּת הַדֶּרֶךְ שׁוֹלֵט בּוֹ, וְיָכוֹל יֵצֶר הָרָע לִשְׁלֹט עָלָיו. עד כאן מדרש הנעלם"],[2,"","וַיַּעַל לוֹט מִצּוֹעַר וְגוֹ', מִתּוֹךְ רְצוֹן הַמֶּלֶךְ, נִפְרַד מִצַּד הַיָּמִין הִתּוּךְ אֶחָד שֶׁל קֶשֶׁר שֶׁהַחֲקִיקָה דְּבוּקָה בְּתוֹךְ הִתּוּךְ הַזָּהָב מִצַּד הַשְּׂמֹאל בְּתוֹךְ טֻמְאָה (של יצרו) (נ\"א ומקומו) וְנַעֲשָׂה שֶׁל קֶשֶׁר אֶחָד שֶׁל הָאִילָן."],[3,"","כְּשֶׁרָצָה יִצְחָק לְהִתְעוֹרֵר בָּעוֹלָם, בַּחֹזֶק שֶׁל הַדִּין הַקָּשֶׁה הִתְחַזֵּק וְהִפְרִיד דְּרָגוֹת מִקִּיּוּמָם, וְהִתְחַזֵּק אַבְרָהָם וְהִפְרִיד אוֹתוֹ קֶשֶׁר אֶחָד שֶׁל הָאִילָן מִתּוֹךְ אוֹתָהּ טֻמְאָה."],[4,"","אוֹתוֹ נָחָשׁ הַקַּדְמוֹנִי נִכְנַס בְּשָׁרְשׁוֹ שֶׁל אוֹתוֹ הָעֵץ, וְהוּא הַיַּיִן שֶׁשָּׁתָה וְהוֹלִיד שְׁתֵּי דְרָגוֹת קְשׁוּרוֹת זוֹ בָּזוֹ. וְהֵן הַדְּרָגוֹת שֶׁסּוֹבְבוֹת בְּצַד הַטֻּמְאָה, אֶחָד נִקְרָא מִלְכּוֹ\"ם וְאֶחָד נִקְרָא פְּעוֹ\"ר."],[5,"","זוֹ עֵצָה בְּנִכְסֶה, וְזוֹ עֵצָה בְּגִלּוּי. פְּעוֹ\"ר, שֶׁהִתְגַּלָּה הוּא וְכָל מַעֲשָׂיו בְּגִלּוּי. מִלְכּוֹ\"ם, שֶׁהוּא בְּכִסּוּי. הוּא וְכָל מַעֲשָׂיו מְכֻסִּים. מִשְּׁנֵי אֵלֶּה נִפְרָדִים מִינִים רַבִּים לְמִינֵיהֶם וְסוֹבְבִים אֶת הַיָּם הַגָּדוֹל וְאֶת כָּל הַצְּדָדִים הַטְּמֵאִים הַלָּלוּ, וְכָל אֶחָד וְאֶחָד קוֹפֵץ (נ\"א נזף) לִמְקוֹמוֹ."],[6,"","כְּמוֹ כֵן הוּא לְמַטָּה. לוֹט נִפְרַד מֵאַבְרָהָם וְשָׂם דִּיּוּרוֹ עִם אַנְשֵׁי סְדם, כְּשֶׁהִתְעוֹרֵר עֲלֵיהֶם הַדִּין נִזְכַּר בְּאַבְרָהָם, וְשָׁלַח לוֹ מִשָּׁם וְנִפְרַד מֵהֶם."],[7,"","בְּנוֹתָיו הִשְׁקוּהוּ יַיִן וְהוֹלִידוּ מִמֶּנּוּ שְׁתֵּי אֻמּוֹת. אַחַת נִקְרֵאת מוֹאָב וְאַחַת נִקְרֵאת עַמּוֹן. אַחַת בְּגִלּוּי וְאַחַת בְּכִסּוּי. עַמּוֹן דַּרְגָּתוֹ מִלְכּוֹ\"ם, עֵצָה בְּכִסּוּי. מוֹאָב דַּרְגָּתוֹ פְּעוֹ\"ר, הַכֹּל בְּגִלּוּי."],[8,"","כְּמוֹ זֶה בְּנוֹתָיו. אַחַת אָמְרָה בֶּן עַמִּי, בֵּן יֵשׁ לִי מֵעַמִּי וְלֹא אָמְרָה מִמִּי הוּא, מִשּׁוּם כָּךְ הוּא הָיָה בְּכִסּוּי. זוֹ אָמְרָה מוֹאָב, מֵאָב הוּא זֶה, מֵאַבָּא הוֹלַדְתִּיהוּ, דַּרְגָּתוֹ פְּעוֹ\"ר, הַדָּבָר בְּגִלּוּי."],[9,"","וּבִשְׁנֵי אֵלֶּה אָחַז דָּוִד הַמֶּלֶךְ, לְאַחַר מִכֵּן מִמּוֹאָב בָּאָה רוּת וְיָצָא מִמֶּנָּה דָּוִד הַמֶּלֶךְ, וּמֵעַמּוֹן הִתְעַטֵּר דָּוִד הַמֶּלֶךְ בָּעֲטָרָה הַזּוֹ שֶׁהִיא עֵדוּת לְזַרְעוֹ שֶׁל דָּוִד, שֶׁכָּתוּב (מלכים ב יא) וַיִּתֵּן עָלָיו אֶת הַנֵּזֶר וְאֶת הָעֵדוּת. וְזוֹ הָיְתָה מִמִּלְכּוֹ\"ם דַּרְגַּת בְּנֵי עַמּוֹן, שֶׁכָּתוּב (שמואל ב יב) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם."],[10,"","מִלְכֹּם דַּרְגַּת בְּנֵי עַמּוֹן הוּא, שֶׁכָּתוּב וַתְּהִי עַל רֹאשׁ דָּוִד, וּמִשָּׁם הָיְתָה עֵדוּת לְבָנָיו לְעוֹלָמִים, וּבָהּ נוֹדַע מִי הוּא מִן בְּנֵי דָוִד הַמֶּלֶךְ שֶׁרָאוּי לִמְלֹךְ וַדַּאי שֶׁאוֹמְרִים מִן דָּוִד הוּא (הגוף). שֶׁאֲפִלּוּ שֶׁנּוֹלַד בְּאוֹתוֹ הַיּוֹם, יָכוֹל הָיָה לִסְבֹּל בָּעֲטָרָה הַהִיא עַל רֹאשׁוֹ (שהרי הוא) שֶׁהָיָה מִשְׁקַל כִּכַּר זָהָב וְאֶבֶן יְקָרָה הָיְתָה, וּבֶן אָדָם אַחֵר לֹא יָכוֹל לִסְבֹּל אוֹתָהּ. וְזֶהוּ שֶׁכָּתוּב בְּיוֹאָשׁ, וַיִּתֵּן עָלָיו אֶת הַנֵּזֶר וְאֶת הָעֵדוּת."],[11,"","וּבִשְׁתֵּי דְרָגוֹת נֶאֱחַז דָּוִד הַמֶּלֶךְ, וְהֵם תֹּקֶף מַלְכוּתוֹ לְהִתְחַזֵּק עַל שְׁאָר הָעַמִּים, שֶׁאִם לֹא נִכְלָל בַּצַּד שֶׁלָּהֶם, לֹא יָכוֹל לְהִתְגַּבֵּר עֲלֵיהֶם כָּל (הגונים) הַדְּרָגוֹת שֶׁל שְׁאָר הָעַמִּים כְּלוּלִים בְּדָוִד לְהִתְגַּבֵּר וּלְהִתְחַזֵּק עֲלֵיהֶם."],[12,"","וַיַּעַל לוֹט מִצּוֹעַר וַיֵּשֶׁב בָּהָר. כָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. אֵלּוּ שְׁתֵּי בָנוֹת שֶׁל יֵצֶר הָרָע מְעוֹרְרוֹת אוֹתוֹ (כדי) לִשְׁלֹט עַל הַגּוּף. אַחַת הִיא נֶפֶשׁ שֶׁמִּתְרַבָּה תָּמִיד בַּגּוּף, וְאַחַת הִיא נֶפֶשׁ שֶׁכּוֹסֶפֶת לְתַאֲווֹת רָעוֹת (ד\"א של העולם הזה) וּבְכָל הַכִּסּוּפִים הָרָעִים שֶׁל הָעוֹלָם הַזֶּה. זוֹהִי הַבְּכִירָ\"ה, וְזוֹ (ואחרת) הַצְּעִירָ\"ה."],[13,"","וְיֵצֶר הָרָע לֹא מִתְחַבֵּר תָּמִיד אֶלָּא בִּשְׁתֵּי אֵלֶּה כְּדֵי לְפַתּוֹת בְּנֵי אָדָם, וּכְדֵי שֶׁיַּאֲמִינוּ לוֹ (להוביל) לְהַאֲבִיד אוֹתָם לִמְקוֹם חִצֵּי הַמָּוֶת וְיַעַבְדוּ אוֹתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (שם ז) עַד יְפַלַּח חֵץ כְּבֵדוֹ."],[14,"","לְלִסְטִים שֶׁמְּקַפְּחִים בֶּהָרִים, וּמַסְתִּירִים עַצְמָם בְּמָקוֹם מַפְחִיד בֶּהָרִים, וְיוֹדְעִים שֶׁהֲרֵי בְּנֵי אָדָם שׁוֹמְרִים עַצְמָם מִלָּלֶכֶת לַמְּקוֹמוֹת הַלָּלוּ, מָה עוֹשִׂים? בּוֹחֲרִים מֵהֶם אוֹתוֹ שֶׁלְּשׁוֹנוֹ חַדָּה מִכֻּלָּם, אוֹתוֹ שֶׁיּוֹדֵעַ לְפַתּוֹת בְּנֵי אָדָם, וְיוֹצֵא מִבֵּינֵיהֶם וְיוֹשֵׁב בְּדֶרֶךְ יְשָׁרָה שֶׁכָּל בְּנֵי הָעוֹלָם עוֹבְרִים שָׁם. כֵּיוָן שֶׁמַּגִּיעַ אֲלֵיהֶם, מַתְחִיל לְהִתְחַבֵּר עִמָּם (ולפתותם). (עד כאן סתרי תורה)."],[15,"","וַיִּסַּע מִשָּׁם אַבְרָהָם אַרְצָה הַנֶּגֶב. כָּל מַסְעוֹתָיו הָיוּ לְצַד דָּרוֹם יוֹתֵר מִלְּצַד אַחֵר, מִשּׁוּם שֶׁהֲרֵי בְּחָכְמָה עָשָׂה לְהִדָּבֵק בַּדָּרוֹם."],[16,"","וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחֹתִי הִוא. שָׁנִינוּ, (כיון) לֹא צָרִיךְ אָדָם לִסְמֹךְ עַל הַנֵּס, וְאִם הַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ נֵס לְבֶן אָדָם, אֵין לוֹ לִסְמֹךְ תָּמִיד עַל נֵס בְּפַעַם אַחֶרֶת, כִּי לֹא בְכָל שָׁעָה וְשָׁעָה מִתְרַחֵשׁ נֵס."],[17,"","וְאִם יַכְנִיס אָדָם אֶת עַצְמוֹ לְמָקוֹם שֶׁהַנֵּזֶק מָצוּי לָעַיִן, הֲרֵי פָּקְעָה כָּל זְכוּתוֹ שֶׁעָשָׂה בַּתְּחִלָּה וּבֵאֲרוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לב) קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת וְגוֹ'. וְאַבְרָהָם, כֵּיוָן שֶׁעָלָה מִמִּצְרַיִם וְנִצּוֹל פַּעַם אַחַת, כָּעֵת לָמָּה הִכְנִיס אֶת עַצְמוֹ בְּצַעַר כְּבַתְּחִלָּה וְאָמַר אֲחֹתִי הִוא?"],[18,"","אֶלָּא אַבְרָהָם לֹא סָמַךְ עַל עַצְמוֹ כְּלוּם, שֶׁרָאָה אֶת הַשְּׁכִינָה תָּמִיד בִּמְדוֹרָהּ שֶׁל שָׂרָה וְלֹא זָזָה מִשָּׁם, וּמִשּׁוּם שֶׁהָיְתָה שָׁם, סָמַךְ אַבְרָהָם וְאָמַר אֲחֹתִי הִוא, כְּמוֹ שֶׁכָּתוּב (משלי ז) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ, וְלָכֵן אָמַר אֲחֹתִי הִוא."],[19,"","וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ וְגוֹ'. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא אֶל רְשָׁעִים? כְּמוֹ שֶׁכָּתוּב (במדבר כב) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם, (בראשית לא) וַיָּבֹא אֱלֹהִים אֶל לָבָן? אֶלָּא אוֹתוֹ מְמֻנֶּה הַשָּׁלִיחַ שֶׁמֻּפְקָד עֲלֵיהֶם הָיָה מִשּׁוּם שֶׁכֻּלָּם, כְּשֶׁעוֹשִׂים שְׁלִיחוּת, נוֹטְלִים הַשֵּׁם הַזֶּה, מִצַּד הַדִּין הֵם בָּאִים. וְעַל זֶה וַיָּבֹא אֱלֹהִים אֶל אֲבִימֶלֶךְ בַּחֲלוֹם הַלָּיְלָה וַיֹּאמֶר לוֹ הִנְּךְ מֵת עַל הָאִשָּׁה אֲשֶׁר לָקַחְתָּ וְגוֹ'."],[20,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (משלי יב) שְׂפַת אֱמֶת וְגוֹ'. שְׂפַת אֱמֶת תִּכּוֹן לָעַד - זֶה אַבְרָהָם, שֶׁכָּל דְּבָרָיו בַּהַתְחָלָה וּבַסּוֹף הָיוּ בֶּאֱמֶת. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר - זֶה אֲבִימֶלֶךְ."],[21,"","בְּאַבְרָהָם נֶאֱמַר, וַיֹּאמֶר אַבְרָהָם אֶל שָׂרָה אִשְׁתּוֹ אֲחֹתִי הִוא. זֶה בַּהַתְחָלָה שֶׁאָמַר מִשּׁוּם הַשְּׁכִינָה שֶׁהָיְתָה עִמָּהּ שֶׁל שָׂרָה אֲחֹתִי הִיא, וְאַבְרָהָם עָשָׂה בְּחָכְמָה."],[22,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאַבְרָהָם הוּא מִצַּד הַיָּמִין, אָמַר אֲחֹתִי הִוא, וְסוֹד כְּמוֹ שֶׁנֶּאֱמַר (שיר ה) אֲחֹתִי רַעְיָתִי יוֹנָתִי תַמָּתִי. וְעַל זֶה אַבְרָהָם קָרָא לָהּ תָּמִיד אֲחוֹתִי, מִשּׁוּם שֶׁנִּדְבָּק עִמָּהּ, וְלא יָזוּזוּ זֶה מִזֶּה לְעוֹלָמִים."],[23,"","לְבַסּוֹף מַה כָּתוּב? וְגַם אָמְנָה אֲחֹתִי בַת אָבִי הִוא אַךְ לֹא בַת אִמִּי. וְכִי כָּךְ הָיָה? אֶלָּא הַכֹּל מִשּׁוּם הַשְּׁכִינָה אָמַר אֲחֹתִי הִוא בַּהַתְחָלָה, שֶׁכָּתוּב אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. אַחַר כָּךְ וְגַם אָמְנָה. מַה זֶּה וְגַם? לְהוֹסִיף עַל מַה שֶּׁאָמַר בַּתְּחִלָּה. אֲחֹתִי בַת אָבִי הִוא, הַבַּת שֶׁל הַחָכְמָה הָעֶלְיוֹנָה, וְלָכֵן נִקְרֵאת אֲחוֹתִי וְנִקְרֵאת חָכְמָה, אַךְ לֹא בַּת אִמִּי, מֵהַמָּקוֹם שֶׁל רֵאשִׁית הַכֹּל הַנִּסְתָּר הָעֶלְיוֹן. וְעַל זֶה וַתְּהִי לִי לְאִשָּׁה, בְּאַחֲוָה וַחֲבִיבוּת, שֶׁכָּתוּב (שם ב) וִימִינוֹ תְחַבְּקֵנִי, וְהַכֹּל סוֹד שֶׁל חָכְמָה."],[24,"","בֹּא רְאֵה, בַּהַתְחָלָה כְּשֶׁיָּרְדוּ לְמִצְרַיִם כָּךְ אָמַר בִּשְׁבִיל לְהִדָּבֵק בְּתוֹךְ הָאֱמוּנָה, וְקָרָא לָהּ אֲחֹתִי כְּדֵי שֶׁלֹּא יִטְעוּ לְתוֹךְ אוֹתָם הַדְּרָגוֹת שֶׁבַּחוּץ. אַף כָּאן אֲחֹתִי, כְּדֵי שֶׁלֹּא תָזוּז מִתּוֹךְ הָאֱמוּנָה כָּרָאוּי."],[25,"","שֶׁהֲרֵי אֲבִימֶלֶךְ וְכָל אוֹתָם יוֹשְׁבֵי הָאָרֶץ הָיוּ הוֹלְכִים אַחַר עֲבוֹדָה זָרָה, וְהוּא נִדְבַּק בְּתוֹךְ הָאֱמוּנָה וּמִשּׁוּם כָּךְ נִכְנַס לְשָׁם וְאָמַר אֲחֹתִי. מָה הָאָחוֹת לֹא נִפְרֶדֶת מִן הָאָח לְעוֹלָמִים - אַף כָּאן. שֶׁהֲרֵי אִשָּׁה יְכוֹלָה לְהִפָּרֵד, אֲבָל אָחוֹת לֹא נִפְרֶדֶת, שֶׁהֲרֵי שְׁנֵי אַחִים לֹא יְכוֹלִים לְהִפָּרֵד לְעוֹלָמִים וּלְעוֹלְמֵי עוֹלָמִים."],[26,"","וְלָכֵן אָמַר אַבְרָהָם אֲחֹתִי הִוא, שֶׁהֲרֵי כֻּלָּם הָיוּ לְהוּטִים בְּתוֹךְ קִשְׁרֵי הַכּוֹכָבִים וּמַזָּלוֹת וְעוֹבְדִים אוֹתָם, וְאַבְרָהָם הָיָה דָבֵק בְּתוֹךְ הָאֱמוּנָה, וְאָמַר אֲחוֹתִי, שֶׁלֹּא נִפְרָד לְעוֹלָמִים. וְסִימָן לַדָּבָר - (ויקרא כא) וְלַאֲחֹתוֹ הַבְּתוּלָה, שֶׁנֶּאֱמַר לַכֹּהֵן הַמָּקוֹם שֶׁאַבְרָהָם שָׁרוּי בּוֹ."],[27,"","כָּתוּב (דברים י) אֶת ה' אֱלֹהֶיךְ תִּירָא אֹתוֹ תַעֲבֹד וּבוֹ תִדְבָּק וּבִשְׁמוֹ תִשָּׁבֵעַ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה, לַה' אֱלֹהֶיךְ תִּירָא לֹא כָתוּב, אֶלָּא כָּתוּב אֶת ה'. מַה זֶּה אֶת? זוֹ הַדַּרְגָּה הָרִאשׁוֹנָה, הַמָּקוֹם שֶׁל יִרְאת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן כָּתוּב תִּירָא, שֶׁשָּׁם אָדָם צָרִיךְ לִירָא לִפְנֵי רִבּוֹנוֹ (הקדוש ברוך הוא), מִשּׁוּם שֶׁהוּא (בית) דִּין."]]],[["וְאוֹתוֹ תַּעֲבֹד. דָּא דַּרְגָּא עִלָּאָה דְּקָיְימָא עַל הַאי דַרְגָּא תַּתָּאָה, וְלָא מִתְפָּרְשָׁאן לְעָלְמִין, אֶת וְאוֹתוֹ, דָּא בְּדָא דְּבֵקִין וְלָא אִתְפָּרְשָׁן. מַאי וְאוֹתוֹ. דָּא אֲתַר בְּרִית קַדִּישָׁא אוֹת לְעָלְמִין. דְּהָא פּוּלְחָנָא לָא שַׁרְיָא בְּאֶת וְלָאו אִיהוּ לְמִפְלַח אֶלָּא לְמִדְחַל, אֲבָל פּוּלְחָנָא אִיהוּ (קטו א) לְעֵילָא, וּבְגִין כָּךְ וְאוֹתוֹ תַעֲבֹד.","וּבוֹ תִדְבָּק. בְּאֲתַר דְּאִיהוּ דְּבֵקוּתָא לְאִתְדַּבְּקָא דְּאִיהוּ גוּפָא דְּשָׁרֵי בְּאֶמְצָעִיתָא. וּבִשְׁמוֹ תִּשָּׁבֵעַ אֲתַר שְׁבִיעָאָה דְּדַרְגִּין. וְסִימָנִיךְ (ירמיהו ל׳:ט׳) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם.","בְּגִין כָךְ אִתְדָּבַּק אַבְרָהָם בִּמְהֵימְנוּתָא כַּד נָחַת לְמִצְרַיִם וְכַד אֲזַל לְאַרְעָא דִּפְלִשְׁתִּים. לְבַּר נָשׁ דְּבָעָא לְנָחֲתָא גּוֹ גּוּבָא עֲמִיקָא. דָּחִיל דְּלָא יָכִיל לְסַלְקָא מִגּוֹ גּוֹבָא, מָה עֲבַד קָשַׁר חַד קִשְׁרָא דְּחֶבֶל לְעֵילָא מִן גּוֹבָא, אָמַר הוֹאִיל דְּקָשִׁירְנָא קִשְׁרָא דָא מִכָּאן וּלְהָלְאָה אִיעוּל תַּמָּן. כָּךְ אַבְרָהָם בְּשַׁעֲתָא דְּבָעָא לְנַחֲתָא לְמִצְרַיִם. עַד לָא יֵיחוּת תַּמָּן קְשַׁר קִשְׁרָא דִּמְהֵימְנוּתָא בְּקַדְמִיתָא לְאִתְתַּקְּפָא בֵּיהּ, וּלְבָתַר נָחַת.","אוּף הָכִי נָמֵי כַּד עָאל לְאַרְעָא דִּפְלִשְׁתִּים. בְגִין כָּךְ (משלי י״ב:י״ט) שְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר, דָּא אֲבִימֶלֶךְ דְּאָמַר בְּתוֹם לְבָבִי וּבְנִקְיוֹן כַּפָּי. וְכַד אֲהַדְּרוּ לֵיהּ מַה כְּתִיב גַּם אָנֹכִי יָדַעְתִּי כִּי בְּתָם לְבָבְךָ עָשִׂיתָ זֹאת, וְלָא כְּתִיב נִקְיוֹן כַּפַּיִם:","וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא. רַבִּי יְהוּדָה פָּתַח וְאָמַר (שמואל א ב׳:ט׳) רַגְלֵי חֲסִידָיו יִשְׁמֹר וְגו'. חֲסִידוֹ כְּתִיב חַד, וְדָא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לֵיהּ תָּדיר וְלָא אַעֲדֵי נְטִירוּ מִנֵּיהּ לְעָלְמִין. וּמַה דְּאָמַר רַגְלֵי, דָּא אִתְּתֵיהּ, דְּקוּדְשָׁא בְּרִיךְ הוּא שַׁדַּר שְׁכִינְתֵּיהּ עִמָּהּ וְנָטַר לָהּ תָּדִיר.","דָּבָר אַחֵר רַגְלֵי חֲסִידָיו יִשְׁמֹר. חַד, דָּא אַבְרָהָם דְּקוּדְשָׁא בְּרִיךְ הוּא אָזִיל עִמֵּיהּ תָּדִיר בְּגִין דְּלָא יֵיכְלוּן לְנָזְקָא לֵיהּ. וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. אִלֵּין אִנּוּן מַלְכִין דַּקַטַּל קוּדְשָׁא בְּרִיךְ הוּא בְּהַהוּא לֵילְיָא דְּרָדַף בַּתְרַיְיהוּ.","הֲדָא הוּא דִכְתִיב בַּחשֶׁךְ יִדַּמּוּ, דָּא לֵילְיָא דְּאִתְקַשַּׁר בַּחֲשׁוֹכָא וְקָטַל לוֹן, וְאַבְרָהָם רָדִיף וְלֵילְיָא קָטִיל לוֹן, הֲדָא הוּא דִכְתִיב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה הוּא וַעֲבָדָיו וַיַּכֵּם. וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה, דָּא קוּדְשָׁא בְּרִיךְ הוּא דְּפָלִיג רַחֲמֵי מִן דִּינָא בְּגִין לְמֶעְבַּד נוּקְמִין לְאַבְרָהָם, וּבְגִין כָּךְ וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. וַיַּכֵּם, וַיַּכּוּם מִבָּעֵי לֵיהּ. אֶלָּא דָּא קוּדְשָׁא בְּרִיךְ הוּא. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ. דְּאִיהוּ וְאֱלִיעֶזֶר הֲווּ בִּלְחוֹדַיְיהוּ.","רַבִּי יִצְחָק אָמַר וְהָא תָּנִינָן בְּאֲתַר דְּנִזְקָא שְׁכִיחַ לָא יִסְמֹךְ בַּר נָשׁ עַל נִיסָא, וְלָא הֲוָה אֲתַר דְּנִזְקָּא אִשְׁתְּכַח כְּהַאי דְּאַבְרָהָם אָזִיל בָּתַר חֲמִשָּׁה מַלְכִין לְמִרְדַּף בַּתְרַיְיהוּ וְלַאֲגָחָא קְרָבָא. אָמַר רַבִּי יְהוּדָה כַּד אָזִיל אַבְרָהָם לְהַאי לָא אֲזַל לַאֲגָחָא קְרָבָא, וְלָא סָמַךְ עַל נִיסָא, אֶלָּא צַעֲרָא דְלוֹט אַפְקֵיהּ מִבֵּיתֵיהּ, וְנָטִיל מָמוֹנָא לְמִפְרַק לֵיהּ, וְאִי לָאו דִּימוּת בַּהֲדֵיהּ גּוֹ שִׁבְיָהּ. כֵּיוָן דְּנָפַק חָמָא שְׁכִינְתָּא דְּנָהֲרָא קַמֵּיהּ וְכַמָּה חֵילִין סָחֳרָנֵיהּ, בְּהַהִיא שַׁעֲתָא רָדַף בַּתְרַיְיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא קָטִיל לוֹן, הֲדָא הוּא דִכְתִיב וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ.","רַבִּי שִׁמְעוֹן אָמַר רָזָא אִיהוּ, רַגְלֵי חֲסִידָו יִשְׁמֹר, דָּא אַבְרָהָם. וְכַד נָפַק אִשְׁתַּתַּף יִצְחָק בַּהֲדֵיהּ וְנָפְלוּ קַמֵּיהּ, וְאִי לָאו דְּאִשְׁתַּתַּף יִצְחָק בַּהֲדֵיהּ דְּאַבְרָהָם לָא אִשְׁתֵּצִיאוּ הֲדָא הוּא דִכְתִיב וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. כִּי לא בְכֹחַ יִגְבַּר אִישׁ. אַף עַל גַּב דְּחֵילָא אִשְׁתְּכַח תָּדִיר בְּיָמִינָא, אִי לָא הֲוָה בְּסִטְרָא דִּשְׂמָאלָא לָא אִתְדַּחְיָין קַמֵּיהּ.","דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר, בְּשַׁעֲתָא דְּבַּר נָשׁ רָחִים לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. קוּדְשָׁא בְּרִיךְ הוּא רָחִים לֵיהּ בְּכָל מַה דְּאִיהוּ עָבִיד וְנָטִיר אָרְחוֹי כְּמָא דְאַתְּ אָמֵר (תהילים קכ״א:ח׳) יְיָ יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם.","תָּא חֲזֵי, כַּמָּה חֲבִיבוּתֵיהּ דְּאַבְרָהָם לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּבְּכָל אֲתַר דְּהֲוָה אָזִיל לָא הֲוָה חָיִיס עַל דִּילֵיהּ כְּלוּם, אֶלָא בְּגִין לְאִתְדַּבְּקָא בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וּבְגִין כָּךְ רַגְלֵי חֲסִידָיו יִשְׁמֹר. וְדָא הִיא אִתְּתֵיהּ, דִּכְתִיב וַאֲבִימֶלֶךְ לא קָרַב אֵלֶיהָ. וּכְתִיב כִּי עַל כֵּן לא נְתַתִּיךָ לִנְגֹעַ אֵלֶיהָ."],[[0,"ואותו תעבוד: אותו","זה הוא מדרגה עליונה, דהיינו יסוד דז\"א, העומדת על מדרגה זו התחתונה שהיא הנוקבא, ואינן נפרדות זו מזו לעולם. \u0003את ואותו,\u0004 דבקים זה בזה ואינם נפרדים. ושואל מהו \u0003ואותו,\u0004 ואומר זה הוא מקום ברית קודש, אות הוא לעולם, דהיינו יסוד, כי עבודה אינה שורה ב \u0003את,\u0004 ואינה ענין לעבוד אלא לירא. אבל עבודה, היא למעלה, ביסוד דז\"א, הנקרא אותו, ומשום זה כתוב ואותו תעבוד."],[1,"וכו תדבק:","הוא במקום שנוהג דבקות להדבק, שהוא הגוף השורה באמצע, דהיינו קו אמצעי שהיא ת\"ת העומד באמצע ב' הידים שהם חסד וגבורה. דהיינו ב' הקוין ימין ושמאל. \u0003ובשמו תשבע:\u0004 הוא מקום שביעי של המדרגות, דהיינו כשהנוקבא היא בסוד שבת, וסימנך ואת דוד מלכם אשר אקים להם. פירוש. הנוקבא נקרא \u0003את\u0004 בסוד היחוד של \u0003את ואותו\u0004 הנ\"ל, שהיחוד הוא מבחינת קו ימין, המקבל מאו\"א עלאין כנ\"ל. ונקראת בסוד \u0003ובשמו תשבע,\u0004 כשהוא מקבלת מבחינת קו אמצעי בסוד המוחין דשבת שאז נקראת \u0003שביעי,\u0004 כנודע."],[2,"בגין כך אתדבק וכו':","משום זה, נתדבק אברהם באמונה, דהיינו בסוד השכינה במדרגת אחות כנ\"ל, כאשר ירד למצרים וכאשר הלך לארץ פלשתים, בדומה לאדם הרוצה לרדת לתוך בור עמוק. והוא מתירא, שלא יוכל לחזור ולעלות מתוך הבור. מח עשה. קשר חבל אחד למעלה מן הבור, אמר מאחר שקשרתי קשר הזה אכנס שמה מכאן ולהלאה. כן אברהם בשעה שרצה לירד למצרים, מטרם שירד שמה קשר מתחילה קשר של אמונה, להתחזק בו, ואחר כך ירד שמה."],[3,"אוף הכי נמי וכו':","וכן עשה גם כן כשנכנס לארץ פלשתים. ועל כן שפת אמת תכון לעד, ועד ארגיעה לשון שקר, זהו אבימלך (כנ\"ל באות שמ\"ז) שאמר בתום לבבי ובנקיון כפי, וכשהשיב לו אלקים מה כתוב, גם אנכי ידעתי כי בתם לבבך עשית זאת, ולא כתוב נקיון כפים. כמו שאמר אבימלך, הרי שאבימלך היה משקר במה שאמר, ובנקיון כפים. וע\"כ כתוב עליו ועד ארגיעה לשון שקר."],[4,"ועתה השב וגו' כי נביא הוא:","ר' יהודה פתח ואמר, רגלי חסידיו ישמור וגו' חסידו כתיב, בלי י', שהמשמעות הוא חסיד אחד, וזהו אברהם, שלא הסיר שמירתו ממנו לעולם. ומה שאמר \u0003רגלי,\u0004 זו היא אשתו של אברהם. שהקב\"ה שלח שכינתו עמה, ושמר אותה תמיד."],[5,"ד\"א רגלי חסידו ישמור:","שכתוב חסידו בלי י' שהמשמעות הוא אחד, זהו אברהם, שהקב\"ה הלך עמו תמיד, כדי שלא יוכלו להזיקו. \u0003ורשעים בחשך ידמו,\u0004 אלו הם המלאכים שהרג הקב\"ה באותו הלילה שאברהם רדף אחריהם."],[6,"הה\"ד בחשך ידמו:","וזהו שכתוב בחשך ידמו. זהו \u0003לילה\u0004, דהיינו הנוקבא, שנקשר בחשך והרג אותם. אברהם רדף והלילה הרג אותם. וזהו שכתוב, ויחלק עליהם לילה הוא ועבדיו ויכם, \u0003ויחלק\u0004 עליהם לילה, זהו הקב\"ה, שחלק הרחמים מן הדין, כדי לנקום נקמת אברהם, ומשום זה כתוב, ורשעים בחשך ידמו. \u0003ויכם.\u0004 ויכום היה צריך לומר, לשון רבים, כי אברהם ועבדיו הכו אותם. אלא זהו הקב\"ה שהוא הכה אותם, \u0003כי לא בכח יגבר איש,\u0004 כי הוא ואליעזר היו בלבדם. כי אליעזר בגימטריא שי\"ח, והיינו שי\"ח ילידי ביתו שאומר הכתוב."],[7,"ר' יצחק אמר וכו':","רי\"א. והרי למדנו, במקום שהנזק מצוי, לא יסמוך אדם על הנס ואין לך מקום שהנזק מצוי בו, כזה, שאברהם הלך אחר ארבעה מלכים, לרדוף אחריהם ולעשות עמהם מלחמה. ולמה סמך עצמו על נס. אמר ר' יהודה, כשהלך לזה אברהם, לא הלך לעשות מלחמה, ולא סמך על הנס, אלא צערו של לוט הוציאו מביתו, ולקח עמו כסף לפדותו, ואם לא יוכל לפדותו, ימות עמו יחד בשביה, אלא כיון שיצא, ראה את השכינה מאירה לפניו, וכמה צבאות מלאכים מסביב לו, בשעה ההיא רדף אחריהם, והקב\"ה הרג אותם. וזהו שכתוב ורשעים בחשך ידמו."],[8,"ר' שמעון אמר וכו':","רש\"א, סוד הוא. רגלי חסידו ישמור זהו אברהם וכשיצא, ללחום עם המלכים, נתחבר יצחק עמו, ונפלו לפניו. ואם יצחק לא היה מתחבר עם אברהם, לא היה יכול לכלותם. וז\"ש ורשעים בחשך ידמו. \u0003כי לא בכח יגבר איש,\u0004 אע\"פ, שהכח נמצא תמיד בימין, שהוא אברהם, עם כל זה, אם הימין לא היה נכלל בצד שמאל, שהוא יצחק, לא היו המלכים נדחים לפניו."],[9,"ד\"א, רגלי חסידו ישמור:","בשעה שאדם אוהב את הקב\"ה, הקב\"ה אוהב אותו בכל מה שהוא עושה, ושומר דרכיו, כמו שאתה אומר, ה' ישמור צאתך ובואך מעתה ועד עולם."],[10,"ת\"ח כמה חביבותיה וכו':","בוא וראה, כמה היה חביבותו של אברהם אל הקב\"ה, כי בכל מקום שהיה הולך, לא היה חושב על שלו כלום, אלא רק להדבק בהקב\"ה בלבד, ומשום זה, ורגלי חסידו ישמור. וזו היא אשתו, כי רגלי, רומז על אשתו כנ\"ל (באות שנ\"ט) שכתוב ואבימלך לא קרב אליה. וכתיב כי על כן לא נתתיך לנגוע אליה."]],[[0,"","וְאֹתוֹ תַעֲבֹד - זוֹ הַדַּרְגָּה הָעֶלְיוֹנָה שֶׁעוֹמֶדֶת עַל הַדַּרְגָּה הַתַּחְתּוֹנָה הַזּוֹ, וְלֹא נִפְרָדִים לְעוֹלָמִים. אֶת וְאֹתוֹ זֶה עִם זֶה דְּבֵקִים וְלֹא נִפְרָדִים. מַה זֶּה וְאֹתוֹ? זֶה מְקוֹם בְּרִית הַקֹּדֶשׁ, אוֹת לְעוֹלָמִים. שֶׁהֲרֵי עֲבוֹדָה לֹא שׁוֹרָה בְּאוֹת וְאֵינוֹ לַעֲבֹד אֶלָּא לִירָא, אֲבָל הָעֲבוֹדָה הִיא לְמַעְלָה, וְלָכֵן וְאֹתוֹ תַעֲבֹד."],[1,"","וּבוֹ תִדְבָּק - בְּמָקוֹם שֶׁהוּא דְּבֵקוּת לְהִדָּבֵק שֶׁהוּא גוּף שֶׁשּׁוֹרֶה בָּאֶמְצַע. וּבִשְׁמוֹ תִשָּׁבֵעַ - הַמָּקוֹם הַשְּׁבִיעִי שֶׁל הַדְּרָגוֹת, וְסִימָן לַדָּבָר - (ירמיה ל) וְאֵת דָּוִד מַלְכָּם אֲשֶׁר אָקִים לָהֶם."],[2,"","מִשּׁוּם כָּךְ נִדְבַּק אַבְרָהָם בָּאֱמוּנָה כְּשֶׁיָּרַד לְמִצְרַיִם וּכְשֶׁהָלַךְ לְאֶרֶץ פְּלִשְׁתִּים. לְאָדָם שֶׁרָצָה לָרֶדֶת לְבוֹר עָמֹק, פָּחַד שֶׁלֹּא יוּכַל לַעֲלוֹת מִתּוֹךְ הַבּוֹר, מֶה עָשָׂה? קָשַׁר קֶשֶׁר אֶחָד שֶׁל חֶבֶל לְמַעְלָה מֵהַבּוֹר. אָמַר, הוֹאִיל וְקָשַׁרְתִּי קֶשֶׁר זֶה, מִכָּאן וָהָלְאָה אֶכָּנֵס לְשָׁם. כָּךְ אַבְרָהָם, בְּשָׁעָה שֶׁרָצָה לָרֶדֶת לְמִצְרַיִם, עַד שֶׁלֹּא יָרַד לְשָׁם קָשַׁר בַּתְּחִלָּה אֶת קֶשֶׁר הָאֱמוּנָה לְהִתְחַזֵּק בּוֹ, וְאַחַר כָּךְ יָרַד."],[3,"","אַף כָּךְ גַּם כְּשֶׁנִּכְנַס לְאֶרֶץ פְּלִשְׁתִּים. מִשּׁוּם כָּךְ (משלי יב) שְׂפַת אֱמֶת תִּכּוֹן לָעַד. וְעַד אַרְגִּיעָה לְשׁוֹן שָׁקֶר - זֶה אֲבִימֶלֶךְ שֶׁאָמַר בְּתָם לְבָבִי וּבְנִקְיֹן כַּפַּי. וּכְשֶׁהֶחֱזִירוּ לוֹ מַה כָּתוּב? גַּם אָנֹכִי יָדַעְתִּי כִּי בְתָם לְבָבְךְ עָשִׂיתָ את, וְלֹא כָתוּב נִקְיוֹן כַּפַּיִם."],[4,"","וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ כִּי נָבִיא הוּא. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שמואל א ב) רַגְלֵי חֲסִידָו יִשְׁמֹר וְגוֹ'. חֲסִידוֹ כָּתוּב אֶחָד, וְזֶה אַבְרָהָם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ תָּמִיד וְלֹא מֵסִיר מִמֶּנּוּ אֶת שְׁמִירָתוֹ לְעוֹלָמִים. וּמַה שֶּׁאָמַר רַגְלֵי - זוֹ אִשְׁתּוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלַח שְׁכִינָתוֹ עִמָּהּ וְשׁוֹמֵר אוֹתָהּ תָּמִיד."],[5,"","דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר - אֶחָד, זֶה אַבְרָהָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָלַךְ עִמּוֹ תָּמִיד כְּדֵי שֶׁלֹּא יוּכְלוּ לְהַזִּיק לוֹ. וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - אֵלּוּ אוֹתָם מְלָכִים שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתוֹ לַיְלָה שֶׁרָדַף אַחֲרֵיהֶם."],[6,"","זְהִוּ שֶׁכָּתוּב בַּחֹשֶׁךְ יִדָּמּוּ, זֶה הַלַּיְלָה שֶׁנִּקְשַׁר בַּחֹשֶׁךְ וְהָרַג אוֹתָם, וְאַבְרָהָם רָדַף וְהַלַּיְלָה הָרַג אוֹתָם. זֶהוּ שֶׁכָּתוּב וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה הוּא וַעֲבָדָיו וַיַּכֵּם. וַיֵּחָלֵק עֲלֵיהֶם לַיְלָה - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁחִלֵּק רַחֲמִים מִן הַדִּין כְּדֵי לַעֲשׂוֹת נְקָמוֹת לְאַבְרָהָם, וּמִשּׁוּם כָּךְ וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ. וַיַּכֵּם? הָיָה צָרִיךְ לִכְתֹּב וַיַּכּוּם! אֶלָּא זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ, שֶׁהוּא וֶאֱלִיעֶזֶר הָיוּ לְבַדָּם."],[7,"","רַבִּי יִצְחָק אָמַר, וַהֲרֵי שָׁנִינוּ שֶׁבְּמָקוֹם שֶׁנֵּזֶק מָצוּי שֶׁלֹּא יִסְמֹךְ בֶּן אָדָם עַל הַנֵּס, וְלֹא הָיָה מָקוֹם שֶׁהַנֵּזֶק מָצוּי כְּמוֹ זֶה שֶׁאַבְרָהָם הוֹלֵךְ אַחַר חֲמִשָּׁה מְלָכִים לִרְדֹּף אַחֲרֵיהֶם וְלַעֲרֹךְ קְרָב. אָמַר רַבִּי יְהוּדָה, כְּשֶׁהָלַךְ אַבְרָהָם עַל זֶה, לֹא הָלַךְ לַעֲרֹךְ קְרָב וְלֹא סָמַךְ עַל הַנֵּס, אֶלָּא צַעֲרוֹ שֶׁל לוֹט הוֹצִיא אוֹתוֹ מִבֵּיתוֹ, וְלָקַח מָמוֹן לִפְדּוֹת אוֹתוֹ, וְאִם לֹא - שֶׁיָּמוּת יַחַד אִתּוֹ בְּתוֹךְ שִׁבְיוֹ. כֵּיוָן שֶׁיָּצָא רָאָה שְׁכִינָה שֶׁמְּאִירָה לְפָנָיו וְכַמָּה צְבָאוֹת סְבִיבָהּ, וּבְאוֹתָהּ שָׁעָה רָדַף אַחֲרֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָרַג אוֹתָם. זֶהוּ שֶׁכָּתוּב וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ."],[8,"","רַבִּי שִׁמְעוֹן אָמַר, סוֹד הוּא, רַגְלֵי חֲסִידָו יִשְׁמֹר - זֶה אַבְרָהָם, וּכְשֶׁיָּצָא, הִשְׁתַּתֵּף עִמּוֹ יִצְחָק וְנָפְלוּ לְפָנָיו, וְאִם לֹא שֶׁהִשְׁתַּתֵּף יִצְחָק יַחַד עִם אַבְרָהָם, לֹא הֻשְׁמְדוּ. זֶהוּ שֶׁכָּתוּב וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ. אַף עַל גַּב שֶׁהַכֹּחַ נִמְצָא תָמִיד בַּיָּמִין, אִם לֹא הָיָה בְּצַד הַשְּׂמֹאל לֹא הָיוּ נִדְחִים לְפָנָיו."],[9,"","דָּבָר אַחֵר רַגְלֵי חֲסִידָו יִשְׁמֹר - בְּשָׁעָה שֶׁבֶּן אָדָם אוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹהֵב אוֹתוֹ בְּכָל מַה שֶּׁהוּא עוֹשֶׂה וְשׁוֹמֵר דְּרָכָיו, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכא) ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם"],[10,"","בֹּא רְאֵה כַּמָּה חֲבִיבוּתוֹ שֶׁל אַבְרָהָם לַקָּבָּ\"ה, שֶׁבְּכָל מָקוֹם שֶׁהָיָה הוֹלֵךְ, לֹא הָיָה חָס עַל שֶׁלּוֹ כְּלוּם, אֶלָּא רַק כְּדֵי לְהִדָּבֵק בַּקָּבָּ\"ה, וּמִשּׁוּם כָּךְ רַגְלֵי חֲסִידָו יִשְׁמֹר, וְזוֹהִי אִשְׁתּוֹ, שֶׁכָּתוּב וַאֲבִימֶלֶךְ לֹא קָרַב אֵלֶיהָ, וְכָתוּב כִּי עַל כֵּן לֹא נְתַתִּיךְ לִנְגֹּעַ אֵלֶיהָ."]]],[["בְּפַרְעֹה מַה כְּתִיב, (בראשית י״ב:י״ז) וַיְנַגַּע יְיָ אֶת פַּרְעֹה וְגו' עַל דְּבַר. אִיהִי אָמְרָה וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מָחֵי, וּבְגִין כָּךְ רַגְלֵי חֲסִידָיו יִשְׁמֹר. וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ, אִלֵּין פַּרְעֹה וְאֲבִימֶלֶךְ, דְּקוּדְשָׁא בְּרִיךְ הוּא עֲבַד בְּהוּ דִּינִין בְּלֵילְיָא. כִּי לא בְּכֹחַ יִגְבַּר אִישׁ. מַאן אִישׁ, דָּא אַבְרָהָם, דִּכְתִיב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ וְגו':","וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר וְגו'. רַבִּי חִיָּיא פָּתַח וְאָמַר (זכריה ג׳:א׳) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עוֹמֵד לִפְנֵי מַלְאַךְ יְיָ וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. הַאי קְרָא אִית לְאִסְתַּכָּלָא בֵּיהּ. וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל דָּא יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק. עוֹמֵד לִפְנֵי מַלְאַךְ יְיָ, מַאן מַלְאַךְ יְיָ. דָּא אֲתַר צְרוֹרָא (ס\"א דנשמתין דצדיקיא צרירן) דְּנִשְׁמָתֵיהּ דְּצַדִּיק צְרִירָא בֵּיהּ, וְכָל אִנּוּן נִשְׁמָתִין דְּצַדִּיקַיָא קָיְימִין תַּמָּן, וְדָא הוּא מַלְאַךְ יְיָ.","וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. דָּא יֵצֶר הָרָע דְּאִיהוּ מְשׁוֹטֵט וְאָזִיל בְּעָלְמָא לְנַטְלָא נִשְׁמָתִין וּלְאַפָּקָא רוּחִין וּלְמִסְטֵי לוֹן לִבְרִיָּיתָא לְעֵילָא וְתַתָּא. וְדָא הוּא בְּשַׁעֲתָא דְּאֲטִיל לֵיהּ נְבוּכַדְנֶצַּר לְאֶשָׁא עִם אִנּוּן נְבִיאֵי הַשֶּׁקֶר, וְהַאי הֲוָה מַסְטִין לְעֵילָא בְּגִין דְּיִתּוֹקַד עִמְּהוֹן.","דְּהָכִי הוּא אָרְחוֹי דְּלָאו אִיהוּ מְקַטְרֵג אֶלָּא בְּזִמְנָא דְּסַכָּנָה וּבְזִמְנָא דְּצַעֲרָא שָׁרְיָא בְּעָלְמָא, וְאִית לֵיהּ רְשׁוּ לְמִסְטֵי וּלְמֶעְבַּד דִּינָא אֲפִלּוּ בְּלָא דִינָא כְּמָא דְאַתְּ אָמֵר, (משלי י״ג:כ״ג-כ״ד) וְיֵשׁ נִסְפָּה בְּלא מִשְׁפָּט. מַהוּ לְשִׂטְנוֹ, דְּהֲוָה אָמַר אוֹ כֻּלְהוּ יִשְׁתֵּזְבוּן אוֹ כֻּלְהוּ יִתּוֹקְדוּן. דְּהָא בְּשַׁעֲתָא דְּאִתְיְיהִיב רְשׁוּתָא לִמְחַבְּלָא לְחַבָּלָא לָא אִשְׁתְּזִיב זַכָּאָה מִן חַיָּיבַיָא,","וּבְגִין כָּךְ בְּשַׁעֲתָא דְּדִינָא שָׁרְיָיא בְּמָתָא בָּעֵי בַּר נָשׁ לְעָרְקָא עַד לָא אִתְפַּס תַּמָּן, דְּהָא מְחַבְּלָא כֵּיוָן דְּשָׁרֵי הָכִי נָמֵי עָבִיד לְזַכָּאָה כְּחַיָּיבָא. וְכָל שֶׁכֵּן דְּהֲווּ תְּלָתֵיהוֹן כְּחַד. וְהֲוָה תָּבַע דְּיִתּוֹקְדוּן כֻּלְהוּ אוֹ יִשְׁתֵּזְבוּן כֻּלְהוּ. בְּגִין דְּכַד אִתְעֲבִיד נִיסָא לָא אִתְעֲבִיד פַּלְגוּ נִיסָא וּפַלְגוּ דִּינָא, אֶלָּא כֹּלָּא כְּחֲדָא, אוֹ נִיסָא אוֹ דִּינָא."],[[0,"בפרעה מה כתיב וכו':","בפרעה מה כתוב. וינגע ה' את פרעה וגו' \u0003על דבר,\u0004 היא אמרה, שרה אמרה להקב\"ה הכה, והקב\"ה היה מכה, ועל כן כתוב \u0003רגלי חסידו ישמור. ורשעים בחשך ידמו,\u0004 אלו הם פרעה ואבימלך שהקב\"ה עשה בהם דינים בלילה, בחשך. \u0003כי לא בכח יגבר איש,\u0004 מי הוא \u0003איש,\u0004 זהו אברהם, שכתוב ועתה השב אשת האיש."],[1,"וה' פקד את שרה וגו':","ר' חייא פתח ואמר. ויראני את יהושע הכהן הגדול עומד לפני מלאך ה' וגו'. במקרא הזה יש להסתכל בו. \u0003ויראני את יהושע הכהן הגדול,\u0004 זהו יהושע בן יהוצדק. \u0003עומד לפני מלאך ה',\u0004 מי הוא מלאך ה'. זהו מקום שנקרא \u0003צרור\u0004 שנשמת הצדיק קשורה בו. וכל נשמות הצדיקים נמצאים שמה, וזהו מלאך ה', שאומר הכתוב."],[2,"והשטן עומד על ימינו לשטנו:","זהו יצר הרע, שהוא הולך ומשוטט בעולם, ליטול נשמות, ולהוציא רוחות מבני העולם, ולהשטין על הבריות למעלה ולמטה. וזה היה בעת שהטיל אותו נבוכדנצר, ליהושע הכהן הגדול לאש, ביחד עם נביאי השקר, ואז היה השטן משטין עליו למעלה, כדי שישרף עמהם."],[3,"דהכי הוא אורחוי וכו':","כי כך הוא דרכו של השטן, שאינו מקטרג אלא בשעת הסכנה. ובשעה שהצער שורה בעולם יש לו רשות להשטין ולעשות דין. אפילו בלי דין, כמו שאתה אומר, ויש נספה בלא משפט. מהו \u0003לשטנו,\u0004 כלומר, מה היה משטין, ואומר, שהיה אומר, או כולם יהיו נצולים, או כולם יהיו נשרפים. כי בשעה שניתן רשות למשחית להשחית, אין הצדיק נצל ממנו יותר, מן הרשע."],[4,"ובגין כך בשעתא וכו':","ומשום זה, בשעה שהדין שורה בעיר, צריך אדם לברוח מטרם שנלכד שם בידי המשחית, כי כיון שהמחבל שורה במקום, עושה גם כן לצדיק כמו לרשע. וכל שכן שהיו שלשתם ביחד דהיינו יהושע כהן גדול עם שני נביאי השקר אחאב בן קוליה וצדקיהו בן מעשיה והיה השטן תובע, או שישרפו כולם או שיצילו כולם כי כשנעשה נס, אינו נעשה חציו נס וחציו דין, אלא כולו בשוה, או נס או דין."]],[[0,"","בְּפַרְעֹה מַה כָּתוּב? (בראשית יב) וַיְנַגַּע ה' אֶת פַּרְעֹה וְגוֹ' עַל דְּבַר שָׂרַי. הִיא אָמְרָה - וְהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה מַכֶּה, וּמִשּׁוּם כָּךְ רַגְלֵי חֲסִידָו יִשְׁמֹר. וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - אֵלּוּ פַּרְעֹה וַאֲבִימֶלֶךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה בָהֶם דִּינִים בַּלַּיְלָה. כִּי לֹא בְכֹחַ יִגְבַּר אִישׁ, מִי זֶה אִישׁ? זֶה אַבְרָהָם, שֶׁכָּתוּב וְעַתָּה הָשֵׁב אֵשֶׁת הָאִישׁ וְגוֹ'."],[1,"","וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (זכריה ג) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עֹמֵד לִפְנֵי מַלְאַךְ ה' וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. בְּפָסוּק זֶה יֵשׁ לְהִסְתַּכֵּל בּוֹ. וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל - זֶה יְהוֹשֻׁעַ בֶּן יְהוֹצָדָק. עֹמֵד לִפְנֵי מַלְאַךְ ה', מִי זֶה מַלְאַךְ ה'? זֶהוּ הַמָּקוֹם (שנשמות הצדיקים צרורות) צְרוֹר שֶׁל נִשְׁמַת הַצַּדִּיק צְרוּרָה בּוֹ, וְכָל אוֹתָן נִשְׁמוֹת הַצַּדִּיקִים עוֹמְדוֹת שָׁם, וְזֶהוּ מַלְאַךְ ה'."],[2,"","וְהַשָּׂטָן עֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ - זֶהוּ יֵצֶר הָרָע שֶׁהוּא מְשׁוֹטֵט וְהוֹלֵךְ בָּעוֹלָם לִטֹּל נְשָׁמוֹת וּלְהוֹצִיא רוּחוֹת וּלְהַסְטוֹת אֶת הַבְּרִיּוֹת לְמַעְלָה וּלְמַטָּה. וְזֶהוּ בְּשָׁעָה שֶׁהִטִּיל אוֹתוֹ נְבוּכַדְנֶצַּר לָאֵשׁ עִם אוֹתָם נְבִיאֵי הַשֶּׁקֶר, וְזֶה הָיָה מַסְטִין לְמַעְלָה כְּדֵי שֶׁיִּשָּׂרֵף עִמָּם."],[3,"","שֶׁכָּךָ הִיא דַּרְכּוֹ - שֶׁאֵינוֹ מְקַטְרֵג אֶלָּא בִּזְמַן שֶׁל סַכָּנָה וּבִזְמַן שֶׁהַצַּעַר שׁוֹרֶה בָּעוֹלָם, וְיֵשׁ לוֹ רְשׁוּת לְהַסְטוֹת וְלַעֲשׂוֹת דִּין אֲפִלּוּ בְּלִי דִין, כְּמוֹ שֶׁנֶּאֱמַר (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. מַה זֶּה לְשִׂטְנוֹ? שֶׁהָיָה אוֹמֵר, אוֹ שֶׁכֻּלָּם יִנָּצְלוּ אוֹ שֶׁכֻּלָּם יִשָּׂרְפוּ. שֶׁהֲרֵי בְּשָׁעָה שֶׁנִּתְּנָה רְשׁוּת לַמַּשְׁחִית לְחַבֵּל, לֹא נִצּוֹל הַצַּדִּיק מֵהָרְשָׁעִים."],[4,"","וְלָכֵן בְּשָׁעָה שֶׁהַדִּין שָׁרוּי בָּעִיר, צָרִיךְ בֶּן אָדָם לִבְרֹחַ בְּטֶרֶם שֶׁיִּתָּפֵס שָׁם, שֶׁהֲרֵי הַמַּשְׁחִית, כֵּיוָן שֶׁמַּתְחִיל, כָּךְ גַּם עוֹשֶׂה לַצַּדִּיק כְּמוֹ לָרָשָׁע, וְכָל שֶׁכֵּן שֶׁהָיוּ שְׁלָשְׁתָּם כְּאֶחָד. וְהָיָה תוֹבֵעַ שֶׁיִּשָּׂרְפוּ כֻלָּם אוֹ יִנָּצְלוּ כֻלָּם. מִשּׁוּם שֶׁכְּשֶׁנַּעֲשֶׂה נֵס, לֹא נַעֲשֶׂה חֲצִי נֵס וַחֲצִי דִין, אֶלָּא הַכֹּל כְּאֶחָד, אוֹ נֵס אוֹ דִין."]]],[["אָמַר לוֹ רַבִּי יוֹסֵי, וְלָא, וְהָא בְּזִמְנָא דְּבָקַע קוּדְשָׁא בְּרִיךְ הוּא יַמָּא לְיִשְׂרָאֵל הֲוָה קָרַע יַמָּא לְאִלֵּין וְאָזְלִין בְּיַבֶּשְׁתָּא, וּמַיָּיא הֲווּ תָּבִין מִסִּטְרָא אָחֳרָא וְטָבְעִין לְאִלֵּין וּמֵתִין, וְאִשְׁתְּכַח נִיסָא הָכָא וְדִינָא הָכָא כֹּלָּא כְּחֲדָא.","אָמַר לֵיהּ וְדָא הוּא דְּקַשְׁיָא קַמֵּיהּ, דְּכַד קוּדְשָׁא בְּרִיךְ הוּא עָבִיד דִּינָא וְנִיסָא כְּחֲדָא, לָאו בְּאֲתַר חָד וְלָא בְּבֵיתָא חָדָא (דאשתכח כלא כחדא), וְאִי אִתְעֲבִיד קַשְׁיָא קַמֵּיהּ, דְּהָא לְעֵילָא לָא אִתְעֲבִיד כֹּלָּא אֶלָּא בִּשְׁלִימוּ כְּחֲדָא אוֹ נִיסָא אוֹ דִּינָא בְּאֲתַר חָד וְלָא בְּפַלְגוּ.","בְגִין כָּךְ לָא עֲבִיד קוּדְשָׁא בְּרִיךְ הוּא דִּינָא בְּחַיָּיבַיָא עַד דְּאִשְׁתַּלִּימוּ בְּחוֹבַיְיהוּ הֲדָא הוּא דִכְתִיב, (בראשית ט״ו:ט״ז) כִּי לא שָׁלֵם עֲוֹן הָאֱמֹרִי עַד הֵנָּה. וּכְתִיב (ישעיהו כ״ז:ח׳) בְּסַאסְאָה בְּשַׁלְחָהּ תְּרִיבֶנָּה. וְעַל דָּא הֲוָה אַסְטִין לֵיהּ לִיהוֹשֻׁעַ דְּיִתּוֹקַד בְּהוּ, עַד דְּאָמַר לֵיהּ (זכריה ג׳:ב׳) יִגְעַר יְיָ בְּךָ הַשָּׂטָן. מַאן אָמַר לֵיהּ, דָּא מַלְאַךְ יְיָ (ואתמר ויאמר יי אל השטן).","וְאִי תֵימָא וַיֹּאמֶר יְיָ אֶל הַשָּׂטָן יִגְעַר יְיָ בְּךָ וְגו'. תָּא חֲזֵי, הָכִי נָמֵי לְמשֶׁה בַּסְּנֶה דִּכְתִיב, (שמות ג׳:ב׳) וַיֵּרָא מַלְאַךְ יְיָ אֵלָיו בְּלַבַּת אֵשׁ. וּכְתִיב וַיַּרְא יְיָ כִּי סָר לִרְאוֹת. לְזִמְנִין מַלְאַךְ יְיָ וּלְזִמְנִין מַלְאָךְ וּלְזִמְנִין יְיָ. וּבְגִין כָּךְ אָמַר לֵיהּ יִגְעַר יְיָ בְּךָ הַשָּׂטָן וְלא אָמַר הִנְּנִי גּוֹעֵר בְּךָ.","תָּא חֲזֵי, כְּגווָֹנָא דָא בְּיוֹמָא דְּאִשְׁתְּכַח דִּינָא בְּעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כֻּרְסְיָיא דְּדִינָא, כְּדֵין אִשְׁתְּכַח הַאי שָׂטָן דְּאַסְטֵי לְעֵילָא וְתַתָּא, וְאִשְׁתְּכַח אִיהוּ לְחַבָּלָא עָלְמָא וְלִיטֹּל נִשְׁמָתִין.","רַבִּי שִׁמְעוֹן הֲוָה יָתִיב וְלָעֵי בְּאוֹרַיְיתָא, וְהֲוָה מִשְׁתַּדֵּל בְּהַאי קְרָא (דברים כ״א:ד׳) וְלָקְחוּ זִ קְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגו' וְעָרְפוּ שָׁם אֶת הָעֶגְלָה בַּנָּחַל. וְדִינָא אִיהוּ בְּקוּפִיץ לְעָרְפָּא לָהּ. אָמַר לֵיהּ רַבִּי אֶלְעָזָר הַאי לְמַאי אִצְטְרִיךְ."],[[0,"א\"ל ר' יוסי וכו':","א\"ל ר\"י, ולא, והרי בזמן שבקע הקב\"ה את הים לישראל, היה קורע את הים לאלו, לישראל והלכו ביבשה, והמים היו חוזרים מצד אחר, וטבעו את אלו, את המצרים, ומתו. ונמצא נס מכאן ודין מכאן, אע\"פ שהיו הכל ביחד."],[1,"א\"ל ודא הוא וכו':","אמר לו וזה הוא שקריעת ים סוף היה קשה לפניו, כי כאשר הקב\"ה עושה נס ודין ביחד, אינו במקום אחד, ולא בבית אחד, ואם נעשה, במקום אחד, כמו בקריעת ים סוף, הוא קשה לפניו. כי הכל למעלה לא נעשה, אלא בשלמות, כולו כאחד ובמקום אחד נעשה, או נס או דין, ולא לחצאים, שיהיה חציו נס וחציו דין."],[2,"בג\"כ לא עביד וכו':","לפיכך, אין הקב\"ה עושה דין ברשעים עד שנשלמו בעונם. כדי שלא יצרך להציל חלק מהם מן הדין, וזהו שכתוב כי לא שלם עון האמורי עד הנה. וכתוב בסאסאה בשלחה תריבנה. ועל כן היה השטן משטין על יהושע שישרף ביניהם, כדי, שלא יהיה חציו דין וחציו נס, עד שאמר לו יגער ה' בך השטן. ושואל מי אמר לו, יגער ה' וגו', ואומר זה מלאך ה', שאמר לשטן יגער ה' בך השטן."],[3,"ואי תימא ויאמר וכו':","ואם תאמר. הרי כתוב, ויאמר ה' אל השטן יגער ה' בך השטן. הרי שהקב\"ה הוא האומר ולא מלאך, בוא וראה, זה גם במשה בסנה, שכתוב, וירא מלאך ה' אליו בלבת אש, וכתוב וירא ה' כי סר לראות, שפעם כתוב מלאך ה', ופעם מלאך ופעם ה'. אף כאן, אע\"פ שכתוב מקודם, ויאמר ה' אל השטן, יתכן שיהיה מלאך, כמו במשה. ומשום זה אמר לו יגער ה', בך השטן, ולא אמר, הנני גוער בך. כי אם ה' היה האומר היה צריך לומר לו, הנני גוער בך השטן. אלא, שהאומר היה מלאך."],[4,"ת\"ח כגוונא וכו':","בוא וראה כעין זה, ביום שנמצא דין בעולם, והקב\"ה יושב על כסא דין, אז נמצא שם שטן הזה המסטין למעלה ולמטה, והוא נמצא, כדי להשחית העולם וליטול נשמות בני אדם. כי הוא השטן הוא מלאך המות כנודע."],[5,"רבי שמעון הוה יתיב וכו':","ר\"ש, היה יושב ולומד בתורה, והיה עוסק בכתוב הזה, ולקחו זקני העיר ההיא עגלת בקר וגומר, וערפו שם את העגלה בנחל. והדין הוא לערוף אותה בקופיץ. דהיינו בגרזן. א\"ל ר' אלעזר, למה צריך זה."]],[[0,"","אָמַר לוֹ רַבִּי יוֹסִי, וָלֹא? וַהֲרֵי בִּזְמַן שֶׁבָּקַע הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַיָּם לְיִשְׂרָאֵל, הָיָה קוֹרֵעַ אֶת הַיָּם לְאֵלֶּה וְהֵם הוֹלְכִים בַּיַּבָּשָׁה, וְהַמַּיִם הָיוּ שָׁבִים מִצַּד אַחֵר וּמַטְבִּיעִים אֶת אֵלֶּה וּמֵתִים. וְנִמְצָא נֵס כָּאן וְדִין כָּאן, הַכֹּל כְּאֶחָד."],[1,"","אָמַר לוֹ, וְזֶהוּ שֶׁקָּשֶׁה לְפָנָיו, שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין וְנֵס כְּאֶחָד, לֹא בְּמָקוֹם אֶחָד וְלֹא בְּבַיִת אֶחָד (שהכל נמצא כאחד). וְאִם נַעֲשֶׂה קָשֶׁה לְפָנָיו, שֶׁהֲרֵי לְמַעְלָה לֹא נַעֲשֶׂה הַכֹּל אֶלָּא בִּשְׁלֵמוּת כְּאֶחָד, אוֹ נֵס אוֹ דִין בְּמָקוֹם אֶחָד וְלֹא לַחֲצָאִין."],[2,"","לָכֵן לֹא עוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא דִּין בָּרְשָׁעִים עַד שֶׁיִּשְׁתַּלְּמוּ בְּחֶטְאָם. זֶהוּ שֶׁכָּתוּב (בראשית טו) כִּי לֹא שָׁלֵם עֲון הָאֱמֹרִי עַד הֵנָּה, וְכָתוּב (ישעיה כז) בְּסַאסְּאָה בְּשַׁלְּחָהּ תְּרִיבֶנָּה. וְעַל זֶה הָיָה מַסְטִין לִיהוֹשֻׁעַ שֶׁיִּשָּׂרֵף עִמָּם, עַד שֶׁאָמַר לוֹ (זכריה ג) יִגְעַר ה' בְּךְ הַשָּׂטָן. מִי אָמַר לוֹ? זֶה מַלְאַךְ ה' (ונאמר ויאמר ה' אל השטן)."],[3,"","וְאִם תֹּאמַר, וַיֹּאמֶר ה' אֶל הַשָּׂטָן יִגְעַר ה' בְּךְ וְגוֹ'? בֹּא רְאֵה, כָּךְ גַּם לְמֹשֶׁה בַּסְּנֶה, שֶׁכָּתוּב (שמות ג) וַיֵּרָא מַלְאַךְ ה' אֵלָיו בְּלַבַּת אֵשׁ, וְכָתוּב וַיַּרְא ה' כִּי סָר לִרְאוֹת. לִפְעָמִים מַלְאַךְ ה', וְלִפְעָמִים מַלְאָךְ, וְלִפְעָמִים ה'. וְלָכֵן אָמַר לוֹ יִגְעַר ה' בְּךְ הַשָּׂטָן וְלֹא אָמַר הִנְנִי גּוֹעֵר בְּךְ."],[4,"","בֹּא רְאֵה, כְּמוֹ זֶה בַּיּוֹם שֶׁנִּמְצָא דִין בָּעוֹלָם וְהַקָּדוֹשׁ בָּרוּךְ הוּא יוֹשֵׁב עַל כִּסֵּא הַדִּין, אָז נִמְצָא הַשָּׂטָן הַזֶּה שֶׁמַּסְטֶה לְמַעְלָה וּלְמַטָּה, וְהוּא נִמְצָא לְהַשְׁחִית אֶת הָעוֹלָם וְלִטֹּל הַנְּשָׁמוֹת."],[5,"","רַבִּי שִׁמְעוֹן הָיָה יוֹשֵׁב וְלוֹמֵד תּוֹרָה, וְהָיָה מִשְׁתַּדֵּל בַּפָּסוּק הַזֶּה, (דברים כא) וְלָקְחוּ זִקְנֵי הָעִיר הַהִיא עֶגְלַת בָּקָר וְגוֹ' וְעָרְפוּ שָׁם אֶת הָעֶגְלָה בַּנָּחַל. וְהַדִּין הוּא בְּסַכִּין לַעֲרֹף אוֹתָהּ. אָמַר לוֹ רַבִּי אֶלְעָזָר, לָמָּה צָרִיךְ אֶת זֶה."]]],[["בָּכָה רַבִּי שִׁמְעוֹן, וְאָמַר, וַוי לְעָלְמָא דְּאִתְמְשַׁךְ בָּתַר דָּא. דְּהָא מִן הַהוּא יוֹמָא דְּהַהוּא חִוְיָא בִּישָׁא דְּאִתְפַּתָּה בֵּיהּ אָדָם שַׁלִיט עַל אָדָם וְשַׁלִּיט עַל בְּנֵי עָלְמָא, אִיהוּ קָאִים לְמִסְטֵי עָלְמָא וְעָלְמָא לָא יָכִיל לְנָפְקָא מֵעָנְשֵׁיהּ עַד דְּיֵיתֵי מַלְכָּא מְשִׁיחָא וְיוֹקִים קוּדְשָׁא בְּרִיךְ הוּא לִדְמִיכֵי עַפְרָא דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח וְגו' וּכְתִיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְאִיהוּ קָאִים עַל עָלְמָא דָא לְמִיטַל נִשְׁמָתִין דְּכָל בְּנֵי נָשָׁא.","וְתָא חֲזֵי הָא כְּתִיב (דברים כ״א:א׳) כִּי יִמָּצֵא חָלָל וְגו' תָּא חֲזֵי, כָּל בְּנֵי עָלְמָא עַל יְדֵי מַלְאַךְ הַמָּוְת נָפְקָא נִשְׁמָתַיְיהוּ. אִי תֵימָא דְּבַּר נָשׁ דָּא עַל יְדָא דְּהַהוּא מַלְאַךְ הַמָּוֶת נָפַק נִשְׁמָתֵיהּ, לָאו הָכִי. אֶלָּא מַאן דְּקָטִיל לֵיהּ, אַפִּיק נִשְׁמָתֵיהּ עַד לָא מָטָא זִמְנֵיהּ לְשַׁלְטָאָה בֵּיהּ הַהוּא מַלְאַךְ הַמָּוֶת.","וּבְגִין כָּךְ וְלָאָרֶץ לא יְכֻפָּר וְגו' וְלָאָרֶץ דִּילָן. וְלָא דַּי לוֹן דְּקָאִים אִיהוּ לְמִסְטֵי עָלְמָא לְמַגָּנָא וּלְקַטְרְגָא תָּדִיר כָל שֶׁכֵּן דְּגָזְלִין מִינֵיהּ מַה דְּאִית לֵיהּ לְנַטְלָא. וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל בְּנוֹי, וּבְגִין כָּךְ קָרֵבִין עַל הַאי עֶגְלָא, בְּגִין לְתָקָּנָא עִמֵּיהּ מַה דְּאִתְנְטִיל הַהִיא נִשְׁמָתָא דְּבַּר נָשׁ מִנֵּיהּ, וְלָא יִשְׁתְּכַח מְקַטְרְגָא עַל (ד\"א ל\"ג קריבין בהאי) עָלְמָא.","וְרָזָא עִלָּאָה תָּנִינָן הָכָא: שׁוֹר פָּרָה, עֵגֶל עֶגְלָה, כֻּלְהוּ בְּרָזָא עִלָּאָה אִשְׁתְּכָחוּ, וּבְגִין כָּךְ בְּדָא מְתַקְּנִין לֵיהּ, וְדָא הוּא דִכְתִיב, (דברים כא) יָדֵינוּ לא שָׁפְכֻה אֶת הַדָּם הַזֶּה וְגו' לא שָׁפְכֻה וְלָא גָרִימְנָא מִיתָתֵיהּ, וּבְדָא לָא אִשְׁתְּכַח מְקַטְרְגָא עֲלַיְיהוּ, וּבְכוֹלָּא יָהִיב קוּדְשָׁא בְּרִיךְ עֵיטָא לְעָלְמָא.","תָּא חֲזֵי, כְּגווָֹנָא דָא בְּיוֹם רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים דְּדִינָא אִשְׁתְּכַח בְּעָלְמָא, אִיהוּ קָאִים לְקַטְרְגָא וְיִשְׂרָאֵל בָּעְיָין לְאִתְעָרָא בְּשׁוֹפָר, וּלְאַתְעָרָא קוֹל דְּכָלִיל בְּאֶשָׁ\"א וּמַיָ\"א וְרוּחָ\"א וְאִתְעֲבִידוּ חָד, וּלְאַשְׁמָעָא הַהוּא קוֹל מִגּוֹ שׁוֹפָר.","וְהַהוּא קוֹל סָלְקָא עַד אֲתַר דְּכָרְסְיָא דְדִינָא יָתְבָא וּבָטַשׁ בָּהּ וְסָלְקָא. כֵּיוָן דְּמָטָא הַאי קוֹל מִתַּתָּא, קוֹל דְּיַעֲקֹב אִתְתַּקַּן לְעֵילָא, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְעַר רַחֲמֵי, דְּהָא כְּגַוְונָא דְּיִשְׂרָאֵל מִתְעָרֵי לְתַתָּא קוֹל חַד כָּלִיל בְּאֶשָׁ\"א וְרוּחָ\"א וּמַיָ\"א דְּנָפְקֵי כְּחֲדָא מִגּוֹ שׁוֹפָר, הָכִי נָמֵי אִתְעַר לְעֵילָא שׁוֹפָר. וְהַהוּא קוֹל דְּכָלִיל בְּאֶשָׁ\"א וּמַיָ\"א וְרוּחָ\"א אִתְתַּקַּן, וְנָפַק דָּא מִתַּתָּא וְדָא מֵעֵילָא, וְאִתְתַּקַּן עָלְמָא וְרַחֲמֵי אִשְׁתְּכָחוּ."],[[0,"בכה ר' שמעון וכו':","בכה ר\"ש ואמר, ווי לעולם הנמשך אחר זה, היינו אחר העגלה, שמשום זה צריכים לערפה, כמ\"ש לפנינו. כי מאותו יום, שהנחש ההוא הרע, שאדם הראשון נתפתה בו, שלט על אדם ושלט על בני העולם, הוא עומד להשטין על העולם. והעולם אינו יכול לצאת מעונשו, דהיינו עונש מיתה, עד שיבא מלך המשיח, פירוש. כי חרבו של מלאך המות ה\"ס גילוי נקודת המנעולא בגוף האדם, שאינה ראויה לקבל אור החיים בסוד \u0003לא זכי הא רע,\u0004 (כנ\"ל לך דף מ\"ב ד\"ה ביאור) ונקודה זו לא תתקנה עד תחיית המתים, וע\"כ אין העולם יכול לצאת מעונשו. והקב\"ה יקים ישני עפר לתחיה. שכתוב בלע המות לנצח. וכתוב, ואת רוח הטומאה אעביר מן הארץ. ועד אז הוא עומד ליטול נשמות מכל בני אדם, שבעולם הזה."],[1,"ותא חזי הא וכו':","ובוא וראה, הרי כתוב, כי ימצא חלל וגו'. בוא וראה, כל בני העולם נשמתם יוצאת על ידי מלאך המות. היינו בגילוי נקודת המנעולא כנ\"ל, ואם תאמר גם אדם זה, שנמצא חלל, יצאה נשמתו על ידי מלאך המות. אינו כן אלא מי שהרגו, הוציא נשמתו, קודם שהגיע זמן שליטתו של מלאך המות. כלומר קודם שהגיע הזמן שתתגלה בו נקודת המנעולא, שהמלאך המות אינו יכול עוד לשלוט עליו ולהמיתו. והרוצח עם רציחתו, מעלה כח הצמצום שבמנעולא להכלים דמפתחא שבמלכות, שהם כלים דבינה, וחוזרת המלכות לבחינת נקודה בלי אורות החיים, ועם פגם הזה שבמלכות. הרוצח נוטל נשמת אדם הנרצח. ונמצא שעון רציחה, מוסיף כח הטומאה גם בכלים הטהורים שמבינה."],[2,"ובגין כך, ולארץ לא יכופר וגו':","ומשום זה כתוב, ולארץ לא יכופר וגו' ולא די להם, לרוצחים, שהנחש הרע, עומד להסטין על העולם בחנם, ומקטרג תמיד, אע\"פ שלא חטא, כל שכן בעת שגוזלים ממנו מה שיש לו ליטול, אשר עם גזלה הזו שגוזל ממלאך המות, מוסיף טומאה ופוגם גם בכלים הטהורים של המלכות הבאים מבינה, כנ\"ל בדיבור הסמוך, ומסלק האורות מכל פרצוף המלכות. וע\"כ אומר הכתוב, ולארץ לא יכופר וגו' כי אם בדם שופכו. כלומר, שצריכים לכפר על הארץ, שהיא המלכות, להחזיר לה ג\"ר דאורותיה שנסתלקו ממנה בעון הרוצח."],[2,"וקב\"ה חיים וכו':","והקב\"ה מרחם על בניו, וע\"כ מקריבים על זה, עגלה, כדי לתקן על ידו ב' דברים, א) מה שניטל נשמת האדם ממנו, מן הנרצח שעי\"ז פרחו אורות ג\"ר מהמלכות, וצריכים להחזיר לה הג\"ר. ב) שלא יקטרג על העולם. כי אחר שנמשכו לה הג\"ר בתקון א', יש כח לנחש לקטרג על העולם, כלומר שסותם אורות העולם, עי\"ז שנאחז בג\"ר הללו הנמשכים מקו שמאל. וע\"כ צריכים לתקון ב', להעביר הקטרוג הזה."],[3,"ורזא עלאה תנינן וכו':","וסוד עליון למדנו כאן. \u0003שור, פרה, עגל, עגלה,\u0004 כולם נמצאים בסוד עליון, ולפיכך, בזה \u0003בעגלה,\u0004 מתקנים אותו. וזהו שכתוב ידינו לא שפכה את הדם הזה וגו', לא שפכה, וגם לא גרמנו את מיתתו. ובזה לא נמצא מקטרג עליהם. ועל הכל נותן הקב\"ה עצה לעולם."],[3,"","פירוש. כי אמר שצריכים ב' תקונים לעון הרציחה א) לחזור ולהמשיך הג\"ר אל המלכות. ב) להעביר הקטרוג מן ג\"ר של המלכות. ותקון הא' נעשה על ידי הבאת העגלה והורדתה לנחל איתן. כי סוד הארת השמאל נקרא פני שור (כנ\"ל ב\"א דף ק\"ע אות קצ\"א) ויש בה ד' מדרגות שהן חו\"ב תו\"מ, וה\"ס שור פרה עגל עגלה, וכל בחינה מתקן את הבחינה שכנגדה, וכיון שצריכים לתקן כאן את המלכות על כן מביאים עגלה שהיא כנגד המלכות, כדי לעורר למעלה המשכת מוחין דג\"ר דשמאל אל המלכות. אמנם כיון שנמשכים הג\"ר דשמאל להמלכות, יש פחד מפני קטרוג השטן שה\"ס אחיזתו בהשמאל, ע\"כ צריכים לתקון הב' להעביר את הקטרוג, שהוא לערוף את העגלה בנחל, שעל ידי עריפה זו מבטלים את בחינת ג\"ר דג\"ר של הארת השמאל ונשארים רק הו\"ק דג\"ר, שאז אין יותר אחיזה אל השטן במוחין הללו. ונודע שלכל תקון עליון צריכים לעורר מלמטה בחינת מעשה וגם בחינת דיבור. וע\"כ צריכים ג\"כ שיאמרו הזקנים \u0003ידינו לא שפכה הדם הזה,\u0004 דהיינו שחוזרים וממשיכים הג\"ר אל המלכות, שנסתלקו ממנה בעון שפיכת דמים, והוא כנגד המעשה דהבאת העגלה לנחל איתן, שה\"ס תקון א'. \u0003ועינינו לא ראו,\u0004 היינו הסתרת הג\"ר המכונים ראיה, שבזה מעבירים את קטרוג הנחש מהארת השמאל, שה\"ס תקון הב', שהוא כנגד המעשה של עריפת העגלה."],[3,"","וזה אמרו \u0003ודא הוא דכתיב ידינו לא שפכה הדם הזה,\u0004 שה\"ס תקון הא' להמשכת הג\"ר דשמאל כנ\"ל. \u0003ולא גרימנא מיתתיה\u0004 שהוא הפירוש של ועינינו לא ראו, כמ\"ש חז\"ל (סוטה מ\"ה ע\"ב), שה\"ס תקון הב' לחעביר קטרוגו של השטן כנ\"ל, ובזה מתבאר שאלת ר' אלעזר (לעיל אות שע\"ו) ששאל \u0003האי למאי אצטריך.\u0004 כי הוא נצרך לב' תקונים האלו."],[4,"תא חזי כגוונא וכו':","בוא וראה כעין זה ביום ראש השנה ויום הכפורים שהדין נמצא אז בעולם, והשטן עומד אז לקטרג, שישראל צריכים אז להתעורר בשופר ולעורר קול, הכלול ממים אש ורוח, שהם חג\"ת, שנעשו בו אחד, ולהשמיע אותו הקול מתוך השופר."],[4,"","פירוש. י\"ב חדשי השנה הם תקון המלכות מתחילתה עד סופה, וכיון שסופה אינו נשלם לגמרי עד גמר התקון, ע\"כ צריכים בכל שנה לחזור ולתקנה, וע\"כ בכל ראש השנה אנו מתחילים מבראשית תקון המלכות, דהיינו כמו שנאצלה ביום ד' דמעשה בראשית שאז היתה, בסו\"ה, ויעש אלקים את שני מארת הגדולים, שאז היתה בשלמות ג\"ר דהארת השמאל, שה\"ס הארת השורק, דהיינו חכמה בלי חסדים. וע\"כ קטרגה הלבנה, אין ב' מלכים משתמשים בכתר אחד, שלא היתה יכולה לסבול חסרון החסדים וה\"ס קטרוג השטן גם כן, שקטרוגו נאחז בהמלכות להמשיך דינים, כל אימת שמאירים בה הג\"ר של השמאל. וצריכים להעביר אחיזת השטן וקטרוגו מן המלכות בעת ההוא. וז\"ש \u0003איהו קאים לקטרגא.\u0004 כיון שנגלו בכל ר\"ה ג\"ר דשמאל, ע\"כ עומד אז השטן לקטרג על המלכות."],[4,"","וזה אמרו, \u0003וישראל בעיין לאתערא בשופר ולאתערא קול דכליל באשא ומיא ורוחא.\u0004 כי כדי להעביר קטרוג השטן צריכים גם כאן לעשות איזו פעולה לבטל הג\"ר דג\"ר של הארת השמאל, כמו שנעשה ע\"י עריפת העגלה, וע\"י אמירת הזקנים, ועינינו לא ראו, בסוד תקון הב' אשר שם. כנ\"ל. ופעולה זו, ה\"ס הקול שאנו מעלים על ידי השופר. ונודע שבדרך כלל, יש ב' מיני קולות, א) קול המלכות הבלתי נמתקת בבינה. ב) קול הבינה או של המלכות הנמתקת בבינה, שאז קולה כקול הבינה. (כמ\"ש לעיל בהקדמת הזהר דף קל\"ח אות קע\"א ד\"ה ובזה ע\"ש) ואומר שקול זה שאנו מעלים כדי למעט הג\"ר דג\"ר, הוא קול דבינה."],[4,"","וז\"ש \u0003ולאשמעא ההוא קול מגו שופר,\u0004 דהיינו בינה המכונה שופר. שה\"ס המסך דחירק שעליו יוצא קו אמצעי המיחד ב' הקוין ימין ושמאל זה בזה (כנ\"ל ב\"א דף ט\"ז אות ט' ד\"ה וזה) וז\"ש \u0003קול דכליל באשא ומיא ורוחא,\u0004 דהיינו קול דכליל בג' קוין המכונים: מים, אש, רוח. \u0003ואתעבידו חד,\u0004 שע\"י המסך הזה, נעשו ג' קוין אחד. ועי\"ז נתמעט ג\"ר דג\"ר מהשמאל (כנ\"ל ב\"א דף רצ\"ד אות שע\"ב ד\"ה רבי) ואז מסתלק קטרוג השטן מהמלכות כמ\"ש לפנינו."],[5,"וההוא קול סלקא וכו':","וקול ההוא עולה עד המקום שכסא הדין יושב דהיינו לג\"ר דשמאל שהקטרוג נאחז שם, ומכה בה דהיינו שממעט הג\"ר דג\"ר אשר שם, ועולה המלכות מכסא דין, לכסא רחמים, ואחר שמגיע קול הזה מלמטה, הנה קול יעקב נתתקן למעלה, שה\"ס קומת החסדים היוצאת על המסך הנ\"ל שה\"ס קו אמצעי הנק' ת\"ת ונק' יעקב, ונקרא רחמים. ואז נתעורר הקב\"ה ברחמים. כי כמו שישראל מעוררים קול אחד למטה. שהוא כלול מאש ומים ורוח היוצאים מתוך השופר, כן מתעורר כנגדם למעלה בשופר העליון, שהוא בינה. כי הכח לתקוע הוא \u0003אש,\u0004 והקול נעשה ע\"י \u0003רוח\u0004 ועם הרוח יוצא ג\"כ זיעה והבל שה\"ס \u0003מים.\u0004 והם מעוררים ג' קוין עליונים שבבינה, שממנה נמשכים המוחין לז\"א ולמלכות, \u0003וההוא קול דכליל באשא ומיא ורוחא אתתקן,\u0004 וקול הכולל אש מים ורוח שעלה מלמטה, דהיינו המסך, נתתקן, ויוצא זה מלמטה, דהיינו המסך, וזה מלמעלה דהיינו קומת החסדים היוצאת על המסך, ונתתקן העולם שהיא המלכות והרחמים נמצאים."]],[[0,"","בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, אוֹי לָעוֹלָם שֶׁנִּמְשָׁךְ אַחַר זֶה, שֶׁהֲרֵי מֵאוֹתוֹ הַיּוֹם שֶׁאוֹתוֹ הַנָּחָשׁ הָרָע הִתְפַּתָּה בּוֹ אָדָם, שׁוֹלֵט עַל הָאָדָם וְשׁוֹלֵט עַל בְּנֵי הָעוֹלָם, הוּא עוֹמֵד לְהַסְטוֹת אֶת הָעוֹלָם, וְהָעוֹלָם לֹא יָכוֹל לָצֵאת מֵעָנְשׁוֹ עַד שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ וְיָקִים הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יְשֵׁנֵי הֶעָפָר, שֶׁכָּתוּב (ישעיה כא) בִּלַּע הַמָּוֶת לָנֶצַח וְגוֹ', וְכָתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ. וְהוּא עוֹמֵד עַל עוֹלָם זֶה לִטֹּל אֶת כָּל נִשְׁמוֹת בְּנֵי הָאָדָם."],[1,"","וּבֹא וּרְאֵה, הֲרֵי כָּתוּב (דברים כא) כִּי יִמָּצֵא חָלָל וְגוֹ'. בּא רְאֵה, כָּל בְּנֵי הָעוֹלָם נִשְׁמָתָם יוֹצֵאת עַל יְדֵי מַלְאַךְ הַמָּוֶת. אִם תֹּאמַר שֶׁבֶּן אָדָם הַזֶּה יָצְאָה נִשְׁמָתוֹ עַל יְדֵי אוֹתוֹ מַלְאַךְ הַמָּוֶת - לֹא כָּךְ! אֶלָּא מִי שֶׁהוֹרֵג אוֹתוֹ, הוֹצִיא אֶת נִשְׁמָתוֹ בְּטֶרֶם הִגִּיעַ זְמַנּוֹ שֶׁיִּשְׁלֹט בּוֹ אוֹתוֹ מַלְאַךְ הַמָּוֶת."],[2,"","וְלָכֵן וְלָאָרֶץ לֹא יְכֻפַּר וְגוֹ'. וְלָאָרֶץ שֶׁלָּנוּ. וְלֹא דַי לָהֶם שֶׁעוֹמֵד הוּא לְהַסְטוֹת הָעוֹלָם לְחִנָּם וּלְקַטְרֵג תָּמִיד, כָּל שֶׁכֵּן שֶׁגּוֹזְלִים מִמֶּנּוּ מַה שֶּׁיֵּשׁ לוֹ לָקַחַת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל בָּנָיו, וְלָכֵן מַקְרִיבִים אֶת הָעֶגְלָה הַזּוֹ, כְּדֵי לְתַקֵּן עִמּוֹ מַה שֶּׁנִּלְקְחָה אוֹתָהּ נְשָׁמָה שֶׁל הָאָדָם מִמֶּנּוּ, וְלֹא יִמָּצֵא מְקַטְרֵג עַל (ד\"א הקרובים בזה) הָעוֹלָם."],[3,"","וְסוֹד עֶלְיוֹן שָׁנִינוּ כָּאן. שׁוֹר, פָּרָה, עֵגֶל, עֶגְלָה - כֻּלָּם בְּסוֹד עֶלְיוֹן נִמְצָאִים, וְלָכֵן בָּזֶה מְתַקְּנִים אוֹתוֹ, וְזֶהוּ שֶׁכָּתוּב (דברים כא) יָדֵינוּ לֹא שָׁפְכֻה אֶת הַדָּם הַזֶּה וְגוֹ'. לֹא שָׁפְכוּ וְלֹא גָרַמְנוּ מִיתָתוֹ. וּבָזֶה לֹא נִמְצָא עֲלֵיהֶם מְקַטְרֵג, וּבַכֹּל נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה לָעוֹלָם."],[4,"","בֹּא רְאֵה, כְּמוֹ זֶה בְּרֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים, שֶׁנִּמְצָא הַדִּין בָּעוֹלָם, הוּא עוֹמֵד לְקַטְרֵג, וְיִשְׂרָאֵל צְרִיכִים לְהִתְעוֹרֵר בַּשּׁוֹפָר וּלְעוֹרֵר קוֹל שֶׁכָּלוּל בְּאֵ\"שׁ וּמַיִ\"ם רוּ\"חַ וְנַעֲשִׂים אֶחָד, וּלְהַשְׁמִיעַ אוֹתוֹ קוֹל מִתּוֹךְ הַשּׁוֹפָר."],[5,"","וְאוֹתוֹ קוֹל עוֹלֶה עַד מָקוֹם שֶׁיּוֹשֵׁב כִּסֵּא הַדִּין וּמַכֶּה בּוֹ וְעוֹלֶה. כֵּיוָן שֶׁמַּגִּיעַ הַקּוֹל הַזֶּה מִלְּמַטָּה, הַקּוֹל שֶׁל יַעֲקֹב נִתְקָן לְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְעוֹרֵר רַחֲמִים. שֶׁהֲרֵי כְּמוֹ שֶׁיִּשְׂרָאֵל מְעוֹרְרִים לְמַטָּה קוֹל אֶחָד כָּלוּל בְּאֵ\"שׁ וְרוּ\"חַ מַיִ\"ם שֶׁיּוֹצְאִים כְּאֶחָד מִתּוֹךְ הַשּׁוֹפָר, כָּךְ גַּם מִתְעוֹרֵר לְמַעְלָה שׁוֹפָר. וְאוֹתוֹ קוֹל שֶׁכָּלוּל בְּאֵ\"שׁ וּמַיִ\"ם רוּ\"חַ נִתְקָן, וְיוֹצֵא זֶה מִלְּמַטָּה וְזֶה מִלְמַעְלָה, וְנִתְקָן הָעוֹלָם וְנִמְצָאִים הָרַחֲמִים."]]],[["וְהַהוּא מְקַטְרְגָא אִעַרְבֵּב דְּחֲשִׁיב לְשַׁלְטָאָה בְּדִינָא וּלְקַטְרְגָא בְּעָלְמָא, וְחָמֵי דְּמִתְעָרֵי רַחֲמֵי, כְּדֵין אִעַרְבָּב וְאִתְּשַׁשׁ חֵילֵיהּ וְלָא יָכִיל לְמֶעְבַּד מִידִי, וְקוּדְשָׁא בְּרִיךְ הוּא דָּאִין עָלְמָא בְּרַחֲמֵי, דְּאִי תֵימָא דְדִינָא אִתְעֲבִיד, לָאו הָכִי, אֶלָּא אִתְחַבָּרוּ רַחֲמֵי בְּדִינָא, וְעָלְמָא אִתְדָּן בְּרַחֲמֵי.","תָּא חֲזֵי, כְּתִיב, (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ דְּאִתְכַּסְיָא סִיהֲרָא. דְּהָא כְּדֵין שָׁלְטָא הַאי חִיוְיָא בִּישָׁא וְיָכִיל לְנַזְקָא עָלְמָא, וְכַד מִתְעָרֵי רַחֲמֵי, סָלְקָא סִיהֲרָא וְאִתְעֲבָרַת מִתַּמָּן, וְאִיהוּ אִתְעַרְבֵּב וְלָא יָכִיל לְשַׁלְטָאָה, וְאִתְעֲבַר דְּלָא יִתְקְרַב תַּמָּן, וְעַל דָּא בְּיוֹם רֹאשׁ הַשָּׁנָה בָּעֵי לְעַרְבְּבָא לֵיהּ כְּמַאן דְּאִתְעַר מִשְּׁנָתֵיהּ וְלָא יְדַע כְּלוּם.","בְּיוֹם הַכִּפּוּרִים בָּעֵי לְנַיְיחָא וּלְמֶעְבַּד לֵיהּ נַיְיחָא דְּרוּחָא בְּשָׂעִיר דְּקָרֵבִין לֵיהּ, וּכְדֵין אִתְהַפַּךְ סַנֵּיגוֹרְיָא עֲלַיְיהוּ דְיִשְׂרָאֵל, אֲבָל בְּיוֹמָא דְּרֹאשׁ הַשָּׁנָה אִתְעַרְבָּב דְּלָא יְדַע וְלָא יָכִיל לְמֶעְבַּד כְּלוּם. חָמֵי אִתְעֲרוּתָא דְּרַחֲמֵי סָלְקִין מִתַּתָּא, וְרַחֲמֵי מִלְּעֵילָא וְסִיהֲרָא סָלְקָא בֵּינַיְיהוּ. כְּדֵין אִתְעַרְבָּב וְלָא יְדַע כְּלוּם וְלָא יָכִיל לְשַׁלְטָאָה.","וְקוּדְשָׁא בְּרִיךְ הוּא דָּן לְהוּ לְיִשְׂרָאֵל בְּרַחֲמֵי, וְחָיִיס עֲלַיְיהוּ וְאִשְׁתְּכַח לְהוּ זִמְנָא כָּל אִנּוּן י' יוֹמִין דְּבֵין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים לְקַבְּלָא כָּל אִנּוּן דְּתָיְיבִין קַמֵּיהּ וּלְכַפָּרָא לוֹן מֵחוֹבַיְיהוּ וְסָלִיק לוֹן לְיוֹמָא דְכִפּוּרֵי.","וְעַל דָּא בְּכוֹלָּא קוּדְשָׁא בְּרִיךְ הוּא פַּקִּיד לוֹן לְיִשְׂרָאֵל לְמֶעְבַּד עוֹבָדָא בְּגִין דְּלָא יִשְׁלוֹט עֲלַיְיהוּ מַאן דְּלָא אִצְטְרִיךְ, וְלָא יִשְׁלוֹט עֲלַיְיהוּ דִינָא, וִיהוֹן כֻּלְהוֹן זַכָּאִין בְּאַרְעָא כִּרְחִימוּ דְּאַבָּא עַל בְּנִין, וְכוֹלָּא בְּעוֹבָדָא וּבְמִלִּין תַּלְיָא, וְהָא אוֹקִימְנָא מִלִּין."],[[0,"וההוא מקטרגא אערבב וכו':","והמקטרג נבוך, שחשב לשלוט בדין ולקטרג בעולם. כלומר, שלא עלה על דעתו, שג\"ר דשמאל יתמעטו פעם, ויתעלם שליטתו וקטרוגו, ורואה שהרחמים מתעוררים, והוא נבוך, וכחו רפה, ואינו יכול לעשות מאומה, והקב\"ה דן את העולם ברחמים. ואם תאמר שדין נעשה, דהיינו במה שנתמעטו הג\"ר דקו שמאל ע\"י קול שופר כנ\"ל, אינו כן. אלא שנתחברו רחמים בדין, והעולם נדון ברחמים. פירוש, כי בעלית קול שופר מלמטה, שה\"ס העלאת מ\"ן דמסך דחירק, יצאה קומת חסדים, שה\"ס קו אמצעי, על המסך (כנ\"ל באות שפ\"ב ד\"ה וההוא) שהוא נקרא יעקב והוא רחמים, והעולם מקבל הרחמים מן קו אמצעי. ולפיכך אין התמעטות ג\"ר דשמאל נחשב לדין. כי זולת זה, לא היו מתגלים הרחמים בעולם."],[1,"תא חזי כתיב וכו':","בוא וראה, כתוב, תקעו בחדש שופר בכסה ליום חגנו, \u0003בכסה,\u0004 פירושו שנתכסה הלבנה. דהיינו המלכות כי אז מחמת הארת השמאל, שולט אותו נחש הרע, ויכול להזיק העולם. וכאשר מתעוררים הרחמים על ידי תקיעת שופר, עולה הלבנה ונעברה משם, דהיינו מהארת השמאל מטעם שנתמעטו הג\"ר ע\"י קול שופר כנ\"ל. והשטן נבוך ואינו יכול לשלוט, והוא נעבר מן הלבנה, ואינו קרב עוד שם. כי אחר התמעטות הג\"ר דשמאל אין לו עוד מה לינק ממנה או לקטרג כנ\"ל. ועל כן ביום ראש השנה, צריכים להומם את השטן, בדומה למצב הנעור משנתו ואינו יודע מאומה."],[2,"בי\"ה בעי לנייחא וכו':","ביום הכפורים צריכים לנהוג עם השטן בנחת, ולעשות לו נחת רוח עם השעיר לעזאזל שמקריבין לו, ששולחים המדברה ששם מקומו, ואז נהפך להיות מליץ טוב על ישראל. אבל ביום ראש השנה נעשה נבוך, ואינו יודע, ואינו יכול לעשות מאומה כי רואה התעוררות רחמים עולה מלמטה ורחמים מושפעים מלמעלה והלבנה, שהיא המלכות, מתעלה ביניהם, אז הוא נבוך, ואינו יודע כלום, ואינו יכול לשלוט."],[3,"וקב\"ה דן וכו':","והקב\"ה דן את ישראל ברחמים, ומרחם עליהם ונותן להם זמן, כל אלו עשרת הימים שבין ראש השנה ליום הכפורים, לקבל כל אלו השבים לפניו, לכפר להם עונותיהם, ומעלה אותם לקדושת יום הכפורים."],[4,"ועל דא בכלא וכו':","ועל כן לתקון כל, צוה הקב\"ה לישראל לעשות המצוה של תקיעת שופר. א) שלא ישלוט עליהם מי שאינו צריך. דהיינו להעביר שליטת השטן וקטרוגו. ב) שלא ישלוט עליהם הדין, אלא שישרה עליהם הרחמים. ויהיו זוכים כולם לרחמיו בארץ כרחם אב על בנים. והכל תלוי, בהתעוררות התחתונים, במעשה ובדבור. וכבר נתבארו הדברים."]],[[0,"","וְאוֹתוֹ מְקַטְרֵג מִתְעַרְבֵּב, שֶׁחוֹשֵׁב לִשְׁלֹט בַּדִּין וּלְקַטְרֵג בָּעוֹלָם, וְרוֹאֶה שֶׁמִּתְעוֹרְרִים רַחֲמִים. אָז מִתְעַרְבֵּב וְתָשׁ כֹּחוֹ וְלֹא יָכוֹל לַעֲשׂוֹת דָּבָר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא דָּן אֶת הָעוֹלָם בְּרַחֲמִים. שֶׁאִם תֹּאמַר שֶׁנַּעֲשֶׂה דִין - לֹא כָּךְ! אֶלָּא מִתְחַבְּרִים רַחֲמִים עִם דִּין, וְהָעוֹלָם נִדּוֹן בְּרַחֲמִים."],[1,"","בֹּא רְאֵה, כָּתוּב (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר בַּכֶּסֶה לְיוֹם חַגֵּנוּ, שֶׁהַלְּבָנָה מִתְכַּסָּה, שֶׁהֲרֵי אָז שׁוֹלֵט הַנָּחָשׁ הָרָע וְיָכוֹל לְהַזִּיק לָעוֹלָם. וּכְשֶׁמִּתְעוֹרְרִים רַחֲמִים, עוֹלָה הַלְּבָנָה וּמָעֳבֶרֶת מִשָּׁם, וְהוּא מִתְעַרְבֵּב וְלֹא יָכוֹל לִשְׁלֹט, וְעוֹבֵר שֶׁלֹּא יִתְקָרֵב לְשָׁם, וְלָכֵן בְּרֹאשׁ הַשָּׁנָה צָרִיךְ לְעַרְבֵּב אוֹתוֹ כְּמִי שֶׁמִּתְעוֹרֵר מִשְּׁנָתוֹ וְלֹא יוֹדֵעַ כְּלוּם."],[2,"","בְּיוֹם הַכִּפּוּרִים צָרִיךְ לָנוּחַ וְלַעֲשׂוֹת לוֹ נַחַת רוּחַ בַּשָּׂעִיר שֶׁמַּקְרִיבִים לוֹ, וְאָז מִתְהַפֵּךְ לְסָנֵגוֹר עַל יִשְׂרָאֵל, אֲבָל בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה מִתְעַרְבֵּב, שֶׁלֹּא יוֹדֵעַ וְלֹא יָכוֹל לַעֲשׂוֹת כְּלוּם. רוֹאֶה הִתְעוֹרְרוּת שֶׁל הָרַחֲמִים עוֹלִים מִלְּמַטָּה וְרַחֲמִים מִלְמַעְלָה וְהלְּבָנָה עוֹלָה בֵּינֵיהֶם, אָז הוּא מִתְעַרְבֵּב וְלֹא יוֹדֵעַ כְּלוּם וְלֹא יָכוֹל לִשְׁלֹט."],[3,"","וְהַקָּדוֹשׁ בָּרוּךָ הוּא דָּן אֶת יִשְׂרָאֵל בְּרַחֲמִים וְחָס עֲלֵיהֶם וּמוֹצֵא לָהֶם זְמַן כָּל אוֹתָם עֲשָׂרָה יָמִים שֶׁבֵּין רֹאשׁ הַשָּׁנָה לְיוֹם הַכִּפּוּרִים לְקַבֵּל אֶת כָּל אוֹתָם הַשָּׁבִים לְפָנָיו וּלְכַפֵּר לָהֶם מֵחֲטָאֵיהֶם וּמַעֲלֶה אוֹתָם לְיוֹם הַכִּפּוּרִים."],[4,"","וְעַל זֶה בַּכֹּל מְצַוֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל לַעֲשׂוֹת מַעֲשֶׂה, כְּדֵי שֶׁלֹּא יִשְׁלֹט עֲלֵיהֶם מִי שֶׁלֹּא צָרִיךְ וְלֹא יִשְׁלֹט עֲלֵיהֶם הַדִּין וְיִהְיוּ כֻלָּם צַדִּיקִים בָּאָרֶץ כְּאַהֲבַת הָאָב עַל הַבָּנִים (בני אדם), וְהַכֹּל תָּלוּי בְּמַעֲשֶׂה וּבְדִבּוּרִים, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים."]]],[["\u0003מִדְרָשׁ הַנֶּעֱלָם\u0004 וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. רַבִּי יוֹחָנָן פָּתַח בְּהַאי קְרָא (שיר השירים ז׳:ו׳) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן מֶלֶךְ אָסוּר בָּרְהָטִים. עָשָׂה קוּדְשָׁא בְּרִיךְ הוּא שִׁלְטוֹנִים לְמַעְלָה וְשִׁלְטוֹנִים לְמַטָה. כְּשֶׁנּוֹתֵן קוּדְשָׁא בְּרִיךְ הוּא מַעֲלָה לַשָּׂרִים שֶׁל מַעְלָה נוֹטְלִים מַעֲלָה הַמְּלָכִים שֶׁל מַטָה. נָתַן מַעֲלָה לְשָׂרוֹ שֶׁל בָּבֶל, נָטַל מַעֲלָה נְבוּכַדְנֶצַּר הָרָשָׁע דִּכְתִיב בֵּיהּ (דניאל ב׳:ל״ח) אַנְתְּ הוּא רֵאשָׁה דִּי דַּהֲבָא, והָיוּ כָּל הָעוֹלָם מְשׁוּעְבָּדִים תַּחַת יָדוֹ וּבְנוֹ וּבֶן בְּנוֹ, הֲדָא הוּא דִכְתִיב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, זֶהוּ נְבוּכַדְנֶצַּר, הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ט׳) תְּחֹתוֹהִי תַּטְלֵל חֵיוַת בָּרָא. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן, זְהוּ בֵּלְשַׁצַּר דְּאָמַר (דניאל ה׳:ז׳) אַרְגְּוָונָא יִלְבָּשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים, זֶהוּ אֱוִיל מְרוֹדָךְ שֶׁהָיָה אָסוּר עַד שֶׁמֵּת אָבִיו נְבוּכַדְנֶצַּר וּמָלַךְ תַּחְתָּיו.","אָמַר רַבִּי יְהוּדָה לְמַאי אֲתָא הַאי טַעַם בְּשִׁיר הַשִּׁירִים. אֶלָּא אָמַר רַבִּי יְהוּדָּה שִׁבְעָה דְבָרִים נִבְרְאוּ קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם, וְאֵלּוּ הֵן וְכוּ', כִּסֵּא הַכָּבוֹד שֶׁנֶּאֱמַר (תהילים צ״ג:ב׳) נָכוֹן כִּסְאֲךָ מֵאָז מֵעוֹלָם אָתָּה וּכְתִיב, (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. שֶׁהוּא הָיָה רֹאשׁ הַנִּקְדַּם לַכֹּל, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּשָׁמָה הַטְהוֹרָה מִכִּסֵּא הַכָּבוֹד לִהְיוֹת מְאִירָה לַגּוּף, הֲדָא הוּא דִכְתִיב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל, זְהוּ כִּסֵּא הַכָּבוֹד שֶׁהוּא רֹאשׁ עַל הַכֹּל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן, זוֹ הִיא הַנְּשָׁמָה הַנִּטֶלֶת מִמֶּנּוּ. מֶלֶךְ אָסוּר בָּרְהָטִים, זְהוּ הַגּוּף שֶׁהוּא אָסוּר בַּקֶּבֶר וְכָלָה בֶּעָפָר וְלֹא נִשְׁאָר מִמֶּנּוּ אֶלָּא כִּמְלֹא תַּרְוָד רֶקֶב. וּמִמֶּנּוּ יִבָּנֶה כָּל הַגּוּף. וּכְשֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַגּוּף הוּא אוֹמֵר לָאָרֶץ שֶׁתַּפְלִיט אוֹתוֹ לַחוּץ דִּכְתִיב (ישעיהו כ״ו:י״ט) ואֶרְץ רְפָאִים תַּפִּיל.","אָמַר רַבִּי יוֹחָנָן הַמֵּתִים שֶׁבָּאֶרֶץ הֵם חַיִּים תְּחִלָּה הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, נְבֵלָתִי יְקוּמוּן אֵלּוּ שֶׁבְּחוּצָּה לָאָרֶץ. הָקִיצּוּ ורַנְּנוּ שׁוֹכְנֵי עָפָר, אֵלּוּ הַמֵּתִים שֶׁבַּמִּדְבָּר. דְּאָמַר רַבִּי יוֹחָנָן לָמָּה מֵת משֶׁה בְּחוּצָּה לָאָרֶץ. לְהַרְאוֹת לְכָל בָּאֵי עוֹלָם, כְּשֵׁם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת לְמשֶׁה כָּךְ עָתִיד לְהַחֲיוֹת לְדוֹרוֹ (למה) שֶׁהֵם קִבְּלוּ הַתּוֹרָה. (דאמר רבי יוחנן) וְעֲלֵיהֶם נֶאֱמַר (ירמיהו ב׳:ב׳) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לא זְרוּעָה.","דָּבָר אַחֵר הָקִיצּוּ ורַנְּנוּ שׁוֹכְנִי עָפָר, אֵלּוּ הֵם הָאָבוֹת. וְהַמֵּתִים בְּחוּצָּה לָאָרֶץ יִבָּנֶה גוּפָם וּמִתְגַּלְגְּלִים תַּחַת הָאָרֶץ עַד אֶרֶץ יִשְׂרָאֵל ושָׁם יְקַבְּלוּ נִשְׁמָתָם וְלֹא בְּחוּצָּה לָאָרֶץ, הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ז:י״ב) לָכֵן הִנָּבֵא וְאָמַרְתָּ אֲלֵיהֶם הִנֵּה אָנֹכִי פּוֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. מַה כְּתִיב אַחֲרָיו ונָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם.","רַבִּי פִּנְחָס אָמַר הַנְּשָׁמָה נִטְלָה מִכִּסֵּא הַכָּבוֹד שֶׁהוּא הָרֹאשׁ כִּדְקָאָמַר (שיר השירים ז׳:ו׳) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא דַּלַת הָרֹאשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים, הוּא הַגּוּף שֶׁהוּא אָסוּר בַּקְבָרִים. זֶהוּ הַגּוּף וְזֶהוּ שָׂרָה וְזֶהוּ מֶלֶךְ. וְקוּדְשָׁא בְּרִיךְ הוּא פּוֹקְדָהּ לַמּוֹעֵד אֲשֶׁר דִּבֶּר אֵלָיו הֲדָא הוּא דִכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. פּוֹקֵד אֶת הַגּוּף לַזְּמַן הַיָּדוּעַ שֶׁבּוֹ יפְקוֹד הַצַּדִּיקִים.","אָמַר רַבִּי פִּנְחָס עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַפּוֹת לְגוּף הַצַּדִּיקִים לֶעָתִיד לָבֹא כְּיוֹפִי שֶׁל אָדָם הָרִאשׁוֹן כְּשֶׁנִּכְנַס לַגַּן עֵדֶן, שֶׁנְּאֱמַר (ישעיהו נ״ח:י״א) וְנָחֲךָ יְיָ תָּמִיד וְגו' וְהָיִיתָ כְּגַן רָוְה. אָמַר רַבִי לֵוִי הַנְּשָׁמָה בְּעוֹדָהּ בְּמַעֲלָתָהּ נִיזוֹנֶת בְּאוֹר שֶׁל מַעְלָה וּמִתְלַבֶּשֶׁת בּוֹ, וּכְשֶׁתִּכָּנֵס (ונשתרש) לַגוּף לֶעָתִיד לָבֹא בְּאוֹתוֹ הָאוֹר מַמָּשׁ תִּכָּנֵס, וְאֲזַי הַגּוּף יָאִיר כְּזוֹהַר הָרָקִיעַ הֲדָא הוּא דִכְתִיב, (דניאל י״ב:ג׳) וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזוֹהַר הָרָקִיעַ, וְיַשִּׂיגוּ בְּנִי אָדָם דֵּעָה שְׁלֵימָה שֶׁנְּאֱמַר (ישעיהו י״א:ט׳) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת יְיָ. מְנָא לָן הָא, מִמַּה דִּכְתִיב וְנָחֲךָ יְיָ תָּמִיד וְהִשְׂבִּיעַ בְּצַּחֲצָּחוֹת נַפְשֶׁךָ. זְה אוֹר שֶׁל מַעְלָה. וְעַצְּמוֹתֶיךָ יַחְלִיץ זְה פְּקִידַת הַגּוּף. וְהָיִיתָ כְּגַן רָוְה וּכְמוֹצָּא מַיִם אֲשֶׁר לא יְכַזְבוּ מֵימָיו. זֶהוּ דַעַת הַבּוֹרֵא יִתְבָּרַךְ, וְאֲזַי יֵדְעוּ הַבְּרִיּוֹת שֶׁהַנְּשָׁמָה הַנִּכְנֶסֶת בָּהֶם שֶׁהִיא נִשְׁמַת הַחַיִּים נִשְׁמַת הַתַּעֲנוּגִים שֶׁהִיא קִבְּלָה תַּעֲנוּגִים מִלְּמַעְלָה וּמְעָדֵנֶּת לַגּוּף וְהַכֹּל תְּמֵהִים בָּהּ ואוֹמְרִים (שיר השירים ז׳:ז׳) מַה יָּפִית וּמַה נָּעַמְתְּ אַהֲבָה בַּתַּעֲנוּגִים. זוֹ הִיא הַנְּשָׁמָה לֶעָתִיד לָבֹא.","אָמַר רַבִּי יְהוּדָה תָּא חֲזֵי, שֶׁכָּךְ הוּא דִּכְתִיב, (שיר השירים ז׳:ז׳) מֶלֶךְ אָסוּר בָּרְהָטִים. וּכְתִיב בַּתְרֵיהּ מַה יָּפִית וּמַה נָּעַמְתְּ. וְאָמַר רַבִּי יְהוּדָה בְּאוֹתוֹ זְמַן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ עוֹלָמוֹ וְלִשְׂמוֹחַ בִּבְרִיּוֹתָיו שֶׁנְּאֱמַר (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו. וְאֲזַי יִהְיֶה שְׂחוֹק בָּעוֹלָם מַה שֶּׁאֵין עַכְשָׁיו, דִּכְתִיב, (תהילים קכ״ו:ב׳) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וגו'. הֲדָא הוּא דִכְתִיב וַתֹּאמֶר שָׂרָה צְּחוֹק עָשָׂה לִי אֱלהִים. שֶׁאֲזַי עֲתִידִים בְּנֵי אָדָם לוֹמַר שִׁירָה שֶׁהוּא עֵת שְׂחוֹק. רַבִּי אַבָּא אָמַר הַיּוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו לֹא הָיְתָה שִׂמְחָה כְּמוֹתָהּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַצַּדִּיקִים הַנִּשְׁאָרִים בִּירוּשָׁלַיִם לא יָשׁוּבוּ עוֹד לְעַפְרָם דִּכְתִיב, (ישעיהו ד׳:ג׳) והָיָה הַנִּשְׁאָר בְּצִּיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַםִ קָדוֹשׁ יֵאָמַר לוֹ. הַנּוֹתָר בְּצִּיּוֹן וּבִיְרוּשָׁלַםִ דַּיְיקָא.","אָמַר רַבִּי אַחָא אִם כֵּן זְעִירִין אִנּוּן, אֶלָּא כָּל אִנּוּן דְּאִשְׁתְּאָרוּ בְּאַרְעָא קַדִּישָׁא דְיִשְׂרָאֵל דִּינָא דִלְהוֹן כִּיְרוּשָׁלַםִ וּכְצִּיּוֹן לְכָל דָּבָר. מְלַמֵּד דְּכָל אֶרֶץ יִשְׂרָאֵל בִּכְלַל יְרוּשָׁלַםִ הִיא, מִמַּשְׁמַע דִּכְתִיב, (ויקרא י״ט:כ״ג) וכִי תָבֹאוּ אֶל הָאָרֶץ הַכֹּל בִּכְלָל.","רַבִּי יְהוּדָה בְּרַבִּי אֶלְעָזָר שָׁאַל לְרַבִּי חִזְקִיָּה, אָמַר לוֹ מֵתִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹתָם, לָמָּה לָא יָהִיב נִשְׁמַתְהוֹן בְּאֲתַר דְּאִתְקְבָרוּ תַּמָּן וְיֵיתוּן לְאַחֲיָיא בְּאַרְעָא דְיִשְׂרָאֵל. אָמַר לוֹ נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת יְרוּשָׁלַםִ וְשֶׁלֹּא תֵּהָרֵס לְעוֹלָמִים, דְּאָמַר רַבִּי יִרְמְיָה עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵשׁ עוֹלָמוֹ וְלִבְנוֹת יְרוּשָׁלַםִ וּלְהוֹרִידָהּ בְּנוּיָה מִלְּמַעְלָה (ס\"א בנין) בְּגִין שֶׁלֹּא יִהָרֵס, וְנִשְׁבַּע שֶׁלא תִּגְלֶה עוֹד כְּנֶסֶת יִשְׂרָאֵל, וְנִשְׁבַּע שֶׁלֹּא יֵהָרֵס בִּנְיַן יְרוּשָׁלַ ם, שֶׁנֶּאֱמַר (ישעיהו ס״ב:ד׳) לא יִאָמֵר לָךְ עוֹד עֲזוּבָה וּלְאַרְצֵּךְ לֹא יֵאָמֵר עוֹד שְׁמָמָה. וּבְכָל מָקוֹם שֶׁאַתָּה מוֹצֵּא לא לֹא, הִיא שְׁבוּעָה, הֲדָא הוּא דִכְתִיב, (בראשית ט׳:י״א) וְלֹא יִכָּרֵת כָּל בָּשָׂר עוֹד מִמֵּי הַמַּבּוּל ולֹא יִהְיֶה עוֹד מַבּוּל וְגו' וּכְתִיב, (ישעיהו נ״ד:ט׳) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ. מִכָּאן שֶׁלֹּא לֹא, שְׁבוּעָה. וּמִן לָאו אַתָּה שׁוֹמֵעַ הֵן. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּים עוֹלָמוֹ קִיּוּם שֶׁלֹּא תִּגְלֶה כְּנֶסֶת יִשְׂרָאֵל וְלֹא תֵּהָרֵס בִּנְיַן בֵּית הַמִּקְדָּשׁ, לְפִיכָךְ אֵין מְקַבְּלִין נִשְׁמָתָן אֶלָּא בְּמָקוֹם קַיָּים לְעוֹלָמִים, כְּדֵי שֶׁתִּהְיְה הַנְּשָׁמָה קַיֶּימֶת בַּגּוּף לְעוֹלָמִים, ודָא הוּא דִכְתִיב הַנִּשְׁאָר בְּצִּיּוֹן והַנּוֹתָר בִּיְרוּשָׁלַם קָדוֹשׁ יֵאָמֵר לוֹ וגו'.","אָמַר רַבִּי חִזְקִיָּה מֵהָכָא (מקרא הוא) הוּא קָדוֹשׁ יְרוּשָׁלַם קָדוֹשׁ הַנּוֹתָר בָּהּ קָדוֹשׁ. הוּא קָדוֹשׁ, דִּכְתִיב, (ישעיהו ו׳:ג׳) קָדוֹשׁ יְיָ צְּבָאוֹת. וּכְתִיב, (הושע י״א:ט׳) בְּקִרְבֵּךְ קָדוֹשׁ. יְרוּשָׁלַםִ קָדוֹשׁ, דִּכְתִיב, (קהלת ח׳:י׳) וּמִמָּקוֹם קָדוֹשׁ יְהַלֵּכוּ. הַנּוֹתָר בָּהּ קָדוֹשׁ, דִּכְתִיב, (ישעיהו ד׳:ג׳) והָיָה הַנִּשְׁאָר בְּצִּיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַםִ קָדוֹשׁ יֵאָמֵר לוֹ. מַה קָּדוֹשׁ הָרִאשׁוֹן קַיָּים אַף הַשְּׁאָר קָדוֹשׁ קָדוֹשׁ קַיָּים.","אָמַר רַבִּי יצְּחָק מַאי דִכְתִיב, (זכריה ח׳:ד׳) עוֹד יֵשְׁבוּ זְקֵנִים וּזְקֵנוֹת בִּרְחוֹבוֹת יְרוּשָׁלַם וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרוֹב ימִים. מַאי טִיבוּתָא דָא (כדי) לְמֵיזַל כְּדֵין דִּכְתִיב וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ. אֶלָּא אָמַר רַבִּי יִצְּחָק (קלה א) עֲתִידִים הַצַּדִּיקִים לֶעָתִיד לָבֹא לְהַחֲיוֹת מֵתִים כֶּאֱלִישָׁע הַנָּבִיא, דִּכְתִיב, (מלכים ב ד׳:כ״ט) וְקַח מִשְׁעַנְתִּי בְּיָדְךָ וָלֵךְ. וּכְתִיב וְשַׂמְתָּ מִשְׁעַנְתִּי עַל פְּנֵי הַנַּעַר. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא דָּבָר שֶׁעֲתִידִים לַעֲשׂוֹת הַצַּדִּיקִים לֶעָתִיד לָבֹא אַתָּה רוֹצֶּה עַכְשָׁיו לַעֲשׂוֹת, מַה כְּתִיב וַיָּשֶׂם אֶת הַמִּשְׁעֶנֶת עַל פְּנֵי הַנַּעַר ואֵין קוֹל וְאֵין עוֹנֶה וְאֵין קָשֶׁב. אֲבָל הַצַּדִּיקִים לֶעָתִיד לָבֹא עָלָה בְּיָדָם הַבְטָחָה זוֹ, דִּכְתִיב, (זכריה י) וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ כְּדֵי לְהַחֲיוֹת בּוֹ אֶת הַמֵּתִים (מה מתים אותם) מֵהַגֵּרִים שֶׁנִּתְגַיְּירוּ מֵאוּמּוֹת הָעוֹלָם דִּכְתִיב בְּהוּ (ישעיהו ס״ה:כ׳) כִּי הַנַּעַר בֶּן מֵאָה שָׁנָה יָמוּת וְהַחוֹטֵא בֶּן מֵאָה שָׁנָה יְקוּלָל. אָמַר רַבִּי יִצְּחָק סוֹפֵיהּ דִּקְרָא מוֹכִיחַ דִּכְתִיב מֵרוֹב יָמִים.","דָּבָר אַחֵר וַתֹּאמֶר שָׂרָה צְּחוֹק עָשָׂה לִי אֱלהִים. כְּתִיב, (ישעיהו ס״ו:י׳) שִׂמְחוּ אֶת יְרוּשָׁלַםִ וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ. אָמַר רַבִּי יְהוּדָה לא הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, כְּאוֹתָהּ שִׂמְחָה שֶׁעָתִיד לִשְׂמוֹחַ עִם הַצַּדִּיקִים לֶעָתִיד לָבוֹא. וְכָל אֶחָד וְאֶחָד מַרְאֶה בָּאֶצְּבַּע ואוֹמֵר (ישעיהו כ״ה:ט׳) הִנֵּה אֱלהֵינוּ זֶה קִוִּינוּ לוֹ וְיוֹשִׁיעֵנוּ זְה יְיָ קִוִּינוּ לוֹ נָגִילָה ונִשְׂמְחָה בִּישׁוּעָתוֹ. וּכְתִיב, (ישעיהו י״ב:ה׳) זַמְּרוּ יְיָ כִּי גֵאוּת עָשָׂה מוּדַעַת זאת בְּכָל הָאָרֶץ.","רַבִּי יוֹחָנָן אָמַר לֹא חָזִינָן מַאן דְּפָּרִישׁ הַאי מִלָּה כְּדָוִד מַלְכָּא דְּאָמַר (תהילים ק״ד:כ״ט) תַּסְתִּיר פָּנְיךָ יִבָּהֵלוּן וגו'. מִכָּאן שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה רָעָה לְשׁוּם אָדָם, אֶלָּא כְּשֶׁאֵינוֹ מַשְׁגִּיחַ בּוֹ הוּא כָּלֶה מֵאֵלָיו, דִּכְתִיב תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן תּוֹסֶף רוּחָם יִגְוָעוּן וְגו'. וְאַחַר כָּךְ (תהילים ק״ד:כ״ט) תְּשַׁלַּח רוּחֲךָ יִבְּרֵאוּן וגו'. וְאַחַר כָּךְ (תהילים ק״ד:ל״א) יְהִי כְבוֹד יְיָ לְעוֹלָם יִשְׂמַח יְיָ בְּמַעֲשָׂיו. וְאֲזַי הַשְּׂחוֹק בָּעוֹלָם דִּכְתִיב, (תהילים קכ״ו:ב׳) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה. הֲדָא הוּא דִכְתִיב ותֹּאמֶר שָׂרָה צְּחֹק עָשָׂה לִי אֱלהִים לִשְׂמוֹחַ בִּישׁוּעָתוֹ.","רַבִּי חִיָּיא אָמַר תָּא חֲזֵי, עַד שֶׁהַגּוּף עוֹמֵד בָּעוֹלָם הַזְּה הוּא חָסֵר מִן הַתַּשְׁלוּם, לְאַחַר שֶׁהוּא צַּדִּיק וְהוֹלֵךְ בְּדַרְכֵי יוֹשֶׁר וּמֵת בְּיוֹשְׁרוֹ, נִקְרָא שָׂרָה בְּתַשְׁלוּמוֹ, הִגִּיעַ לִתְחִיַּית הַמֵּתִים הוּא שָׂרָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁאַחֵר הוּא שֶׁהֶחֱיָה קוּדְשָׁא בְּרִיךְ הוּא. לְאַחַר שֶׁהוּא חַי, וְשָׂמֵחַ עִם הַשְּׁכִינָה וּמַעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא הַיָּגוֹן מִן הָעוֹלָם דִּכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוֶת לָנֶצַּח וּמָחָה יְיָ אֱלהִים דִּמְעָה מֵעַל כָּל פָּנִים וגו'. אֲזַי נִקְרָא יִצְּחָק, בִּשְׁבִיל הַצְּחוֹק וְהַשִּׂמְחָה שֶׁיִּהְיֶה לַצַּדִּיקִים לֶעָתִיד לָבֹא."],[[0,"","מכאן עד אות ת\"ד אין צריך ביאור"]],[[0,"","וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. רַבִּי יוֹחָנָן פָּתַח בְּפָסוּק זֶה, (שיר ז) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן מֶלֶךְ אָסוּר בָּרְהָטִים. עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שַׁלִּיטִים לְמַעְלָה וְשַׁלִּיטִים לַטָּה. כְּשֶׁנּוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא מַעֲלָה לְשָׂרִים שֶׁל מַעְלָה, נוֹטְלִים מַעֲלָה הַמְּלָכִים שֶׁל מַטָּה. נָתַן מַעֲלָה לְשָׂרוֹ שֶׁל בָּבֶל - נָטַל מַעֲלָה נְבוּכַדְנֶצַּר הָרָשָׁע, שֶׁכָּתוּב בּוֹ (דניאל ב) אַתָּה הוּא רֹאשׁ הַזָּהָב. וְהָיוּ כָּל הָעוֹלָם מְשֻׁעְבָּדִים תַּחַת יָדוֹ וּבְנוֹ וּבֶן בְּנוֹ. זֶהוּ שֶׁכָּתוּב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. זֶהוּ נְבוּכַדְנֶצַּר. זֶהוּ שֶׁכָּתוּב (שם ד) תַּחְתָּיו תִּצְלַל חַיַּת הַשָּׂדֶה. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זֶהוּ בֶּלְשַׁצַּר שֶׁאָמַר (שם ה) יִלְבַּשׁ אַרְגָּמָן. מֶלֶךְ אָסוּר בָּרְהָטִים - זֶהוּ אֱוִיל מְרֹדַךְ שֶׁהָיָה אָסוּר עַד שֶׁמֵּת אָבִיו נְבוּכַדְנֶצַּר וּמָלַךְ תַּחְתָּיו."],[1,"","אָמַר רַבִּי יְהוּדָה, לָמָּה בָּא טַעַם זֶה בְּשִׁיר הַשִּׁירִים? אֶלָּא, אָמַר רַבִּי יְהוּדָה, שִׁבְעָה דְבָרִים נִבְרְאוּ קֹדֶם שֶׁנִּבְרָא הָעוֹלָם, וְאֵלּוּ הֵן וְכוּ', כִּסֵּא הַכָּבוֹד - שֶׁנֶּאֱמַר (תהלים צג) נָכוֹן כִּסְאֲךְ מֵאָז מֵעוֹלָם אָתָּה, וְכָתוּב (ירמיה יז) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן. שֶׁהוּא הָיָה רֹאשׁ הַנִּקְדַּם לַכֹּל, וְנָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַנְּשָׁמָה הַטְּהוֹרָה מִכִּסֵּא הַכָּבוֹד לִהְיוֹת מְאִירָה לַגּוּף. זֶהוּ שֶׁכָּתוּב רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. זֶהוּ כִּסֵּא הַכָּבוֹד שֶׁהוּא רֹאשׁ עַל הַכֹּל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זוֹ הִיא הַנְּשָׁמָה הַנִּטֶּלֶת מִמֶּנּוּ. מֶלֶךְ אָסוּר בָּרְהָטִים - זֶהוּ הַגּוּף שֶׁהוּא אָסוּר בַּקֶּבֶר וְכָלֶה בֶּעָפָר וְלֹא נִשְׁאָר מִמֶּנּוּ אֶלָּא כִּמְלֹא תַרְוָד רֶקֶב, וּמִמֶּנּוּ יִבָּנֶה כָּל הַגּוּף. וּכְשֶׁפּוֹקֵד הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַגּוּף, הוּא אוֹמֵר לָאָרֶץ שֶׁתַּפְלִיט אוֹתוֹ לַחוּץ, שֶׁכָּתוּב (ישעיה כו) וָאָרֶץ רְפָאִים תַּפִּיל."],[2,"","אָמַר רַבִּי יוֹחָנָן, הַמֵּתִים שֶׁבָּאָרֶץ הֵם חַיִּים תְּחִלָּה, זֶהוּ שֶׁכָּתוּב (שם) יִחְיוּ מֵתֶיךְ. נְבֵלָתִי יְקוּמוּן - אֵלּוּ שֶׁבְּחוּצָה לָאָרֶץ. הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר - אֵלּוּ הַמֵּתִים שֶׁבַּמִּדְבָּר. שֶׁאָמַר רַבִּי יוֹחָנָן, לָמָּה מֵת מֹשֶׁה בְּחוּצָה לָאָרֶץ? לְהַרְאוֹת לְכָל בָּאֵי עוֹלָם, כְּשֵׁם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת לְמֹשֶׁה, כָּךְ עָתִיד לְהַחֲיוֹת לְדוֹרוֹ, (למה)? שֶׁהֵם קִבְּלוּ הַתּוֹרָה. (שאמר רבי יוחנן) וַעֲלֵיהֶם נֶאֱמַר (ירמיה ב) זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר בְּאֶרֶץ לֹא זְרוּעָה."],[3,"","דָּבָר אַחֵר הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר - אֵלּוּ הֵם הָאָבוֹת. וְהַמֵּתִים בְּחוּצָה לָאָרֶץ יִבָּנֶה גוּפָם וּמִתְגַּלְגְּלִים תַּחַת הָאָרֶץ עַד אֶרֶץ יִשְׂרָאֵל, וְשָׁם יְקַבְּלוּ נִשְׁמָתָם, וְלֹא בְּחוּצָה לָאָרֶץ. זֶהוּ שֶׁכָּתוּב (יחזקאל לז) לָכֵן הִנָּבֵא וְאָמַרְתָּ אֲלֵיהֶם (וגו'), הִנֵּה אֲנִי פֹתֵחַ אֶת קִבְרוֹתֵיכֶם וְהַעֲלֵיתִי אֶתְכֶם מִקִּבְרוֹתֵיכֶם עַמִּי וְהֵבֵאתִי אֶתְכֶם אֶל אַדְמַת יִשְׂרָאֵל. מַה כָּתוּב אַחֲרָיו? וְנָתַתִּי רוּחִי בָכֶם וִחְיִיתֶם."],[4,"","רַבִּי פִּנְחָס אָמַר, הַנְּשָׁמָה נִטְּלָה מִכִּסֵּא הַכָּבוֹד שֶׁהוּא הָרֹאשׁ, כְּמוֹ שֶׁנֶּאֱמַר (שיר ז) רֹאשֵׁךְ עָלַיִךְ כַּכַּרְמֶל. וְדַלַּת רֹאשֵׁךְ כָּאַרְגָּמָן - זוֹ הִיא הַנְּשָׁמָה שֶׁהִיא דַּלַּת הָרֹאשׁ. מֶלֶךְ אָסוּר בָּרְהָטִים - הוּא הַגּוּף שֶׁהוּא אָסוּר בַּקְּבָרִים. זֶהוּ הַגּוּף, וְזֶהוּ שָׂרָה, וְזֶהוּ מֶלֶךְ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא פּוֹקְדָהּ לַמּוֹעֵד אֲשֶׁר דִּבֵּר אֵלָיו. זֶהוּ שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. פּוֹקֵד אֶת הַגּוּף לַזְּמַן הַיָּדוּעַ שֶׁבּוֹ יִפְקֹד הַצַּדִּיקִים."],[5,"","אָמַר רַבִּי פִּנְחָס, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְיַפּוֹת לְגוּף הַצַּדִּיקִים לֶעָתִיד לָבֹא כַּיֹּפִי שֶׁל אָדָם הָרִאשׁוֹן כְּשֶׁנִּכְנַס לְגַן עֵדֶן, שֶׁנֶּאֱמַר (ישעיה נח) וְנָחֲךְ ה' תָּמִיד וְגוֹ' וְהָיִיתָ כְּגַן רָוֶה. אָמַר רַבִּי לֵוִי, הַנְּשָׁמָה בְּעוֹדָהּ בְּמַעֲלָתָהּ, נִזּוֹנֵית בְּאוֹר שֶׁל מַעְלָה וּמִתְלַבֶּשֶׁת בּוֹ, וּכְשֶׁתִּכָּנֵס (ונשתרש) לַגּוּף לֶעָתִיד לָבא - בְּאוֹתוֹ הָאוֹר מַמָּשׁ תִּכָּנֵס, וַאֲזַי הַגּוּף יָאִיר כְּזֹהַר הָרָקִיעַ. זֶהוּ שֶׁכָּתוּב (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹהַר הָרָקִיעַ. וְיַשִּׂיגוּ בְּנֵי אָדָם דֵּעָה שְׁלֵמָה, שֶׁנֶּאֱמַר (ישעיה יא) כִּי מָלְאָה הָאָרֶץ דֵּעָה אֶת ה'. מִנַּיִן לָנוּ זֶה? מִמַּה שֶּׁכָּתוּב וְנָחֲךְ ה' תָּמִיד וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. זֶה אוֹר שֶׁל מַעְלָה. וְעַצְמֹתֶיךָ יַחֲלִיץ - זֶה פְּקִידַת הַגּוּף. וְהָיִיתָ כְּגַן רָוֶה וּכְמוֹצָא מַיִם אֲשֶׁר לֹא יְכַזְּבוּ מֵימָיו - זֶהוּ דַּעַת הַבּוֹרֵא יִתְבָּרַךְ. וַאֲזַי יֵדְעוּ הַבְּרִיּוֹת שֶׁהַנְּשָׁמָה הַנִּכְנֶסֶת בָּהֶם, שֶׁהִיא נִשְׁמַת הַחַיִּים, נִשְׁמַת הַתַּעֲנוּגִים, שֶׁהִיא קִבְּלָה הַתַּעֲנוּגִים מִלְמַעְלָה וּמְעַדֶּנֶת לַגּוּף, וְהַכֹּל תְּמֵהִים בָּהּ וְאוֹמְרִים (שיר ז) מַה יָּפִית וּמַה נָּעַמְתְּ אַהֲבָה בַּתַּעֲנוּגִים. זוֹ הִיא הַנְּשָׁמָה לֶעָתִיד לָבֹא."],[6,"","אָמַר רַבִּי יְהוּדָה, בֹּא רְאֵה שֶׁכָּךְ הוּא, שֶׁכָּתוּב (שם) מֶלֶךְ אָסוּר בָּרְהָטִים, וְכָתוּב אַחֲרָיו מַה יָּפִית וּמַה נָּעַמְתְּ. וְאָמַר רַבִּי יְהוּדָה, בְּאוֹתוֹ זְמַן עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְשַׂמֵּחַ עוֹלָמוֹ וְלִשְׂמֹחַ בִּבְרִיּוֹתָיו, שֶׁנֶּאֱמַר (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו. וַאֲזַי יִהְיֶה שְׂחוֹק בָּעוֹלָם מַה שֶּׁאֵין כֵּן עַכְשָׁו, שֶׁכָּתוּב (שם קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וְגוֹ'. זֶהוּ שֶׁכָּתוּב וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, שֶׁאֲזַי עֲתִידִים בְּנֵי אָדָם לוֹמַר שִׁירָה, שֶׁהוּא עֵת שְׂחוֹק. רַבִּי אַבָּא אָמַר, הַיּוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא עִם בְּרִיּוֹתָיו, לֹא הָיְתָה שִׂמְחָה כְּמוֹתָהּ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וְהַצַּדִּיקִים הַנִּשְׁאָרִים בִּירוּשָׁלַיִם לֹא יָשׁוּבוּ עוֹד לַעֲפָרָם, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ. הַנּוֹתָר בְּצִיּוֹן וּבִירוּשָׁלַיִם דַּוְקָא."],[7,"","אָמַר רַבִּי אָחָא, אִם כֵּן מְעַטִּים הֵם. אֶלָּא כָּל אוֹתָם שֶׁנִּשְׁאֲרוּ בְּאֶרֶץ יִשְׂרָאֵל הַקְּדוֹשָׁה דִּינָם כִּירוּשָׁלַיִם וּכְצִיּוֹן לְכָל דָּבָר. מְלַמֵּד שֶׁכָּל אֶרֶץ יִשְׂרָאֵל בִּכְלַל יְרוּשָׁלַיִם הִיא, מִמַּשְׁמָע שֶׁכָּתוּב (ויקרא יט) וְכִי תָבאוּ אֶל הָאָרֶץ. הַכֹּל בַּכְּלָל. רַבִּי יְהוּדָה בְּרַבִּי אֶלְעָזָר שָׁאַל לְרַבִּי חִזְקִיָּה. אָמַר לוֹ, מֵתִים שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹתָם, לָמָּה לֹא נָתַן נִשְׁמָתָם בְּמָקוֹם שֶׁנִּקְבְּרוּ שָׁם, וְיָבאוּ לְהֵחָיוֹת בְּאֶרֶץ יִשְׂרָאֵל? אָמַר לוֹ, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְנוֹת יְרוּשָׁלַיִם, וְשֶׁלֹּא תֵהָרֵס לְעוֹלָמִים. שֶׁאָמַר רַבִּי יִרְמְיָה, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ עוֹלָמוֹ וְלִבְנוֹת יְרוּשָׁלַיִם וּלְהוֹרִידָהּ בְּנוּיָה מִלְמַעְלָה (בנין) כְּדֵי שֶׁלֹּא יֵהָרֵס, וְנִשְׁבַּע שֶׁלֹּא תִגְלֶה עוֹד כְּנֶסֶת יִשְׂרָאֵל, וְנִשְׁבַּע שֶׁלֹּא יֵהָרֵס בִּנְיַן יְרוּשָׁלַיִם, שֶׁנֶּאֱמַר (ישעיה סב) לֹא יֵאָמֵר לָךְ עוֹד עֲזוּבָה וּלְאַרְצֵךְ לֹא יֵאָמֵר עוֹד שְׁמָמָה."],[8,"","וּבְכָל מָקוֹם שֶׁאַתָּה מוֹצֵא לֹא לֹא - הִיא שְׁבוּעָה. זֶהוּ שֶׁכָּתוּב (בראשית ט) וְלֹא יִכָּרֵת כָּל בָּשָׂר עוֹד מִמֵּי הַמַּבּוּל וְלֹא יִהְיֶה עוֹד מַבּוּל וְגוֹ', וְכָתוּב (ישעיה נד) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבֹר מֵי נֹחַ. מִכָּאן שֶׁלֹּא לֹא - שְׁבוּעָה. וּמִן לָאו אַתָּה שׁוֹמֵעַ הֵן. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְקַיֵּם עוֹלָמוֹ קִיּוּם שֶׁלֹּא תִגְלֶה כְּנֶסֶת יִשְׂרָאֵל וְלֹא יֵהָרֵס בִּנְיַן בֵּית הַמִּקְדָּשׁ, לְפִיכָךְ אֵין מְקַבְּלִים נִשְׁמָתָם אֶלָּא בְּמָקוֹם קַיָּם לְעוֹלָמִים, כְּדֵי שֶׁתִּהְיֶה הַנְּשָׁמָה קַיֶּמֶת בַּגּוּף לְעוֹלָמִים. וְזֶה הוּא שֶׁכָּתוּב הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ וְגוֹ'."],[9,"","אָמַר רַבִּי חִזְקִיָּה, מִכָּאן (מקרא הוא) הוּא קָדוֹשׁ, יְרוּשָׁלַיִם קָדוֹשׁ, הַנּוֹתָר בָּהּ קָדוֹשׁ. הוּא קָדוֹשׁ - שֶׁכָּתוּב (ישעיה ו) קָדוֹשׁ ה' צְבָאוֹת, וְכָתוּב (הושע יא) בְּקִרְבְּךְ קָדוֹשׁ. יְרוּשָׁלַיִם קָדוֹשׁ - שֶׁכָּתוּב (קהלת ח) וּמִמְּקוֹם קָדוֹשׁ יְהַלֵּכוּ. הַנּוֹתָר בָּהּ קָדוֹשׁ - שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלַיִם קָדוֹשׁ יֵאָמֶר לוֹ. מַה קָּדוֹשׁ הָרִאשׁוֹן קַיָּם - אַף הַשְּׁאָר קָדוֹשׁ קָדוֹשׁ קַיָּם."],[10,"","אָמַר רַבִּי יִצְחָק, מַה זֶּה שֶׁכָּתוּב (זכריה ח) עֹד יֵשְׁבוּ זְקֵנִים וּזְקֵנוֹת בִּרְחֹבוֹת יְרוּשָׁלם וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ מֵרֹב יָמִים? מַה טּוֹבָה הִיא זוֹ (כדי) לָלֶכֶת אָז שֶׁכָּתוּב וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ? אֶלָּא, אָמַר רַבִּי יִצְחָק, עֲתִידִים הַצַּדִּיקִים לֶעָתִיד לָבֹא לְהַחֲיוֹת מֵתִים כֶּאֱלִישָׁע הַנָּבִיא, שֶׁכָּתוּב (מלכים ב ד) וְקַח מִשְׁעַנְתִּי בְיָדְךְ וָלֵךְ, וְכָתוּב וְשַׂמְתָּ מִשְׁעַנְתִּי עַל פְּנֵי הַנָּעַר. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: דָּבָר שֶׁעֲתִידִים לַעֲשׂוֹת הַצַּדִּיקִים לֶעָתִיד לָבֹא אַתָּה רוֹצֶה לַעֲשׂוֹת עַכְשָׁו לַעֲשׂוֹת? מַה כָּתוּב? וַיָּשֶׂם אֶת הַמִּשְׁעֶנֶת עַל פְּנֵי הַנַּעַר וְאֵין קוֹל וְאֵין עוֹנֶה וְאֵין קָשֶׁב. אֲבָל הַצַּדִּיקִים לֶעָתִיד לָבֹא עָלָה בְיָדָם הַבְטָחָה זוֹ, שֶׁכָּתוּב (זכריה ח) וְאִישׁ מִשְׁעַנְתּוֹ בְּיָדוֹ, כְּדֵי לְהַחֲיוֹת בּוֹ אֶת הַמֵּתִים. (מי הם המתים)? אוֹתָם מֵהַגֵּרִים שֶׁנִּתְגַּיְּרוּ מֵאֻמּוֹת הָעוֹלָם, שֶׁכָּתוּב בָּהֶם (ישעיה סה) כִּי הַנַּעַר בֶּן מֵאָה שָׁנָה יָמוּת וְהַחוֹטֶא בֶּן מֵאָה שָׁנָה יְקֻלָּל. אָמַר רַבִּי יִצְחָק, סוֹף הַפָּסוּק מוֹכִיח, שֶׁכָּתוּב מֵרֹב יָמִים."],[11,"","דָּבָר אַחֵר וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, כָּתוּב (ישעיה סו) שִׂמְחוּ אֶת יְרוּשָׁלם וְגִילוּ בָהּ כָּל אֹהֲבֶיהָ שִׂישׂוּ אִתָּהּ מָשׂוֹשׂ כָּל הַמִּתְאַבְּלִים עָלֶיהָ. אָמַר רַבִּי יְהוּדָה, לֹא הָיְתָה שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם כְּאוֹתָהּ שִׂמְחָה שֶׁעָתִיד לִשְׂמֹחַ עִם הַצַּדִּיקִים לֶעָתִיד לָבא, וְכָל אֶחָד מַרְאֶה בָּאֶצְבַּע וְאוֹמֵר, (שם כה) הִנֵּה אֱלֹהֵינוּ זֶה קִוִּינוּ לוֹ וְיוֹשִׁיעֵנוּ זֶה ה' קִוִּינוּ לוֹ נָגִילָה וְנִשְׂמְחָה בִּישׁוּעָתוֹ, וְכָתוּב (שם יב) זַמְּרוּ ה' כִּי גֵאוּת עָשָׂה מוּדַעַת זאת בְּכָל הָאָרֶץ."],[12,"","רַבִּי יוֹחָנָן אָמַר, לֹא רָאִינוּ מִי שֶׁפֵּרַשׁ אֶת הַדָּבָר הַזֶּה כְּדָוִד הַמֶּלֶךְ שֶׁאָמַר (תהלים קד) תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן וְגוֹ'. מִכָּאן שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה רָעָה לְשׁוּם אָדָם, אֶלָּא כְּשֶׁאֵינוֹ מַשְׁגִּיחַ בּוֹ - הוּא כָּלֶה מֵאֵלָיו, שֶׁכָּתוּב תַּסְתִּיר פָּנֶיךְ יִבָּהֵלוּן תֹּסֵף רוּחָם יִגְוָעוּן וְגוֹ', וְאַחַר כָּךְ (שם) תְּשַׁלַּח רוּחֲךְ יִבָּרֵאוּן וְגוֹ', וְאַחַר כָּךְ (שם) יְהִי כְבוֹד ה' לְעוֹלָם יִשְׂמַח ה' בְּמַעֲשָׂיו. וַאֲזַי הַשְּׂחוֹק בָּעוֹלָם, שֶׁכָּתוּב (שם קכו) אָז יִמָּלֵא שְׂחוֹק פִּינוּ וּלְשׁוֹנֵנוּ רִנָּה. זֶהוּ שֶׁכָּתוּב וַתֹּאמֶר שָׂרָה צְחֹק עָשָׂה לִי אֱלֹהִים, לִשְׂמֹחַ בִּישׁוּעָתוֹ."],[13,"","רַבִּי חִיָּיא אָמַר, בֹּא רְאֵה, עַד שֶׁהַגּוּף עוֹמֵד בָּעוֹלָם הַזֶּה, הוּא חָסֵר מִן הַתַּשְׁלוּם. לְאַחַר שֶׁהוּא צַדִּיק וְהוֹלֵךְ בְּדַרְכֵי יֹשֶׁר וּמֵת בְּיָשְׁרוֹ, נִקְרָא שָׂרָה בְּתַשְׁלוּמוֹ. הִגִּיעַ לִתְחִיַּת הַמֵּתִים, הוּא שָׂרָה, כְּדֵי שֶׁלֹּא יֹאמְרוּ שֶׁאַחֵר הוּא שֶׁהֶחֱיָה הַקָּדוֹשׁ בָּרוּךְ הוּא. לְאַחַר שֶׁהוּא חַי וְשָׂמֵחַ עִם הַשְּׁכִינָה וּמַעֲבִיר הַקָּדוֹשׁ בָּרוּךְ הוּא הַיָּגוֹן מִן הָעוֹלָם, שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ', אֲזַי נִקְרָא יִצְחָק בִּשְׁבִיל הַצְּחוֹק וְהַשִּׂמְחָה שֶׁיִּהְיֶה לַצַּדִּיקִים לֶעָתִיד לָבֹא."]]],[["רַבִּי יְהוּדָה אֲתָא לְהַהוּא אֲתַר דִּכְפַר חָנָן, שָׁדְרוּ לֵיהּ תִּקְרוֹבְתָּא כָּל בְּנֵי מָאתָא, עָאל לְגַבֵּיהּ רַבִּי אַבָּא, אָמַר לֵיהּ אֵימָתַי לֵיזִיל מַר, אָמַר לֵיהּ אֶפְרַע מַה דְּיָהֲבוּ לִי בְּנִי מָאתָא וְאֵיזִיל, אָמַר לֵיהּ לָא לֵיחוּשׁ מַר לְהַאי תִּקְרוֹבְתָּא לְאוֹרַיְיתָא הוּא דְּעֲבְדוּ, וְלָא יְקַבְּלוּ מִנָּךְ כְּלוּם, אָמַר לֵיהּ וְלָא מְקַבְּלֵי מִלֵּי דְאוֹרַיְיתָא, אָמַר אִין. אָתוּ כָּל בְּנִי מָאתָא. אָמַר לֵיהּ רַבִּי יְהוּדָה כֻּלְּהוֹן מָארֵי מְתִיבְתָּא, אָמַר לֵיהּ, ואִי אִית מַאן דְּלָא יָאוֹת לְמֵיתַב הָכָא לֵיקוּם וְלֵיזִיל. קָם רַבִּי אַבָּא וְאַבְדִּיל מִנַּיְיהוּ עֲשָׂרָה דִי יְקַבְּלוּן מִנִּיהּ, אָמַר לְהוּ יְתִּיבוּ בַּהֲדֵי גַבְרָא רַבָּא דְּנָא, ואֲנָא ואִנּוּן נְקַבֵּל לְמָחָר וְנְתִיב עִמֵּיהּ. אָזְלוּ. ואִנּוּן עֲשָׂרָה דְּאִשְׁתָּאֲרוּ עִמֵּיהּ יְתִיבוּ (אנון עשרה) וְלָא אָמַר כְּלוּם, אָמְרוּ לֵיהּ אִי רְעוּתֵיהּ דְּמַר נְקַבֵּל אַפֵּי שְׁכִינְתָּא. אָמַר לְהוּ והָא רַבִּי אַבָּא לֵית הָכָא, שָׁדְרוּ בַּהֲדֵיהּ וְאָתָא.","פָּתַח וְאָמַר וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. מַאי שִׁנּוּיָא הֲוָה הָכָא, הֲוָה לֵיהּ לְמֵימַר וַיְיָ זָכָר אֶת שָׂרָה כְּמָה דְּאָמַר (בראשית ל׳:כ״ב) וַיִּזְכֹּר אֱלהִים אֶת רָחֵל. דְּאֵין פְּקִידָה אֶלָּא עַל מַה דְּהֲוָה בְּקַדְמִיתָא. אֶלָּא בְּקַדְמִיתָא הֲוָה, דִּכְתִיב שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה, וְעַל אוֹתוֹ עִנְיָן נֶאֱמַר שֶׁפָּקַד עַכְשָׁיו, מַשְׁמַע דִּכְתִיב כַּאֲשֶׁר אָמָר, דְּאִלְמָלֵא לֹא נְאֱמַר כַּאֲשֶׁר אָמָר לֵימָא זְכִירָה, אֲבָל פָּקַד הַהִיא מִלָּה דְּאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךָ.","לְבָתַר אָמַר הָכִי, הַאי צַּדִּיק דְּזָכֵי לְמֵיסַק לְהַהוּא יְקָר עִלָּאָה, דִּיוּקְנֵיהּ מִתְפַּתַּח בְּכָרְסֵי יְקרִיהּ, וכֵן לְכָל צַּדִּיק וְצַּדִּיק דִּיוּקְנֵיהּ לְעֵילָא כַּד הֲוָה לְתַתָּא לְאַבְטָחָא לְהַהִיא נִשְׁמָתָא קַדִּישָׁא.","וְהַיְינוּ דְּאָמַר רַבִּי יוֹחָנָן, מַאי דִכְתִיב, (חבקוק ג׳:י״א) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה, דְּזָהֲרָן גּוּפָא וְנִשְׁמָתָא דְּקָיְימִין בְּאִדְרָא קַדִּישָׁא עִלָּאָה דִלְעֵילָא כִּדִיוּקְנָא דְּהֲוָה קָאִים בְּאַרְעָא, והַהִיא דִיוּקְנָא (ס\"א מזונה) מִמְּזוֹנָהּ הֲנָאַת נִשְׁמָתָא, והַהִיא עֲתִידָה לְאִתְלַבַּשׁ בְּהַאי גַרְמָא דְּאִשְׁתָּאַר בְּאַרְעָא, וְאַרְעָא מִתְעֲבַר מִנִּיהּ וטָפַל טִינֵיהּ לְבָרָא, וְדָא הוּא דְּאִתְקְרֵי קְדוּשָׁה."],[[2,"לבתר אמר הכי וכו':","אחרי כן אמר כך. צדיק הזה, שזכה לעלות לאותו כבוד העליון, צורתו נחקקה בכסא הכבוד. וכן כל צדיק וצדיק נמצאת צורתו למעלה, בגן עדן, כמו שהיתה למטה, בעולם הזה. כדי להבטיח את הנשמה הקדושה, בתחיית הגוף שבעולם הזה."],[3,"והיינו דאמר וכו':","והיינו דא\"ר יוחנן, מה שכתוב, שמש ירח עמד זבולה, הוא ללמדינו שהגוף והנשמה עומדים בחדר הקדוש העליון של מעלה ומאירים באותה הצורה שהיו עומדים בארץ, בעוה\"ז ומזונה של צורה ההיא, של עולם הזה, היא מהנאת הנשמה. והיא עתידה להתלבש בעצם הזה, הנקרא לוז, הנשאר קיים בארץ עד לתחית המתים, שהארץ מתעברת ממנו ופלטת פסולת שלו החוצה. וזו היא, דהיינו הצורה הנ\"ל, שנקראת קדושה."]],[[0,"","רַבִּי יְהוּדָה בָּא לְאוֹתוֹ מָקוֹם שֶׁל כְּפַר חָנָן. שָׁלְחוּ לוֹ מִנְחָה כָּל בְּנֵי הָעִיר. נִכְנַס לְפָנָיו רַבִּי אַבָּא, אָמַר לוֹ, מָתַי הוֹלֵךְ מַר? אָמַר לוֹ, אֶפְרַע מַה שֶּׁנָּתְנוּ לִי בְּנֵי הָעִיר וְאֵלֵךְ. אָמַר לוֹ, אַל יַחְשֹׁשׁ מַר לַמִּנְחָה הַ את. לַתּוֹרָה הֵם עָשׂוּ אֶת זֶה, וְלֹא יְקַבְּלוּ מִמְּךְ כְּלוּם. אָמַר לוֹ, וְלֹא יְקַבְּלוּ דִּבְרֵי תוֹרָה? אָמַר כֵּן. בָּאוּ כָּל בְּנֵי הָעִיר. אָמַר לוֹ רַבִּי יְהוּדָה, כֻּלָּם רָאשֵׁי יְשִׁיבוֹת. אָמַר לוֹ, וְאִם יֵשׁ מִי שֶׁלֹּא נָאֶה לוֹ לָשֶׁבֶת כָּאן - שֶׁיָּקוּם וְיֵלֵךְ. קָם רַבִּי אַבָּא וְהִבְדִּיל מֵהֶם עֲשָׂרָה שֶׁיְּקַבְּלוּ מִמֶּנּוּ. אָמַר לָהֶם, שְׁבוּ עִם הָאִישׁ הַגָּדוֹל הַזֶּה, וַאֲנִי וְהֵם נְקַבֵּל לְמָחָר וְנֵשֵׁב עִמּוֹ. הָלְכוּ. וְאוֹתָם עֲשָׂרָה שֶׁיָּשְׁבוּ עִמּוֹ יָשְׁבוּ (אותם עשרה) וְלֹא אָמַר כְּלוּם. אָמְרוּ לוֹ, אִם רְצוֹנוֹ שֶׁל מַר, נְקַבֵּל פְּנֵי שְׁכִינָה. אָמַר לָהֶם, וַהֲרֵי רַבִּי אַבָּא אֵינוֹ כָּאן. שָׁלְחוּ לוֹ וּבָא."],[1,"","פָּתַח וְאָמַר, וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמַר, מָה הַשִּׁנּוּי שֶׁהָיָה כָּאן? הָיָה לוֹ לוֹמַר, וַה' זָכַר אֶת שָׂרָה, כְּמוֹ שֶׁאָמַר (בראשית ל) וַיִּזְכֹּר אֱלֹהִים אֶת רָחֵל, שֶׁאֵין פְּקִידָה אֶלָּא עַל מַה שֶּׁהָיָה בַּתְּחִלָּה. אֶלָּא בַּהַתְחָלָה הָיָה, שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה, וְעַל אוֹתוֹ עִנְיָן נֶאֱמַר שֶׁפָּקַד עַכְשָׁו, מַשְׁמָע שֶׁכָּתוּב כַּאֲשֶׁר אָמָר. שֶׁאִלְמָלֵא לֹא נֶאֱמַר כַּאֲשֶׁר אָמָר, שֶׁיֹּאמַר זְכִירָה. אֲבָל פָּקַד - אוֹתוֹ דָּבָר שֶׁאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךְ."],[2,"","אַחַר כָּךְ אָמַר כָּךְ, צַדִּיק זֶה שֶׁזּוֹכֶה לַעֲלוֹת לְאוֹתוֹ כָּבוֹד עֶלְיוֹן, דְּמוּתוֹ נֶחְקֶקֶת בְּכִסֵּא כְבוֹדוֹ, וְכֵן לְכָל צַדִּיק וְצַדִּיק דְּמוּתוֹ לְמַעְלָה כְּמוֹ שֶׁהָיָה לְמַטָּה לְהַבְטִיחַ לְאוֹתָהּ נְשָׁמָה קְדוֹשָׁה."],[3,"","וְזְהִוּ שֶׁאָמַר רַבִּי יוֹחָנָן, מַה זֶּה שֶׁכָּתוּב (חבקוק ג) שֶׁמֶשׁ יָרֵחַ עָמַד זְבֻלָה? שֶׁזּוֹהֲרִים גּוּף וּנְשָׁמָה שֶׁעוֹמְדִים בַּגֹּרֶן הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁלְּמַעְלָה כִּדְמוּת שֶׁהָיָה עוֹמֵד בָּאָרֶץ, וְאוֹתָהּ דְּמוּת נִזּוֹנֵית הֲנָאַת הַנְּשָׁמָה, וְאוֹתָהּ הָעֲתִידָה לְהִתְלַבֵּשׁ בָּעֶצֶם הַזּוֹ שֶׁנִּשְׁאֲרָה בָּאָרֶץ, וְהָאֲדָמָה תַּעֲבֹר מִמֶּנָּה וְטוֹפֶלֶת אֶת הַזֻּהֲמָה הַחוּצָה, וְזֶהוּ שֶׁנִּקְרָא קְדֻשָּׁה."]]],[["וְכַד קָיְימָא דִּיוּקְנָא הַהִיא דִלְעֵילָא, אֲתָא בְּכָל יַרְחָא לְסָגְדָא קַמֵּי מַלְכָּא קַדִּישָׁא בְּרִיךְ הוּא דִּכְתִיב, (ישעיהו ס״ו:כ״ג) והָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ. והוּא מְבַשֵּׂר לֵיהּ וְאָמַר לַמּוֹעֵד אָשׁוּב אֵלֶיךָ, לְהַהוּא זְמַן דְּעָתִיד לְאַחֲיָא מֵיתַיָא עַד דְּאִתְפַּקְדַת לְהַהוּא זִמְנָא כְּמָה דְאִתְבַּשַּׂר הֲדָא הוּא דִכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. וְהַהוּא יוֹמָא דְּחָדֵי קוּדְשָׁא בְּרִיךְ הוּא בְּעוֹבָדוֹי הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו.","אָמַר לֵיהּ רַבִּי אַבָּא נֵימָא לָן מַר עַל פָּרָשָׁתָא לְבָתַר, אָמַר יָאוֹת לְכוֹן לְמִפְתַּח פָּרְשָׁתָא דָא. פָּתַח וְאָמַר וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְגו' וַיֹּאמֶר קַח נָא אֶת בִּנְךָ אֶת יְחִידְךָ אֲשֶׁר אָהַבְתָּ וְגו'. הָכָא אִית לְאִסְתַּכָּלָא הַאי אוּמָנָא דְּאַפִּיק כַּסְפָּא מִמְקוֹרָא דְאַרְעָא, מַאי עֲבַד. בְּקַדְמִיתָא מְעֲיִּיל לֵיהּ בְּנוּר דָּלִיק עַד דְּנָפִיק מִנִּיהּ כָּל זוּהֲמָא דְאַרְעָא, וְהָא אִשְׁתָּאֲרַת כַּסְפָּא אֲבָל לָא כַסְפָּא שְׁלֵימָתָא, לְבָתַר מַאי עָבִיד, מְעֲיִּיל לֵיהּ בְּנוּרָא כִּדְבְקַדְמִיתָא וּמַפִּיק מִנֵּיהּ סְטָיְיפֵי כְּמָא דְאַתְּ אָמֵר, (משלי כ״ה:ד׳) הָגוֹ סִיגִים מִכָּסֶף וְגו' וּכְדֵין הוּא כַּסְפָּא שְׁלֵימָתָא בְּלָא עִרְבּוּבְיָא.","כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְעֲיִּיל הַאי גוּפָא תְּחוֹת אַרְעָא עַד דְּמִתְרְקַב כּוּלֵיהּ וְנָפִיק מִנֵּיהּ כָּל זוּהֲמָא בִּישָׁא, ואִשְׁתָּאַר הַהוּא תַּרְוָוד רֶקֶב וְאִתְבְּנֵי גוּפָא מִנִּיהּ, וְעַד כְּעָן הוּא גוּפָא לָא שְׁלִים.","לְבָתַר הַהוּא יוֹמָא רַבָּא דִּכְתִיב, (זכריה י״ד:ז׳) והָיָה יוֹם אֶחָד הוּא יִוָּדַע לַיְיָ לא יוֹם וְלֹא לַיְלָה, מִתְטַמְּרָן כֻּלְּהוּ בְּעַפְרָא כִּדְבְקַדְמִיתָא מִן קֳדָם דְּחִילוּ ותַקִּיפוּ דְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (ישעיהו ב׳:י״ט) וּבָאוּ בִּמְעָרוֹת צֻּרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד יְיָ וּמֵהֲדַר גְּאוֹנוֹ וְגו'. וְנָפִיק נִשְׁמָתַיְיהוּ וּמִתְעַכֵּל הַהוּא תַּרְוָוד רֶקֶב ואִשְׁתָּאַר גּוּפָּא דְּאִתְבְּנֵי תַּמָּן (נ\"א נהורא) דִּילֵיהּ כִּנְהוֹרָא דְשִׁמְשָׁא וּכְזָהֲרָא דִּרְקִיעָא דִּכְתִיב, (דניאל י״ב:ג׳) והַמַּשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ וגו'. וּכְדֵין כַּסְפָּא שְׁלִים, גּוּפָא שְׁלֵימָא בְּלָא עִרְבּוּבְיָא אַחְרָנַיְתָא. (מכאן עד סוף מדרש הנעלם בדף קיח אינו נמצא בז\"ג רק בז\"ק)"],[[0,"וכד קיימא דיוקנא וכו':","וכאשר אותה הצורה של עוה\"ז, נמצאת למעלה, היא באה בכל ראש חדש להשתחוות לפני המלך הקדוש. שכתוב, והיה מדי חדש בחדשו וגו', והוא, המלך הקדוש, מבשר לה ואמר, למועד אשוב אליך, דהיינו לאותו הזמן שהוא עתיד להחיות המתים, עד שהיא נפקדת לזמן ההוא כמו שנתבשרה, וזהו שכתוב וה' פקד את שרה כאשר אמר. והוא היום שהקב\"ה שמח במעשיו, וז\"ש ישמח ה' במעשיו."],[1,"א\"ל ר' אבא וכו':","אמר לו ר' אבא, כששמעו מתחיל בכתוב, ישמח ה' במעשיו, יאמר לנו אדוני דבריו, על מקראות הפרשה. ולא על פסוקי תהילים. אחר זה אמר להם, ר' יהודה, יפה בשבילכם לפתוח בפרשה זו. פתח ואמר ויהי אחר הדברים האלה וגו', ויאמר קח נא את בנך וגו'. כאן יש להסתכל, והוא דומה לאומן הזה המוציא כסף ממקורות הארץ, מהו עושה. תחילה מכניס את החומר באש שורפת, עד שיוצאת ממנו כל זוהמת הארץ, ונשאר הכסף. אבל הוא אינו עוד כסף שלם. ואחרי כן מהו עושה. חוזר ומכניסו באש כבתחילה. ומוציא ממנו הסיגים, כמו שאתה אומר, הגו סיגים מכסף וגו', ואז הוא כסף שלם בלי תערובת דבר אחר."],[2,"כך דקב\"ה וכו':","כך הקב\"ה מכניס את גוף הזה תחת הארץ, עד שנרקב כולו, ויוצא ממנו כל הזוהמא הרעה. ונשאר ממנו מלא כף רקב. והגוף חוזר ונבנה ממנו. ועדיין הוא גוף בלתי שלם."],[3,"לבתר ההוא וכו':","לאחר אותו יום הגדול שכתוב, והיה יום אחד הוא יודע לה' לא יום ולא לילה וגו', שמסתתרים כולם בעפר כבתחילה. כמו בקבר מטרם התחיה, מפני הפחד והעוז של הקב\"ה, וזהו שכתוב, ובאו במערות צורים ובמחלות עפר מפני פחד ה' ומהדר גאונו וגו'. ויוצא נשמתם, ונעכל שם אותו כף רקב, ונשאר הגוף הנבנה שם כאור השמש וזהר הרקיע, שכתוב והמשכילים יזהירו כזהר הרקיע וגו'. ואז הכסף שלם, דהיינו גוף שלם בלי תערובת דבר אחר."]],[[0,"","וּכְשֶׁעוֹמֶדֶת אוֹתָהּ הַדְּמוּת הַהִיא שֶׁלְּמַעְלָה, בָּאָה בְּכָל חֹדֶשׁ לְהִשְׁתַּחֲווֹת לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ. וְהוּא מְבַשֵּׂר לוֹ וְאוֹמֵר, לַמּוֹעֵד אָשׁוּב אֵלֶיךְ. לְאוֹתוֹ זְמַן שֶׁעָתִיד לְהַחֲיוֹת מֵתִים עַד שֶׁתִּפָּקֵד לְאוֹתוֹ זְמַן כְּמוֹ שֶׁהִתְבַּשְּׂרָה. זֶהוּ שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר. וְאוֹתוֹ יוֹם שֶׁיִּשְׂמַח הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשָׂיו, זֶהוּ שֶׁכָּתוּב (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו."],[1,"","אָמַר לוֹ רַבִּי אַבָּא, יֹאמַר לָנוּ מַר עַל הַפָּרָשָׁה שֶׁאַחַר כָּךְ. אָמַר, יָפֶה לָכֶם לִפְתֹּחַ פָּרָשָׁה זוֹ. פָּתַח וְאָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְגוֹ', וַיֹּאמֶר קַח נָא אֶת בִּנְךְ אֶת יְחִידְךְ אֲשֶׁר אָהַבְתָּ וְגוֹ'. כָּאן יֵשׁ לְהִתְבּוֹנֵן, הָאֻמָּן הַזֶּה שֶׁמּוֹצִיא כֶסֶף מִמְּקוֹר הָאָרֶץ, מָה עוֹשֶׂה. בַּתְּחִלָּה? מַכְנִיס אוֹתוֹ לְאֵשׁ דּוֹלֶקֶת עַד שֶׁמּוֹצִיא מִמֶּנּוּ אֶת כָּל הַזֻּהֲמָה שֶׁל הָאָרֶץ, וַהֲרֵי נִשְׁאָר כֶּסֶף, אֲבָל לֹא כֶּסֶף שָׁלֵם. אַחַר כָּךְ מָה עוֹשֶׂה? מַכְנִיס אוֹתוֹ בָּאֵשׁ כְּבַתְּחִלָּה וּמוֹצִיא מִמֶּנּוּ סִיגִים, כְּמוֹ שֶׁנֶּאֱמַר (משלי כה) הָגוֹ סִיגִים מִכֶּסֶף וְגוֹ', וְאָז הוּא כֶּסֶף שָׁלֵם לְלֹא עִרְבּוּבְיָה."],[2,"","כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס אֶת הַגּוּף הַזֶּה תַּחַת הָאָרֶץ, עַד שֶׁכֻּלּוֹ נִרְקָב וְיָצְאָה מִמֶּנּוּ כָּל הַזֻּהֲמָה הָרָעָה, וְנִשְׁאָר אוֹתוֹ תַּרְוַד רֶקֶב וְנִבְנֶה מִמֶּנּוּ הַגּוּף, וְעַד עַכְשָׁו הוּא גוּף לֹא שָׁלֵם."],[3,"","אַחַר אוֹתוֹ יוֹם הַגָּדוֹל, שֶׁכָּתוּב (זכריה יד) וְהָיָה יוֹם אֶחָד הוּא יִוָּדַע לַה' לֹא יוֹם וְלֹא לָיְלָה, מֻסְתָּרִים כֻּלָּם בֶּעָפָר כְּמוֹ בַּתְּחִלָּה מִלִּפְנֵי פַּחַד וְהַחֹזֶק שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב (ישעיה ב) וּבָאוּ בִּמְעָרוֹת צֻרִים וּבִמְחִלּוֹת עָפָר מִפְּנֵי פַּחַד ה' וּמֵהֲדַר גְּאוֹנוֹ וְגוֹ'. וְיָצָא נִשְׁמָתָם וּמִתְעַכֵּל אוֹתוֹ תַּרְוַד רֶקֶב, וְנִשְׁאָר גּוּף שֶׁנִּבְנָה שָׁם (האור) שֶׁלּוֹ כְּאוֹר הַשֶּׁמֶשׁ וּכְזהַר הָרָקִיעַ, שֶׁכָּתוּב (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזהַר הָרָקִיעַ וְגוֹ', וְאָז כֶּסֶף שָׁלֵם, גּוּף שָׁלֵם בְּלִי עִרְבּוּבְיָה אַחֶרֶת."]]],[["דְּאָמַר רַבִּי יַעֲקֹב גּוּפָא דְנָהִיר יִרְמֵי קוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא דִּכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ. וּכְתִיב (ישעיהו כ״ב:י״ז) הִנֵּה יְיָ מְטַלְטֶלְךָ וגו'. וּכְדֵין יִתְקְרוּן קַדִּישִׁין עִלָּאִין דִּכְתִיב, (ישעיהו ד׳:ג׳) קָדוֹשׁ יֵאָמֶר לוֹ. וְדָא הוּא דְּאִתְקְרֵי תְּחִיַּית הַמֵּתִים דְּבַתְרַיְיתָא, וְדָא הוּא (כספא שלים גופא שלימא) (נ\"א נסיונא) בַּתְרַיְיתָא וְלָא יִטְעֲמוּן עוֹד טַעֲמָא דְמוֹתָא דִּכְתִיב בִּי נִשְׁבַּעְתִּי נְאֻם יְיָ כִּי יעַן אֲשֶׁר עָשִׂיתָ וְגו' כִּי בָּרֵךְ אֲבָרֶכְךָ וְגו'. וּבְהַהוּא זִמְנָא מַצְּלוּ צַּדִּיקַיָּיא דְּלָא יִתְנַסּוּן בְּדָא יתִּיר.","מַה כְּתִיב וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל וגו'. אִלֵּין שְׁאָר חַיָּיבֵי עַלְמָא דְּאִתְקְרוּן אֵילִים כְּמָא דְאַתְּ אָמֵר, (ישעיהו ס׳:ז׳) אֵילֵי נְבָיוֹת יְשָׁרְתוּנֶךְ וּמְתַרְגְּמִינָן רַבְרְבֵי נְבָיוֹת. אַחַר נֶאֱחַז בַּסְּבַךְ וְגו' כְּמָא דְאַתְּ אָמֵר, (תהילים ע״ה:י״א) וְכָל קַרְנֵי רְשָׁעִים אֲגַדֵּעַ. (וישלח אברהם וגו) וַיִּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל וְגו'. דְּאִנּוּן מְזוּמָנִין לְאִתְנַסָּאָה בְּכָל נִסְיוֹנָא בִּישָׁא, וְיִשְׁתָּאֲרוּן הַצַּדִּיקִים לְעַלְמָא דְאָתֵי כְּמַלְאָכִין עִלָּאִין קַדִּישִׁין לְיַחֲדָא שְׁמֵיהּ, וּבְגִין כָּךְ כְּתִיב, (זכריה י״ד:ט׳) בַּיּוֹם הַהוּא יִהְיְה יְיָ אֶחָד וּשְׁמוֹ אֶחָד וגו'.","אָמַר לֵיהּ (נ\"א אמר לון) רַבִּי יְהוּדָה מִכָּאן וּלְהָלְאָה אַצְּלָחוּ פִּתְחָא. עָאל יוֹמָא אָחֳרָא עָאלוּ קַמֵּיהּ כָּל בְּנִי מָתָא, אָמְרוּ לֵיהּ לֵימָא לָן מַר מִלַּיָיא דְאוֹרַיְיתָא בְּפָרְשָׁתָא דְּקָרֵינָן בָּהּ יוֹמָא דְשַׁבַּתָּא וַיְיָ פָּקַד אֶת שָׂרָה. קָם בֵּינֵי עַמּוּדֵי, פָּתַח וְאָמַר וַיְיָ פָּקַד אֶת שָׂרָה וְגו'. שָׁלשׁ מַפְתֵּחוֹת בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא ולא מְסָרָם לא בְּיַד מַלְאָךְ וְלֹא בְּיַד שָׂרָף. מַפְתֵּחַ שֶׁל חַיָּה וְשֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּית הַמֵּתִים. בָּא אֵלִיָּהוּ וְנָטַל הַשְּׁנַיִם שֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּית הַמֵּתִים. וְאָמַר רַבִּי יוֹחָנָן לֹא נִמְסַר בְּיַד אֵלִיָּהוּ אֶלָּא אַחַת. דְּאָמַר רַבִּי יוֹחָנָן כְּשֶׁבִּקֵּשׁ אֵלִיָּהוּ לְהַחֲיוֹת בֶּן הַצָּרְפִית אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, לָא יָאוֹת לָךְ לְמֵיסַב בִּידָךְ שְׁתֵּי מַפְתֵּחוֹת, אֶלָּא תֵּן לִי מַפְתֵּחַ הַגְּשָׁמִים וּתְחַיֶּה הַמֵּת. והַיְינוּ דִכְתִיב, (מלכים א י״ח:א׳) לֵךְ הֵרָאֵה אֶל אַחְאָב וְגו' וְאֶתְּנָה מָטָר. לא אָמַר ותֵן מָטָר אֶלָּא וְאֶתְּנָה."],[[0,"דאמר ר' יעקב וכו':","שאמר ר\"י, גוף מאיר יטיל הקב\"ה מלמעלה, שכתוב, כי טל אורות טלך וכתוב הנה ה' מטלטלך וגו', ואז יקראו קדושים עליונים. שכתוב קדוש יאמר לו, וזה הוא שנקרא תחית המתים האחרונה. ולא יטעמו עוד טעם של מות, שכתוב בי נשבעתי נאום ה' וגו' ובזמן ההוא מתפללים הצדיקים שלא יתנסו בזה יותר."],[1,"מה כתיב וכו':","מה כתוב, וישא אברהם את עיניו וירא והנה איל וגו', היינו שאר רשעי עולם הנקראים אילים, כש\"א אילי נביות ישרתונך, ומתרגמינן רברבי נביות. \u0003אחר נאחז בסבך\u0004 וגו', הוא כמו שאתה אומר וכל קרני רשעים אגדע. \u0003וילך אברהם ויקח את האיל\u0004 וגו', שהם מזומנים עוד להתנסות בכל נסיון רע. והצדיקים ישארו לעתיד לבא כמלאכים העליונים הקדושים, ליחד את שמו, וע\"כ כתוב, ביום ההוא יהיה ה' אחד ושמו אחד וגו'."],[2,"א\"ל רבי יהודה",": אמר להם ר' יהודה, מכאן ואילך פתחו הפתח, כלומר שיכולים מעתה לכנוס אלי כל מי שרוצה. כי כבר גמר לומר סודות חנעלים ביותר."]],[[0,"","שֶׁאָמַר רַבִּי יַעֲקֹב, גּוּף שֶׁמֵּאִיר יִזְרֹק הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה, שֶׁכָּתוּב (ישעיה כו) כִּי טַל אוֹרוֹת טַלֶּךְ, וְכָתוּב (שם כב) הִנֵּה ה' מְטַלְטֶלְךְ וְגוֹ'. וְאָז יִקָּרְאוּ קְדוֹשִׁים עֶלְיוֹנִים, שֶׁכָּתוּב (שם ד) קָדוֹשׁ יֵאָמֶר לוֹ. וְזֶהוּ שֶׁנִּקְרָא תְּחִיַּת הַמֵּתִים שֶׁל הַסּוֹף, וְזֶהוּ (כסף שלם גוף שלם) (נסיון) אַחֲרוֹן, וְלֹא יִטְעֲמוּ עוֹד טַעַם הַמָּוֶת, שֶׁכָּתוּב בִּי נִשְׁבַּעְתִּי נְאֻם ה' כִּי יַעַן אֲשֶׁר עָשִׂיתָ וְגוֹ' כִּי בָרֵךְ אֲבָרֶכְךְ וְגוֹ'. וּבְאוֹתוֹ זְמַן מִתְפַּלְלִים הַצַּדִּיקִים שֶׁלֹּא יִתְנַסּוּ בָזֶה יוֹתֵר."],[1,"","מַה כָּתוּב? וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל וְגוֹ'. אֵלּוּ שְׁאָר רִשְׁעֵי הָעוֹלָם שֶׁנִּקְרְאוּ אֵילִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) אֵילֵי נְבָיוֹת יְשָׁרְתוּנֶךְ, וּמְתַרְגְּמִים: גְּדוֹלֵי נְבָיוֹת. אַחַר נֶאֱחַז בַּסְּבַךְ וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר וְכָל קַרְנֵי רְשָׁעִים אֲגַדֵּעַ. וַיֵּלֶךְ אַבְרָהָם וַיִּקַּח אֶת הָאַיִל וְגוֹ', שֶׁהֵם מְזֻמָּנִים לְהִתְנַסּוֹת בְּכָל נִסָּיוֹן רַע, וְיִשָּׁאֲרוּ הַצַּדִּיקִים לָעוֹלָם הַבָּא כְּמוֹ מַלְאָכִים עֶלְיוֹנִים קְדוֹשִׁים לְיַחֵד אֶת שְׁמוֹ, וְלָכֵן כָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד וְגוֹ'."],[2,"","אָמַר לוֹ (אמר להם) רַבִּי יְהוּדָה, מִכָּאן וָהָלְאָה פִּתְחוּ הַפֶּתַח. נִכְנַס יוֹם אַחֵר, וְנִכְנְסוּ לְפָנָיו כָּל בְּנֵי הָעִיר. אָמְרוּ לוֹ, יֹאמַר לָנוּ מַר דִּבְרֵי תוֹרָה בַּפָּרָשָׁה שֶׁקָּרִינוּ בָהּ בְּיוֹם שַׁבָּת, וַה' פָּקַד אֶת שָׂרָה. קָּם בֵּין הָעַמּוּדִים, פָּתַח וְאָמַר, וַה' פָּקַד אֶת שָׂרָה וְגוֹ'. שְׁלֹשָׁה מַפְתְּחוֹת בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא מְסָרָם לֹא בְּיַד מַלְאָךְ וְלֹא בְּיַד שָׂרָף: מַפְתֵּחַ שֶׁל חַיָּה, וְשֶׁל גְּשָׁמִים, וְשֶׁל תְּחִיַּת הַמֵּתִים. בָּא אֵלִיָּהוּ וְנָטַל הַשְּׁנַיִם - שֶׁל גְּשָׁמִים וְשֶׁל תְּחִיַּת הַמֵּתִים. וְאָמַר רַבִּי יוֹחָנָן, לֹא נִמְסַר בְּיַד אֵלִיָּהוּ אֶלָּא אַחַת. שֶׁאָמַר רַבִּי יוֹחָנָן, כְּשֶׁבִּקֵּשׁ אֵלִיָּהוּ לְהַחֲיוֹת בֶּן הַצָּרְפִית, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: לֹא נָאֶה לְךְ לָקַחַת בְּיָדְךְ שְׁנֵי מַפְתְּחוֹת, אֶלָּא תֵּן לִי מַפְתֵּחַ הַגְּשָׁמִים, וּתְחַיֶּה הַמֵּת. וְהַיְנוּ שֶׁכָּתוּב (מלכים א יח) לֵךְ הֵרָאֵה אֶל אַחְאָב וְגוֹ' וְאֶתְּנָה מָטָר. לֹא אָמַר וְתֵן מָטָר, אֶלָּא וְאֶתְּנָה."]]],[["וְהָא אֱלִישָׁע הֲווּ לֵיהּ. אִין. לְקַיֵּים פִּי שְׁנַיִם בְּרוּחוֹ שֶׁל אֵלִיּהוּ, אֶלָּא שְׁלָשְׁתָּם לא מְסָרָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַד שָׁלִיחַ, דְּאָמַר רַבִּי סִימּוֹן בֹּא וּרְאֵה כֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּפַעַם אַחַת מְחַיִּה מֵתִים וּמוֹרִיד שְׁאוֹל וַיָּעַל, מַזְרִיחַ מְאוֹרוֹת וּמוֹרִיד גְּשָׁמִים, מַצְּמִיחַ חָצִּיר, מְדַשֵּׁן יְבוּלִים, פּוֹקֵד עֲקָרוֹת, נוֹתֵן פַּרְנָסוֹת, עוֹזֵר דַּלִּים, סוֹמֵךְ נוֹפְלִים, זוֹקֵף כְּפוּפִים, מְהַעֲדֵא מַלְכִין וּמְהָקֵם מַלְכִין, וְהַכֹּל בִּזְמַן אֶחָד וּבְרֶגַע אֶחָד וּבְבַת אַחַת מַה שֶּׁאֵין שָׁלִיחַ לְעוֹלָם יָכוֹל לַעֲשׂוֹתוֹ.","תַּנְיָא אָמַר רַבִּי יוֹסֵי כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ צָּרִיךְ לַעֲשׂוֹת אֶלָּא בְּדִבּוּר, דְּכֵיוָן דְאָמַר מִמְּקוֹם קְדוּשָׁתוֹ יְהֵא כָךְ מִיָּד נַעֲשָׂה. בֹּא וּרְאֵה כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא דִּכְתִיב, (תהילים ל״ג:ו׳) בִּדְבַר יְיָ שָׁמַיִם נַעֲשׂוּ. דְּאָמַר רַבִּי יוֹחָנָן (יהודה) מַאי דִכְתִיב, (שמות י״ב:י״ב) וְעָבַרְתִּי בְּאֶרֶץ מִצְּרַיִם אֲנִי וְלֹא מַלְאָךְ וגו'.","אִי הָכִי יְקָרָא סַגִּיאָה הוּא לְמִצְּרָאֵי, דְּלָא דָמֵי מַאן דְּתָפַשׂ מַלְכָּא לְמַאן דְּתָפַשׂ הֶדְיוֹטָא. וְעוֹד אֵין לְךָ אוּמָה מְזוּהֱמֶת בְּכָל טוּמְאָה כְּמוֹ הַמִּצְּרִים דִּכְתִיב בְּהוּ (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְגו' שֶׁהֵם חֲשׁוּדִים עַל מִשְׁכַּב זָכוּר, וְהֵם בָּאִים מֵחָם שֶׁעָשָׂה מַה שֶּׁעָשָׂה לְאָבִיו וְקִלֵּל אוֹתוֹ וְלִכְנַעַן בְּנוֹ. וְכִי לֹא הָיָה לְהַקָּדוֹשׁ בָּרוּךְ הוּא מַלְאָךְ אוֹ שָׁלִיחַ לְשַׁגֵּר לַעֲשׂוֹת נְקָמָה בְּמִצְּרַיִם כְּמוֹ שֶׁעָשָׂה בְּאַשּׁוּר שֶׁהָיָה בְּנוֹ שֶׁל שֵׁם דִּכְתִיב, (בראשית י׳:כ״ב) וּבְנֵי שֵׁם עֵילָם וְאַשּׁוּר. ושֵׁם הָיָה כֹּהֵן גָּדוֹל וְנִתְבָּרֵךְ שֶׁנְּאֱמַר (בראשית ט׳:כ״ו) בָּרוּךְ יְיָ אֱלהֵי שֵׁם. וְהָיָה לְשֵׁם הַגְּדוּלָּה וְהַבְּרָכָה עַל אֶחָיו. וּכְתִיב בָּם (ישעיהו ל״ז:ל״ו) וַיִּצֵּא מַלְאַךְ יְיָ וַיַּכֶּה בְּמַחֲנֶה אַשּׁוּר. וְעַל יְדֵי שָׁלִיחַ נַעֲשָׂה, כָל שֶׁכֵּן הַמִּצְּרִים שֶׁהֵם מְזוּהָמִים יוֹתֵר מִכָּל אוּמָה, ואָמַר אֲנִי וְלֹא מַלְאָךְ.","אֶלָּא אָמַר רַבִּי יְהוּדָה מִכָּאן לָמַדְנוּ כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַעֲלָתוֹ שֶׁהוּא גָּבוֹהַּ עַל הַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא אוּמָה זוֹ שֶׁל מִצְּרַיִם מְזוּהֱמֶת וּמְטוּנֶפֶת, ואֵין רָאוּי לְשַׁגֵּר מַלְאָךְ ולא שָׂרָף, דָּבָר קָדוֹשׁ בֵּין רְשָׁעִים אֲרוּרִים מְטוּנָפִים, אֶלָּא אֲנִי עוֹשֶׂה מַה שֶּׁאֵין יָכוֹל לַעֲשׂוֹת מַלְאָךְ וְלֹא שָׂרָף ולא שָׁלִיחַ. שֶׁאֲנִי אוֹמֵר מִמְּקוֹם קְדוּשָּׁתִי יְהֵא כָךְ וּמִיָּד נַעֲשָׂה, מַה שֶּׁאֵין הַמַּלְאָךְ יָכוֹל לַעֲשׂוֹתוֹ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדוּשָּׁתוֹ אוֹמֵר יְהֵא כָךְ וּמִיָּד נַעֲשָׂה מַה שֶּׁהוּא רוֹצֶּה לַעֲשׂוֹת. וּלְפִיכָךְ לא נַעֲשֵׂית נְקָמָה זוֹ עַל יְדֵי מַלְאָךְ וְשָׁלִיחַ, בִּשְׁבִיל קְלוֹן הַמִּצְּרִים, וּלְהַרְאוֹת גְּדוּלָּתוֹ שֶׁל מָקוֹם שֶׁלֹּא רָצָּה שֶׁיִּכָּנְסוּ בֵּינֵיהֶם דָּבָר קָדוֹשׁ, וְעַל הַדֶּרֶךְ הַזֶּה נֶאֱמַר אֲנִי וְלֹא מַלְאָךְ. אֲנִי יָכוֹל לַעֲשׂוֹתוֹ וְלֹא מַלְאָךְ."],[[2,"אי הכי יקרא סגיאה וכו':","אם כן, כבוד גדול הוא זה למצרים, שאינו דומה מי שתפשו מלך למי שתפשו איש פשוט."]],[[0,"","וַהֲרֵי אֱלִישָׁע הָיוּ לוֹ? כֵּן. לְקַיֵּם פִּי שְׁנַיִם בְּרוּחוֹ שֶׁל אֵלִיָּהוּ. אֶלָּא שְׁלָשְׁתָּם לֹא מְסָרָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּיַד שָׁלִיחַ. שֶׁאָמַר רַבִּי סִימוֹן, בֹּא רְאֵה כֹּחוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא: בְּפַעַם אַחַת מְחַיֵּה מֵתִים וּמוֹרִיד שְׁאוֹל וַיָּעַל, מַזְרִיחַ מְאוֹרוֹת וּמוֹרִיד גְּשָׁמִים, מַצְמִיחַ חָצִיר, מְדַשֵּׁן יְבוּלִים, פּוֹקֵד עֲקָרוֹת, נוֹתֵן פַּרְנָסוֹת, עוֹזֵר דַּלִּים, סוֹמֵךְ נוֹפְלִים, זוֹקֵף כְּפוּפִים, מַעֲבִיר מְלָכִים וּמֵקִים מְלָכִים, וְהַכֹּל בִּזְמַן אֶחָד וּבְרֶגַע אֶחָד וּבְבַת אַחַת מַה שֶּׁאֵין שָׁלִיחַ לְעוֹלָם יָכוֹל לַעֲשׂוֹתוֹ."],[1,"","שָׁנִינוּ בַּבָּרַיְתָא, אָמַר רַבִּי יוֹסֵי, כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵינוֹ צָרִיךְ לַעֲשׂוֹת אֶלָּא בְּדִבּוּר. שֶׁכֵּיוָן שֶׁאָמַר מִמְּקוֹם קְדֻשָּׁתוֹ יְהֵא כָּךְ - מִיָּד נַעֲשָׂה. בֹּא רְאֵה כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. שֶׁאָמַר רַבִּי יוֹחָנָן (יהודה), מַה זֶּה שֶׁכָּתוּב (שמות יב) וְעָבַרְתִּי בְּאֶרֶץ מִצְרַיִם אֲנִי וְלֹא מַלְאָךְ וְגוֹ'?"],[2,"","אִם כָּךְ, כָּבוֹד גָּדוֹל הוּא לְמִצְרַיִם, שֶׁלֹּא דוֹמֶה מִי שֶׁתָּפַס מֶלֶךְ לְמִי שֶׁתָּפַס הֶדְיוֹט. וְעוֹד, אֵין לְךְ אֻמָּה מְזֹהֶמֶת בְּכָל טֻמְאָה כְּמוֹ הַמִּצְרִים, שֶׁכָּתוּב בָּהֶם (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם וְגוֹ', שֶׁהֵם חֲשׁוּדִים עַל מִשְׁכַּב זָכוּר, וְהֵם בָּאִים מֵחָם שֶׁעָשָׂה מַה שֶּׁעָשָׂה לְאָבִיו, וְקִלֵּל אוֹתוֹ וְלִכְנַעַן בְּנוֹ. וְכִי לֹא הָיָה לַקָּבָּ\"ה מַלְאָךְ אוֹ שָׁלִיחַ לְשַׁגֵּר לַעֲשׂוֹת נְקָמָה בְּמִצְרַיִם כְּמוֹ שֶׁעָשָׂה בְּאַשּׁוּר שֶׁהָיָה בְּנוֹ שֶׁל שֵׁם, שֶׁכָּתוּב (בראשית י) וּבְנֵי שֵׁם עֵילָם וְאַשּׁוּר. וְשֵׁם הָיָה כֹּהֵן גָּדוֹל וְנִתְבָּרֵךְ, שֶׁנֶּאֱמַר (שם ט) בָּרוּךְ ה' אֱלֹהֵי שֵׁם, וְהָיָה לְשֵׁם הַגְּדֻלָּה וְהַבְּרָכָה עַל אֶחָיו, וְכָתוּב בָּם (ישעיה לז) וַיֵּצֵא מַלְאַךְ ה' וַיַּכֶּה בְּמַחֲנֵה אַשּׁוּר, וְעַל יְדֵי שָׁלִיחַ נַעֲשָׂה. כָּל שֶׁכֵּן הַמִּצְרִים שֶׁהֵם מְזהָמִים יוֹתֵר מִכָּל אֻמָּה, וְאָמַר אֲנִי וְלֹא מַלְאָךְ."],[3,"","אֶלָּא,? אָמַר רַבִּי יְהוּדָה, מִכָּאן לָמַדְנוּ כֹּחַ גְּבוּרָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַעֲלָתוֹ שֶׁהוּא גָבוֹהַּ מֵעַל הַכֹּל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: אֻמָּה זוֹ שֶׁל מִצְרַיִם מְזֹהֶמֶת וּמְטֻנֶּפֶת, וְאֵין רָאוּי לְשַׁגֵּר מַלְאָךְ וְלֹא שָׂרָף, דָּבָר קָדוֹשׁ בֵּין רְשָׁעִים אֲרוּרִים מְטֻנָּפִים, אֶלָּא אֲנִי עוֹשֶׂה מַה שֶּׁאֵין יָכוֹל לַעֲשׂוֹת מַלְאָךְ וְלֹא שָׂרָף וְלֹא שָׁלִיחַ. שֶׁאֲנִי אוֹמֵר מִמְּקוֹם קְדֻשָּׁתִי יְהֵא כָּךְ - וּמִיָּד נַעֲשֶׂה, מַה שֶּׁאֵין הַמַּלְאָךְ יָכוֹל לַעֲשׂוֹתוֹ. אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מִמְּקוֹם קְדֻשָּׁתוֹ אוֹמֵר יְהֵא כָּךְ - וּמִיָּד נַעֲשֶׂה מַה שֶּׁהוּא רוֹצֶה לַעֲשׂוֹת. וּלְפִיכָךְ לֹא נַעֲשֵׂית נְקָמָה זוֹ עַל יְדֵי מַלְאָךְ וְשָׁלִיחַ, בִּשְׁבִיל קְלוֹן הַמִּצְרִים, וּלְהַרְאוֹת גְּדֻלָּתוֹ שֶׁל מָקוֹם שֶׁלֹּא רָצָה שֶׁיִּכָּנְסוּ בֵינֵיהֶם דָּבָר קָדוֹשׁ. וְעַל הַדֶּרֶךְ הַזֶּה נֶאֱמַר אֲנִי וְלֹא מַלְאָךְ. אֲנִי יָכוֹל לַעֲשׂוֹתוֹ, וְלֹא מַלְאָךְ."]]],[["כַּיּוֹצֵּא בּוֹ אָמַר רַבִּי יְהוּדָה מַאי דִכְתִיב, (יונה ב׳:י״א) וַיֹּאמֶר יְיָ לַדָּג. וְכַמָּה צַּדִּיקִים וַחֲסִידִים מִיִּשְׂרָאֵל שֶׁלֹּא דִּבֵּר עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָא לְדַבֵּר עִם הַדָּג דָּבָר שֶׁאֵינוֹ מַכִּיר וְיוֹדֵעַ. אֶלָּא אָמַר רַבִּי יְהוּדָה כֵּיוָן שֶׁעָלְתָה תְּפִלָּתוֹ שֶׁל יוֹנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדוּשָּׁתוֹ אָמַר בִּשְׁבִיל שֶׁיָּקִיא הַדָּג אֶת יוֹנָה אֶל הַיַּבָּשָׁה. למ\"ד לַדָּג כְּמוֹ בִּשְׁבִיל, כְּלוֹמַר וַיֹּאמֶר יְיָ בִּשְׁבִיל הַדָּג שֶׁיָּקִיא אֶת יוֹנָה אֶל הַיַּבָּשָׁה. מִמְּקוֹם קְדוּשָּׁתוֹ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, יְהֵא כָךְ וּמִיָּד נַעֲשָׂה, מַה שֶׁאֵין שָׁלִיחַ יָכוֹל לַעֲשׂוֹתוֹ.","תַּנְיָא אָמַר רַבִּי שִׁמְעוֹן מַפְתֵּחַ שֶׁל חַיָה בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הִיא, וּבְעוֹד שֶׁהִיא יוֹשֶׁבֶת עַל הַמַּשְׁבֵּר הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בְּאוֹתוֹ הַוְּלַד אִם רָאוּי הוּא לָצֵּאת לָעוֹלָם (יוצא ו) פּוֹתֵחַ דַּלְתוֹת בִּטְנָהּ וְיוֹצֵּא, וְאִם לָאו סוֹגֵר דַּלְתוֹתֶיהָ וּמֵתוּ שְׁנֵיהֶם. אִי הָכִי לא יִצֵּא רָשָׁע לָעוֹלָם. אֶלָּא הָכִי תָּנִינָן עַל שָׁלשׁ עֲבֵירוֹת נָשִׁים מֵתוֹת וְכוּ' (אמר רבי שמעון והא) וְאָמַר רַבִּי יִצְּחָק לָמָּה אִשָּׁה מַפֶּלֶת פְּרִי בִטְנָהּ. אֶלָּא אָמַר רַבִּי יִצְּחָק הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אוֹתוֹ הָעוּבָּר שֶׁאֵינוֹ רָאוּי לָצֵּאת לָעוֹלָם וּמַקְדִּים לַהֲמִיתוֹ בִּמְעֵי אִמּוֹ שֶׁנֶּאֱמַר (בראשית ו׳:ד׳) הַנְּפִילִים הָיוּ בָּאָרֶץ בַּיָּמִים הָהֵם. הַנְּפִלִים כְּתִיב בְּלֹא יוּד רִאשׁוֹנָה. וְלָמָּה, בִּשְׁבִיל שֶׁאַחֲרֵי כֵן בָּאוּ בְּנֵי הָאֱלהִים אֶל בְּנוֹת הָאָדָם וְיָלְדוּ לָהֶם בִּזְנוּת וַיִּרְבּוּ מַמְזֵרִים בָּעוֹלָם."],[],[[0,"","כַּיּוֹצֵא בּוֹ אָמַר רַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (יונה ב) וַיֹּאמֶר ה' לַדָּג? וְכַמָּה צַדִּיקִים וַחֲסִידִים מִיִּשְׂרָאֵל שֶׁלֹּא דִבֵּר עִמָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, וּבָא לְדַבֵּר עִם הַדָּג דָּבָר שֶׁאֵינוֹ מַכִּיר וְיוֹדֵעַ!? אֶלָּא, אָמַר רַבִּי יְהוּדָה, כֵּיוָן שֶׁעָלְתָה תְפִלָּתוֹ שֶׁל יוֹנָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִמְּקוֹם קְדֻשָּׁתוֹ אָמַר בִּשְׁבִיל שֶׁיָּקִיא הַדָּג אֶת יוֹנָה אֶל הַיַּבָּשָׁה. לָמֶ\"ד לַ'דָּג כְּמוֹ בִּשְׁבִיל. כְּלוֹמַר, וַיּאמֶר ה' בִּשְׁבִיל הַדָּג שֶׁיָּקִיא אֶת יוֹנָה אֶל הַיַּבָּשָׁה. מִמְּקוֹם קְדֻשָּׁתוֹ אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא יְהֵא כָּךְ - וּמִיָּד נַעֲשָׂה, מַה שֶּׁאֵין שָׁלִיחַ יָכוֹל לַעֲשׂוֹתוֹ."],[1,"","שָׁנִינוּ בַּבָּרַיְתָא, אָמַר רַבִּי שִׁמְעוֹן, מַפְתֵּחַ שֶׁל חַיָּה בְּיָדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הִיא, וּבְעוֹד שֶׁהִיא יוֹשֶׁבֶת עַל הַמַּשְׁבֵּר, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בְּאוֹתוֹ הַוָּלָד. אִם רָאוּי הוּא לָצֵאת לָעוֹלָם - (יוצא, ו) פוֹתֵחַ דַּלְתוֹת בִּטְנָהּ וְיוֹצֵא. וְאִם לָאו - סוֹגֵר דַּלְתוֹתֶיהָ וּמֵתוּ שְׁנֵיהֶם. אִם כָּךְ, לֹא יֵצֵא רָשָׁע לְעוֹלָם? אֶלָּא כָּךְ שָׁנִינוּ, עַל שָׁלֹשׁ עֲבֵרוֹת נָשִׁים מֵתוֹת וְכוּ', (אמר רבי שמעון והרי) וְאָמַר רַבִּי יִצְחָק, לָמָּה אִשָּׁה מַפֶּלֶת פְּרִי בִטְנָהּ. אֶלָּא,? אָמַר רַבִּי יִצְחָק, הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אוֹתוֹ הָעֻבָּר שֶׁאֵינוֹ רָאוּי לָצֵאת לָעוֹלָם, וּמַקְדִּים לַהֲמִיתוֹ בִּמְעֵי אִמּוֹ, שֶׁנֶּאֱמַר (בראשית ו) הַנְּפִלִים הָיוּ בָאָרֶץ בַּיָּמִים הָהֵם. הַנְּפִלִים כָּתוּב בְּלֹא יוֹ\"ד רִאשׁוֹנָה, וְלָמָּה? בִּשְׁבִיל שֶׁאַחֲרֵי כֵן בָּאוּ בְּנֵי הָאֱלֹהִים אֶל בְּנוֹת הָאָדָם וְיָלְדוּ לָהֶם בִּזְנוּת וַיִּרְבּוּ מַמְזֵרִים בָּעוֹלָם."]]],[["הֵמָּה הַגִּבּוֹרִים אֲשֶׁר מֵעוֹלָם. שֶׁאֵין גִּבּוֹר וּפָרִיץ ועָרִיץ כְּמוֹ הַמַּמְזִר. אַנְשֵׁי הַשֵּׁם, שֶׁהַכֹּל יַכִּירוּ לִקְרוֹתוֹ הַשֵּׁם הַיָּדוּעַ מַמְזִר, דְּכֵיוָן שֶׁרוֹאִים מַעֲשָׂיו שֶׁהוּא פָּרִיץ וְעָרִיץ וְגִבּוֹר הַכֹּל יִקְרְאוּהוּ אוֹתוֹ שֵׁם. וּמַה דְאָמַר רַבִּי שִׁמְעוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בְּאוֹתוֹ הַוְּלַד. אֵין לְךָ רָשָׁע בָּעוֹלָם מֵאוֹתָם הָרְשָׁעִים הַיּוֹצְּאִים לָעוֹלָם שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּין בּוֹ ורוֹאֶה אִם אוֹתוֹ הַגּוּף יַנִּיחַ בֵּן צַּדִּיק וְכָשֵׁר, אוֹ שֶׁיַּצִּיל לְאָדָם מִיִּשְׂרָאֵל מִמִּיתָה מְשׁוּנָּה, אוֹ שֶׁיַּעֲשֶׂה טוֹבָה אַחַת, וּבִשְׁבִיל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִּיאוֹ לָעוֹלָם.","בְּיוֹמוֹי דְרַבִּי יוֹסֵי הֲווּ אִנּוּן פְּרִיצֵּי דְּהֲווּ מְשַׁדְּדֵי בְּטוּרַיָּיא עִם פְּרִיצֵּי אוּמּוֹת הָעוֹלָם, וְכַד מַשְׁכְּחֵי בַּר נָשׁ וְתָפְשֵׂי לֵיהּ לְקָטְלֵיהּ, הֲווּ אָמְרִין לֵיהּ מַה שְּׁמָךְ, אִי הֲוָה יוּדָאי הֲווּ אָזְלִין עִמֵּיהּ וּמַפְקִין לֵיהּ מִן טוּרַיָּיא, וְאִי הֲוָה בַּר נָשׁ אַחֲרִינָא קָטְלֵי לֵיהּ. (והא) והֲוָה אָמַר רַבִּי יוֹסֵי אִתְחֲזוּן אִנּוּן בְּכל הַאי לְמֵיעַל לְעַלְמָא דְאָתֵי.","תָּנוּ רַבָּנָן ג' דְּבָרִים הַלָּלוּ אֵינָן בָּאִן לָעוֹלָם אֶלָּא בְּקוֹלוֹת, קוֹל חַיָּה דִּכְתִיב, (בראשית ג׳:ט״ז) בְּעֶצֶּב תֵּלְדִי בָּנִים וּכְתִיב, (בראשית ל׳:כ״ב) וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים. קוֹל גְּשָׁמִים דִּכְתִיב, (תהילים כ״ט:ג׳) קוֹל יְיָ עַל הַמָּיִם וּכְתִיב, (מלכים א י״ח:מ״א) כִּי קוֹל הֲמוֹן הַגָּשֶׁם. קוֹל תְּחִיַּית הַמֵּתִים דִּכְתִיב, (ישעיהו מ׳:ג׳) קוֹל קוֹרֵא בַּמִּדְבָּר. מַאי בָּעֵי הָכָא קָלָא בְּמַדְבְּרָא. אֶלָּא אָמַר רַבִּי זְרִיקָא אִלֵּין אִנּוּן קָלַיָיא לְאַתְעָרָא מֵתֵי מִדְבָּר, וּמִכָּאן דְּהוּא הַדִּין לְכָל הָעוֹלָם. אָמַר רַבִּי יוֹחָנָן הָא תְּנַן כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר נִכְנַס בְּקוֹלוֹת. כְּשֶׁיָּקוּמוּ בִּתְחִיַּית הַמֵּתִים אֵינוֹ דִּין שֶׁיָּקוּמוּ בְּקוֹלֵי קוֹלוֹת.","אָמַר רַבִּי יעֲקֹב עֲתִידָה בַּת קוֹל לִהְיוֹת מִתְפּוֹצֶּצֶּת בְּבָתֵּי קְבָרוֹת וְאוֹמֶרֶת (ישעיהו כ״ו:י״ט) הָקִיצּוּ ורַנְּנוּ שׁוֹכְנִי עָפָר, וַעֲתִידִים לִחְיוֹת בְּטַל שֶׁל אוֹר גָּדוֹל שֶׁל מַעְלָה דִּכְתִיב, (ישעיהו כ״ו:י״ט) כִּי טַל אוֹרוֹת טַלֶּךָ וְאֶרֶץ רְפָאִים תַּפִּיל. אכי\"ר, (ע\"כ מדרש הנעלם).","וַיְיָ פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר, דִּכְתִיב לַמּוֹעֵד אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וּלְשָׂרָה בֵן. וְתָנִינָן פָּקַד אֶת שָׂרָה, פְּקִידָה לְנוּקְבָא, זְכִירָה לִדְכוּרָא, וּבְגִין כָּךְ וַיְיָ פָּקַד אֶת שָׂרָה, כַּאֲשֶׁר אָמַר, דִּכְתִיב שׁוֹב אָשׁוּב אֵלֶיךָ כָּעֵת חַיָּה וְגו', מֵהָכָא מַשְׁמַע דְּאָמַר (קב ב) וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךָ, וַיֹּאמֶר סְתָם, דְּאִיהוּ הֲוָה וְלָא שְׁלִיחָא אָחֳרָא:","וַיַּעַשׂ יְיָ לְשָׂרָה וְגו'. כֵּיוָן דְּאָמַר וַיְיָ פָּקַד אֶת שָׂרָה, מַהוּ וַיַּעַשׂ יְיָ לְשָׂרָה. אֶלָּא הָכִי תָּנִינָן דְּאִיבָּא דְּעוֹבָדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק מֵעֵדֶן אִיהוּ, וְאִיהוּ נִשְׁמַתְהוֹן דְּצַדִּיקַיָּיא, וְאִיהוּ מַזָּלָא דְּכָל בִּרְכָאן טָבָאן וְגִשְׁמֵי בִּרְכָאן נָזְלֵי מִנֵּיהּ וּמִתַּמָּן נָפְקֵי, דִּכְתִיב לְהַשְׁקוֹת אֶת הַגָּן, דְּאִיהוּ מַזִּיל וּמַשְׁקֶה מֵעֵילָא לְתַתָּא, בְּגִין דְּבָנֵי (נשא) בְּהַאי (קפא א) מַזָּלָא תַּלְיָין וְלָא בְּאֲתַר אָחֳרָא. וְעַל דָּא כְּתִיב וַיְיָ פָּקַד אֶת שָׂרָה פְּקִידָה בִּלְחוֹדוֹי.","וַיַּעַשׂ יְיָ לְשָׂרָה. עֲשִׂיָּיה אִיהוּ לְעֵילָא מֵהַאי דַרְגָא (קיב ב) כְּמָה דְאִתְּמָר דְּהָא בְּמַזְּלָא תַּלְיָיא, וְעַל דָּא כָּאן פְּקִידָה וְכָאן עֲשִׂיָּיה. וּבְגִין כָּךְ אָמַר יְיָ וַיְיָ וְכֹלָּא חַד.","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר (תהילים קכ״ז:ג׳) הִנֵּה נַחֲלַת יְיָ בָּנִים שָׂכָר פְּרִי הַבָּטֶן. הִנֵּה נַחֲלַת יְיָ, אַחְסַנְתָּא לְאִתְאַחֲדָא בַּיְיָ דְּלָא יִתְעֲבַר מִינָהּ לְעָלְמִין, דְּבַר נָשׁ דְּזָכֵי לִבְנִין בְּהַאי עַלְמָא זָכֵי בְּהוּ לְמֵיעַל לְפַרְגּוֹדָא בְּעַלְמָא דְאָתֵי. בְּגִין דְּהַהוּא בְּרָא דְּשָׁבִיק בַּר נָשׁ וְזָכֵי בֵּיהּ בְּעַלְמָא דָא, אִיהוּ יִזְכֵּי לֵיהּ לְעַלְמָא דְאָתֵי, וְזָכֵי לְאַעָלָא בֵּיהּ לְנַחֲלַת יְיָ. מַאן נַחֲלַת יְיָ, דָּא אֶרֶץ הַחַיִּים. וְהָכִי קָרָא לָהּ לְאֶרֶץ יִשְׂרָאֵל דְּאִיהִי אֶרֶץ הַחַיִּים.","דָּוִד מַלְכָּא (קרא ליה) נַחֲלַת יְיָ דִּכְתִיב, (שמואל א כ״ו:י״ט) כִּי גֵּרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת יְיָ לֵאמֹר לֵךְ עֲבֹד אֱלהִים אֲחֵרִים, וּבְגִין כָּךְ הִנֵּה נַחֲלַת יְיָ בָּנִים. מַאן אַזְכֵּי לֵיהּ לְבַר נָשׁ. בְּנִין. אִי זָכֵי בְּהוּ בְּהַאי עַלְמָא, שָׂכָר פְּרִי הַבָּטֶן, אַגְרָא וְחוּלָקָא טָבָא בְּהַהִיא עַלְמָא, בְּהַהוּא אִיבָּא דְּמֵעוֹי אִיהוּ דְּזָכֵי בַּר נָשׁ בְּהַהוּא עַלְמָא בְּהוּ.","תָּא חֲזֵי, הִנֵּה נַחֲלַת יְיָ בָּנִים. יְרוּתָא וְאַחְסַנְתָּא דְּאִיבִּין דְּעוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא מִלְּעֵילָא אִיהוּ מֵאִילָנָא דְחַיֵּי, דְּהָא מִתַּמָּן זָכֵי בַּר נָשׁ לִבְנִין כְּמָא דְאַתְּ אָמֵר, (הושע י״ד:ט׳) מִמֶּנִּי פֶּרְיְךָ נִמְצָא. מַה כְּתִיב, (תהילים קכ״ז:ה׳) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לא יֵבוֹשׁוּ וְגו'. אַשְׁרֵי בְּעַלְמָא דֵין וְאַשְׁרֵי בְּעַלְמָא דְאָתֵי.","לֹא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר. מַאן אוֹיְבִים בַּשָּׁעַר. אִלֵּין מָארִיהוֹן דְּדִינִין, דְּכַד נִשְׁמָתָא נָפְקַת מֵהַאי עַלְמָא, כַּמָּה אִנּוּן מָרֵיהוֹן דְּדִינִין דְּזַמִּינִין קַמֵּיהּ, עַד לָא יֵיעוּל לְדוּכְתֵּיהּ בַּשָּׁעַר בְּהַהוּא תַּרְעָא דְּיֵיעוּל תַּמָּן, בְּגִין דְּמַשְׁכּוֹנִין שָׁבִיק בְּהַאי עַלְמָא וּבְגִינֵיהוֹן יִזְכֵּי בְּהַהוּא עַלְמָא וְעַל דָּא לא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר.","רַבִּי יְהוּדָה וְרַבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר לֵיהּ רַבִּי יְהוּדָה לְרַבִּי יוֹסֵי פְּתַח פּוּמָךְ וְלָעֵי בְּאוֹרַיְיתָא דְּהָא שְׁכִינְתָּא אִשְׁתַּכְּחַת גַּבָּךְ, דְּכָל זְמַן דִּבְמִלֵּי דְאוֹרַיְיתָא לָעָאן שְׁכִינְתָּא אַתְיָא וּמִתְחַבְּרָא, וְכָל שֶׁכֵּן בְּאוֹרְחָא (עט ב דשכינתא קדמא ואתיא ואזלא קמייהו דבני נשא דזכאן במהימנותא דקודשא בריך הוא.)","פָּתַח רַבִּי יוֹסֵי וְאָמַר. (תהלים קכז) אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנְךָ. אֶשְׁתְּךָ כְּגֶפֶן פֹּרִיָּה, כָּל זִמְנָא דְּאִתְּתָא בְּיַרְכְּתֵי בֵיתָא וְלָא נָפְקָא לְבַר, הִיא צְנוּעָה וְאִתְחֲזֵי לְאוֹלָדָא בְּנִין דְּכָשְׁרָן. כְּגֶפֶן, מַה גֶּפֶן לָא אִתְנַטְעָא אלָּא בְּזִינָהּ וְלָא בְּזִינָא אָחֳרָא. כָּךְ אִתְּתָא דְכָשְׁרָא לָא תֶעֱבַד נְטִיעָן בְּבַר נָשׁ אָחֳרָא. מַה גֶּפֶן לָא אִית בֵּיהּ רְכִיבָה מֵאִילָנָא אָחֳרָא, אוּף הָכִי אִתְּתָא דְּכָשְׁרָא הָכִי נָמֵי.","חֲמֵי מָה אַגְרָהּ, בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים. מַה זֵיתִים לָא נָפְלֵי טַרְפַּיְיהוּ כָּל יוֹמֵי שַׁתָּא וְכֻלְּהוּ קְשׁוּרִין (נ\"א בסירי) תָּדִיר, אוּף הָכִי בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךָ.","מַה כְּתִיב בַּתְרֵיהּ הִנֵּה כִי כֵן יְבֹרַךְ גָּבֶר יְרֵא יְיָ. מַאי הִנֵּה כִי כֵן יְבֹרַךְ גָּבֶר. הִנֵּה כֵן מִבָּעֵי לֵיהּ. אֶלָּא לְאַסְגָּאָה מִלָּה אָחֳרָא דְּאוֹלִיפְנָא דָּא מִינָּהּ, דְּכָל זִמְנָא דִּשְׁכִינְתָּא הֲוָה צְנִיעָא בְּאַתְרָהּ כְּדְקָא חָזֵי לָהּ כִּבְיָכוֹל בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים אִלֵּין יִשְׂרָאֵל כַּד שָׁרָאן בְּאַרְעָא. סָבִיב לְשֻׁלְחָנְךָ. דְּאָכְלֵי וְשָׁתָאן וּקְרֵבִין קָרְבָּנִין וְחָדָאן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְבָּרְכָן עִלָּאִין וְתַתָּאִין בְּגִינַיְיהוּ.","לְבָתַר דִּשְׁכִינְתָּא נָפְקַת, אִתְגָּלוּ יִשְׂרָאֵל מֵעַל פְּתוֹרָא דְּאֲבוּהוֹן וְהֲווּ בֵּינֵי עַמָּמַיָא וְצָוְוחִין כָּל יוֹמָא וְלֵית דְּאַשְׁגַּח בְּהוּ בַּר קוּדְשָׁא בְּרִיךְ הוּא דִּכְתִיב (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגו'. וְחָמִינָן כַּמָּה קַדִּישִׁין עִלָּאִין מִיתוּ בִּגְזֵרִין תַּקִּיפִין, וְכָל דָּא בְּגִין עוֹנָשָׁא דְאוֹרַיְיתָא דְּלָא קִיְימוּ יִשְׂרָאֵל כַּד הֲווּ שָׁרָאן בְּאַרְעָא קַדִּישָׁא.","חֲמֵי מַה כְּתִיב, (דברים כ״ח:מ״ז) תַּחַת אֲשֶׁר לא עָבַדְתָּ אֶת יְיָ אֱלהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. הַאי קְרָא אִיהוּ רָזָא, תַּחַת אֲשֶׁר לא עָבַדְתָּ בְּשִׂמְחָה, בִּזְמַן דְּכֹהֲנֵי הֲווּ קְרֵבִין קָרְבָּנִין וַעֲלָוָון וְדָא הִיא בְּשִׂמְחָה. וּבְטוּב לֵבָב, אִלֵּין לֵיוָאֵי. מֵרוֹב כֹּל, אֵלּוּ יִשְׂרָאֵל דְּהֲווּ אֶמְצָעִיִּים בֵּינַיְיהוּ וְנָטְלֵי בִּרְכָאן מִכָּל סִטְרִין.","דִּכְתִיב, (ישעיהו ט׳:ב׳) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. אִלֵּין כַּהֲנֵי. שָׂמְחוּ לְפָנֶיךָ כְּשִׂמְחַת בַּקָּצִיר, אֵלּוּ יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא בָּרִיךְ לוֹן עִבּוּרָא דְחַקְלָא וְיַהֲבֵי מַעַשְׂרָא מִכֹּלָּא. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל. אִלֵּין לֵיוָאֵי דְּנָטְלָא מַעַשְׂרָא מִגּוֹ אִדְרָא.","דָּבָר אַחֵר הִרְבִּיתָ הַגּוֹי. אִלֵּין יִשְׂרָאֵל דִּמְהֵימְנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא עֲלַיְיהוּ כְּדְקָא חָזֵי. לוֹ הִגְדַלְתָּ הַשִּׂמְחָה, דָּא אִיהוּ דַרְגָּא רֵישָׁא עִלָּאָה דְּאַבְרָהָם דְּאִתְדָּבַּק בָּהּ, דְּאִיהוּ גָּדוֹל וְחֶדְוָה בֵּיהּ אִשְׁתַּכַּח.","שָׂמְחוּ לְפָנֶיךָ, בְּשַׁעֲתָא דְּסָלְקִין לְאִתְדַבְּקָא בָּךְ. כְּשִׂמְחַת בַּקָּצִיר, דָּא כְּנֶסֶת יִשְׂרָאֵל דְּשִׂמְחַת בַּקָּצִיר דִּילֵיהּ הֲוָה. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל. כַּאֲשֶׁר יָגִילוּ, אִלֵּין שְׁאָר חֵילִין וּרְתִיכִין לְתַתָּא בְּזִמְנָא דִּמְחַלְּקֵי שָׁלָל וְטַרְפֵי טַרְפָא בְּרֵאשִׁיתָא דְכֹלָּא.","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ הֵפֵרוּ תוֹרָתֶךָ. עֵת לַעֲשׂוֹת לַיְיָ מַהוּ. אֶלָּא הָא אוּקְמוּהָ. אֲבָל עֵת, דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִקְרֵי עֵת. כְּמָה דְאַתְּ אָמֵר, (ויקרא ט״ז:ב׳) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. מַאי וְאַל יָבֹא בְכָל עֵת. כְּמָה דְאַתְּ אָמֵר, (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָּׁה זָרָה. וְדָא הוּא (ויקרא י׳:א׳) וַיַּק1ְריבוּ לִפְנֵי יְיָ אֵשׁ זָרָה וְגו'. מַאי טַעְמָא עֵת. בְּגִין דְּאִית לָהּ עֵת וּזְמַן לְכֹלָּא לְקָרְבָא לְאִתְנַהֲרָא לְאִתְחַבְּרָא כְּדְקָא יְאוּת. כְּמָא דְאַתְּ אָמֵר, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ יְיָ עֵת רָצוֹן.","לַעֲשׂוֹת לַיְיָ כְּמָה דִכְתִיב, (שמואל ב ח׳:י״ג) וַיַּעַשׂ דָּוִד שֵׁם. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא כְּאִילוּ עָבִיד וְתַקֵּן הַאי עֵת לְחַבְּרָא לָהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. וְכָל כָּךְ לָמָּה בְּגִין דְּהֵפֵרוּ תוֹרָתֶךָ, דְּאִילוּ לא הֵפֵרוּ תוֹרָתֶךָ לָא אִשְׁתַּכַּח פִּירוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא מִיִּשְׂרָאֵל לְעָלְמִין.","אָמַר רַבִּי יוֹסֵי כְּגַוְּונָא דָא כְּתִיב, (ישעיהו ס׳:כ״ב) אֲנִי יְיָ בְּעִתָּהּ אֲחִישֶׁנָּה. מַהוּ בְּעִתָּהּ. בְּעֵת ה'. דְּתָקוּם מֵעַפְרָא כְּדֵין אֲחִישֶׁנָּה.","אָמַר רַבִּי יוֹסֵי וְעִם כָּל דָּא יוֹמָא חַד נֶאֱלַמְתִּי דוּמִיָּ\"ה, בְּגִין דְּאִסְתַּלַּק וא\"ו מִן ה\"א, וְקוֹל לָא אִשְׁתַּכַּח, כְּדֵין דִּבּוּר אִתְאַלָּם.","וּבְגִין כָּךְ הִיא שְׁכִיבַת בְּעַפְרָא כָּל הַהוּא יוֹמָא (דנא) דְּה\"א. וּמַאן אִיהוּ אֶלֶף חֲמִשָּׁאָה, וְאַף עַל גַּב דְּאַקְדִימַת בְּגָלוּתָא עַד לָא יֵיעוּל הַהוּא אֶלֶף חֲמִשָּׁאָה רָזָא דְּה\"א,","וְכַד יֵיתֵי אֶלֶף שְׁתִיתָאָה דְּאִיהוּ רָזָא דְּוא\"ו, כְּדֵין וא\"ו יוֹקִים לְה\"א. בְּזִמְנָא (שמות ט ב) שִׁית זִמְנִין עֶשֶׂר שִׁתִּין נֶפֶשׁ, כְּדֵין שְׁלִימוּ וא\"ו עֶשֶׂר זִמְנִין, וא\"ו שִׁית זִמְנִין עֶשֶׂר, (דוא\"ו) וא\"ו סָלְקָא (בעשר) בְּי', וא\"ו נָחֲתָא בְּה\"א.","אִשְׁתְּלִים וא\"ו גּוֹ עֶשֶׂר שִׁית זִמְנִין, כְּדֵין הֲווּ שִׁתִּין לְאָקְמָא מֵעַפְרָא, וּבְכָל שִׁתִּין וְשִׁתִּין מֵהַהוּא אֶלֶף שְׁתִיתָאָה אִתְתַּקַּף ה\"א וְסַלְקָא בְּדַרְגּוֹי לְאִתְתַּקְּפָא. וּבְשִׁית מְאָה שְׁנִין לִשְׁתִיתָאָה יִתְפַּתְּחוּן תַּרְעֵי דְחָכְמְתָא לְעֵילָא וּמַבּוּעֵי דְחָכְמְתָא לְתַתָּא, וְיִתְתַּקַּן עַלְמָא לְאָעֳלָא בִּשְׁבִיעָאָה. כְּבַר נָשׁ דְּמִתְתַּקַּן בְּיוֹמָא שְׁתִיתָאָה מֵכִי עָרַב שִׁמְשָׁא לְאֲעָלָא בְּשַׁבַּתָּא. אוּף הָכִי נָמֵי. וְסִימָנִיךְ (בראשית ז׳:י״א) בִּשְׁנַת שֵׁשׁ מֵאוֹת שָׁנָה לְחַיֵּי נֹחַ וְגו' נִבְקְעוּ כָּל מַעְיְינוֹת תְּהוֹם רַבָּה.","אָמַר לֵיהּ רַבִּי יוֹסֵי כָּל דָּא אֲרִיכוּ זִמְנָא יַתִּיר מִכְּמָה דְאוּקְמוּהָ חַבְרַיָיא דְּאִיהוּ יוֹמָא חַד גָּלוּתָא דִּכְנֶסֶת יִשְׂרָאֵל וְלָא יַתִּיר דִּכְתִיב, (איכה א׳:י״ג) נְתָנַנִי שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא מֵאַבָּא בְּרָזִין דְּאַתְוָון דִּשְׁמָא קַדִּישָׁא וּבְיוֹמֵי דִּשְׁנֵי עַלְמָא וּבְיוֹמֵי דִבְרֵאשִׁית וְכֹלָּא רָזָא חָדָא אִיהוּ.","וּכְדֵין יִתְחֲזֵי קַשְׁתָּא בַּעֲנָנָא בִּגְוָונֵי (עב ב) נְהִירִין כְּאִתְּתָא דְמִתְקַשְּׁטָא לְבַעֲלָהּ דִּכְתִיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם וְהָא אוּקְמוּהָ וְשַׁפִּיר הוּא. וּרְאִיתִיהָ, בִּגְוָונִין נְהִירִין כְּדְקָא יְאוּת.","וּכְדֵין לִזְכֹּר בְּרִית עוֹלָם. מַאן בְּרִית עוֹלָם. דָּא כְּנֶסֶת יִשְׂרָאֵל, וְיִתְחַבַּר וא\"ו בְּה\"א, וְיֵיקִים לָהּ מֵעַפְרָא, כְּמָא דְאַתְּ אָמֵר וַיִּזְכֹּר אֱלהִים אֶת בְּרִיתוֹ. דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהִי בְּרִית, כְּמָא דְאַתְּ אָמֵר וְהָיְתָה לְאוֹת בְּרִית וְגו'.","כַּד יִתְעַר וא\"ו לְגַבֵּי ה\"א, כְּדֵין אָתִין עִלָּאִין יִתְעָרוּן בְּעָלְמָא (רלו א) וּבְנוֹי דִרְאוּבֵן זְמִינִין דְּיִתְעָרוּן, קְרָבִין בְּכָל עַלְמָא, וּכְנֶסֶת יִשְׂרָאֵל יוֹקִים לָהּ מֵעַפְרָא וְיִדְכַּר לָהּ קוּדְשָׁא בְּרִיךְ הוּא.","וְיִשְׁתַּכַּח קוּדְשָׁא בְּרִיךְ הוּא לְגַבָּהּ גּוֹ גָּלוּתָא כְּחוּשְׁבַּן וא\"ו שִׁית זִמְנִין י' (עשר). עֶשֶׂר זִמְנִין שִׁית שְׁנִין, וּכְדֵין תֵּיקוּם וְיִתְפַּקַד עַלְמָא לְמֶעְבַּד נוּקְמִין, וּמַאן דְּאִיהוּ מָאִיךְ יִתְרְמֵי.","אָמַר לֵיהּ רַבִּי יוֹסֵי שַׁפִּיר קָאֲמַרְתְּ בְּגִין דְּאִיהוּ גּוֹ רָזָא דְּאַתְוָון. וְלֵית לָן לְאַתְעָרָא חוּשְׁבַּן וְקִצִּין אָחֳרָנִין, דְּהָא בְּסִפְרָא דְּרַב יֵיבָא סָבָא אַשְׁכְּחָן חוּשְׁבַּן דָּא דִּכְתִיב, (ויקרא כ״ו:ל״ד) אָז תִּרְצֶה הָאָרֶץ. וְהוּא רָזָא דְּוא\"ו דִּכְתִיב, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְדָא הוּא וא\"ו כֹּלָּא כְּחֲדָא, וְעַל דָּא אֶזְכּוֹר, וּלְבָתַר וְהָאָרֶץ אֶזְכּוֹר, דָּא כְּנֶסֶת יִשְׂרָאֵל. תִּרְצֶה. תִּתְרְעֵי אַרְעָא לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא.","אֲבָל יוֹמָא חַד דְּאָמְרוּ חַבְרַיָיא וַדַּאי כֹּלָּא הוּא גָּנִיז קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְכֹלָּא אִשְׁתְּכַח בְּרָזָא דְאַתְוָון דִּשְׁמָא קַדִּישָׁא, דְּהָא גָלוּתָא בְּאִנּוּן אַתְוָון גָּלֵי לוֹן רַבִּי יֵיסָא הָכָא, וְהַשְׁתָּא בְּאִנּוּן אַתְוָון אִתְגַּלְּיָין וְגָלֵי לוֹן.","אָמַר לֵיהּ תָּא חֲזֵי, דְּאָפִילּוּ כַּד אִתְפַּקְּדָא שָׂרָה, מֵהַאי דַרְגָא לָא פַּקִּיד לָהּ, אֶלָּא בְּרָזָא דְוא\"ו, דִּכְתִיב וַיְיָ פָּקַד אֶת שָׂרָה וְגו'. בְּגִין דְּכֹלָּא בְּרָזָא דְוא\"ו אִיהוּ, וּבְהָא כָּלִיל כֹּלָּא, וּבֵיהּ אִתְגַּלְּיָא כֹּלָּא, בְּגִין דְּכָל מִלָּה דְּאִיהִי סְתִימָא אִיהִי גַּלֵּי כָּל סָתִים. וְלָא אָתֵי מַאן דְּאִיהוּ בְּאִתְגַלְּיָא וִיגַלֵּי מַה דְּאִיהוּ סָתִים.","אָמַר רַבִּי יוֹסֵי כַּמָּה אִית לָן לְאִתְמַשְּׁכָא גּוֹ גָּלוּתָא עַד הַהוּא זִמְנָא, וְכֹלָּא תָּלֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא כַּד יְתוּבוּן בִּתְיוּבְתָּא. אִי יִזְכּוּ וְאִי לָא יִזְכּוּ, כְּמָה דְאִתְמָּר בְּהַאי קְרָא דִּכְתִיב אֲנִי יְיָ בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ אֲחִישֶׁנָּה לא זָכוּ בְּעִתָּהּ.","אֲזְלוּ, עַד דְּהֲווּ אָזְלֵי, אָמַר רַבִּי יוֹסֵי אַדְכַּרְנָא הַשְׁתָּא דְּהָא בְּאֲתַר דָּא יָתִיבְנָא יוֹמָא חַד עִם אַבָּא, וְאָמַר לִי בְּרִי זַמִּין אַנְתְּ כַּד מָטוּן יוֹמָךְ לְשִׁיתִּין שְׁנִין לְאַשְׁכָּחָא בְּהַאי אֲתַר סִימָא דְּחָכְמְתָא עִלָּאָה, וְהָא זָכִינָא לְאִנּוּן יוֹמִין וְלָא אַשְׁכַּחְנָא, וְלָא יְדַעְנָא אִי הַנֵּי מִלִּין דְּקָאֲמָרָן אוֹ הַהִיא חָכְמְתָא דְּאִיהוּ אָמַר.","וְאָמַר לִי כַּד יִמְטוּן קוּלְפִין דְּנוּרָא גּוֹ טְהִירֵי יְדָךְ אִתְאֲבִיד מִינָךְ. אֲמִינָא לֵיהּ אַבָּא בַּמֶּה יְדַעְתְּ. אָמַר לִי בְּהַנֵּי תְּרֵין צִפּוֹרִין דְּאַעֲבָרוּ עַל רֵישָׁךְ יְדַעְנָא.","אַדְּהָכִי אִתְפְּרַשׁ רַבִּי יוֹסֵי וְעָאל גּוֹ מְעַרְתָּא חָדָא וְאַשְׁכַּח סִפְרָא חַד דְּהֲוָה נָעִיץ גּוֹ נוּקְבָא דְּטִנָּרָא בִּסְיָיפֵי מְעַרְתָּא, נָפַק בֵּיהּ.","כֵּיוָן דְּפָתַח לֵיהּ חָמָא שִׁבְעִין וּתְרֵין גְּלִיפִין דְּאַתְוָון דְּאִתְמְסָרוּ לְאָדָם הָרִאשׁוֹן וּבְהוּ הֲוָה יָדַע כָּל חָכְמְתָא דְּעִלָּאִין קַדִּישִׁין וְכָל אִנּוּן דְּבָתַר רֵיחַיָא דְּמִתְגַּלְגְּלָן בָּתַר פָּרוּכְתָּא גּוֹ טְהִירִין עִלָּאִין וְכָל אִנּוּן מִלִּין דְּזַמִּינִין לְמֵיתֵי לְעָלְמָא, עַד יוֹמָא דְּיֵקוּם עֲנָנָא דְּבִסְטַר מַעֲרָב וְיַחְשִׁיךְ עָלְמָא.","קָרָא לְרַבִּי יְהוּדָה וְשָׁרוּ לְמִלְעֵי בְּהַהוּא סִפְרָא, לָא סְפִיקוּ לְמִלְעֵי תְּרֵי אוֹ תְּלָתָא סִטְרִין דְּאִנּוּן אַתְוָון עַד דְּהֲווּ מִסְתַּכְּלִין בְּהַהִיא חָכְמָה עִלָּאָה, כֵּיוָן דְּמָטוּ לְמִלְעֵי בִּסְתִירוּ דְּסִפְרָא וּמִשְׁתָּעוּ דָּא עִם דָּא, נָפַק שְׁבִיבָא דְּאֶשָׁא וְעִלְעוּלָא דְּרוּחָא וּבָטַשׁ בִּידֵיהוֹן וְאִתְאֲבִיד מִנַּיְיהוּ. בָּכָה רַבִּי יוֹסֵי וְאָמַר דִּילְמָא חַס וְשָׁלוֹם חוֹבָה אִיהוּ גַּבָּן אוֹ דְּלָאו אֲנַן זַכִּין לְמִנְדַע לֵיהּ.","כַּד אָתוּן לְגַבֵּי דְרַבִּי שִׁמְעוֹן אִשְׁתָּעוּ לֵיהּ עוֹבָדָא דָא, אָמַר לוֹן דִּילְמָא בְּקֵץ מְשִׁיחָא דְּאִנּוּן אַתְוָון הֲוֵיתוּן מִשְׁתַּדְּלֵי, אָמְרוּ לֵיהּ דָּא לָא יַדְעִינָן דְּהָא כֹּלָּא אִתְנְשֵׁי מִינָן. אָמַר לוֹן רַבִּי שִׁמְעוֹן לֵית רְעוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּדָא דְּיִתְגְּלֵי כָּל כָּךְ לְעַלְמָא, וְכַד יְהֵא קָרִיב לְיוֹמֵי מְשִׁיחָא אֲפִילּוּ רַבְיֵי דְעַלְמָא זְמִינִין לְאַשְׁכָּחָא טְמִירִין דְּחָכְמְתָא וּלְמִנְדַע בֵּיהּ קִצִּין וְחוּשְׁבְּנִין, וּבְהַהוּא זִמְנָא אִתְגַּלְּיָא לְכֹלָּא הֲדָא הוּא דִכְתִיב (צפניה ג׳:ט׳) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים וְגו'. מַהוּ אָז. בְּזִמְנָא דְּתֵיקוּם כְּנֶסֶת יִשְׂרָאֵל מֵעַפְרָא וְיוֹקִים לָהּ קוּדְשָׁא בְּרִיךְ הוּא כְּדֵין אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם יְיָ וּלְעָבְדוֹ שְׁכֶם אֶחָד.","תָּא חֲזֵי, אַף עַל גַּב דְּאַבְרָהָם כְּתִיב בֵּיהּ וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה. וְכָל מַטְלָנוֹי הֲווּ לְדָרוֹמָא וְאִתְקַשַּׁר בֵּיהּ, לָא סָלִיק לְדוּכְתֵּיהּ כְּדְקָא יְאוּת עַד דְּאִתְיְלִיד יִצְחָק, כֵּיוָן דְּאִתְיְלִיד יִצְחָק אִסְתַּלַּק לְאַתְרֵיהּ וְאִיהוּ אִשְׁתַּתַּף בַּהֲדֵיהּ וְאִתְקַשְּׁרוּ דָּא בְּדָא."],[[1,"ביומוי דר' יוסי וכו':","בימיו של ר' יוסי היו פריצים, שהיו שודדים בהרים ביחד עם פריצי אומות העולם. וכשהיו מוצאים איש ותפסוהו להורגו, היו אומרים לו מה שמך, ואם היה יהודי, היו הולכים עמו ומוציאים אותו מבין ההרים. ואם היה אדם אחר שאינו יהודי, הרגו אותו. והיה אומר ר' יוסי, ובכל זאת, ראוים המה לבא לחיי עולם הבא. ע\"כ מדרש הנעלם."],[4,"וה' פקד את שרה כאשר אמר:","שכתוב למועד אשוב אליך כעת חיה ולשרה בן ולמדנו \u0003פקד את שרה,\u0004 פקידה נוהג בנוקבא. זכירה הוא בדכר, ועל כן כתיב בשרה. והויה פקד את שרה. והויה, ה\"ס הנוקבא דהיינו הוא ובית דינו, (כנ\"ל דף פ\"ב אות רפ\"א ע\"ש) \u0003כאשר אמר,\u0004 היינו שכתוב ויאמר שוב אשוב וגו' מכאן משמע מה שאמר הכתוב ויאמר שוב אשוב וגו' שנאמר ויאמר סתם, שהוא היה, דהיינו הנוקבא, (כנ\"ל דף מ\"ה אות מ'). ולא שליח אחר. דאם לא כן, איך נאמר כאן, וה' פקד את שרה כאשר אמר, היכן אמר."],[5,"ויעש ה' לשרה וגו':","ושואל, כיון שאמר, וה' פקד את שרה, למה לי. ויעש ה' לשרה. ומשיב, אלא כך למדנו, שפרי \u0003מעשיו\u0004 של הקב\"ה, הוא מאותו הנהר הנמשך ויוצא מעדן שהוא ז\"א, (כנ\"ל ב\"א דף רי\"א אות רמ\"ז) והוא נשמות הצדיקים, כלומר שהעשיה שלו הוא נשמות הצדיקים. והוא המזל שכל ברכות הטובות וגשמי ברכה נוזלים ממנו, ומשם יוצאים שכתוב להשקות את הגן, שהוא מזיל ומשקה ממעלה למטה. משום שבנים תלוים במזל הזה, ולא במקום אחר. \u0003מזל\u0004 ה\"ס דיקנא דא\"א, וכשז\"א מקבל ממנו המוחין נקרא גם הוא מזל."],[6,"ועל דא כתיב וכו':","ועל כן כתוב \u0003והוי\"ה\u0004 פקד את שרה, שכתוב רק פקידה, שה\"ס הנוקבא. ויעש \u0003הוי\"ה\u0004 לשרה, \u0003עשיה\u0004 שה\"ס בנים ונשמות הצדיקים שהם פרי מעשיו היא למעלה ממדרגה זו דפקידה, כמו שנתבאר שהוא תלוי במזל, וע\"כ כתוב כאן פקידה הנמשכת מהנוקבא, וכאן עשיה הנמשכת מז\"א. ומשום זה אמר הויה והויה, והכל אחד, בפקידה כתוב \u0003והויה\u0004 פקד, שה\"ס הוא ובית דינו, שפירושו הנוקבא (כנ\"ל דף פ\"ב אות רפ\"א) ובעשיה כתוב ויעש \u0003הויה,\u0004 שהוא ז\"א כמ\"ש שם."],[7,"ר' אלעזר פתח וכו':","ר\"א פתח ואמר, הנה נחלת ה' בנים שכר פרי הבטן. הנה נחלת ה', פירושו נחלה להתאחד בה' שלא יסור ממנו לעולם. כי אדם הזוכה לבנים בעולם הזה, זוכה בהם לכנוס למחיצתו \u0003של הקב\"ה\u0004 בעולם הבא. משום שאותו הבן שהניח האדם, שזכה בו בעולם הזה, הוא יזכהו לעולם הבא, וזוכה על ידו לכנוס בנחלת ה'."],[8,"מאן נחלת ה' וכו':","ושואל מהו נחלת ה'. ואומר שזו היא ארץ החיים, דהיינו הנוקבא, וכן קרא דוד המלך לארץ ישראל, שהיא ארץ החיים, \u0003נחלת ה'.\u0004 שכתוב כי גרשוני היום מהסתפח בנחלת ה' וגו'."],[8,"ובגין כך וכו':","ומשום זה אומר הכתוב הנה נחלת ה' בנים, מי מזכה את האדם בנחלת ה'. בנים מזכים אותו. אם זכה לבנים בעולם הזה, הם שכר פרי הבטן, שהם שכר והלק טוב בעולם הנצחי, כי בפרי בטן ההוא, זוכה על ידיהם האדם לעולם הנצחי."],[9,"תא חזי הנה וכו':","בוא וראה, הנה נחלת ה' בנים, פירושו, ירושה ונחלה מפרי מעשיו של הקב\"ה, היינו מעץ החיים, כי הקב\"ה נקרא עץ החיים. כי משם זוכה האדם לבנים, כמו שאתה אומר, ממני פריך נמצא. מה כתוב, אשרי הגבר אשר מלא את אשפתו מהם וגו' אשרי הוא בעולם הזה אשרי הוא בעולם הבא."],[10,"לא יבושו כי ידברו את אויבים בשער:","ושואל, מי הם האויבים בשער. ואומר אלו הם בעלי הדין. כי כשהנשמה יוצאת מעולם הזה, כמה הם בעלי הדין המועדים לפניו מטרם שיכנוס למקומו. \u0003בשער,\u0004 פירושו, באותו השער שנכנס דרך שם למקומו שם הם עומדים. והוא נצל מהם, משום שהניח משכנות בעולם הזה, דהיינו הבנים, ובשבילם יזכה בעולם הנצחי, ועל כן, לא יבושו כי ידברו את אויבים בשער."],[11,"ר' יהודה ור' יוסי וכו':","ר\"י ור' יוסי היו הולכים בדרך. אמר לו ר' יהודה לר' יוסי, פתח פיך ללמוד בתורה. שהרי השכינה נמצאת אצלך. כי כל זמן שעוסקים בתורה השכינה באה ומתחברת. וכל שכן כשהולכים בדרך, שהשכינה מקדמת עצמה ובאה, והולכת לפני בני אדם שזכו באמונתו של הקב\"ה."],[12,"פתח ר' יוסי וכו':","פתח ר\"י ואמר, אשתך כגפן פוריה בירכתי ביתך וגו' אשתך כגפן פוריה. פירושו, שכל זמן שהאשה היא בירכתי הבית ואינה יוצאת לחוץ היא צנועה, וראויה להוליד בנים כשרים. \u0003כגפך,\u0004 מה גפן אינה נטעת רק במינה, ולא במין אחר, כך אשה כשרה לא תעשה נטיעות. דהיינו בנים, מאדם אחר. מה גפן אין בו הרכבה מאילן אחר אף אשה כשרה כך. כלומר. אפילו זווג לבד לא קבלה מאחר."],[13,"חמי מה אגרה וכו':","ראה מה שכרה. בניך כשתילי זיתים. מה זיתים אין עלותיהם נופלים כל ימות השנה, וכולם קשורים תמיד באילן. כך, בניך כשתילי זיתים סביב לשלחניך, קשורים תמיד בך."],[14,"מה כתיב בתריה וכו':","מה כתוב אחריו, הנה כי כן יבורך גבר ירא ה'. ושואל מהו \u0003הנה כי כן\u0004 יבורך גבר, \u0003הנה כן\u0004 היה צריך לומר. ומשיב אלא לרבות דבר אחר שלמדים ממנה, שכל זמן שהשכינה היתה צנועה במקומה כראוי לה, כביכול, בניך \u0003כשתילי זיתים,\u0004 אלו הם ישראל כששורים בארץ ישראל, \u0003סביב לשלחנך,\u0004 שאוכלים ושותים ומקריבים קרבנות ושמחים לפני הקב\"ה, ומתברכים בשבילם, עליונים ותחתונים."],[15,"לבתר דשכינתא וכו':","אחר שיצאה השכינה ממקומה נגלו ישראל משלחן אביהם, ובאו בין העמים, וזועקים כל היום ואין מי שישגיח עליהם, חוץ מקב\"ה, שכתוב, ואף גם זאת בהיותם בארץ אויביהם וגו'. ואנו רואים, כמה קדושים עליונים, שמתו בגזרות קשות. וכל זה בשביל עונש התורה שלא קיימו ישראל בהיותם שורים בארץ הקודש."],[16,"חמי מה כתיב וכו':","ראה מה כתוב, תחת אשר לא עבדת את ה' אלקיך וגו'. מקרא זה הוא סוד. \u0003תחת אשר לא עבדת בשמחה,\u0004 בזמן שהכהנים היו מקריבים קרבנות ועולות וזה הוא בשמחה. \u0003ובטוב לבב,\u0004 אלו הם לוים, \u0003מרוב כל,\u0004 אלו הם ישראל, שהיו אמצעים בין כהנים ולוים, ומקבלים ברכות מכל הצדדים, מימין ומשמאל."],[17,"דכתיב הרבית וכו':","שכתוב, \u0003הרבית הגוי לו הגדלת השמחה\u0004 אלו הם הכהנים. \u0003שמחו לפניך כשמחת בקציר,\u0004 אלו הם ישראל, שהקב\"ה ברך להם תבואת השדה ונתנו מעשר מכל. \u0003כאשר יגילו בחלקם שלל,\u0004 אלו הם לוים שמקבלים מעשר מן הגרן."],[18,"ד\"א הרבית הגוי וכו':","פירוש אחר, \u0003הרבית הגוי,\u0004 אלו הם ישראל, שאמונתו של הקב\"ה עליהם כראוי. וה\"ס קו אמצעי, הכולל לב' הקוין ימין ושמאל כמ\"ש לפנינו. \u0003לו הגדלת השמחה,\u0004 זה הוא מדרגת ראש העליון, דהיינו חסד שנעשה לחכמה, שאברהם נתדבק בה, שנקרא \u0003גדול\u0004 ושמחה נמצאת בו. וה\"ס קו ימין, חסד."],[19,"שמחו לפניך בשעתא","וכו': \u0003שמחו לפניך,\u0004 בשעה שעלו להתדבק בך, בב' הבחינות, א) \u0003כשמחת בקציר,\u0004 זה הוא כנסת ישראל, דהיינו הנוקבא, שהיתה שמחה בקציר שלו, וה\"ס קו שמאל, כי קצירת השדה מהארת שמאל הוא. וקציר, פירושו תכלית הנרצה מעבודת השדה. ואומרו, \u0003בקציר שלו,\u0004 ה\"ס דבעלה אתעטר בה, והיא לא אתעטרת בבעלה. ב) היא \u0003כאשר יגילו בחלקים שלל.\u0004 כאשר יגילו שאר צבאות ומרכבות שלמטה מן הנוקבא, בזמן שמחלקים שלל וטורפים טרף בראש הכל, דהיינו רישא עלאה דאברהם אתדבק בו כנ\"ל, שה\"ס קו ימין חסד כנ\"ל, וזה שיעור הכתוב \u0003הרבית הגוי,\u0004 שהרבה והגדיל את ישראל, \u0003לו הגדלת השמחה,\u0004 ה\"ס קו ימין בבחינת ראש עליון כנ\"ל, וישראל \u0003שמחו לפניך,\u0004 בב' בחינות בימין ושמאל להיותם קו אמצעי הכולל ב' הקוין, א) \u0003כשמחת בקציר\u0004 שה\"ס קו שמאל ב) שישראל שמחים \u0003כאשר יגילו\u0004 צבאות המלאכים שבבי\"ע, בעת שראש העליון \u0003מחלק שלל\u0004 וטרף, שאז מקבלים כל התחתונים שבבי\"ע."],[20,"ר' יהודה פתח וכו':","ר\"י פתח ואמר, עת לעשות לה' הפרו תורתך. ושואל, עת לעשות לה' מהו. ואומר, אלא כבר בארוהו, אבל \u0003עת\u0004 זהו כנסת ישראל, דהיינו הנוקבא, שנקראת \u0003עת,\u0004 כמו שאתה אומר, ואל יבא בכל \u0003עת\u0004 אל הקדש, מהו ואל יבא בכל עת. הוא כמו שאתה אומר לשמרך מאשה זרה, וזה הוא ויקריבו לפני ה' אש זרה. כלומר, שגם הנוקבא דקליפות נקראת \u0003עת,\u0004 שהיא אשה זרה, אש זרה, וע\"כ אומר ואל יבא בכל עת אל הקדש, אלא \u0003בעת\u0004 דקדושה. \u0003מאי טעמא עת וכו':\u0004 ושואל, מהו הטעם שהנוקבא נקראת \u0003עת\u0004. ואומר משום שיש לה עת וזמן לכל, דהיינו כ\"ח עתים המובאים בקהלת ג', כדי להתקרב ולאור ולהתחבר עם ז\"א כראוי, כמו שאתה אומר, ואני תפלתי לך ה' עת רצון."],[21,"לעשות לה':","פירושו, כמו שכתוב ויעש דוד שם, שפירושו, שתקן הנוקבא הנקראת \u0003שם.\u0004 אף כן כל מי שעוסק בתורה הוא כאלו עשה ותקן את \u0003עת\u0004 הזו, שהיא הנוקבא, לחבר אותה בהקב\"ה. וכל כך למה, למה צריכים לעבוד ולתקן את הנוקבא. הוא משום \u0003דהפרו תורתך,\u0004 כי אלו לא הפרו תורתך, לא היה נמצא לעולם פירוד הקב\"ה מישראל. כי יחוד קוב\"ה ושכינתיה לא היה נפסק לעולם."],[22,"אמר ר' יוסי וכו':","אר\"י, כעין זה כתוב, אני ה' בעתה אחישנה. מהו \u0003בעתה\u0004 ואומר שהוא אותיות \u0003בעת ה'\u0004 שפירושו, בעת ש \u0003ה'\u0004 שהיא הנוקבא, תקום מעפר שלה, אז אחישנה. כלומר שמכחי תקום מעפר הגלות. ולא מכחה עצמה. אמר ר' יוסי, ועם כל זה, יום אחד נמצא כנסת ישראל בעפר הגלות, ולא יותר. דהיינו יומו של הקב\"ה, שהוא אלף שנה, כמ\"ש כי אלף שנים בעיניך כיום אתמול וגו'. והכונה הוא על אלף החמישי כמ\"ש לפנינו, כי אלף הרביעי לא היה שלם, שהיה חסר קע\"ב שנה. כי החורבן היה בשנת ג' אלפים תתכ\"ח."],[23,"אמר ר' יהודה וכו':","אר\"י, כך אמרו. אבל בא וראה, הסוד שלמדתי, בשעה שכנסת ישראל הגלתה ממקומה, אז האותיות של השם הקדוש, כביכול, נפרדו. שנפרדה \u0003ה\"א\u0004 מן \u0003וא\"ו\u0004 מהשם הויה. ובשביל שנפרדו, מה כתוב נאלמתי דומיה. משום שנסתלק \u0003וא\"ו\u0004 מן \u0003ה\"א,\u0004 והקול לא נמצא ואז הדבור נתאלם. פירוש. ז\"א ה\"ס ו' של הויה, ונקרא \u0003קול.\u0004 הנוקבא היא \u0003ה'\u0004 אחרונה של הויה, ונקראת \u0003דבור.\u0004 וכיון שהנוקבא שה\"ס \u0003ה'\u0004 נפרדה מן ה \u0003ו',\u0004 הרי היא נשארת כדבור בלי קול וע\"כ אומר הכתוב על זמן הגלות, נאלמתי דומיה."],[24,"ובגין כך היא שכיבת וכו':","ומשום זה היא שוכבת בעפר הגלות כל אותו היום של ה \u0003ה'.\u0004 ומי הוא. הוא אלף החמישי ואע\"פ שהקדימה לצאת לגלות מטרם שבא אלף החמישי, שה\"ס \u0003ה',\u0004 כי באלף הרביעי נחרב הבית, מ\"מ כיון שאינו אלף שלם אין אנו חושבים אותו כנ\"ל."],[25,"וכד ייתי אלף שתיתאה וכו':","וכאשר יבא אלף הששי, שהוא סוד ה \u0003ואו,\u0004 דהיינו היסוד שהוא מילוי ה \u0003ו'\u0004 שהוא ז\"א, אז ה \u0003ו'\u0004 יקים את ה \u0003ה',\u0004 שהיא הנוקבא, בזמן שש פעם עשר. וה \u0003ו'\u0004 עולה ב \u0003י,\u0004 משם הויה, שהיא חכמה. ואז \u0003ו'\u0004 יורדת ומשפעת ב \u0003ה'.\u0004"],[25,"","פירוש. כשז\"א יקבל מוחין שלימים מבחינת החכמה בקביעות, וישפיע אותם לנוקבא, אז תהיה הגאולה, וז\"א ה\"ס הו' של שם הויה. על שם שש הספירות שלו חג\"ת נה\"י שחסר ג\"ר, שהם כח\"ב. ואפילו כשיש לו מוחין דג\"ר, עדיין הוא חסר כח\"ב, אלא רק חג\"ת שלו עולים ומלבישים לכח\"ב, ונעשו חב\"ד, (כנ\"ל ב\"א דף ק\"כ ד\"ה אצבען) ואינם עוד ג\"ר אמתיים. וז\"ס מ\"ש בזהר רישא דמלכא בחסד וגבורה אתתקן. ונמצא אפילו בעת שיש לו ג\"ר אין לו יותר מו\"ק, אמנם נבחן, שכל קצה וקצה משש קצוות שלו השיג ג\"ר, וה\"ס המספר ששים, דהיינו שנבחן ג\"ר בכל קצה שלו. וכבר ידעת שיש ד' בחינות מוחין, שנקראים רוח נשמה חיה יחידה. שמוחין דקומת ז\"א, נק' רוח. ומוחין מבינה נקראים נשמה. ומוחין דחכמה נק' חיה. ומוחין דכתר נק' יחידה. וכן בכל אחד מאלו הד' יש ד' בחינות מוחין הללו. ומבחינת המספר, נבחנים מוחין דרוח לעשרות, שהם ששים, כי ז\"א ספירותיו בסוד עשרות. ומוחין דנשמה למאות, דהיינו שש מאות, כי בינה, ספירותיה הן בסוד מאות. ומוחין דחיה לאלפים, שהם ששת אלפים."],[25,"","וזה אמרו, \u0003ו' יוקים לה' בזמנא שית זמנין עשר.\u0004 שז\"א שנק' ו' יקים את ה \u0003ה'\u0004 שהיא הנוקבא, בזמן שיהיה לו מוחין דג\"ר בקביעות, הנבחנים \u0003לשית זמנין עשר,\u0004 כלומר שכל קצה שלו משיג ג\"ר ונעשה עשר ומבחינת עצם הספירות אינם אלא חג\"ת נה\"י החסרים ג\"ר כנ\"ל. והוא רק בעת אשר ו' \u0003סלקא לי'\u0004 שה \u0003ו'\u0004 שהוא ז\"א, יקבל מוחין מן ה \u0003י'\u0004 של הויה, שהוא חכמה. שספירותיה הן מאלפים, ויהיה במספר ששת אלפים. דהיינו שכל קצה מו\"ק שלו השיג בחינת החכמה, שהוא אלף. ואז \u0003ו' נחתא\u0004 ב \u0003ה',\u0004 שישפיע אלו המוחין דחכמה אל ה \u0003ה',\u0004 שהיא הנוקבא, ויקים לה מעפר הגלות."],[25,"","אמנם אין צריכים ששת אלפים שלמים, מפני שהחכמה עצמה מתפרטת גם כן לנרנח\"י, וכשמשיג נשמה מחכמה, שה\"ס מספר שש מאות מאלף הששי, מיד יתפתחון תרעי דחכמתא וכו' כמ\"ש בסמוך."],[26,"אשתלים וא\"ו גו עשר וכו':","כשנשלם ה \u0003ו',\u0004 שה\"ס ז\"א, מעשר, שש פעמים, שה\"ס ג\"ר דרוח, שמשיג כל קצה מו\"ק, ועתה באלף הששי שה\"ס חכמה, הן בחינת רוח החכמה, כנ\"ל. אז הם במספר ששים, להקים הנוקבא מעפר. ובכל ששים וששים שבאלף הששי, מתחזקת ה \u0003ה'\u0004 ונתעלית במדרגותיה להתחזק, ובשש מאות שנה לאלף הששי, דהיינו בעת שכל קצה משיג מוחין מבינה שספירותיה במאות, שהם שש מאות, כנ\"ל, שעתה הם נשמה דחכמה. דהיינו בינה דחכמה, יפתחו שערי החכמה למעלה, ומעיינות החכמה למטה. הג\"ר דבינה נבחנות לשערי החכמה וז\"ת דבינה נבחנות למעייני החכמה. ויתתקן העולם אז לכנוס לאלף השביעי, שה\"ס שלמות המלכות עצמה בסוד שבת, כאדם המתקן עצמו ביום הששי בבוא השמש כדי לכנוס בשבת, אף כאן כן. וסימנך, בשנת שש מאות שנה לחיי נח וגו' נבקעו כל מעיינות תהום רבה."],[27,"א\"ל ר' יוסי וכו':","אמר לו ר\"י, הרי זה יותר אריכות הזמן ממה שאמרו החברים, שהגלות של כנסת ישראל הוא רק יום אחד ולא יותר, שכתוב, נתנני שוממה כל היום דוה, והיינו בסוד יומו של הקב\"ה שהוא אלף שנה כנ\"ל, אמר לו, כך למדתי מאבי בסוד האותיות של השם הקדוש הויה, ובימי שנות העולם ובימי בראשית, והכל סוד אחד הוא."],[28,"וכדין יתחזי קשתא וכו':","ואז יהיה נראה הקשת בעננים בצבעים מאירים, כמו אשה המפארת את עצמה לבעלה. כי קשת ה\"ס הנוקבא, (כנ\"ל נח צ\"ה בד\"ה מאי) שכתוב וראיתיה. לזכור ברית עולם, וכבר בארוה ויפה היא, אבל וראיתיה, פירושו, בצבעים מאירים כראוי. פירוש, כי מטרם הגאולה אין בקשת אלא ג' צבעים: לבן, אדום, ירוק, שה\"ס יה\"ו, ובחינת עצמה חסרה שם. (כנ\"ל פ' נח דף צ\"ה ד\"ה פירוש ע\"ש.) אבל בעת הגאולה יאירו כל ד' הצבעים בקשת, כי גם בחינתה עצמה תאיר בשוה עם ג' גוונים דז\"א. בסוד והיה אור הלבנה כאור החמה."],[29,"וכדין לזכור וכו':","ואז נאמר, \u0003לזכור ברית עולם.\u0004 מהו ברית עולם. הוא כנסת ישראל, דהיינו הנוקבא, שהיא ברית, כמו שאתה אומר והיתה לאות ברית."],[30,"כד יתער וא\"ו וכו':","כאשר ה \u0003ו',\u0004 שהוא ז\"א, יתעורר אל ה \u0003ה',\u0004 שהיא הנוקבא, אז אותות עליונים יבאו בעולם, ובני ראובן עתידים לעשות מלחמות בכל העולם. וכנסת ישראל, הקב\"ה יקים אותה מעפר הגלות, ויזכור אותה."],[31,"וישתכח קב\"ה וכו':","והקב\"ה ימצא אצלה בגלות באלף הששי כחשבון, וי\"ו, דהיינו שכופל עם אות \u0003ו'\u0004 על המילוי שלו שהוא \u0003י'\u0004 ואח\"כ כופל עם המילוי \u0003י'\u0004 את אות \u0003ו',\u0004 כזה \u0003ו'\u0004 פעמים המילוי \u0003י',\u0004 נעשה ה \u0003ו'\u0004 ששים, \u0003י'\u0004 פעמים \u0003ו'\u0004 שהיא ששים, נעשה ה \u0003ו'\u0004 שש מאות. דהיינו שש מאות באלף הששי. ואז יקום ויפקד העולם, שהוא הנוקבא, לעשות נקמות, ומי שהוא שפל יתרומם."],[32,"א\"ל ר' יוסי וכו':","אמר לו ר\"י, יפה אמרת, משום שבארת בסוד האותיות של שם הויה, ואין לנו להעיר חשבונות וקצים אחרים, שאינם בסוד האותיות, כי בספרו של ר' ייבא סבא מצאנו דרוש כעין חשבון זה שלך, שכתוב, אז תרצה הארץ את שבתותיה, והוא סוד ה \u0003ו',\u0004 כלומר שלא יגולה רצון זה אל הארץ שהיא הנוקבא, אלא בסוד השלמות של ה \u0003ו'\u0004 כמו שביאר ר' יהודה, שכתוב, וזכרתי את בריתי יעקוב, עם \u0003ו',\u0004 וזהו \u0003וו,\u0004 כי כשאומרים \u0003ו' נשמע עוד ו'\u0004 בתוכו, אשר \u0003ו'\u0004 ראשונה רומזת על יעקב. שהוא ת\"ת, ו \u0003ו'\u0004 השניה רומזת על יסוד דז\"א שה\"ס ה \u0003ו'\u0004 שביעקוב הנ\"ל, \u0003כלא כחדא,\u0004 הכל כאחד, כלומר, שביעקוב עם \u0003ו',\u0004 נמצא ת\"ת ויסוד שהם אחד, ועל כן אומר הכתוב, \u0003אזכור,\u0004 ואח\"כ \u0003והארץ אזכור\u0004 שהיא כנסת ישראל, דהיינו הנוקבא. פירוש. שמקודם לכן כתוב וזכרתי את בריתי יעקב ואת בריתי יצחק ואף את בריתי אברהם. והיה די שיסיים והארץ אזכור, ולמה מסיים אזכור והארץ אזכור. והוא ללמדנו כי תחילה צריך ז\"א לקבל שלמותו בעצמו, שה\"ס ה \u0003ו'\u0004 וה\"ס אברהם יצחק ויעקב, וע\"כ כתוב עליו במיוחד אזכור, ואח\"כ והארץ אזכור. כי ה \u0003ו'\u0004 יקים את ה \u0003ה'.\u0004 וגם ה \u0003ה'\u0004 תשיג את שלמותה. \u0003תרצה\u0004 פירושו, \u0003תתרעי ארעא לגבי קב\"ה.\u0004 שהארץ תתרצה אל הקב\"ה, והוא יקום אותה. דהיינו כמו שהיתה ה \u0003ת'\u0004 של תרצה צרויה, וה \u0003ר\u0004 קמוצה. כי אין לפרש את הרצון בהנוקבא עצמה, כי אין הדבר תלוי ברצונה אלא ברצון ז\"א. (ע\"כ דברי ר' ייבא סבא)."],[33,"אבל יומא חד וכו':","אבל יום אחד, שאמרו החברים על זמן הגלות, ודאי הוא, שהכל טמון ומסתתר לפני הקב\"ה, והכל נמצא ומתגלה, בסוד האותיות של השם הקדוש, שהרי הגלות שה\"ס ההסתר, גילה לנו ר' ייסא באלו האותיות, (דהיינו דאתפרשא \u0003ה'\u0004 מן \u0003ו'\u0004 כנ\"ל באות תמ\"ב) ועתה נתגלה באלו האותיות סוד הגאולה, דהיינו שתלויה בשלמות ה \u0003ו'\u0004 של השם הויה."],[34,"א\"ל ת\"ח דאפילו וכו':","אמר לו בוא וראה, שאפילו כשנפקדה שרה לא נפקדה ממדרגה זו דפקידה שהיא הנוקבא, ה\"ת דהויה, אלא בסוד ה \u0003ו',\u0004 שכתוב, \u0003ו\u0004 הויה פקד את שרה, כי והויה, יורה הוא ובית דינו, הוא ה\"ס ז\"א סוד ה \u0003ו',\u0004 ובית דינו ה\"ס הנוקבא. הרי שאפילו פקידת שרה היתה ב \u0003ו'\u0004 דהויה. משום שהכל הוא בסוד ה \u0003ו'\u0004 ובזה כלול הכל, דהיינו שהכל נסתר ב \u0003ו',\u0004 ובו מתגלה הכל, שהכל נגלה על ידי שלמות ה \u0003ו'.\u0004 משום שכל דבר שהוא סתום, הוא מגלה כל סתום, ולא יבא מי שהוא מגולה, ויגלה מה שהוא סתום. פירוש. האדם נברא בכל רע ושפלות. כמו שכתוב עייר פרא אדם יולד, וכל כליו שבגופו, דהיינו החושים והמדות ומכ\"ש המחשבה, משמשים לו רק רע ואפסיות כל היום. והזוכה להדבק בו יתברך, אין השי\"ת בורא לו כלים אחרים במקומם, שיהיו כדאים וראוים לקבל בתוכם, שפע הרוחני הנצחי המיועד לו, אלא אותם הכלים השפלים, שתשמישם עד עתה היה רע ומתועב, מתהפכים ונעשים לו כלי קבלה לכל נועם ורוך הנצחי. ולא עוד, אלא כל כלי שחסרונותיו היו גדולים ביותר נעשו עתה לחשובים ביותר כלומר שמדת גילוים גדולה ביותר, עד שאם היה לו איזה כלי בגופו בלי שום חסרון, נעשה לו עתה כמו דבר מיותר שאינו משמש לו כלום. ודומה לכלי עץ וחרס שכל שחסרונו, דהיינו חקיקתו, גדול יותר, כן מדת קבולו וחשיבותו גדולה יותר. וכבר דברנו מזה לעיל (בהקדמת הזהר דף קכ\"ב ד\"ה פרוש ע\"ש) וכזה נוהג ג\"כ בעולמות העליונים שאין שום גילוי מושפע לעולם אלא ע\"י בחינות סתומות, ולפי שיעור הסתימות שבמדרגה כן שיעור הגילוים שבה שמשפעת לעולם, ואם אין בה סתימה לא תוכל להשפיע כלום. וכמו שיסד האריז\"ל בזמירות יום שבת, במלין סתימין תגלון פתגמין וזה אמרו, \u0003בגין דכל מלה דאיהי סתימא איהי גלי כל סתים,\u0004 והיינו סוד ה \u0003ו'\u0004 של שם הויה, שה\"ס ז\"א, שהמוחין שלו הם תמיד בבחינת חסדים מכוסים ונעלמים מהארת חכמה, (כנ\"ל ב\"א דף רנ\"ב ד\"ה ורזא) וע\"כ הוא מיועד לגלות גאולה השלמה, בסוד \u0003ו'\u0004 יוקים ל \u0003ה'\u0004 כנ\"ל. כי לפי שיעור הסתימה והכיסוי שבו, כן יהיה לעתיד מדת גילויו כנ\"ל. אבל \u0003ולא אתי מאן דאיהו באתגליא ויגלי מה דאיהו סתום,\u0004 דהיינו סוד \u0003ה'\u0004 אחרונה שבשם הויה, שה\"ס הנוקבא, שבה החסדים מתגלים וכל בחינת גילוי חכמה שבעולמות רק ממנה באה, (כנ\"ל ב\"א דף רנ\"ב ד\"ה ורזא) ולפי שאין בה סתימה. ע\"כ לא תוכל לגלות מה שהוא סתום, דהיינו הגאולה. ואע\"פ שיש סתימות גם בהנוקבא חוץ מזה, עם כל זה אינן מספיקות לגילוי הגדול הזה, של גאולה השלמה, כי לפי גודל הגילוי כן מוכרח להיות מדת הסתימה כנ\"ל."],[35,"א\"ר יוסי וכו':","אר\"י, כמה יש לנו להמשך בגלות עד אותו הזמן, ועל הכל תלה הקב\"ה, את הגאולה, אם ישובו בתשובה, בין אם יזכו לגאולה ובין אם לא יזכו לגאולה, פירושו, על ידי תשובה, או לא יעשו תשובה. כמו שנאמר במקרא הזה, שכתוב אני ה' בעתה אחישנה, זכו, אם יעשו תשובה אחישנה, לא זכו, שלא יעשו תשובה, \u0003בעתה.\u0004"],[36,"אזלו עד וכו':","הלכו. בעוד שהיו הולכים, אמר ר' יוסי, נזכרתי עתה, אשר במקום הזה, ישבתי פעם עם אבי, ואמר לי: בני, כשימיך יגיעו לששים שנה, עתיד אתה למצוא במקום הזה, אוצר של חכמה העליונה. וכבר זכיתי לימים אלו, ועוד לא מצאתי כלום, ואיני יודע, אם אפשר אלו החידושים שאמרתי, הוא אותה החכמה שאמר לי שאמצא."],[37,"ואמר לי כד וכו':","ואמר לי, כאשר יגיעו הכאות של אש בכפות ידיך. תהיה החכמה אבודה ממך. אמרתי לו: אבי במה ידעת זה. אמר לי: באלו ב' צפורים שעברו על ראשך, אני יודע את זה."],[38,"אדהכי אתפרש וכו':","בינתים נפרש ר' יוסי מר' יהודה, ונכנס תוך מערה אחת, ומצא ספר אחד שהיה תקוע תוך נקב שבאבן, בסוף המערה, לקחו ויצא עמו."],[39,"כיון דפתח וכו':","כיון שפתח את הספר, ראה, ע\"ב חקיקות אותיות, שנמסרו לאדם הראשון, ועמהם היה יודע כל החכמה של עליונים הקדושים, וכל אלו הקליפות שלאחר הריחים, שמתגלגלים אחר הפרוכת המכסה על אורות העליונים. וכל הדברים העתידים לבא לעולם, עד היום שיקום ענן שבצד מערב, - ויחשיך העולם. \u0003נצח והוד\u0004 מכונים ריחים ורכב, שהם שוחקות מן לצדיקים, ליסוד ומלכות, הנק' צדיק וצדק. ויש קליפות נגד שניהם, אבל עיקר הקליפות הם כנגד הוד שנקרא \u0003ריחים.\u0004 וז\"ש \u0003וכל אינון דבתר ריחיא,\u0004 אמנם מקום עמידתם אינם באצילות, כי שם נאמר, לא יגורך רע. אלא שעומדים אחר הפרכת, דהיינו אחר הפרסא שמתחת האצילות, המפסקת בין אצילות לבי\"ע. שהם נמצאים בבי\"ע."],[40,"קרא לר' יהודה וכו':","קרא לר\"י, והתחילו ללמוד באותו הספר. לא הספיקו, ללמוד שנים או שלשה עמודים בספר, וכבר היו מסתכלים בחכמה עליונה. כיון שהגיעו ללמוד בנסתרות שבספר, ודברו זה עם זה, יצאה להבת אש ורוח סערה, והכה בידיהם, ונאבד הספר מהם."],[40,"בכה ר' יוסי וכו':","בכה ר\"י ואמר, אולי יש בנו עון, או שאין אנו כדאים לדעת אותו."],[41,"כד אתון וכו':","כשבאו לפני ר' שמעון וספרו לו המעשה. אמר להם, אולי בקץ משיח שבאלו האותיות היתם עוסקים. אמרו לו, אין אנו יודעים, כי הכל נשכח ממנו."],[41,"אמר לון ר\"ש וכו':","אמר להם ר' שמעון, אין רצונו של הקב\"ה בזה, שיתגלה יותר מדאי לעולם, וכשיהיה קרוב לימות המשיח אפילו תנוקות שבעולם עתידים למצוא סודות החכמה, ולדעת בהם קצים וחשבונות של הגאולה, ובאותו הזמן תגלה לכל. וז\"ש כי אז אהפוך אל עמים וגו', מהו אז. היינו בזמן שכנסת ישראל תקום מעפר, ויקום אותה הקב\"ה, אז אהפוך אל עמים וגו'."],[42,"ת\"ח אע\"ג וכו':","בוא וראה, אף על פי שכתוב באברהם, ויסע אברם הלוך ונסוע הנגבה, וכל נסיעותיו היו לצד דרום, שהוא ימין, דהיינו חסד. ונקשר בו, עכ\"ז, לא נתעלה למקומו כראוי, עד שנולד יצחק. כיון שנולד יצחק נתעלה למקומו, לצפון לצד שמאל, ואברהם נשתתף עמו ונתקשרו זה בזה. שמתוך השתתפותם והתכללותם זה בזה נשלמו שניהם."]],[[0,"","הֵמָּה הַגִּבֹּרִים אֲשֶׁר מֵעוֹלָם - שֶׁאֵין גִּבּוֹר וּפָרִיץ וְעָרִיץ כְּמוֹ הַמַּמְזֵר. אַנְשֵׁי הַשֵּׁם - שֶׁהַכֹּל יַכִּירוּ לִקְרוֹת הַשֵּׁם הַיָּדוּעַ מַמְזֵר. שֶׁכֵּיוָן שֶׁרוֹאִים מַעֲשָׂיו שֶׁהוּא פָּרִיץ וְעָרִיץ וְגִבּוֹר, הַכֹּל יִקְרָאוּהוּ אוֹתוֹ שֵׁם. וּמַה שֶּׁאָמַר רַבִּי שִׁמְעוֹן, הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בְּאוֹתוֹ הַוָּלָד - אֵין לְךְ רָשָׁע בָּעוֹלָם מֵאוֹתָם הָרְשָׁעִים הַיּוֹצְאִים לָעוֹלָם שֶׁאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מְעַיֵּן בּוֹ וְרוֹאֶה אִם אוֹתוֹ הַגּוּף יַנִּיחַ בֵּן צַדִּיק וְכָשֵׁר, אוֹ שֶׁיַּצִּיל לְאָדָם מִיִּשְׂרָאֵל מִמִּיתָה מְשֻׁנָּה, אוֹ שֶׁיַּעֲשֶׂה טוֹבָה אַחַת, וּבִשְׁבִיל כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹצִיאוֹ לָעוֹלָם."],[1,"","בִּימֵי רַבִּי יוֹסֵי הָיוּ אוֹתָם פָּרִיצִים שֶׁהָיוּ שׁוֹדְדִים בֶּהָרִים עִם פָּרִיצֵי אֻמּוֹת הָעוֹלָם, וּכְשֶׁמּוֹצְאים בֶּן אָדָם וְתוֹפְסִים אוֹתוֹ לְהָרְגוֹ, הָיוּ אוֹמְרִים לוֹ: מַה שִּׁמְךְ? אִם הָיָה יְהוּדִי - הָיוּ הוֹלְכִים עִמּוֹ וּמוֹצִיאִים אוֹתוֹ מִן הֶהָרִים, וְאִם הָיָה אִישׁ אַחֵר - הוֹרְגִים אוֹתוֹ. (והרי) וְהָיָה אוֹמֵר רַבִּי יוֹסֵי, רְאוּיִים אֵלּוּ בְּכָל זֶה לְהִכָּנֵס לָעוֹלָם הַבָּא."],[2,"","שָׁנוּ רַבּוֹתֵינוּ, שְׁלֹשָׁה דְבָרִים הַלָּלוּ אֵינָם בָּאִים לָעוֹלָם אֶלָּא בְקוֹלוֹת: קוֹל חַיָּה, שֶׁכָּתוּב (בראשית ג) בְּעֶצֶב תֵּלְדִי בָנִים, וְכָתוּב (שם ל) וַיִּשְׁמַע אֵלֶיהָ אֱלֹהִים. קוֹל גְּשָׁמִים, שֶׁכָּתוּב (תהלים כט) קוֹל ה' עַל הַמָּיִם, וְכָתוּב (מלכים א יח) כִּי קוֹל הֲמוֹן הַגָּשֶׁם. קוֹל תְּחִיַּת הַמֵּתִים, שֶׁכָּתוּב (ישעיה מ) קוֹל קוֹרֵא בַּמִּדְבָּר. מַה צָּרִיךְ כָּאן קוֹל בַּמִּדְבָּר אֶלָּא,? אָמַר רַבִּי זְרִיקָא, אֵלּוּ אוֹתָם קוֹלוֹת לְעוֹרֵר מֵתֵי מִדְבָּר. וּמִכָּאן שֶׁהוּא הַדִּין לְכָל הָעוֹלָם. אָמַר רַבִּי יוֹחָנָן, הֲרֵי שָׁנִינוּ, כְּשֶׁנִּכְנַס אָדָם לַקֶּבֶר, נִכְנַס בְּקוֹלוֹת. כְּשֶׁיָּקוּמוּ בִּתְחִיַּת הַמֵּתִים אֵינוֹ דִין שֶׁיָּקוּמוּ בְּקוֹלֵי קוֹלוֹת?"],[3,"","אָמַר רַבִּי יַעֲקֹב, עֲתִידָה בַּת קוֹל לִהְיוֹת מִתְפּוֹצֶצֶת בְּבָתֵּי קְבָרוֹת וְאוֹמֶרֶת: (ישעיה כו) הָקִיצוּ וְרַנְּנוּ שֹׁכְנֵי עָפָר. וַעֲתִידִים לִחְיוֹת בְּטַל שֶׁל אוֹר גָּדוֹל שֶׁל מַעְלָה, שֶׁכָּתוּב (שם) כִּי טַל אוֹרוֹת טַלֶּךְ וָאָרֶץ רְפָאִים תַּפִּיל. אָמֵן כֵּן יְהִי רָצוֹן. עד כאן מדרש הנעלם."],[4,"","וַה' פָּקַד אֶת שָׂרָה כַּאֲשֶׁר אָמָר, שֶׁכָּתוּב לַמּוֹעֵד אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וּלְשָׂרָה בֵן. וְשָׁנִינוּ, פָּקַד אֶת שָׂרָה - פְּקִידָה לִנְקֵבָה, זְכִירָה לְזָכָר. וּמִשּׁוּם כָּךְ וַה' פָּקַד אֶת שָׂרָה. כַּאֲשֶׁר אָמָר, שֶׁכָּתוּב שׁוֹב אָשׁוּב אֵלֶיךְ כָּעֵת חַיָּה וְגוֹ'. מִכָּאן מַשְׁמָע שֶׁאָמַר וַיֹּאמֶר שׁוֹב אָשׁוּב אֵלֶיךְ, וַיֹּאמֶר סְתָם, שֶׁהוּא הָיָה וְלֹא שָׁלִיחַ אַחֵר."],[5,"","וַיַּעַשׂ ה' לְשָׂרָה וְגוֹ'. כֵּיוָן שֶׁאָמַר וַה' פָּקַד אֶת שָׂרָה, מַהוּ וַיַּעַשׂ ה' לְשָׂרָה? אֶלָּא כָּךְ שָׁנִינוּ, שֶׁפְּרִי מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מֵעֵדֶן הוּא, וְהוּא נִשְׁמוֹת הַצַּדִּיקִים, וְהוּא הַמַּזָּל שֶׁכָּל הַבְּרָכוֹת הַטּוֹבוֹת וְגִשְׁמֵי בְרָכָה נוֹזְלִים מִמֶּנּוּ וּמִשָּׁם יוֹצְאִים, שֶׁכָּתוּב לְהַשְׁקוֹת אֶת הַגָּן. שֶׁהוּא מַזִּיל וּמַשְׁקֶה מִלְמַעְלָה לְמַטָּה מִשּׁוּם שֶׁבָּנִים בַּמַּזָּל הַזֶּה תְּלוּיִים, וְלֹא בְמָקוֹם אַחֵר. וְעַל זֶה כָּתוּב וַה' פָּקַד אֶת שָׂרָה, פְּקִידָה בִּלְבַדָּהּ."],[6,"","וַיַּעַשׂ ה' לְשָׂרָה, עֲשִׂיָּה הִיא לְמַעְלָה מִן הַדַּרְגָּה הַזּוֹ, כְּמוֹ שֶׁנֶּאֱמַר שֶׁבְּמַזָּל זֶה תָּלוּי, וְעַל זֶה כָּאן פְּקִידָה וְכָאן עֲשִׂיָּה. וְלָכֵן אָמַר ה' וַה', וְהַכֹּל אֶחָד."],[7,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (תהלים קכז) הִנֵּה נַחֲלַת ה' בָּנִים שָׂכָר פְּרִי הַבָּטֶן. הִנֵּה נַחֲלַת ה', חֵלֶק לְהֵאָחֵז בַּה' שֶׁלֹּא יִתְבַּטֵּל מִמֶּנָּה לְעוֹלָמִים. שֶׁבֶּן אָדָם שֶׁזּוֹכֶה לְבָנִים בָּעוֹלָם הַזֶּה, זוֹכֶה בָהֶם לְהִכָּנֵס לַפַּרְגּוֹד לָעוֹלָם הַבָּא, מִשּׁוּם שֶׁאוֹתוֹ הַבֵּן שֶׁהִשְׁאִיר בֶּן הָאָדָם וְזוֹכֶה בּוֹ בָּעוֹלָם הַזֶּה, הוּא יְזַכֶּה אוֹתוֹ לָעוֹלָם הַבָּא, וְזוֹכֶה לְהִכָּנֵס בּוֹ לְנַחֲלַת ה'. מַה זֶּה נַחֲלַת ה'? זוֹ אֶרֶץ הַחַיִּים. וְכָךְ קָרָא לָהּ אֶת אֶרֶץ יִשְׂרָאֵל, שֶׁהִיא אֶרֶץ הַחַיִּים."],[8,"","דָּוִד הַמֶּלֶךְ (קרא לה) נַחֲלַת ה', שֶׁכָּתוּב (שמואל א כו) כִּי גֵרְשׁוּנִי הַיּוֹם מֵהִסְתַּפֵּחַ בְּנַחֲלַת ה' לֵאמֹר לֵךְ עֲבֹד אֱלֹהִים אֲחֵרִים, וּמִשּׁוּם כָּךְ הִנֵּה נַחֲלַת ה' בָּנִים. מִי מְזַכֶּה אֶת הָאִישׁ הַזֶּה? בָּנִים. אִם זוֹכֶה בָהֶם בָּעוֹלָם הַזֶּה - שָׂכָר פְּרִי הַבָּטֶן. שָׂכָר וְחֵלֶק טוֹב בְּאוֹתוֹ עוֹלָם בְּאוֹתוֹ פְּרִי מֵעָיו הוּא שֶׁזּוֹכֶה בֶּן אָדָם בְּאוֹתוֹ עוֹלָם בָּהֶם."],[9,"","בֹּא רְאֵה, הִנֵּה נַחֲלַת ה' בָּנִים, יְרֻשָּׁה וְחֵלֶק שֶׁל פֵּרוֹת שֶׁל מַעֲשֵׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מִלְמַעְלָה הוּא מֵעֵץ הַחַיִּים, שֶׁהֲרֵי מִשָּׁם זוֹכֶה בֶּן אָדָם לְבָנִים, כְּמוֹ שֶׁנֶּאֱמַר (הושע יד) מִמֶּנִּי פֶּרְיְךְ נִמְצָא. מַה כָּתוּב? (תהלים קכז) אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לֹא יֵבֹשׁוּ וְגוֹ'. אַשְׁרֵי בָּעוֹלָם הַזֶּה, וְאַשְׁרֵי בָּעוֹלָם הַבָּא."],[10,"","לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר, מִי הָאוֹיְבִים בַּשַּׁעַר? אֵלּוּ בַּעֲלֵי הַדִּינִים. שֶׁכַּאֲשֶׁר נְשָׁמָה יוֹצֵאת מֵהָעוֹלָם הַזֶּה, כַּמָּה הֵם בַּעֲלֵי הַדִּינִים שֶׁמְּזֻמָּנִים לְפָנֶיהָ עַד שֶׁלֹּא תִכָּנֵס לַמָּקוֹם בַּשַּׁעַר בְּאוֹתוֹ שַׁעַר שֶׁתִּכָּנֵס לְשָׁם, מִשּׁוּם שֶׁהִשְׁאִיר מַשְׁכּוֹנוֹת בָּעוֹלָם הַזֶּה וּבִגְלָלָם יִזְכֶּה בְּאוֹתוֹ עוֹלָם. וְעַל זֶה לֹא יֵבֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשָּׁעַר."],[11,"","רַבִּי יְהוּדָה וְרַבִּי יוֹסִי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יְהוּדָה לְרַבִּי יוֹסִי, פְּתַח פִּיךְ וְדַבֵּר בַּתּוֹרָה, שֶׁהֲרֵי הַשְּׁכִינָה נִמְצֵאת אֶצְלְךְ, שֶׁבְּכָל זְמַן שֶׁבְּדִבְרֵי תוֹרָה מְדַבְּרִים, בָּאָה הַשְּׁכִינָה וּמִתְחַבֶּרֶת, וְכָל שֶׁכֵּן בַּדֶּרֶךְ, שֶׁשְּׁכִינָה מַקְדִּימָה וּבָאָה וְהוֹלֶכֶת לִפְנֵי בְּנֵי אָדָם שֶׁזּוֹכִים בֶּאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא."],[12,"","פָּתַח רַבִּי יוֹסִי וְאָמַר, (שם) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךְ. אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה - כָּל זְמַן שֶׁהָאִשָּׁה בְּיַרְכְּתֵי הַבַּיִת וְלֹא יוֹצֵאת הַחוּצָה, הִיא צְנוּעָה וּרְאוּיָה לְהוֹלִיד בָּנִים כְּשֵׁרִים. כְּגֶפֶן - מַה גֶּפֶן לֹא נִנְטַעַת אֶלָּא בְּמִינָהּ וְלֹא בְּמִין אַחֵר, כָּךְ אִשָּׁה כְּשֵׁרָה לֹא תַעֲשֶׂה נְטִיעוֹת עִם אִישׁ אַחֵר; מַה גֶּפֶן אֵין בָּהּ הַרְכָּבָה מֵעֵץ אַחֵר, אַף כָּךְ אִשָּׁה כְּשֵׁרָה גַּם כָּךְ."],[13,"","רְאֵה מַה שְּׂכָרָהּ: בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים. מַה זֵּיתִים אֵין עֲלֵיהֶם נוֹפְלִים כָּל יְמוֹת הַשָּׁנָה וְכֻלָּם קְשׁוּרִים (בסר) תָּמִיד, אַף כָּךְ בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים סָבִיב לְשֻׁלְחָנֶךְ."],[14,"","מַה כָּתוּב אַחֲרָיו? הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר יְרֵא ה'. מַה זֶּה הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר? הִנֵּה כֵן הָיָה צָרִיךְ (לכתב) ! אֶלָּא לְרַבּוֹת דָּבָר אַחֵר שֶׁלָּמַדְנוּ זֶה מִמֶּנָּה, שֶׁכָּל זְמַן שֶׁהַשְּׁכִינָה הָיְתָה צְנוּעָה בִּמְקוֹמָהּ כָּרָאוּי לָהּ כִּבְיָכוֹל - בָּנֶיךְ כִּשְׁתִילֵי זֵיתִים, אֵלּוּ יִשְׂרָאֵל כְּשֶׁשְּׁרוּיִים בָּאָרֶץ. סָבִיב לְשֻׁלְחָנֶךְ - שֶׁאוֹכְלִים וְשׁוֹתִים וּמַקְרִיבִים קָרְבָּנוֹת וּשְׂמֵחִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים בִּגְלָלָם."],[15,"","אַחַר שֶׁיָּצְאָה הַשְּׁכִינָה וְגָלוּ יִשְׂרָאֵל מֵעַל שֻׁלְחַן אֲבִיהֶם, וְהֵם בֵּין הָעַמִּים וְצוֹוְחִים כָּל יוֹם, וְאֵין מִי שֶׁיַּשְׁגִּיחַ בָּהֶם פְּרָט לַקָּבָּ\"ה, שֶׁכָּתוּב (ויקרא כו) וְאַף גַּם זאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם וְגוֹ'. וְרָאִינוּ כַּמָּה קְדוֹשִׁים עֶלְיוֹנִים מֵתוּ בִּגְזֵרוֹת תַּקִּיפוֹת, וְכָל זֶה מִשּׁוּם עֹנֶשׁ הַתּוֹרָה שֶׁלֹּא קִיְּמוּ יִשְׂרָאֵל כְּשֶׁהָיוּ שְׁרוּיִים בָּאָרֶץ הַקְּדוֹשָׁה."],[16,"","רְאֵה מַה כָּתוּב, (דברים כח) תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךְ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. פָּסוּק זֶה הוּא סוֹד. תַּחַת אֲשֶׁר לֹא עָבַדְתָּ בְּשִׂמְחָה, בִּזְמַן שֶׁכֹּהֲנִים הָיוּ מַקְרִיבִים קָרְבָּנוֹת וְעוֹלוֹת, וְזוֹ הִיא בְּשִׂמְחָה. וּבְטוּב לֵבָב - אֵלּוּ הַלְוִיִּם. מֵרֹב כֹּל - אֵלּוּ יִשְׂרָאֵל שֶׁהָיוּ אֶמְצָעִיִּים בֵּינֵיהֶם וְנָטְלוּ בְרָכוֹת מִכָּל הַצְּדָדִים,"],[17,"","שֶׁכָּתוּב (ישעיה ט) הִרְבִּיתָ הַגּוֹי לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה. אֵלּוּ הַכֹּהֲנִים. שָׂמְחוּ לְפָנֶיךְ כְּשִׂמְחַת בַּקָּצִיר - אֵלּוּ יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בֵּרַךְ לָהֶם אֶת תְּבוּאַת הַשָּׂדֶה וְנוֹתְנִים מַעֲשֵׂר מִן הַכֹּל. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל - אֵלּוּ לְוִיִּם שֶׁנּוֹטְלִים מַעֲשֵׂר מִתּוֹךְ הַגֹּרֶן."],[18,"","דָּבָר אַחֵר הִרְבִּיתָ הַגּוֹי - אֵלּוּ יִשְׂרָאֵל שֶׁאֱמוּנַת הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם כָּרָאוּי. לוֹ הִגְדַּלְתָּ הַשִּׂמְחָה - זוֹהִי דַּרְגַּת הָרֹאשׁ הָעֶלְיוֹן שֶׁל אַבְרָהָם שֶׁנִּדְבַּק בָּהּ, שֶׁהוּא גָדוֹל, וְחֶדְוָה נִמְצֵאת בּוֹ."],[19,"","שָׂמְחוּ לְפָנֶיךְ - בְּשָׁעָה שֶׁעוֹלִים לְהִדָּבֵק בְּךְ. כְּשִׂמְחַת בַּקָּצִיר - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁשִּׂמְחַת הַקָּצִיר הִיא שֶׁלָּהּ. כַּאֲשֶׁר יָגִילוּ בְּחַלְּקָם שָׁלָל - כַּאֲשֶׁר יָגִילוּ אֵלּוּ שְׁאָר הַצְּבָאוֹת וְהַמֶּרְכָּבוֹת לְמַטָּה בִּזְמַן שֶׁמְּחַלְּקִים שָׁלָל וְטוֹרְפִים טֶרֶף בְּרֵאשִׁית הַכֹּל."],[20,"","רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים קיט) עֵת לַעֲשׂוֹת לַה' הֵפֵרוּ תוֹרָתֶךְ. מַה זֶּה עֵת לַעֲשׂוֹת לַה'? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל עֵת - זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁנִּקְרֵאת עֵת, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טז) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. מַה זֶּה וְאַל יָבֹא בְכָל עֵת? כְּמוֹ שֶׁנֶּאֱמַר (משלי ז) לִשְׁמָרְךְ מֵאִשָּׁה זָרָה. וְזֶהוּ (ויקרא י) וַיַּקְרִיבוּ לִפְנֵי ה' אֵשׁ זָרָה וְגוֹ'. מָה הַטַּעַם עֵת? מִשּׁוּם שֶׁיֵּשׁ לָהּ עֵת וּזְמַן לַכֹּל לְהִתְקָרֵב לִהְיוֹת מְאִירָה וּלְהִתְחַבֵּר כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ ה' עֵת רָצוֹן."],[21,"","לַעָשׂוֹת לַה', כְּמוֹ שֶׁכָּתוּב (שמואל ב ח) וַיַּעַשׂ דָּוִד שֵׁם. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה כְּאִלּוּ עָשָׂה וְתִקֵּן אֶת הָעֵת הַזֹּאת לְחַבֵּר אוֹתָהּ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא (תפארת). וְכָל כָּךְ לָמָּה? מִשּׁוּם שֶׁהֵפֵרוּ תוֹרָתֶךְ. שֶׁאִלּוּ לֹא הֵפֵרוּ תוֹרָתֶךְ, לֹא נִמְצָא פֵרוּד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִיִּשְׂרָאֵל לְעוֹלָמִים."],[22,"","אָמַר רַבִּי יוֹסִי, כְּמוֹ זֶה כָּתוּב (ישעיה ס) אֲנִי ה' בְּעִתָּהּ אֲחִישֶׁנָּה. מַהוּ בְּעִתָּהּ? בְּעֵת ה'. שֶׁתָּקוּם מִן הֶעָפָר, אָז אֲחִישֶׁנָּה."],[23,"","אָמַר רַבִּי יוֹסִי, וְעִם כָּל זֶה, יוֹם אֶחָד הִיא כְּנֶסֶת יִשְׂרָאֵל בְּתוֹךְ הֶעָפָר וְלֹא יוֹתֵר. אָמַר רַבִּי יְהוּדָה, כָּךְ אָמְרוּ, אֲבָל בֹּא רְאֵה הַסּוֹד שֶׁלָּמַדְנוּ. בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל גָּלְתָה מִמְּקוֹמָהּ, אָז אוֹתִיּוֹת הַשֵּׁם הַקָּדוֹשׁ כִּבְיָכוֹל נִפְרְדוּ, שֶׁנִּפְרְדָה הֵ\"א מִן וָא\"ו, וּמִשּׁוּם שֶׁנִּפְרְדוּ מַה כָּתוּב? (תהלים לט) נֶאֱלַמְתִּי דוּמִיָּ\"ה, מִשּׁוּם שֶׁהִסְתַּלֵּק וָא\"ו מֵהֵ\"א וְקוֹל לֹא נִמְצָא, אָז הַדִּבּוּר נֶאֱלָם,"],[24,"","וְלָכֵן הִיא שׁוֹכֶבֶת לֶעָפָר כָּל אוֹתוֹ הַיּוֹם הַזֶּה שֶׁל הֵ\"א. וּמִיהוּ? הָאֶלֶף הַחֲמִישִׁי. וְאַף עַל גַּב שֶׁהִקְדִּימָה בַּגָּלוּת עַד שֶׁלֹּא נִכְנָס אוֹתוֹ הָאֶלֶף הַחֲמִישִׁי, הַסּוֹד שֶׁל הֵ\"א."],[25,"","וּכְשֶׁיָּבֹא הָאֶלֶף הַשִּׁשִּׁי, שֶׁהוּא הַסּוֹד שֶׁל וָא\"ו, אָז וָא\"ו יָקִים אֶת הֵ\"א. בִּזְמַן שֵׁשׁ פְּעָמִים עֶשֶׂר שִׁשִּׁים נֶפֶשׁ, אָז שְׁלֵמוּת שֶׁל וָא\"ו עֶשֶׂר פְּעָמִים, וָא\"ו שֵׁשׁ פְּעָמִים עֶשֶׂר, (שוא\"ו) וָא\"ו עוֹלָה (בעשר) בְּי', וָא\"ו יוֹרֶדֶת בְּהֵ\"א."],[26,"","נִשְׁלֶמֶת וָא\"ו בְּתוֹךְ עֶשֶׂר שֵׁשׁ פְּעָמִים, אָז הֵם שִׁשִּׁים לַהֲקִימָהּ מֵהֶעָפָר. וּבְכָל שִׁשִּׁים וְשִׁשִּׁים מֵאוֹתוֹ הָאֶלֶף הַשִּׁשִּׁי מִתְחַזֶּקֶת הֵ\"א, וְעוֹלָה בְּדַרְגוֹתֶיהָ לְהִתְחַזֵּק. וּבְשֵׁשׁ מֵאוֹת שָׁנִים לָאֶלֶף הַשִּׁשִּׁי יִפָּתְחוּ שַׁעֲרֵי הַחָכְמָה לְמַעְלָה וּמַעְיָנוֹת שֶׁל חָכְמָה לְמַטָּה, וְיִתְתַּקֵּן הָעוֹלָם לְהִכָּנֵס לַשְּׁבִיעִי. כְּמוֹ בֶּן אָדָם שֶׁמְּתַקֵּן בְּיוֹם שִׁשִּׁי מִכְּשֶׁמַּעֲרִיב הַשֶּׁמֶשׁ לְהִכָּנֵס לְשַׁבָּת, אַף כָּךְ גַּם, וְסִימָן לַדָּבָר - (בראשית ז) בִּשְׁנַת שֵׁשׁ מֵאוֹת שָׁנָה לְחַיֵּי נֹחַ וְגוֹ' נִבְקְעוּ כָּל מַעְיְנוֹת תְּהוֹם רַבָּה."],[27,"","אָמַר לוֹ רַבִּי יוֹסִי, כָּל זֶה זְמַן אָרֹךְ יוֹתֵר מִכְּפִי שֶׁבֵּאֲרוּהוּ הַחֲבֵרִים שֶׁהוּא יוֹם אֶחָד גָּלוּת שֶׁל כְּנֶסֶת יִשְׂרָאֵל וְלֹא יוֹתֵר, שֶׁכָּתוּב (איכה א) נְתָנַני שׁוֹמֵמָה כָּל הַיּוֹם דָּוָה. אָמַר לוֹ, כָּךְ לָמַדְתִּי מֵאָבִי בְּסוֹדוֹת הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ וּבַיָּמִים שֶׁל שְׁנוֹת הָעוֹלָם וּבַיָּמִים שֶׁל בְּרֵאשִׁית, וְהַכֹּל בְּסוֹד אֶחָד הוּא."],[28,"","וְאָז תֵּרָאֶה הַקֶּשֶׁת בִּגְוָנִים מְאִירִים כְּמוֹ אִשָּׁה שֶׁמִּתְקַשֶּׁטֶת לְבַעְלָהּ, שֶׁכָּתוּב (בראשית ט) וּרְאִיתִיהָ לִזְכֹּר בְּרִית עוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ וְיָפֶה הוּא. וּרְאִיתִיהָ בִּגְוָנִים מְאִירִים כָּרָאוּי,"],[29,"","וְאָז לִזְכֹּר בְּרִית עוֹלָם. מַה זֶּה בְּרִית עוֹלָם? זוֹ כְּנֶסֶת יִשְׂרָאֵל, וְיִתְחַבֵּר וָא\"ו עִם הֵ\"א וִיקִימָהּ מִן הֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר וַיִּזְכֹּר אֱלֹהִים אֶת בְּרִיתוֹ. זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא בְּרִית, כְּמוֹ שֶׁנֶּאֱמַר וְהָיְתָה לְאוֹת בְּרִית וְגוֹ'."],[30,"","אָז יִתְעוֹרֵר וָא\"ו אֶל הֵ\"א, אָז אוֹתוֹת עֶלְיוֹנִים יִתְעוֹרְרוּ בָעוֹלָם, וַעֲתִידִים בְּנֵי רְאוּבֵן לְעוֹרֵר קְרָבוֹת בְּכָל הָעוֹלָם, וּכְנֶסֶת יִשְׂרָאֵל יָקִים אוֹתָהּ מִן הֶעָפָר וְיִזְכֹּר אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא,"],[31,"","וְיִמָּצֵא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶצְלָהּ בְּתוֹךְ הַגָּלוּת כְּחֶשְׁבּוֹן וָא\"ו שֵׁשׁ פְּעָמִים י' (עשר). עֶשֶׂר פְּעָמִים שֵׁשׁ שָׁנִים, וְאָז תָּקוּם וְיִפָּקֵד הָעוֹלָם לַעֲשׂוֹת נְקָמוֹת. וּמִי שֶׁהוּא נָמוּךְ - יִגְבַּהּ."],[32,"","אָמַר לוֹ רַבִּי יוֹסִי, יָפֶה אָמַרְתָּ, מִשּׁוּם שֶׁהוּא בְּתוֹךְ סוֹד הָאוֹתִיּוֹת וְאֵין לָנוּ לְעוֹרֵר חֶשְׁבּוֹן וְקִצִּים אֲחֵרִים, שֶׁהֲרֵי בְּסִפְרוֹ שֶׁל רַב יֵיבָא הַזָּקֵן מָצָאנוּ חֶשְׁבּוֹן זֶה, שֶׁכָּתוּב (ויקרא כו) אָז תִּרְצֶה הָאָרֶץ, וְהוּא הַסּוֹד שֶׁל וָא\"ו, שֶׁכָּתוּב (שם) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב, וְזֶהוּ וָא\"ו, הַכֹּל כְּאֶחָד. וְעַל זֶה אֶזְכֹּר. וְאַחַר כָּךְ וְהָאָרֶץ אֶזְכֹּר, זוֹ כְּנֶסֶת יִשְׂרָאֵל. תִּרְצֶה, תִּתְרַצֶּה הָאָרֶץ אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[33,"","אֲבָל יוֹם אֶחָד שֶׁאָמְרוּ הַחֲבֵרִים, וַדַּאי הַכֹּל גָּנוּז לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהַכֹּל נִמְצָא בְּסוֹד הָאוֹתִיּוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ, שֶׁהֲרֵי הַגָּלוּת בְּאוֹתָן הָאוֹתִיּוֹת גִּלָּה אוֹתָן רַבִּי יֵיסָא כָּאן, וְעַכְשָׁו בְּאוֹתָן הָאוֹתִיּוֹת הִתְגַּלּוּ וְגִלָּה אוֹתָן."],[34,"","אָמַר לוֹ, בּא רְאֵה שֶׁאֲפִלּוּ כְּשֶׁנִּפְקְדָה שָׂרָה, מִדַּרְגָּה הַזּוֹ לֹא פָקַד אוֹתָהּ, אֶלָּא בַּסּוֹד שֶׁל וָא\"ו, שֶׁכָּתוּב וַה' פָּקַד אֶת שָׂרָה וְגוֹ', מִשּׁוּם שֶׁהַכֹּל הוּא בַּסּוֹד שֶׁל וָא\"ו, וּבְהֵ\"א כּוֹלֵל הַכֹּל וּבוֹ מִתְגַּלֶּה הַכֹּל, מִשּׁוּם שֶׁכָּל דָּבָר נִסְתָּר הוּא מְגַלֶּה כָּל נִסְתָּר וְלֹא בָא מִישֶׁהוּ בְּגִלּוּי וִיגַלֶּה מַה שֶּׁהוּא נִסְתָּר."],[35,"","אָמַר רַבִּי יוֹסִי, כַּמָּה יֵשׁ לָנוּ לְהִמָּשֵׁךְ בְּתוֹךְ הַגָּלוּת עַד אוֹתוֹ הַזְּמַן, וְהַכֹּל תָּלָה לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁיָּשׁוּבוּ בִתְשׁוּבָה - אִם יִזְכּוּ וְאִם לֹא יִזְכּוּ, כְּמוֹ שֶׁנֶּאֱמַר בַּפָּסוּק הַזֶּה שֶׁכָּתוּב אֲנִי ה' בְּעִתָּהּ אֲחִישֶׁנָּה. זָכוּ - אֲחִישֶׁנָּה. לֹא זָכוּ - בְּעִתָּהּ."],[36,"","הָלְכוּ, בְּעוֹדָם הוֹלְכִים, אָמַר רַבִּי יוֹסִי, נִזְכַּרְתִּי עַכְשָׁו שֶׁבַּמָּקוֹם הַזֶּה יָשַׁבְתִּי יוֹם אֶחָד עִם אָבִי וְאָמַר לִי, בְּנִי, עָתִיד אַתָּה כְּשֶׁתַּגִּיעַ יָמֶיךְ לְשִׁשִּׁים שָׁנִים לִמְצֹא בַּמָּקוֹם הַזֶּה אוֹצָר שֶׁל חָכְמָה עֶלְיוֹנָה, וַהֲרֵי זָכִיתִי לְאוֹתָם הַיָּמִים וְלֹא מָצָאתִי, וְאֵינוֹ יוֹדֵעַ אִם הַדְּבָרִים הַלָּלוּ שֶׁאָמַרְנוּ אוֹ אוֹתָהּ הַחָכְמָה שֶׁהוּא אָמַר."],[37,"","וְאָמַר לִי, כְּשֶׁיַּגִּיעוּ הַשַׁלְהָבוֹת שֶׁל הָאֵשׁ לְתוֹךְ הָאֲוִיר שֶׁל יָדֶיךְ, יֹאבַד מִמְּךְ. אָמַרְתִּי לוֹ, אַבָּא, בַּמֶּה יָדַעְתָּ? אָמַר לִי, בְּאוֹתָן שְׁתֵּי צִפֳּרִים שֶׁעָבְרוּ עַל רֹאשְׁךְ יָדַעְתִּי."],[38,"","בֵּין כָּךְ נִפְרַד רַבִּי יוֹסִי וְנִכְנַס לְתוֹךְ מְעָרָה אַחַת, וּמָצָא סֵפֶר אֶחָד שֶׁהָיָה נָעוּץ בְּתוֹךְ נֶקֶב שֶׁל הַסֶּלַע בִּקְצֵה הַמְּעָרָה. יָצָא אִתּוֹ."],[39,"","כֵּיוָן שֶׁפָּתַח אוֹתוֹ, רָאָה שִׁבְעִים וּשְׁתַּיִם חִקּוּקֵי אוֹתִיּוֹת שֶׁנִּמְסְרוּ לְאָדָם הָרִאשׁוֹן, וּבָהֶם הָיָה יוֹדֵעַ כָּל הַחָכְמָה שֶׁל עֶלְיוֹנִים קְדוֹשִׁים וְכָל אוֹתָם שֶׁאַחַר הָרֵיחַיִם שֶׁמִּתְגַּלְגְּלִים אַחַר הַפָּרֹכֶת תּוֹךְ אוֹרוֹת עֶלְיוֹנִים וְכָל אוֹתָם דְּבָרִים שֶׁעֲתִידִים לָבֹא לָעוֹלָם עַד הַיּוֹם שֶׁיָּקוּם עָנָן בְּצַד מַעֲרָב וְיַחְשִׁיךְ אֶת הָעוֹלָם."],[40,"","קָרָא לְרַבִּי יְהוּדָה וְהִתְחִילוּ לִלְמֹד בְּאוֹתוֹ סֵפֶר. לֹא הִסְפִּיקוּ לִלְמֹד שְׁנַיִם אוֹ שְׁלֹשָׁה צְדָדִים שֶׁל אוֹתָן הָאוֹתִיּוֹת עַד שֶׁהָיוּ מִסְתַּכְּלִים בְּאוֹתָהּ חָכְמָה עֶלְיוֹנָה. כֵּיוָן שֶׁהִגִּיעוּ לִלְמֹד בְּסִתְרֵי הַסֵּפֶר וְדִבְּרוּ זֶה עִם זֶה, יָצָא שְׁבִיב שֶׁל אֵשׁ וּמַשָּׁב שֶׁל רוּחַ וְהִכָּה בִידֵיהֶם וְאָבַד מֵהֶם. בָּכָה רַבִּי יוֹסִי וְאָמַר, אוּלַי חַס וְחָלִילָה חֵטְא הוּא אֶצְלֵנוּ, אוֹ שֶׁאֵין אָנוּ זַכָּאִים לָדַעַת אוֹתוֹ."],[41,"","כְּשֶׁבָּאוּ אֶל רַבִּי שִׁמְעוֹן, סִפְּרוּ לוֹ הַמַּעֲשֶׂה הַזֶּה. אָמַר לָהֶם, אוּלַי בְּקֵץ הַמָּשִׁיחַ שֶׁל אוֹתָם אוֹתִיּוֹת הֱיִיתֶם עֲסוּקִים? אָמְרוּ לוֹ, אֶת זֶה לֹא יָדַעְנוּ, שֶׁהֲרֵי הַכֹּל נִשְׁכָּח מֵעִמָּנוּ. אָמַר לָהֶם רַבִּי שִׁמְעוֹן, שֶׁאֵין רְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא בָּזֶה שֶׁיִּתְגַּלֶּה כָּל כָּךְ לָעוֹלָם, וּכְשֶׁיִּהְיֶה קָרוֹב לִימוֹת הַמָּשִׁיחַ, אֲפִלּוּ תִינוֹקוֹת שֶׁל הָעוֹלָם עֲתִידִים לִמְצֹא נִסְתָּרוֹת שֶׁל חָכְמָה וְלָדַעַת בּוֹ קִצִּים וְחֶשְׁבּוֹנוֹת, וּבְאוֹתוֹ זְמַן יִתְגַּלֶּה לַכֹּל. זֶהוּ שֶׁכָּתוּב (צפניה ג) כִּי אָז אֶהְפֹּךְ אֶל עַמִּים וְגוֹ'. מַה זֶּה אָז? בִּזְמַן שֶׁתָּקוּם כְּנֶסֶת יִשְׂרָאֵל מִן הֶעָפָר וְיָקִים אוֹתָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז אֶהְפֹּךְ אֶל עַמִּים שָׂפָה בְרוּרָה לִקְרֹא כֻלָּם בְּשֵׁם ה' וּלְעָבְדוֹ שְׁכֶם אֶחָד."],[42,"","בֹּא רְאֵה, אַף עַל גַּב שֶׁכָּתוּב בְּאַבְרָהָם, וַיִּסַּע אַבְרָם הָלוֹךְ וְנָסוֹעַ הַנֶּגְבָּה, וְכָל מַסְעוֹתָיו הָיוּ לַדָּרוֹם וְנִקְשַׁר בּוֹ, לֹא עָלָה לִמְקוֹמוֹ כָּרָאוּי עַד שֶׁנּוֹלַד יִצְחָק. כֵּיוָן שֶׁנּוֹלַד יִצְחָק, הִתְעַלָּה לִמְקוֹמוֹ וְהִשְׁתַּתֵּף עִמּוֹ וְנִקְשְׁרוּ זֶה עִם זֶה."]]],[["בְגִין כָּךְ אִיהוּ קָרֵי לֵיהּ יִצְחָק וְלָא אָחֳרָא, בְּגִין לְשַׁתְּפָא מַיָא בְּאֶשָׁא, דִּכְתִיב וַיִּקְרָא אַבְרָהָם אֶת שֵׁם בְּנוֹ הַנּוֹלַד לוֹ אֲשֶׁר יָלְדָה לוֹ שָׂרָה יִצְחָק. מַאן הַנּוֹלַד לוֹ, אֵשׁ מִמַּיִם:","וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק. אָמַר רַבִּי חִיָּיא, מִיּוֹמָא דְּאִתְיְלִיד יִצְחָק וְהֲוָה יִשְׁמָעֵאל בְּבֵיתָא דְאַבְרָהָם, לָא אִסְתַּלַּק יִשְׁמָעֵאל בִּשְׁמָא, בְּאֲתַר דְּדַהֲבָא שַׁרְיָא סוֹסְפִיתָא לָא אִדְכַּר קַמֵּיהּ, וּבְגִין כָּךְ אֶת בֶּן הָגָר הַמִּצְרִית, גְּבַר דְּלָא יִתְחֲזֵי לְאַדְכָּרָא קַמֵּיהּ דְּיִצְחָק.","אָמַר רַבִּי יִצְחָק וַתֵּרֶא שָׂרָה, בְּעֵינָא דִקְלָנָא חָמַאת לֵיהּ שָׂרָה, דְּלָא חָמַאת לֵיהּ בְּעֵינָא דְּאִיהוּ בְּרָא דְּאַבְרָהָם, אֶלָּא דְּאִיהוּ בְּרָא דְּהָגָר הַמִּצְרִית, וּבְגִין כָּךְ וַתֵּרֶא שָׂרָה. דְּשָׂרָה חָמַאת לֵיהּ בְּעֵינָא דָא וְלֹא אַבְרָהָם, דְּאִילוּ בְּאַבְרָהָם לֹא כְּתִיב אֶת בֶּן הָגָר אֶלָּא אֶת בְּנוֹ.","תָּא חֲזֵי, לְבָתַר מַה כְּתִיב וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינִי אַבְרָהָם עַל אוֹדוֹת בְּנוֹ. וְלָא כְּתִיב עַל אוֹדוֹת בֶּן הָגָר הַמִּצְרִית. בְגִין כָּךְ וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית. וְלָא חָמַאת דְּאִיהוּ בְּרִיהּ דְּאַבְרָהָם.","רַבִּי שִׁמְעוֹן אָמַר הַאי קְרָא תּוּשְׁבַּחְתָּא דְשָׂרָה אִיהוּ, בְּגִין דְּחָמַאת לֵיהּ דְּקָא מְצַחֵק לְכּוֹכָבִים וּמַזָּלוֹת, אָמְרָה, וַדַּאי לַאו בְּרָא דָא בְּרָא דְאַבְרָהָם לְמֶעֱבַד עוֹבָדוֹי דְאַבְרָהָם, אֶלָּא בְּרָא דְּהָגָר הַמִּצְרִית אִיהוּ אֲהַדַּר לְחוּלָקָא דְּאִמֵּיהּ, בְגִין כָּךְ וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ, כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזֹּאת עִם בְּנִי עִם יִצְחָק.","וְכִי סַלְקָא דַעְתָּךְ דְּקַנֵּי לָהּ שָׂרָה אוֹ לִבְרָהּ, אִי הָכִי לא אוֹדֵי קוּדְשָׁא בְּרִיךְ הוּא עִמָּהּ, דִּכְתִיב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקוֹלָהּ. אֶלָּא בְּגִין דְּחָמַאת לֵיהּ בְּכּוֹכָבִים וּמַזָּלוֹת וְאִמֵּיהּ אוּלְפָא לֵיהּ נִמּוּסֵי דְּכּוֹכָבִים וּמַזָּלוֹת, בְּגִין כָּךְ אֲמְרַת שָׂרָה כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזֹּאת, אֲנָא יָדַעְנָא דְּלָא יָרִית לְעָלְמִין חוּלָקָא דִמְהֵימְנוּתָא, וְלָא יְהֵא לֵיהּ עִם בְּרִי חוּלָקָא לָא בְּעַלְמָא דֵין וְלָא בְּעַלְמָא דְאָתֵי, וּבְגִין כָךְ אוֹדֵי עִמָּהּ קוּדְשָׁא בְּרִיךְ הוּא.","וְקוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַפְרָשָׁא בִּלְחוֹדוֹי זַרְעָא קַדִּישָׁא כְּדְקָא יְאוּת, דִּבְגִין כָּךְ בָּרָא עַלְמָא דְּהָא יִשְׂרָאֵל סָלִיק בִּרְעוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא עַד לָא יִבְרֵי עַלְמָא, וּבְגִין כָּךְ נָפַק אַבְרָהָם לְעַלְמָא וְעַלְמָא מִתְקַיֵּים בְּגִינֵיהּ, וְאַבְרָהָם וְיִצְחָק (לא) קָיְימוּ וְלָא אִתְיַישְׁבוּ בְּדוּכְתַּיְיהוּ עַד דְּנָפַק יַעֲקֹב לְעָלְמָא.","כֵּיוָן דְּנָפַק יַעֲקֹב לְעַלְמָא אִתְקָיְימוּ אַבְרָהָם וְיִצְחָק וְאִתְקְיַּים כָּל עַלְמָא, וּמִתַּמָּן נָפַק עַמָּא קַדִּישָׁא לְעַלְמָא, וְאִתְקְיַּים כֹּלָּא כְּגַוְונָא קַדִּישָׁא כְּדְקָא יְאוּת, וּבְגִין כָּךְ אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקוֹלָהּ כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע, וְלֹא בְּיִשְׁמָעֵאל. מַה כְּתִיב לְבָתַר וַתֵּלֶךְ וַתֵּתַע בְּמִדְבַּר בְּאֵר שָׁבַע.","כְּתִיב הָכָא וַתֵּתַע וּכְתִיב הָתָם (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתּוּעִים. וְקוּדְשָׁא בְּרִיךְ הוּא בְּגִינֵיהּ דְּאַבְרָהָם לָא שָׁבִיק. לָהּ וְלִבְרָהּ.","תָּא חֲזֵי, בְּקַדְמִיתָא כַד אָזְלַת מִקַּמָּהּ דְּשָׂרָה מַה כְּתִיב כִּי שָׁמַע יְיָ אֶל עָנְיֵיךְ. וְהַשְׁתָּא דְּטָעַאת בָּתַר כּוֹכָבִים וּמַזָּלוֹת אַף עַל גַּב דִּכְתִיב וַתִּשָּׂא אֶת קוֹלָהּ וַתֵּבְךָ. מַה כְּתִיב כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר. וְלָא כְּתִיב כִּי שָׁמַע אֱלהִים אֶת קוֹלֵךְ.","בַּאֲשֶׁר הוּא שָׁם. הָא אוּקְמוּהָ דְּלָאו בַּר עוֹנָשָׁא הוּא לְגַבֵּי בֵּי דִינָא דִּלְעֵילָא, דְּהָא בֵּי דִינָא דִלְתַתָּא עָנְשִׁין מִתְּלֵיסַר שְׁנִין וּלְעֵילָא, וּבֵי דִינָא דִלְעֵילָא מֵעֶשְׂרִים שְׁנִין וּלְהָלְאָה. וְאַף עַל גַּב דְּחַיָּיבָא הֲוָה, לָאו בַּר עוֹנָשָׁא אִיהוּ. וְהָא אוּקְמוּהָ, וְדָא הוּא דִכְתִיב בַּאֲשֶׁר הוּא שָׁם.","אָמַר רַבִּי אֶלְעָזָר אִי הָכִי מַאן דְּאִסְתַּלַּק מֵעַלְמָא עָד לָא מָטוּן יוֹמוֹי לְעֶשְׂרִין שְׁנִין, מֵאָן אֲתַר אִתְעַנָּשׁ, בְּגִין דְּהָא מִתְּלֵיסַר שְׁנִין וּלְתַתָּא לָאו בַּר עוֹנָשָׁא אִיהוּ אֶלָא בְּחֶטְאוֹי דְּאֲבוֹי. אֲבָל מִתְּלֵיסַר שְׁנִין וּלְעֵילָא מַהוּ, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא חָס עֲלֵיהּ דְּלֵימוּת זַכַּאי (ולא לימות חייב) וְיָהִיב לֵיהּ אֲגַר טַב בְּהַהוּא עָלְמָא, וְלָא לֵימוּת חַיָּיב דְּיִתְעַנָּשׁ בְּהַהוּא עָלְמָא וְאוּקְמוּהָ."],[[0,"בג\"כ איהו וכו':","משום זה, אברהם קרא אותו יצחק, ולא אחר, כדי לשתף בזה \u0003מים באש.\u0004 מדתו של אברהם שהוא \u0003מים\u0004 במדתו של יצחק שהוא \u0003אש.\u0004 שכתוב, ויקרא אברהם את שם בנו הנולד לו אשר ילדה לו שרה, יצחק. ושואל למה מדייק הכתוב לומר \u0003הנולד לו.\u0004 ואומר, אש ממים. פירוש, שהוא כדי ללמדנו, שיצחק שהוא אש נולד מאברהם שהוא מים ועל כן נכללו זה בזה."],[1,"ותרא שרה את בן הגר וגו':","אמר ר' חייא מיום שנולד יצחק, וישמעאל היה בביתו של אברהם, לא נזכר ישמעאל בשמו, כי במקום ששורה זהב, לא נזכר לפניו פסולת, ומשום זה כתוב את בן הגר המצרית, ולא ישמעאל בן הגר, איש שאינו כדאי להזכיר שמו לפני יצחק."],[2,"אמר רבי יצחק וכו': אר\"י, ותרא שרה","עם עין לקלון, כלומר החפצה לראות רק קלון, ראתה אותו שרה, כי לא ראתה אותו, עם העין, שהוא בנו של אברהם, אלא שהוא בנו של הגר המצרית, ומשום זה כתב, \u0003ותרא שרה,\u0004 כי רק שרה ראתה אותו עם עין כזו, ולא אברהם, כי באברהם לא כתוב את בן הגר, אלא את בנו."],[3,"ת\"ח לבתר וכו':","בוא וראה לאחר כך מה כתוב, וירע הדבר מאד בעיני אברהם על אודות בנו. ולא כתוב על אודות בן הגר המצרית, וכנגד זה כתוב, ותרא שרה את בן הגר המצרית, ולא ראתה שהוא בנו של אברהם."],[4,"ר' שמעון אמר וכו':","רש\"א, מקרא זה, שבחה של שרה הוא. משום שראתה אותו שמצחק לעבודה זרה, אמרה, ודאי, אין בן זה בנו של אברהם, לעשות מעשיו של אברהם, אלא בן הגר המצרית הוא, כי חזר לחלק אמו ומשום זה, ותאמר לאברהם גרש האמה הזאת ואת בנה כי לא יירש וגו'."],[5,"וכי סלקא דעתך וכו':","והכי יעלה על דעתך, ששרה קנא אותה או את בנה, וע\"כ אמרה גרש וגו', אם היה כן, לא היה הקב\"ה מודה לדבריה, שכתוב כל אשר תאמר אליך שרה שמע בקולה. אלא משום שראתה אותו בעבודה זרה, ואמו למדה אותו חוקי עבודה זרה, משום זה אמרה שרה, כי לא יירש בן האמה הזאת: אני יודעת שלא יירש לעולם חלק של האמונה, ולא יהיה לו חלק עם בני לא בעולם הזה ולא בעולם הבא. ועל כן הודה לה הקב\"ה."],[6,"וקב\"ה בעא לאפרשא וכו':","והקב\"ה רצה להבדיל זרע הקדוש בלבדם כראוי, שמשום זה ברא העולם, כי ישראל עלה ברצונו של הקב\"ה מטרם שברא העולם. ומשום זה יצא אברהם לעולם, והעולם נתקיים בשבילו. ואברהם ויצחק עמדו ולא נתיישבו במקומם עד שיצא יעקב לעולם."],[7,"כיון דנפק וכו':","כיון שיצא יעקב לעולם נתקיימו ואברהם ויצחק ונתקיים כל העולם."],[7,"ומתמן נפק וכו':","ומשם. מיעקב, יצא עם הקדוש לעולם, ונתקיים הכל כצד הקדושה כראוי. ועל כן אמר לו הקב\"ה, כל אשר תאמר אליך שרה שמע בקולה, כי ביצחק יקרא לך זרע, ולא בישמעאל."],[8,"מה כתיב וכו':","מה כתוב אחר כך, ותלך ותתע במדבר באר שבע. כתוב כאן ותתע, וכתוב שם הבל המה מעשה תעתועים, לומדים גזירה שוה, מה שם עבודה זרה אף כאן עבודה זרה. והקב\"ה, בזכות אברהם, לא עזב אותה ואת בנה. והציל אותם מצמא, אע\"פ שעבדה עבודה זרה."],[9,"ת\"ח בקדמיתא וכו':","בוא וראה בתחילה כאשר ברחה מפני שרה, מה כתוב, כי שמע ה' אל ענייך. ועתה שהיא זנה אחר עבודה זרה, אע\"פ שכתוב, ותשא את קולה ותבך, מה כתוב, כי שמע אלקים אל קול הנער, ולא כתוב כי שמע אלקים אל קולך."],[10,"באשר הוא שם:","הנה בארוהו, שישמעאל לא היה בן עונשין אצל ב\"ד של מעלה. כי בית דין של מטה מענישים מי\"ג שנים ומעלה, ובית דין של מעלה מענישים מעשרים שנה ומעלה. לפיכך, אף על פי שהיה רשע, לא היה בן עונשים. וזה הוא שכתוב \u0003באשר הוא שם,\u0004 דהיינו משום שהיה פחות מכ' שנים, וע\"כ, הצילו הקב\"ה."],[11,"א\"ר אלעזר וכו':","אר\"א, אם כן, מי שנפטר מעולם, מטרם שמגיע ימיו לכ' שנים, מאיזה מקום הוא נענש למיתה. כי למטה מי\"ג שנים אע\"פ שאינו בן עונשים הוא נענש ומת על חטאיו של אביו, להיותו עוד ברשותו, אבל מי\"ג שנים ומעלה מהו, הרי כבר יצא מרשות אביו, ומשום מה נענש ומת בעוד שאינו בן עונשים."],[11,"א\"ל קב\"ה וכו':","אמר לו. הקב\"ה מרחם עליו שימות צדיק, ונותן לו שכר טוב בעולם הנצחי. ולא ימות רשע, שיתענש באותו עולם וכבר בארוהו כן."]],[[0,"","לָכֵן הוּא קָרָא לוֹ יִצְחָק וְלֹא אַחֵר, כְּדֵי לְשַׁתֵּף מַיִם עִם אֵשׁ, שֶׁכָּתוּב וַיִּקְרָא אַבְרָהָם אֶת שֶׁם בְּנוֹ הַנּוֹלַד לוֹ אֲשֶׁר יָלְדָה לּוֹ שָׂרָה יִצְחָק. מִי הַנּוֹלַד לוֹ? אֵשׁ מִמַּיִם."],[1,"","וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק. אָמַר רַבִּי חִיָּיא, מִיּוֹם שֶׁנּוֹלַד יִצְחָק וְהָיָה יִשְׁמָעֵאל בְּבֵית אַבְרָהָם, לֹא הִתְעַלָּה יִשְׁמָעֵאל בַּשֵּׁם. בְּמָקוֹם שֶׁזָּהָב שׁוֹרֶה, לֹא נִזְכָּר פְּסֹלֶת לְפָנָיו, וְלָכֵן אֶת בֶּן הָגָר הַמִּצְרִית, אִישׁ שֶׁלֹּא רָאוּי לְהִזָּכֵר לִפְנֵי יִצְחָק."],[2,"","אָמַר רַבִּי יִצְחָק, וַתֵּרֶא שָׂרָה, בְּעַיִן שֶׁל קָלוֹן רָאֲתָה אוֹתוֹ שָׂרָה, שֶׁלֹּא רָאֲתָה אוֹתוֹ בְּעַיִן שֶׁהוּא בֶּן אַבְרָהָם, אֶלָּא שֶׁהוּא בֶּן הָגָר הַמִּצְרִית, וּמִשּׁום כָּךְ וַתֵּרֶא שָׂרָה. שֶׁרָאֲתָה שָׂרָה אוֹתוֹ בְּעַיִן זוֹ וְלֹא אַבְרָהָם, שֶׁאִלּוּ בְּאַבְרָהָם לֹא כָתוּב אֶת בֶּן הָגָר, אֶלָּא אֶת בְּנוֹ."],[3,"","בֹּא רְאֵה אַחַר כָּךְ מַה כָּתוּב, וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינֵי אַבְרָהָם עַל אוֹדת בְּנוֹ. וְלֹא כָתוּב עַל אוֹדוֹת בֶּן הָגָר הַמִּצְרִית. מִשּׁוּם כָּךְ וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית, וְלֹא רָאֲתָה שֶׁהוּא בֶּן אַבְרָהָם."],[4,"","רַבִּי שִׁמְעוֹן אָמַר, הַפָּסוּק הַזֶּה תִּשְׁבַּחַת לְשָׂרָה הוּא. מִשּׁוּם שֶׁרָאֲתָה אוֹתוֹ מְצַחֵק לְכוֹכָבִים וּמַזָּלוֹת, אָמְרָה וַדַּאי שֶׁבֵּן זֶה אֵינוֹ בְּנוֹ שֶׁל אַבְרָהָם לַעֲשׂוֹת אֶת מַעֲשֵׂי אַבְרָהָם, אֶלָּא בֶּן הָגָר הַמִּצְרִית הוּא, חָזַר לַחֵלֶק שֶׁל אִמּוֹ. לָכֵן וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַ את עִם בְּנִי עִם יִצְחָק."],[5,"","וְכִי עָלָה עַל דַּעְתְּךְ שֶׁקִּנְּאָה לָהּ שָׂרָה אוֹ לַבֵּן שֶׁלָּהּ? אִם כָּךְ, לֹא הָיָה מוֹדֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהּ, שֶׁכָּתוּב כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ. אֶלָּא מִשּׁוּם שֶׁרָאֲתָה אוֹתוֹ עִם כּוֹכָבִים וּמַזָּלוֹת וְאִמּוֹ מְלַמֶּדֶת אוֹתוֹ מִנְהֲגֵי עֲבוֹדָה זָרָה, לָכֵן אָמְרָה שָׂרָה כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזאת. אֲנִי יוֹדַעַת שֶׁלֹּא יִירַשׁ לְעוֹלָמִים אֶת חֵלֶק הָאֱמוּנָה, וְלֹא יִהְיֶה לוֹ עִם בְּנִי חֵלֶק לֹא בָּעוֹלָם הַזֶּה וְלֹא בָּעוֹלָם הַבָּא. וְלָכֵן הוֹדָה עִמָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[6,"","וְהַקָּדוֹשׁ בָּרוּךָ הוּא רָצָה לְהַפְרִיד לְבַדּוֹ אֶת הַזֶּרַע הַקָּדוֹשׁ כָּרָאוּי, שֶׁמִּשּׁוּם כָּךְ בָּרָא אֶת הָעוֹלָם, שֶׁהֲרֵי יִשְׂרָאֵל עָלָה בִרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁלֹּא נִבְרָא הָעוֹלָם, וְלָכֵן יָצָא אַבְרָהָם לָעוֹלָם וְהָעוֹלָם הָיָה מִתְקַיֵּם בִּגְלָלוֹ, וְאַבְרָהָם וְיִצְחָק (לא) עָמְדוּ וְלֹא הִתְיַשְּׁבוּ בִמְקוֹמָם עַד שֶׁיָּצָא יַעֲקֹב לָעוֹלָם."],[7,"","כֵּיוָן שֶׁיָּצָא יַעֲקֹב לָעוֹלָם, הִתְקַיְּמוּ אַבְרָהָם וְיִצְחָק וְעָמַד כָּל הָעוֹלָם, וּמִשָּׁם יָצָא הָעָם הַקָּדוֹשׁ לָעוֹלָם וְהִתְקַיֵּם הַכֹּל בְּגָוֶן קָדוֹשׁ כָּרָאוּי. וְלָכֵן אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךְ שָׂרָה שְׁמַע בְּקֹלָהּ כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע, וְלֹא בְּיִשְׁמָעֵאל. מַה כָּתוּב אַחַר כָּךְ? וַתֵּלֶךְ וַתֵּתַע בְּמִדְבַּר בְּאֵר שָׁבַע."],[8,"","כָּתוּב כָּאן וַתֵּתַע, וְכָתוּב שָׁם (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּגְלַל אַבְרָהָם לֹא עָזַב אוֹתָהּ וְאֶת בְּנָהּ."],[9,"","בֹּא רְאֵה, בַּהַתְחָלָה כְּשֶׁהָלְכָה מִלִּפְנֵי שָׂרָה מַה כָּתוּב? כִּי שָׁמַע ה' אֶל עָנְיֵךְ. וְכָאן שֶׁטָּעֲתָה אַחַר כּוֹכָבִים וּמַזָּלוֹת, אַף עַל גַּב שֶׁכָּתוּב וַתִּשָּׂא אֶת קֹלָהּ וַתֵּבְךָּ, מַה כָּתוּב? כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר, וְלֹא כָתוּב כִּי שָׁמַע אֱלֹהִים אֶת קוֹלֵךְ."],[10,"","בַּאֲשֶׁר הוּא שָׁם, הֲרֵי פֵּרְשׁוּהָ שֶׁלֹּא בָר עֹנֶשׁ הוּא אֵצֶל בֵּית הַדִּין שֶׁלְּמַעְלָה, שֶׁהֲרֵי בֵּית דִּין שֶׁל מַטָּה מַעֲנִישִׁים מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנָה וָמַעְלָה, וּבֵית שֶׁל שֶׁל מַעְלָה מֵעֶשְׂרִים שָׁנָה וָמַעְלָה, וְאַף עַל גַּב שֶׁהָיָה רָשָׁע, אֵינוֹ בֶּן עֹנֶשׁ. וַהֲרֵי פֵּרְשׁוּהָ, וְזֶהוּ שֶׁכָּתוּב בַּאֲשֶׁר הוּא שָׁם."],[11,"","אָמַר רַבִּי אֶלְעָזָר, אִם כָּךְ, מִי שֶׁמִּסְתַּלֵּק מֵהָעוֹלָם בְּטֶרֶם הִגִּיעוּ יָמָיו לְעֶשְׂרִים שָׁנָה, מֵאֵיזֶה מָקוֹם נֶעֱנָשׁ, מִשּׁוּם שֶׁהֲרֵי מִשְּׁלֹשׁ עֶשְׂרֵה שָׁנִים וָמַטָּה אֵינוֹ בַּר עֳנָשִׁים אֶלָּא בַּחֲטָאֵי אָבִיו, אֲבָל מִשְּׁלֹשׁ עֶשְׂרֵה וָמַעְלָה מַהוּ? אָמַר לוֹ, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עָלָיו שֶׁיָּמוּת זַכַּאי (ולא ימות חיב), וְנוֹתֵן לוֹ שָׂכָר טוֹב בָּעוֹלָם הַהוּא, וְלֹא יָמוּת חַיָּב שֶׁיֵּעָנֵשׁ בְּאוֹתוֹ עוֹלָם, וּבֵאֲרוּהָ."]]],[["אָמַר לֵיהּ אִי חַיָּיבָא הוּא וְלָא מָטוּן יוֹמוֹי לְעֶשְׂרִין שְׁנִין מַהוּ כֵּיוָן דְּאִסְתַּלַּק מֵעַלְמָא בְּמַאי הוּא עוֹנְשֵׁיהּ. אָמַר לֵיהּ בְּדָא אִתְקְיַּים (משלי י״ג:כ״ג) וְיֵשׁ נִסְפָּה בְּלא מִשְׁפָּט. דְּכַד עוֹנָשָׁא נָחִית לְעַלְמָא אִיהוּ (דינא) אַעֲרַע בְּלָא כַּוָּנָה לְעֵילָא וְתַתָּא בְּהַהוּא מְחַבְּלָא וְיִתְעַנַּשׁ כַּד לָא אַשְׁגָּחוּ עֲלֵיהּ מִלְעֵילָא.","וְעֲלֵיהּ כְּתִיב, (משלי ה׳:כ״ב) עֲווֹנוֹתָיו יִלְכְּדֻנוֹ אֶת הָרָשָׁע. א\"ת לְאַסְגָּאָה מַאן דְּלָא מָטוּן יוֹמוֹי לְאִתְעֲנָשָׁא. עֲווֹנוֹתָיו יִלְכְּדֻנוֹ (את הרשע) וְלָא בֵּי דִינָא דִלְעֵילָא, וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ וְלָא בֵּי דִינָא דִלְתַתָּא. בְּגִין כָּךְ כְּתִיב כִּי שָׁמַע אֱלהִים אֶל קוֹל הַנַּעַר בַּאֲשֶׁר הוּא שָׁם.","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב מָלֵא בְּוא\"ו אַמַּאי. אֶלָּא בִּתְרֵין סִטְרִין אִיהוּ (אנון). רָזָא דְחָכְמְתָא חָדָא. דְּאִיהוּ רָזָא דַרְגָּא דְחָכְמְתָא. אֲתַר דְּשָׁרֵי בֵּיהּ יַעֲקֹב. אֲבָל הַאי קְרָא עַל גָּלוּתָא דְיִשְׂרָאֵל אִתְּמָר, דְּכַד אִנּוּן גּוֹ גָּלוּתָא, הַהוּא זִמְנָא דְּיִתְפַּקְדוּן (ביה יעקב) יִתְפַּקְדוּן בְּרָזָא דְּוא\"ו. וְאִיהוּ בְּאֶלֶף שְׁתִיתָאָה.","(ואתחנן ער א) וּפְקִידָה בְּרָזָא דְוא\"ו שִׁית רִגְעֵי וּפְלַג עִידָן. וּבְזִמְנָא דְּשִׁתִּין שְׁנִין לְעִבּוּרָא דְדַשָּׁא בְּאֶלֶף שְׁתִיתָאָה יָקִים אֱלָהּ שְׁמַיָא פְּקִידוּ לִבְרַתֵּיהּ דְּיַעֲקֹב. וּמֵהַהוּא זִמְנָא עַד דִּיְהֵא לָהּ זְכִירָה שִׁית שְׁנִין וּפַלְגָא. וּמֵהַהוּא זִמְנָא שִׁית שְׁנִין אָחֳרָנִין וְאִנּוּן שִׁבְעִין (ותלת) וּתְרֵין וּפַּלְגָא.","בְּשִׁיתִּין וְשִׁית יִתְגְּלֵי מַלְכָּא מְשִׁיחָא בְּאַרְעָא (שמות ז ב, ט ב) דְגָלִיל, וְכַד כֹּכָבָא דְּבִסְטַר מִזְרָח יִבְלַע שֶׁבַע כֹּכְבַיָא מִסְטַר צָפוֹן, וְשַׁלְהוֹבָא דְּאֶשָׁא אוּכְמָא תְּהֵא תַּלְיָא בִּרְקִיעָא שִׁיתִּין יוֹמִין, וּקְרָבִין יִתְעָרוּן בְּעַלְמָא לִסְטַר צָפוֹן, וּתְרִין מַלְכִין יִפְּלוּן בְּאִנּוּן קְרָבִין.","וְיִזְדַּוְּוגוּן כֻּלְּהוֹן עַמְּמַיָא עַל בְּרַתֵּיהּ דְּיַעֲקֹב לְאִדַחְיָיא לָהּ (לון) מֵעָלְמָא. וְעַל הַהוּא זִמְנָא כְּתִיב (והיתה) (ירמיהו ל׳:ז׳) וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּהּ יִוָּשֵׁעַ וּכְדֵין יִסְתַּיְּימוּן נַפְשִׁין מִגּוּפָא וּבָעְיָין לְאִתְחַדְּשָׁא, וְסִימָנִיךְ (כל הנפש לבית יעקב הבאה מצרימה שבעים וכתיב) (בראשית מ״ו:כ״ז) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה וְגו' כָּל נֶפֶשׁ שִׁשִּׁים וָשֵׁשׁ.","בְּשִׁבְעִין וּתְלַת כָּל מַלְכֵי עַלְמָא יִתְכַּנְּשׁוּן לְגוֹ קַרְתָּא רַבְּתָא דְּרוֹמִי, וְקוּדְשָׁא בְּרִיךְ הוּא יִתְעַר עֲלַיְיהוּ אֶשָׁא וּבַרְדָא וְאַבְנֵי אַלְגָבִישׁ וְיִתְאַבְּדוּן מֵעַלְמָא, בַּר אִנּוּן מְלָכִין דְּלָא יִמְטוּן לְתַמָּן וִיהַדְּרוּן לְאַגָּחָא קְרָבִין אָחֳרָנִין. וּמֵהַהוּא זִמְנָא מַלְכָּא מְשִׁיחָא יִתְעַר בְּכָל עַלְמָא, וְיִתְכַּנְּשׁוּן עִמֵּיהּ כַּמָּה עַמִּין וְכַמָּה חַיָּילִין מִכָּל סְיָיפֵי עַלְמָא, וְכָל בְּנֵי יִשְׂרָאֵל יִתְכַּנְּשׁוּן בְּכָל אִנּוּן אַתְרֵי.","עַד דְּאִשְׁתַּלִּימוּ אִנּוּן שְׁנִין לְמֵאָה, כְּדֵין וא\"ו יִתְחַבַּר בְּה\"א, וּכְדֵין (ישעיהו ס״ו:כ׳) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַיְיָ וְגו'. וּבְנֵי יִשְׁמָעֵאל (ישראל) זְמִינִין בְּהַהוּא זִמְנָא לְאַתְעָרָא (עליהון) עִם כָּל עַמִּין דְּעַלְמָא לְמֵיתֵי עַל יְרוּשָׁלֵם דִּכְתִיב, (זכריה י״ד:ב׳) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלַ ם לַמִלְחָמָה וְגו'. וּכְתִיב, (תהילים ב׳:ב׳) יִתְיַצְּבוּ מַלְכֵי אֶרֶץ וְרוֹזְנִים נוֹסְדוּ יָחַד עַל יְיָ וְעַל מְשִׁיחוֹ. וּכְתִיב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק יְיָ יִלְעַג לָמוֹ.","לְבָתַר וא\"ו זְעִירָא יִתְעָר לְאִתְחַבָּרָא וּלְחַדְּשָׁא נִשְׁמָתִין דְּהֲווּ עַתִּיקִין בְּגִין לְחַדְתָּא עַלְמָא כְּמָה דִכְתִיב, (שם קד) יִשְׂמַח יְיָ בְּמַעֲשָׂיו וּכְתִיב יְהִי כְבוֹד יְיָ לְעוֹלָם לְאִתְחַבָּרָא כְּדְקָא יְאוּת. יִשְׂמַח יְיָ בְּמַעֲשָׂיו לְנַחֲתָא לוֹן לְעָלְמָא וּלְמֶהֱוֵי כֻּלְּהוֹן בְּרִיָין חַדְתִּין לְחַבְּרָא עַלְמִין כֻּלְּהוּ כְּחַד.","זַכָּאִין אִנּוּן כָּל אִנּוּן דְּיִשְׁתָּאֲרוּן בְּעַלְמָא בִּסְיָיפֵי אֶלֶף שְׁתִיתָאָה לְמֵיעַל בְּשַׁבַּתָּא, דְּהָא כְּדֵין אִיהוּ יוֹמָא חַד לְקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי לְאִזְדַּוְּוגָא כְּדְקָא יְאוּת וּלְמִלְקַט נִשְׁמָתִין חַדְתִּין לְמֶהֱוֵי בְּעַלְמָא עִם אִנּוּן דְּאִשְׁתָּאֲרוּ בְּקַדְמִיתָא דִּכְתִיב, (ישעיהו ד׳:ג׳) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּיְרוּשָׁלַם קָדוֹשׁ יֵאָמֵר לוֹ כָּל הַכָּתוּב לְחַיִּים בִּיְרוּשָׁלַ ם:","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וַיֹּאמֶר אֵלָיו אַבְרָהָם וַיֹּאמֶר הִנִּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר (תהלים מה) אַתָּה הוּא מַלְכִּי וְגו'. דָּא הוּא שְׁלִימוּ דְּכָל דַּרְגִּין כְּחֲדָא דָּא בְּדָא."],[[0,"א\"ל אי חייבא וכו':","אמר לו אם הוא רשע, ולא הגיע ימיו לעשרים שנה, מהו. אם נסתלק מעולם, מאין בא עונשו, כי לא תוכל לומר כדי שימות צדיק, כי הוא רשע ולא צדיק."],[0,"א\"ל בדא וכו':","אמר לו בזה נתקיים ויש נספה בלא משפט. דהיינו שנענש בלי משפט, כי כאשר העונש ירד לעולם, הוא היינו הפחות מעשרים שנה, פוגע במחבל ההוא המעניש, בלי כונה למעלה ולמטה, כלומר בלי כונה מב\"ד של מעלה ובלי כונה מב\"ד של מטה, והוא נענש, רק משום שלא השגיחו עליו למעלה לשומרו שלא יפגע המחבל. וכיון שנפגש עם המחבל, וכבר אינו מבחין בין טוב לרע, (כנ\"ל בדף ק\"ח אות ש\"ע ע\"ש)."],[1,"ועליה כתיב וכו':","ועליו כתוב עונותיו ילכדנו את הרשע, \u0003את\u0004 הוא לרבות מי שעוד לא הגיע זמנו להענש, \u0003עונותיו ילכדנו\u0004 ולא בית דין של מעלה, ובחבלי חטאתו יתמך, ולא בית דין של מטה משום זה כתוב, כי שמע אלקים אל קול הנער באשר הוא שם. שעוד לא היה ראוי להענש על חטאיו, וע\"כ שמע אלקים את קולו אע\"פ שהיה רשע."],[2,"ר\"ש פתח ואמר, וזכרתי את בריתי יעקוב:","יעקב הוא מלא עם \u0003ו',\u0004 ושואל למה. ואומר, בב' צדדים הוא, סוד החכמה א' שהוא, היינו ה \u0003ו'\u0004 סוד מדרגת החכמה במקום שיעקב שורה בו. שהוא ת\"ת דאצילות, סוד קו אמצעי. והמילוי \u0003ו'\u0004 שביעקב יורה על יסוד, שהוא סוד החכמה שבפרצוף, (כנ\"ל בהקדמת הזהר דף י\"א ד\"ה וז\"ש ואיטמירו ע\"ש). ות\"ת ויסוד כאחד הם בסוד \u0003וו\u0004 (כנ\"ל דף קל\"ג אות תנ\"א) וע\"כ כתוב יעקוב עם \u0003ו'\u0004 לרמז על חיבורו עם היסוד, שהוא שלמותו בסוד החכמה."],[2,"אבל האי קרא וכו':","ושנית, אבל מקרא זה נאמר על גלות ישראל, כי כשהם בגלות בשעה שיהיו נפקדים מהגלות, יהיו נפקדים בסוד ה \u0003ו'.\u0004 שהוא באלף הששי, וע\"כ כתוב יעקוב עם \u0003ו'.\u0004 לרמז שיעקב, דהיינו בני ישראל יגאלו ב \u0003ו'\u0004 שהוא אלף הששי."],[3,"ופקידה ברזא דו':","והפקודה בסוד ה \u0003ו'\u0004 הוא ששה רגעים וחצי עת. ובזמן ששים שנה, לבריח הדלת, באלף הששי, ה \u0003ו'\u0004 דהיינו ת\"ת ה\"ס בריח התיכון המבריח בתוך הקרשים מקצה אל הקצה, וע\"כ מכונה בריח הדלת. יקום אלקי השמים פקידה לבת יעקב. ומזמן ההוא עד שיהיה לה זכירה ימשך שש שנים ומחצה, שהוא זמן המשכת הפקידה, ומזמן ההוא ימשך ששה שנים אחרים, שהוא זמן המשכת הזכירה, והם שבעים ושנים שנים ומחצה."],[3,"","פירוש. כי אין לך הארה, שלא תתגלה בשתים, בקטנות וגדלות. תחילה בקטנות שהוא בחינת ו\"ק המאיר רק ממטה למעלה שהיא \u0003אור נקבה.\u0004 וגילוי זה נקרא \u0003פקידה,\u0004 ואחר כך נגלה הגדלות, שהוא אור הג\"ר, המאיר ממעלה למטה, וגילוי זה נקרא \u0003זכירה.\u0004 כלומר, \u0003אור זכר.\u0004 וסימנך שהנקבה נולדה ופניה למעלה, והזכר נולד ופניו למטה, ולפיכך בלידת יצחק כתיב תחילה וה' פקד את שרה, שה\"ס אור נקבה, הנקרא \u0003פקידה,\u0004 ועוד אינה ראויה להוליד עד שנמשך לה הזכירה, וע\"כ כתוב פעם ב', ויעש ה' לשרה כאשר דבר, שהוא \u0003זכירה,\u0004 כי כתוב כאן עשיה, ועשיה בחינת זכר הוא, כי אור נקבה אין בה עשיה, כי אשה קרקע עולם הוא (כמ\"ש לעיל דף קכ\"ו ד\"ה ועל דא), ע\"ש. וכן בגאולה העתידה. שהו' יקים לה' באור הגדול השלם, בסו\"ה והיה אור הלבנה כאור החמה, הנה גם כן מתחילה תתגלה הפקידה של אור הגדול הזה, ואח\"כ הזכירה. וז\"ש \u0003ופקידה ברזא דו' שית רגעי ופלג עידן.\u0004 שהפקידה הנמשכת בסוד הו', תאיר רק שש רגעים, שה\"ס חג\"ת נה\"י, המאירים בה מהתכללות הזכר, ומבחינתה עצמה אין לה רק חצי עת, דהיינו חצי המלכות הנקראת עת (לעיל דף ק\"ל אות תל\"ט) דהיינו רק מחזה ולמעלה שבה, ולא מחזה ולמטה, שהוא מטעם היותה עוד בבחינת הפקידה, שהיא אור נקבה, שאינו מאיר ממעלה למטה, וע\"כ חסר בה חצי עת, דהיינו מחזה ולמטה. ומשום זה תמשכנה שני הפקידה, שש שנים ומחצה מששים שנה עד ס\"ו ומחצה. ואז תתגלה מסוד הו' אור \u0003הזכירה,\u0004 שהוא אור זכר, ואז יתגלה מלך המשיח, כמ\"ש לפנינו, שהוא זכר וסוד ו', והארתו תמשך שש שנים אחרים כמ\"ש להלן."],[4,"בשתין ושית יתגלי מלכא משיחא:","בששים ושש שנים יתגלה מלך המשיח בארץ הגליל, והוא משיח בן יוסף, וע\"כ מקום גילוי שלו ארץ הגליל, שהוא נחלת יוסף (כמ\"ש בזהר ויקהל אוח תצ\"ג) וכאשר כוכב שבצד מזרח יבלע שבע כוכבים שמצד צפון, ושלהבת אש שחור תהיה תלויה ברקיע ששים ימים, ומלחמות יתעוררו בעולם על צד צפון, וב' מלכים יפלו באלו המלחמות, ויתחברו כל העמים על בת יעקב, לדחותה מן העולם, שעל אותו הזמן כתוב, ועת צרה היא ליעקב וממנה יושע, הנה אז יכלו כל הנפשות מגוף, וצריכים לחזור ולהתחדש. וסימנך, כל הנפש הבאה ליעקב מצרימה וגו', כל נפש ששים ושש."],[4,"","ביאור הדברים. כי מטרם גאולה השלמה העתידה, אע\"פ שהיו גאולות, דהיינו ממצרים ומבבל, היו רק מכח אורות וכלים של אמא, בסוד אמא אוזיפת לברתא מאנהא, (כנ\"ל בהקדמת הזהר דף כ'\"ו ד\"ה ואמא ע\"ש) אבל המלכות עצמה מצד עצמה לא היה לה עוד שום גאולה, שז\"ס הקשת שמאירים בה רק ג' גוונים, לבן, אדום, ירוק, שהם חג\"ת, וגוון שלה עצמה, שה\"ס גוון שחור, אינו מאיר בה כלל, (כנ\"ל ב\"א דף ע\"ו ד\"ה כן ע\"ש) שזה סוד, שהמלכות לית לה מגרמה ולא מידי. אלא שצריכה לקבל מז\"א בעלה, שהוא משפיע לה מאורות וכלים דאמא. אבל גאולה השלמה, פירושה, שהמלכות עצמה תבנה, דהיינו בכלים ואורות של עצמה, ולא תהיה צריכה עוד לקבל מז\"א אורות וכלים דאמא, וז\"ס והיה אור הלבנה כאור החמה וגו'."],[4,"","ונבאר תחילה המאמר בדרך כלל. וכבר ידעת שהפרט והכלל שוים זה לזה, וכמו שבגאולות הקודמות של המלכות נבנה המלכות בסדר ג' קוין, ואח\"כ נבנית בחינתה, בסוד כלי הקבלה של ג' קוין, כן בגאולה הכוללת העתידה, צריך אור הגאולה לתקן את המלכות בזה אחר זה, בסוד ג' קוין, ואח\"כ בחינתה עצמה המקבלת מה שיש בג' הקוין, ואח\"ז תהיה לה כל השלימות הראויה לזווג השלם. שהם ה' בחינות תקון. ובזה תבין סדר זמנים שחושב כאן. כי תקון א) הוא מס' עד ס\"ו ופלגא, יתוקן קו ימין שבה, שעל תקון זה מספיק אור הפקידה. ומס\"ו עד ע\"ג שנים מתחיל אור הזכירה, והוא תקון ב) שאז יתוקן קו שמאל שבה, וע\"כ יתגלה אז משיח בן יוסף בארץ הגליל, שהוא המתקן מצד השמאל. וכל האותות שהזהר חושב באותו הזמן, באים כולם מכח הדינים, הנוהגים תמיד בהארת השמאל, תקון ג), הוא מע\"ג שנים עד מאה שנים, שאז יתוקן קו אמצעי שבה, וע\"כ יתגלה אז משיח בן דוד, שהוא המתקן מצד קו האמצעי, תקון ד), הוא בחינתה עצמה, לקבל כל מה שיש בג' הקוין, והוא ממאה שנים עד סייפי אלף שתיתאה. ולפיכך יתחיל אז הזווג של הו' ב \u0003ה'.\u0004 וכל נשמות הישנות, דהיינו אותו שיצאו מימות בריאת העולם עד סוף אלף הששי, יקבלו אז התחדשות בשלימות גדול עד מאד. תקון ה), היא אלף השביעי, שאז כבר נשלמה המלכות בתכלית שלימותה, ויהיה יום אחד להקב\"ה לאזדווגא כדקא יאות (כמ\"ש באות תפ\"ג) ואז יולדו נשמות חדשות, שעוד לא היו כלל מיום בריאת העולם עד אלף הז'."],[4,"","וזה אמרו \u0003בשתין ושית יתגלי מלכא משיחא בארעא דגליל.\u0004 שהוא משיח בן יוסף, המתגלה בנחלתו כנ\"ל, וזמנו ז' שנים עד ע\"ג שנים. והסוד הוא, כי הוא בא לתקן עם אור הזכירה את מחצית המלכות שהיתה עוד חסרה באור הפקידה, (כמ\"ש לעיל בדיבור הסמוך), שזמנו היה, \u0003שית שנין ופלגא,\u0004 ע\"ש, והוא מטעם היותו אור ו\"ק, ועתה שהגיע אור הזכירה שהוא ג\"ר, נגלה משיח בן יוסף תחילה, כדי לתקן את כל קו השמאל דהיינו ז' שנים שלמים, שיורה שגם המלכות תתקנה כולה, ואפילו מחזה ולמטה כנ\"ל, שה\"ס תקון ב). כי בגאולות הקודמות נתתקן קו השמאל שלה, רק מכח עליתה למקום אמא, שקבלה הקו שמאל של אמא, (כנ\"ל ב\"א דף רל\"ד ד\"ה וכן) אבל עתה תתוקן קו השמאל שבה עצמה במקומה למטה ואינה צריכה עוד לקו שמאל דאמא."],[4,"","וזה אמרו. \u0003וכד ככבא דבסטר מזרח יבלע שבע ככביא מסטר צפון,\u0004 כי ד' רוחות, הם חו\"ב תו\"מ, ונמצא בינה צד צפין, ותפארת צד מזרח. וסוד הזכירה ה\"ס אור הו' שהוא ת\"ת, שה\"ס ככב מסטר מזרח, שיתקן את המלכות בקו שמאל מבחינתה עצמה, נמצא שמבטל בזה, את צד שמאל דאמא שה\"ס צד צפון שהיה בבנין המלכות עד הנה. והוא מובן כמו שהוא בולע לתוכו, את ז' ככבים דבינה, ואומרו, ז' ככבים, היינו ז\"ס חג\"ת נהי\"ם הכלולים בקו שמאל."],[4,"","וזה אמרו, \u0003ושלהובא דאשא אוכמא תהא תליא ברקיעא שתין יומין.\u0004 כי הדינים הבאים לעולם בעת הארת השמאל מכונים שלהבת אש, ועד עתה היה השלהבת אש בגוון אדום, להיותו מבחינת בינה, ולא ממלכות עצמה כנ\"ל, כי ד' הגוונים לבן אדום ירוק שחור הם חו\"ב תו\"מ, (כנ\"ל ב\"א דף ג' ד\"ה כד) ונמצא גוון אדום שהוא בינה. אבל עתה שהמלכות השיגה אורות וכלים מבחינתה עצמה, וקו השמאל נמשך לה בכלים שלה, שה\"ס גוון שחור, נמצא שגם השלהבת אש הבא עם הארת השמאל הוא ג\"כ בגוון שחור, ולפיכך אומר \u0003ושלהובא דאשא אוכמא תהא תליא ברקיעא.\u0004 ומספר \u0003שיתין יומין,\u0004 ה\"ס ששים גבורים, שכן מכונה הארת השמאל. שזה מלמדנו, שאע\"פ שהוא אור ג\"ר, מכל מקום אינו אלא ג\"ר שבו\"ק, שכל קצה כלול מעשר, והם במספר ששים. ויומין ה\"ס ספירות, כנודע."],[4,"","וזה אמרו, \u0003וקרבין יתערון בעלמא לסטר צפון, ותרין מלכין יפלון באינון קרבין,\u0004 כי מכח הדינים שבהארת השמאל ימשכו מלחמות בעולם, ומשום שהמזרח יבלע אז את הצפון כנ\"ל, ימשכו גם הדינים כן, ממזרח לצפון. וב' מלכים יפלו באלו המלחמות, אחד מאומות העולם, ואחד מישראל, שהוא משיח בן יוסף. וז\"ש \u0003ויזדווגון כולהון עממיא על ברתא דיעקב, לאדחייא לה מעלמא,\u0004 כי אחר נפילת משיח בן יוסף, יתגברו האומות מאד, וירצו לדחות את ישראל מעולם. וז\"ש ועל ההוא זמנא כתיב ועת צרה וגו'. כלומר שאלו הדינים והצרות לא יבואו בתורת עונשים אלא כדי שיהיו אחר כך כלים לישועה השלמה. וז\"ס \u0003וממנה יושע.\u0004"],[4,"","וזה אמרו, \u0003וכדין יסתיימון נפשין מגופא,\u0004 שמחמת הדינים והצרות שיהיו אז יתרוקנו כחות הנפשות שהיו פעם בגוף, כלומר לא לבד הנפשות מאותו הדור אלא הנפשות מכל הדורות שמיום בריאת העולם עד אז, שהיו פעם בגוף כולן יחלשו ויכלה כחם, עד \u0003ובעיין לאתחדשא,\u0004 שהן צריכות ומוכרחות להתחדש."],[6,"בשבעין ותלת וגו':","בשבעים ושלש שנים, דהיינו אחר ז' שנים לגילוי משיח בן יוסף, כל מלכי העולם יתאספו לעיר הגדולה רומי, והקב\"ה יעיר עליהם אש וברד ואבני אלגביש ויאבדו מעולם. ורק אותם המלכים שלא באו לרומי, ישארו בעולם, שיחזרו אח\"כ לעשות מלחמות אחרות. ובזמן ההוא יעיר מלך המשיח בכל העולם, ויתאספו אליו כמה עמים וכמה צבאות מכל קצוי העולם. וכל בני ישראל יתאספו במקומותיהם."],[6,"","פירוש, כי כאן נתתקן קו אמצעי, שענינו הוא להכניע השמאל באופן שיכלל בקו ימין, וכן ימין בשמאל, ואז נשלם המדרגה מכל הצדדים (כנ\"ל ב\"א דף ט\"ז ד\"ה וזה). וז\"ש \u0003בשבעין ותלת כל מלכי עלמא,\u0004 דהיינו כל אלו שכחם הוא משמאל, \u0003יתכנשון לגו קרתא רבתא דרומי,\u0004 שהוא הראש לכל כחות השמאל, \u0003וקב\"ה יתער עלייהו וכו' ויתאבדון מעלמא,\u0004 כי ע\"י הארת קו אמצעי נתבטאו כל הדינים, וכחות השמאל נאבדים מן העולם, \u0003בר אינון מלכין דלא ימטון לתמן,\u0004 דהיינו אותם הנמשכים מקליפות הימין, שלא באו לרומי שהיא שמאל, \u0003ויהדרון לאגחא קרבין אחרנין,\u0004 כי בעת תקון הד' יגיע זמן של כחות הימין להלחם בישראל כמ\"ש לפנינו. \u0003ומההוא זמנא מלכא משיחא יתער וכו',\u0004 והיינו משיח בן דוד, הנמשך מן קו אמצעי, וע\"כ מגיע זמנו להתגלות עם תקונו. \u0003וכל בני ישראל יתכנשון בכל אנון אתרי,\u0004 כי אז מתחיל קבוץ גליות, והם מתקבצים במקומותיהם ללכת לירושלים. אבל עוד אינם הולכים מטרם ביאת תקון הד', שהיא תקון המלכות, שתקבל הארת ג' הקוין בתוכה, ואז מתקבצים כל ישראל ובאים לירושלים."],[7,"עד דאשתלימו אינון שנין למאה וכו':","עד שנשלמו השנים, והגיעו למאה שנים לאלף הששי, אז יתחבר ה \u0003ו'\u0004 ב \u0003ה',\u0004 שישפיעו תקוני ג' הקוין הנ\"ל אל ה \u0003ה'\u0004 שהיא המלכות, דהיינו תקון הד' הנ\"ל. ואז והביאו את כל אחיכם מכל הגוים מנחה לה' ואז יהיה קבוץ גליות. ועתידים בני ישמעאל שהם הראש, לכל כחות הקליפות מימין כמו רומי לכחות השמאל בזמן ההוא, להתעורר יחד עם כל עמי העולם, שלא באו לרומי כנ\"ל, לבא על ירושלים למלחמה, שכתוב, ואספתי את כל הגוים אל ירושלים למלחמה וגו'. וכתוב יתיצבו מלכי ארץ וגו'. וכתוב יושב בשמים ישחק וגו'."],[8,"לבתר ו' זעירא וכו':","אחר כך, דהיינו אחר שכל כחות הס\"א הימין והשמאל יאבדו מהעולם, יתעורר \u0003ו'\u0004 הקטנה, שהוא יסוד דז\"א, להתחבר עם ה \u0003ה',\u0004 ולחדש נשמות הישנות, דהיינו כל אותם שהיו בגוף, מעת בריאת העולם עד אז, (כנ\"ל דף קל\"א ד\"ה וכד עש\"ה) כדי לחדש העולם, שהוא המלכות כמו שכתוב, ישמח ה' במעשיו. וכתוב יהי כבוד ה' לעולם, פירושו, כדי שתתחבר ה \u0003ה'\u0004 עם הו' כראוי. ישמח ה' במעשיו, פירושו, להוריד מעשיו, שהם הנשמות שנתחדשו לעולם, שתהינה כולם בריות חדשות, ויתחברו כל העולמות כולם כאחד."],[9,"זכאין אינון וכו':","אשרי הם כל אלו שישארו בעולם בסוף אלף הששי לכנוס בשבת, שהוא אלף השביעי, כי אז הוא יום אחד לה' לבדו, להזדווג עם ה \u0003ה'\u0004 כראוי, וללקוט נשמות חדשות להשפיע לעולם, דהיינו נשמות שלא היו עוד בעולם, שיהיו בעולם, ביחד עם נשמות הישנות שנשארו מתחילה, דהיינו שנתחדשו כנ\"ל, שכתוב, והיה הנשאר בציון והנותר בירושלים קדוש יאמר לו כל הכתוב לחיים בירושלים."],[10,"ויהי אחר וגו' ויאמר הנני:","ר' יהודה פתח ואמר. אתה הוא מלכי אלקים וגו', זה הוא שלימות כל המדרגות כאחד קשורות זו בזו. כי יש בכתוב הזה חג\"ת ומלכות, שהם כללות כל המדרגות. כי \u0003אתה\u0004 הוא חסד בסו\"ה אתה כהן לעולם. \u0003אלקים\u0004 הוא גבורה. \u0003הוא\u0004 הוא ת\"ת. \u0003מלכי\u0004 הוא מלכות."]],[[0,"","אָמַר לוֹ, אִם אֵינוֹ חַיָּב וְלֹא הִגִּיעוּ יָמָיו לְעֶשְׂרִים שָׁנָה, כֵּיוָן שֶׁהִסְתַּלֵּק מֵהָעוֹלָם בַּמָּה הוּא עָנְשׁוֹ? אָמַר לוֹ, בָּזֶה מִתְקַיֵּם, (משלי יג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. שֶׁכְּשֶׁעֹנֶשׁ יוֹרֵד לָעוֹלָם, הוּא (הדין) פּוֹגֵעַ בְּלִי כַוָּנָה לְמַעְלָה וּלְמַטָּה בְּאוֹתוֹ מַשְׁחִית, וְיֵעָנֵשׁ כְּשֶׁלֹּא מַשְׁגִּיחִים עָלָיו מִלְמַעְלָה."],[1,"","וְעָלָיו כָּתוּב (שם ה) עֲווֹנוֹתָיו יִלְכְּדֻנוֹ אֶת הָרָשָׁע. אֶת - לְרַבּוֹת מִי שֶׁלֹּא הִגִּיעוּ יָמָיו לְהֵעָנֵשׁ. עֲווֹנוֹתָיו יִלְכְּדֻנוֹ (את הרשע), וְלֹא בֵּית הַדִּין שֶׁלְּמַעְלָה. וּבְחַבְלֵי חַטָּאתוֹ יִתָּמֵךְ, וְלֹא בֵּית דִּין שֶׁלְּמַטָּה. לָכֵן כָּתוּב כִּי שָׁמַע אֱלֹהִים אֶל קוֹל הַנַּעַר בַּאֲשֶׁר הוּא שָׁם."],[2,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ויקרא כו) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. מָלֵא בְּוָא\"ו לָמָּה? אֶלָּא בִּשְׁנֵי צְדָדִים הוּא (הם). סוֹד שֶׁל חָכְמָה אֶחָד. שֶׁהוּא הַסּוֹד שֶׁל דַּרְגָּה שֶׁל חָכְמָה, הַמָּקוֹם שֶׁשּׁוֹרֶה בּוֹ יַעֲקֹב. אֲבָל פָּסוּק זֶה נֶאֱמַר עַל הַגָּלוּת שֶׁל יִשְׂרָאֵל. שֶׁכְּשֶׁהֵם בְּתוֹךְ הַגָּלוּת, אוֹתוֹ זְמַן שֶׁיִּפָּקְדוּ (בו י קב), הֵם יִפָּקְדוּ בַּסּוֹד שֶׁל וָא\"ו, וְהוּא בָּאֶלֶף הַשִּׁשִּׁי."],[3,"","וּפְקִידָה בְּסוֹד שֶׁל וָא\"ו שִׁשָּׁה רְגָעִים וַחֲצִי זְמַן. וּבִזְמַן שֶׁל שִׁשִּׁים שָׁנִים לִבְרִיחַ הַדֶּלֶת בָּאֶלֶף הַשִּׁשִּׁי, יָקִים אֱלֹהֵי הַשָּׁמַיִם פְּקִידָה לְבַת יַעֲקֹב. וּמֵאוֹתוֹ זְמַן עַד שֶׁיִּהְיֶה לָהּ זְכִירָה - שֵׁשׁ שָׁנִים וָחֵצִי. וּמֵאוֹתוֹ זְמַן שֵׁשׁ שָׁנִים אֲחֵרוֹת, וְהֵם שִׁבְעִים (ושלש) וּשְׁתַּיִם וָחֵצִי."],[4,"","בְּשִׁשִּׁים וָשֵׁשׁ יִתְגַּלֶּה מֶלֶךְ הַמָּשִׁיחַ בְּאֶרֶץ הַגָּלִיל, וְכוֹכָב אֶחָד בְּצַד מִזְרָח יִבְלַע שִׁבְעָה כּוֹכָבִים מִצַּד צָפוֹן, וְשַׁלְהֶבֶת אֵשׁ שְׁחוֹרָה תִּהְיֶה תְלוּיָה בָּרָקִיעַ שִׁשִּׁים יוֹם, וּקְרָבוֹת יִתְעוֹרְרוּ בָעוֹלָם לְצַד צָפוֹן, וּשְׁנֵי מְלָכִים יִפְּלוּ בְּאוֹתָם קְרָבוֹת."],[5,"","וְיִזְדַּוְּגוּ כָּל הָעַמִּים עַל בַּת יַעֲקֹב לִדְחוֹת אוֹתָהּ (אותם) מֵהָעוֹלָם. וְעַל אוֹתוֹ הַזְּמַן כָּתוּב, (והיתה) (ירמיה ל) וְעֵת צָרָה הִיא לְיַעֲקֹב וּמִמֶּנָּה יִוָּשֵׁעַ, וְאָז יִסְתַּיְּמוּ הַנְּפָשׁוֹת מֵהַגּוּף וְרוֹצִים לְהִתְחַדֵּשׁ, וְסִימָן לַדָּבָר - (כל הנפש לבית יעקב הבאה מצרימה שבעים, וכתוב) (בראשית מו) כָּל הַנֶּפֶשׁ הַבָּאָה לְיַעֲקֹב מִצְרַיְמָה וְגוֹ', כָּל נֶפֶשׁ שִׁשִּׁים וָשֵׁשׁ."],[6,"","בְּשִׁבְעִים וְשָׁלֹשׁ כָּל מַלְכֵי הָעוֹלָם יִתְכַּנְּסוּ לְתוֹךְ הָעִיר הַגְּדוֹלָה שֶׁל רוֹמִי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר עֲלֵיהֶם אֵשׁ וּבָרָד וְאַבְנֵי אֶלְגָּבִישׁ וְיאבְדוּ מֵהָעוֹלָם, פְּרָט לְאוֹתָם מְלָכִים שֶׁלֹּא יַגִּיעוּ לְשָׁם וְיַחְזְרוּ לְעוֹרֵר קְרָבוֹת אֲחֵרִים. וּמֵאוֹתוֹ זְמַן מֶלֶךְ הַמָּשִׁיחַ יִתְעוֹרֵר בְּכָל הָעוֹלָם, וְיִתְכַּנְּסוּ עִמּוֹ כַּמָּה עַמִּים וְכַמָּה חֲיָלוֹת מִכָּל סוֹפֵי הָעוֹלָם, וְכָל בְּנֵי יִשְׂרָאֵל יִתְכַּנְּסוּ בְּכָל אוֹתָם מְקוֹמוֹת."],[7,"","עַד שֶׁיִּשְׁלְמוּ אוֹתָן שָׁנִים לְמֵאָה. אָז וָא\"ו תִּתְחַבֵּר עִם הֵ\"א, וְאָז (ישעיה סו) וְהֵבִיאוּ אֶת כָּל אֲחֵיכֶם מִכָּל הַגּוֹיִם מִנְחָה לַה' וְגוֹ'. וּבְנֵי יִשְׁמָעֵאל (ישראל) עֲתִידִים בְּאוֹתוֹ זְמַן לְהִתְעוֹרֵר (עליהם) עִם כָּל עַמֵּי הָעוֹלָם לָבא עַל יְרוּשָׁלַיִם, שֶׁכָּתוּב (זכריה יד) וְאָסַפְתִּי אֶת כָּל הַגּוֹיִם אֶל יְרוּשָׁלַיִם לַמִּלְחָמָה וְגוֹ'. וְכָתוּב (תהלים ב) יִתְיַצְּבוּ מַלְכֵי אֶרֶץ וְרוֹזְנִים נוֹסְדוּ יָחַד עַל ה' וְעַל מְשִׁיחוֹ. וְכָתוּב יוֹשֵׁב בַּשָּׁמַיִם יִשְׂחָק ה' יִלְעַג לָמוֹ."],[8,"","אַחַר כָּךְ וָא\"ו קְטַנָּה תִּתְעוֹרֵר לְהִתְחַבֵּר וּלְחַדֵּשׁ נְשָׁמוֹת שֶׁהָיוּ יְשָׁנוֹת כְּדֵי לְחַדֵּשׁ אֶת הָעוֹלָם, כְּמוֹ שֶׁכָּתוּב (שם קד) יִשְׂמַח ה' בְּמַעֲשָׂיו. וְכָתוּב יְהִי כְבוֹד ה' לְעוֹלָם, לְהִתְחַבֵּר כָּרָאוּי. יִשְׂמַח ה' בְּמַעֲשָׂיו, לְהוֹרִיד אוֹתָם לָעוֹלָם, וְשֶׁכֻּלָּם יִהְיוּ בְרִיּוֹת חֲדָשׁוֹת לְחַבֵּר אֶת כָּל הָעוֹלָמוֹת יַחַד."],[9,"","אַשְׁרֵיהֶם כָּל אוֹתָם שֶׁיִּשָּׁאֲרוּ בְּסוֹף הָאֶלֶף הַשִּׁשִּׁי לְהִכָּנֵס לְשַׁבָּת, שֶׁהֲרֵי אָז הוּא יוֹם אֶחָד לַקָּבָּ\"ה לְבַדּוֹ, לְהִזְדַּוֵּג כָּרָאוּי וְלִלְקֹט נְשָׁמוֹת חֲדָשׁוֹת שֶׁיִּהְיוּ בָעוֹלָם עִם אוֹתָם שֶׁנִּשְׁאֲרוּ בָרִאשׁוֹנָה, שֶׁכָּתוּב (ישעיה ד) וְהָיָה הַנִּשְׁאָר בְּצִיּוֹן וְהַנּוֹתָר בִּירוּשָׁלם קָדוֹשׁ יֵאָמֶר לוֹ כָּל הַכָּתוּב לַחַיִּים בִּירוּשָׁלם."],[10,"","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וַיֹּאמֶר אֵלָיו אַבְרָהָם וַיֹּאמֶר הִנֵּנִי. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים מד) אַתָּה הוּא מַלְכִּי וְגוֹ'. זוֹהִי הַשְּׁלֵמוּת שֶׁל כָּל הַדְּרָגוֹת יַחַד זוֹ עִם זוֹ."]]],[["צַוֵּה יְשׁוּעוֹת יַעֲקֹב, כָּל אִנּוּן שְׁלִיחָן דְּעַבְדֵּי שְׁלִיחוּתָא בְּעַלְמָא דְלֶיהוֵי כֻּלְּהוּ מִסִּטְרָא דְרַחֲמֵי וְלָא לֶהווֹ מִסִּטְרָא דְדִינָא, בְּגִין דְּאִית מָארֵי שְׁלִיחָן מִסִּטְרָא דְרַחֲמֵי וּמִסִּטְרָא דְדִינָא קַשְׁיָא. אִנּוּן שְׁלִיחָן דְּאַתְיָין מִסִּטְרָא דְרַחֲמֵי לָא עַבְדֵי שְׁלִיחוּתָא דְדִינָא בְּעַלְמָא כְּלָל.","וְאִי תֵימָא הָא מַלְאָכָא דְּאִתְגְּלֵי לֵיהּ לְבִלְעָם הָא תָּנִינָן שְׁלִיחָא דְּרַחֲמֵי הֲוָה וְאִתְהַפַּךְ לְדִינָא. לָא. לְעוֹלָם לָא אִשְׁתַּנֵּי, אֶלָּא שְׁלִיחָא דְרַחֲמֵי הֲוָה לַאֲגָנָא עֲלַיְיהוּ דְיִשְׂרָאֵל וּלְמֶהֱוֵי סַנֵּיגוֹרְיָא עֲלַיְיהוּ, וּלְקֳבְלֵיהּ הוּא דִינָא, וְכָךְ אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד אוֹטִיב לְדָא הַהוּא טִיבוּ דִּינָא לְדָא. כָּךְ הָא שְׁלִיחָא דְרַחֲמֵי הֲוָה לְהוּ לְיִשְׂרָאֵל וּלְבִלְעָם אִתְהַפַּךְ לְדִינָא. בְגִין כָּךְ צַוֵּה יְשׁוּעוֹת יַעֲקֹב, אָמַר דָוִד, פַּקִּיד עַל עַלְמָא כַּד יִשְׁתַּלְּחוּן שְׁלִיחָאָה דִּי לֶהֶוְיָן מִסִּטְרָא דְרַחֲמֵי.","רַבִּי אַבָּא אָמַר צַוֵּה יְשׁוּעוֹת יַעֲקֹב דְּאִנּוּן גּוֹ גַלְוָותָא וְיִשְׁתַּכַּח פּוּרְקָנָא לְהוֹן גּוֹ גָּלוּתְהוֹן. תָּא חֲזֵי, תּוּשְׁבְּחָן דְּאֲבָהָן יַעֲקֹב הֲוָה, וְאִלְמָלֵא יִצְחָק לָא אֲתָא יַעֲקֹב לְעַלְמָא, וּבְגִין כָּךְ צַוִּה יְשׁוּעוֹת יַעֲקֹב דָּא יִצְחָק, דְּכֵיוָן דְּאִשְׁתְּזִיב יִצְחָק יְשׁועוֹת יַעֲקֹב הֲווּ.","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי שִׁמְעוֹן אָמַר הָא תָּנִינָן וַיְהִי בִּימֵי עַל צַעֲרָא אִתְּמָר, וַיְהִי אַף עַל גַּב דְּלָא כְּתִיב בִּימֵי טַפְסֵי דְצַעֲרָא אִית בֵּיהּ. וַיְהִי אַחַר, בָּתַר דַּרְגָּא תַּתָּאָה דְּכָל דַּרְגִּין עִלָּאִין, וּמַאן אִיהוּ דְּבָרִים, כְּמָא דְאַתְּ אָמֵר (שמות ד׳:י׳) לא אִישׁ דְּבָרִים אָנֹכִי.","וּמַאן הֲוָה בָּתַר דַּרְגָּא דָא, וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם דְּאַתְיָא יֵצֶר הָרָע לְקַטְרְגָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. הָכָא אִית לְאִסְתַּכָּלָא וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם. אֶת יִצְחָק מִבָּעֵי לֵיהּ. דְּהָא יִצְחָק בַּר תְּלָתִין וְשֶׁבַע שְׁנִין הֲוָה וְהָא אֲבוֹי לָאו בַּר עוֹנָשָׁא דִילֵיהּ הֲוָה, דְּאִלְמָלֵא אָמַר יִצְחָק לָא בָעֵינָא לָא אִתְעֲנַשׁ אֲבוֹי עֲלֵיהּ. מַאי טַעְמָא וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְלָא כְּתִיב נִסָּה אֶת יִצְחָק.","אֶלָּא אֶת אַבְרָהָם וַדַּאי דְּבָעֵי לְאִתְכְּלָלָא בְּדִינָא, דְּהָא אַבְרָהָם לָא הֲוָה בֵּיהּ דִּינָא כְּלַל מִקַּדְמַת דְּנָא, וְהַשְׁתָּא אִתְכְּלִיל מַיָי\"א בְּאֶשָׁ\"א. וְאַבְרָהָם לָא הֲוָה שְׁלִים עַד הַשְׁתָּא דְּאִתְעַטַּר לְמֶעְבַּד דִּינָא וּלְאַתְקָנָא לֵיהּ בְּאַתְרֵיהּ.","וְכָל יוֹמוֹי לָא הֲוָה שְׁלִים עַד הַשְׁתָּא דְּאִתְכְּלִיל מַיָ\"א בְּאֶשָׁ\"א וְאֶשָׁ\"א בְּמַיָ\"א, וּבְגִין כָּךְ וְהָאֱלהִים נִסָּה אֶת אַבְרָהָם וְלא אֶת יִצְחָק, דְּאַזְמִין אַבְרָהָם לְאִתְכְּלָלָא בְּדִינָא, וְכַד עָבִיד דָּא, עָאל (קלג ב) אֶשָׁ\"א בְּמַיָ\"א וְאִשְׁתְּלִים דָּא עִם דָּא. וְדָא עָבִיד דִּינָא לְאִתְכְּלָלָא דָּא בְּדָא. וּכְדֵין יֵצֶר הָרָע אֲתָא לְקַטְרְגָא עֲלֵיהּ דְּאַבְרָהָם דְּלָא אִשְׁתְּלִים כְּדְקָא יְאוּת עַד דְּיַעֲבִיד דִּינָא בְּיִצְחָק. דְּיֵצֶר הָרָע אַחַר הַדְּבָרִים אִיהוּ וְאָתָא לְקַטְרְגָא.","וְתָא חֲזֵי רָזָא דְמִלָּה, אַף עַל גַּב דְּקָאֲמָרָן דְּאַבְרָהָם כְּתִיב וְלָא יִצְחָק, יִצְחָק נָמֵי אִתְכְּלִיל בֵּיהּ בְּהַאי קְרָא, רָזָא דִכְתִיב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. נִסָּה לְאַבְרָהָם לָא כְּתִיב אֶלָּא אֶת אַבְרָהָם אֶת דַּיְיקָא וְדָא יִצְחָק. דְּהָא בְּהַהִיא שַׁעֲתָא בִּגְבוּרָ\"ה תַּתָּאָה שַׁרְיָא, כֵּיוָן דְּאִתְעַקַּד וְאִזְדַּמַּן בְּדִינָא עַל יְדָא דְּאַבְרָהָם כְּדְקָא יְאוּת, כְּדֵין אִתְעַטַּר בְּאַתְרֵיהּ בַּהֲדֵיהּ דְּאַבְרָהָם וְאִתְכְּלִילוּ אֶשָׁ\"א בְּמַיָ\"א וּסְלִיקוּ לְעֵילָא, וּכְדֵין אִשְׁתַּכַּח מַחְלוֹקֶת כְּדְקָא יְאוּת מַיָא בְּאֶשָׁא.","מַאן (עבד) חָמָא אַבָּא רַחֲמָנָא דְּאִתְעֲבִיד אַכְזָר. אֶלָּא בְּגִין לְאִשְׁתַּכָּחָא מַחְלוֹקֶת מַיָא בְּאֶשָׁא וּלְאִתְעַטְּרָא בְּאַתְרַייהוּ (ד\"א ל\"ג כדקא יאות), עַד דְּאָתָא יַעֲקֹב וְאִתְתַּקַּן כֹּלָּא כְּדְקָא יְאוּת וְאִתְעֲבִידוּ תְּלָתָא אַבָּהָן שְׁלֵמִין וְאִתְתַּקָנוּ עִלָּאֵי וְתַתָּאֵי:","וַיֹּאמֶר קַח נָא אֶת בִּנְךָ. וְכִי הֵיאַךְ יָכִיל אַבְרָהָם דְּאִיהוּ סָבָא. אִי תֵימָא בְּגִין דְּיִצְחָק לָא נָפִיק מֵרְשׁוּתֵיהּ כְּלַל, יָאוֹת, אֲבָל כְּמָא דְאַתְּ אָמֵר, (במדבר כ׳:כ״ה) קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ אֶלָּא בְּגִין לְאַמְשָׁכָא לוֹן בְּמִלִּין וּלְאַדְבָּרָא לוֹן לִרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, אוּף הָכָא קַח בְּמִלִּין. אֶת בִּנְךָ אֶת יְחִידְךָ אֲשֶׁר אָהַבְתָּ הָא אוּקְמוּהָ. וְלֶךְ לְךָ אֶל אֶרֶץ הַמּוֹרִיָּה כְּמָא דְאַתְּ אָמֵר (שיר השירים ד׳:ו׳) אֵלֵךְ לִי אֶל הַר הַמּוֹר. לְאַתְקָנָא בְּאַתְרָא דְּיִתְחֲזֵי:"],[[0,"צוה ישועות יעקב:","פירושו, שכל אלו השליחים העושים שליחות בעולם יהיו כולם מצד הרחמים, ולא יהיו מצד הדין \u0003בגין דאית מארי וכו':\u0004 משום שיש בעלי השליחות מצד הרחמים, ומצד דין הקשה. ואלו השליחים הבאים מצד הרחמים, אינם עושים בעולם, שליחות של דין כלל."],[1,"ואי תימא וכו':","ואם תאמר הרי המלאך שנגלה לו לבלעם, הרי למדנו שהיה שליח של רחמים ונהפך לדין. הרי, ששליח של רחמים יכול לעשות דין. ומשיב, לא, לעולם לא נשתנה לעשות דין, אלא שליח של רחמים היה להגן על ישראל, ולהיות מליץ טוב עליהם, ולעומתו, לבלעם היה דין."],[1,"וכך ארחוי וכו':","וכך דרכיו של הקב\"ה, כשמטיב לזה, נמצא הטבה זו, שהוא דין לזה, כך זה, שליח של רחמים היה לישראל ולבלעם נהפך לדין. ועל כן בקש, \u0003צוה ישועות יעקב,\u0004 אמר דוד, צוה על העולם, כאשר ישלחו שליח, יהיה מצד הרחמים."],[2,"רבי אבא אמר, צוה וגו':","רא\"א, צוה ישועות יעקב, פירושו, שהתפלל על יעקב, שהם בגלות, שיהיה להם ישועה בעת הגלות. בוא וראה. תפארת האבות היה יעקב, ואלמלא יצחק לא היה בא יעקב לעולם, ומשום זה, צוה ישועות יעקב, היינו יצחק, שהוא ישועתו של יעקב. כי כיון שנצל יצחק בעקדה, ישועת יעקב היה."],[3,"ויהי אחר הדברים האלה:","ר' שמעון אמר, הרי למדנו, \u0003ויהי בימי,\u0004 על צער נאמר. ואם כתוב \u0003ויהי,\u0004 אע\"פ שאינו כתוב \u0003בימי,\u0004 נמצא בו גם כן טופס של צער. \u0003ויהי אחר,\u0004 פירושו, \u0003אחר\u0004 מדרגה התחתונה של מדרגות העליונות דאצילות, ומי היא, היא \u0003דברים,\u0004 דהיינו מלכות, כמו שאתה אומר לא איש דברים אנכי."],[4,"ומאן הוה בתר וכו':","ומי הוא אחר מדרגה זו, אחר המלכות, היינו והאלקים נסה את אברהם, שבא משם היצר הרע לקטרג לפני הקב\"ה, ועל כן נסה את אברהם. ושיעור הכתוב, ויהי \u0003אחר\u0004 הדברים, \u0003ויהי\u0004 קטרוג יצר הרע, שמקומו הוא \u0003אחר\u0004 המלכות הנקראת דברים, וע\"כ והאלקים נסה את אברהם."],[4,"הכא אית לאסתכלא וכו':","כאן יש להסתכל. שכתוב, והאלקים נסה את אברהם, את יצחק היה צריך לומר. שהרי יצחק כבר היה בן שלשים ושבע שנה, ואביו כבר לא היה בן עונשין עליו, שיענש בשבילו, ואלמלי אמר יצחק איני רוצה, לא היה אביו נענש עליו, ואם כן מה הטעם שכתוב, והאלקים נסה את אברהם, ולא כתוב, נסה את יצחק."],[5,"אלא את אברהם ודאי וכו':","ומשיב, אלא ודאי שצריך לומר, \u0003את אברהם\u0004 שהוא היה צריך להכלל בדין, כי לא היה שום דין באברהם מקודם לכן, אלא כולו חסד, ועתה נכלל מים באש, חסד בדין, ואברהם לא היה שלם עד עתה, שנתעטר לעשות דין ולתקן הדין במקומו. פירוש. כי אין הארת החכמה אלא בקו שמאל, וע\"כ מטרם שאברהם נכלל ביצחק שהוא קו שמאל, לא היה שלם, שהיה מחוסר הארת החכמה, ועל ידי מעשה העקדה נכלל ביצחק ונתעטר על ידו בהארת החכמה ונשתלם. וז\"ש שנתעטר לעשות דין, בעקדה, ועל ידי זה נתתקן הדין, שה\"ס הארת שמאל, במקומו, דהיינו שנכלל במקומו של אברהם שהוא חסד."],[6,"וכל יומוי לא הוה שלים וכו':","וכל ימיו לא היה שלם עד עתה, כנ\"ל בסמוך, שנכלל מים באש, ימין בשמאל, ואש במים, שמאל בימין. ומשום זה, והאלקים נסה את אברהם, ולא את יצחק, כי הקב\"ה הזמין את אברהם שיהיה נכלל בדין, בסוד השמאל, וכאשר עשה מעשה העקדה נכנס האש במים, שהדין נכנס בחסד, ונשלם זה עם זה. כמ\"ש לעיל בדיבור הסמוך. וזהו עשה הדין של העקדה שיכלול זה בזה. ועל כן בא יצר הרע לקטרג על אברהם שלא נשלם בראוי, עד שיעשה הדין של העקדה ביצחק. כי היצר הרע נמצא מקומו אחר \u0003הדברים,\u0004 אחר המלכות בסו\"ה לפתח חטאת רובץ, (כנ\"ל ב\"א דף של\"ט ד\"ה מאי לפתח) ובא לקטרג."],[7,"ות\"ח רזא דמלה וכו':","ובוא וראה סוד הדבר. אף על פי שאמרנו, שכתוב אברהם ולא יצחק, הנה יצחק גם כן נכלל במקרא הזה, שכתוב, והאלקים נסה את אברהם, נסה לאברהם אינו כתוב, אלא שכתוב, את אברהם, \u0003את\u0004 הוא בדיוק, והוא רומז על יצחק. כי בשעה ההיא, היה יצחק שורה בגבורה תחתונה, דהיינו בהנוקבא, כיון שנעקד ונועד בדין על ידי אברהם כראוי, אז נתעטר יצחק במקומו עם אברהם, ונכללו אש במים, ועלו למעלה, אברהם בחסד שעלה לחכמה, ויצחק בגבורה שעלה לבינה. ואז נתישב המחלוקת כראוי. כי עשו שלום ביניהם, שנכללו אש ומים זה מזה. (עי' לעיל ב\"א דף רפ\"ד ד\"ה א\"ר יצחק)"],[8,"מאן חמא וכו':","מי ראה אב רחמן שיעשה אכזר על בנו, אלא כדי ליישב את המחלוקת, להכליל מים באש, דהיינו חסד של אברהם באש של יצחק, ויתעטרו במקומם כנ\"ל. והיה זה עד שבא יעקב, שה\"ס קו האמצעי, ונתתקן הכל כראוי, ונעשו שלשה אבות שלמים, דהיינו שנעשו מרכבה לג' קוין העליונים, ונתתקנו העליונים ותחתונים."],[9,"ויאמר קח נא את בנך וגו':","ושואל, וכי איך יכול אברהם לקחת את יצחק בנו, הלא היה זקן. ואם תאמר, שהפירוש הוא, משום שיצחק לא יצא מרשותו, יעשה מה שאברהם יצוה אותו, ועל זה נאמר קח, הוא פירוש טוב. אבל הוא כמו שאתה אומר, קח את אהרן ואת אלעזר בנו, שהפירוש הוא רק להמשיך אותם בדברים, ולהזכירם לעשות רצון הקב\"ה. אף כאן באברהם, הפירוש הוא קח, עם דברים. את בנך את יחידך אשר אהבת, וכבר בארוה. ולך לך אל ארץ המוריה, פירושו כמו שאתה אומר אלך לי אל הר המור, כדי לתקן במקום הראוי לתקן. פירוש, מור ומוריה אחד הוא, והוא מקום המקדש (כמ\"ש בד\"ה ב' ג') ושם מקום ראוי לתקון. וע\"ז מביא הזהר ראיה מהכתוב אלך לי אל הר המור, הנאמר בהקב\"ה, שגם הקב\"ה עצמו הולך שם לתקן את הנוקבא. וע\"כ אמר הקב\"ה גם לאברהם שילך שמה לתקן את עצמו ואת יצחק בנו."]],[[0,"","צַוֵּה יְשׁוּעוֹת יַעֲקֹב, כָּל אוֹתָם הַשְּׁלִיחִים שֶׁעוֹשִׂים שְׁלִיחוּת בָּעוֹלָם, שֶׁכֻּלָּם יִהְיוּ בְּצַד הָרַחֲמִים וְלֹא יִהְיוּ מִצַּד הַדִּין, מִשּׁוּם שֶׁיֵּשׁ בַּעֲלֵי שְׁלִיחִים מִצַּד הָרַחֲמִים וּמִצַּד הַדִּין הַקָּשֶׁה. אוֹתָם שְׁלִיחִים שֶׁבָּאִים מִצַּד הָרַחֲמִים לֹא עוֹשִׂים שְׁלִיחוּת שֶׁל דִּין בָּעוֹלָם כְּלָל."],[1,"","וְאִם תֹּאמַר, הִנֵּה הַמַּלְאָךְ שֶׁהִתְגַּלָּה לְבִלְעָם, הֲרֵי שָׁנִינוּ שָׁלִיחַ שֶׁל רַחֲמִים וְהִתְהַפֵּךְ לְדִין - לֹא! לְעוֹלָם לֹא מִשְׁתַּנֶּה. אֶלָּא שְׁלִיחַ הָרַחֲמִים הָיָה לְהָגֵן עַל יִשְׂרָאֵל וְלִהְיוֹת עֲלֵיהֶם סָנֵגוֹר, וּכְנֶגְדּוֹ הוּא הַדִּין. כָּךְ דְּרָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּשֶׁמֵּיטִיב לָזֶה, אוֹתוֹ הַחֶסֶד הוּא דִין לָזֶה. כֵּן הַשָּׁלִיחַ הַזֶּה הָיָה שֶׁל רַחֲמִים לְיִשְׂרָאֵל, וּלְבִלְעָם הִתְהַפֵּךְ לְדִין, מִשּׁוּם כָּךְ צַוֵּה יְשׁוּעוֹת יַעֲקֹב. אָמַר דָּוִד, צַוֵּה עַל הָעוֹלָם, כַּאֲשֶׁר יִשָּׁלְחוּ שְׁלוּחִים שֶׁיִּהְיוּ מִצַּד הָרַחֲמִים."],[2,"","רַבִּי אַבָּא אָמַר, צַוֵּה יְשׁוּעוֹת יַעֲקֹב, שֶׁהֵם בְּתוֹךְ הַגָּלוּת, וְתִמָּצֵא לָהֶם גְּאֻלָּה בְּתוֹךְ גָּלוּתָם. בּא רְאֵה, הַמְשֻׁבָּח שֶׁל הָאָבוֹת הָיָה יַעֲקֹב, וְאִלְמָלֵא יִצְחָק לֹא בָא יַעֲקֹב לָעוֹלָם. וּמִשּׁוּם כָּךְ, צַוֵּה יְשׁוּעוֹת יַעֲקֹב - זֶה יִצְחָק. שֶׁכֵּיוָן שֶׁנִּצַּל יִצְחָק, הָיוּ יְשׁוּעוֹת יַעֲקֹב."],[3,"","וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. רַבִּי שִׁמְעוֹן אָמַר, הִנֵּה שָׁנִינוּ וַיְהִי בִּימֵי, נֶאֱמַר עַל צַעַר. וַיְהִי - אַף עַל גַּב שֶׁלֹּא כָתוּב בִּימֵי, דְּפוּס שֶׁל צַעַר יֵשׁ בּוֹ. וַיְהִי אַחַר הַדְּבָרִים, אַחַר הַדַּרְגָּה הַתַּחְתּוֹנָה שֶׁל כָּל הַדְּרָגוֹת הָעֶלְיוֹנוֹת. וּמַהוּ הַדְּבָרִים? כְּמוֹ שֶׁנֶּאֱמַר (שמות ד) לֹא אִישׁ דְּבָרִים אָנֹכִי."],[4,"","וּמִי הָיָה אַחַר הַדַּרְגָּה הַזּוֹ? וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. שֶׁבָּא יֵצֶר הָרָע לְקַטְרֵג לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. כָּאן יֵשׁ לְהִסְתַּכֵּל, וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם? אֶת יִצְחָק הָיָה צָרִיךְ (לכתב), שֶׁהֲרֵי יִצְחָק הָיָה בֶּן שְׁלֹשִׁים וָשֶׁבַע, וַהֲרֵי אָבִיו לֹא הָיָה בַּר עֹנֶשׁ שֶׁלּוֹ, שֶׁאִלְמָלֵא אָמַר יִצְחָק אֵינִי רוֹצֶה - לֹא הָיָה נֶעֱנַשׁ אָבִיו עָלָיו. מָה הַטַּעַם וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְלֹא כָתוּב נִסָּה אֶת יִצְחָק?"],[5,"","אֶלָּא אֶת אַבְרָהָם, וַדַּאי שֶׁרָצָה לְהִכָּלֵל עִם דִּין, שֶׁהֲרֵי אַבְרָהָם לֹא הָיָה בּוֹ דִּין כְּלָל מִקֹּדֶם לָכֵן, וְכָאן נִכְלְלוּ מַיִ\"ם עִם אֵ\"שׁ, וְאַבְרָהָם לֹא הָיָה שָׁלֵם עַד עַכְשָׁו, שֶׁהִתְעַטֵּר לַעֲשׂוֹת דִּין וּלְהַתְקִינוֹ בִּמְקוֹמוֹ."],[6,"","וְכָל יָמָיו לֹא הָיָה שָׁלֵם עַד עַכְשָׁו שֶׁנִּכְלַל מַיִ\"ם עִם אֵ\"שׁ וְאֵ\"שׁ עִם מַיִ\"ם, וּמִשּׁוּם כָּךְ וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וְלֹא אֶת יִצְחָק, שֶׁהִזְמִין אַבְרָהָם לְהִכָּלֵל עִם דִּין. וּכְשֶׁעָשָׂה אֶת זֶה, נִכְנַס אֵ\"שׁ עִם מַיִ\"ם וְנִשְׁלַם זֶה עִם זֶה. וְזֶה עוֹשֶׂה הַדִּין לְהִכָּלֵל זֶה עִם זֶה. וְאָז יֵצֶר הָרָע בָּא לְקַטְרֵג עַל אַבְרָהָם שֶׁלֹּא הִשְׁתַּלֵּם כָּרָאוּי עַד שֶׁיַּעֲשֶׂה דִין בְּיִצְחָק. שֶׁיֵּצֶר הָרָע הוּא אַחַר הַדְּבָרִים וְהוּא בָּא לְקַטְרֵג."],[7,"","וּבֹא וּרְאֵה סוֹד הַדָּבָר. אַף עַל גַּב שֶׁאָמַרְנוּ שֶׁכָּתוּב אַבְרָהָם וְלֹא יִצְחָק, גַּם יִצְחָק נִכְלָל בַּפָּסוּק הַזֶּה סוֹד הַכָּתוּב וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם. לֹא כָתוּב נִסָּה לְאַבְרָהָם, אֶלָּא אֶת אַבְרָהָם, אֶת דַּוְקָא, וְזֶה יִצְחָק. שֶׁהֲרֵי בְּאוֹתָהּ שָׁעָה בַּגְּבוּרָ\"ה הַתַּחְתּוֹנָה שׁוֹרֶה. כֵּיוָן שֶׁנֶּעֱקַד וְהִזְדַּמֵּן בְּדִין עַל יְדֵי אַבְרָהָם כָּרָאוּי, אָז הִתְעַטֵּר בִּמְקוֹמוֹ יַחַד עִם אַבְרָהָם וְנִכְלְלוּ אֵ\"שׁ עִם מַיִ\"ם וְעָלוּ לְמַעְלָה, וְאָז נִמְצְאָה מַחֲלֹקֶת כָּרָאוּי, מַיִם עִם אֵשׁ."],[8,"","מִי (עשה) רָאָה אָב רַחְמָן שֶׁנַּעֲשֶׂה אַכְזָר? אֶלָּא כְּדֵי שֶׁתִּמָּצֵא מַחֲלֹקֶת מַיִם עִם אֵשׁ וּלְהִתְעַטֵּר בִּמְקוֹמָם (כראוי), עַד שֶׁבָּא יַעֲקֹב וְהַכֹּל הִתְתַּקֵּן כָּרָאוּי, וְנַעֲשׂוּ שְׁלֹשָׁה אָבוֹת שְׁלֵמִים וְנִתְקְנוּ עֶלְיוֹנִים וְתַחְתּוֹנִים."],[9,"","וַיֹּאמֶר קַח נָא אֶת בִּנְךְ. וְכִי אֵיךְ יָכוֹל אַבְרָהָם שֶׁהוּא זָקֵן? אִם תֹּאמַר מִשּׁוּם שֶׁיִּצְחָק לֹא יָצָא מֵרְשׁוּתוֹ כְּלָל - יָפֶה, אֲבָל כְּמוֹ שֶׁנֶּאֱמַר (במדבר כ) קַח אֶת אַהֲרֹן וְאֶת אֶלְעָזָר בְּנוֹ, אֶלָּא כְּדֵי לְהַמְשִׁיכָם בִּדְבָרִים וּלְהַנְהִיגָם לִרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף כָּאן קַח בִּדְבָרִים. אֶת בִּנְךְ אֶת יְחִידְךְ אֲשֶׁר אָהַבְתָּ, הֲרֵי פֵּרְשׁוּהָ. וְלֶךְ לְךְ אֶל אֶרֶץ הַמֹּרִיָּה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) אֵלֵךְ לִי אֶל הַר הַמּוֹר, לְתַקֵּן בַּמָּקוֹם שֶׁרָאוּי."]]],[["בַּיּוֹם הַשְּׁלִישִׁי וַיִּשָּׂ\"א אַבְרָהָ\"ם אֶ\"ת עֵינָיו וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק. בַּיּוֹם הַשְּׁלִישִׁי הָא אוּקְמוּהָ, אֶלָּא כֵּיוָן דְּאִתְּמָר וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלהִים מַאי טַעְמָא בַּיּוֹם הַשְּׁלִישִׁי וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק. אֶלָּא בְּגִין דִּכְתִיב כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע וְדָא הוּא יַעֲקֹב דְּנָפַק מִנֵּיהּ וְהַאי הוּא בַּיּוֹם הַשְּׁלִישִׁי. וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק כְּמָא דְאַתְּ אָמֵר (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ נִרְאָה לִי.","וַיַּרְא אֶת הַמָּקוֹם. דָּא הוּא יַעֲקֹב דִּכְתִיב, (בראשית כ״ח:י״א) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. אִסְתַּכַּל אַבְרָהָם בַּיּוֹם הַשְּׁלִישִׁי דְּאִיהוּ דַרְגָּא תְּלִיתָאָה וְחָמָא לֵיהּ לְיַעֲקֹב דְּזַמִּין לְמֵיפַק מִנֵּיהּ. מֵרָחוֹק כְּמָה דְאֲמָרָן מֵרָחוֹק וְלָא לִזְמַן קָרִיב.","אָמַר לֵיהּ רִבִּי אֶלְעָזָר מַאי שְׁבָחָא אִיהוּ לְאַבְרָהָם כַּד אִסְתַּכַּל וְחָמָא דְּזַמִּין לְמֵיפַק מִנִּיהּ יַעֲקֹב. דְּהָא כַּד אָזִיל לְמֶיעֱקַד לֵיהּ לְיִצְחָק, לָאו שְׁבָחָא כָּל כָּךְ אִיהוּ דִילֵיהּ.","אָמַר לֵיהּ וַדַּאי (והא) חָמָא לֵיהּ לְיַעֲקֹב דְּהָא מִקַּדְמַת דְּנָא יָדַע אַבְרָהָם חָכְמְתָא, וְאִסְתַּכַּל הַשְׁתָּא בַּיּוֹם הַשְּׁלִישִׁי דְּאִיהוּ דַרְגָּא תְּלִיתָאָה לְמֶעְבַּד שְׁלִימוּ וּכְדֵין חָמָא לֵיהּ לְיַעֲקֹב דִּכְתִיב וַיַּרְא אֶת הַמָּקוֹם. אֲבָל הַשְׁתָּא קַיְימָא לֵיהּ מִלָּה מֵרָחוֹק בְּגִין דְּאָזִיל לְמֶיעֱקַד לֵיהּ לְיִצְחָק וְלָא בָּעָא לְהַרְהֵר אֲבַתְרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.","מֵרָחוֹק חָמָא לֵיהּ גּוֹ אַסְפַּקְלַרְיָאה דְּלָא נָהֲרָא בִּלְחוֹדוֹי, וּבְגִין כָּךְ חָמָא לֵיהּ וְלָא אִתְגְּלִי כֹּלָּא, דְּאִלּוּ אַסְפַּקְלַרְיָאה דְנַהֲרָא הֲוָה שְׁכִיחַ עַל הַאי אַסְפַּקְלַרְיָאה דְּלָא נַהֲרָא אִתְקְיַּים עֲלֵיהּ אַבְרָהָם כְּדְקָא יָאוֹת, אֲבָל מֵרָחוֹק, בִּלְחוֹדוֹי הֲוָה, מֵרָחוֹק.","מַאי טַעְמָא אִסְתַּלַּק מֵהַאי מִלָּה אַסְפַּקְלַרְיָאה דְּנַהֲרָא בְּגִין דְּהַאי דַּרְגָּא דְּיַעֲקֹב הֲוָה. וּבְגִין דְּיַעֲקֹב עַד לָא אִתְיְילִיד לָא אִשְׁתַּכַּח הַשְׁתָּא עַל הַאי דַרְגָא. וְתוּ בְּגִין דִּיהַךְ וִיקַבֵּל אַגְרָא. וַיַּרְא אֶת הַמָּקוֹם מֵרָחוֹק דָּא יַעֲקֹב כְּמָה דְאִתְּמָר מֵרָחוֹק דְּלָא זָכָה בֵּיהּ.","(ראייה בעינוי בהאי עלמא אלא מרחוק מגו האי דרגא דהא כד אתא יעקב הכא דאף על גב דאתו לההוא ראייה וחמא ליעקב, אמר אברהם ודאי קודשא בריך הוא ידע בגוונא אחרא דאתחזי, מיד ויבן שם אברהם את המזבח וגו'.","מה כתיב לעילא ויאמר יצחק אל אברהם אביו ויאמר אבי, הא אוקמוה. אבל מאי טעמא לא אתיב ליה (מדי)) מִיָּד. אֶלָא בְּגִין דְּהָא אִסְתַּלַּק מֵרַחֲמֵי דְאַבָּא עַל בְּרָא וּבְגִין כָּךְ כְּתִיב הִנְּנִּי בְנִי, הִנְּנִּי דְאִסְתַּלָּקוּ רַחֲמֵי וְאִתְהַפַּךְ לְדִינָא:","וַיֹּאמֶר אַבְרָהָם, וְלָא כְּתִיב וַיֹּאמֶר אָבִיו, דְּהָא לָא קָאִים עֲלֵיהּ כְּאַבָּא אֶלָּא בַּעַל מַחְלוֹקֶת הֲוָה בֵּיהּ. אֱלהִים יִרְאֶה לוֹ הַשֶּׂה. יִרְאֶה לָנוּ מִבָּעֵי לֵיהּ, מַאי יִרְאֶה לוֹ. אֶלָּא אָמַר לֵיהּ אֱלֹהִים יִרְאֶה לוֹ לְגַרְמֵיהּ, כַּד אִיהוּ יִצְטְרִיךְ. אֲבָל הַשְׁתָּא בְּנִי וְלָא אִמְרָא. מִיָּד וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו.","רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר (ישעיהו ל״ג:ז׳) הֵן אֶרְאֶלָם צָעֲקוּ חוּצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הֵן אֶרְאֶלָם אִלֵּין מַלְאֲכֵי עִלָּאֵי. צָעֲקוּ בְּהַהִיא שַׁעֲתָא וּבָעוּ לְקַיְימָא עַל הַהִיא מִלָּה דִּכְתִיב, (בראשית ט״ו:ה׳) וַיּוֹצֵא אוֹתוֹ הַחוּצָה. בְּגִין כָּךְ צָעֲקוּ חוּצָה.","מַלְאֲכֵי שָׁלוֹם. אִלֵּין אִנּוּן מַלְאָכִין אָחֳרָנִין דְּהֲווּ זְמִינִין לְמֵיהַךְ קַמֵּיהּ דְּיַעֲקֹב וּבְגִינֵיהּ דְּיַעֲקֹב אַבְטַח לוֹן שְׁלִימוּ, קוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִיב, (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בּוֹ מַלְאֲכֵי אֱלהִים. וְאִלֵּין אִקְרוּן מַלְאֲכֵי שָׁלוֹם, כֻּלְּהוּ בָּכוּ כַּד חָמוּ לֵיהּ לְאַבְרָהָם דְּעָקִיד לֵיהּ לְיִצְחָק, וְאִזְדַּעְזְעוּ עִלָּאֵי וְתַתָּאֵי וְכֻלְּהוּ עֲלֵיהּ דְּיִצְחָק:"],[[0,"ביום השלישי וגו' וירא את המקום מרחוק:","ביום השלישי כבר בארוהו אלא, שיש לשאול, כיון שנאמר ויקם וילך אל המקום אשר אמר לו האלקים, מהו הטעם שנאמר, ביום השלישי וירא את המקום מרחוק, מה מלמדנו בזה. ומשיב. אלא משום שכתוב כי ביצחק יקרא לך זרע, וזהו משום שיעקב יצא ממנו. כי יצחק ה\"ס קו שמאל שאין לו קיום רק ע\"י קו אמצעי, שהוא יעקב, והוא נקרא ביום השלישי, כי אברהם יצחק יעקב ה\"ס חג\"ת, הנקראים ג' ימים, ונמצא יעקב שהוא ת\"ת, הוא יום השלישי. וע\"כ נסתכל ביעקב. שהוא קיומו של יצחק."],[1,"וירא את המקום מרחוק:","הוא כמו שאתה אומר, מרחוק ה' נראה לי, שה\"ס מסך דחירק שבקו אמצעי. (כנ\"ל דף י\"ד ד\"ה הורמנותא עש\"ה) \u0003וירא את המקום,\u0004 זה יעקב, שכתוב בו, ויקח מאבני המקום. נסתכל אברהם ביום הג', שהוא מדרגה הג', דהיינו ת\"ת, וראה שם את יעקב, שהוא עתיד לצאת ממנו, אבל \u0003מרחוק\u0004 שפירושו כמו שאמרנו, מרחוק, ולא בזמן קרוב. פירוש. וירא את המקום מרחוק, פירושו, שראה רק את המסך, אבל עוד לא ראה אז את התקון של קו אמצעי, שנקרא יעקב, דהיינו קומת החסדים היוצאת על מסך דחירק, וראה כי תקון הזה יהיה בזמן רחוק. וענין זה כבר נתבאר לעיל פרשת לך י\"ג ד\"ה ונתבאר."],[2,"אמר ליה ר' אלעזר וכו':","א\"ל ר\"א. איזה שבח הוא לאברהם, כשנסתכל וראה שיעקב עתיד לצאת ממנו, הרי בעוד שהיה הולך לעקוד את יצחק, אין זה לו שבח כל כך, שזה מביאהו בהכרח להרהר ח\"ו אחר דבריו של הקב\"ה, כי אם יעלהו לעולה, איך יצא ממנו יעקב."],[3,"א\"ל ודאי חמא וכו':","אמר לו ודאי הוא שראה את יעקב, שהרי עוד מקודם העקדה היה אברהם יודע חכמה, דהיינו שהיה לו מוחין העליונים היוצאים על ג' קוין, אשר קו אמצעי הוא יעקב. ועתה נסתכל ביום השלישי, שהוא מדרגה ג', ת\"ת, כדי להביא ממנו את השלמות. דהיינו להשלים המוחין שלו, שאין שלמות אלא מקו אמצעי, ואז אוה\"כ, שראה את יעקב, שנאמר \u0003וירא את המקום,\u0004 דהיינו שראה את קו האמצעי שנקרא יעקב, אבל עתה עמד לו הדבר \u0003מרחוק\u0004 שלא היה יכול להשיג אותו, משום שהלך לעקוד את יצחק, ולא רצה להרהר אחר הקב\"ה, שאמר לו להעלותו עולה, וע\"כ לא השיג היטב את קו אמצעי, שהוא יעקב. כנ\"ל בסמוך."],[4,"מרחוק חמא ליה וכו'","מרחוק, היינו שראה אותו באספקלריאה שאינה מאירה, בלבד, דהיינו שראה את המסך דחירק של קו אמצעי בלי קומת החסדים שיוצאת על המסך הזה. ומשום זה ראה אותו ולא נגלה לו בשלמות. כי אלו אספקלריאה המאירה, שהיא קומת אור החסדים, היתה נמצאת על האספקלריאה שאינה מאירה, שה\"ס המסך היה אברהם משיגו כראוי. אמנם לא כך היה אלא מרחוק בלבד היה דהיינו שראה רק בחינה מסך שלו המעכב על האור, ולא ראה את הזווג דהכאה שעליו, המוציא קומת אור החסדים."],[5,"מאי טעמא אסתלק וכו':","ושואל, מהו הטעם שאספקלריאה המאירה נסתלקה מדבר הזה, דהיינו מהמסך כנ\"ל. ומשיב, משום שזה הוא מדרגת יעקב, ומשום שעוד לא נולד יעקב לא נמצא עתה בחינתו שהוא קומת החסדים, על מדרגה הזו, שהוא המסך. ועוד, כדי שילך לעקוד את בנו ויקבל שכר. כי אם היתה אספקלריאה המאירה נמצאת על המסך, הרי היה משיג בבירור שיצא ממנו יעקב, ולא היה מקיים מצות הקב\"ה לעקוד את בנו. \u0003וירא את המקום מרחוק\u0004 וכו', ולפי זה, וירא את המקום מרחוק, היינו שראה את יעקב כמו שבארנו, \u0003מרחוק\u0004 פירושו, שלא זכה בו, כי לא השיגו, כמבואר."],[6,"ויבאו אל המקום וגו':","הכתוב מרמז כאן שאע\"פ שבא לאותו ראיה וראה את יעקב, כנ\"ל, אמר אברהם ודאי הוא שהקב\"ה, שאמר לו לעקוד את יצחק, יודע זה באופן אחר כראוי. מיד ויבן שם אברהם את המזבח. כלומר, שאע\"פ שראה שיצחק יוליד את יעקב, עכ\"ז לא הרהר, ובטל את דעתו מפני הקב\"ה. ובנה את המזבח וכו'."],[7,"מה כתיב לעילא וכו':","מה כתוב למעלה מזה, ויאמר יצחק אל אברהם אביו, ויאמר אבי, וכבר בארוהו. אבל מהו הטעם שלא השיב לו כלום. פירוש. כי כתוב כאן ב' פעמים ויאמר, שכתוב \u0003ויאמר\u0004 יצחק אל אברהם אביו. ואח\"כ \u0003ויאמר\u0004 אבי. ועל אמירה הראשונה לא השיב לו כלום עד שאמר פעם שנית, אבי, ואז השיב לו, \u0003הנני בני.\u0004 ושואל הזהר, למה לא השיב לו כלום על אמירה הראשונה. \u0003אלא בגין\u0004 וכו': ומשיב, אלא משום שאברהם נסתלק מרחמי אב על בנו, ובא למדת הדין, וע\"כ לא ענהו על אמירה הראשונה. ומשום זה אמר, הנני בני, הנני דאסתלקו רחמי. ונהפך לדין. פירוש. \u0003אני\u0004 רומז על מדת הדין. והנני הוא כמו \u0003הנה אני,\u0004 שפירושו שירד לדין."],[8,"ויאמר אברהם:","ואינו כתוב ויאמר אביו. והוא, משום שלא היה עמו כאב, אלא היה בעל מחלוקת שלו. \u0003אלקים יראה לו השה.\u0004 ושואל, יראה לנו, היה צריך לומר ולא \u0003יראה לו.\u0004 ומשיב, אלא אמר לו, אלקים יראה לו, לעצמו, בעת שיהיה נצרך לזה, אבל עתה בני, לעולה, ולא שה. מיד וילכו שניהם יחדיו. שיצחק הלך כרצון אביו."],[9,"ר' שמעון פתח וכו':","ר\"ש פתח ואמר. הן אראלם צעקו חוצה מלאכי שלום מר יבכיון. \u0003הן אראלם,\u0004 אלו הם מלאכים העליונים, שצעקו בשעה ההיא, שנעקד יצחק ורצו שתתקיים דבר ההוא שכתוב, ויוצא אותו \u0003החוצה\u0004 וגו', דהיינו ברכת הזרע. משום זה כתוב \u0003צעקו חוצה.\u0004"],[10,"מלאכי שלום:","אלו הם מלאכים אחרים, שהיו עתידים ללכת לפני יעקב, ובשביל יעקב, הבטיח אותם הקב\"ה את השלימות. שכתוב ויעקב הלך לדרכו ויפגעו בו מלאכי אלקים. ואלו נקראים מלאכי שלום כולם בכו כשראו את אברהם שעקד את יצחק, ונזדעזעו עליונים ותחתונים, וכולם על יצחק."]],[[0,"","בַּיּוֹם הַשְּׁלִישִׁי וַיִּשָּׂ\"א אַבְרָהָ\"ם אֶ\"ת עֵינָיו וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק. בַּיּוֹם הַשְּׁלִישִׁי, הֲרֵי פֵּרְשׁוּהָ. אֶלָּא כֵּיוָן שֶׁאָמַר וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלֹהִים, מָה הַטַּעַם בַּיּוֹם הַשְּׁלִישִׁי וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק? אֶלָּא מִשּׁוּם שֶׁכָּתוּב כִּי בְיִצְחָק יִקָּרֵא לְךְ זָרַע, וְזֶהוּ יַעֲקֹב שֶׁיָּצָא מִמֶּנּוּ, וְזֶהוּ בַּיּוֹם הַשְּׁלִישִׁי. וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) מֵרָחוֹק ה' נִרְאה לִי."],[1,"","וַיַּרְא אֶת הַמָּקוֹם - זֶהוּ יַעֲקֹב, שֶׁכָּתוּב (בראשית כח) וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם. הִסְתַּכֵּל אַבְרָהָם בַּיּוֹם הַשְּׁלִישִׁי, שֶׁהוּא הַדַּרְגָּה הַשְּׁלִישִׁית, וְרָאָה אֶת יַעֲקֹב שֶׁעָתִיד לָצֵאת מִמֶּנּוּ. מֵרָחוֹק, כְּמוֹ שֶׁאָמַרְנוּ מֵרָחוֹק וְלֹא לִזְמַן קָרוֹב."],[2,"","אָמַר לוֹ רַבִּי אֶלְעָזָר, מַה שֶּׁבַח שֶׁל אַבְרָהָם כְּשֶׁהִסְתַּכֵּל וְרָאָה שֶׁעָתִיד לָצֵאת מִמֶּנּוּ יַעֲקֹב, שֶׁהֲרֵי כְּשֶׁהָלַךְ לַעֲקֹד אֶת יִצְחָק אֵינוֹ שֶׁבַח כָּל כָּךְ שֶׁלּוֹ?"],[3,"","אָמַר לוֹ, וַדַּאי (והרי) שֶׁרָאָה אֶת יַעֲקֹב, שֶׁהֲרֵי מִקֹּדֶם לָכֵן יָדַע אַבְרָהָם אֶת הַחָכְמָה, וְהִסְתַּכֵּל עַכְשָׁו בַּיּוֹם הַשְּׁלִישִׁי שֶׁהִיא דַרְגָּה שְׁלִישִׁית לַעֲשׂוֹת שְׁלֵמוּת, וְאָז רָאָה אֶת יַעֲקֹב, שֶׁכָּתוּב וַיַּרְא אֶת הַמָּקוֹם. אֲבָל עַכְשָׁו עָמַד לוֹ הַדָּבָר מֵרָחוֹק, מִשּׁוּם שֶׁהָלַךְ לַעֲקֹד אֶת יִצְחָק וְלֹא רָצָה לְהַרְהֵר אַחֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[4,"","מֵרָחוֹק רָאָה אוֹתוֹ בְּתוֹךְ הָאַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה בִּלְבַדָּהּ, וְלָכֵן רָאָה אוֹתוֹ וְלֹא הִתְגַּלָּה הַכֹּל. שֶׁאִלּוּ הָיְתָה מְצוּיָה הָאַסְפַּקְלַרְיָה הַמְּאִירָה עַל הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, הִתְקַיֵּם עָלֶיהָ אַבְרָהָם כָּרָאוּי, אֲבָל מֵרָחוֹק בִּלְבַדּוֹ הָיָה. מֵרָחוֹק."],[5,"","מָה הַטַּעַם הִסְתַּלְּקָה מֵהַדָּבָר הַזֶּה הָאַסְפַּקְלַרְיָה הַמְּאִירָה? מִשּׁוּם שֶׁזּוֹ הָיְתָה דַרְגָּתוֹ שֶׁל יַעֲקֹב, וּמִשּׁוּם שֶׁעֲדַיִן לֹא נוֹלַד יַעֲקֹב, לֹא נִמְצָא כָּאן עַל הַדַּרְגָּה הַזּוֹ. וְעוֹד, כְּדֵי שֶׁיֵּלֵךְ וִיקַבֵּל שָׂכָר. וַיַּרְא אֶת הַמָּקוֹם מֵרָחֹק - זֶה יַעֲקֹב, כְּמוֹ שֶׁנִּתְבָּאֵר מֵרָחוֹק, שֶׁלֹּא זָכָה בּוֹ."],[6,"","(ראיה בעיניו בעולם הזה, אלא מרחוק, מתוך הדרגה הזו, שהרי כשבא יעקב, אברהם היה מת והסתלק מהעולם, וירא את המקום מרחק, אבל לא בראיה אחרת). וַיָּבֹאוּ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלֹהִים וְגוֹ'. רָמוּז (ראה) כָּאן, שֶׁאַף עַל גַּב שֶׁבָּאוּ לְאוֹתָהּ רְאִיָּה וְרָאָה אֶת יַעֲקֹב, אָמַר אַבְרָהָם, וַדַּאי הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ בְּגָוֶן אַחֵר שֶׁרָאוּי, מִיָּד וַיִּבֶן שָׁם אַבְרָהָם אֶת הַמִּזְבֵּחַ וְגוֹ'."],[7,"","מַה כָּתוּב לְמַעְלָה? וַיֹּאמֶר יִצְחָק אֶל אַבְרָהָם אָבִיו וַיֹּאמֶר אָבִי. הֲרֵי פֵּרְשׁוּהָ. אֲבָל מָה הַטַּעַם לֹא הֵשִׁיב לוֹ (דבר) מִיָּד? אֶלָּא מִשּׁוּם שֶׁהֲרֵי הִסְתַּלֵּק מֵרַחֲמִים שֶׁל אָב עַל בֵּן, וְלָכֵן כָּתוּב הִנֶּנִּי בְנִי, הִנֶּנִּי שֶׁהִסְתַּלְּקוּ הָרַחֲמִים וְהִתְהַפֵּךְ לְדִין."],[8,"","וַיֹּאמֶר אַבְרָהָם, וְלֹא כָתוּב וַיֹּאמֶר אָבִיו, שֶׁהֲרֵי לֹא עָמַד עָלָיו כְּאָב, אֶלָּא בַּעַל מַחֲלֹקֶת הָיָה עִמּוֹ. אֱלֹהִים יִרְאֶה לּוֹ הַשֶּׂה. הָיָה צָרִיךְ (לכתב) יִרְאֶה לָנוּ, מַה זֶּה יִרְאֶה לּוֹ? אֶלָּא אָמַר לוֹ אֱלֹהִים יִרְאֶה לוֹ לְעַצְמוֹ כְּשֶׁהוּא יִצְטָרֵךְ, אֲבָל עַכְשָׁו בְּנִי, וְלֹא כֶבֶשׂ. מִיָּד וַיֵּלְכוּ שְׁנֵיהֶם יַחְדָּו."],[9,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. הֵן אֶרְאֶלָּם - אֵלּוּ מַלְאָכִים עֶלְיוֹנִים, צָעֲקוּ בְּאוֹתָהּ שָׁעָה וְרָצוּ לַעֲמֹד עַל אוֹתוֹ הַדָּבָר, שֶׁכָּתוּב (בראשית טו) וַיּוֹצֵא אֹתוֹ הַחוּצָה, לָכֵן צָעֲקוּ חֻצָה."],[10,"","מַלְאֲכֵי שָׁלוֹם - אֵלּוּ אוֹתָם מַלְאָכִים אֲחֵרִים שֶׁהָיוּ עֲתִידִים לָלֶכֶת לִפְנֵי יַעֲקֹב, וּבִשְׁבִיל יַעֲקֹב הִבְטִיחַ לָהֶם שְׁלֵמוּת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שם לב) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. וְאֵלּוּ נִקְרְאוּ מַלְאֲכֵי שָׁלוֹם, כֻּלָּם בָּכוּ כְּשֶׁרָאוּ אֶת אַבְרָהָם שֶׁעוֹקֵד אֶת יִצְחָק, וְהִזְדַּעְזְעוּ עֶלְיוֹנִים וְתַחְתּוֹנִים וְכֻלָּם עַל יִצְחָק."]]],[["וַיִּקְרָא אֵלָיו מַלְאַךְ יְיָ וְגו', פָּסִיק טַעְמָא בְּגַוַּויְהוּ, דְּלָאו אַבְרָהָם בַּתְרָאָה כְּקַדְמָאָה. בַּתְרָאָה שְׁלִים (נשא קלח א) קַדְמָאָה לָא שְׁלִים. כְּגַוְונָא דָא שְׁמוּאֵל שְׁמוּאֵל, בַּתְרָאָה שְׁלִים, קַדְמָאָה לָא שְׁלִים. בַּתְרָאָה נָבִיא, קַדְמָאָה לָא נָבִיא. אֲבָל משֶׁה משֶׁה, לָא פָּסִיק, בְּגִין דְּמִיּוֹמָא דְּאִתְיְילִיד לָא אַעֲדֵי מִנֵּיהּ שְׁכִינְתָּא. אַבְרָהָם אַבְרָהָם. רַבִּי חִיָּיא אָמַר בְּגִין לְאַתְעָרָא לֵיהּ בְּרוּחָא אָחֳרָא בְּעוֹבָדָא אָחֳרָא בְּלִבָּא אָחֳרָא.","רַבִּי יְהוּדָה אָמַר אִתְבְּרִיר יִצְחָק וְאִסְתַּלִּיק בִּרְעוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּרֵיחָא דִקְטוֹרֶת בּוּסְמִין דְּקָרְבִין כָּהֲנַיָּיא קַמֵּיהּ, תְּרֵין זִמְנִין בְּיוֹמָא וְאִשְׁתְּלִים קָרְבָּנָא. דְּהָא צַעֲרָא דְאַבְרָהָם הֲוָה בְּשַׁעֲתָא דְּאִתְּמָר לֵיהּ אַל תִּשְׁלַח יָדְךָ אֶל הַנַּעַר וְאַל תַּעַשׂ לוֹ מְאוּמָה. חָשִׁיב דְּקָרְבָּנֵיהּ לָא אִשְׁתְּלִים וּלְמַגָּנָא עָבַד וְסִדֵּר כֹּלָּא וּבְנָה מִזְבֵּחַ. מִיָּד. וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנִּה אַיִל אַחַר וְגו'","הָא תָּנִינָן הוּא אַיִל דְּאִתְבְּרֵי בֵּין הַשְּׁמָשׁוֹת הֲוָה, וּבֶן שְׁנָתוֹ הָיָה כְּמָא דְאַתְּ אָמֵר, (במדבר ז׳:ט״ו) כֶּבֶשׂ אֶחָד בֶּן שְׁנָתוֹ וְהָכִי אִצְטְרִיךְ (נ\"א ואת אמרת בין השמשות. ותו והא יצחק לא הוה בעלמא, אלא אתפקיד וכו') (והא יצחק לא הוה בעלמא) וְאַתְּ אֲמַרְתְּ בֵּין הַשְּׁמָשׁוֹת. אֶלָּא אִתְפַּקַּד חֵילָא לְאִזְדַּמְּנָא הַהוּא אִימְרָא בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ לְאַבְרָהָם. כְּמָה דְּכָל אִנּוּן מִלִּין דְּהֲווּ בֵּין הַשְּׁמָשׁוֹת אִתְמַנָּא חֵילָא לְאִזְדַּמְּנָא הַהוּא מִלָּה (לההוא זמנא) בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ. הָכִי נָמֵי הַאי אַיִל דְּאִתְקְרִיב תְּחוֹתֵיהּ דְּיִצְחָק.","פָּתַח וְאָמַר, (ישעיהו ס״ג:ט׳) בְּכָל צָרָתָם לֹא צָר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם וְגו'. תָּא חֲזֵי, בְּכָל צָרָתָם דְּיִשְׂרָאֵל כַּד אִזְדַּמַּן לוֹן עָאקָן, כְּתִיב לֹא בְּאל\"ף וּקְרִי בְּוא\"ו, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּעָקוּ. לא בְּאל\"ף, אֲתַר עִלָּאָה יַתִּיר, אַף עַל גַּב דְּלָאו בְּהַהוּא אֲתַר רוּגְזָא וְעָקוּ, לְהָתָם לְעֵילָא מָטָא עַקְתָא דְיִשְׂרָאֵל. לא בְּאל\"ף כְּמָא דְאַתְּ אָמֵר, (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. כְּתִיב בְּאל\"ף וּקְרִי בְּוא\"ו.","וּמַלְאַךָ פָּנָיו הוֹשִׁיעָם. וְהָא אִיהוּ עִמְהוֹן בְּהַהוּא עָקוּ, וְאַתְּ אֲמַרְתְּ הוֹשִׁיעָם. אֶלָּא מוֹשִׁיעָם לֹא כְּתִיב, אֶלָּא הוֹשִׁיעָם מִקַּדְמַת דְּנָא דְּאִיהוּ זַמִּין בְּהַהוּא עָקוּ לְמִסְבַּל עִמְּהוֹן. תָּא חֲזֵי, בְּכָל זִמְנָא דְיִשְׂרָאֵל אִנּוּן בְּגָלוּתָא, שְׁכִינְתָּא עִמְּהוֹן בְּגָלוּתָא, וְהָא אוּקְמוּהָ, דִּכְתִיב (דברים ל׳:ג׳) וְשָׁב יְיָ אֱלהֶיךָ אֶת שְׁבוּתְךָ וְרִחַמְךָ וְגו'.","דָּבָר אַחֵר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם, דָּא שְׁכִינְתָּא. דְּאִיהִי עִמְּהוֹן בְּגָלוּתָא וְאַתְּ אֲמַרְתְּ דְּאִיהוּ הוֹשִׁיעָם. אֶלָּא הָכִי הוּא וַדַּאי, דְּאִלֵּין אִנּוּן מִשְׁכְּנוֹתָיו דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגָלוּתָא, וּבְגִין דִּשְׁכִינְתָּא עִמְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא אַדְכַּר לוֹן לְאוֹטָבָא לוֹן וְלְאֲפָקָא לוֹן מִן גָּלוּתָא, דִּכְתִיב, (שמות ו׳:ה׳) וָאֶזְכֹּר אֶת בְּרִיתִי בְּקַדְמִיתָא, וּלְבָתַר וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלַי.","וְגַם רָאִיתִי. לְאַסְגָּאָה רְאִיָה אָחֳרָא דְּאִיהוּ קַדְמָאָה דְּכֹלָּא, וּכְתִיב, (שמות ב׳:כ״ד) וַיִּזְכֹּר אֱלהִים אֶת בְּרִיתוֹ דָּא שְׁכִינְתָּא. אֶת אַבְרָהָם לְאַבְרָהָם מִבָּעֵי לֵיהּ, אֶלָּא אֶת אַבְרָהָם דָּא הוּא חַבְרוּתָא וְזִוּוּגָא דִילָהּ בַּאֲבָהָן. אֶת אַבְרָהָם (במדבר קכ א) דָּא הוּא מַעֲרָבִית דְּרוֹמִית. אֶת יִצְחָק דָּא הוּא צְפוֹנִית מַעֲרָבִית. וְאֶת יַעֲקֹב דָּא הוּא זִוּוּגָא חָדָא, כְּלָלָא חָדָא, זִוּוּגָא שְׁלִים כְּדְקָא יָאוֹת.","כְּגַוְונָא דָא אֶת הַשָּׁמַיִם דָּא הוּא כְּלָלָא מִדַּת לַיְלָה בַּיּוֹם. וְאֶת הָאָרֶץ דָּא מִדַּת יוֹם בְּלַיְלָה כְּחֲדָא. אוּף הָכָא בְּכֻלְּהוּ אֶת, וּבְיַעֲקֹב וְאֶת, לְמֶהֱוֵי כֹּלָּא זִוּוּגָא חָדָא דְּלָא מִתְפַּרְשִׁין דְּכַר וְנוּקְבָא לְעָלְמִין. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַכְרָזָא בְּכָל עַלְמָא וּלְאַשְׁמָעָא קָל דְּיֵימָא (ישעיהו ס״ג:ח׳-ט׳) וַיֹּאמֶר אַךְ עַמִּי הֵמָּה בָּנִים לֹא יְשַׁקֵּרוּ ויְהִי לָהֶם לְמוֹשִׁיעַ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן: (עד כאן פרשת וירא)"],[[0,"ויקרא אליו מלאך ה' וגו':","אברהם אברהם מפסיק טעם ביניהם, דהיינו טעם הנקרא פסיק, שזה יורה, שאברהם האחרון אינו כאברהם הראשון, כי האחרון, דהיינו אחר העקידה הוא שלם, שכבר נכלל ביצחק ואברהם הראשון אינו שלם, משום שעוד לא היה נכלל ביצחק (כנ\"ל דף קמ\"ז אות ת\"צ). כעין זה שמואל שמואל מפסיק טעם ביניהם, שיורה, שהאחרון שלם והראשון אינו שלם, כי האחרון כבר היה נביא והראשון עוד לא היה נביא. אבל משה משה אינו מפסיק טעם ביניהם, משום שמיום שבולד לא סרה ממנו השכינה, ואין הפרש מהראשון אל האחרון. \u0003אברהם אברהם,\u0004 רבי חייא אמר שע\"כ הזכיר שמו ב' פעמים, כדי לעורר אותו ברוח אחר במעשה אחר ובלב אחר. פירוש. כי עד עתה היה מתלבש בדין כדי לקיים מצות הקב\"ה. ע\"כ היה המלאך צריך להחזירו למדת החסד, וזה עשה בכפילת שם אברהם אברהם, שעוררו ברוח אחר, שלא ישלח ידו אל הנער, ובמעשה אחר שיעלה האיל לעולה תחת בנו ובלב אחר, לאהבה את יצחק בנו כבראשונה."],[1,"ר' יהודה אמר וכו':","רי\"א, יצחק נתברר ונתעלה לרצון לפני הקב\"ה, בעקדתו על המזבח, כריח של קטרת הסמים שהיו מקריבים לפניו הכהנים ב' פעמים ביום, והקרבן נשלם, כמו שהיה נקרב ונשרף לריח ניחוח לפני ה'. כי אברהם היה מצטער בשעה שנאמר לו, אל תשלח ידך אל הנער ואל תעש לו מאומה, שחשב, שקרבנו לא נשלם, ולחנם עשה וסדר הכל ובנה מזבח, מיד וישא אברהם את עיניו וירא והנה איל אחר וגו'. והקריבו תחת יצחק, ובזה נשלם."],[2,"הא תנינן וכו':","הנה למדנו, שהוא, איל שנברא בין השמשות היה, והרי ובן שנתו היה, כמו שאתה אומר כבש אחד בן שנתו. וכן הוא צריך להיות כמו עולת תמיד, ואיך תאמר שהאיל נולד בין השמשות. ומשיב, אלא שנתמנה, אז בע\"ש בין השמשות, הכח של אותו האיל, שיהיה נועד לבא בפועל אל אברהם, בשעה שיצרך לו. וע\"כ, נולד באמת בזמנו, וכשהיה בן שנה נזדמן לאברהם. כמו כל הדברים שנבראו בערב שבת בין השמשות, שפירושו, שנתמנה אז רק הכח, שיזדמן הדבר בפועל לעת הצורך. וכן הוא אותו האיל, שנקרב תחת יצחק."],[3,"פתח ואמר בכל צרתם לא צר וגו':","בוא וראה בכל צרתם של ישראל, כשנזדמנו להם הצרות, כתוב עליהם, לא באלף וקרינן \u0003לו\u0004 בו', משום שהקב\"ה עמהם בצרה. \u0003לא\u0004 עם \u0003א',\u0004 שפירושו שאינו מצטער, הוא במקום יותר עליון. ואע\"פ שאין שם במקום ההוא כעס וצרה. ששם נאמר עוז וחדוה במקומו, עכ\"ז מגיע שם למעלה צרות ישראל. \u0003לא בא'\u0004 דומה כמו שאתה אומר, הוא עשנו \u0003ולא\u0004 אנחנו, שכתוב ב \u0003א'\u0004 וקורים ב \u0003ו'.\u0004"],[4,"ומלאך פניו הושיעם:","שואל, והרי הוא נמצא עמהם בצרה, כי מתחיל לומר בכל צרתם לו צר, ואתה אומר \u0003הושיעם,\u0004 אם נמצא עמהם בצרה עוד לא הושיעם. ומשיב אלא \u0003מושיעם\u0004 לא כתוב, רק \u0003הושיעם,\u0004 לשון עבר, מקודם לכן, ופירושו, שהושיעם בזה, שנמצא עמהם באותה הצרה, וסובל עמהם. בוא וראה בכל פעם שישראל הם בגלות גם השכינה עמהם בגלות, ובארוהו, שכתוב ושב ה' אלקיך את שבותך ורחמיך, שהיה לו לומר, והשיב את שבותך, ואומר \u0003ושב,\u0004 ללמדך שהשכינה עמהם בגלות, וע\"כ אומר \u0003ושב\u0004 שסובב על עצמו כביכול."],[5,"ד\"א ומלאך פניו הושיעם:","זו היא השכינה, שהיא עמהם בגלות, כמו שאומר בתחילת הכתוב, ואתה אומר \u0003שהוא הושיעם,\u0004 ואם נמצא עמהם בגלות, הרי עוד לא הושיעם. ומשיב אלא כך הוא ודאי, שאלו הצרות של ישראל, הם משכנותיו של הקב\"ה בגלות, דהיינו שהקב\"ה נמצא בכל צרה וצרה שלהם, ומשום שהשכינה עמהם, הקב\"ה זוכר אותם להטיב להם ולהוציאם מן הגלות. שכתוב ואזכור את בריתי דהיינו השכינה, ואחר כך כתוב ועתה הנה צעקת בני ישראל בא אלי. הרי שהושיעם ממש בזה שנמצא עמהם בצרה. ואע\"פ שהכתוב ואזכור את בריתי, כתוב אח\"כ בפרשת וארא, אין קושיא, כי אין מוקדם ומאוחר בתורה. וההפרש בין פירוש זה לפירוש הראשון הוא, כי שם תירץ, שבזה שנמצא עמהם בצרה הרי הוא הושיעם, כי הוא סובל עמהם ומקל את צערם. וכאן אומר שהושיעם, עם מציאותו בצרה, שהבטיח להם בזת את גאולתם."],[6,"וגם ראיתי וכו':","שכתוב והנה צעקת וגו' וגם ראיתי. הוא לרבות ראיה אחרת שהוא ראשונה לכולם, שכתוב ויזכור אלקים את בריתו, זה היא השכינה. שזה הוא מוקדם גם להכתוב ואזכור את בריתי. \u0003את אברהם:\u0004 שואל, היה צריך לומר, ויזכור את בריתו \u0003לאברהם\u0004 ומשיב, אלא \u0003את אברהם,\u0004 זה הוא החיבור והזווג של השכינה עם האבות, כי \u0003את\u0004 היא שם השכינה (כנ\"ל בראשית א' דף י\"ח אות י\"א) \u0003את אברהם,\u0004 זה הוא \u0003מערבית דרומית,\u0004 דהיינו חיבוק הימין, כי \u0003דרום\u0004 ה\"ס ימין וחסד, הנקרא \u0003אברהם, ומערב\u0004 ה\"ס השכינה, הנקראת \u0003את,\u0004 שאברהם מחבק אותה עם חסדים. \u0003את יצחק\u0004 זה הוא \u0003צפונית מערבית.\u0004 דהיינו חיבוק השמאל כי \u0003צפון\u0004 ה\"ס שמאל וגבורה הנקרא יצחק, \u0003ומערב\u0004 ה\"ס השכינה הנק' \u0003את,\u0004 ש \u0003יצחק\u0004 מחבק אותה עם גבורות. \u0003ואת יעקב\u0004 זה הוא זווג אחד, כלל אחד, זווג שלם כראוי. כי זה יורה על זווג ז\"א הנקרא \u0003יעקב\u0004 עם השכינה הנקראת \u0003את.\u0004 ואין זווג אלא בקו אמצעי, שהוא יעקב, אבל באברהם ויצחק נוהג רק חיבוק, וז\"ש בו \u0003זווגא חדא.\u0004 והכתוב \u0003ואת יעקב\u0004 כולל אותם יחד, וז\"ש \u0003כללא חדא.\u0004 וה \u0003ו'\u0004 הנוספת, שאומר \u0003ואת\u0004 יעקב, יורה על שלמות הזווג, כמ\"ש להלן וז\"ש \u0003זווגא שלים כדקא יאות.\u0004"],[7,"כגוונא דא וכו':","כעין זה הוא בהכתוב, \u0003את השמים,\u0004 שזה הוא התכללות מדת לילה שהיא הנוקבא ביום שהוא ז\"א. \u0003ואת הארץ,\u0004 זה הוא מדת יום הנכלל במדת לילה ביחד, דהיינו התכללות ז\"א בהנוקבא. כי ה \u0003ו'\u0004 של ואת יורה על הזכר הנכלל בהנוקבא. אף כאן בכולם כתוב \u0003את,\u0004 את אברהם את יצחק, וביעקב כתוב \u0003ואת,\u0004 שזה יורה, על היותם לגמרי זווג אחד, שהזכר והנקבה אינם נפרדים לעולם. ועתיד הקב\"ה להכריז בכל העולם ולהשמיע קולו שיאמר, ויאמר אך עמי המה בנים לא ישקר, ויהי להם למושיע. ברוך ה' לעולם אמן ואמן."]],[[0,"","וַיִּקְרָא אֵלָיו מַלְאַךְ ה' וְגוֹ'. מַפְסִיק טַעַם בֵּינֵיהֶם, שֶׁאֵין אַבְרָהָם הָאַחֲרוֹן כָּרִאשׁוֹן. הָאַחֲרוֹן שָׁלֵם, הָרִאשׁוֹן לֹא שָׁלֵם. כְּמוֹ זֶה שְׁמוּאֵל שְׁמוּאֵל - הָאַחֲרוֹן שָׁלֵם, הָרִאשׁוֹן לֹא שָׁלֵם. הָאַחֲרוֹן נָבִיא, הָרִאשׁוֹן לֹא נָבִיא. אֲבָל בְּמֹשֶׁה מֹשֶׁה אֵין הֶפְסֵק טַעַם, מִשּׁוּם שֶׁמִּיּוֹם שֶׁנּוֹלַד לֹא זָזָה מִמֶּנּוּ שְׁכִינָה. אַבְרָהָם אַבְרָהָם. רַבִּי חִיָּיא אָמַר, כְּדֵי לְעוֹרְרוֹ לְרוּחַ אַחֶרֶת, בְּמַעֲשֶׂה אַחֵר, בְּלֵב אַחֵר."],[1,"","רַבִּי יְהוּדָה אָמַר, נִבְחַר יִצְחָק וְהִתְעַלָּה בְרָצוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּרֵיחַ קְטֹרֶת הַבְּשָׂמִים שֶׁמַּקְרִיבִים הַכֹּהֲנִים לְפָנָיו פַּעֲמַיִם בַּיּוֹם וְנִשְׁלָם הַקָּרְבָּן. שֶׁהֲרֵי צַעֲרוֹ שֶׁל אַבְרָהָם הָיָה בְּשָׁעָה שֶׁנֶּאֱמַר לוֹ אַל תִּשְׁלַח יָדְךְ אֶל הַנַּעַר וְאַל תַּעַשׂ לוֹ מְאוּמָה, חָשַׁב שֶׁקָּרְבָּנוֹ לֹא נִשְׁלַם וּלְחִנָּם עָשָׂה וְסִדֵּר הַכֹּל וּבָנָה מִזְבֵּחַ. מִיָּד: וַיִּשָּׂא אַבְרָהָם אֶת עֵינָיו וַיַּרְא וְהִנֵּה אַיִל אַחַר וְגוֹ'."],[2,"","הֲרֵי שָׁנִינוּ, הוּא הָאַיִל שֶׁנִּבְרָא בֵּין הַשְּׁמָשׁוֹת הָיָה, וּבֶן שְׁנָתוֹ הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ז) כֶּבֶשׂ אֶחָד בֶּן שְׁנָתוֹ, וְכָךְ צָרִיךְ. (ואתה אמרת בין השמשות, ועוד, והרי יצחק לא היה בעולם, אלא נפקד וכו') (והרי יצחק לא היה בעולם) וְאַתָּה אוֹמֵר שֶׁנִּבְרָא בֵּין הַשְּׁמָשׁוֹת? אֶלָּא נִפְקַד כֹּחַ שֶׁיְּזַמֵּן אוֹתוֹ הָאַיִל בְּשָׁעָה שֶׁהִצְטָרֵךְ אוֹתוֹ אַבְרָהָם. כְּמוֹ שֶׁכָּל אוֹתָם הַדְּבָרִים שֶׁהָיוּ בֵּין הַשְּׁמָשׁוֹת, הִתְמַנָּה כֹּחַ שֶׁיִּזְדַּמֵּן אוֹתוֹ דָבָר (לזמן ההוא) בְּשָׁעָה שֶׁצָּרִיךְ אוֹתוֹ. כָּךְ גַּם הָאַיִל הַזֶּה שֶׁהֻקְרַב תַּחַת יִצְחָק."],[3,"","פָּתַח וְאָמַר, (ישעיה סג) בְּכָל צָרָתָם לֹא צָר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם וְגוֹ'. בּא רְאֵה, בְּכָל צָרָתָם שֶׁל יִשְׂרָאֵל, כְּשֶׁמִּזְדַּמְּנוֹת לָהֶם צָרוֹת, כָּתוּב לֹא בְּאָלֶ\"ף וְקוֹרְאִים בְּוָא\"ו, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּם בַּצָּרָה. לֹא בְּאָלֶ\"ף מָקוֹם יוֹתֵר עֶלְיוֹן, אַף עַל גַּב שֶׁאֵין בְּאוֹתוֹ מָקוֹם רֹגֶז וְצָרָה, לְשָׁם לְמַעְלָה מַגִּיעָה צָרָתָם שֶׁל יִשְׂרָאֵל. לֹא בְּאָלֶ\"ף, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ק) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. כָּתוּב בְּאָלֶ\"ף וְקוֹרְאִים בְּוָא\"ו."],[4,"","וּמַלְאַךָ פָּנָיו הוֹשִׁיעָם, וַהֲרֵי הוּא עִמָּם בְּאוֹתָהּ צָרָה, וְאַתָּה אוֹמֵר הוֹשִׁיעָם? אֶלָּא לֹא כָתוּב מוֹשִׁיעָם, אֶלָּא הוֹשִׁיעָם מִקֹּדֶם לָכֵן, שֶׁהוּא עָתִיד בְּאוֹתָהּ צָרָה לִסְבֹּל עִמָּם. בּא רְאֵה, בְּכָל זְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת - שְׁכִינָה עִמָּם בַּגָּלוּת, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (דברים ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחַמְךְ וְגוֹ'."],[5,"","דָּבָר אַחֵר וּמַלְאַךְ פָּנָיו הוֹשִׁיעָם - זוֹ שְׁכִינָה, שֶׁהִיא עִמָּם בַּגָּלוּת, וְאַתָּה אוֹמֵר שֶׁהוּא הוֹשִׁיעָם? אֶלָּא כָּךְ זֶה בְּוַדַּאי, שֶׁאֵלֶּה הֵם מִשְׁכְּנוֹתָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּגָּלוּת. וּמִשּׁוּם שֶׁשְּׁכִינָה עִמָּהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא זוֹכֵר אוֹתָם לְהֵיטִיב לָהֶם וּלְהוֹצִיאָם מֵהַגָּלוּת, שֶׁכָּתוּב (שמות ו) וָאֶזְכֹּר אֶת בְּרִיתִי, בַּהַתְחָלָה. וְאַחַר כָּךְ, וְעַתָּה הִנֵּה צַעֲקַת בְּנֵי יִשְׂרָאֵל בָּאָה אֵלַי."],[6,"","וְגַם רָאִיתִי - לְרַבּוֹת רְאִיָּה אַחֶרֶת שֶׁהִיא הָרִאשׁוֹנָה שֶׁל הַכֹּל. וְכָתוּב (שם ב) וַיִּזְכֹּר אֱלֹהִים אֶל בְּרִיתוֹ, זוֹ שְׁכִינָה. אֶת אַבְרָהָם? לְאַבְרָהָם הָיָה צָרִיךְ לִכְתֹּב. אֶלָּא אֶת אַבְרָהָם זוֹ הַחֲבֵרוּת וְהַזִּוּוּג שֶׁלָּהּ עִם הָאָבוֹת. אֶת אַבְרָהָם - זֶהוּ מַעֲרָבִית דְּרוֹמִית. אֶת יִצְחָק - זֶהוּ צְפוֹנִית מַעֲרָבִית. וְאֶת יַעֲקֹב - זֶהוּ זִוּוּג אֶחָד, כְּלָל אֶחָד, זִוּוּג שָׁלֵם כָּרָאוּי."],[7,"","כְּמוֹ זֶה אֵת הַשָּׁמַיִם - זֶהוּ כְּלָל שֶׁל מִדַּת לַיְלָה בַּיּוֹם. וְאֵת הָאָרֶץ - זוֹ מִדַּת יוֹם בַּלַּיְלָה כְּאֶחָד. אַף כָּאן בְּכֻלָּם אֶת, וּבְיַעֲקֹב וְאֶת, שֶׁיִּהְיֶה הַכֹּל זִוּוּג אֶחָד שֶׁלֹּא נִפְרָדִים זָכָר וּנְקֵבָה לְעוֹלָמִים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַכְרִיז בְּכָל הָעוֹלָם וּלְהַשְׁמִיעַ קוֹל שֶׁיֹּאמַר (ישעיה סג) וַיֹּאמֶר אַךְ עַמִּי הֵמָּה בָּנִים לֹא יְשַׁקֵּרוּ וַיְהִי לָהֶם לְמוֹשִׁיעַ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."]]]]};
